T[#T+1]={id=18687,class="Lighting",parent=-1,props={["Ambient"]=Color3.new(0.498039,0.498039,0.498039),["AttributesSerialize"]="",["Brightness"]=1.0,["ColorShift_Bottom"]=Color3.new(0.0,0.0,0.0),["ColorShift_Top"]=Color3.new(0.0,0.0,0.0),["EnvironmentDiffuseScale"]=0.0,["EnvironmentSpecularScale"]=0.0,["ExposureCompensation"]=0.0,["FogColor"]=Color3.new(0.75,0.75,0.75),["FogEnd"]=100000.0,["FogStart"]=0.0,["GeographicLatitude"]=41.733299,["GlobalShadows"]=true,["Name"]="Lighting",["OutdoorAmbient"]=Color3.new(0.498039,0.498039,0.498039),["Outlines"]=true,["ShadowSoftness"]=0.5,["SourceAssetId"]=-1,["Tags"]="",["Technology"]={_enum=2},["TimeOfDay"]="14:00:00"}}
T[#T+1]={id=1368,class="LocalScript",parent=1269,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{156766F1-2897-492B-AE70-D526FF78D13C}",["Source"]="while true do\010wait()\010if script.Parent.Enabled == true then\010script.Parent.AdminScript.Disabled = false\010script.Parent.Script.Disabled = false\010script.Parent.all.Script.Disabled = false\010for i,buttons in pairs (script.Parent.all:GetChildren()) do\010for i,scripts in pairs (buttons:GetChildren()) do\010if scripts:FindFirstChild(\034Script\034) then\010scripts.Script.Disabled = false\010end\010end\010end\010end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18236,class="LocalScript",parent=18235,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="BulletVisualizerScript",["ScriptGuid"]="{A18874BF-F833-4DBC-B3AE-6094137793E6}",["Source"]="local BE = script:WaitForChild(\034Visualize\034)\010local RE = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010\010function VisualizeBullet(Player,Handle,MuzzleOffset,EndPos,MuzzleEffect,HitEffect,HitSound,ExplosiveData,BulletData,VisualizeExplosion,VisualizeEnabled)\010\009if Player ~= game.Players.LocalPlayer then\010\009\009if Handle then\010\009\009\009local MuzzlePos = (Handle.CFrame * CFrame.new(MuzzleOffset.X,MuzzleOffset.Y,MuzzleOffset.Z)).p\010\009\009\009local Distance = (MuzzlePos-EndPos).magnitude/2\010\009\009\010\009\009\009local Muzzle = Instance.new(\034Part\034)\010\009\009\009Muzzle.Name = \034Bullet\034\010\009\009\009Muzzle.Size = Vector3.new(0.01,0.01,0.01)\010\009\009\009Muzzle.Transparency = 1\010\009\009\009Muzzle.Anchored = false\010\009\009\009Muzzle.CanCollide = false\010\009\009\009Muzzle.TopSurface = Enum.SurfaceType.SmoothNoOutlines\010\009\009\009Muzzle.BottomSurface = Enum.SurfaceType.SmoothNoOutlines\010\009\009\009local Particle = MuzzleEffect:Clone()\010\009\009\009Particle.Parent = Muzzle\010\009\009\009local Weld = Instance.new(\034Weld\034,Muzzle)\010\009\009\009Weld.Part0 = Handle\010\009\009\009Weld.Part1 = Muzzle\010\009\009\009Weld.C0 = CFrame.new(MuzzleOffset.X,MuzzleOffset.Y,MuzzleOffset.Z)\010\009\009\009Muzzle.Position = MuzzlePos\010\009\009\009Muzzle.Parent = Workspace.CurrentCamera\010\009\009\009Spawn(function() Particle:Emit(5) end)\010\009\009\009game.Debris:AddItem(Muzzle,10)\009\010\009\009\010\009\009\009local HitPart = Instance.new(\034Part\034)\010\009\009\009HitPart.Name = \034Bullet\034\010\009\009\009HitPart.Size = Vector3.new(0.01,0.01,0.01)\010\009\009\009HitPart.Transparency = 1\010\009\009\009HitPart.Anchored = true\010\009\009\009HitPart.CanCollide = false\010\009\009\009HitPart.TopSurface = Enum.SurfaceType.SmoothNoOutlines\010\009\009\009HitPart.BottomSurface = Enum.SurfaceType.SmoothNoOutlines\010\009\009\009local Particle = HitEffect:Clone()\010\009\009\009Particle.Parent = HitPart\010\009\009\009local Sound = Instance.new(\034Sound\034,HitPart)\010\009\009\009Sound.SoundId = \034rbxassetid://\034..HitSound\010\009\009\009Sound.Volume = 1\010\009\009\009HitPart.Position = EndPos\010\009\009\009HitPart.Parent = Workspace.CurrentCamera\010\009\009\009Spawn(function() Particle:Emit(2) Sound:Play() end)\010\009\009\009game.Debris:AddItem(HitPart,10)\009\010\009\009\009\010\009\009\009if ExplosiveData[1] and VisualizeExplosion then\010\009\009\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009\009\009Explosion.BlastRadius = ExplosiveData[2]\010\009\009\009\009Explosion.BlastPressure = 0\010\009\009\009\009Explosion.Position = EndPos\010\009\009\009\009Explosion.Parent = Workspace.CurrentCamera\010\009\009\009end\010\009\009\009if VisualizeEnabled then\010\009\009\009\009local Bullet = Instance.new(\034Part\034)\010\009\009\009\009Bullet.Name = \034Bullet\034\010\009\009\009\009Bullet.Size = Vector3.new(0.2,0.2,0.2)\010\009\009\009\009Bullet.BrickColor = BulletData[3]\010\009\009\009\009Bullet.Transparency = BulletData[4]\010\009\009\009\009Bullet.Material = BulletData[5]\010\009\009\009\009Bullet.Anchored = true\010\009\009\009\009Bullet.CanCollide = false\010\009\009\009\009Bullet.TopSurface = Enum.SurfaceType.SmoothNoOutlines\010\009\009\009\009Bullet.BottomSurface = Enum.SurfaceType.SmoothNoOutlines\010\009\009\009\009local Mesh = Instance.new(\034SpecialMesh\034,Bullet)\010\009\009\009\009Mesh.MeshType = Enum.MeshType.Brick\010\009\009\009\009Mesh.Scale = BulletData[2] * 5\010\009\009\009\009Mesh.Offset =  Vector3.new(0,0,-Mesh.Scale.Z/10)\010\009\009\009\009Bullet.CFrame = CFrame.new(MuzzlePos,EndPos)\010\009\009\009\009Bullet.Parent = Workspace.CurrentCamera\010\009\009\009\009game.Debris:AddItem(Bullet,10)\010\009\009\009\009if BulletData[1] ~= math.huge then\010\009\009\009\009\009for i = 0,Distance,BulletData[1] do\010\009\009\009\009\009\009if i ~= 0 then Bullet.CFrame = Bullet.CFrame * CFrame.new(0,0,-BulletData[1]) end\010\009\009\009\009\009\009if (Bullet.Position - EndPos).magnitude < BulletData[2].Z then\010\009\009\009\009\009\009\009Mesh.Scale = Vector3.new(BulletData[2].X,BulletData[2].Y,(Bullet.Position - EndPos).magnitude) * 5\010\009\009\009\009\009\009\009Mesh.Offset =  Vector3.new(0,0,-Mesh.Scale.Z/10)\010\009\009\009\009\009\009end\010\009\009\009\009\009\009game:GetService(\034RunService\034).Stepped:wait()\010\009\009\009\009\009end\010\009\009\009\009else\010\009\009\009\009\009Mesh.Scale = Vector3.new(BulletData[2].X,BulletData[2].Y,(Bullet.Position - EndPos).magnitude) * 5\010\009\009\009\009\009Mesh.Offset =  Vector3.new(0,0,-Mesh.Scale.Z/10)\010\009\009\009\009\009local Time = game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009\009\009\009while Bullet.Transparency < 1 do\010\009\009\009\009\009\009Bullet.Transparency = Bullet.Transparency + (Time/BulletData[6])\010\009\009\009\009\009\009Time = game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009\009if Bullet then Bullet:Destroy() end\010\009\009\009end\010\009\009end\010\009end\010end\010\010BE.Event:connect(VisualizeBullet)\010RE.OnClientEvent:connect(VisualizeBullet)\010--BE.Event:connect(function() print(\034Bindable Firing\034) end)\010--RE.OnClientEvent:connect(function() print(\034Remote Firing\034) end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18238,class="LocalScript",parent=18235,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{7B208A7D-254B-4818-A08F-602D44F7EB32}",["Source"]="while true do\010game:GetService(\034RunService\034).Heartbeat:wait()\010if script.Parent.Parent:FindFirstChild(\034Morph/Model Gui\034) and script.Parent.Parent.PlayerGui:FindFirstChild(\034Morph/Model Gui\034) == nil then\010local gui = script.Parent.Parent:FindFirstChild(\034Morph/Model Gui\034):Clone()\010gui.Parent = script.Parent.Parent.PlayerGui\010gui.Enabled = true\010end\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18251,class="LocalScript",parent=18241,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Local",["ScriptGuid"]="{F0146D66-909D-44F2-A0BE-6BE16F84DDDD}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Camera = Workspace.CurrentCamera\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local GunScript_Server = Tool:WaitForChild(\034GunScript_Server\034)\010local ChangeAmmoAndClip = GunScript_Server:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = GunScript_Server:WaitForChild(\034InflictTarget\034)\010local AmmoValue = GunScript_Server:WaitForChild(\034Ammo\034)\010local ClipsValue = GunScript_Server:WaitForChild(\034Clips\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local IdleAnim\010local FireAnim\010local ReloadAnim\010local ShotgunClipinAnim\010local Grip2\010local Handle2\010local HandleToFire = Handle\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,2)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local Equipped = false\010local Enabled = true\010local Down = false\010local Reloading = false\010local AimDown = false\010local Ammo = AmmoValue.Value\010local Clips = ClipsValue.Value\010local MaxClip = Module.MaxClip\010local PiercedHumanoid = {}\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009IdleAnim = Tool:WaitForChild(\034IdleAnim\034)\010\009IdleAnim = Humanoid:LoadAnimation(IdleAnim)\010end\010if Module.FireAnimationID ~= nil then\010\009FireAnim = Tool:WaitForChild(\034FireAnim\034)\010\009FireAnim = Humanoid:LoadAnimation(FireAnim)\010end\010if Module.ReloadAnimationID ~= nil then\010\009ReloadAnim = Tool:WaitForChild(\034ReloadAnim\034)\010\009ReloadAnim = Humanoid:LoadAnimation(ReloadAnim)\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009ShotgunClipinAnim = Tool:WaitForChild(\034ShotgunClipinAnim\034)\010\009ShotgunClipinAnim = Humanoid:LoadAnimation(ShotgunClipinAnim)\010end\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function RayCast(Start,Direction,Range,Ignore)\010\009local Hit,EndPos = game.Workspace:FindPartOnRay(Ray.new(Start,Direction*Range),Ignore)\010\009if Hit then\010\009\009if (Hit.Transparency > 0.75\010\009\009\009or Hit.Name == \034Handle\034\010\009\009\009or Hit.Name == \034Effect\034\010\009\009\009or Hit.Name == \034Bullet\034\010\009\009\009or Hit.Name == \034Laser\034\010\009\009\009or string.lower(Hit.Name) == \034water\034\010\009\009\009or Hit.Name == \034Rail\034\010\009\009\009or Hit.Name == \034Arrow\034\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent.Humanoid.Health == 0)\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent:FindFirstChild(\034TEAM\034) and TEAM and Hit.Parent.TEAM.Value == TEAM.Value))\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and PiercedHumanoid[Hit.Parent.Humanoid]) then\010\009\009\009Hit,EndPos = RayCast(EndPos+(Direction*.01),Direction,Range-((Start-EndPos).magnitude),Ignore)\010\009\009end\010\009end\010\009return Hit,EndPos\010end\010\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then ShootingHandle.FireSound:Play() end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= 