009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009Reloading = false\010\009\009UpdateGUI()\010\009end\010end\010\010function UpdateGUI()\010\009GUI.Frame.Ammo.Fill:TweenSizeAndPosition(UDim2.new(Ammo/Module.AmmoPerClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Clips.Fill:TweenSizeAndPosition(UDim2.new(Clips/Module.MaxClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Ammo.Current.Text = Ammo\010\009GUI.Frame.Ammo.Max.Text = Module.AmmoPerClip\010\009GUI.Frame.Clips.Current.Text = Clips\010\009GUI.Frame.Clips.Max.Text = Module.MaxClip\010\010\009GUI.Frame.Ammo.Current.Visible = not Reloading\010\009GUI.Frame.Ammo.Max.Visible = not Reloading\010\009GUI.Frame.Ammo.Frame.Visible = not Reloading\010\009GUI.Frame.Ammo.Reloading.Visible = Reloading\010\010\009GUI.Frame.Clips.Current.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Max.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Frame.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.NoMoreClip.Visible = (Clips <= 0)\010\009\010\009GUI.Frame.Clips.Visible = Module.LimitedClipEnabled\010\009GUI.Frame.Size = Module.LimitedClipEnabled and UDim2.new(0,250,0,100) or UDim2.new(0,250,0,55)\010\009GUI.Frame.Position = Module.LimitedClipEnabled and UDim2.new(1,-260,1,-110)or UDim2.new(1,-260,1,-65)\010end\010\010Mouse.Button1Down:connect(function()\010\009Down = true\010end)\010Mouse.Button1Up:connect(function()\010\009Down = false\010end)\010\010ChangeAmmoAndClip.OnClientEvent:connect(function(ChangedAmmo,ChangedClips)\010\009Ammo = ChangedAmmo\010\009Clips = ChangedClips\010\009UpdateGUI()\010end)\010Tool.Equipped:connect(function(TempMouse)\010\009Equipped = true\010\009UpdateGUI()\010\009if Module.AmmoPerClip ~= math.huge then GUI.Parent = Player.PlayerGui end\010\009TempMouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009if IdleAnim then IdleAnim:Play(nil,nil,Module.IdleAnimationSpeed) end\010\009TempMouse.KeyDown:connect(function(Key)\010\009\009if string.lower(Key) == \034r\034 then\010\009\009\009Reload()\010\009\009elseif string.lower(Key) == \034e\034 then\010\009\009\009if not Reloading and AimDown == false and Module.SniperEnabled then\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = Module.FieldOfView\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034) or Tool.ZoomGui:Clone()\010\009\009\009\009GUI.Parent = game.Players.LocalPlayer.PlayerGui]]\010\009\009\009\009GUI.Scope.Visible = true\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.LockFirstPerson\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = false\010\009\009\009\009AimDown = true\010\009\009\009\009Mouse.Icon=\034http://www.roblox.com/asset?id=187746799\034\010\009\009\009else\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009\009GUI.Scope.Visible = false\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009\009AimDown = false\010\009\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009\009end\010\009\009end\010\009end)\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010Tool.Unequipped:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010Humanoid.Died:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010\010while true do\010\009local IsChargedShot = false\010\009if Equipped and Enabled and Down and not Reloading and Ammo > 0 and Humanoid.Health > 0 then\010\009\009Enabled = false\010\009\009if Module.ChargedShotEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034ChargeSound\034) then HandleToFire.ChargeSound:Play() end\010\009\009\009wait(Module.ChargingTime)\010\009\009\009IsChargedShot = true\010\009\009end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindUp\034) then HandleToFire.WindUp:Play() end\010\009\009\009wait(Module.DelayBeforeFiring)\010\009\009end\010\009\009while Equipped and not Reloading and (Down or IsChargedShot) and Ammo > 0 and Humanoid.Health > 0 do\010\009\009\009IsChargedShot = false\010\009\009\009for i = 1,(Module.BurstFireEnabled and Module.BulletPerBurst or 1) do\010\009\009\009\009Spawn(ShakeCamera)\010\009\009\009\009for x = 1,(Module.ShotgunEnabled and Module.BulletPerShot or 1) do\010\009\009\009\009\009Fire(HandleToFire)\010\009\009\009\009end\010\009\009\009\009Ammo = Ammo - 1\010\009\009\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009\009\009UpdateGUI()\010\009\009\009\009if Module.BurstFireEnabled then wait(Module.BurstRate) end\010\009\009\009\009if Ammo <= 0 then break end\010\009\009\009end\010\009\009\009HandleToFire = (HandleToFire == Handle and Module.DualEnabled) and Handle2 or Handle\010\009\009\009wait(Module.FireRate)\010\009\009\009if not Module.Auto then break end\010\009\009end\010\009\009if HandleToFire.FireSound.IsPlaying and HandleToFire.FireSound.Looped then HandleToFire.FireSound:Stop() end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindDown\034) then HandleToFire.WindDown:Play() end\010\009\009\009wait(Module.DelayAfterFiring)\010\009\009end\010\009\009Enabled = true\010\009\009if Ammo <= 0 then Reload() end\010\009end\010\009game:GetService(\034RunService\034).RenderStepped:wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18254,class="LocalScript",parent=18251,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{746ED48E-312A-4099-AFE6-0758D6208B78}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18291,class="LocalScript",parent=18286,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="AnimationScript",["ScriptGuid"]="{CE8736BE-2791-457D-BE73-95BB30233B57}",["Source"]="-- Waits for the child of the specified parent\010local function WaitForChild(parent, childName)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010local Tool = script.Parent\010\010local Animations = {}\010local MyHumanoid\010local MyCharacter\010\010\010local function PlayAnimation(animationName)\010\009if Animations[animationName] then\010\009\009Animations[animationName]:Play()\010\009end\010end\010\010local function StopAnimation(animationName)\010\009if Animations[animationName] then\010\009\009Animations[animationName]:Stop()\010\009end\010end\010\010\010function OnEquipped(mouse)\010\009MyCharacter = Tool.Parent\010\009MyHumanoid = WaitForChild(MyCharacter, 'Humanoid')\010\009if MyHumanoid then\010\009\009Animations['EquipAnim'] = MyHumanoid:LoadAnimation(WaitForChild(Tool, 'EquipAnim5'))\010\009\009Animations['IdleAnim'] = MyHumanoid:LoadAnimation(WaitForChild(Tool, 'IdleAnim3'))\010\009\009Animations['OverheadAnim'] = MyHumanoid:LoadAnimation(WaitForChild(Tool, 'OverheadAnim2'))\010\009\009Animations['SlashAnim'] = MyHumanoid:LoadAnimation(WaitForChild(Tool, 'SlashAnim2'))\010\009\009Animations['ThrustAnim'] = MyHumanoid:LoadAnimation(WaitForChild(Tool, 'ThrustAnim2'))\010\009\009Animations['UnequipAnim'] = MyHumanoid:LoadAnimation(WaitForChild(Tool, 'UnequipAnim2'))\010\009end\010\009PlayAnimation('EquipAnim')\010\009PlayAnimation('IdleAnim')\010end\010\010function OnUnequipped()\010\009for animName, _ in pairs(Animations) do\010\009\009StopAnimation(animName)\010\009end\010end\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Unequipped:connect(OnUnequipped)\010\010WaitForChild(Tool, 'PlaySlash').Changed:connect(\010\009function (value)\010\009\009--if value then\010\009\009\009PlayAnimation('SlashAnim')\010\009\009--else\010\009\009--\009StopAnimation('SlashAnim')\010\009\009--end\010\009end)\010\010WaitForChild(Tool, 'PlayThrust').Changed:connect(\010\009function (value)\010\009\009--if value then\010\009\009\009PlayAnimation('ThrustAnim')\010\009\009--else\010\009\009--\009StopAnimation('ThrustAnim')\010\009\009--end\010\009end)\010\010WaitForChild(Tool, 'PlayOverhead').Changed:connect(\010\009function (value)\010\009\009--if value then\010\009\009\009PlayAnimation('OverheadAnim')\010\009\009--else\010\009\009--\009StopAnimation('OverheadAnim')\010\009\009--end\010\009end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18292,class="LocalScript",parent=18286,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Local Gui",["ScriptGuid"]="{D804CFA0-1F15-4101-94DA-8F4E875D4586}",["Source"]="local Tool = script.Parent;\010\010enabled = true\010function onButton1Down(mouse)\010\009if not enabled then\010\009\009return\010\009end\010\010\009enabled = false\010\009mouse.Icon = \034rbxasset://textures\092\092GunWaitCursor.png\034\010\009while not Tool.Enabled do\010\009\009wait(0.05)\010\009end\010\009\010\009mouse.Icon = \034rbxasset://textures\092\092GunCursor.png\034\010\009enabled = true\010\010end\010\010function onEquippedLocal(mouse)\010\010\009if mouse == nil then\010\009\009print(\034Mouse not found\034)\010\009\009return \010\009end\010\010\009mouse.Icon = \034rbxasset://textures\092\092GunCursor.png\034\010\009mouse.Button1Down:connect(function() onButton1Down(mouse) end)\010end\010\010\010Tool.Equipped:connect(onEquippedLocal)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18304,class="LocalScript",parent=18286,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="ModifierScript",["ScriptGuid"]="{7F09E87F-481A-45A2-BAAE-BC2DED78DB92}",["Source"]="--this script modifies this weapon depending on if you have the according gamepass\010\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do print('waiting for' .. childName) wait() end\010\009return parent[childName]\010end\010\010local Tool=script.Parent\010local Player=Tool.Parent.Parent\010local Handle=WaitForChild(Tool,'Handle')\010local Mesh= WaitForChild(Handle,'Mesh')\010--local BoingSound=WaitForChild(Handle,'Boing')\010\010local CrystalSwordModifierName = 'CrystalSword'\010\010local IsCrystal=WaitForChild(Tool,'IsCrystal')\010\010local NormalTexture = 'http://www.roblox.com/asset/?id=94746105'\010local CrystalSwordTexture = 'http://www.roblox.com/asset/?id=97912267'\010local NormalIcon = 'http://www.roblox.com/asset/?id=94746192'\010local CrystalIcon = 'http://www.roblox.com/asset/?id=97913524'\010\010\010function OnModifierAdded(nmodifier)\010\009if nmodifier.Name == CrystalSwordModifierName then\010\009\009IsCrystal.Value=true\010\009\009Mesh.TextureId=CrystalSwordTexture\010\009\009Tool.TextureId= CrystalIcon\010\009\009Tool.ToolTip= 'Emerald Edge'\010\009end\010end\010\010function OnModifierRemoved(nmodifier)\010\009if nmodifier.Name == CrystalSwordModifierName then\010\009\009IsCrystal.Value=false\010\009\009Mesh.TextureId= NormalTexture\010\009\009Tool.TextureId= CrystalIcon\010\009\009Tool.ToolTip= 'Sword'\010\009end\010end\010\010function OnPlayerChildAdded(nchild)\010\009if nchild.Name=='PlayerModifiers' then\010\009\009nchild.ChildAdded:connect(OnModifierAdded)\010\009\009for _,i in pairs(nchild:GetChildren()) do\010\009\009\009OnModifierAdded(i)\010\009\009end\010\009\009nchild.ChildRemoved:connect(OnModifierRemoved)\010\009end\010end\010\010Player.ChildAdded:connect(OnPlayerChildAdded)\010if Player:FindFirstChild('PlayerModifiers') then\010\009OnPlayerChildAdded(Player['PlayerModifiers'])\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18334,class="LocalScript",parent=18331,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{738D6022-712D-4D31-ADEC-5991F886A236}",["Source"]="while true do\010script.Parent.TextLabel2.Text = game.workspace.Scripts.WaveScript.Zombies_To_Kill.Value - game.workspace.Scripts.WaveScript.Dead_Zombies.Value\010wait(0.1)\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
