T[#T+1]={id=18346,class="LocalScript",parent=18337,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{CDC338C3-2D82-41B4-982A-BD00E8107D3F}",["Source"]="sp = script.Parent\010Frame = sp:WaitForChild(\034Frame\034)\010Boss = game.ReplicatedStorage:WaitForChild(\034Boss\034)\010Health = Frame:WaitForChild(\034Health\034)\010Red = Frame:WaitForChild(\034Red\034)\010HealthCount = Frame:WaitForChild(\034HealthCount\034)\010BossName = Frame:WaitForChild(\034BossName\034)\010Humanoid = nil\010\010while true do\010\009if Boss.Value ~= nil then\010\009\009if Boss.Value:FindFirstChild(\034Torso\034) then\010\009\009\009sp.BossGui.Adornee = Boss.Value.Torso\010\009\009\009sp.BossGui.Enabled = true\010\009\009end\010\009\009Frame.Visible = true\010\009\009BossName.Text = Boss.Value.Name\010\009\009Humanoid = Boss.Value:FindFirstChild(\034Humanoid\034)\010\009\009if Humanoid then\010\009\009\009Health.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009\009\009if Red.Size.X.Scale > Health.Size.X.Scale then\010\009\009\009\009Red:TweenSize(UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0), 1, 1, (Red.Size.X.Scale-Health.Size.X.Scale)*10, true)\010\009\009\009else\010\009\009\009\009Red.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009\009\009end\010\009\009\009HealthCount.Text = math.floor(Humanoid.Health)..\034 | \034..Humanoid.MaxHealth\010\009\009\009--Health.BackgroundColor3 = Color3.new(1-(Humanoid.Health/Humanoid.MaxHealth),Humanoid.Health/Humanoid.MaxHealth,0)\010\009\009else\010\009\009\009sp.BossGui.Adornee = nil\010\009\009\009sp.BossGui.Enabled = false\010\009\009\009Frame.Visible = false\010\009\009end\010\009\009if Boss.Value.Parent == nil then\010\009\009\009--Boss.Value = nil\010\009\009\009sp.BossGui.Adornee = nil\010\009\009\009sp.BossGui.Enabled = false\010\009\009\009Frame.Visible = false\010\009\009end\010\009else\010\009\009sp.BossGui.Adornee = nil\010\009\009sp.BossGui.Enabled = false\010\009\009Frame.Visible = false\010\009end\010\009wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
