d\010\009end\010end)\010\010while true do\010\009local IsChargedShot = false\010\009if Equipped and Enabled and Down and not Reloading and Ammo > 0 and Humanoid.Health > 0 then\010\009\009Enabled = false\010\009\009if Module.ChargedShotEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034ChargeSound\034) then HandleToFire.ChargeSound:Play() end\010\009\009\009wait(Module.ChargingTime)\010\009\009\009IsChargedShot = true\010\009\009end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindUp\034) then HandleToFire.WindUp:Play() end\010\009\009\009wait(Module.DelayBeforeFiring)\010\009\009end\010\009\009while Equipped and not Reloading and (Down or IsChargedShot) and Ammo > 0 and Humanoid.Health > 0 do\010\009\009\009IsChargedShot = false\010\009\009\009for i = 1,(Module.BurstFireEnabled and Module.BulletPerBurst or 1) do\010\009\009\009\009Spawn(ShakeCamera)\010\009\009\009\009for x = 1,(Module.ShotgunEnabled and Module.BulletPerShot or 1) do\010\009\009\009\009\009Fire(HandleToFire)\010\009\009\009\009end\010\009\009\009\009Ammo = Ammo - 1\010\009\009\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009\009\009UpdateGUI()\010\009\009\009\009if Module.BurstFireEnabled then wait(Module.BurstRate) end\010\009\009\009\009if Ammo <= 0 then break end\010\009\009\009end\010\009\009\009HandleToFire = (HandleToFire == Handle and Module.DualEnabled) and Handle2 or Handle\010\009\009\009wait(Module.FireRate)\010\009\009\009if not Module.Auto then break end\010\009\009end\010\009\009if HandleToFire.FireSound.IsPlaying and HandleToFire.FireSound.Looped then HandleToFire.FireSound:Stop() end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindDown\034) then HandleToFire.WindDown:Play() end\010\009\009\009wait(Module.DelayAfterFiring)\010\009\009end\010\009\009Enabled = true\010\009\009if Ammo <= 0 then Reload() end\010\009end\010\009game:GetService(\034RunService\034).RenderSteppe