T[#T+1]={id=18973,class="LocalScript",parent=18970,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{0140710D-E091-486A-8100-6DF99030D655}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19020,class="LocalScript",parent=19005,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Local",["ScriptGuid"]="{A1725409-0C97-4572-893B-095820650CA7}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Camera = Workspace.CurrentCamera\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local GunScript_Server = Tool:WaitForChild(\034GunScript_Server\034)\010local ChangeAmmoAndClip = GunScript_Server:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = GunScript_Server:WaitForChild(\034InflictTarget\034)\010local AmmoValue = GunScript_Server:WaitForChild(\034Ammo\034)\010local ClipsValue = GunScript_Server:WaitForChild(\034Clips\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local IdleAnim\010local FireAnim\010local ReloadAnim\010local ShotgunClipinAnim\010local Grip2\010local Handle2\010local HandleToFire = Handle\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,2)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local Equipped = false\010local Enabled = true\010local Down = false\010local Reloading = false\010local AimDown = false\010local Ammo = AmmoValue.Value\010local Clips = ClipsValue.Value\010local MaxClip = Module.MaxClip\010local PiercedHumanoid = {}\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009IdleAnim = Tool:WaitForChild(\034IdleAnim\034)\010\009IdleAnim = Humanoid:LoadAnimation(IdleAnim)\010end\010if Module.FireAnimationID ~= nil then\010\009FireAnim = Tool:WaitForChild(\034FireAnim\034)\010\009FireAnim = Humanoid:LoadAnimation(FireAnim)\010end\010if Module.ReloadAnimationID ~= nil then\010\009ReloadAnim = Tool:WaitForChild(\034ReloadAnim\034)\010\009ReloadAnim = Humanoid:LoadAnimation(ReloadAnim)\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009ShotgunClipinAnim = Tool:WaitForChild(\034ShotgunClipinAnim\034)\010\009ShotgunClipinAnim = Humanoid:LoadAnimation(ShotgunClipinAnim)\010end\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function RayCast(Start,Direction,Range,Ignore)\010\009local Hit,EndPos = game.Workspace:FindPartOnRay(Ray.new(Start,Direction*Range),Ignore)\010\009if Hit then\010\009\009if (Hit.Transparency > 0.75\010\009\009\009or Hit.Name == \034Handle\034\010\009\009\009or Hit.Name == \034Effect\034\010\009\009\009or Hit.Name == \034Bullet\034\010\009\009\009or Hit.Name == \034Laser\034\010\009\009\009or string.lower(Hit.Name) == \034water\034\010\009\009\009or Hit.Name == \034Rail\034\010\009\009\009or Hit.Name == \034Arrow\034\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent.Humanoid.Health == 0)\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent:FindFirstChild(\034TEAM\034) and TEAM and Hit.Parent.TEAM.Value == TEAM.Value))\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and PiercedHumanoid[Hit.Parent.Humanoid]) then\010\009\009\009Hit,EndPos = RayCast(EndPos+(Direction*.01),Direction,Range-((Start-EndPos).magnitude),Ignore)\010\009\009end\010\009end\010\009return Hit,EndPos\010end\010\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then ShootingHandle.FireSound:Play() end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009PiercedHumanoid[TargetHumanoid] = true\010\009\009\009\009\009end\010\009\009\009\009else\010\009\009\009\009\009PierceAvailable = 0\010\009\009\009\009end\010\009\009\009end\010\009\009else\010\009\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009\009Explosion.BlastRadius = Module.Radius\010\009\009\009Explosion.BlastPressure = 0\010\009\009\009Explosion.Position = EndPos\010\009\009\009Explosion.Parent = Workspace.CurrentCamera\010\009\009\009Explosion.Hit:connect(function(Hit)\010\009\009\009\009if Hit and Hit.Parent and Hit.Name == \034Torso\034 then\010\009\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009PierceAvailable = 0\010\009\009end\010\009\009PierceAvailable = Hit and (PierceAvailable - 1) or -1\010\009\009Player.PlayerScripts.BulletVisualizerScript.Visualize:Fire(nil,ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009false,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009game.ReplicatedStorage.VisualizeBullet:FireServer(ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009true,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009Start = EndPos + (Direction*0.01)\010\009end\010\009print(\034==========\034)\010end\010\010function Reload()\010\009if Enabled and not Reloading and (Clips > 0 or not Module.LimitedClipEnabled) and Ammo < Module.AmmoPerClip then\010\009\009Reloading = true\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009\009UpdateGUI()\010\009\009if Module.ShotgunReload then\010\009\009\009for i = 1,(Module.AmmoPerClip - Ammo) do\010\009\009\009\009if ShotgunClipinAnim then ShotgunClipinAnim:Play(nil,nil,Module.ShotgunClipinAnimationSpeed) end\010\009\009\009\009Handle.ShotgunClipin:Play()\010\009\009\009\009wait(Module.ShellClipinSpeed)\010\009\009\009end\010\009\009end\010\009\009if ReloadAnim then ReloadAnim:Play(nil,nil,Module.ReloadAnimationSpeed) end\010\009\009Handle.ReloadSound:Play()\010\009\009wait(Module.ReloadTime)\010\009\009if Module.LimitedClipEnabled then Clips = Clips - 1 end\010\009\009Ammo = Module.AmmoPerClip\010\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009Reloading = false\010\009\009UpdateGUI()\010\009end\010end\010\010function UpdateGUI()\010\009GUI.Frame.Ammo.Fill:TweenSizeAndPosition(UDim2.new(Ammo/Module.AmmoPerClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Clips.Fill:TweenSizeAndPosition(UDim2.new(Clips/Module.MaxClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Ammo.Current.Text = Ammo\010\009GUI.Frame.Ammo.Max.Text = Module.AmmoPerClip\010\009GUI.Frame.Clips.Current.Text = Clips\010\009GUI.Frame.Clips.Max.Text = Module.MaxClip\010\010\009GUI.Frame.Ammo.Current.Visible = not Reloading\010\009GUI.Frame.Ammo.Max.Visible = not Reloading\010\009GUI.Frame.Ammo.Frame.Visible = not Reloading\010\009GUI.Frame.Ammo.Reloading.Visible = Reloading\010\010\009GUI.Frame.Clips.Current.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Max.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Frame.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.NoMoreClip.Visible = (Clips <= 0)\010\009\010\009GUI.Frame.Clips.Visible = Module.LimitedClipEnabled\010\009GUI.Frame.Size = Module.LimitedClipEnabled and UDim2.new(0,250,0,100) or UDim2.new(0,250,0,55)\010\009GUI.Frame.Position = Module.LimitedClipEnabled and UDim2.new(1,-260,1,-110)or UDim2.new(1,-260,1,-65)\010end\010\010Mouse.Button1Down:connect(function()\010\009Down = true\010end)\010Mouse.Button1Up:connect(function()\010\009Down = false\010end)\010\010ChangeAmmoAndClip.OnClientEvent:connect(function(ChangedAmmo,ChangedClips)\010\009Ammo = ChangedAmmo\010\009Clips = ChangedClips\010\009UpdateGUI()\010end)\010Tool.Equipped:connect(function(TempMouse)\010\009Equipped = true\010\009UpdateGUI()\010\009if Module.AmmoPerClip ~= math.huge then GUI.Parent = Player.PlayerGui end\010\009TempMouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009if IdleAnim then IdleAnim:Play(nil,nil,Module.IdleAnimationSpeed) end\010\009TempMouse.KeyDown:connect(function(Key)\010\009\009if string.lower(Key) == \034r\034 then\010\009\009\009Reload()\010\009\009elseif string.lower(Key) == \034e\034 then\010\009\009\009if not Reloading and AimDown == false and Module.SniperEnabled then\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = Module.FieldOfView\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034) or Tool.ZoomGui:Clone()\010\009\009\009\009GUI.Parent = game.Players.LocalPlayer.PlayerGui]]\010\009\009\009\009GUI.Scope.Visible = true\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.LockFirstPerson\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = false\010\009\009\009\009AimDown = true\010\009\009\009\009Mouse.Icon=\034http://www.roblox.com/asset?id=187746799\034\010\009\009\009else\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009\009GUI.Scope.Visible = false\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009\009AimDown = false\010\009\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009\009end\010\009\009end\010\009end)\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010Tool.Unequipped:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010Humanoid.Died:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010\010while true do\010\009local IsChargedShot = false\010\009if Equipped and Enabled and Down and not Reloading and Ammo > 0 and Humanoid.Health > 0 then\010\009\009Enabled = false\010\009\009if Module.ChargedShotEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034ChargeSound\034) then HandleToFire.ChargeSound:Play() end\010\009\009\009wait(Module.ChargingTime)\010\009\009\009IsChargedShot = true\010\009\009end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindUp\034) then HandleToFire.WindUp:Play() end\010\009\009\009wait(Module.DelayBeforeFiring)\010\009\009end\010\009\009while Equipped and not Reloading and (Down or IsChargedShot) and Ammo > 0 and Humanoid.Health > 0 do\010\009\009\009IsChargedShot = false\010\009\009\009for i = 1,(Module.BurstFireEnabled and Module.BulletPerBurst or 1) do\010\009\009\009\009Spawn(ShakeCamera)\010\009\009\009\009for x = 1,(Module.ShotgunEnabled and Module.BulletPerShot or 1) do\010\009\009\009\009\009Fire(HandleToFire)\010\009\009\009\009end\010\009\009\009\009Ammo = Ammo - 1\010\009\009\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009\009\009UpdateGUI()\010\009\009\009\009if Module.BurstFireEnabled then wait(Module.BurstRate) end\010\009\009\009\009if Ammo <= 0 then break end\010\009\009\009end\010\009\009\009HandleToFire = (HandleToFire == Handle and Module.DualEnabled) and Handle2 or Handle\010\009\009\009wait(Module.FireRate)\010\009\009\009if not Module.Auto then break end\010\009\009end\010\009\009if HandleToFire.FireSound.IsPlaying and HandleToFire.FireSound.Looped then HandleToFire.FireSound:Stop() end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindDown\034) then HandleToFire.WindDown:Play() end\010\009\009\009wait(Module.DelayAfterFiring)\010\009\009end\010\009\009Enabled = true\010\009\009if Ammo <= 0 then Reload() end\010\009end\010\009game:GetService(\034RunService\034).RenderStepped:wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19023,class="LocalScript",parent=19020,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{6F60F899-CDE2-4B71-97D5-1D47B45017F2}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19056,class="LocalScript",parent=19055,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ScytheScript",["ScriptGuid"]="{465588AF-0D5C-4C12-8BC1-DFE537435C03}",["Source"]="wait(1.5)\010-----------------\010--| Constants |--\010-----------------\010\010local HIT_DAMAGE = 150\010local LIMB_DEBRIS_TIME = 4 --NOTE: Should be less than respawn time\010\010local SLASH_COOLDOWN = 0.5\010\010local IGNORE_LIST = {torso = 1, handle = 1, effect = 1, water = 1} --NOTE: Keys must be lowercase, values must evaluate to true\010\010--------------------\010--| WaitForChild |--\010--------------------\010\010-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Tool = script.Parent\010local ToolHandle = Tool.Handle\010\010local MyModel = nil\010local MyPlayer = nil\010\010-------------------------\010--| Utility Functions |--\010-------------------------\010\010-- Returns a character ancestor and its Humanoid, or nil\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009local humanoid = subject:FindFirstChild('Humanoid')\010\009\009if humanoid then\010\009\009\009return subject, humanoid\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010-- Removes any old creator tags and applies new ones to the specified target\010local function ApplyTags(target)\010\009while target:FindFirstChild('creator') do\010\009\009target.creator:Destroy()\010\009end\010\010\009local creatorTag = Instance.new('ObjectValue')\010\009creatorTag.Value = MyPlayer\010\009creatorTag.Name = 'creator' --NOTE: Must be called 'creator' for website stats\010\010\009local iconTag = Instance.new('StringValue')\010\009iconTag.Value = Tool.TextureId\010\009iconTag.Name = 'icon'\010\010\009iconTag.Parent = creatorTag\010\009creatorTag.Parent = target\010\009DebrisService:AddItem(creatorTag, 4)\010end\010\010-----------------------\010--| Other Functions |--\010-----------------------\010\010local function OnTouched(otherPart)\010\009if otherPart and not IGNORE_LIST[string.lower(otherPart.Name)] then\010\009\009local character, humanoid = FindCharacterAncestor(otherPart)\010\009\009local TEAM = character:FindFirstChild(\034TEAM\034)\010\009\009if character and humanoid and character ~= MyModel and TEAM and TEAM.Value ~= MyModel.TEAM.Value then\010\009\009\009if connection then connection:disconnect() end\010\009\009\009ApplyTags(humanoid)\010\009\009\009ToolHandle[\034HitSound\034..math.random(1,3)]:Play()\010\009\009\009Tool.DamageEvent:FireServer(humanoid,HIT_DAMAGE)\010\009\009end\010\009end\010end\010\010local function OnEquipped()\010\009MyModel = Tool.Parent\010\009MyPlayer = PlayersService:GetPlayerFromCharacter(MyModel)\010\009if MyModel:FindFirstChild('Humanoid') then\010\009\009MyModel:FindFirstChild('Humanoid').WalkSpeed = MyModel:FindFirstChild('Humanoid').WalkSpeed * 2\010\009end\010end\010\010local function OnUnequipped()\010\009if MyModel:FindFirstChild('Humanoid') then\010\009\009MyModel:FindFirstChild('Humanoid').WalkSpeed = MyModel:FindFirstChild('Humanoid').WalkSpeed / 2\010\009end\010end\010\010local function OnActivated()\010\009if Tool.Enabled and MyModel:FindFirstChild('Humanoid') and MyModel.Humanoid.Health > 0 then\010\009\009Tool.Enabled = false --NOTE: Starts the animation\010\010\009\009connection = ToolHandle.Touched:connect(OnTouched)\010\009\009Delay(0.4, function() --NOTE: Hardcoded length of animation :[\010\009\009\009if connection then\010\009\009\009\009connection:disconnect()\010\009\009\009end\010\009\009end)\010\010\009\009local slashSound = ToolHandle:FindFirstChild('SwordSlash')\010\009\009if slashSound then\010\009\009\009slashSound:Play()\010\009\009end\010\010\009\009wait(SLASH_COOLDOWN)\010\010\009\009Tool.Enabled = true\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Unequipped:connect(OnUnequipped)\010Tool.Activated:connect(OnActivated)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19057,class="LocalScript",parent=19055,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MostAnimations",["ScriptGuid"]="{C5228B1F-4925-40DA-B598-CC19CB4905FC}",["Source"]="--------------------\010--| WaitForChild |--\010--------------------\010\010-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local Tool = script.Parent\010\010--local ScytheEquipAnimation = WaitForChild(script, 'ScytheEquip2')\010local ScytheIdleAnimation = WaitForChild(script, 'Idle')\010local ScytheSlashAnimation = WaitForChild(script, 'AttackAnim')\010\010local ScytheEquipTrack = nil\010local ScytheIdleTrack = nil\010local ScytheSlashTrack = nil\010\010-----------------\010--| Functions |--\010-----------------\010\010local function OnEquipped()\010\009local myModel = Tool.Parent\010\009local humanoid = myModel:FindFirstChild('Humanoid')\010\009if humanoid then -- Preload animations\010\009\009--[[ScytheEquipTrack = humanoid:LoadAnimation(ScytheEquipAnimation)\010\009\009if ScytheEquipTrack then ScytheEquipTrack:Play() end]]\010\010\009\009ScytheIdleTrack = humanoid:LoadAnimation(ScytheIdleAnimation)\010\009\009if ScytheIdleTrack then ScytheIdleTrack:Play() end\010\010\009\009ScytheSlashTrack = humanoid:LoadAnimation(ScytheSlashAnimation)\010\009end\010end\010\010local function OnChanged(property)\010\009if property == 'Enabled' and Tool.Enabled == false then\010\009\009if ScytheSlashTrack then ScytheSlashTrack:Play(nil,nil,2) end\010\009end\010end\010\010local function OnUnequipped()\010\009-- Stop all animations\010\009if ScytheEquipTrack then ScytheEquipTrack:Stop() end\010\009if ScytheIdleTrack then ScytheIdleTrack:Stop() end\010\009if ScytheSlashTrack then ScytheSlashTrack:Stop() end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Changed:connect(OnChanged)\010Tool.Unequipped:connect(OnUnequipped)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19062,class="LocalScript",parent=19055,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChargeScript",["ScriptGuid"]="{0B041E06-DEE0-4A14-ABB8-8AFCD94E8CCC}",["Source"]="local Tool = script.Parent\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local Torso = Character:WaitForChild(\034Torso\034)\010local DamageEvent = Tool:WaitForChild(\034DamageEvent\034)\010\010local ChargeDamage = 500\010local ChargeKnockback = 50\010local ChargeSpeed = 125\010local ChargeDuration = 1.5\010local ChargeSelfDamage = 25\010local ChargeSelfDamageTwo = -250\010\010local ChargeReady = true\010local ChargeCooldown = 7.5\010local Equipped = false\010local Charging = false\010local ChargeDirection = Vector3.new(0,0,0)\010local BodyVelocity\010local Fires = {}\010\010Torso.Touched:connect(function(Hit)\010\009if Hit.Parent == nil or not Charging or Humanoid.Health == 0 and Hit.Parent ~= Character then return end\010\009local HitHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009local HitTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009local HitTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009if (HitHumanoid and HitHumanoid.Health ~= 0 and HitTEAM and HitTEAM.Value ~= TEAM.Value) then\010\009\009Charging = false\010\009\009Humanoid.AutoRotate = true\010\009\009Tool.Handle.Charge1:Stop()\010\009\009Tool.Handle.Charge2:Stop()\010\009\009Tool.Handle.Charge3:Stop()\010\009\009Tool.Handle[\034ChargeHit\034..math.random(1,3)]:Play()\010\009\009HitHumanoid.Sit = false\010\009\009HitTorso.Velocity = ChargeDirection * ChargeKnockback\010\009\009DamageEvent:FireServer(HitHumanoid,ChargeDamage)\010\009\009if BodyVelocity then BodyVelocity:Destroy() end\010\009\009Torso.Velocity = Vector3.new(0,0,0)\010\009\009for _, Fire in pairs(Fires) do\010\009\009\009Fire.Enabled = false\010\009\009end\010\009\009Delay(5,function()\010\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009Fire:Destroy()\010\009\009\009end\010\009\009end)\010\009elseif (Hit.Anchored == true and Hit.CanCollide == true) then\010\009\009Charging = false\010\009\009Humanoid.AutoRotate = true\010\009\009Tool.Handle.Charge1:Stop()\010\009\009Tool.Handle.Charge2:Stop()\010\009\009Tool.Handle.Charge3:Stop()\010\009\009Tool.Handle[\034ChargeHit\034..math.random(1,3)]:Play()\010\009\009DamageEvent:FireServer(Humanoid,ChargeSelfDamage)\010\009\009if BodyVelocity then BodyVelocity:Destroy() end\010\009\009Torso.Velocity = Vector3.new(0,0,0)\010\009\009for _, Fire in pairs(Fires) do\010\009\009\009Fire.Enabled = false\010\009\009end\010\009\009Delay(5,function()\010\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009Fire:Destroy()\010\009\009\009end\010\009\009end)\010\009end\010end)\010\010Tool.Equipped:connect(function()\010\009Equipped = true\010end)\010\010Tool.Unequipped:connect(function()\010\009Equipped = false\010end)\010\010Mouse.KeyDown:connect(function(Key)\010\009if not Equipped then return end\010\009if string.lower(Key) == \034e\034 then\010\009\009if ChargeReady then\010\009\009\009ChargeReady = false\010\009\009\009Delay(ChargeCooldown,function() ChargeReady = true end)\010\009\009\009if Humanoid:GetState() ~= Enum.HumanoidStateType.Dead then Humanoid:ChangeState(Enum.HumanoidStateType.Running) end\010\009\009\009Torso.CFrame = CFrame.new(Torso.Position, Vector3.new(Mouse.Hit.p.X,Torso.Position.Y,Mouse.Hit.p.Z))\010\009\009\009ChargeDirection = Torso.CFrame.lookVector\010\009\009\009Tool.Handle[\034Charge\034..math.random(1,3)]:Play()\010\009\009\009for _, Parts in pairs(Character:GetChildren()) do\010\009\009\009\009if Parts.ClassName == \034Part\034 or Parts.ClassName == \034WedgePart\034 or Parts.ClassName == \034CornerWedgePart\034 then\010\009\009\009\009\009local Fire = script.ChargeFire:Clone()\010\009\009\009\009\009table.insert(Fires,Fire)\010\009\009\009\009\009Fire.Size = 5 + (Parts.Size.magnitude*1.5)\010\009\009\009\009\009Fire.Enabled = true\010\009\009\009\009\009DamageEvent:FireServer(Humanoid,ChargeSelfDamageTwo)\010\009\009\009\009\009Fire.Parent = Parts\010\009\009\009\009end\010\009\009\009end\010\009\009\009Torso.Velocity = ChargeDirection * ChargeSpeed\010\009\009\009BodyVelocity = script.BodyVelocity:Clone()\010\009\009\009BodyVelocity.Velocity = ChargeDirection * ChargeSpeed\010\009\009\009BodyVelocity.Parent = Torso\010\009\009\009Charging = true\010\009\009\009Humanoid.AutoRotate = false\010\009\009\009wait(ChargeDuration)\010\009\009\009Charging = false\010\009\009\009Humanoid.AutoRotate = true\010\009\009\009if Humanoid:GetState() ~= Enum.HumanoidStateType.Dead then Humanoid:ChangeState(Enum.HumanoidStateType.Running) end\010\009\009\009Torso.Velocity = Vector3.new(0,0,0)\010\009\009\009if BodyVelocity then BodyVelocity:Destroy() end\010\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009Fire.Enabled = false\010\009\009\009end\010\009\009\009Delay(5,function()\010\009\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009\009Fire:Destroy()\010\009\009\009\009end\010\009\009\009end)\010\009\009end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19850,class="LocalScript",parent=19848,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{4E34831F-6211-40C2-9A33-49E7245FA069}",["Source"]="-- Made by Stickmasterluke\010 -- edited by fusroblox\010\010function WaitForChild(obj, name)\010\009while not obj:FindFirstChild(name) do\010\009\009wait()\010\009\009print(\0341waiting for \034 .. name)\010\009end\010\009return obj:FindFirstChild(name)\010end\010\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009if subject:FindFirstChild('Humanoid') then\010\009\009\009return subject\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010local Tool = script.Parent\010\010local GunObj ={\010\009Reloading = \034http://www.roblox.com/asset/?id=94155503\034,\010\009\010\009Cursors = {\010\009\009\034http://www.roblox.com/asset/?id=94154683\034, -- black\010\009\009\034http://www.roblox.com/asset/?id= 94154829\034, -- red\010\009\009\034http://www.roblox.com/asset/?id=94155503\034, \010\009\009\034http://www.roblox.com/asset/?id=94155569\034\010\009},\010\009\010\009ClipSize = 50,\010\009Equipped = false,\010\009\010\009Player = game.Players.localPlayer,\010\009Ammo = WaitForChild(script.Parent,\034Ammo\034),\010\009Clips,\010\009Gui = WaitForChild(Tool,\034AmmoHud\034),\010\009NumberImages={},\010\009IdleAni,\010\009MyMouse\010\009\010}\010\010local ChestWeld\010Tool.Equipped:connect(function(mouse) GunObj:OnEquipped(mouse) end)\010local initialized=false\010\010function GunObj:Initialize()\010\009if initialized then return end\010\009initialized=true\010\009self.Ammo.Changed:connect(function()self:UpdateGui()end)\010\010\009WaitForChild(Tool, \034Reloading\034)\010\009print('got to connections!!!!! ')\010\009Tool.Reloading.Changed:connect(function() self:UpdateGui() end)\010\009Tool.Unequipped:connect(function() self:OnUnequipped() end)\010\009\010\009Tool.DoFireAni.Changed:connect(PlayFireAni)\010\009self.NumberImages['0']=94128401\010\009self.NumberImages['1']=94128421\010\009self.NumberImages['2']=94128434\010\009self.NumberImages['3']=94128446\010\009self.NumberImages['4']=94128466\010\009self.NumberImages['5']=94128485\010\009self.NumberImages['6']=94128496\010\009self.NumberImages['7']=94128523\010\009self.NumberImages['8']=94128538\010\009self.NumberImages['9']=94128538\010\010\009local bar=WaitForChild(self.Gui,'Bar')\010\009self:UpdateNumbers(self.ClipSize..'', WaitForChild(bar,'TotalAmmo'))\010end\010\010function GunObj:UpdateNumbers(data,frame)\010\009if string.len(data)==0 then\010\009\009data= '0'..data\010\009end\010\009if string.len(data)==1 then\010\009\009data= '0'..data\010\009end\010\010\009local digit=WaitForChild(WaitForChild(frame,'1'),'digit')\010\009if digit.Image ~='http://www.roblox.com/asset/?id='..self.NumberImages[string.sub(data,1,1)] then\010\009\009local ndigit=digit:Clone()\010\009\009ndigit.Position=UDim2.new(ndigit.Position.X.Scale,ndigit.Position.X.Offset,ndigit.Position.Y.Scale,ndigit.Position.Y.Offset-65)\010\009\009ndigit.Image='http://www.roblox.com/asset/?id='..self.NumberImages[string.sub(data,1,1)]\010\009\009ndigit.Parent=digit.Parent\010\009\009ndigit:TweenPosition(digit.Position, \034Out\034, \034Quad\034, .1,true)\010\009\009digit.Name='oldDigit'\010\009\009digit:TweenPosition(UDim2.new(digit.Position.X.Scale,digit.Position.X.Offset,digit.Position.Y.Scale,\010\009\009\009digit.Parent.Position.Y.Offset+95), \034Out\034, \034Quad\034, .25,true)\010\009\009game.Debris:AddItem(digit,1)\010\009end\010\009digit=WaitForChild(WaitForChild(frame,'2'),'digit')\010\009if digit.Image ~='http://www.roblox.com/asset/?id='..self.NumberImages[string.sub(data,2,2)] then\010\009\009ndigit=digit:Clone()\010\009\009ndigit.Position=UDim2.new(ndigit.Position.X.Scale,ndigit.Position.X.Offset,ndigit.Position.Y.Scale,ndigit.Position.Y.Offset-65)\010\009\009ndigit.Image='http://www.roblox.com/asset/?id='..self.NumberImages[string.sub(data,2,2)]\010\009\009ndigit.Parent=digit.Parent\010\009\009ndigit:TweenPosition(UDim2.new(digit.Position.X.Scale,digit.Position.X.Offset,digit.Position.Y.Scale,0), \034Out\034, \034Quad\034, .25,true)\010\009\009digit.Name='oldDigit'\010\009\009digit:TweenPosition(UDim2.new(digit.Position.X.Scale,digit.Position.X.Offset,digit.Position.Y.Scale,\010\009\009\009digit.Parent.Position.Y.Offset+95), \034Out\034, \034Quad\034, .25,true)\010\009\009game.Debris:AddItem(digit,1)\010\009end\010end\010\010function GunObj:UpdateGui()\010\009if self.Equipped then\010\009\009local Player = game.Players.localPlayer\010\009\009if Player ~= nil then\010\009\009\009if self.Ammo == nil then\010\009\009\009\009--self.Gui.Bar.GunLabel.Text =\034Futuro Heavy Pistol\034\010\009\009\009\009--self.Gui.Bar.AmmoLabel.Text = \034\034\010\009\009\009else\010\009\009\009\009--self.Gui.Bar.GunLabel.Text =\034Futuro Heavy Pistol\034\010\009\009\009\009--self.Gui.Bar.AmmoLabel.Text = tostring(self.Ammo.Value)..\034/\034..tostring(self.ClipSize)\010\009\009\009\009self:UpdateNumbers(tostring(self.Ammo.Value),WaitForChild(self.Gui.Bar,'AmmoLeft'))\010\009\009\009end\010\009\009\009if Tool.Reloading.Value then\010\009\009\009\009--self.Gui.Bar.AmmoLabel.Text = \034Reloading\034\010\009\009\009end\010\009\009end\010\009end\010end\010\010function GunObj:CursorUpdate(mouse)\010\009local reloadCounter=0\010\009while self.Equipped do\010\009\009if Tool.Reloading.Value then\010\009\009\009reloadCounter=reloadCounter+1\010\009\009\009if reloadCounter%20<10 then\010\009\009\009\009mouse.Icon = self.Cursors[3]\010\009\009\009else\010\009\009\009\009mouse.Icon = self.Cursors[4]\010\009\009\009end\010\009\009elseif mouse.Target and FindCharacterAncestor(mouse.Target) then\010\009\009\009mouse.Icon = self.Cursors[2]\010\009\009else \010\009\009\009mouse.Icon = self.Cursors[1]\010\009\009end\010\009\009wait(1/30)\010\009end\010end\010\010local InReload=false\010\010function GunObj:OnEquipped(mouse)\010\009self:Initialize()\010\009if mouse ~= nil then\010\009\009self.Equipped = true\010\009\009local Player = game.Players.LocalPlayer\010\009\009if Player ~= nil then\010\009\009\009local humanoid=WaitForChild(Player.Character,'Humanoid')\010\009\009\009if not self.IdleAni then\010\009\009\009\009self.IdleAni = humanoid:LoadAnimation(WaitForChild(script.Parent,'idle'))\010\009\009\009\009self.IdleAni:Play()\010\009\009\009end\010\009\009\009local plrgui = WaitForChild(Player,\034PlayerGui\034)\010\009\009\009self.Gui.Parent = plrgui\010\009\009\009mouse.Button1Down:connect(function()\010\009\009\009\009if not Tool.Down.Value then\010\009\009\009\009\009Tool.Aim.Value = mouse.Hit.p\010\009\009\009\009\009Tool.Down.Value = true\010\009\009\009\009\009while Tool.Down.Value do\010\009\009\009\009\009\009Tool.Aim.Value = mouse.Hit.p\010\009\009\009\009\009\009wait()\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009mouse.Button1Up:connect(function()\010\009\009\009\009Tool.Down.Value = false\010\009\009\009end)\010\009\009\009mouse.KeyDown:connect(function(key) \010\009\009\009\009if key=='r' and not Tool.Reloading.Value and not Tool.Down.Value and self.Ammo.Value ~=8 and self.Ammo.Value ~=0 and not InReload then\010\009\009\009\009\009Tool.Reloading.Value=true\010\009\009\009\009end\010\009\009\009end)\010\009\009\009--mouse.Icon = self.Cursors[1]\010\009\009\009Tool.Reloading.Changed:connect(function(val)\010\009\009\009\009if mouse ~= nil and self.Equipped then\010\009\009\009\009\009if val then\010\009\009\009\009\009\009--mouse.Icon = self.Cursors.Reloading\010\009\009\009\009\009else\010\009\009\009\009\009\009--mouse.Icon = self.Cursors[1]\010\009\009\009\009\009end\010\009\009\009\009\009local Player = game.Players.LocalPlayer\010\009\009\009\009\009if Player ~= nil then\010\009\009\009\009\009\009local gui = WaitForChild(Player.PlayerGui, \034AmmoHud\034)\010\009\009\009\009\009\009local humanoid=WaitForChild(Player.Character,'Humanoid')\010\009\009\009\009\009\009self:UpdateGui()\010\009\009\009\009\009\009if Tool.Reloading.Value then\010\009\009\009\009\009\009\009--gui.Bar.AmmoLabel.Text = \034Reloading\034\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009self:UpdateGui()\010\009\009\009MyMouse=mouse\010\009\009\009Spawn(function() self:CursorUpdate(mouse) end )\010\009\009end\010\009end\010end\010\010function GunObj:OnUnequipped()\010\009if self.IdleAni then\010\009\009self.IdleAni:Stop()\010\009\009self.IdleAni:Destroy()\010\009\009self.IdleAni=nil\010\009end\010\009self.Gui.Parent = Tool\010\009self.Equipped = false\010\009print('in unequipp')\010\009if ChestWeld then\010\009\009print('chestweldexists')\010\009\009ChestWeld:Destroy()\010\009end\010\009local Player = game.Players.localPlayer\010\009if Player ~= nil then\010\009\009local gui = WaitForChild(Player.PlayerGui,\034AmmoHud\034)\010\009\009--gui.Bar.GunLabel.Text = \034\034\010\009\009--gui.Bar.AmmoLabel.Text = \034\034\010\009end\010end\010\010function PlayFireAni()\010\009wait(.1)\010\009local aniTrack = WaitForChild(Tool.Parent,\034Humanoid\034):LoadAnimation(Tool.FireAni)\010\009aniTrack:Play(0,1,1.2)\010end\010\010local function weldBetween(a, b)\010    local weld = Instance.new(\034Weld\034)\010    weld.Part0 = a\010    weld.Part1 = b\010    weld.C0 = CFrame.new()\010    weld.C1 = b.CFrame:inverse() * a.CFrame\010    weld.Parent = a\010    return weld;\010end\010\010\010function PlayReloadAni()\010\009InReload=true\010\009local aniTrack = WaitForChild(Tool.Parent,\034Humanoid\034):LoadAnimation(Tool.Reload)\010\009local torso=WaitForChild(Tool.Parent,'Torso')\010\009local oldWeld\010\009for _,i in pairs(WaitForChild(Tool.Parent,'Right Arm'):GetChildren()) do\010\009\009if i:IsA('Weld') and i.Part1==Tool.Handle then\010\009\009\009oldWeld=i\010\009\009end\010\009end\010\009if not oldWeld then \010\009\009print('What... no old weld!')\010\009\009return\010\009end\010\009ChestWeld= weldBetween(torso,Tool.Handle)\010\009oldWeld.Part1=nil\010\009aniTrack:Play(0,1,1)\010\009wait(4)\010\009oldWeld.Part1=Tool.Handle\010\009ChestWeld:Destroy()\010\009ChestWeld=nil\010\009InReload=false\010end\010\010Tool.Reloading.Changed:connect(function() if Tool.Reloading.Value then PlayReloadAni() end end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19889,class="LocalScript",parent=19884,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Local Gui",["ScriptGuid"]="{46A1E76A-5134-4410-BE5D-F724B70E7B08}",["Source"]="local Tool = script.Parent;\010\010enabled = true\010function onButton1Down(mouse)\010\009if not enabled then\010\009\009return\010\009end\010\010\009enabled = false\010\009mouse.Icon = \034rbxasset://textures\092\092GunWaitCursor.png\034\010\010\009wait(1)\010\009mouse.Icon = \034rbxasset://textures\092\092GunCursor.png\034\010\009enabled = true\010\010end\010\010function onEquippedLocal(mouse)\010\010\009if mouse == nil then\010\009\009print(\034Mouse not found\034)\010\009\009return \010\009end\010\010\009mouse.Icon = \034rbxasset://textures\092\092GunCursor.png\034\010\009mouse.Button1Down:connect(function() onButton1Down(mouse) end)\010end\010\010\010Tool.Equipped:connect(onEquippedLocal)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19901,class="LocalScript",parent=19890,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MouseIcon",["ScriptGuid"]="{FE820E29-EE01-4DA8-8BA5-CA6BB41958F6}",["Source"]="--Made by Luckymaxer\010\010Mouse_Icon = \034rbxasset://textures/GunCursor.png\034\010Reloading_Icon = \034rbxasset://textures/GunWaitCursor.png\034\010\010Tool = script.Parent\010\010Mouse = nil\010\010function UpdateIcon()\010\009if Mouse then\010\009\009Mouse.Icon = Tool.Enabled and Mouse_Icon or Reloading_Icon\010\009end\010end\010\010function OnEquipped(ToolMouse)\010\009Mouse = ToolMouse\010\009UpdateIcon()\010end\010\010function OnChanged(Property)\010\009if Property == \034Enabled\034 then\010\009\009UpdateIcon()\010\009end\010end\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Changed:connect(OnChanged)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19902,class="LocalScript",parent=19890,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{D33DC0DA-C815-49FC-B96E-02AD966C8D1E}",["Source"]="--Made by Luckymaxer\010\010Tool = script.Parent\010Handle = Tool:WaitForChild(\034Handle\034)\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010RunService = game:GetService(\034RunService\034)\010ContentProvider = game:GetService(\034ContentProvider\034)\010UserInputService = game:GetService(\034UserInputService\034)\010\010InputCheck = Instance.new(\034ScreenGui\034)\010InputCheck.Name = \034InputCheck\034\010InputFrame = Instance.new(\034Frame\034)\010InputFrame.BackgroundTransparency = 1\010InputFrame.Size = UDim2.new(1, 0, 1, 0)\010InputFrame.Parent = InputCheck\010\010RbxUtility = LoadLibrary(\034RbxUtility\034)\010Create = RbxUtility.Create\010\010Animations = {}\010LocalObjects = {}\010\010ServerControl = Tool:WaitForChild(\034ServerControl\034)\010ClientControl = Tool:WaitForChild(\034ClientControl\034)\010\010Rate = (1 / 60)\010\010ToolEquipped = false\010\010function SetAnimation(mode, value)\010\009if not ToolEquipped or not CheckIfAlive() then\010\009\009return\010\009end\010\009local function StopAnimation(Animation)\010\009\009for i, v in pairs(Animations) do\010\009\009\009if v.Animation == Animation then\010\009\009\009\009v.AnimationTrack:Stop(value.EndFadeTime)\010\009\009\009\009if v.TrackStopped then\010\009\009\009\009\009v.TrackStopped:disconnect()\010\009\009\009\009end\010\009\009\009\009table.remove(Animations, i)\010\009\009\009end\010\009\009end\010\009end\010\009if mode == \034PlayAnimation\034 then\010\009\009for i, v in pairs(Animations) do\010\009\009\009if v.Animation == value.Animation then\010\009\009\009\009if value.Speed then\010\009\009\009\009\009v.AnimationTrack:AdjustSpeed(value.Speed)\010\009\009\009\009\009return\010\009\009\009\009elseif value.Weight or value.FadeTime then\010\009\009\009\009\009v.AnimationTrack:AdjustWeight(value.Weight, value.FadeTime)\010\009\009\009\009\009return\010\009\009\009\009else\010\009\009\009\009\009StopAnimation(value.Animation, false)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009\009local AnimationMonitor = Create(\034Model\034){}\010\009\009local TrackEnded = Create(\034StringValue\034){Name = \034Ended\034}\010\009\009local AnimationTrack = Humanoid:LoadAnimation(value.Animation)\010\009\009local TrackStopped\010\009\009if not value.Manual then\010\009\009\009TrackStopped = AnimationTrack.Stopped:connect(function()\010\009\009\009\009if TrackStopped then\010\009\009\009\009\009TrackStopped:disconnect()\010\009\009\009\009end\010\009\009\009\009StopAnimation(value.Animation, true)\010\009\009\009\009TrackEnded.Parent = AnimationMonitor\010\009\009\009end)\010\009\009end\010\009\009table.insert(Animations, {Animation = value.Animation, AnimationTrack = AnimationTrack, TrackStopped = TrackStopped})\010\009\009AnimationTrack:Play(value.FadeTime, value.Weight, value.Speed)\010\009\009if TrackStopped then\010\009\009\009AnimationMonitor:WaitForChild(TrackEnded.Name)\010\009\009end\010\009\009return TrackEnded.Name\010\009elseif mode == \034StopAnimation\034 and value then\010\009\009StopAnimation(value.Animation)\010\009end\010end\010\010function CheckIfAlive()\010\009return (((Character and Character.Parent and Humanoid and Humanoid.Parent and Humanoid.Health > 0 and Player and Player.Parent) and true) or false)\010end\010\010function Equipped(Mouse)\010\009Character = Tool.Parent\010\009Player = Players:GetPlayerFromCharacter(Character)\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009ToolEquipped = true\010\009if not CheckIfAlive() then\010\009\009return\010\009end\010\009Spawn(function()\010\009\009PlayerMouse = Player:GetMouse()\010\009\009Mouse.Button1Down:connect(function()\010\009\009\009InvokeServer(\034Button1Click\034, {Down = true})\010\009\009end)\010\009\009Mouse.Button1Up:connect(function()\010\009\009\009InvokeServer(\034Button1Click\034, {Down = false})\010\009\009end)\010\009\009Mouse.KeyDown:connect(function(Key)\010\009\009\009InvokeServer(\034KeyPress\034, {Key = Key, Down = true})\010\009\009end)\010\009\009Mouse.KeyUp:connect(function(Key)\010\009\009\009InvokeServer(\034KeyPress\034, {Key = Key, Down = false})\010\009\009end)\010\009\009local PlayerGui = Player:FindFirstChild(\034PlayerGui\034)\010\009\009if PlayerGui then\010\009\009\009InputCheckClone = InputCheck:Clone()\010\009\009\009if UserInputService.TouchEnabled then\010\009\009\009\009InputCheckClone = InputCheck:Clone()\010\009\009\009\009InputCheckClone.InputButton.InputBegan:connect(function()\010\009\009\009\009\009InvokeServer(\034Button1Click\034, {Down = true})\010\009\009\009\009end)\010\009\009\009\009InputCheckClone.InputButton.InputEnded:connect(function()\010\009\009\009\009\009InvokeServer(\034Button1Click\034, {Down = false})\010\009\009\009\009end)\010\009\009\009\009InputCheckClone.Parent = PlayerGui\010\009\009\009end\010\009\009end\010\009\009for i, v in pairs(Tool:GetChildren()) do\010\009\009\009if v:IsA(\034Animation\034) then\010\009\009\009\009ContentProvider:Preload(v.AnimationId)\010\009\009\009end\010\009\009end\010\009end)\010end\010\010function Unequipped()\010\009if InputCheckClone then\010\009\009Debris:AddItem(InputCheckClone, 0)\010\009end\010\009if ObjectLocalTransparencyModifier then\010\009\009ObjectLocalTransparencyModifier:disconnect()\010\009end\010\009for i, v in pairs(Animations) do\010\009\009if v and v.AnimationTrack then\010\009\009\009v.AnimationTrack:Stop()\010\009\009end\010\009end\010\009LocalObjects = {}\010\009Animations = {}\010\009ToolEquipped = false\010end\010\010function InvokeServer(mode, value)\010\009local ServerReturn = nil\010\009pcall(function()\010\009\009ServerReturn = ServerControl:InvokeServer(mode, value)\010\009end)\010\009return ServerReturn\010end\010\010function OnClientInvoke(mode, value)\010\009if mode == \034PlayAnimation\034 and value and ToolEquipped and Humanoid then\010\009\009SetAnimation(\034PlayAnimation\034, value)\010\009elseif mode == \034StopAnimation\034 and value then\010\009\009SetAnimation(\034StopAnimation\034, value)\010\009elseif mode == \034PlaySound\034 and value then\010\009\009value:Play()\010\009elseif mode == \034StopSound\034 and value then\010\009\009value:Stop()\010\009elseif mode == \034MousePosition\034 then\010\009\009return ((PlayerMouse and {Position = PlayerMouse.Hit.p, Target = PlayerMouse.Target}) or nil)\010\009elseif Mode == \034SetLocalTransparencyModifier\034 and value and ToolEquipped then\010\009\009pcall(function()\010\009\009\009local ObjectFound = false\010\009\009\009for i, v in pairs(LocalObjects) do\010\009\009\009\009if v == value then\010\009\009\009\009\009ObjectFound = true\010\009\009\009\009end\010\009\009\009end\010\009\009\009if not ObjectFound then\010\009\009\009\009table.insert(LocalObjects, value)\010\009\009\009\009if ObjectLocalTransparencyModifier then\010\009\009\009\009\009ObjectLocalTransparencyModifier:disconnect()\010\009\009\009\009end\010\009\009\009\009ObjectLocalTransparencyModifier = RunService.RenderStepped:connect(function()\010\009\009\009\009\009for i, v in pairs(LocalObjects) do\010\009\009\009\009\009\009if v.Object and v.Object.Parent then\010\009\009\009\009\009\009\009if ((not v.AutoUpdate and (v.Object.LocalTransparencyModifier == 1 or  v.Object.LocalTransparencyModifier == 0)) or v.AutoUpdate) then\010\009\009\009\009\009\009\009\009v.Object.LocalTransparencyModifier = v.Transparency\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009else\010\009\009\009\009\009\009\009table.remove(LocalObjects, i)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end)\010\009\009\009end\010\009\009end)\010\009end\010end\010\010ClientControl.OnClientInvoke = OnClientInvoke\010Tool.Equipped:connect(Equipped)\010Tool.Unequipped:connect(Unequipped)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19909,class="LocalScript",parent=19907,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Local",["ScriptGuid"]="{2E63868B-D731-422E-836F-DB5292E8ECFA}",["Source"]="--local mDebugId = game.Workspace.DebugId.Value\010--game.Workspace.DebugId.Value = game.Workspace.DebugId.Value+1\010--print(\034Running swordscript <\034..mDebugId..\034>\034)\010\010-------------------------------------\010-- Makes an RBX::Lua Instance using\010-- a table of key-value pairs to\010-- initialize it. Values with numeric \010-- keys will be parented to the object\010-- and other values will be set\010-- as members of the object.\010function Create(ty)\010\009return function(data)\010\009\009local obj = Instance.new(ty)\010\009\009for k, v in pairs(data) do\010\009\009\009if type(k) == 'number' then\010\009\009\009\009v.Parent = obj\010\009\009\009else\010\009\009\009\009obj[k] = v\010\009\009\009end\010\009\009end\010\009\009return obj\010\009end\010end\010\010---------------------------------------\010-- Same as Make, but modifies an existing\010-- object rather than creating ones.\010function Modify(obj, data)\010\009for k, v in pairs(data) do\010\009\009if type(data) == 'number' then\010\009\009\009data.Parent = obj\010\009\009else\010\009\009\009data[k] = v\010\009\009end\010\009end\010\009return obj\010end\010\010-----------------------------------------\010-- Creates a class which can be instantiated\010-- using `CreateCLASSNAME( ... )`.\010---usage:\010--class'MyClass'(function(this, arg1)\010--\009this.ClassMember = value\010--\009function this.ClassMethod(...) ... end\010--end, function(def)\010--\009def.StaticMember = value\010--\009 function def.StaticMethod(...) ... end\010--end)\010--local obj = CreateMyClass(arg1)\010------------------------------------------\010local function class(name)\010\009local def = {}\010\009getfenv(0)[name] = def\010\009return function(ctor, static)\010\009\009local nctor = function(...)\010\009\009\009local this = {}\010\009\009\009if ctor then\010\009\009\009\009ctor(this, ...)\010\009\009\009end\010\009\009\009return this\010\009\009end\010\009\009getfenv(0)['Create'..name] = nctor\010\009\009if static then static(def) end\010\009end\010end\010\010\010---------------------------------------------\010-- Signal class for custom-made events\010--API:\010-- Signal:connect(callback)\010-- Signal:fire(...)\010-- Signal:wait()\010---------------------------------------------\010class'Signal'(function(this)\010\009local mListeners = {}\010\009local mWaitObject = Create'BoolValue'{}\010\010\009function this:connect(func)\010\009\009local connection = {}\010\009\009function connection:disconnect()\010\009\009\009mListeners[func] = nil\010\009\009end\010\009\009mListeners[func] = connection\010\009\009return connection\010\009end\010\010\009function this:fire(...)\010\009\009--print(\034Fire evt<\034..tostring(this)..\034> from script<\034..mDebugId..\034>\034)\010\009\009for func, conn in pairs(mListeners) do\010\009\009\009--print(\034-> \034..tostring(func)..\034( ... )\034)\010\009\009\009func(...)\010\009\009end\010\009\009mWaitObject.Value = not mWaitObject.Value\010\009end\010\010\009function this:wait()\010\009\009mWaitObject.Changed:wait()\010\009end\010end)\010\010\010--------------------------------------------------\010-- Bin class for cleaning up assets\010--API: \010-- Bin:add(func: Function, ident: String)\010-- Bin:clean(ident: String)\010-- Bin:cleanAll()\010--------------------------------------------------\010class'Bin'(function(this)\010\009local mGarbage = {}\010\010\009function this:add(func, ident)\010\009\009ident = ident or '__unnamed'\010\009\009if not mGarbage[ident] then\010\009\009\009mGarbage[ident] = {}\010\009\009end\010\009\009mGarbage[ident][#mGarbage[ident]+1] = func\010\009end\010\010\009function this:clean(ident)\010\009\009local listToCall = mGarbage[ident]\010\009\009if listToCall then\010\009\009\009for _, func in pairs(listToCall) do\010\009\009\009\009func()\010\009\009\009end\010\009\009\009mGarbage[ident] = nil\010\009\009end\010\009end\010\010\009function this:cleanAll()\010\009\009for ident, list in pairs(mGarbage) do\010\009\009\009for _, func in pairs(list) do\010\009\009\009\009func()\010\009\009\009end\010\009\009\009mGarbage[ident] = nil\010\009\009end\010\009end\010end)\010\010\010-----------------------------------------------------\010-- AnimationProvider class for easy loading of\010-- animation assets into animationtracks once \010-- a humanoid is available.\010--API:\010-- AnimationProvider:registerAnimation(ident, assetid)\010-- AnimationProvider:setHumanoid(humanoid)\010-- AnimationProvider:setTool(tool)\010-- AnimationProvider:getAnimation(ident)\010-----------------------------------------------------\010class'AnimationProvider'(function(this)\010\009local mAnimations = {--[[ident => {AnimationId, CurrentTrack, CurrentAnim} ]]}\010\009local mCurrentHumanoid = nil\010\010\009function this:registerAnimation(ident, assetid)\010\009\009--check for an existing copy of the anim\010\009\009local existingAnim = Tool.Tool:FindFirstChild('ANIM_'..ident)\010\009\009\009\010\009\009--make the data for this anim\010\009\009local animdat = {\010\009\009\009AnimationId = assetid, \010\009\009\009CurrentAnim = existingAnim or Create'Animation'{\010\009\009\009\009Name = \034ANIM_\034..ident,\010\009\009\009\009AnimationId = assetid,\009\010\009\009\009},\010\009\009}\010\009\009mAnimations[ident] = animdat\010\010\009\009--if there's a current tool, put it in there\010\009\009if Tool.Tool then\010\009\009\009Tool.HUGE_EQUIP_HACK = true\010\009\009\009animdat.CurrentAnim.Parent = Tool.Tool\010\009\009\009Tool.HUGE_EQUIP_HACK = false\010\009\009end\010\009\009\010\009\009--if there's a humanoid load the animation track\010\009\009if mCurrentHumanoid then\010\009\009\009animdat.CurrentTrack = mCurrentHumanoid:LoadAnimation(animdat.CurrentAnim)\010\009\009end\010\009end\010\010\009function this:setHumanoid(humanoid)\010\009\009mCurrentHumanoid = humanoid\010\009\009for _, anim in pairs(mAnimations) do\010\009\009\009anim.CurrentTrack = humanoid:LoadAnimation(anim.CurrentAnim)\010\009\009end\010\009end\010\010\009function this:getAnimation(ident)\010\009\009local dat = mAnimations[ident]\010\009\009if not dat then error(\034Gear Fatal Error: Animation `\034..ident..\034` not found\034) end\010\009\009if not dat.CurrentTrack then \010\009\009\009error(\034Gear Fatal Error: No Humanoid for animation `\034..ident..\034` to run in\034) \010\009\009end\010\009\009return dat.CurrentTrack\010\009end\010end)\010\010\010----------------------------------------------\010-- SoundProvider class\010-- functions similarily to the animationprovider\010----------------------------------------------\010class'SoundProvider'(function(this)\010\009local mSounds = {}\010\010\009function this:registerSound(ident, assetid, inpart)\010\009\009inpart = inpart or Tool.Tool:FindFirstChild('Handle')\010\009\009if not inpart then\010\009\009\009repeat\010\009\009\009\009inpart = Tool.Tool.ChildAdded:wait()\010\009\009\009until inpart.Name == 'Handle'\010\009\009end\010\009\009local existingSound = inpart:FindFirstChild('SOUND_'..ident)\010\009\009local sounddat = {\010\009\009\009SoundId = assetid,\010\009\009\009CurrentSound = existingSound or Create'Sound'{\010\009\009\009\009Name = 'SOUND_'..ident,\010\009\009\009\009SoundId = assetid,\010\009\009\009\009Parent = inpart,\010\009\009\009},\010\009\009}\010\009\009mSounds[ident] = sounddat\010\009end\010\010\009function this:getSound(ident)\010\009\009local dat = mSounds[ident]\010\009\009if dat then\010\009\009\009return dat.CurrentSound\010\009\009end\010\009end\010end)\010\010\010----------------------------------------------\010-- DebounceProvider class -- Prevent events\010-- from happening in too rapid succession\010----------------------------------------------\010class'DebounceProvider'(function(this)\010\009local mFlagNameToLastTime = {}\010\010\009function this:test(ident, delta)\010\009\009local t = tick()\010\009\009local lastTime = mFlagNameToLastTime[ident] or 0\010\009\009if delta then\010\009\009\009return (t-lastTime) > delta\010\009\009else\010\009\009\009return mFlagNameToLastTime[ident]\010\009\009end\010\009end\010\009function this:set(ident, state)\010\009\009if state then\010\009\009\009mFlagNameToLastTime[ident] = state\010\009\009elseif state == false then\010\009\009\009mFlagNameToLastTime[ident] = false\010\009\009else\010\009\009\009mFlagNameToLastTime[ident] = tick()\010\009\009end\010\009end\010end)\010\010\010function TagHumanoid(humanoid)\010\009if Tool.Player then\010\009\009local tag = Create'ObjectValue'{\010\009\009\009Name = \034creator\034, \010\009\009\009Value = Tool.Player,\010\009\009\009Parent = humanoid,\010\009\009}\010\009\009game.Debris:AddItem(tag, 1)\010\009end\010end\010\010\010------- wait for any event in a set of events  to fire ------\010function WaitForAny(tb)\010\009local evt = tb\010\009local conn = {}\010\009local eventargs = nil\010\009local waitProxy = Create'BoolValue'{}\010\009for _, e in pairs(evt) do\010\009\009local c = e:connect(function(...)\010\009\009\009for _, c in pairs(conn) do\010\009\009\009\009c:disconnect()\010\009\009\009end\010\009\009\009eventargs = {...}\010\009\009\009waitProxy.Value = not waitProxy.Value\010\009\009end)\010\009\009conn[#conn+1] = c\010\009end\010\009--\010\009waitProxy.Changed:wait()\010\009--\010\009return unpack(eventargs)\010end\010\010\010----------------------------------------------\010-- Tool singleton class\010--API:\010-- ...\010class'Tool'(nil, function(this)\010\009--need this here for the animationprovider to use\010\009this.HUGE_EQUIP_HACK = false\010\010\009this.Bin = CreateBin()\010\009this.AnimationProvider = CreateAnimationProvider()\010\009this.DebounceProvider = CreateDebounceProvider()\010\009this.SoundProvider = CreateSoundProvider()\010\010\009--general values\010\009this.Tool = script.Parent\010\009this.Player = nil\010\009this.Humanoid = nil\010\009this.Character = nil\010\010\009--============ several flags for the gear\010\009--nothing\010\010\009--some events\010\009this.Equipped = CreateSignal()\010\009this.Unequipped = CreateSignal()\010\009this.OwnerChange = CreateSignal()\010\010\009--mouse utility events\010\009this.MouseClick = CreateSignal()\010\009this.MouseRelease = CreateSignal()\010\009this.MouseDoubleClick = CreateSignal()\010\009this.DoubleClickThreshold = 0.2\010\009this.MouseDown = false\010\009this.KeyDown = CreateSignal()\010\009this.KeyUp = CreateSignal()\010\009this.KeyState = {}\010\010\009local mLastClickTime = 0\010\010\009--\010\009local mCharacterChangedCn = nil\010\009local mCharacterChildAddedCn = nil\010\009local function locateAndAssignParts(ch)\010\009\009if ch:FindFirstChild('Humanoid') then this.Humanoid = ch.Humanoid end\010\009\009if ch:FindFirstChild('Head') then this.HeadPart = ch.Head end\010\009\009if ch:FindFirstChild('Torso') then this.TorsoPart = ch.Torso end\010\009\009if ch:FindFirstChild('Right Arm') then \009this.RightArmPart = ch['Right Arm'] end\010\009\009if ch:FindFirstChild('Left Arm') then \009this.LeftArmPart = \009ch['Left Arm'] end\010\009\009if ch:FindFirstChild('Right Leg') then \009this.RightLegPart = ch['Right Leg'] end\010\009\009if ch:FindFirstChild('Left Leg') then \009this.LeftLegPart = \009ch['Left Leg'] end\010\009end\010\009local function listenForCharacterAndParts(player)\010\009\009this.Tool = script.Parent\010\009\009this.Player = player\010\009\009--\010\009\009if mCharacterChangedCn then mCharacterChangedCn:disconnect() end\010\009\009mCharacterChangedCn = player.Changed:connect(function(prop)\010\009\009\009if prop == 'Character' and player.Character then\010\009\009\009\009if mCharacterChildAddedCn then mCharacterChildAddedCn:disconnect() end\010\009\009\009\009mCharacterChildAddedCn = player.Character.ChildAdded:connect(function(ch)\010\009\009\009\009\009locateAndAssignParts(player.Character)\010\009\009\009\009end)\010\009\009\009end\010\009\009end)\010\009\009if player.Character then\010\009\009\009if mCharacterChildAddedCn then mCharacterChildAddedCn:disconnect() end\010\009\009\009mCharacterChildAddedCn = player.Character.ChildAdded:connect(function(ch)\010\009\009\009\009locateAndAssignParts(player.Character)\010\009\009\009end)\010\009\009end\010\009end\010\009script.Parent.Changed:connect(function(prop)\010\009\009if prop == 'Parent' then\010\009\009\009--if it's in a character or backpack, find stuff\010\009\009\009local backpack = script.Parent.Parent\010\009\009\009if backpack and backpack:IsA('Backpack') then\010\009\009\009\009listenForCharacterAndParts(backpack.Parent)\010\009\009\009end\010\009\009end\010\009end)\010\009--if I'm allready in the backpack, listen for character\010\009if script.Parent.Parent:IsA('Backpack') then\010\009\009listenForCharacterAndParts(script.Parent.Parent.Parent)\010\009end\010\009script.Parent.Equipped:connect(function(mouse)\010\009\009--print(\034Internal Equipped: Time b: \034..time())\010\009\009--set up general values in the tool\010\009\009this.Mouse = mouse\010\009\009local curOwner = game.Players:GetPlayerFromCharacter(script.Parent.Parent)\010\009\009if curOwner ~= this.Player then\010\009\009\009this.Player = curOwner\010\009\009\009this.OwnerChange:fire(this.Player)\010\009\009end\010\009\009this.Character = this.Player.Character\010\009\009this.Humanoid = this.Character.Humanoid\010\009\009this.AnimationProvider:setHumanoid(this.Humanoid)\010\009\009locateAndAssignParts(this.Player.Character)\010\010\009\009--set up the mouse events\010\009\009mouse.Button1Down:connect(function()\010\009\009\009this.MouseDown = true\010\009\009\009local t = tick()\010\009\009\009if (t-mLastClickTime) < this.DoubleClickThreshold then\010\009\009\009\009--prvent multiple double-clicks in a row\010\009\009\009\009mLastClickTime = 0\010\009\009\009\009this.MouseDoubleClick:fire(mouse)\010\009\009\009else\010\009\009\009\009mLastClickTime = t\010\009\009\009\009this.MouseClick:fire(mouse)\010\009\009\009end\010\009\009end)\010\009\009mouse.Button1Up:connect(function()\010\009\009\009this.MouseDown = false\010\009\009\009this.MouseRelease:fire()\010\009\009end)\010\009\009mouse.KeyDown:connect(function(key)\010\009\009\009this.KeyState[key] = true\010\009\009\009this.KeyDown:fire(key)\010\009\009end)\010\009\009mouse.KeyUp:connect(function(key)\010\009\009\009this.KeyState[key] = false\010\009\009\009this.KeyUp:fire(key)\010\009\009end)\010\010\009\009--done setup, call the equipped function\010\009\009if this.HUGE_EQUIP_HACK then\010\009\009\009--the HUGE_EQUIP_HACK flags tells the tool that the equip is a synchronous\010\009\009\009--call as a result of parenting an animation to the character, which happens \010\009\009\009--when the tool is picked up from the workspace, but not during normal equips \010\009\009\009--(Why does this happen???), if this is the case, the call should be rederrred \010\009\009\009--one tick to ensure that all of the gear's loading can complete before it's \010\009\009\009--equipped event is called.\010\009\009\009--TODO: Blame John for this.\010\009\009\009Delay(0, function()\010\009\009\009\009this.Equipped:fire(mouse)\010\009\009\009end)\010\009\009else\010\009\009\009--otherwise, proceed as normal\010\009\009\009this.Equipped:fire(mouse)\010\009\009end\010\009end)\010\010\009script.Parent.Unequipped:connect(function()\010\009\009--before my teardown, fire the event\010\009\009this.Unequipped:fire()\010\010\009\009--delete all my garbage\010\009\009this.Bin:cleanAll()\010\009end)\010end)\010\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010--------------------------------------------------------------------------------------------------------------\010\010\010--------------------------------------------------\010function WaitForObject(name, parent)\010\009local object = parent:FindFirstChild(name)\010\009while not object do\010\009\009parent.ChildAdded:wait()\010\009\009object = parent:FindFirstChild(name)\010\009end\010\009return object\010end\010\010\010-------------------------------------------------\010Tool.AnimationProvider:registerAnimation('equip',          'http://www.roblox.com/asset/?id=73033645')\010Tool.AnimationProvider:registerAnimation('beginslash',     'http://www.roblox.com/asset/?id=73033669')\010Tool.AnimationProvider:registerAnimation('endslash',       'http://www.roblox.com/asset/?id=73033682')\010Tool.AnimationProvider:registerAnimation('charginmaslash', 'http://www.roblox.com/asset/?id=73033590')\010Tool.AnimationProvider:registerAnimation('powerslash',     'http://www.roblox.com/asset/?id=73033705')\010Tool.AnimationProvider:registerAnimation('entershield',    'http://www.roblox.com/asset/?id=73033633')\010Tool.AnimationProvider:registerAnimation('exitshield',     'http://www.roblox.com/asset/?id=73033655')\010Tool.AnimationProvider:registerAnimation('walkshield',     'http://www.roblox.com/asset/?id=73033721')\010Tool.SoundProvider:registerSound('slash', 'rbxasset://sounds\092\092swordslash.wav')\010Tool.SoundProvider:registerSound('equip', 'rbxasset://sounds\092\092unsheath.wav')\010Tool.SoundProvider:registerSound('down', 'rbxasset://sounds\092\092swordlunge.wav')\010Tool.SoundProvider:registerSound('hitground', 'rbxasset://sounds\092\092snap.wav')\010\010\010-------------------------------------------------\010local Shield = Create'Part'{\010\009Name = 'Shield';\010\009Size = Vector3.new(2.8,1,3.8);\010\009CanCollide = false;\010\009Create'SpecialMesh'{\010\009\009Scale = Vector3.new(2, 1.2, 2);\010\009\009TextureId = 'http://www.roblox.com/asset/?id=73012518';\010\009\009MeshId = 'http://www.roblox.com/asset/?id=73012430';\010\009};\010}\010\010\010-------------------------------------------------\010function SetShieldMode(state)\010\009Tool.Tool.ShieldState.Value = state\010end\010function GetShieldMode()\010\009return Tool.Tool.ShieldState.Value\010end\010\010\010-------------------------------------------------\010local ShieldScreenGui = Create'ScreenGui'{\010\009Name = 'DragonSword_Gui';\010}\010\010local ShieldGui = Create'Frame'{\010\009Style = 'RobloxRound';\010\009Position = UDim2.new(0.5, -128, 1, -150);\010\009Size = UDim2.new(0, 256, 0, 40);\010\009Name = 'ShieldGui';\010\009--\010\009Parent = ShieldScreenGui;\010\009--\010\009Create'Frame'{\010\009\009Name = 'Bar';\010\009\009Size = UDim2.new(1, 0, 1, 0);\010\009\009BackgroundColor3 = Color3.new(0.2, 0.2, 1.0);\010\009};\010\009Create'TextLabel'{\010\009\009Name = 'Label';\010\009\009Size = UDim2.new(1, 0, 1, 0);\010\009\009BackgroundTransparency = 1.0;\010\009\009Text = 'Shield Health: 400/400';\010\009\009Font = 'ArialBold';\010\009\009FontSize = 'Size14';\010\009\009TextColor3 = Color3.new(0.3, 0.3, 0.8);\010\009\009TextStrokeTransparency = 0;\010\009\009TextStrokeColor3 = Color3.new(1,1,1);\010\009};\010}\010\010local ShieldModeMessage = Create'Frame'{\010\009Style = 'RobloxRound';\010\009Position = UDim2.new(0.5, -320, 1, -160);\010\009Size = UDim2.new(0, 180, 0, 60);\010\009Name = 'ShieldUsageDescription';\010\009--\010\009Parent = ShieldScreenGui;\010\009--\010\009Create'TextLabel'{\010\009\009Name = 'Label';\010\009\009Size = UDim2.new(1, 0, 1, 0);\010\009\009BackgroundTransparency = 1.0;\010\009\009Text = 'Hold Q to protect\092nyourself from damage';\010\009\009Font = 'Arial';\010\009\009FontSize = 'Size14';\010\009\009TextWrapped = true;\010\009\009TextColor3 = Color3.new(1, 1, 1);\010\009\009--TextStrokeTransparency = 0;\010\009\009--TextStrokeColor3 = Color3.new(1,1,1);\010\009};\010}\010\010\010function LerpColors(c1, c2, fac)\010\009return Color3.new(c1.r*(1-fac) + c2.r*fac, \010\009                  c1.g*(1-fac) + c2.g*fac,\010\009                  c1.b*(1-fac) + c2.b*fac)\010end\010\010\010function UpdateShieldGui()\010\009local shields = script.Parent.ShieldValue.Value\010\009local max = script.Parent.ShieldMax.Value\010\009--\010\009ShieldGui.Bar.Size = UDim2.new(shields/max, 0, 1, 0)\010\009ShieldGui.Label.Text = 'Shield Health: '..shields..'/'..max\010\009--\010end\010local LastShieldChange = 0\010WaitForObject('ShieldValue', script.Parent)\010script.Parent.ShieldValue.Changed:connect(function()\010\009LastShieldChange = tick()\010\009UpdateShieldGui()\010end)\010Spawn(function()\010\009--shield bar flasher daemon\010\009while true do\010\009\009wait()\010\009\009local timeSinceLastChange = tick()-LastShieldChange\010\009\009if timeSinceLastChange < 1 then\010\009\009\009local frac = 1 - ((timeSinceLastChange-1)^2)*math.sin(tick()*10)\010\009\009\009--\010\009\009\009ShieldGui.Bar.BackgroundColor3 = LerpColors(Color3.new(1,1,1), Color3.new(0.2,0.2,1), frac)\010\009\009else\010\009\009\009ShieldGui.Bar.BackgroundColor3 = Color3.new(0.2,0.2,1.0)\010\009\009end\010\009end\010end)\010\010\010-------------------------------------------------\010local DamageAmount = 0\010local Debounce = false\010Tool.MouseClick:connect(function()\010\009if Debounce or GetShieldMode() then return end\010\009Debounce = true\010\009DamageAmount = 10\010\009Tool.AnimationProvider:getAnimation('beginslash'):Play(0, 1, 6)\010\009repeat until Tool.AnimationProvider:getAnimation('beginslash').KeyframeReached:wait() == 'complete'\010\009if Tool.MouseDown then\010\009\009Tool.AnimationProvider:getAnimation('charginmaslash'):Play(0, 1, 5)\010\009\009while Tool.MouseDown do wait() end\010\009\009Tool.AnimationProvider:getAnimation('charginmaslash'):Stop(0)\010\009\009DamageAmount = 30\010\009\009Tool.AnimationProvider:getAnimation('powerslash'):Play(0, 1, 4)\010\009\009Spawn(function()\010\009\009\009Tool.SoundProvider:getSound('down'):Play()\010\009\009\009wait(0.1)\010\009\009\009Tool.SoundProvider:getSound('slash'):Play()\010\009\009\009wait(0.2)\010\009\009\009Tool.SoundProvider:getSound('down'):Play()\010\009\009end)\010\009\009------------ stolen from dagger of time to make the character \034dash\034\010\009\009------------\010\009\009repeat until Tool.AnimationProvider:getAnimation('powerslash').KeyframeReached:wait() == 'complete'\010\009\009DamageAmount = 0\010\009else\010\009\009DamageAmount = 20\010\009\009Tool.SoundProvider:getSound('slash'):Play()\010\009\009Tool.AnimationProvider:getAnimation('endslash'):Play(0, 1, 8)\010\009\009repeat until Tool.AnimationProvider:getAnimation('endslash').KeyframeReached:wait() == 'complete'\010\009\009DamageAmount = 0\010\009end\010\009Debounce = false\010end)\010\010local IsWalking = false\010\010Tool.KeyDown:connect(function(key)\010\009if key:lower() == 'q' and not Debounce then\010\009\009SetShieldMode(true)\010\009\009Tool.AnimationProvider:getAnimation('entershield'):Play(0, 1, 6)\010\009\009Tool.Humanoid.WalkSpeed = 10\010\009\009repeat until Tool.AnimationProvider:getAnimation('entershield').KeyframeReached:wait() == 'complete'\010\009\009if IsWalking and GetShieldMode() then\010\009\009\009Tool.AnimationProvider:getAnimation('walkshield'):Play(0, 1, 4)\010\009\009end\010\009end\010end)\010\010Tool.KeyUp:connect(function(key)\010\009if key:lower() == 'q' and GetShieldMode() then\010\009\009SetShieldMode(false)\010\009\009Tool.AnimationProvider:getAnimation('entershield'):Stop(0)\010\009\009Tool.AnimationProvider:getAnimation('walkshield'):Stop(0)\010\009\009Tool.AnimationProvider:getAnimation('exitshield'):Play(0, 1, 6)\010\009\009Tool.Humanoid.WalkSpeed = 16\010\009end\010end)\010\010local DamageCn;\010Tool.Equipped:connect(function()\010\009ShieldScreenGui.Parent = Tool.Player.PlayerGui\010\009----------------- generate the left grip for the shield ---------\010\009--note, the right grip requires special handling\010\009Spawn(function()\010\009\009leftArm = WaitForObject('Left Arm', Tool.Character)\010\009\009Shield.Parent = Tool.Character\010\009\009local leftGripMotor = Create'Motor6D'{\010\009\009\009Parent = leftArm;\010\009\009\009Part0 = leftArm;\010\009\009\009Part1 = Shield;\010\009\009}\010\009end)\010\010\009-------------- play the equip anims and sounds ------------------\010\009Tool.AnimationProvider:getAnimation('equip'):Play(0, 1, 2)\010\009Tool.SoundProvider:getSound('equip'):Play()\010\010\010\009--------------------- set up the shield-walking anims -----------\010\009local walkingCn = Tool.Humanoid.Running:connect(function(speed)\010\009\009if speed > 0 then\010\009\009\009IsWalking = true\010\009\009\009if GetShieldMode() then\010\009\009\009\009Tool.AnimationProvider:getAnimation('walkshield'):Play(0, 1, 4)\010\009\009\009else\010\009\009\009\009Tool.AnimationProvider:getAnimation('walkshield'):Stop(0)\010\009\009\009end\010\009\009else\010\009\009\009IsWalking = false\010\009\009\009Tool.AnimationProvider:getAnimation('walkshield'):Stop(0)\010\009\009end\010\009end)\010\009Tool.Bin:add(function()\010\009\009walkingCn:disconnect()\010\009end, 'walkingConnection')\010\010\010\009------------------ set up the damage\010\009DamageCn = Tool.Tool.Handle.Touched:connect(function(part)\010\009\009local hum = (part.Parent or game):FindFirstChild('Humanoid')\010\009\009if hum and hum ~= Tool.Humanoid and DamageAmount > 0 then\010\009\009\009local msg = Create'ObjectValue'{\010\009\009\009\009Name = tostring(DamageAmount);\010\009\009\009\009Value = hum;\010\009\009\009}\010\009\009\009msg.Parent = script.Parent.DamageBin\010\009\009end\010\009end)\010end)\010\010Tool.Unequipped:connect(function()\010\009Shield.Parent = nil\010\009Debounce = false\010\009IsWalking = false\010\009Tool.AnimationProvider:getAnimation('equip'):Stop(0.1)\010\009Tool.AnimationProvider:getAnimation('beginslash'):Stop(0.1)\010\009Tool.AnimationProvider:getAnimation('endslash'):Stop(0.1)\010\009Tool.AnimationProvider:getAnimation('charginmaslash'):Stop(0.1)\010\009Tool.AnimationProvider:getAnimation('powerslash'):Stop(0.1)\010\009Tool.AnimationProvider:getAnimation('entershield'):Stop(0.1)\010\009Tool.AnimationProvider:getAnimation('exitshield'):Stop(0.1)\010\009Tool.AnimationProvider:getAnimation('walkshield'):Stop(0.1)\010\009ShieldScreenGui.Parent = nil\010\009DamageCn:disconnect()\010end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19938,class="LocalScript",parent=19931,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MouseIcon",["ScriptGuid"]="{48B223D7-C07F-4DB5-9C3B-DE8E757BF1DC}",["Source"]="--Made by Luckymaxer\010\010Mouse_Icon = \034rbxasset://textures/GunCursor.png\034\010Reloading_Icon = \034rbxasset://textures/GunWaitCursor.png\034\010\010Tool = script.Parent\010\010Mouse = nil\010\010function UpdateIcon()\010\009if Mouse then\010\009\009Mouse.Icon = Tool.Enabled and Mouse_Icon or Reloading_Icon\010\009end\010end\010\010function OnEquipped(ToolMouse)\010\009Mouse = ToolMouse\010\009UpdateIcon()\010end\010\010function OnChanged(Property)\010\009if Property == \034Enabled\034 then\010\009\009UpdateIcon()\010\009end\010end\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Changed:connect(OnChanged)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19939,class="LocalScript",parent=19931,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{A7C155A5-F606-4ADE-9079-9A95E5A7622F}",["Source"]="--Made by Luckymaxer\010\010Tool = script.Parent\010Handle = Tool:WaitForChild(\034Handle\034)\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010RunService = game:GetService(\034RunService\034)\010ContentProvider = game:GetService(\034ContentProvider\034)\010UserInputService = game:GetService(\034UserInputService\034)\010\010InputCheck = Instance.new(\034ScreenGui\034)\010InputCheck.Name = \034InputCheck\034\010InputFrame = Instance.new(\034Frame\034)\010InputFrame.Name = \034InputButton\034\010InputFrame.BackgroundTransparency = 1\010InputFrame.Size = UDim2.new(1, 0, 1, 0)\010InputFrame.Parent = InputCheck\010\010RbxUtility = LoadLibrary(\034RbxUtility\034)\010Create = RbxUtility.Create\010\010Animations = {}\010LocalObjects = {}\010\010ServerControl = Tool:WaitForChild(\034ServerControl\034)\010ClientControl = Tool:WaitForChild(\034ClientControl\034)\010\010Rate = (1 / 60)\010\010ToolEquipped = false\010\010function SetAnimation(mode, value)\010\009if not ToolEquipped or not CheckIfAlive() then\010\009\009return\010\009end\010\009if mode == \034PlayAnimation\034 and value and ToolEquipped and Humanoid then\010\009\009for i, v in pairs(Animations) do\010\009\009\009if v.Animation == value.Animation then\010\009\009\009\009v.AnimationTrack:Stop()\010\009\009\009\009table.remove(Animations, i)\010\009\009\009end\010\009\009end\010\009\009local AnimationTrack = Humanoid:LoadAnimation(value.Animation)\010\009\009table.insert(Animations, {Animation = value.Animation, AnimationTrack = AnimationTrack})\010\009\009AnimationTrack:Play(value.FadeTime, value.Weight, value.Speed)\010\009elseif mode == \034StopAnimation\034 and value then\010\009\009for i, v in pairs(Animations) do\010\009\009\009if v.Animation == value.Animation then\010\009\009\009\009v.AnimationTrack:Stop()\010\009\009\009\009table.remove(Animations, i)\010\009\009\009end\010\009\009end\010\009end\010end\010\010function CheckIfAlive()\010\009return (((Character and Character.Parent and Humanoid and Humanoid.Parent and Humanoid.Health > 0 and Player and Player.Parent) and true) or false)\010end\010\010function Equipped(Mouse)\010\009Character = Tool.Parent\010\009Player = Players:GetPlayerFromCharacter(Character)\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009ToolEquipped = true\010\009if not CheckIfAlive() then\010\009\009return\010\009end\010\009Spawn(function()\010\009\009PlayerMouse = Player:GetMouse()\010\009\009Mouse.Button1Down:connect(function()\010\009\009\009InvokeServer(\034Button1Click\034, {Down = true})\010\009\009end)\010\009\009Mouse.Button1Up:connect(function()\010\009\009\009InvokeServer(\034Button1Click\034, {Down = false})\010\009\009end)\010\009\009Mouse.KeyDown:connect(function(Key)\010\009\009\009InvokeServer(\034KeyPress\034, {Key = Key, Down = true})\010\009\009end)\010\009\009Mouse.KeyUp:connect(function(Key)\010\009\009\009InvokeServer(\034KeyPress\034, {Key = Key, Down = false})\010\009\009end)\010\009\009local PlayerGui = Player:FindFirstChild(\034PlayerGui\034)\010\009\009if PlayerGui then\010\009\009\009InputCheckClone = InputCheck:Clone()\010\009\009\009if UserInputService.TouchEnabled then\010\009\009\009\009InputCheckClone = InputCheck:Clone()\010\009\009\009\009InputCheckClone.InputButton.InputBegan:connect(function()\010\009\009\009\009\009InvokeServer(\034Button1Click\034, {Down = true})\010\009\009\009\009end)\010\009\009\009\009InputCheckClone.InputButton.InputEnded:connect(function()\010\009\009\009\009\009InvokeServer(\034Button1Click\034, {Down = false})\010\009\009\009\009end)\010\009\009\009\009InputCheckClone.Parent = PlayerGui\010\009\009\009end\010\009\009end\010\009\009for i, v in pairs(Tool:GetChildren()) do\010\009\009\009if v:IsA(\034Animation\034) then\010\009\009\009\009ContentProvider:Preload(v.AnimationId)\010\009\009\009end\010\009\009end\010\009end)\010end\010\010function Unequipped()\010\009for i, v in pairs(Animations) do\010\009\009if v and v.AnimationTrack then\010\009\009\009v.AnimationTrack:Stop()\010\009\009end\010\009end\010\009if InputCheckClone then\010\009\009Debris:AddItem(InputCheckClone, 0)\010\009end\010\009if ObjectLocalTransparencyModifier then\010\009\009ObjectLocalTransparencyModifier:disconnect()\010\009end\010\009LocalObjects = {}\010\009Animations = {}\010\009ToolEquipped = false\010end\010\010function InvokeServer(mode, value)\010\009local ServerReturn = nil\010\009pcall(function()\010\009\009ServerReturn = ServerControl:InvokeServer(mode, value)\010\009end)\010\009return ServerReturn\010end\010\010function OnClientInvoke(mode, value)\010\009if not ToolEquipped or not CheckIfAlive() then\010\009\009return\010\009end\010\009if mode == \034PlayAnimation\034 and value then\010\009\009SetAnimation(\034PlayAnimation\034, value)\010\009elseif mode == \034StopAnimation\034 and value then\010\009\009SetAnimation(\034StopAnimation\034, value)\010\009elseif mode == \034PlaySound\034 and value then\010\009\009value:Play()\010\009elseif mode == \034StopSound\034 and value then\010\009\009value:Stop()\010\009elseif mode == \034MouseData\034 then\010\009\009return ((PlayerMouse and {Position = PlayerMouse.Hit.p, Target = PlayerMouse.Target}) or nil)\010\009elseif mode == \034SetLocalTransparencyModifier\034 and value and ToolEquipped then\010\009\009pcall(function()\010\009\009\009local ObjectFound = false\010\009\009\009for i, v in pairs(LocalObjects) do\010\009\009\009\009if v == value then\010\009\009\009\009\009ObjectFound = true\010\009\009\009\009end\010\009\009\009end\010\009\009\009if not ObjectFound then\010\009\009\009\009table.insert(LocalObjects, value)\010\009\009\009\009if ObjectLocalTransparencyModifier then\010\009\009\009\009\009ObjectLocalTransparencyModifier:disconnect(