Touched(RayHit, RayPos)\010end\010\010function Button1Pressed(Down)\010\009if not Down and MouseDown then\010\009\009MouseDown = false\010\009end\010end\010\010function KeyPress(Key, Down)\010\009if Key == \034r\034 and Down then\010\009\009Reload()\010\009end\010end\010\010function Activated()\010\009if not Tool.Enabled or not ToolEquipped or Reloading then\010\009\009return\010\009end\010\009Tool.Enabled = false\010\009if Configuration.Ammo.Magazines.Value > 0 then\010\009\009local FirstShot = false\010\009\009if Configuration.Automatic.Value then\010\009\009\009MouseDown = true\010\009\009end\010\009\009OnClientInvoke(\034StopAnimation\034, {Animation = Animations.Fire.Animation, FadeTime = nil})\010\009\009OnClientInvoke(\034PlayAnimation\034, Animations.Fire)\010\009\009while MouseDown or not FirstShot and ToolEquipped and CheckIfAlive() do\010\009\009\009if Configuration.Ammo.Magazines.Value <= 0 or not ToolEquipped or not CheckIfAlive() then\010\009\009\009\009break\010\009\009\009end\010\009\009\009if not FirstShot then\010\009\009\009\009FirstShot = true\010\009\009\009end\010\009\009\009local BurstAmount = math.random(Configuration.Burst.Bullets.MinValue, Configuration.Burst.Bullets.MaxValue)\010\009\009\009local WithinFiringRange = false\010\009\009\009Spawn(function()\010\009\009\009\009InvokeServer(\034Fire\034, true)\010\009\009\009end)\010\009\009\009for i = 1, ((BurstAmount > 0 and BurstAmount) or 1) do\010\009\009\009\009local TargetPosition = OnClientInvoke(\034MousePosition\034)\010\009\009\009\009if not TargetPosition then\010\009\009\009\009\009break\010\009\009\009\009end\010\009\009\009\009TargetPosition = TargetPosition.Position\010\009\009\009\009local StartPosition = (Handle.CFrame * CFrame.new(FiringOffset.X, FiringOffset.Y, FiringOffset.Z)).p\010\009\009\009\009if BurstAmount > 0 then\010\009\009\009\009\009local Offset = (Configuration.Burst.Offset.Value * 100)\010\009\009\009\009\009TargetPosition = TargetPosition + Vector3.new((math.ra