()\010\009LocalObjects = {}\010\009if CheckIfAlive() then\010\009\009Humanoid.CameraOffset = Vector3.new(0, 0, 0)\010\009end\010\009for i, v in pairs(Sounds) do\010\009\009v:Stop()\010\009end\010\009if PlayerMouse then\010\009\009PlayerMouse.Icon = \034\034\010\009end\010\009for i, v in pairs({InputCheckClone, ObjectLocalTransparencyModifier, AmmoDisplayClone, ClipSizeChanged, MagazinesChanged}) do\010\009\009if tostring(v) == \034Connection\034 then\010\009\009\009v:disconnect()\010\009\009elseif v and v.Parent then\010\009\009\009v:Destroy()\010\009\009end\010\009end\010\009MouseDown = false\010\009for i, v in pairs(AnimationTracks) do\010\009\009if v and v.AnimationTrack then\010\009\009\009v.AnimationTrack:Stop()\010\009\009end\010\009end\010\009AnimationTracks = {}\010\009ToolEquipped = false\010end\010\010function InvokeServer(mode, value)\010\009pcall(function()\010\009\009local ServerReturn = ServerControl:InvokeServer(mode, value)\010\009\009return ServerReturn\010\009end)\010end\010\010function OnClientInvoke(mode, value)\010\009if mode == \034PlayAnimation\034 and value and ToolEquipped and Humanoid then\010\009\009SetAnimation(\034PlayAnimation\034, value)\010\009elseif mode == \034StopAnimation\034 and value then\010\009\009SetAnimation(\034StopAnimation\034, value)\010\009elseif mode == \034PlaySound\034 and value then\010\009\009value:Play()\010\009elseif mode == \034StopSound\034 and value then\010\009\009value:Stop()\010\009elseif mode == \034MousePosition\034 then\010\009\009return {Position = PlayerMouse.Hit.p, Target = PlayerMouse.Target}\010\009elseif mode == \034SetLocalTransparencyModifier\034 and value and ToolEquipped then\010\009\009pcall(function()\010\009\009\009local ObjectFound = false\010\009\009\009for i, v in pairs(LocalObjects) do\010\009\009\009\009if v == value then\010\009\009\009\009\009ObjectFound = true\010\009\009\009\009end\010\009\009\009end\010\009\009\009if not ObjectFound then\010\009\009\009\009table.insert(LocalObjects, value)\010\009\009\009\009if ObjectLocalTransparencyModifier then\010\009\009\009\009\009ObjectLocalTransparencyModifier:disconnect()\010\009\009\009\009end\010\009\009\009\009ObjectLocalTransparencyModifier = RunService.RenderStepped:connect(function()\010\009\009\009\009\009for i, v in pairs(LocalObjects) do\010\009\009\009\009\009\009if v.Object and v.Object.Parent then\010\009\009\009\009\009\009\009local CurrentTransparency = v.Object.LocalTransparencyModifier\010\009\009\009\009\009\009\009if ((not v.AutoUpdate and (CurrentTransparency == 1 or  CurrentTransparency == 0)) or v.AutoUpdate) then\010\009\009\009\009\009\009\009\009v.Object.LocalTransparencyModifier = v.Transparency\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009else\010\009\009\009\009\009\009\009table.remove(LocalObjects, i)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end)\010\009\009\009end\010\009\009end)\010\009end\010end\010\010ClientControl.OnClientInvoke = OnClientInvoke\010\010Tool.Activated:connect(Activated)\010Tool.Equipped:connect(Equipped)\010Tool.Unequipped:connect(Unequipped)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20007,class="LocalScript",parent=19959,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="CastLaser",["ScriptGuid"]="{5A5005FA-6659-4EF6-A05C-E92D9645C91D}",["Source"]="--Made by Luckymaxer\010\010Debris = game:GetService(\034Debris\034)\010\010Camera = game:GetService(\034Workspace\034).CurrentCamera\010\010Sounds = {\010\009RayHit = script:WaitForChild(\034Hit\034)\010}\010\010BasePart = Instance.new(\034Part\034)\010BasePart.Shape = Enum.PartType.Block\010BasePart.Material = Enum.Material.Plastic\010BasePart.TopSurface = Enum.SurfaceType.Smooth\010BasePart.BottomSurface = Enum.SurfaceType.Smooth\010BasePart.FormFactor = Enum.FormFactor.Custom\010BasePart.Size = Vector3.new(0.2, 0.2, 0.2)\010BasePart.CanCollide = true\010BasePart.Locked = true\010BasePart.Anchored = false\010\010BaseRay = BasePart:Clone()\010BaseRay.Name = \034Laser\034\010BaseRay.BrickColor = BrickColor.new(\034New Yeller\034)\010BaseRay.Material = Enum.Material.SmoothPlastic\010BaseRay.Size = Vector3.new(0.2, 0.2, 0.2)\010BaseRay.Anchored = true\010BaseRay.CanCollide = false\010BaseRayMesh = Instance.new(\034SpecialMesh\034)\010BaseRayMesh.Name = \034Mesh\034\010BaseRayMesh.MeshType = Enum.MeshType.Brick\010BaseRayMesh.Scale = Vector3.new(0.2, 0.2, 1)\010BaseRayMesh.Offset = Vector3.new(0, 0, 0)\010BaseRayMesh.VertexColor = Vector3.new(1, 1, 1)\010BaseRayMesh.Parent = BaseRay\010\010function PlaySound(Position, Sound)\010\009local SoundPart = BasePart:Clone()\010\009SoundPart.Name = \034ParticlePart\034\010\009SoundPart.Transparency = 1\010\009SoundPart.Anchored = true\010\009SoundPart.CanCollide = false\010\009local SoundObject = Sound:Clone()\010\009SoundObject.Parent = SoundPart\010\009Debris:AddItem(SoundPart, 1.5)\010\009SoundPart.Parent = game:GetService(\034Workspace\034)\010\009SoundPart.CFrame = CFrame.new(Position)\010\009SoundObject:Play()\010end\010\010function FireRay(StartPosition, TargetPosition, Hit)\010\009\010\009local Vec = (TargetPosition - StartPosition)\010\009local Distance = Vec.magnitude\010\009local Direction = Vec.unit\010\009\010\009local PX = (StartPosition + (0.25 * Distance) * Direction)\010\009local PY = (StartPosition + (0.5 * Distance) * Direction)\010\009local PZ = (StartPosition + (0.75 * Distance) * Direction)\010\009\010\009local DX = (StartPosition - PX).magnitude\010\009local DY = (PX - PY).magnitude\010\009local DZ = (PY - PZ).magnitude\010\009\010\009local Limit = 2\010\009local AX = (PX + Vector3.new(math.random(math.max(-Limit, (-0.21 * DX)), math.min(Limit, (0.21 * DX))),math.random(math.max(-Limit, (-0.21 * DX)),math.min(Limit, (0.21 * DX))), math.random(math.max(-Limit, (-0.21 * DX)), math.min(Limit, (0.21 * DX)))))\010\009local AY = (PY + Vector3.new(math.random(math.max(-Limit, (-0.21 * DY)), math.min(Limit, (0.21 * DY))),math.random(math.max(-Limit, (-0.21 * DY)),math.min(Limit, (0.21 * DY))), math.random(math.max(-Limit, (-0.21 * DY)), math.min(Limit, (0.21 * DY)))))\010\009local AZ = (PZ + Vector3.new(math.random(math.max(-Limit, (-0.21 * DZ)), math.min(Limit, (0.21 * DZ))),math.random(math.max(-Limit, (-0.21 * DZ)),math.min(Limit, (0.21 * DZ))), math.random(math.max(-Limit, (-0.21 * DZ)), math.min(Limit, (0.21 * DZ)))))\010\009\010\009local Rays = {\010\009\009{Distance = (AX - StartPosition).magnitude, Direction = CFrame.new(StartPosition, AX)},\010\009\009{Distance = (AY - AX).magnitude, Direction = CFrame.new(AX, AY)},\010\009\009{Distance = (AZ - AY).magnitude, Direction = CFrame.new(AY, AZ)},\010\009\009{Distance = (TargetPosition - AZ).magnitude, Direction = CFrame.new(AZ, TargetPosition)},\010\009}\010\009\010\009for i, v in pairs(Rays) do\010\009\009local Ray = BaseRay:Clone()\010\009\009Ray.BrickColor = BrickColor.new(\034New Yeller\034)\010\009\009Ray.Reflectance = 0.4\010\009\009Ray.Transparency = 0.7\010\009\009local Mesh = Ray.Mesh\010\009\009Mesh.Scale = (Vector3.new(0.15, 0.15, (v.Distance / 1)) * 5)\010\009\009Ray.CFrame = (v.Direction * CFrame.new(0, 0, (-0.5 * v.Distance)))\010\009\009Debris:AddItem(Ray, (0.1 / (#Rays - (i - 1))))\010\009\009Ray.Parent = Camera\010\009end\010\009\010end\010\010pcall(function()\010\009local StartPosition = script:WaitForChild(\034StartPosition\034).Value\010\009local TargetPosition = script:WaitForChild(\034TargetPosition\034).Value\010\009local RayHit = script:WaitForChild(\034RayHit\034).Value\010\009FireRay(StartPosition, TargetPosition)\010\009if RayHit then\010\009\009PlaySound(TargetPosition, Sounds.RayHit)\010\009end\010end)\010\010Debris:AddItem(script, 1)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20015,class="LocalScript",parent=20013,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Client",["ScriptGuid"]="{324DDEA2-61E4-42AB-82DC-B2FC9B51D8F2}",["Source"]="local Player = game:GetService(\034Players\034).LocalPlayer\010local UIS = game:GetService(\034UserInputService\034)\010local Mouse = Player:GetMouse()\010local Tool = script.Parent\010local Remote = Tool:WaitForChild(\034Remote\034)\010local Tracks = {}\010local InputType = Enum.UserInputType\010\010local BeganConnection, EndedConnection\010\010function playAnimation(animName, ...)\010\009if Tracks[animName] then\010\009\009Tracks[animName]:Play()\010\009else\010\009\009local anim = Tool:FindFirstChild(animName)\010\009\009if anim and Tool.Parent and Tool.Parent:FindFirstChild(\034Humanoid\034) then\010\009\009\009Tracks[animName] = Tool.Parent.Humanoid:LoadAnimation(anim)\010\009\009\009playAnimation(animName, ...)\010\009\009end\010\009end\010end\010\010function stopAnimation(animName)\010\009if Tracks[animName] then\010\009\009Tracks[animName]:Stop()\010\009end\010end\010\010function inputBegan(input)\010\009if input.UserInputType == InputType.MouseButton1 then\010\009\009Remote:FireServer(\034LeftDown\034)\010\009end\010end\010\010function inputEnded(input)\010\009if input.UserInputType == InputType.MouseButton1 then\010\009\009Remote:FireServer(\034LeftUp\034)\010\009end\010end\010\010function onRemote(func, ...)\010\009if func == \034PlayAnimation\034 then\010\009\009playAnimation(...)\010\009elseif func == \034StopAnimation\034 then\010\009\009stopAnimation(...)\010\009end\010end\010\010function onEquip()\010\009BeganConnection = UIS.InputBegan:connect(inputBegan)\010\009EndedConnection = UIS.InputEnded:connect(inputEnded)\010end\010\010function onUnequip()\010\009if BeganConnection then\010\009\009BeganConnection:disconnect()\010\009\009BeganConnection = nil\010\009end\010\009\010\009if EndedConnection then\010\009\009EndedConnection:disconnect()\010\009\009EndedConnection = nil\010\009end\010end\010\010Tool.Equipped:connect(onEquip)\010Tool.Unequipped:connect(onUnequip)\010Remote.OnClientEvent:connect(onRemote)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20026,class="LocalScript",parent=20025,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ScytheScript",["ScriptGuid"]="{E7FB5BF0-D4BC-4F12-A270-7CF6E38E3B85}",["Source"]="wait(1.5)\010-----------------\010--| Constants |--\010-----------------\010\010local HIT_DAMAGE = 1500\010local LIMB_DEBRIS_TIME = 4 --NOTE: Should be less than respawn time\010\010local SLASH_COOLDOWN = 0.5\010\010local IGNORE_LIST = {torso = 1, handle = 1, effect = 1, water = 1} --NOTE: Keys must be lowercase, values must evaluate to true\010\010--------------------\010--| WaitForChild |--\010--------------------\010\010-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Tool = script.Parent\010local ToolHandle = Tool.Handle\010\010local MyModel = nil\010local MyPlayer = nil\010\010-------------------------\010--| Utility Functions |--\010-------------------------\010\010-- Returns a character ancestor and its Humanoid, or nil\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009local humanoid = subject:FindFirstChild('Humanoid')\010\009\009if humanoid then\010\009\009\009return subject, humanoid\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010-- Removes any old creator tags and applies new ones to the specified target\010local function ApplyTags(target)\010\009while target:FindFirstChild('creator') do\010\009\009target.creator:Destroy()\010\009end\010\010\009local creatorTag = Instance.new('ObjectValue')\010\009creatorTag.Value = MyPlayer\010\009creatorTag.Name = 'creator' --NOTE: Must be called 'creator' for website stats\010\010\009local iconTag = Instance.new('StringValue')\010\009iconTag.Value = Tool.TextureId\010\009iconTag.Name = 'icon'\010\010\009iconTag.Parent = creatorTag\010\009creatorTag.Parent = target\010\009DebrisService:AddItem(creatorTag, 4)\010end\010\010-----------------------\010--| Other Functions |--\010-----------------------\010\010local function OnTouched(otherPart)\010\009if otherPart and not IGNORE_LIST[string.lower(otherPart.Name)] then\010\009\009local character, humanoid = FindCharacterAncestor(otherPart)\010\009\009local TEAM = character:FindFirstChild(\034TEAM\034)\010\009\009if character and humanoid and character ~= MyModel and TEAM and TEAM.Value ~= MyModel.TEAM.Value then\010\009\009\009if connection then connection:disconnect() end\010\009\009\009ApplyTags(humanoid)\010\009\009\009ToolHandle[\034HitSound\034..math.random(1,3)]:Play()\010\009\009\009Tool.DamageEvent:FireServer(humanoid,HIT_DAMAGE)\010\009\009end\010\009end\010end\010\010local function OnEquipped()\010\009MyModel = Tool.Parent\010\009MyPlayer = PlayersService:GetPlayerFromCharacter(MyModel)\010\009if MyModel:FindFirstChild('Humanoid') then\010\009\009MyModel:FindFirstChild('Humanoid').WalkSpeed = MyModel:FindFirstChild('Humanoid').WalkSpeed * 2\010\009end\010end\010\010local function OnUnequipped()\010\009if MyModel:FindFirstChild('Humanoid') then\010\009\009MyModel:FindFirstChild('Humanoid').WalkSpeed = MyModel:FindFirstChild('Humanoid').WalkSpeed / 2\010\009end\010end\010\010local function OnActivated()\010\009if Tool.Enabled and MyModel:FindFirstChild('Humanoid') and MyModel.Humanoid.Health > 0 then\010\009\009Tool.Enabled = false --NOTE: Starts the animation\010\010\009\009connection = ToolHandle.Touched:connect(OnTouched)\010\009\009Delay(0.4, function() --NOTE: Hardcoded length of animation :[\010\009\009\009if connection then\010\009\009\009\009connection:disconnect()\010\009\009\009end\010\009\009end)\010\010\009\009local slashSound = ToolHandle:FindFirstChild('SwordSlash')\010\009\009if slashSound then\010\009\009\009slashSound:Play()\010\009\009end\010\010\009\009wait(SLASH_COOLDOWN)\010\010\009\009Tool.Enabled = true\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Unequipped:connect(OnUnequipped)\010Tool.Activated:connect(OnActivated)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20027,class="LocalScript",parent=20025,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MostAnimations",["ScriptGuid"]="{A85FB240-6FE0-45CD-A131-9AE76FF574EB}",["Source"]="--------------------\010--| WaitForChild |--\010--------------------\010\010-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local Tool = script.Parent\010\010--local ScytheEquipAnimation = WaitForChild(script, 'ScytheEquip2')\010local ScytheIdleAnimation = WaitForChild(script, 'Idle')\010local ScytheSlashAnimation = WaitForChild(script, 'AttackAnim')\010\010local ScytheEquipTrack = nil\010local ScytheIdleTrack = nil\010local ScytheSlashTrack = nil\010\010-----------------\010--| Functions |--\010-----------------\010\010local function OnEquipped()\010\009local myModel = Tool.Parent\010\009local humanoid = myModel:FindFirstChild('Humanoid')\010\009if humanoid then -- Preload animations\010\009\009--[[ScytheEquipTrack = humanoid:LoadAnimation(ScytheEquipAnimation)\010\009\009if ScytheEquipTrack then ScytheEquipTrack:Play() end]]\010\010\009\009ScytheIdleTrack = humanoid:LoadAnimation(ScytheIdleAnimation)\010\009\009if ScytheIdleTrack then ScytheIdleTrack:Play() end\010\010\009\009ScytheSlashTrack = humanoid:LoadAnimation(ScytheSlashAnimation)\010\009end\010end\010\010local function OnChanged(property)\010\009if property == 'Enabled' and Tool.Enabled == false then\010\009\009if ScytheSlashTrack then ScytheSlashTrack:Play(nil,nil,2) end\010\009end\010end\010\010local function OnUnequipped()\010\009-- Stop all animations\010\009if ScytheEquipTrack then ScytheEquipTrack:Stop() end\010\009if ScytheIdleTrack then ScytheIdleTrack:Stop() end\010\009if ScytheSlashTrack then ScytheSlashTrack:Stop() end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Changed:connect(OnChanged)\010Tool.Unequipped:connect(OnUnequipped)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20032,class="LocalScript",parent=20025,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChargeScript",["ScriptGuid"]="{BEB3C727-B1DD-4B77-9701-DDBBFDA0341E}",["Source"]="local Tool = script.Parent\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local Torso = Character:WaitForChild(\034Torso\034)\010local DamageEvent = Tool:WaitForChild(\034DamageEvent\034)\010\010local ChargeDamage = 5000\010local ChargeKnockback = 200\010local ChargeSpeed = 125\010local ChargeDuration = 1.5\010local ChargeSelfDamage = 0\010local ChargeSelfDamageTwo = -999999\010\010local ChargeReady = true\010local ChargeCooldown = 1.5\010local Equipped = false\010local Charging = false\010local ChargeDirection = Vector3.new(0,0,0)\010local BodyVelocity\010local Fires = {}\010\010Torso.Touched:connect(function(Hit)\010\009if Hit.Parent == nil or not Charging or Humanoid.Health == 0 and Hit.Parent ~= Character then return end\010\009local HitHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009local HitTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009local HitTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009if (HitHumanoid and HitHumanoid.Health ~= 0 and HitTEAM and HitTEAM.Value ~= TEAM.Value) then\010\009\009Charging = false\010\009\009Humanoid.AutoRotate = true\010\009\009Tool.Handle.Charge1:Stop()\010\009\009Tool.Handle.Charge2:Stop()\010\009\009Tool.Handle.Charge3:Stop()\010\009\009Tool.Handle[\034ChargeHit\034..math.random(1,3)]:Play()\010\009\009HitHumanoid.Sit = false\010\009\009HitTorso.Velocity = ChargeDirection * ChargeKnockback\010\009\009DamageEvent:FireServer(HitHumanoid,ChargeDamage)\010\009\009if BodyVelocity then BodyVelocity:Destroy() end\010\009\009Torso.Velocity = Vector3.new(0,0,0)\010\009\009for _, Fire in pairs(Fires) do\010\009\009\009Fire.Enabled = false\010\009\009end\010\009\009Delay(5,function()\010\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009Fire:Destroy()\010\009\009\009end\010\009\009end)\010\009elseif (Hit.Anchored == true and Hit.CanCollide == true) then\010\009\009Charging = false\010\009\009Humanoid.AutoRotate = true\010\009\009Tool.Handle.Charge1:Stop()\010\009\009Tool.Handle.Charge2:Stop()\010\009\009Tool.Handle.Charge3:Stop()\010\009\009Tool.Handle[\034ChargeHit\034..math.random(1,3)]:Play()\010\009\009DamageEvent:FireServer(Humanoid,ChargeSelfDamage)\010\009\009if BodyVelocity then BodyVelocity:Destroy() end\010\009\009Torso.Velocity = Vector3.new(0,0,0)\010\009\009for _, Fire in pairs(Fires) do\010\009\009\009Fire.Enabled = false\010\009\009end\010\009\009Delay(5,function()\010\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009Fire:Destroy()\010\009\009\009end\010\009\009end)\010\009end\010end)\010\010Tool.Equipped:connect(function()\010\009Equipped = true\010end)\010\010Tool.Unequipped:connect(function()\010\009Equipped = false\010end)\010\010Mouse.KeyDown:connect(function(Key)\010\009if not Equipped then return end\010\009if string.lower(Key) == \034e\034 then\010\009\009if ChargeReady then\010\009\009\009ChargeReady = false\010\009\009\009Delay(ChargeCooldown,function() ChargeReady = true end)\010\009\009\009if Humanoid:GetState() ~= Enum.HumanoidStateType.Dead then Humanoid:ChangeState(Enum.HumanoidStateType.Running) end\010\009\009\009Torso.CFrame = CFrame.new(Torso.Position, Vector3.new(Mouse.Hit.p.X,Torso.Position.Y,Mouse.Hit.p.Z))\010\009\009\009ChargeDirection = Torso.CFrame.lookVector\010\009\009\009Tool.Handle[\034Charge\034..math.random(1,3)]:Play()\010\009\009\009for _, Parts in pairs(Character:GetChildren()) do\010\009\009\009\009if Parts.ClassName == \034Part\034 or Parts.ClassName == \034WedgePart\034 or Parts.ClassName == \034CornerWedgePart\034 then\010\009\009\009\009\009local Fire = script.ChargeFire:Clone()\010\009\009\009\009\009table.insert(Fires,Fire)\010\009\009\009\009\009Fire.Size = 5 + (Parts.Size.magnitude*1.5)\010\009\009\009\009\009Fire.Enabled = true\010\009\009\009\009\009DamageEvent:FireServer(Humanoid,ChargeSelfDamageTwo)\010\009\009\009\009\009Fire.Parent = Parts\010\009\009\009\009end\010\009\009\009end\010\009\009\009Torso.Velocity = ChargeDirection * ChargeSpeed\010\009\009\009BodyVelocity = script.BodyVelocity:Clone()\010\009\009\009BodyVelocity.Velocity = ChargeDirection * ChargeSpeed\010\009\009\009BodyVelocity.Parent = Torso\010\009\009\009Charging = true\010\009\009\009Humanoid.AutoRotate = false\010\009\009\009wait(ChargeDuration)\010\009\009\009Charging = false\010\009\009\009Humanoid.AutoRotate = true\010\009\009\009if Humanoid:GetState() ~= Enum.HumanoidStateType.Dead then Humanoid:ChangeState(Enum.HumanoidStateType.Running) end\010\009\009\009Torso.Velocity = Vector3.new(0,0,0)\010\009\009\009if BodyVelocity then BodyVelocity:Destroy() end\010\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009Fire.Enabled = false\010\009\009\009end\010\009\009\009Delay(5,function()\010\009\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009\009Fire:Destroy()\010\009\009\009\009end\010\009\009\009end)\010\009\009end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20049,class="LocalScript",parent=20048,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ScytheScript",["ScriptGuid"]="{2335E2A5-D2B3-4481-9482-F0A472CEF381}",["Source"]="wait(1.5)\010-----------------\010--| Constants |--\010-----------------\010\010local HIT_DAMAGE = 3000\010local LIMB_DEBRIS_TIME = 4 --NOTE: Should be less than respawn time\010\010local SLASH_COOLDOWN = 0.5\010\010local IGNORE_LIST = {torso = 1, handle = 1, effect = 1, water = 1} --NOTE: Keys must be lowercase, values must evaluate to true\010\010--------------------\010--| WaitForChild |--\010--------------------\010\010-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Tool = script.Parent\010local ToolHandle = Tool.Handle\010\010local MyModel = nil\010local MyPlayer = nil\010\010-------------------------\010--| Utility Functions |--\010-------------------------\010\010-- Returns a character ancestor and its Humanoid, or nil\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009local humanoid = subject:FindFirstChild('Humanoid')\010\009\009if humanoid then\010\009\009\009return subject, humanoid\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010-- Removes any old creator tags and applies new ones to the specified target\010local function ApplyTags(target)\010\009while target:FindFirstChild('creator') do\010\009\009target.creator:Destroy()\010\009end\010\010\009local creatorTag = Instance.new('ObjectValue')\010\009creatorTag.Value = MyPlayer\010\009creatorTag.Name = 'creator' --NOTE: Must be called 'creator' for website stats\010\010\009local iconTag = Instance.new('StringValue')\010\009iconTag.Value = Tool.TextureId\010\009iconTag.Name = 'icon'\010\010\009iconTag.Parent = creatorTag\010\009creatorTag.Parent = target\010\009DebrisService:AddItem(creatorTag, 4)\010end\010\010-----------------------\010--| Other Functions |--\010-----------------------\010\010local function OnTouched(otherPart)\010\009if otherPart and not IGNORE_LIST[string.lower(otherPart.Name)] then\010\009\009local character, humanoid = FindCharacterAncestor(otherPart)\010\009\009local TEAM = character:FindFirstChild(\034TEAM\034)\010\009\009if character and humanoid and character ~= MyModel and TEAM and TEAM.Value ~= MyModel.TEAM.Value then\010\009\009\009if connection then connection:disconnect() end\010\009\009\009ApplyTags(humanoid)\010\009\009\009ToolHandle[\034HitSound\034..math.random(1,3)]:Play()\010\009\009\009Tool.DamageEvent:FireServer(humanoid,HIT_DAMAGE)\010\009\009end\010\009end\010end\010\010local function OnEquipped()\010\009MyModel = Tool.Parent\010\009MyPlayer = PlayersService:GetPlayerFromCharacter(MyModel)\010\009if MyModel:FindFirstChild('Humanoid') then\010\009\009MyModel:FindFirstChild('Humanoid').WalkSpeed = MyModel:FindFirstChild('Humanoid').WalkSpeed * 2\010\009end\010end\010\010local function OnUnequipped()\010\009if MyModel:FindFirstChild('Humanoid') then\010\009\009MyModel:FindFirstChild('Humanoid').WalkSpeed = MyModel:FindFirstChild('Humanoid').WalkSpeed / 2\010\009end\010end\010\010local function OnActivated()\010\009if Tool.Enabled and MyModel:FindFirstChild('Humanoid') and MyModel.Humanoid.Health > 0 then\010\009\009Tool.Enabled = false --NOTE: Starts the animation\010\010\009\009connection = ToolHandle.Touched:connect(OnTouched)\010\009\009Delay(0.4, function() --NOTE: Hardcoded length of animation :[\010\009\009\009if connection then\010\009\009\009\009connection:disconnect()\010\009\009\009end\010\009\009end)\010\010\009\009local slashSound = ToolHandle:FindFirstChild('SwordSlash')\010\009\009if slashSound then\010\009\009\009slashSound:Play()\010\009\009end\010\010\009\009wait(SLASH_COOLDOWN)\010\010\009\009Tool.Enabled = true\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Unequipped:connect(OnUnequipped)\010Tool.Activated:connect(OnActivated)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20050,class="LocalScript",parent=20048,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MostAnimations",["ScriptGuid"]="{F8887BBD-B9B0-448E-AAE1-85D4F153CC54}",["Source"]="--------------------\010--| WaitForChild |--\010--------------------\010\010-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local Tool = script.Parent\010\010--local ScytheEquipAnimation = WaitForChild(script, 'ScytheEquip2')\010local ScytheIdleAnimation = WaitForChild(script, 'Idle')\010local ScytheSlashAnimation = WaitForChild(script, 'AttackAnim')\010\010local ScytheEquipTrack = nil\010local ScytheIdleTrack = nil\010local ScytheSlashTrack = nil\010\010-----------------\010--| Functions |--\010-----------------\010\010local function OnEquipped()\010\009local myModel = Tool.Parent\010\009local humanoid = myModel:FindFirstChild('Humanoid')\010\009if humanoid then -- Preload animations\010\009\009--[[ScytheEquipTrack = humanoid:LoadAnimation(ScytheEquipAnimation)\010\009\009if ScytheEquipTrack then ScytheEquipTrack:Play() end]]\010\010\009\009ScytheIdleTrack = humanoid:LoadAnimation(ScytheIdleAnimation)\010\009\009if ScytheIdleTrack then ScytheIdleTrack:Play() end\010\010\009\009ScytheSlashTrack = humanoid:LoadAnimation(ScytheSlashAnimation)\010\009end\010end\010\010local function OnChanged(property)\010\009if property == 'Enabled' and Tool.Enabled == false then\010\009\009if ScytheSlashTrack then ScytheSlashTrack:Play(nil,nil,2) end\010\009end\010end\010\010local function OnUnequipped()\010\009-- Stop all animations\010\009if ScytheEquipTrack then ScytheEquipTrack:Stop() end\010\009if ScytheIdleTrack then ScytheIdleTrack:Stop() end\010\009if ScytheSlashTrack then ScytheSlashTrack:Stop() end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Changed:connect(OnChanged)\010Tool.Unequipped:connect(OnUnequipped)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20055,class="LocalScript",parent=20048,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChargeScript",["ScriptGuid"]="{EC33E06D-7F57-4E91-AA69-1BB301FF8665}",["Source"]="local Tool = script.Parent\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local Torso = Character:WaitForChild(\034Torso\034)\010local DamageEvent = Tool:WaitForChild(\034DamageEvent\034)\010\010local ChargeDamage = 50000\010local ChargeKnockback = 300\010local ChargeSpeed = 125\010local ChargeDuration = 1.5\010local ChargeSelfDamage = -999999999\010local ChargeSelfDamageTwo = -999999999\010\010local ChargeReady = true\010local ChargeCooldown = 1.5\010local Equipped = false\010local Charging = false\010local ChargeDirection = Vector3.new(0,0,0)\010local BodyVelocity\010local Fires = {}\010\010Torso.Touched:connect(function(Hit)\010\009if Hit.Parent == nil or not Charging or Humanoid.Health == 0 and Hit.Parent ~= Character then return end\010\009local HitHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009local HitTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009local HitTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009if (HitHumanoid and HitHumanoid.Health ~= 0 and HitTEAM and HitTEAM.Value ~= TEAM.Value) then\010\009\009Charging = false\010\009\009Humanoid.AutoRotate = true\010\009\009Tool.Handle.Charge1:Stop()\010\009\009Tool.Handle.Charge2:Stop()\010\009\009Tool.Handle.Charge3:Stop()\010\009\009Tool.Handle[\034ChargeHit\034..math.random(1,3)]:Play()\010\009\009HitHumanoid.Sit = false\010\009\009HitTorso.Velocity = ChargeDirection * ChargeKnockback\010\009\009DamageEvent:FireServer(HitHumanoid,ChargeDamage)\010\009\009if BodyVelocity then BodyVelocity:Destroy() end\010\009\009Torso.Velocity = Vector3.new(0,0,0)\010\009\009for _, 