eFire:Clone()\010\009\009\009\009\009table.insert(Fires,Fire)\010\009\009\009\009\009Fire.Size = 5 + (Parts.Size.magnitude*1.5)\010\009\009\009\009\009Fire.Enabled = true\010\009\009\009\009\009DamageEvent:FireServer(Humanoid,ChargeSelfDamageTwo)\010\009\009\009\009\009Fire.Parent = Parts\010\009\009\009\009end\010\009\009\009end\010\009\009\009Torso.Velocity = ChargeDirection * ChargeSpeed\010\009\009\009BodyVelocity = script.BodyVelocity:Clone()\010\009\009\009BodyVelocity.Velocity = ChargeDirection * ChargeSpeed\010\009\009\009BodyVelocity.Parent = Torso\010\009\009\009Charging = true\010\009\009\009Humanoid.AutoRotate = false\010\009\009\009wait(ChargeDuration)\010\009\009\009Charging = false\010\009\009\009Humanoid.AutoRotate = true\010\009\009\009if Humanoid:GetState() ~= Enum.HumanoidStateType.Dead then Humanoid:ChangeState(Enum.HumanoidStateType.Running) end\010\009\009\009Torso.Velocity = Vector3.new(0,0,0)\010\009\009\009if BodyVelocity then BodyVelocity:Destroy() end\010\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009Fire.Enabled = false\010\009\009\009end\010\009\009\009Delay(5,function()\010\009\009\009\009for _, Fire in pairs(Fires) do\010\009\009\009\009\009Fire:Destroy()\010\009\009\009\009end\010\009\009\009end)\010\009\009end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20070,class="LocalScript",parent=20048,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="SummonScript",["ScriptGuid"]="{A7CAB52C-3764-409E-9D95-2B91C51F07B8}",["Source"]="local Tool = script.Parent\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010\010local Charge2Ready = true\010local Charge2Cooldown = 1\010\010Tool.Equipped:connect(function()\010\009Equipped = true\010end)\010\010Tool.Unequipped:connect(function()\010\009Equipped = false\010end)\010\010Mouse.KeyDown:connect(function(Key)\010\009if not Equipped then return end\010\009if string.lower(Key) == \034q\034 then\010\009\009\009\009\009if Charge2Ready then\010\009\009\009Charge2Ready = false\010\009\009\009Delay(Charge2Cooldown,function() Charge2Ready = true end)\010\009local doge = game.lighting.Allies[\034Decoy Doge\034]:clone()\010\009doge.Parent =  game.Workspace\010\009doge:MoveTo(script.Parent.Handle.Position+Vector3.new(0,5,0))\010\009end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20085,class="LocalScript",parent=20071,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Client",["ScriptGuid"]="{8D6E72AA-F3A0-4745-9E6E-02C8367F2909}",["Source"]="local Player = game:GetService(\034Players\034).LocalPlayer\010while not Player.Character do wait() end\010local Character = Player.Character\010local Human = Character:WaitForChild(\034Humanoid\034)\010\010local CAS = game:GetService(\034ContextActionService\034)\010local ActionName = \034GiantAngelicSword\034\010\010local Tool = script.Parent\010local Remote = Tool:WaitForChild(\034Remote\034)\010\010local Animations = {\010\009Hold = Tool:WaitForChild(\034Hold\034),\010\009Slam = Tool:WaitForChild(\034Slam\034),\010\009SwingRightToLeft = Tool:WaitForChild(\034SwingRightToLeft\034),\010\009SwingLeftToRight = Tool:WaitForChild(\034SwingLeftToRight\034),\010}\010local HoldTrack\010\010function playAnimation(name, fade, weight, speed)\010\009if Animations[name] then\010\009\009local track = Human:LoadAnimation(Animations[name])\010\009\009track:Play(fade, weight, speed)\010\009end\010end\010\010function onAction(actionName, inputState, inputObject)\010\009if inputState == Enum.UserInputState.Begin then\010\009\009Remote:FireServer(\034Attack\034)\010\009end\010end\010\010function onEquipped()\010\009--ensure unequip\010\009onUnequipped()\010\009\010\009--animate\010\009HoldTrack = Human:LoadAnimation(Animations.Hold)\010\009HoldTrack:Play(0.5)\010\009\010\009--bind actions\010\009CAS:BindActionToInputTypes(\010\009\009ActionName,\010\009\009onAction,\010\009\009false,\010\009\009Enum.UserInputType.MouseButton1,\010\009\009Enum.UserInputType.Touch\010\009)\010end\010\010function onUnequipped()\010\009--unbind\010\009CAS:UnbindAction(ActionName)\010\009\010\009--stop animation\010\009if HoldTrack then\010\009\009HoldTrack:Stop()\010\009end\010end\010\010function onRemote(func, ...)\010\009if func == \034PlayAnimation\034 then\010\009\009playAnimation(...)\010\009end\010end\010\010--set up events\010Tool.Equipped:connect(onEquipped)\010Tool.Unequipped:connect(onUnequipped)\010Remote.OnClientEvent:connect(onRemote)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20101,class="LocalScript",parent=20089,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Local",["ScriptGuid"]="{1E794A8C-80E0-444B-847B-409EC9303005}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Camera = Workspace.CurrentCamera\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local GunScript_Server = Tool:WaitForChild(\034GunScript_Server\034)\010local ChangeAmmoAndClip = GunScript_Server:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = GunScript_Server:WaitForChild(\034InflictTarget\034)\010local AmmoValue = GunScript_Server:WaitForChild(\034Ammo\034)\010local ClipsValue = GunScript_Server:WaitForChild(\034Clips\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local IdleAnim\010local FireAnim\010local ReloadAnim\010local ShotgunClipinAnim\010local Grip2\010local Handle2\010local HandleToFire = Handle\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,2)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local Equipped = false\010local Enabled = true\010local Down = false\010local Reloading = false\010local AimDown = false\010local Ammo = AmmoValue.Value\010local Clips = ClipsValue.Value\010local MaxClip = Module.MaxClip\010local PiercedHumanoid = {}\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009IdleAnim = Tool:WaitForChild(\034IdleAnim\034)\010\009IdleAnim = Humanoid:LoadAnimation(IdleAnim)\010end\010if Module.FireAnimationID ~= nil then\010\009FireAnim = Tool:WaitForChild(\034FireAnim\034)\010\009FireAnim = Humanoid:LoadAnimation(FireAnim)\010end\010if Module.ReloadAnimationID ~= nil then\010\009ReloadAnim = Tool:WaitForChild(\034ReloadAnim\034)\010\009ReloadAnim = Humanoid:LoadAnimation(ReloadAnim)\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009ShotgunClipinAnim = Tool:WaitForChild(\034ShotgunClipinAnim\034)\010\009ShotgunClipinAnim = Humanoid:LoadAnimation(ShotgunClipinAnim)\010end\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function RayCast(Start,Direction,Range,Ignore)\010\009local Hit,EndPos = game.Workspace:FindPartOnRay(Ray.new(Start,Direction*Range),Ignore)\010\009if Hit then\010\009\009if (Hit.Transparency > 0.75\010\009\009\009or Hit.Name == \034Handle\034\010\009\009\009or Hit.Name == \034Effect\034\010\009\009\009or Hit.Name == \034Bullet\034\010\009\009\009or Hit.Name == \034Laser\034\010\009\009\009or string.lower(Hit.Name) == \034water\034\010\009\009\009or Hit.Name == \034Rail\034\010\009\009\009or Hit.Name == \034Arrow\034\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent.Humanoid.Health == 0)\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent:FindFirstChild(\034TEAM\034) and TEAM and Hit.Parent.TEAM.Value == TEAM.Value))\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and PiercedHumanoid[Hit.Parent.Humanoid]) then\010\009\009\009Hit,EndPos = RayCast(EndPos+(Direction*.01),Direction,Range-((Start-EndPos).magnitude),Ignore)\010\009\009end\010\009end\010\009return Hit,EndPos\010end\010\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then\010\009local Zombie = script.Parent.Handle.FireSound:Clone()\010\009Zombie:Play()\010\009Zombie.Script.Disabled = false\010\009Zombie.Parent = script.Parent.Handle\010\009Zombie.Name = \034wut\034\010\009end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009PiercedHumanoid[TargetHumanoid] = true\010\009\009\009\009\009end\010\009\009\009\009else\010\009\009\009\009\009PierceAvailable = 0\010\009\009\009\009end\010\009\009\009end\010\009\009else\010\009\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009\009Explosion.BlastRadius = Module.Radius\010\009\009\009Explosion.BlastPressure = 0\010\009\009\009Explosion.Position = EndPos\010\009\009\009Explosion.Parent = Workspace.CurrentCamera\010\009\009\009Explosion.Hit:connect(function(Hit)\010\009\009\009\009if Hit and Hit.Parent and Hit.Name == \034Torso\034 then\010\009\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009PierceAvailable = 0\010\009\009end\010\009\009PierceAvailable = Hit and (PierceAvailable - 1) or -1\010\009\009Player.PlayerScripts.BulletVisualizerScript.Visualize:Fire(nil,ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009false,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009game.ReplicatedStorage.VisualizeBullet:FireServer(ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009true,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009Start = EndPos + (Direction*0.01)\010\009end\010\009print(\034==========\034)\010end\010\010function Reload()\010\009if Enabled and not Reloading and (Clips > 0 or not Module.LimitedClipEnabled) and Ammo < Module.AmmoPerClip then\010\009\009Reloading = true\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009\009UpdateGUI()\010\009\009if Module.ShotgunReload then\010\009\009\009for i = 1,(Module.AmmoPerClip - Ammo) do\010\009\009\009\009if ShotgunClipinAnim then ShotgunClipinAnim:Play(nil,nil,Module.ShotgunClipinAnimationSpeed) end\010\009\009\009\009Handle.ShotgunClipin:Play()\010\009\009\009\009wait(Module.ShellClipinSpeed)\010\009\009\009end\010\009\009end\010\009\009if ReloadAnim then ReloadAnim:Play(nil,nil,Module.ReloadAnimationSpeed) end\010\009\009Handle.ReloadSound:Play()\010\009\009wait(Module.ReloadTime)\010\009\009if Module.LimitedClipEnabled then Clips = Clips - 1 end\010\009\009Ammo = Module.AmmoPerClip\010\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009Reloading = false\010\009\009UpdateGUI()\010\009end\010end\010\010function UpdateGUI()\010\009GUI.Frame.Ammo.Fill:TweenSizeAndPosition(UDim2.new(Ammo/Module.AmmoPerClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Clips.Fill:TweenSizeAndPosition(UDim2.new(Clips/Module.MaxClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Ammo.Current.Text = Ammo\010\009GUI.Frame.Ammo.Max.Text = Module.AmmoPerClip\010\009GUI.Frame.Clips.Current.Text = Clips\010\009GUI.Frame.Clips.Max.Text = Module.MaxClip\010\010\009GUI.Frame.Ammo.Current.Visible = not Reloading\010\009GUI.Frame.Ammo.Max.Visible = not Reloading\010\009GUI.Frame.Ammo.Frame.Visible = not Reloading\010\009GUI.Frame.Ammo.Reloading.Visible = Reloading\010\010\009GUI.Frame.Clips.Current.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Max.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Frame.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.NoMoreClip.Visible = (Clips <= 0)\010\009\010\009GUI.Frame.Clips.Visible = Module.LimitedClipEnabled\010\009GUI.Frame.Size = Module.LimitedClipEnabled and UDim2.new(0,250,0,100) or UDim2.new(0,250,0,55)\010\009GUI.Frame.Position = Module.LimitedClipEnabled and UDim2.new(1,-260,1,-110)or UDim2.new(1,-260,1,-65)\010end\010\010Mouse.Button1Down:connect(function()\010\009Down = true\010end)\010Mouse.Button1Up:connect(function()\010\009Down = false\010end)\010\010ChangeAmmoAndClip.OnClientEvent:connect(function(ChangedAmmo,ChangedClips)\010\009Ammo = ChangedAmmo\010\009Clips = ChangedClips\010\009UpdateGUI()\010end)\010Tool.Equipped:connect(function(TempMouse)\010\009Equipped = true\010\009UpdateGUI()\010\009if Module.AmmoPerClip ~= math.huge then GUI.Parent = Player.PlayerGui end\010\009TempMouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009if IdleAnim then IdleAnim:Play(nil,nil,Module.IdleAnimationSpeed) end\010\009TempMouse.KeyDown:connect(function(Key)\010\009\009if string.lower(Key) == \034r\034 then\010\009\009\009Reload()\010\009\009elseif string.lower(Key) == \034e\034 then\010\009\009\009if not Reloading and AimDown == false and Module.SniperEnabled then\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = Module.FieldOfView\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034) or Tool.ZoomGui:Clone()\010\009\009\009\009GUI.Parent = game.Players.LocalPlayer.PlayerGui]]\010\009\009\009\009GUI.Scope.Visible = true\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.LockFirstPerson\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = false\010\009\009\009\009AimDown = true\010\009\009\009\009Mouse.Icon=\034http://www.roblox.com/asset?id=187746799\034\010\009\009\009else\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009\009GUI.Scope.Visible = false\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009\009AimDown = false\010\009\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009\009end\010\009\009end\010\009end)\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010Tool.Unequipped:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010Humanoid.Died:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010\010while true do\010\009local IsChargedShot = false\010\009if Equipped and Enabled and Down and not Reloading and Ammo > 0 and Humanoid.Health > 0 then\010\009\009Enabled = false\010\009\009if Module.ChargedShotEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034ChargeSound\034) then HandleToFire.ChargeSound:Play() end\010\009\009\009wait(Module.ChargingTime)\010\009\009\009IsChargedShot = true\010\009\009end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindUp\034) then HandleToFire.WindUp:Play() end\010\009\009\009wait(Module.DelayBeforeFiring)\010\009\009end\010\009\009while Equipped and not Reloading and (Down or IsChargedShot) and Ammo > 0 and Humanoid.Health > 0 do\010\009\009\009IsChargedShot = false\010\009\009\009for i = 1,(Module.BurstFireEnabled and Module.BulletPerBurst or 1) do\010\009\009\009\009Spawn(ShakeCamera)\010\009\009\009\009for x = 1,(Module.ShotgunEnabled and Module.BulletPerShot or 1) do\010\009\009\009\009\009Fire(HandleToFire)\010\009\009\009\009end\010\009\009\009\009Ammo = Ammo - 1\010\009\009\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009\009\009UpdateGUI()\010\009\009\009\009if Module.BurstFireEnabled then wait(Module.BurstRate) end\010\009\009\009\009if Ammo <= 0 then break end\010\009\009\009end\010\009\009\009HandleToFire = (HandleToFire == Handle and Module.DualEnabled) and Handle2 or Handle\010\009\009\009wait(Module.FireRate)\010\009\009\009if not Module.Auto then break end\010\009\009end\010\009\009if HandleToFire.FireSound.IsPlaying and HandleToFire.FireSound.Looped then HandleToFire.FireSound:Stop() end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindDown\034) then HandleToFire.WindDown:Play() end\010\009\009\009wait(Module.DelayAfterFiring)\010\009\009end\010\009\009Enabled = true\010\009\009if Ammo <= 0 then Reload() end\010\009end\010\009game:GetService(\034RunService\034).RenderStepped:wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20104,class="LocalScript",parent=20101,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{7C9B3EE4-9573-4AF2-810C-B560C4CD617B}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20147,class="LocalScript",parent=20136,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalKatanaScript",["ScriptGuid"]="{51F22B1A-628C-4500-986C-823ADF3E34E8}",["Source"]="local Tool = script.Parent\010Tool.Enabled = true\010\010local r = game:GetService(\034RunService\034)\010\010--invisible forces to move player around\010--body velocity\010local newBV = nil\010--body gyro\010local newBG = nil\010--body angualar velocity\010local newBAV = nil\010--body position\010local newBP = nil\010\010local slashSound = Tool.Handle.SlashSound\010local spinSound = Tool.Handle.SpinSound\010local whackSound = Tool.Handle.WhackSound\010\010--hum = local player's humanoid model\010--torso = local player's torso\010function slashIt(hum, torso)\010\009nsAnim = hum:LoadAnimation(Tool[\034Ninja Slash\034])\010\009if nsAnim == nil then Tool.Enabled = true return end\010\009\010\009nsAnim:Play()\010\009--where the player's torso is pointing\010\009if game.Players.NumPlayers>1 then \010\009\009target = getNearestPlayer().Character.Torso.CFrame.p  \010\009else target = hum.TargetPoint end\010\010\009local dir = (target - torso.Position) * Vector3.new(1, 0, 1)\010\009newBV = nil\010\009if dir.magnitude > .01 then \010\009\009-- make 'em dash forwards too\010\009\009dir = dir.unit\010\009\009newBV = Instance.new(\034BodyVelocity\034)\010\009\009newBV.P = 100000\010\009\009newBV.maxForce = Vector3.new(newBV.P, 0, newBV.P)\010\009\009newBV.velocity = dir * 50\010\009\009newBV.Parent = torso\010\010\009\009torso.CFrame = CFrame.new(torso.Position, target * Vector3.new(1, 0, 1) + Vector3.new(0, torso.Position.Y, 0))\010\009end\010\009\010\009wait(.5)\010\009slashSound:Play()\010\009if newBV ~= nil then newBV:remove() end\010\009wait(.5)\010end\010\010function blowIt(iterations)\010\010\009nsAnim = hum:LoadAnimation(Tool[\034dualslash2\034])\010\009nsAnim:Play()\010\009wait(.75)\010\009--create line explosion\010\009local exp_loc=Tool.Handle.CFrame.p\010\009--local exp_dir= Vector3.new(Tool.Parent.Torso.CFrame.lookVector)\010\009local exp_dir= torso.CFrame.lookVector\010\009Tool.lineExplosion:Play()\010\009for i=2, iterations, 1 do\010\009\009local explosion = Instance.new('Explosion', Workspace)\010\009\009explosion.ExplosionType = Enum.ExplosionType.CratersAndDebris\010\009\009explosion.Position=exp_loc+(exp_dir*(i*10))\010\009\009explosion.BlastPressure = 1\010\009\009explosion.BlastRadius = 10\010\009\009wait(.05)\010\009end\010\009\010end\010\010--returns closest player object\010function getNearestPlayer()\010\009local nearest=nil\010\009local nearest_distance=0\010\009local tdist = 0\010\009local parent_pos= game.Players.LocalPlayer.Character.Torso.CFrame.p\010\009local player= nil\010\009for _, player in pairs(game.Players:GetPlayers()) do\010\009\009print (player)\010\009\009if player.Character and player~=game.Players.LocalPlayer then\010\009\009\009tdist= (player.Character.Torso.CFrame.p-parent_pos).magnitude\010\009\009\009if nearest==nil or tdist<nearest_distance then\010\009\009\009\009nearest_distance=tdist\010\009\009\009\009nearest=player\010\009\009\009end\010\009\009end\010\009end\010\009return nearest\010end\010\010--hum = local player's humanoid model\010--torso = local player's torso\010function dashIt(hum, torso)\010\010\009ndAnim = hum:LoadAnimation(Tool[\034Ninja Dash\034])\010\009if ndAnim == nil then Tool.Enabled = true return end\010\010\009if game.Players.NumPlayers>1 then \010\009\009target = getNearestPlayer().Character.Torso.CFrame.p  \010\009else target = hum.TargetPoint end\010\010\009print (target)\010\009local dir = (target - torso.Position) * Vector3.new(1, 0, 1)\010\009if dir.magnitude < .01 then Tool.Enabled = true return end\010\009dir = dir.unit\010\010\009newBG = Instance.new(\034BodyGyro\034)\010\009newBG.P = 30000\010\009newBG.maxTorque = Vector3.new(newBG.P, newBG.P, newBG.P)\010\009--newBG.cframe = torso.CFrame * CFrame.Angles(-math.pi/2, 0, 0)\010\009local torsoPosition = torso.Position\010\009newBG.cframe = CFrame.new(torsoPosition, target*Vector3.new(1,0,1) + Vector3.new(0, torsoPosition.Y, 0) ) * CFrame.Angles(-math.pi/2, 0, 0)\010\009newBG.Parent = torso\010\010\009newBP = Instance.new(\034BodyPosition\034)\010\009newBP.P = 100000\010\009newBP.maxForce = Vector3.new(newBP.P, newBP.P, newBP.P)\010\009newBP.position = torsoPosition + Vector3.new(0, 1.5, 0)\010\009newBP.Parent = torso\010\010\009newBAV = Instance.new(\034BodyAngularVelocity\034)\010\009newBAV.P = 100000\010\009newBAV.maxTorque = Vector3.new(newBAV.P, newBAV.P, newBAV.P)\010\009\010\009newBV = Instance.new(\034BodyVelocity\034)\010\009newBV.P = 100000\010\009newBV.maxForce = Vector3.new(newBV.P, 0, newBV.P)\010\009newBV.velocity = dir * 64\010\010\009ndAnim:Play()\010\009wait(.5)\010\009spinSound:Play()\010\009newBG.maxTorque = Vector3.new(newBP.P, 0, newBP.P)\010\009newBP.maxForce = Vector3.new(0, newBP.P, 0)\010\009newBV.Parent = torso\010\010\009newBAV.angularvelocity = torso.CFrame:vectorToWorldSpace(Vector3.new(0, -30, 0))\010\009hum.Sit = true\010\009newBAV.Parent = torso\010\010\009wait(1)\010\010\009-- testing for fun\010--\009for i = 1, 50 do\010\009\009--target = hum.TargetPoint\010\009\009--newdir = (target - torso.Position) * Vector3.new(1, 0, 1)\010\009\009--if newdir.magnitude > .01 then \010--\009\009\009dir = newdir \010\009\009\009--dir = dir.unit \010\009\009\009--newBV.velocity = dir * 32 \010\009\009--end\010\010\009\009--newBG.cframe = CFrame.new(torso.Position, target*Vector3.new(1,0,1) + Vector3.new(0, torso.Position.Y, 0) ) * CFrame.Angles(-math.pi/2, 0, 0)\010\010\009\009--wait(.1)\010\009--end\010\009-- end of testing for fun\010\010\010\009--for i = 1, 3 do\010--\009\009ndAnim:Play()\010\009\009--wait(2)\010\009--end\010\010\009hum.Sit = false\010\009if newBAV ~= nil then newBAV:remove() end\010\009if newBP ~= nil then newBP:remove() end\010\009if newBV ~= nil then newBV:remove() end\010\010\009if newBG ~= nil then newBG.cframe = CFrame.new(torsoPosition, target*Vector3.new(1,0,1) + Vector3.new(0, torsoPosition.Y, 0) ) end\010\009if newBG ~= nil then newBG.maxTorque = Vector3.new(newBG.P, newBG.P, newBG.P) end\010\009spinSound:Stop()\010\009wait(.25)\010\009if newBG ~= nil then newBG:remove() end\010end\010\010local ultra_step_num=-1\010--time last key was pressed\010local lastWDown = 0\010local lastADown = 0\010local lastDDown = 0\010--time that dash was activated(see onKeyDown)\010local dashTime = 0\010--time of last slatsh effect\010local lastSlash = 0\010local lastSuperStrike = 0\010local amAnimating = false\010function onActivated()\010\009--cant find vChar's declaration??\010\009--vChar=player?\010\009vChar = Tool.Parent\010\009if vChar == nil then return end\010\009--hum = humanoid(player model)\010\009hum = vChar:FindFirstChild(\034Humanoid\034)\010\009if hum == nil then return end\010\009--if not Tool.Enabled then return end\010\009if amAnimating then return end\010\009Tool.Enabled = false\010\009amAnimating = true\010\010\009torso = vChar:FindFirstChild(\034Torso\034)\010\009if torso == nil then Tool.Enabled = true return end\010\010\009t = r.Stepped:wait()\010\009if t - lastSuperStrike < .2 then\010\009\009blowIt(10)\010\009\009wait(.5)  -- reload time\010\009\009amAnimating = false\010\009elseif t - dashTime < .2 then\009\009--special double click\010\009\009-- dash attack\010\009\009dashIt(hum, torso)\010\009\009wait(.5)  -- reload time\010\009\009amAnimating = false\010\009elseif t - lastSlash < .2 then\009--normal double click\010\009\009-- slash attack\010\009\009slashIt(hum, torso)\010\009\009--wait(1)\010\009\009amAnimating = false\010\009\009--wait(.5)  -- reload time\010\009else\010\009\009-- normal attack\010\009\009whackSound:Play()\010\009\009lastSlash = t\010\009\009amAnimating = false -- here must be before the wait, to allow for double-clix\010\009\009wait(.5)\010\009end\010\009if not amAnimating then Tool.Enabled = true end\010end\010\010local keyConnection = nil\010local keytime = 0\010function onKeyDown(key)\010\009keytime = r.Stepped:wait()\010\009if key:lower() == \034w\034 then\010\009\009if (keytime - lastWDown < .2) then dashTime = keytime end\010\009\009lastWDown = keytime\010\009elseif key:lower() == \034a\034 then\010\009\009lastADown = keytime\010\009elseif key:lower() == \034d\034 then\010\009\009lastDDown = keytime\010\009\009if lastDDown-lastADown <.4 and lastWDown>lastADown then \010\009\009\009print(\034SUPER STRIKE\034) \010\009\009\009lastSuperStrike=keytime\010\009\009end\010\009end\010end\010\010function onEquippedLocal(mouse)\010\009slashSound.Volume = 1 \010\009spinSound.Volume = 1\010\009whackSound.Volume = 1\010\010\009keyConnection = mouse.KeyDown:connect(onKeyDown)\010\010\009vChar = Tool.Parent\010\009if vChar == nil then return end\010\009--hum = humanoid(player model)\010\009hum = vChar:FindFirstChild(\034Humanoid\034)\010\009nsAnim = hum:LoadAnimation(Tool.swordPumpUp)\010\009nsAnim:Play()\010\009nsAnim:AdjustSpeed(3)\010end\010\010function onUnequippedLocal()\010\009if keyConnection ~= nil then keyConnection:disconnect() end\010\010\009if newBV ~= nil then newBV:remove() end\010\009if newBG ~= nil then newBG:remove() end\010\009if newBAV ~= nil then newBAV:remove() end\010\009if newBP ~= nil then newBP:remove() end\010\010\009slashSound.Volume = 0\010\009spinSound.Volume = 0\010\009whackSound.Volume = 0\010end\010\010Tool.Equipped:connect(onEquippedLocal)\010Tool.Unequipped:connect(onUnequippedLocal)\010Tool.Activated:connect(onActivated)\010 ",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20148,class="LocalScript",parent=20136,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Local Gui",["ScriptGuid"]="{3EDA675C-297D-4DD6-9AED-0326A0ED765B}",["Source"]="local Tool = script.Parent;\013\010\013\010local stillEquipped = true\013\010function onEquippedLocal(mouse)\013\010\009stillEquipped = true\013\010\009if mouse == nil then\013\010\009\009print(\034Mouse not found\034)\013\010\009\009return\013\010\009end\013\010\009\013\010\009while stillEquipped do\013\010\009\009print(\034Setting Mouse to Go\034)\013\010\009\009mouse.Icon = \034rbxasset://textures\092\092GunCursor.png\034\013\010\013\010\009\009while Tool.Enabled and stillEquipped do\013\010\009\009\009wait(.01)\013\010\009\009end\013\010\009\013\010\009\009print(\034Setting Mouse To Wait\034)\013\010\009\009mouse.Icon = \034rbxasset://textures\092\092GunWaitCursor.png\034\013\010\013\010\009\009while not Tool.Enabled and stillEquipped do\013\010\009\009\009wait(.01)\013\010\009\009end\013\010\009end\013\010end\013\010\013\010function onUnequippedLocal()\013\010\009stillEquipped = false\013\010end\013\010\013\010\013\010Tool.Equipped:connect(onEquippedLocal)\013\010Tool.Unequipped:connect(onUnequippedLocal)\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20161,class="LocalScript",parent=20155,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MouseIcon",["ScriptGuid"]="{EA142EF9-8627-428E-98FD-127BAE8F1C25}",["Source"]="local MOUSE_ICON = 'rbxasset://textures/GunCursor.png'\010local RELOADING_ICON = 'rbxasset://textures/GunWaitCursor.png'\010\010local Tool = script.Parent\010\010local Mouse = nil\010\010local function UpdateIcon()\010\009if Mouse then\010\009\009Mouse.Icon = Tool.Enabled and MOUSE_ICON or RELOADING_ICON\010\009end\010end\010\010local function OnEquipped(mouse)\010\009Mouse = mouse\010\009UpdateIcon()\010end\010\010local function OnChanged(property)\010\009if property == 'Enabled' then\010\009\009UpdateIcon()\010\009end\010end\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Changed:connect(OnChanged)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20162,class="LocalScript",parent=20155,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Launcher",["ScriptGuid"]="{754B1443-7A5E-403B-AC9E-149730F1A679}",["Source"]="wait()\010-----------------\010--| Constants |--\010-----------------\010\010local GRAVITY_ACCELERATION = 196.2\010\010local RELOAD_TIME = 0.05 -- Seconds until tool can be used again\010local ROCKET_SPEED = 0 -- Speed of the projectile\010\010local MISSILE_MESH_ID = 'http://www.roblox.com/asset/?id=90780672'\010local MISSILE_TEXTURE_ID = 'http://www.roblox.com/asset/?id=59693968'\010local MISSILE_MESH_SCALE = Vector3.new(10,10,15)\010local ROCKET_PART_SIZE = Vector3.new(1.2, 1.2, 3.27)\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local MyPlayer = PlayersService.LocalPlayer\010\010local Tool = script.Parent\010local ToolHandle = Tool.Handle\010\010local RocketScript = script:WaitForChild('Rocket')\010local SwooshSound = script:WaitForChild('Swoosh')\010local BoomSound = script:WaitForChild('Boom')\010local BoomSound2 = script:WaitForChild('Boom2')\010local Clip = Tool:WaitForChild('Clip')\010local ShootSound = ToolHandle:WaitForChild('Shoot')\010local ReloadSound = ToolHandle:WaitForChild('Reload')\010\010--NOTE: We create the rocket once and then clone it when the player fires\010local Rocket = Instance.new('Part') do\010\009-- Set up the rocket part\010\009Rocket.Name = 'Rocket'\010\009Rocket.FormFactor = Enum.FormFactor.Custom --NOTE: This must be done before changing Size\010\009Rocket.Size = ROCKET_PART_SIZE\010\009Rocket.CanCollide = false\010\009Rocket.Anchored = true\010\010\009-- Add the mesh\010\009local mesh = Instance.new('SpecialMesh', Rocket)\010\009mesh.MeshId = MISSILE_MESH_ID\010\009mesh.TextureId = MISSILE_TEXTURE_ID\010\009mesh.Scale = MISSILE_MESH_SCALE\010\010\009-- Add fire\010\009local fire = Instance.new('Fire', Rocket)\010\009fire.Heat = 5\010\009fire.Size = 2\010\010\009-- Add a force to counteract gravity\010\009local bodyForce = Instance.new('BodyForce', Rocket)\010\009bodyForce.Name = 'Antigravity'\010\009bodyForce.force = Vector3.new(0, Rocket:GetMass() * GRAVITY_ACCELERATION, 0)\010\010\009-- Clone the sounds and set Boom to PlayOnRemove\010\009local swooshSoundClone = SwooshSound:Clone()\010\009swooshSoundClone.Parent = Rocket\010\009local boomSoundClone = BoomSound:Clone()\010\009boomSoundClone.PlayOnRemove = true\010\009boomSoundClone.Parent = Rocket\010\009local boomSoundClone2 = BoomSound2:Clone()\010\009boomSoundClone2.PlayOnRemove = true\010\009boomSoundClone2.Parent = Rocket\010\010\009-- Attach creator tags to the rocket early on\010\009local creatorTag = Instance.new('ObjectValue', Rocket)\010\009creatorTag.Value = MyPlayer\010\009creatorTag.Name = 'creator' --NOTE: Must be called 'creator' for website stats\010\009local iconTag = Instance.new('StringValue', creatorTag)\010\009iconTag.Value = Tool.TextureId\010\009iconTag.Name = 'icon'\010\010\009-- Finally, clone the rocket script and enable it\010\009local rocketScriptClone = RocketScript:Clone()\010\009rocketScriptClone.Parent = Rocket\010\009rocketScriptClone.Disabled = false\010\009local rocketScriptClone2 = script.Script:Clone()\010\009rocketScriptClone2.Parent = Rocket\010\009local rocketScriptClone3 = script.Trail:Clone()\010\009rocketScriptClone3.Parent = Rocket\010\009local rocketScriptClone4 = script.DamageTag:Clone()\010\009rocketScriptClone4.Parent = rocketScriptClone\010end\010\010-----------------\010--| Functions |--\010-----------------\010\010local function Reload()\010\009while Clip.Value ~= Clip.MaxValue do\010\009\009ReloadSound:Play()\010\009\009if Anim2 then Anim2:Play() end\010\009\009wait(0)\010\009\009Clip.Value = Clip.Value + 4\010\009end\010end\010\010local function Equip(Mouse)\010\009if Mouse then\010\009\009Mouse.KeyDown:connect(function(Key)\010\009\009\009if string.lower(Key) == \034r\034 then\010\009\009\009\009if Tool.Enabled then\010\009\009\009\009\009Tool.Enabled = false\010\009\009\009\009\009Reload()\010\009\009\009\009\009Tool.Enabled = true\010\009\009\009\009end\010\009\009\009end\010\009\009end)\010\009end\010\009Anim = MyPlayer.Character:FindFirstChild('Humanoid'):LoadAnimation(Tool.ShootAnim)\010\009Anim2 = MyPlayer.Character:FindFirstChild('Humanoid'):LoadAnimation(Tool.ReloadAnim)\010end\010\010local function Unequip()\010\009if Anim then Anim:Stop() end\010\009if Anim2 then Anim2:Stop() end\010end\010\010local function OnActivated()\010\009local myModel = MyPlayer.Character\010\009if Tool.Enabled and myModel and myModel:FindFirstChild('Humanoid') and myModel.Humanoid.Health > 0 then\010\009\009Tool.Enabled = false\010\009\009\010\009\009ShootSound:Play()\010\009\009if Anim then Anim:Play(nil,nil,2.5) end\010\010\009\009-- Create a clone of Rocket and set its color\010\009\009local rocketClone = Rocket:Clone()\010\009\009DebrisService:AddItem(rocketClone, 30)\010\009\009rocketClone.BrickColor = MyPlayer.TeamColor\010\010\009\009-- Position the rocket clone and launch!\010\009\009local spawnPosition = (ToolHandle.CFrame * CFrame.new(0, 0, -3)).p\010\009\009rocketClone.CFrame = CFrame.new(spawnPosition, myModel.Humanoid.TargetPoint) --NOTE: This must be done before assigning Parent\010\009\009rocketClone.Velocity = rocketClone.CFrame.lookVector * ROCKET_SPEED --NOTE: This should be done before assigning Parent\010\009\009rocketClone.Parent = game.Players.LocalPlayer.Character.Torso\010\010\009\009Clip.Value = Clip.Value - 1\010\009\009wait(RELOAD_TIME)\010\009\009if Clip.Value == 0 then\010\009\009\009Reload()\010\009\009end\010\010\009\009Tool.Enabled = true\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Tool.Activated:connect(OnActivated)\010Tool.Equipped:connect(Equip)\010Tool.Unequipped:connect(Unequip)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20169,class="LocalScript",parent=20162,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Rocket",["ScriptGuid"]="{7F858BEF-04BF-49F6-B501-B69ADA6DB36F}",["Source"]="-----------------\010--| Constants |--\010-----------------\010\010local BLAST_RADIUS = 8 -- Blast radius of the explosion\010local BLAST_DAMAGE = 1000 -- Amount of damage done to players\010local BLAST_FORCE = 1000 -- Amount of force applied to parts\010\010local IGNORE_LIST = {rocket = 1, handle = 1, effect = 1, water = 1} -- Rocket will fly through things named these\010--NOTE: Keys must be lowercase, values must evaluate to true\010\010Explode = Instance.new(\034Part\034)\010Explode.formFactor = \034Custom\034\010Explode.Size = Vector3.new(0,0,0)\010Explode.Anchored = true\010Explode.CanCollide = false\010Explode.TopSurface = 0\010Explode.BottomSurface = 0\010Explode.BrickColor = BrickColor.new(\034Institutional white\034)\010Mesh = Instance.new(\034SpecialMesh\034,Explode)\010Mesh.MeshType = \034Brick\034\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009return hit2,pos2\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Rocket = script.Parent\010\010local CreatorTag = Rocket:WaitForChild('creator')\010local SwooshSound = Rocket:WaitForChild('Swoosh')\010\010-----------------\010--| Functions |--\010-----------------\010\010function DamageTag(parent,damage)\010\009DmgTag = script.DamageTag:clone()\010\009DmgTag.Damage.Value = damage\010\009DmgTag.creator.Value = game.Players.LocalPlayer\010\009DmgTag.Disabled = false\010\009DmgTag.Parent = parent\010end\010\010-- Removes any old creator tags and applies a new one to the target\010local function ApplyTags(target)\010\009while target:FindFirstChild('creator') do\010\009\009target.creator:Destroy()\010\009end\010\010\009local creatorTagClone = CreatorTag:Clone()\010\009DebrisService:AddItem(creatorTagClone, 1.5)\010\009creatorTagClone.Parent = target\010end\010\010-- Returns the ancestor that contains a Humanoid, if it exists\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009local humanoid = subject:FindFirstChild('Humanoid')\010\009\009if humanoid then\010\009\009\009return subject, humanoid\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010-- Customized explosive effect that doesn't affect teammates and only breaks joints on dead parts\010local function OnExplosionHit(hitPart, hitDistance, blastCenter)\010\009if hitPart and hitDistance then\010\009\009local character, humanoid = FindCharacterAncestor(hitPart.Parent)\010\009\009if humanoid and humanoid.Health > 0 then -- Humanoids are tagged and damaged\010\009\009\009if hitPart.Name == 'Torso' then\010\009\009\009\009--ApplyTags(humanoid)\010\009\009\009\009DamageTag(character,BLAST_DAMAGE)\010\009\009\009\009--humanoid:TakeDamage(BLAST_DAMAGE)\010\009\009\009end\010\009\009end\010\009end\010end\010\010local function OnTouched(otherPart,RayPos)\010\009if Rocket and otherPart then\010\009\009-- Fly through anything in the ignore list\010\009\009if IGNORE_LIST[string.lower(otherPart.Name)] then\010\009\009\009return\010\009\009end\010\010\009\009local myPlayer = CreatorTag.Value\010\009\009if myPlayer then\010\009\009\009-- Fly through the creator\010\009\009\009if myPlayer.Character and myPlayer.Character:IsAncestorOf(otherPart) then\010\009\009\009\009return\010\009\009\009end\010\010\009\009\009 -- Fly through friendlies\010\009\009\009if not myPlayer.Neutral then\010\009\009\009\009local character = FindCharacterAncestor(otherPart.Parent)\010\009\009\009\009local player = PlayersService:GetPlayerFromCharacter(character)\010\009\009\009\009if player and player ~= myPlayer and player.TeamColor == Rocket.BrickColor then\010\009\009\009\009\009return\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\010\009\009-- Fly through terrain water\010\009\009if otherPart == Workspace.Terrain then\010\009\009\009--NOTE: If the rocket is large, then the simplifications made here will cause it to fly through terrain in some cases\010\009\009\009local frontOfRocket = Rocket.Position + (Rocket.CFrame.lookVector * (Rocket.Size.Z / 2))\010\009\009\009local cellLocation = Workspace.Terrain:WorldToCellPreferSolid(frontOfRocket)\010\009\009\009local cellMaterial = Workspace.Terrain:GetCell(cellLocation.X, cellLocation.Y, cellLocation.Z)\010\009\009\009if cellMaterial == Enum.CellMaterial.Water or cellMaterial == Enum.CellMaterial.Empty then\010\009\009\009\009return\010\009\009\009end\010\009\009end\010\009\009\010\009\009Rocket.Transparency = 1\010\009\009Rocket.CFrame = CFrame.new(RayPos.X,RayPos.Y,RayPos.Z)\010\010\009\009-- Create the explosion\010\009\009local explosion = Instance.new('Explosion')\010\009\009explosion.BlastPressure = 500000 -- Completely safe explosion\010\009\009explosion.BlastRadius = BLAST_RADIUS\010\009\009explosion.DestroyJointRadiusPercent = 0\010\009\009explosion.ExplosionType = Enum.ExplosionType.NoCraters\010\009\009explosion.Position = Rocket.Position\010\009\009explosion.Parent = game.Players.LocalPlayer.Character.Torso\010\010\009\009-- Connect custom logic for the explosion\010\009\009explosion.Hit:connect(function(hitPart, hitDistance) OnExplosionHit(hitPart, hitDistance, explosion.Position) end)\010\009\009\010\009\009ypcall(function()\010\009\009\009for i = 1, 3 do\010\009\009\009\009ExplodeClone = Explode:clone()\010\009\009\009\009ExplodeClone.Position = Rocket.Position\010\009\009\009\009ExplodeClone.Mesh.Scale = Vector3.new(5,5,5)*5\010\009\009\009\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009\009\009\009ExplodeClone.Parent = game.Players.LocalPlayer.Character.Torso\010\009\009\009\009NewScript = Rocket.Script:clone()\010\009\009\009\009NewScript.Disabled = false\010\009\009\009\009NewScript.Parent = ExplodeClone\010\009\009\009end\010\009\009end)\010\010\009\009-- Move this script and the creator tag (so our custom logic can execute), then destroy the rocket\010\009\009script.Parent = explosion\010\009\009CreatorTag.Parent = script\010\009\009Rocket:Destroy()\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010SwooshSound:Play()\010\010--Rocket.Touched:connect(OnTouched)\010\010while script.Parent == Rocket do\010\009ExplodeClone = Explode:clone()\010\009ExplodeClone.Name = \034Effect\034\010\009ExplodeClone.BrickColor = BrickColor.new(\034White\034)\010\009ExplodeClone.Position = Rocket.Position\010\009ExplodeClone.Mesh.Scale = Vector3.new(1,1,1)*5\010\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009ExplodeClone.Parent = game.Players.LocalPlayer.Character.Torso\010\009NewScript = Rocket.Trail:clone()\010\009NewScript.Disabled = false\010\009NewScript.Parent = ExplodeClone\010\009local hit,pos = raycast(Rocket.Position,((Rocket.CFrame * CFrame.new(0,0,-10)).p-Rocket.Position).unit,10)\010\009if hit then\010\009\009OnTouched(hit,pos)\010\009end\010\009Rocket.CFrame = Rocket.CFrame * CFrame.new(0,0,-5) * CFrame.Angles(0, 0, math.rad(18))\010\009game:GetService(\034RunService\034).Stepped:wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20170,class="LocalScript",parent=20162,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Trail",["ScriptGuid"]="{BF8A1AA8-D0A7-49C1-AA9F-04468C88067A}",["Source"]="Fire = script.Parent\010WaitTime = 0.05\010Grow = math.random(15,25)/10\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Pastel light blue\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.1\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Institutional white\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.2\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Toothpaste\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.3\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Institutional white\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.4\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Pastel light blue\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.5\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Toothpaste\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.6\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.7\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.8\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.9\010wait(WaitTime)\010Fire:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
