0.4\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Pastel light blue\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.5\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Toothpaste\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.6\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.7\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.8\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.9\010wait(WaitTime)\010Fire:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20189,class="LocalScript",parent=20175,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Client",["ScriptGuid"]="{32E2D43D-1DE8-4E69-A682-E61AFCBB1633}",["Source"]="local Player = game:GetService(\034Players\034).LocalPlayer\010while not Player.Character do wait() end\010local Character = Player.Character\010local Human = Character:WaitForChild(\034Humanoid\034)\010\010local CAS = game:GetService(\034ContextActionService\034)\010local ActionName = \034GiantAngelicSword\034\010\010local Tool = script.Parent\010local Remote = Tool:WaitForChild(\034Remote\034)\010\010local Animations = {\010\009Hold = Tool:WaitForChild(\034Hold\034),\010\009Slam = Tool:WaitForChild(\034Slam\034),\010\009SwingRightToLeft = Tool:WaitForChild(\034SwingRightToLeft\034),\010\009SwingLeftToRight = Tool:WaitForChild(\034SwingLeftToRight\034),\010}\010local HoldTrack\010\010function playAnimation(name, fade, weight, speed)\010\009if Animations[name] then\010\009\009local track = Human:LoadAnimation(Animations[name])\010\009\009track:Play(fade, weight, speed)\010\009end\010end\010\010function onAction(actionName, inputState, inputObject)\010\009if inputState == Enum.UserInputState.Begin then\010\009\009Remote:FireServer(\034Attack\034)\010\009end\010end\010\010function onEquipped()\010\009--ensure unequip\010\009onUnequipped()\010\009\010\009--animate\010\009HoldTrack = Human:LoadAnimation(Animations.Hold)\010\009HoldTrack:Play(0.5)\010\009\010\009--bind actions\010\009CAS:BindActionToInputTypes(\010\009\009ActionName,\010\009\009onAction,\010\009\009false,\010\009\009Enum.UserInputType.MouseButton1,\010\009\009Enum.UserInputType.Touch\010\009)\010end\010\010function onUnequipped()\010\009--unbind\010\009CAS:UnbindAction(ActionName)\010\009\010\009--stop animation\010\009if HoldTrack then\010\009\009HoldTrack:Stop()\010\009end\010end\010\010function onRemote(func, ...)\010\009if func == \034PlayAnimation\034 then\010\009\009playAnimation(...)\010\009end\010end\010\010--set up events\010Tool.Equipped:connect(onEquipped)\010Tool.Unequipped:connect(onUnequipped)\010Remote.OnClientEvent:connect(onRemote)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20341,class="LocalScript",parent=20331,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Local",["ScriptGuid"]="{AD968882-7B05-4BE2-8325-373658E0C425}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Camera = Workspace.CurrentCamera\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local GunScript_Server = Tool:WaitForChild(\034GunScript_Server\034)\010local ChangeAmmoAndClip = GunScript_Server:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = GunScript_Server:WaitForChild(\034InflictTarget\034)\010local AmmoValue = GunScript_Server:WaitForChild(\034Ammo\034)\010local ClipsValue = GunScript_Server:WaitForChild(\034Clips\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local IdleAnim\010local FireAnim\010local ReloadAnim\010local ShotgunClipinAnim\010local Grip2\010local Handle2\010local HandleToFire = Handle\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,2)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local Equipped = false\010local Enabled = true\010local Down = false\010local Reloading = false\010local AimDown = false\010local Ammo = AmmoValue.Value\010local Clips = ClipsValue.Value\010local MaxClip = Module.MaxClip\010local PiercedHumanoid = {}\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009IdleAnim = Tool:WaitForChild(\034IdleAnim\034)\010\009IdleAnim = Humanoid:LoadAnimation(IdleAnim)\010end\010if Module.FireAnimationID ~= nil then\010\009FireAnim = Tool:WaitForChild(\034FireAnim\034)\010\009FireAnim = Humanoid:LoadAnimation(FireAnim)\010end\010if Module.ReloadAnimationID ~= nil then\010\009ReloadAnim = Tool:WaitForChild(\034ReloadAnim\034)\010\009ReloadAnim = Humanoid:LoadAnimation(ReloadAnim)\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009ShotgunClipinAnim = Tool:WaitForChild(\034ShotgunClipinAnim\034)\010\009ShotgunClipinAnim = Humanoid:LoadAnimation(ShotgunClipinAnim)\010end\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function RayCast(Start,Direction,Range,Ignore)\010\009local Hit,EndPos = game.Workspace:FindPartOnRay(Ray.new(Start,Direction*Range),Ignore)\010\009if Hit then\010\009\009if (Hit.Transparency > 0.75\010\009\009\009or Hit.Name == \034Handle\034\010\009\009\009or Hit.Name == \034Effect\034\010\009\009\009or Hit.Name == \034Bullet\034\010\009\009\009or Hit.Name == \034Laser\034\010\009\009\009or string.lower(Hit.Name) == \034water\034\010\009\009\009or Hit.Name == \034Rail\034\010\009\009\009or Hit.Name == \034Arrow\034\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent.Humanoid.Health == 0)\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent:FindFirstChild(\034TEAM\034) and TEAM and Hit.Parent.TEAM.Value == TEAM.Value))\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and PiercedHumanoid[Hit.Parent.Humanoid]) then\010\009\009\009Hit,EndPos = RayCast(EndPos+(Direction*.01),Direction,Range-((Start-EndPos).magnitude),Ignore)\010\009\009end\010\009end\010\009return Hit,EndPos\010end\010\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then ShootingHandle.FireSound:Play() end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009PiercedHumanoid[TargetHumanoid] = true\010\009\009\009\009\009end\010\009\009\009\009else\010\009\009\009\009\009PierceAvailable = 0\010\009\009\009\009end\010\009\009\009end\010\009\009else\010\009\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009\009Explosion.BlastRadius = Module.Radius\010\009\009\009Explosion.BlastPressure = 0\010\009\009\009Explosion.Position = EndPos\010\009\009\009Explosion.Parent = Workspace.CurrentCamera\010\009\009\009Explosion.Hit:connect(function(Hit)\010\009\009\009\009if Hit and Hit.Parent and Hit.Name == \034Torso\034 then\010\009\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009PierceAvailable = 0\010\009\009end\010\009\009PierceAvailable = Hit and (PierceAvailable - 1) or -1\010\009\009Player.PlayerScripts.BulletVisualizerScript.Visualize:Fire(nil,ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009false,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009game.ReplicatedStorage.VisualizeBullet:FireServer(ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009true,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009Start = EndPos + (Direction*0.01)\010\009end\010\009print(\034==========\034)\010end\010\010function Reload()\010\009if Enabled and not Reloading and (Clips > 0 or not Module.LimitedClipEnabled) and Ammo < Module.AmmoPerClip then\010\009\009Reloading = true\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009\009UpdateGUI()\010\009\009if Module.ShotgunReload then\010\009\009\009for i = 1,(Module.AmmoPerClip - Ammo) do\010\009\009\009\009if ShotgunClipinAnim then ShotgunClipinAnim:Play(nil,nil,Module.ShotgunClipinAnimationSpeed) end\010\009\009\009\009Handle.ShotgunClipin:Play()\010\009\009\009\009wait(Module.ShellClipinSpeed)\010\009\009\009end\010\009\009end\010\009\009if ReloadAnim then ReloadAnim:Play(nil,nil,Module.ReloadAnimationSpeed) end\010\009\009Handle.ReloadSound:Play()\010\009\009wait(Module.ReloadTime)\010\009\009if Module.LimitedClipEnabled then Clips = Clips - 1 end\010\009\009Ammo = Module.AmmoPerClip\010\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009Reloading = false\010\009\009UpdateGUI()\010\009end\010end\010\010function UpdateGUI()\010\009GUI.Frame.Ammo.Fill:TweenSizeAndPosition(UDim2.new(Ammo/Module.AmmoPerClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Clips.Fill:TweenSizeAndPosition(UDim2.new(Clips/Module.MaxClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Ammo.Current.Text = Ammo\010\009GUI.Frame.Ammo.Max.Text = Module.AmmoPerClip\010\009GUI.Frame.Clips.Current.Text = Clips\010\009GUI.Frame.Clips.Max.Text = Module.MaxClip\010\010\009GUI.Frame.Ammo.Current.Visible = not Reloading\010\009GUI.Frame.Ammo.Max.Visible = not Reloading\010\009GUI.Frame.Ammo.Frame.Visible = not Reloading\010\009GUI.Frame.Ammo.Reloading.Visible = Reloading\010\010\009GUI.Frame.Clips.Current.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Max.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Frame.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.NoMoreClip.Visible = (Clips <= 0)\010\009\010\009GUI.Frame.Clips.Visible = Module.LimitedClipEnabled\010\009GUI.Frame.Size = Module.LimitedClipEnabled and UDim2.new(0,250,0,100) or UDim2.new(0,250,0,55)\010\009GUI.Frame.Position = Module.LimitedClipEnabled and UDim2.new(1,-260,1,-110)or UDim2.new(1,-260,1,-65)\010end\010\010Mouse.Button1Down:connect(function()\010\009Down = true\010end)\010Mouse.Button1Up:connect(function()\010\009Down = false\010end)\010\010ChangeAmmoAndClip.OnClientEvent:connect(function(ChangedAmmo,ChangedClips)\010\009Ammo = ChangedAmmo\010\009Clips = ChangedClips\010\009UpdateGUI()\010end)\010Tool.Equipped:connect(function(TempMouse)\010\009Equipped = true\010\009UpdateGUI()\010\009if Module.AmmoPerClip ~= math.huge then GUI.Parent = Player.PlayerGui end\010\009TempMouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009if IdleAnim then IdleAnim:Play(nil,nil,Module.IdleAnimationSpeed) end\010\009TempMouse.KeyDown:connect(function(Key)\010\009\009if string.lower(Key) == \034r\034 then\010\009\009\009Reload()\010\009\009elseif string.lower(Key) == \034e\034 then\010\009\009\009if not Reloading and AimDown == false and Module.SniperEnabled then\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = Module.FieldOfView\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034) or Tool.ZoomGui:Clone()\010\009\009\009\009GUI.Parent = game.Players.LocalPlayer.PlayerGui]]\010\009\009\009\009GUI.Scope.Visible = true\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.LockFirstPerson\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = false\010\009\009\009\009AimDown = true\010\009\009\009\009Mouse.Icon=\034http://www.roblox.com/asset?id=187746799\034\010\009\009\009else\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009\009GUI.Scope.Visible = false\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009\009AimDown = false\010\009\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009\009end\010\009\009end\010\009end)\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010Tool.Unequipped:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010Humanoid.Died:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010\010while true do\010\009local IsChargedShot = false\010\009if Equipped and Enabled and Down and not Reloading and Ammo > 0 and Humanoid.Health > 0 then\010\009\009Enabled = false\010\009\009if Module.ChargedShotEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034ChargeSound\034) then HandleToFire.ChargeSound:Play() end\010\009\009\009wait(Module.ChargingTime)\010\009\009\009IsChargedShot = true\010\009\009end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindUp\034) then HandleToFire.WindUp:Play() end\010\009\009\009wait(Module.DelayBeforeFiring)\010\009\009end\010\009\009while Equipped and not Reloading and (Down or IsChargedShot) and Ammo > 0 and Humanoid.Health > 0 do\010\009\009\009IsChargedShot = false\010\009\009\009for i = 1,(Module.BurstFireEnabled and Module.BulletPerBurst or 1) do\010\009\009\009\009Spawn(ShakeCamera)\010\009\009\009\009for x = 1,(Module.ShotgunEnabled and Module.BulletPerShot or 1) do\010\009\009\009\009\009Fire(HandleToFire)\010\009\009\009\009end\010\009\009\009\009Ammo = Ammo - 1\010\009\009\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009\009\009UpdateGUI()\010\009\009\009\009if Module.BurstFireEnabled then wait(Module.BurstRate) end\010\009\009\009\009if Ammo <= 0 then break end\010\009\009\009end\010\009\009\009HandleToFire = (HandleToFire == Handle and Module.DualEnabled) and Handle2 or Handle\010\009\009\009wait(Module.FireRate)\010\009\009\009if not Module.Auto then break end\010\009\009end\010\009\009if HandleToFire.FireSound.IsPlaying and HandleToFire.FireSound.Looped then HandleToFire.FireSound:Stop() end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindDown\034) then HandleToFire.WindDown:Play() end\010\009\009\009wait(Module.DelayAfterFiring)\010\009\009end\010\009\009Enabled = true\010\009\009if Ammo <= 0 then Reload() end\010\009end\010\009game:GetService(\034RunService\034).RenderStepped:wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20344,class="LocalScript",parent=20341,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{32B4DB0B-ECCF-48D1-A0F5-68585B2198FE}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20550,class="LocalScript",parent=20548,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Local Gui",["ScriptGuid"]="{48C7A434-9B3C-47CE-A27F-7847284A49D2}",["Source"]="local Tool = script.Parent;\013\010\013\010enabled = true\013\010function onButton1Down(mouse)\013\010\009if not enabled then\013\010\009\009return\013\010\009end\013\010\013\010\009enabled = false\013\010\009mouse.Icon = \034rbxasset://textures\092\092GunWaitCursor.png\034\013\010\013\010\009wait(0.2)\013\010\009mouse.Icon = \034rbxasset://textures\092\092GunCursor.png\034\013\010\009enabled = true\013\010\013\010end\013\010\013\010function onEquippedLocal(mouse)\013\010\013\010\009if mouse == nil then\013\010\009\009print(\034Mouse not found\034)\013\010\009\009return \013\010\009end\013\010\013\010\009mouse.Icon = \034rbxasset://textures\092\092GunCursor.png\034\013\010\009mouse.Button1Down:connect(function() onButton1Down(mouse) end)\013\010end\013\010\013\010\013\010Tool.Equipped:connect(onEquippedLocal)\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20580,class="LocalScript",parent=20578,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Local Gui",["ScriptGuid"]="{5CF40C31-29CB-4A2B-8CC9-A19341859034}",["Source"]="local Tool = script.Parent;\013\010\013\010enabled = true\013\010function onButton1Down(mouse)\013\010\009if not enabled then\013\010\009\009return\013\010\009end\013\010\013\010\009enabled = false\013\010\009mouse.Icon = \034rbxasset://textures\092\092GunWaitCursor.png\034\013\010\013\010\009wait(0.2)\013\010\009mouse.Icon = \034rbxasset://textures\092\092GunCursor.png\034\013\010\009enabled = true\013\010\013\010end\013\010\013\010function onEquippedLocal(mouse)\013\010\013\010\009if mouse == nil then\013\010\009\009print(\034Mouse not found\034)\013\010\009\009return \013\010\009end\013\010\013\010\009mouse.Icon = \034rbxasset://textures\092\092GunCursor.png\034\013\010\009mouse.Button1Down:connect(function() onButton1Down(mouse) end)\013\010end\013\010\013\010\013\010Tool.Equipped:connect(onEquippedLocal)\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20677,class="LocalScript",parent=20670,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MouseIcon",["ScriptGuid"]="{893D32F1-C650-437D-A5B7-C39B4B318632}",["Source"]="--Made by Luckymaxer\010\010Mouse_Icon = \034rbxasset://textures/GunCursor.png\034\010Reloading_Icon = \034rbxasset://textures/GunWaitCursor.png\034\010\010Tool = script.Parent\010\010Mouse = nil\010\010function UpdateIcon()\010\009if Mouse then\010\009\009Mouse.Icon = Tool.Enabled and Mouse_Icon or Reloading_Icon\010\009end\010end\010\010function OnEquipped(ToolMouse)\010\009Mouse = ToolMouse\010\009UpdateIcon()\010end\010\010function OnChanged(Property)\010\009if Property == \034Enabled\034 then\010\009\009UpdateIcon()\010\009end\010end\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Changed:connect(OnChanged)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20678,class="LocalScript",parent=20670,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{D3291FDE-9D80-4312-A906-1FE1FBFC1ED9}",["Source"]="--Made by Luckymaxer\010\010Tool = script.Parent\010Handle = Tool:WaitForChild(\034Handle\034)\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010RunService = game:GetService(\034RunService\034)\010ContentProvider = game:GetService(\034ContentProvider\034)\010UserInputService = game:GetService(\034UserInputService\034)\010\010InputCheck = Instance.new(\034ScreenGui\034)\010InputCheck.Name = \034InputCheck\034\010InputFrame = Instance.new(\034Frame\034)\010InputFrame.Name = \034InputButton\034\010InputFrame.BackgroundTransparency = 1\010InputFrame.Size = UDim2.new(1, 0, 1, 0)\010InputFrame.Parent = InputCheck\010\010RbxUtility = LoadLibrary(\034RbxUtility\034)\010Create = RbxUtility.Create\010\010Animations = {}\010LocalObjects = {}\010\010ServerControl = Tool:WaitForChild(\034ServerControl\034)\010ClientControl = Tool:WaitForChild(\034ClientControl\034)\010\010Rate = (1 / 60)\010\010ToolEquipped = false\010\010function SetAnimation(mode, value)\010\009if not ToolEquipped or not CheckIfAlive() then\010\009\009return\010\009end\010\009if mode == \034PlayAnimation\034 and value and ToolEquipped and Humanoid then\010\009\009for i, v in pairs(Animations) do\010\009\009\009if v.Animation == value.Animation then\010\009\009\009\009v.AnimationTrack:Stop()\010\009\009\009\009table.remove(Animations, i)\010\009\009\009end\010\009\009end\010\009\009local AnimationTrack = Humanoid:LoadAnimation(value.Animation)\010\009\009table.insert(Animations, {Animation = value.Animation, AnimationTrack = AnimationTrack})\010\009\009AnimationTrack:Play(value.FadeTime, value.Weight, value.Speed)\010\009elseif mode == \034StopAnimation\034 and value then\010\009\009for i, v in pairs(Animations) do\010\009\009\009if v.Animation == value.Animation then\010\009\009\009\009v.AnimationTrack:Stop()\010\009\009\009\009table.remove(Animations, i)\010\009\009\009end\010\009\009end\010\009end\010end\010\010function CheckIfAlive()\010\009return (((Character and Character.Parent and Humanoid and Humanoid.Parent and Humanoid.Health > 0 and Player and Player.Parent) and true) or false)\010end\010\010function Equipped(Mouse)\010\009Character = Tool.Parent\010\009Player = Players:GetPlayerFromCharacter(Character)\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009ToolEquipped = true\010\009if not CheckIfAlive() then\010\009\009return\010\009end\010\009Spawn(function()\010\009\009PlayerMouse = Player:GetMouse()\010\009\009Mouse.Button1Down:connect(function()\010\009\009\009InvokeServer(\034Button1Click\034, {Down = true})\010\009\009end)\010\009\009Mouse.Button1Up:connect(function()\010\009\009\009InvokeServer(\034Button1Click\034, {Down = false})\010\009\009end)\010\009\009Mouse.KeyDown:connect(function(Key)\010\009\009\009InvokeServer(\034KeyPress\034, {Key = Key, Down = true})\010\009\009end)\010\009\009Mouse.KeyUp:connect(function(Key)\010\009\009\009InvokeServer(\034KeyPress\034, {Key = Key, Down = false})\010\009\009end)\010\009\009local PlayerGui = Player:FindFirstChild(\034PlayerGui\034)\010\009\009if PlayerGui then\010\009\009\009InputCheckClone = InputCheck:Clone()\010\009\009\009if UserInputService.TouchEnabled then\010\009\009\009\009InputCheckClone = InputCheck:Clone()\010\009\009\009\009InputCheckClone.InputButton.InputBegan:connect(function()\010\009\009\009\009\009InvokeServer(\034Button1Click\034, {Down = true})\010\009\009\009\009end)\010\009\009\009\009InputCheckClone.InputButton.InputEnded:connect(function()\010\009\009\009\009\009InvokeServer(\034Button1Click\034, {Down = false})\010\009\009\009\009end)\010\009\009\009\009InputCheckClone.Parent = PlayerGui\010\009\009\009end\010\009\009end\010\009\009for i, v in pairs(Tool:GetChildren()) do\010\009\009\009if v:IsA(\034Animation\034) then\010\009\009\009\009ContentProvider:Preload(v.AnimationId)\010\009\009\009end\010\009\009end\010\009end)\010end\010\010function Unequipped()\010\009for i, v in pairs(Animations) do\010\009\009if v and v.AnimationTrack then\010\009\009\009v.AnimationTrack:Stop()\010\009\009end\010\009end\010\009if InputCheckClone then\010\009\009Debris:AddItem(InputCheckClone, 0)\010\009end\010\009if ObjectLocalTransparencyModifier then\010\009\009ObjectLocalTransparencyModifier:disconnect()\010\009end\010\009LocalObjects = {}\010\009Animations = {}\010\009ToolEquipped = false\010end\010\010function InvokeServer(mode, value)\010\009local ServerReturn = nil\010\009pcall(function()\010\009\009ServerReturn = ServerControl:InvokeServer(mode, value)\010\009end)\010\009return ServerReturn\010end\010\010function OnClientInvoke(mode, value)\010\009if not ToolEquipped or not CheckIfAlive() then\010\009\009return\010\009end\010\009if mode == \034PlayAnimation\034 and value then\010\009\009SetAnimation(\034PlayAnimation\034, value)\010\009elseif mode == \034StopAnimation\034 and value then\010\009\009SetAnimation(\034StopAnimation\034, value)\010\009elseif mode == \034PlaySound\034 and value then\010\009\009value:Play()\010\009elseif mode == \034StopSound\034 and value then\010\009\009value:Stop()\010\009elseif mode == \034MouseData\034 then\010\009\009return ((PlayerMouse and {Position = PlayerMouse.Hit.p, Target = PlayerMouse.Target}) or nil)\010\009elseif mode == \034SetLocalTransparencyModifier\034 and value and ToolEquipped then\010\009\009pcall(function()\010\009\009\009local ObjectFound = false\010\009\009\009for i, v in pairs(LocalObjects) do\010\009\009\009\009if v == value then\010\009\009\009\009\009ObjectFound = true\010\009\009\009\009end\010\009\009\009end\010\009\009\009if not ObjectFound then\010\009\009\009\009table.insert(LocalObjects, value)\010\009\009\009\009if ObjectLocalTransparencyModifier then\010\009\009\009\009\009ObjectLocalTransparencyModifier:disconnect()\010\009\009\009\009end\010\009\009\009\009ObjectLocalTransparencyModifier = RunService.RenderStepped:connect(function()\010\009\009\009\009\009for i, v in pairs(LocalObjects) do\010\009\009\009\009\009\009if v.Object and v.Object.Parent then\010\009\009\009\009\009\009\009if ((not v.AutoUpdate and (v.Object.LocalTransparencyModifier == 1 or  v.Object.LocalTransparencyModifier == 0)) or v.AutoUpdate) then\010\009\009\009\009\009\009\009\009v.Object.LocalTransparencyModifier = v.Transparency\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009else\010\009\009\009\009\009\009\009table.remove(LocalObjects, i)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end)\010\009\009\009end\010\009\009end)\010\009end\010end\010\010ClientControl.OnClientInvoke = OnClientInvoke\010Tool.Equipped:connect(Equipped)\010Tool.Unequipped:connect(Unequipped)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20697,class="LocalScript",parent=20692,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{2E7B74B8-393A-44A7-8C96-238AD3A319F7}",["Source"]="--Made by Luckymaxer\010\010Gui = script.Parent\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010\010MainFrame = Gui:WaitForChild(\034MainFrame\034)\010Button = MainFrame:WaitForChild(\034Button\034)\010\010ServerConnection = Gui:WaitForChild(\034ServerConnection\034).Value\010Tool = Gui:WaitForChild(\034Tool\034).Value\010\010function InvokeServer(mode, value)\010\009local ServerReturn = nil\010\009pcall(function()\010\009\009ServerReturn = ServerConnection:InvokeServer(mode, value)\010\009end)\010\009return ServerReturn\010end\010\010Button.MouseButton1Click:connect(function()\010\009InvokeServer(\034KeyPress\034, {Key = \034q\034, Down = true})\010end)\010\010if Tool and Tool.Parent then\010\009Tool.Changed:connect(function(Property)\010\009\009if Property == \034Parent\034 then\010\009\009\009if not Tool.Parent or not Tool.Parent:IsA(\034Backpack\034) or not Players:GetPlayerFromCharacter(Tool.Parent) then\010\009\009\009\009Debris:AddItem(Gui, 1.5)\010\009\009\009end\010\009\009end\010\009end)\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20703,class="LocalScript",parent=20698,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Launcher",["ScriptGuid"]="{F20D40D4-2872-45D0-B9CA-56811C206CCF}",["Source"]="wait()\010-----------------\010--| Constants |--\010-----------------\010\010local GRAVITY_ACCELERATION = 196.2\010\010local RELOAD_TIME = 0.45 -- Seconds until tool can be used again\010local ROCKET_SPEED = 1 -- Speed of the projectile\010\010local MISSILE_MESH_ID = ''\010local MISSILE_TEXTURE_ID = ''\010local MISSILE_MESH_SCALE = Vector3.new(10,10,15)\010local ROCKET_PART_SIZE = Vector3.new(0,0,0)\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local MyPlayer = PlayersService.LocalPlayer\010\010local Tool = script.Parent\010local ToolHandle = Tool.Handle\010\010local RocketScript = script:WaitForChild('Rocket')\010local BoomSound = script:WaitForChild('Boom')\010local ShootSound = ToolHandle:WaitForChild('Shoot')\010\010--NOTE: We create the rocket once and then clone it when the player fires\010local Rocket = Instance.new('Part') do\010\009-- Set up the rocket part\010\009Rocket.Name = 'Rocket'\010\009Rocket.FormFactor = Enum.FormFactor.Custom --NOTE: This must be done before changing Size\010\009Rocket.Size = ROCKET_PART_SIZE\010\009Rocket.CanCollide = false\010\009Rocket.Anchored = true\010\009Rocket.Transparency = 1\010\010\009-- Add the mesh\010\009local mesh = Instance.new('SpecialMesh', Rocket)\010\009mesh.MeshId = MISSILE_MESH_ID\010\009mesh.TextureId = MISSILE_TEXTURE_ID\010\009mesh.Scale = MISSILE_MESH_SCALE\010\010\009-- Add a force to counteract gravity\010\009local bodyForce = Instance.new('BodyForce', Rocket)\010\009bodyForce.Name = 'Antigravity'\010\009bodyForce.force = Vector3.new(0, Rocket:GetMass() * GRAVITY_ACCELERATION, 0)\010\010\009-- Clone the sounds and set Boom to PlayOnRemove\010\009local boomSoundClone = BoomSound:Clone()\010\009boomSoundClone.Parent = Rocket\010\010\009-- Attach creator tags to the rocket early on\010\009local creatorTag = Instance.new('ObjectValue', Rocket)\010\009creatorTag.Value = MyPlayer\010\009creatorTag.Name = 'creator' --NOTE: Must be called 'creator' for website stats\010\009MyPlayer.Character.TEAM:Clone().Parent = Rocket\010\009local iconTag = Instance.new('StringValue', creatorTag)\010\009iconTag.Value = Tool.TextureId\010\009iconTag.Name = 'icon'\010\009\010\009local Flame1 = script.Flame1:Clone()\010\009Flame1.Enabled = true\010\009Flame1.Parent = Rocket\010\009local Flame2 = script.Flame2:Clone()\010\009Flame2.Enabled = true\010\009Flame2.Parent = Rocket\010\009local ExplosionEffect1 = script.ExplosionEffect1:Clone()\010\009ExplosionEffect1.Parent = Rocket\010\009local ExplosionEffect2 = script.ExplosionEffect2:Clone()\010\009ExplosionEffect2.Parent = Rocket\010\010\009-- Finally, clone the rocket script and enable it\010\009local rocketScriptClone = RocketScript:Clone()\010\009rocketScriptClone.Parent = Rocket\010\009rocketScriptClone.Disabled = false\010\009local rocketScriptClone2 = script.DamageTag:Clone()\010\009rocketScriptClone2.Parent = rocketScriptClone\010end\010\010-----------------\010--| Functions |--\010-----------------\010\010local function Equip(Mouse)\010\009Anim = MyPlayer.Character:FindFirstChild('Humanoid'):LoadAnimation(Tool.ShootAnim)\010\009Anim2 = MyPlayer.Character:FindFirstChild('Humanoid'):LoadAnimation(Tool.ReloadAnim)\010end\010\010local function Unequip()\010\009if Anim then Anim:Stop() end\010\009if Anim2 then Anim2:Stop() end\010end\010\010local function OnActivated()\010\009local myModel = MyPlayer.Character\010\009if Tool.Enabled and myModel and myModel:FindFirstChild('Humanoid') and myModel.Humanoid.Health > 0 then\010\009\009Tool.Enabled = false\010\009\009\010\009\009ShootSound:Play()\010\009\009if Anim then Anim:Play(nil,nil,2.5) end\010\010\009\009-- Create a clone of Rocket and set its color\010\009\009local rocketClone = Rocket:Clone()\010\009\009DebrisService:AddItem(rocketClone, 10)\010\009\009rocketClone.BrickColor = MyPlayer.TeamColor\010\010\009\009-- Position the rocket clone and launch!\010\009\009local spawnPosition = (ToolHandle.CFrame * CFrame.new(0, 0.375, -0.5)).p\010\009\009rocketClone.CFrame = CFrame.new(spawnPosition, myModel.Humanoid.TargetPoint) --NOTE: This must be done before assigning Parent\010\009\009rocketClone.Velocity = rocketClone.CFrame.lookVector * ROCKET_SPEED --NOTE: This should be done before assigning Parent\010\009\009rocketClone.Parent = game.Players.LocalPlayer.Character.Torso\010\010\009\009wait(RELOAD_TIME)\010\010\009\009Tool.Enabled = true\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Tool.Activated:connect(OnActivated)\010Tool.Equipped:connect(Equip)\010Tool.Unequipped:connect(Unequip)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20707,class="LocalScript",parent=20703,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Rocket",["ScriptGuid"]="{915C88A2-7AC7-4ECC-A61B-6FD0ADAAC286}",["Source"]="-----------------\010--| Constants |--\010-----------------\010\010local BLAST_RADIUS = 8 -- Blast radius of the explosion\010local BLAST_DAMAGE = 100 -- Amount of damage done to players\010local BLAST_FORCE = 1000 -- Amount of force applied to parts\010\010local IGNORE_LIST = {rocket = 1, handle = 1, effect = 1, water = 1} -- Rocket will fly through things named these\010--NOTE: Keys must be lowercase, values must evaluate to true\010\010Explode = Instance.new(\034Part\034)\010Explode.formFactor = \034Custom\034\010Explode.Size = Vector3.new(0,0,0)\010Explode.Anchored = true\010Explode.CanCollide = false\010Explode.TopSurface = 0\010Explode.BottomSurface = 0\010Explode.BrickColor = BrickColor.new(\034Deep orange\034)\010Mesh = Instance.new(\034SpecialMesh\034,Explode)\010Mesh.MeshType = \034Brick\034\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Rocket = script.Parent\010\010local CreatorTag = Rocket:WaitForChild('creator')\010local TEAM = Rocket:WaitForChild('TEAM')\010\010-----------------\010--| Functions |--\010-----------------\010\010function DamageTag(parent,damage)\010\009DmgTag = script.DamageTag:clone()\010\009DmgTag.Damage.Value = damage\010\009DmgTag.creator.Value = game.Players.LocalPlayer\010\009DmgTag.Disabled = false\010\009DmgTag.Parent = parent\010end\010\010function AOEDamage(pos,radius,damage)\010\009local temp = workspace:children()\010\009for i = 1,#temp do\010\009\009if temp[i] ~= script.Parent and game.Players:GetPlayerFromCharacter(temp[i]) ~= CreatorTag.Value then\010\009\009\009local human = temp[i]:findFirstChild(\034Humanoid\034)\010\009\009\009local torso = temp[i]:findFirstChild(\034Torso\034)\010\009\009\009local team = temp[i]:findFirstChild(\034TEAM\034)\010\009\009\009if human ~= nil and torso ~= nil and human.Health ~= 0 and team and team.Value ~= script.Parent.TEAM.Value then\010\009\009\009\009if (pos - torso.Position).magnitude < radius + (torso.Size.magnitude/2.5) then\010\009\009\009\009\009DamageTag(human.Parent,BLAST_DAMAGE)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010end\010\010function GetNearestTarget()\010\009local temp = workspace:children()\010\009local target\010\009local dist = 250\010\009for i = 1,#temp do\010\009\009if temp[i] ~= script.Parent and game.Players:GetPlayerFromCharacter(temp[i]) ~= CreatorTag.Value then\010\009\009\009local human = temp[i]:findFirstChild(\034Humanoid\034)\010\009\009\009local torso = temp[i]:findFirstChild(\034Torso\034)\010\009\009\009local team = temp[i]:findFirstChild(\034TEAM\034)\010\009\009\009if human ~= nil and torso ~= nil and human.Health ~= 0 and team and team.Value ~= script.Parent.TEAM.Value then\010\009\009\009\009if (Rocket.Position - torso.Position).magnitude < dist then\010\009\009\009\009\009dist = (Rocket.Position - torso.Position).magnitude\010\009\009\009\009\009target = torso\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return target\010end\010\010-- Removes any old creator tags and applies a new one to the target\010local function ApplyTags(target)\010\009while target:FindFirstChild('creator') do\010\009\009target.creator:Destroy()\010\009end\010\010\009local creatorTagClone = CreatorTag:Clone()\010\009DebrisService:AddItem(creatorTagClone, 1.5)\010\009creatorTagClone.Parent = target\010end\010\010-- Returns the ancestor that contains a Humanoid, if it exists\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009local humanoid = subject:FindFirstChild('Humanoid')\010\009\009if humanoid then\010\009\009\009return subject, humanoid\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010-- Customized explosive effect that doesn't affect teammates and only breaks joints on dead parts\010local function OnExplosionHit(hitPart, hitDistance, blastCenter)\010\009if hitPart and hitDistance then\010\009\009local character, humanoid = FindCharacterAncestor(hitPart.Parent)\010\009\009if humanoid and humanoid.Health > 0 then -- Humanoids are tagged and damaged\010\009\009\009local TEAM2 = character:FindFirstChild(\034TEAM\034)\010\009\009\009if TEAM2 and TEAM2.Value ~= TEAM.Value then\010\009\009\009\009if hitPart.Name == 'Torso' then\010\009\009\009\009\009--ApplyTags(humanoid)\010\009\009\009\009\009DamageTag(character,BLAST_DAMAGE)\010\009\009\009\009\009--humanoid:TakeDamage(BLAST_DAMAGE)\010\009\009\009\009end\010\009\009\009--end\010\009\009end\010\009end\010end\010end\010\010local function OnTouched(otherPart,RayPos)\010\009if Rocket and otherPart then\010\009\009-- Fly through anything in the ignore list\010\009\009if IGNORE_LIST[string.lower(otherPart.Name)] then\010\009\009\009return\010\009\009end\010\010\009\009local myPlayer = CreatorTag.Value\010\009\009if myPlayer then\010\009\009\009-- Fly through the creator\010\009\009\009if myPlayer.Character and myPlayer.Character:IsAncestorOf(otherPart) then\010\009\009\009\009return\010\009\009\009end\010\010\009\009\009 -- Fly through friendlies\010\009\009\009if not myPlayer.Neutral then\010\009\009\009\009local character = FindCharacterAncestor(otherPart.Parent)\010\009\009\009\009local player = PlayersService:GetPlayerFromCharacter(character)\010\009\009\009\009if player and player ~= myPlayer and player.TeamColor == Rocket.BrickColor then\010\009\009\009\009\009return\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\010\009\009-- Fly through terrain water\010\009\009if otherPart == Workspace.Terrain then\010\009\009\009--NOTE: If the rocket is large, then the simplifications made here will cause it to fly through terrain in some cases\010\009\009\009local frontOfRocket = Rocket.Position + (Rocket.CFrame.lookVector * (Rocket.Size.Z / 2))\010\009\009\009local cellLocation = Workspace.Terrain:WorldToCellPreferSolid(frontOfRocket)\010\009\009\009local cellMaterial = Workspace.Terrain:GetCell(cellLocation.X, cellLocation.Y, cellLocation.Z)\010\009\009\009if cellMaterial == Enum.CellMaterial.Water or cellMaterial == Enum.CellMaterial.Empty then\010\009\009\009\009return\010\009\009\009end\010\009\009end\010\009\009\010\009\009Rocket.Transparency = 1\010\009\009--Rocket.CFrame = CFrame.new(RayPos.X,RayPos.Y,RayPos.Z)\010\010\009\009-- Create the explosion\010\009\009--[[local explosion = Instance.new('Explosion')\010\009\009explosion.BlastPressure = 500000 -- Completely safe explosion\010\009\009explosion.BlastRadius = BLAST_RADIUS\010\009\009explosion.DestroyJointRadiusPercent = 0\010\009\009explosion.ExplosionType = Enum.ExplosionType.NoCraters\010\009\009explosion.Position = Rocket.Position\010\009\009explosion.Parent = game.Players.LocalPlayer.Character.Torso\010\010\009\009-- Connect custom logic for the explosion\010\009\009explosion.Hit:connect(function(hitPart, hitDistance) OnExplosionHit(hitPart, hitDistance, explosion.Position) end)]]\010\009\009AOEDamage(Rocket.Position,20,BLAST_DAMAGE)\010\010\009\009-- Move this script and the creator tag (so our custom logic can execute), then destroy the rocket\010\009\009CreatorTag.Parent = script\010\009\009Rocket.Flame1.Enabled = false\010\009\009Rocket.Flame2.Enabled = false\010\009\009Rocket.ExplosionEffect1:Emit(50)\010\009\009Rocket.ExplosionEffect2:Emit(50)\010\009\009Rocket.Boom:Play()\010\009\009wait(5)\010\009\009Rocket:Destroy()\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010--Rocket.Touched:connect(OnTouched)\010\010local RotSpeed = 0.01\010for i = 1,math.huge do\010\009local FrontRocket = (Rocket.CFrame * CFrame.new(0,0,-0.01)).p\010\009local BackRocket = (Rocket.CFrame * CFrame.new(0,0,0.01)).p\010\009local Target = GetNearestTarget()\010\009if Target~=nil then\010\009\009if Target then idealVelocity = --[[SPEED *]] (Target.Position - Rocket.Position).unit end\010\009\009Rocket.Velocity = --[[SPEED *]] (Rocket.Velocity + RotSpeed * (idealVelocity - Rocket.Velocity)).unit\010\009\009Rocket.CFrame = CFrame.new(Rocket.Position, Rocket.Position + Rocket.Velocity)\010\009\009if RotSpeed < 0.75 then\010\009\009\009RotSpeed = RotSpeed + 0.0075\010\009\009end\010\009end\010\009local hit,pos = raycast(Rocket.Position,((Rocket.CFrame * CFrame.new(0,0,-15)).p-Rocket.Position).unit,15)\010\009if hit then\010\009\009OnTouched(hit,pos)\010\009end\010\009Rocket.CFrame = Rocket.CFrame * CFrame.new(0,0,-7.5) * CFrame.Angles(0, 0, math.rad(18))\010\009game:GetService(\034RunService\034).RenderStepped:wait()\010\009if script.Parent == nil then break end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20713,class="LocalScript",parent=20698,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MouseIcon",["ScriptGuid"]="{07D6DDFB-286D-41C8-9F1B-94D30A207AF1}",["Source"]="local MOUSE_ICON = 'rbxasset://textures/GunCursor.png'\010local RELOADING_ICON = 'rbxasset://textures/GunWaitCursor.png'\010\010local Tool = script.Parent\010\010local Mouse = nil\010\010local function UpdateIcon()\010\009if Mouse then\010\009\009Mouse.Icon = Tool.Enabled and MOUSE_ICON or RELOADING_ICON\010\009end\010end\010\010local function OnEquipped(mouse)\010\009Mouse = mouse\010\009UpdateIcon()\010end\010\010local function OnChanged(property)\010\009if property == 'Enabled' then\010\009\009UpdateIcon()\010\009end\010end\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Changed:connect(OnChanged)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20891,class="LocalScript",parent=20885,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{9ECDDC2E-0ADC-4F3F-BD24-1B80EDB3EC25}",["Source"]="--Made by Stickmasterluke\010\010cursors={\010\034http://www.roblox.com/asset/?id=205898768\034,\009\009\009\009--red\009\009\009--change the cursors\010\034http://www.roblox.com/asset/?id=205898768\034,\009\009\009\009--blue\010\034http://www.roblox.com/asset/?id=205898768\034,\009\009\009\009--purple\010reloading=\034http://www.roblox.com/asset/?id=205898768\034,\010}\010clipsize=14\010equipped=false\010\010sp=script.Parent\010plr=game.Players.localPlayer\010ammo=sp:FindFirstChild(\034Ammo\034)\010clips=sp:FindFirstChild(\034Clips\034)\010\010while gui==nil do\010\009wait()\010\009gui=sp:FindFirstChild(\034PlasmaAssaultGui\034)\010end\010\010function updategui()\010\009if equipped then\010\009\009local plr=game.Players.localPlayer\010\009\009if plr~=nil then\010\009\009\009if ammo==nil then\010\009\009\009\009gui.Bar.GunLabel.Text=sp.Name\010\009\009\009\009gui.Bar.AmmoLabel.Text=\034\034\010\009\009\009\009gui.Bar.Fill.Size=UDim2.new(-1,0,.8,0)\010\009\009\009elseif clips==nil then\010\009\009\009\009gui.Bar.GunLabel.Text=sp.Name\010\009\009\009\009gui.Bar.AmmoLabel.Text=tostring(ammo.Value)..\034/\034..tostring(clipsize)\010\009\009\009\009gui.Bar.Fill.Size=UDim2.new(-1*ammo.Value/clipsize,0,.8,0)\010\009\009\009\009gui.Bar.Fill.Visible=true\010\009\009\009else\010\009\009\009\009gui.Bar.GunLabel.Text=sp.Name\010\009\009\009\009gui.Bar.AmmoLabel.Text=tostring(ammo.Value)..\034/\034..tostring(clipsize)..\034   \034..tostring(clips.Value)\010\009\009\009\009gui.Bar.Fill.Size=UDim2.new(-1*ammo.Value/clipsize,0,.8,0)\010\009\009\009\009gui.Bar.Fill.Visible=true\010\009\009\009end\010\009\009\009gui.Bar.Fill.BackgroundColor3=Color3.new(0,204/255,1)\010\009\009\009if sp.Reloading.Value then\010\009\009\009\009gui.Bar.AmmoLabel.Text=\034Reloading\034\010\009\009\009end\010\009\009end\010\009end\010end\010\010function onEquipped(mouse)\010\009if mouse~=nil then\010\009\009equipped=true\010\009\009local plr=game.Players.LocalPlayer\010\009\009if plr~=nil then\010\009\009\009local plrgui=plr:FindFirstChild(\034PlayerGui\034)\010\009\009\009if plrgui~=nil then\010\009\009\009\009gui.Parent=plrgui\010\009\009\009end\010\009\009\009mouse.Button1Down:connect(function()\010\009\009\009\009if not sp.Down.Value then\010\009\009\009\009\009sp.Aim.Value=mouse.Hit.p\010\009\009\009\009\009sp.Down.Value=true\010\009\009\009\009\009while sp.Down.Value do\010\009\009\009\009\009\009sp.Aim.Value=mouse.Hit.p\010\009\009\009\009\009\009wait()\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009mouse.Button1Up:connect(function()\010\009\009\009\009sp.Down.Value=false\010\009\009\009end)\010\009\009\009mouse.Icon=cursors[1]\010\009\009\009sp.Reloading.Changed:connect(function(val)\010\009\009\009\009if mouse~=nil and equipped then\010\009\009\009\009\009if val then\010\009\009\009\009\009\009mouse.Icon=cursors.reloading\010\009\009\009\009\009else\010\009\009\009\009\009\009mouse.Icon=cursors[1]\010\009\009\009\009\009end\010\009\009\009\009\009local plr=game.Players.localPlayer\010\009\009\009\009\009if plr~=nil then\010\009\009\009\009\009\009local gui=plr.PlayerGui:FindFirstChild(\034AmmoHud\034)\010\009\009\009\009\009\009if gui~=nil then\010\009\009\009\009\009\009\009updategui()\010\009\009\009\009\009\009\009if sp.Reloading.Value then\010\009\009\009\009\009\009\009\009gui.Bar.AmmoLabel.Text=\034Reloading\034\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009updategui()\010\009\009end\010\009end\010end\010\010function onUnequipped()\010\009gui.Parent=sp\010\009equipped=false\010\009local plr=game.Players.localPlayer\010\009if plr~=nil then\010\009\009local gui=plr.PlayerGui:FindFirstChild(\034AmmoHud\034)\010\009\009if gui~=nil then\010\009\009\009gui.Bar.GunLabel.Text=\034\034\010\009\009\009gui.Bar.AmmoLabel.Text=\034\034\010\009\009\009gui.Bar.Fill.Visible=false\010\009\009end\010\009end\010end\010\010sp.Equipped:connect(onEquipped)\010sp.Unequipped:connect(onUnequipped)\010\010if ammo~=nil then\010\009ammo.Changed:connect(function()\010\009\009updategui()\010\009end)\010\009if clips~=nil then\010\009\009clips.Changed:connect(function()\010\009\009\009updategui()\010\009\009end)\010\009end\010end\010\010while sp:FindFirstChild(\034Reloading\034)==nil do\010\009wait(1)\010end\010sp.Reloading.Changed:connect(function()\010\009updategui()\010end)\010\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
