34)\010\009\009if gui~=nil then\010\009\009\009gui.Bar.GunLabel.Text=\034\034\010\009\009\009gui.Bar.AmmoLabel.Text=\034\034\010\009\009\009gui.Bar.Fill.Visible=false\010\009\009end\010\009end\010end\010\010sp.Equipped:connect(onEquipped)\010sp.Unequipped:connect(onUnequipped)\010\010if ammo~=nil then\010\009ammo.Changed:connect(function()\010\009\009updategui()\010\009end)\010\009if clips~=nil then\010\009\009clips.Changed:connect(function()\010\009\009\009updategui()\010\009\009end)\010\009end\010end\010\010while sp:FindFirstChild(\034Reloading\034)==nil do\010\009wait(1)\010end\010sp.Reloading.Changed:connect(function()\010\009updategui()\010end)\010\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
