T[#T+1]={id=26215,class="LocalScript",parent=26197,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Local",["ScriptGuid"]="{0BB686CA-6A2F-4589-AB8E-9F5669EA529C}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Camera = Workspace.CurrentCamera\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local GunScript_Server = Tool:WaitForChild(\034GunScript_Server\034)\010local ChangeAmmoAndClip = GunScript_Server:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = GunScript_Server:WaitForChild(\034InflictTarget\034)\010local AmmoValue = GunScript_Server:WaitForChild(\034Ammo\034)\010local ClipsValue = GunScript_Server:WaitForChild(\034Clips\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local IdleAnim\010local FireAnim\010local ReloadAnim\010local ShotgunClipinAnim\010local Grip2\010local Handle2\010local HandleToFire = Handle\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,2)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local Equipped = false\010local Enabled = true\010local Down = false\010local Reloading = false\010local AimDown = false\010local Ammo = AmmoValue.Value\010local Clips = ClipsValue.Value\010local MaxClip = Module.MaxClip\010local PiercedHumanoid = {}\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009IdleAnim = Tool:WaitForChild(\034IdleAnim\034)\010\009IdleAnim = Humanoid:LoadAnimation(IdleAnim)\010end\010if Module.FireAnimationID ~= nil then\010\009FireAnim = Tool:WaitForChild(\034FireAnim\034)\010\009FireAnim = Humanoid:LoadAnimation(FireAnim)\010end\010if Module.ReloadAnimationID ~= nil then\010\009ReloadAnim = Tool:WaitForChild(\034ReloadAnim\034)\010\009ReloadAnim = Humanoid:LoadAnimation(ReloadAnim)\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009ShotgunClipinAnim = Tool:WaitForChild(\034ShotgunClipinAnim\034)\010\009ShotgunClipinAnim = Humanoid:LoadAnimation(ShotgunClipinAnim)\010end\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function RayCast(Start,Direction,Range,Ignore)\010\009local Hit,EndPos = game.Workspace:FindPartOnRay(Ray.new(Start,Direction*Range),Ignore)\010\009if Hit then\010\009\009if (Hit.Transparency > 0.75\010\009\009\009or Hit.Name == \034Handle\034\010\009\009\009or Hit.Name == \034Effect\034\010\009\009\009or Hit.Name == \034Bullet\034\010\009\009\009or Hit.Name == \034Laser\034\010\009\009\009or string.lower(Hit.Name) == \034water\034\010\009\009\009or Hit.Name == \034Rail\034\010\009\009\009or Hit.Name == \034Arrow\034\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent.Humanoid.Health == 0)\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent:FindFirstChild(\034TEAM\034) and TEAM and Hit.Parent.TEAM.Value == TEAM.Value))\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and PiercedHumanoid[Hit.Parent.Humanoid]) then\010\009\009\009Hit,EndPos = RayCast(EndPos+(Direction*.01),Direction,Range-((Start-EndPos).magnitude),Ignore)\010\009\009end\010\009end\010\009return Hit,EndPos\010end\010\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then ShootingHandle.FireSound:Play() end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009PiercedHumanoid[TargetHumanoid] = true\010\009\009\009\009\009end\010\009\009\009\009else\010\009\009\009\009\009PierceAvailable = 0\010\009\009\009\009end\010\009\009\009end\010\009\009else\010\009\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009\009Explosion.BlastRadius = Module.Radius\010\009\009\009Explosion.BlastPressure = 0\010\009\009\009Explosion.Position = EndPos\010\009\009\009Explosion.Parent = Workspace.CurrentCamera\010\009\009\009Explosion.Hit:connect(function(Hit)\010\009\009\009\009if Hit and Hit.Parent and Hit.Name == \034Torso\034 then\010\009\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009PierceAvailable = 0\010\009\009end\010\009\009PierceAvailable = Hit and (PierceAvailable - 1) or -1\010\009\009Player.PlayerScripts.BulletVisualizerScript.Visualize:Fire(nil,ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009false,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009game.ReplicatedStorage.VisualizeBullet:FireServer(ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009true,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009Start = EndPos + (Direction*0.01)\010\009end\010\009print(\034==========\034)\010end\010\010function Reload()\010\009if Enabled and not Reloading and (Clips > 0 or not Module.LimitedClipEnabled) and Ammo < Module.AmmoPerClip then\010\009\009Reloading = true\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009\009UpdateGUI()\010\009\009if Module.ShotgunReload then\010\009\009\009for i = 1,(Module.AmmoPerClip - Ammo) do\010\009\009\009\009if ShotgunClipinAnim then ShotgunClipinAnim:Play(nil,nil,Module.ShotgunClipinAnimationSpeed) end\010\009\009\009\009Handle.ShotgunClipin:Play()\010\009\009\009\009wait(Module.ShellClipinSpeed)\010\009\009\009end\010\009\009end\010\009\009if ReloadAnim then ReloadAnim:Play(nil,nil,Module.ReloadAnimationSpeed) end\010\009\009Handle.ReloadSound:Play()\010\009\009wait(Module.ReloadTime)\010\009\009if Module.LimitedClipEnabled then Clips = Clips - 1 end\010\009\009Ammo = Module.AmmoPerClip\010\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009Reloading = false\010\009\009UpdateGUI()\010\009end\010end\010\010function UpdateGUI()\010\009GUI.Frame.Ammo.Fill:TweenSizeAndPosition(UDim2.new(Ammo/Module.AmmoPerClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Clips.Fill:TweenSizeAndPosition(UDim2.new(Clips/Module.MaxClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Ammo.Current.Text = Ammo\010\009GUI.Frame.Ammo.Max.Text = Module.AmmoPerClip\010\009GUI.Frame.Clips.Current.Text = Clips\010\009GUI.Frame.Clips.Max.Text = Module.MaxClip\010\010\009GUI.Frame.Ammo.Current.Visible = not Reloading\010\009GUI.Frame.Ammo.Max.Visible = not Reloading\010\009GUI.Frame.Ammo.Frame.Visible = not Reloading\010\009GUI.Frame.Ammo.Reloading.Visible = Reloading\010\010\009GUI.Frame.Clips.Current.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Max.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Frame.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.NoMoreClip.Visible = (Clips <= 0)\010\009\010\009GUI.Frame.Clips.Visible = Module.LimitedClipEnabled\010\009GUI.Frame.Size = Module.LimitedClipEnabled and UDim2.new(0,250,0,100) or UDim2.new(0,250,0,55)\010\009GUI.Frame.Position = Module.LimitedClipEnabled and UDim2.new(1,-260,1,-110)or UDim2.new(1,-260,1,-65)\010end\010\010Mouse.Button1Down:connect(function()\010\009Down = true\010end)\010Mouse.Button1Up:connect(function()\010\009Down = false\010end)\010\010ChangeAmmoAndClip.OnClientEvent:connect(function(ChangedAmmo,ChangedClips)\010\009Ammo = ChangedAmmo\010\009Clips = ChangedClips\010\009UpdateGUI()\010end)\010Tool.Equipped:connect(function(TempMouse)\010\009Equipped = true\010\009UpdateGUI()\010\009if Module.AmmoPerClip ~= math.huge then GUI.Parent = Player.PlayerGui end\010\009TempMouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009if IdleAnim then IdleAnim:Play(nil,nil,Module.IdleAnimationSpeed) end\010\009TempMouse.KeyDown:connect(function(Key)\010\009\009if string.lower(Key) == \034r\034 then\010\009\009\009Reload()\010\009\009elseif string.lower(Key) == \034e\034 then\010\009\009\009if not Reloading and AimDown == false and Module.SniperEnabled then\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = Module.FieldOfView\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034) or Tool.ZoomGui:Clone()\010\009\009\009\009GUI.Parent = game.Players.LocalPlayer.PlayerGui]]\010\009\009\009\009GUI.Scope.Visible = true\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.LockFirstPerson\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = false\010\009\009\009\009AimDown = true\010\009\009\009\009Mouse.Icon=\034http://www.roblox.com/asset?id=187746799\034\010\009\009\009else\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009\009GUI.Scope.Visible = false\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009\009AimDown = false\010\009\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009\009end\010\009\009end\010\009end)\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\00