\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if ShootingHandle.FireSound.IsPlaying == false then ShootingHandle.FireSound:Play() end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then ShootingHandle.FireSound:Play() end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoi