T[#T+1]={id=26629,class="LocalScript",parent=26626,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{FA51ECCA-ECF1-4C91-AC5B-13644F5886BB}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
