T[#T+1]={id=26903,class="LocalScript",parent=26893,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Local",["ScriptGuid"]="{03D8A956-D86D-4511-B54C-0895DB375347}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Camera = Workspace.CurrentCamera\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local GunScript_Server = Tool:WaitForChild(\034GunScript_Server\034)\010local ChangeAmmoAndClip = GunScript_Server:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = GunScript_Server:WaitForChild(\034InflictTarget\034)\010local AmmoValue = GunScript_Server:WaitForChild(\034Ammo\034)\010local ClipsValue = GunScript_Server:WaitForChild(\034Clips\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local IdleAnim\010local FireAnim\010local ReloadAnim\010local ShotgunClipinAnim\010local Grip2\010local Handle2\010local HandleToFire = Handle\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,2)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local Equipped = false\010local Enabled = true\010local Down = false\010local Reloading = false\010local AimDown = false\010local Ammo = AmmoValue.Value\010local Clips = ClipsValue.Value\010local MaxClip = Module.MaxClip\010local PiercedHumanoid = {}\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009IdleAnim = Tool:WaitForChild(\034IdleAnim\034)\010\009IdleAnim = Humanoid:LoadAnimation(IdleAnim)\010end\010if Module.FireAnimationID ~= nil then\010\009FireAnim = Tool:WaitForChild(\034FireAnim\034)\010\009FireAnim = Humanoid:LoadAnimation(FireAnim)\010end\010if Module.ReloadAnimationID ~= nil then\010\009ReloadAnim = Tool:WaitForChild(\034ReloadAnim\034)\010\009ReloadAnim = Humanoid:LoadAnimation(ReloadAnim)\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009ShotgunClipinAnim = Tool:WaitForChild(\034ShotgunClipinAnim\034)\010\009ShotgunClipinAnim = Humanoid:LoadAnimation(ShotgunClipinAnim)\010end\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function RayCast(Start,Direction,Range,Ignore)\010\009local Hit,EndPos = game.Workspace:FindPartOnRay(Ray.new(Start,Direction*Range),Ignore)\010\009if Hit then\010\009\009if (Hit.Transparency > 0.75\010\009\009\009or Hit.Name == \034Handle\034\010\009\009\009or Hit.Name == \034Effect\034\010\009\009\009or Hit.Name == \034Bullet\034\010\009\009\009or Hit.Name == \034Laser\034\010\009\009\009or string.lower(Hit.Name) == \034water\034\010\009\009\009or Hit.Name == \034Rail\034\010\009\009\009or Hit.Name == \034Arrow\034\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent.Humanoid.Health == 0)\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent:FindFirstChild(\034TEAM\034) and TEAM and Hit.Parent.TEAM.Value == TEAM.Value))\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and PiercedHumanoid[Hit.Parent.Humanoid]) then\010\009\009\009Hit,EndPos = RayCast(EndPos+(Direction*.01),Direction,Range-((Start-EndPos).magnitude),Ignore)\010\009\009end\010\009end\010\009return Hit,EndPos\010end\010\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then ShootingHandle.FireSound:Play() end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009PiercedHumanoid[TargetHumanoid] = true\010\009\009\009\009\009end\010\009\009\009\009else\010\009\009\009\009\009PierceAvailable = 0\010\009\009\009\009end\010\009\009\009end\010\009\009else\010\009\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009\009Explosion.BlastRadius = Module.Radius\010\009\009\009Explosion.BlastPressure = 0\010\009\009\009Explosion.Position = EndPos\010\009\009\009Explosion.Parent = Workspace.CurrentCamera\010\009\009\009Explosion.Hit:connect(function(Hit)\010\009\009\009\009if Hit and Hit.Parent and Hit.Name == \034Torso\034 then\010\009\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\0