tedClipEnabled then Clips = Clips - 1 end\010\009\009Ammo = Module.AmmoPerClip\010\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009Reloading = false\010\009\009UpdateGUI()\010\009end\010end\010\010function UpdateGUI()\010\009GUI.Frame.Ammo.Fill:TweenSizeAndPosition(UDim2.new(Ammo/Module.AmmoPerClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Clips.Fill:TweenSizeAndPosition(UDim2.new(Clips/Module.MaxClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Ammo.Current.Text = Ammo\010\009GUI.Frame.Ammo.Max.Text = Module.AmmoPerClip\010\009GUI.Frame.Clips.Current.Text = Clips\010\009GUI.Frame.Clips.Max.Text = Module.MaxClip\010\010\009GUI.Frame.Ammo.Current.Visible = not Reloading\010\009GUI.Frame.Ammo.Max.Visible = not Reloading\010\009GUI.Frame.Ammo.Frame.Visible = not Reloading\010\009GUI.Frame.Ammo.Reloading.Visible = Reloading\010\010\009GUI.Frame.Clips.Current.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Max.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Frame.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.NoMoreClip.Visible = (Clips <= 0)\010\009\010\009GUI.Frame.Clips.Visible = Module.LimitedClipEnabled\010\009GUI.Frame.Size = Module.LimitedClipEnabled and UDim2.new(0,250,0,100) or UDim2.new(0,250,0,55)\010\009GUI.Frame.Position = Module.LimitedClipEnabled and UDim2.new(1,-260,1,-110)or UDim2.new(1,-260,1,-65)\010end\010\010Mouse.Button1Down:connect(function()\010\009Down = true\010end)\010Mouse.Button1Up:connect(function()\010\009Down = false\010end)\010\010ChangeAmmoAndClip.OnClientEvent:connect(function(ChangedAmmo,ChangedClips)\010\009Ammo = ChangedAmmo\010\009Clips = ChangedClips\010\009UpdateGUI()\010end)\010Tool.Equipped:connect(function(TempMouse)\010\009Equipped = true\010\009UpdateGUI()\010\009if Module.AmmoPerClip ~= math.huge then GUI.Parent = Player.PlayerGui end\010\009TempMouse.Icon = \034rbxassetid://\034..M