T[#T+1]={id=27616,class="LocalScript",parent=27613,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{B04F92BF-E88F-4BEE-83D8-E9064C8C28E3}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27654,class="LocalScript",parent=27648,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MouseIcon",["ScriptGuid"]="{B0AE2C14-424A-416A-8158-D270FBEE25F1}",["Source"]="local MOUSE_ICON = 'rbxasset://textures/GunCursor.png'\010local RELOADING_ICON = 'rbxasset://textures/GunWaitCursor.png'\010\010local Tool = script.Parent\010\010local Mouse = nil\010\010local function UpdateIcon()\010\009if Mouse then\010\009\009Mouse.Icon = Tool.Enabled and MOUSE_ICON or RELOADING_ICON\010\009end\010end\010\010local function OnEquipped(mouse)\010\009Mouse = mouse\010\009UpdateIcon()\010end\010\010local function OnChanged(property)\010\009if property == 'Enabled' then\010\009\009UpdateIcon()\010\009end\010end\010\010Tool.Equipped:connect(OnEquipped)\010Tool.Changed:connect(OnChanged)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27655,class="LocalScript",parent=27648,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Launcher",["ScriptGuid"]="{75E35A5C-8A85-4C47-A867-27F630467218}",["Source"]="wait()\010-----------------\010--| Constants |--\010-----------------\010\010local GRAVITY_ACCELERATION = 196.2\010\010local RELOAD_TIME = 0.75 -- Seconds until tool can be used again\010local ROCKET_SPEED = 0 -- Speed of the projectile\010\010local MISSILE_MESH_ID = 'http://www.roblox.com/asset/?id=90780672'\010local MISSILE_TEXTURE_ID = 'http://www.roblox.com/asset/?id=90780623'\010local MISSILE_MESH_SCALE = Vector3.new(10,10,15)\010local ROCKET_PART_SIZE = Vector3.new(1.2, 1.2, 3.27)\010local Player = game.Players.LocalPlayer\010local TEAM = Player.Character:WaitForChild(\034TEAM\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local Humanoid = Player.Character:WaitForChild(\034Humanoid\034)\010local Reloading = false\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local MyPlayer = PlayersService.LocalPlayer\010\010local Tool = script.Parent\010local ToolHandle = Tool.Handle\010\010local Clip = Tool:WaitForChild('Clip')\010local ShootSound = ToolHandle:WaitForChild('Shoot')\010local ReloadSound = ToolHandle:WaitForChild('Reload')\010\010-----------------\010--| Functions |--\010-----------------\010\010function UpdateGUI()\010\009local LimitedClipEnabled = false\010\009\010\009local Clips = 4\010\009\010\009local MaxClip = 4\010\009\010\009GUI.Frame.Ammo.Fill:TweenSizeAndPosition(UDim2.new(Clip.Value/Clip.MaxValue,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Clips.Fill:TweenSizeAndPosition(UDim2.new(Clip.Value/Clip.MaxValue,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Ammo.Current.Text = script.Parent.Clip.Value\010\009GUI.Frame.Ammo.Max.Text = script.Parent.Clip.MaxValue\010\009GUI.Frame.Clips.Current.Text = Clips\010\009GUI.Frame.Clips.Max.Text = MaxClip\010\010\009GUI.Frame.Ammo.Current.Visible = not Reloading\010\009GUI.Frame.Ammo.Max.Visible = not Reloading\010\009GUI.Frame.Ammo.Frame.Visible = not Reloading\010\009GUI.Frame.Ammo.Reloading.Visible = Reloading\010\010\009GUI.Frame.Clips.Current.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Max.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Frame.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.NoMoreClip.Visible = (Clips <= 0)\010\009\010\009GUI.Frame.Clips.Visible = LimitedClipEnabled\010\009GUI.Frame.Size = LimitedClipEnabled and UDim2.new(0,250,0,100) or UDim2.new(0,250,0,55)\010\009GUI.Frame.Position = LimitedClipEnabled and UDim2.new(1,-260,1,-110)or UDim2.new(1,-260,1,-65)\010end\010\010\010local function Reload()\010\009while Clip.Value ~= Clip.MaxValue do\010\009\009ReloadSound:Play()\010\009\009Reloading = true\010\009\009UpdateGUI()\010\009\009if Anim2 then script.Parent.AnimEvent:FireServer(Tool.ReloadAnim,1) end\010\009\009wait(0.75)\010\009\009Clip.Value = Clip.Value + 1\010\009end\010\009Reloading = false\010\009UpdateGUI()\010end\010\010local function Equip(Mouse)\010\009GUI.Parent = Player.PlayerGui\010\009UpdateGUI()\010\009if Mouse then\010\009\009Mouse.KeyDown:connect(function(Key)\010\009\009\009if string.lower(Key) == \034r\034 then\010\009\009\009\009if Tool.Enabled then\010\009\009\009\009\009Tool.Enabled = false\010\009\009\009\009\009Reload()\010\009\009\009\009\009Tool.Enabled = true\010\009\009\009\009end\010\009\009\009end\010\009\009end)\010\009end\010\009Anim = MyPlayer.Character:FindFirstChild('Humanoid'):LoadAnimation(Tool.ShootAnim)\010\009Anim2 = MyPlayer.Character:FindFirstChild('Humanoid'):LoadAnimation(Tool.ReloadAnim)\010end\010\010local function Unequip()\010\009GUI.Parent = script\010\009UpdateGUI()\010\009if Anim then Anim:Stop() end\010\009if Anim2 then Anim2:Stop() end\010end\010\010local function OnActivated()\010\009local myModel = MyPlayer.Character\010\009if Tool.Enabled and myModel and myModel:FindFirstChild('Humanoid') and myModel.Humanoid.Health > 0 then\010\009\009script.Parent.FireEvent:FireServer(myModel.Humanoid.TargetPoint,TEAM)\010\009\009Tool.Enabled = false\010\009\009\010\009\009--[[ShootSound:Play()\010\009\009if Anim then Anim:Play(nil,nil,2.5) end\010\010\009\009-- Create a clone of Rocket and set its color\010\009\009local rocketClone = Rocket:Clone()\010\009\009DebrisService:AddItem(rocketClone, 30)\010\009\009rocketClone.BrickColor = MyPlayer.TeamColor\010\010\009\009-- Position the rocket clone and launch!\010\009\009local spawnPosition = (ToolHandle.CFrame * CFrame.new(0, 0, -3)).p\010\009\009rocketClone.CFrame = CFrame.new(spawnPosition, myModel.Humanoid.TargetPoint) --NOTE: This must be done before assigning Parent\010\009\009rocketClone.Velocity = rocketClone.CFrame.lookVector * ROCKET_SPEED --NOTE: This should be done before assigning Parent\010\009\009rocketClone.Parent = game.Players.LocalPlayer.Character.Torso]]\010\010\009\009Clip.Value = Clip.Value - 1\010\009\009UpdateGUI()\010\009\009wait(RELOAD_TIME)\010\009\009if Clip.Value == 0 then\010\009\009\009Reload()\010\009\009end\010\010\009\009Tool.Enabled = true\010\009end\010end\010\010Humanoid.Died:connect(function()\010\009GUI.Parent = script\010end)\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Tool.Activated:connect(OnActivated) --when u click it activte the thing\010Tool.Equipped:connect(Equip)\010Tool.Unequipped:connect(Unequip)\010",["SourceAssetId"]=-1,["Tags"]=""}}
