cal IsChargedShot = false\010\009if Equipped and Enabled and Down and not Reloading and Ammo > 0 and Humanoid.Health > 0 then\010\009\009Enabled = false\010\009\009if Module.ChargedShotEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034ChargeSound\034) then HandleToFire.ChargeSound:Play() end\010\009\009\009wait(Module.ChargingTime)\010\009\009\009IsChargedShot = true\010\009\009end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindUp\034) then HandleToFire.WindUp:Play() end\010\009\009\009wait(Module.DelayBeforeFiring)\010\009\009end\010\009\009while Equipped and not Reloading and (Down or IsChargedShot) and Ammo > 0 and Humanoid.Health > 0 do\010\009\009\009IsChargedShot = false\010\009\009\009for i = 1,(Module.BurstFireEnabled and Module.BulletPerBurst or 1) do\010\009\009\009\009Spawn(ShakeCamera)\010\009\009\009\009for x = 1,(Module.ShotgunEnabled and Module.BulletPerShot or 1) do\010\009\009\009\009\009Fire(HandleToFire)\010\009\009\009\009end\010\009\009\009\009Ammo = Ammo - 1\010\009\009\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009\009\009UpdateGUI()\010\009\009\009\009if Module.BurstFireEnabled then wait(Module.BurstRate) end\010\009\009\009\009if Ammo <= 0 then break end\010\009\009\009end\010\009\009\009HandleToFire = (HandleToFire == Handle and Module.DualEnabled) and Handle2 or Handle\010\009\009\009wait(Module.FireRate)\010\009\009\009if not Module.Auto then break end\010\009\009end\010\009\009if HandleToFire.FireSound.IsPlaying and HandleToFire.FireSound.Looped then HandleToFire.FireSound:Stop() end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindDown\034) then HandleToFire.WindDown:Play() end\010\009\009\009wait(Module.DelayAfterFiring)\010\009\009end\010\009\009Enabled = true\010\009\009if Ammo <= 0 then Reload() end\010\009end\010\009game:GetService(\034RunService\034).RenderStepped:wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27760,class="LocalScript",parent=27757,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{870DD5F7-F568-40AF-8EA0-5662C8FDAE6A}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27802,class="LocalScript",parent=27792,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Local",["ScriptGuid"]="{81B5FD7A-7883-48A8-A5E8-847B213BC16C}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Camera = Workspace.CurrentCamera\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local GunScript_Server = Tool:WaitForChild(\034GunScript_Server\034)\010local ChangeAmmoAndClip = GunScript_Server:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = GunScript_Server:WaitForChild(\034InflictTarget\034)\010local AmmoValue = GunScript_Server:WaitForChild(\034Ammo\034)\010local ClipsValue = GunScript_Server:WaitForChild(\034Clips\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local IdleAnim\010local FireAnim\010local ReloadAnim\010local ShotgunClipinAnim\010local Grip2\010local Handle2\010local HandleToFire = Handle\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,2)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local Equipped = false\010local Enabled = true\010local Down = false\010local Reloading = false\010local AimDown = false\010local Ammo = AmmoValue.Value\010local Clips = ClipsValue.Value\010local MaxClip = Module.MaxClip\010local PiercedHumanoid = {}\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009IdleAnim = Tool:WaitForChild(\034IdleAnim\034)\010\009IdleAnim = Humanoid:LoadAnimation(IdleAnim)\010end\010if Module.FireAnimationID ~= nil then\010\009FireAnim = Tool:WaitForChild(\034FireAnim\034)\010\009FireAnim = Humanoid:LoadAnimation(FireAnim)\010end\010if Module.ReloadAnimationID ~= nil then\010\009ReloadAnim = Tool:WaitForChild(\034ReloadAnim\034)\010\009ReloadAnim = Humanoid:LoadAnimation(ReloadAnim)\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009ShotgunClipinAnim = Tool:WaitForChild(\034ShotgunClipinAnim\034)\010\009ShotgunClipinAnim = Humanoid:LoadAnimation(ShotgunClipinAnim)\010end\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function RayCast(Start,Direction,Range,Ignore)\010\009local Hit,EndPos = game.Workspace:FindPartOnRay(Ray.new(Start,Direction*Range),Ignore)\010\009if Hit then\010\009\009if (Hit.Transparency > 0.75\010\009\009\009or Hit.Name == \034Handle\034\010\009\009\009or Hit.Name == \034Effect\034\010\009\009\009or Hit.Name == \034Bullet\034\010\009\009\009or Hit.Name == \034Laser\034\010\009\009\009or string.lower(Hit.Name) == \034water\034\010\009\009\009or Hit.Name == \034Rail\034\010\009\009\009or Hit.Name == \034Arrow\034\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent.Humanoid.Health == 0)\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent:FindFirstChild(\034TEAM\034) and TEAM and Hit.Parent.TEAM.Value == TEAM.Value))\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and PiercedHumanoid[Hit.Parent.Humanoid]) then\010\009\009\009Hit,EndPos = RayCast(EndPos+(Direction*.01),Direction,Range-((Start-EndPos).magnitude),Ignore)\010\009\009end\010\009end\010\009return Hit,EndPos\010end\010\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then ShootingHandle.FireSound:Play() end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009PiercedHumanoid[TargetHumanoid] = true\010\009\009\009\009\009end\010\009\009\009\009else\010\009\009\009\009\009PierceAvailable = 0\010\009\009\009\009end\010\009\009\009end\010\009\009else\010\009\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009\009Explosion.BlastRadius = Module.Radius\010\009\009\009Explosion.BlastPressure = 0\010\009\009\009Explosion.Position = EndPos\010\009\009\009Explosion.Parent = Workspace.CurrentCamera\010\009\009\009Explosion.Hit:connect(function(Hit)\010\009\009\009\009if Hit and Hit.Parent and Hit.Name == \034Torso\034 then\010\009\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009PierceAvailable = 0\010\009\009end\010\009\009PierceAvailable = Hit and (PierceAvailable - 1) or -1\010\009\009Player.PlayerScripts.BulletVisualizerScript.Visualize:Fire(nil,ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009false,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009game.ReplicatedStorage.VisualizeBullet:FireServer(ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009true,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009Start = EndPos + (Direction*0.01)\010\009end\010\009print(\034==========\034)\010end\010\010function Reload()\010\009if Enabled and not Reloading and (Clips > 0 or not Module.LimitedClipEnabled) and Ammo < Module.AmmoPerClip then\010\009\009Reloading = true\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009\009UpdateGUI()\010\009\009if Module.ShotgunReload then\010\009\009\009for i = 1,(Module.AmmoPerClip - Ammo) do\010\009\009\009\009if ShotgunClipinAnim then ShotgunClipinAnim:Play(nil,nil,Module.ShotgunClipinAnimationSpeed) end\010\009\009\009\009Handle.ShotgunClipin:Play()\010\009\009\009\009wait(Module.ShellClipinSpeed)\010\009\009\009end\010\009\009end\010\009\009if ReloadAnim then ReloadAnim:Play(nil,nil,Module.ReloadAnimationSpeed) end\010\009\009Handle.ReloadSound:Play()\010\009\009wait(Module.ReloadTime)\010\009\009if Module.LimitedClipEnabled then Clips = Clips - 1 end\010\009\009Ammo = Module.AmmoPerClip\010\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009Reloading = false\010\009\009UpdateGUI()\010\009end\010end\010\010function UpdateGUI()\010\009GUI.Frame.Ammo.Fill:TweenSizeAndPosition(UDim2.new(Ammo/Module.AmmoPerClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Clips.Fill:TweenSizeAndPosition(UDim2.new(Clips/Module.MaxClip,0,1,0), UDim2.new(0,0,0,0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)\010\009GUI.Frame.Ammo.Current.Text = Ammo\010\009GUI.Frame.Ammo.Max.Text = Module.AmmoPerClip\010\009GUI.Frame.Clips.Current.Text = Clips\010\009GUI.Frame.Clips.Max.Text = Module.MaxClip\010\010\009GUI.Frame.Ammo.Current.Visible = not Reloading\010\009GUI.Frame.Ammo.Max.Visible = not Reloading\010\009GUI.Frame.Ammo.Frame.Visible = not Reloading\010\009GUI.Frame.Ammo.Reloading.Visible = Reloading\010\010\009GUI.Frame.Clips.Current.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Max.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.Frame.Visible = not (Clips <= 0)\010\009GUI.Frame.Clips.NoMoreClip.Visible = (Clips <= 0)\010\009\010\009GUI.Frame.Clips.Visible = Module.LimitedClipEnabled\010\009GUI.Frame.Size = Module.LimitedClipEnabled and UDim2.new(0,250,0,100) or UDim2.new(0,250,0,55)\010\009GUI.Frame.Position = Module.LimitedClipEnabled and UDim2.new(1,-260,1,-110)or UDim2.new(1,-260,1,-65)\010end\010\010Mouse.Button1Down:connect(function()\010\009Down = true\010end)\010Mouse.Button1Up:connect(function()\010\009Down = false\010end)\010\010ChangeAmmoAndClip.OnClientEvent:connect(function(ChangedAmmo,ChangedClips)\010\009Ammo = ChangedAmmo\010\009Clips = ChangedClips\010\009UpdateGUI()\010end)\010Tool.Equipped:connect(function(TempMouse)\010\009Equipped = true\010\009UpdateGUI()\010\009if Module.AmmoPerClip ~= math.huge then GUI.Parent = Player.PlayerGui end\010\009TempMouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009if IdleAnim then IdleAnim:Play(nil,nil,Module.IdleAnimationSpeed) end\010\009TempMouse.KeyDown:connect(function(Key)\010\009\009if string.lower(Key) == \034r\034 then\010\009\009\009Reload()\010\009\009elseif string.lower(Key) == \034e\034 then\010\009\009\009if not Reloading and AimDown == false and Module.SniperEnabled then\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = Module.FieldOfView\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034) or Tool.ZoomGui:Clone()\010\009\009\009\009GUI.Parent = game.Players.LocalPlayer.PlayerGui]]\010\009\009\009\009GUI.Scope.Visible = true\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.LockFirstPerson\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = false\010\009\009\009\009AimDown = true\010\009\009\009\009Mouse.Icon=\034http://www.roblox.com/asset?id=187746799\034\010\009\009\009else\010\009\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009\009GUI.Scope.Visible = false\010\009\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009\009AimDown = false\010\009\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009\009end\010\009\009end\010\009end)\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010Tool.Unequipped:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010Humanoid.Died:connect(function()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010\010while true do\010\009local IsChargedShot = false\010\009if Equipped and Enabled and Down and not Reloading and Ammo > 0 and Humanoid.Health > 0 then\010\009\009Enabled = false\010\009\009if Module.ChargedShotEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034ChargeSound\034) then HandleToFire.ChargeSound:Play() end\010\009\009\009wait(Module.ChargingTime)\010\009\009\009IsChargedShot = true\010\009\009end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindUp\034) then HandleToFire.WindUp:Play() end\010\009\009\009wait(Module.DelayBeforeFiring)\010\009\009end\010\009\009while Equipped and not Reloading and (Down or IsChargedShot) and Ammo > 0 and Humanoid.Health > 0 do\010\009\009\009IsChargedShot = false\010\009\009\009for i = 1,(Module.BurstFireEnabled and Module.BulletPerBurst or 1) do\010\009\009\009\009Spawn(ShakeCamera)\010\009\009\009\009for x = 1,(Module.ShotgunEnabled and Module.BulletPerShot or 1) do\010\009\009\009\009\009Fire(HandleToFire)\010\009\009\009\009end\010\009\009\009\009Ammo = Ammo - 1\010\009\009\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009\009\009UpdateGUI()\010\009\009\009\009if Module.BurstFireEnabled then wait(Module.BurstRate) end\010\009\009\009\009if Ammo <= 0 then break end\010\009\009\009end\010\009\009\009HandleToFire = (HandleToFire == Handle and Module.DualEnabled) and Handle2 or Handle\010\009\009\009wait(Module.FireRate)\010\009\009\009if not Module.Auto then break end\010\009\009end\010\009\009if HandleToFire.FireSound.IsPlaying and HandleToFire.FireSound.Looped then HandleToFire.FireSound:Stop() end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindDown\034) then HandleToFire.WindDown:Play() end\010\009\009\009wait(Module.DelayAfterFiring)\010\009\009end\010\009\009Enabled = true\010\009\009if Ammo <= 0 then Reload() end\010\009end\010\009game:GetService(\034RunService\034).RenderStepped:wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27803,class="LocalScript",parent=27802,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{09754110-2B52-4434-8592-2B22A480E40F}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28036,class="LocalScript",parent=28030,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="LocalScript",["ScriptGuid"]="{6300E65F-EC07-424A-9335-D793E79A9C90}",["Source"]="--Made by Stickmasterluke\010\010cursors={\010\034http://www.roblox.com/asset/?id=205898768\034,\009\009\009\009--red\009\009\009--change the cursors\010\034http://www.roblox.com/asset/?id=205898768\034,\009\009\009\009--blue\010\034http://www.roblox.com/asset/?id=205898768\034,\009\009\009\009--purple\010reloading=\034http://www.roblox.com/asset/?id=205898768\034,\010}\010clipsize=14\010equipped=false\010\010sp=script.Parent\010plr=game.Players.localPlayer\010ammo=sp:FindFirstChild(\034Ammo\034)\010clips=sp:FindFirstChild(\034Clips\034)\010\010while gui==nil do\010\009wait()\010\009gui=sp:FindFirstChild(\034PlasmaAssaultGui\034)\010end\010\010function updategui()\010\009if equipped then\010\009\009local plr=game.Players.localPlayer\010\009\009if plr~=nil then\010\009\009\009if ammo==nil then\010\009\009\009\009gui.Bar.GunLabel.Text=sp.Name\010\009\009\009\009gui.Bar.AmmoLabel.Text=\034\034\010\009\009\009\009gui.Bar.Fill.Size=UDim2.new(-1,0,.8,0)\010\009\009\009elseif clips==nil then\010\009\009\009\009gui.Bar.GunLabel.Text=sp.Name\010\009\009\009\009gui.Bar.AmmoLabel.Text=tostring(ammo.Value)..\034/\034..tostring(clipsize)\010\009\009\009\009gui.Bar.Fill.Size=UDim2.new(-1*ammo.Value/clipsize,0,.8,0)\010\009\009\009\009gui.Bar.Fill.Visible=true\010\009\009\009else\010\009\009\009\009gui.Bar.GunLabel.Text=sp.Name\010\009\009\009\009gui.Bar.AmmoLabel.Text=tostring(ammo.Value)..\034/\034..tostring(clipsize)..\034   \034..tostring(clips.Value)\010\009\009\009\009gui.Bar.Fill.Size=UDim2.new(-1*ammo.Value/clipsize,0,.8,0)\010\009\009\009\009gui.Bar.Fill.Visible=true\010\009\009\009end\010\009\009\009gui.Bar.Fill.BackgroundColor3=Color3.new(0,204/255,1)\010\009\009\009if sp.Reloading.Value then\010\009\009\009\009gui.Bar.AmmoLabel.Text=\034Reloading\034\010\009\009\009end\010\009\009end\010\009end\010end\010\010function onEquipped(mouse)\010\009if mouse~=nil then\010\009\009equipped=true\010\009\009local plr=game.Players.LocalPlayer\010\009\009if plr~=nil then\010\009\009\009local plrgui=plr:FindFirstChild(\034PlayerGui\034)\010\009\009\009if plrgui~=nil then\010\009\009\009\009gui.Parent=plrgui\010\009\009\009end\010\009\009\009mouse.Button1Down:connect(function()\010\009\009\009\009if not sp.Down.Value then\010\009\009\009\009\009sp.Aim.Value=mouse.Hit.p\010\009\009\009\009\009sp.Down.Value=true\010\009\009\009\009\009while sp.Down.Value do\010\009\009\009\009\009\009sp.Aim.Value=mouse.Hit.p\010\009\009\009\009\009\009wait()\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009mouse.Button1Up:connect(function()\010\009\009\009\009sp.Down.Value=false\010\009\009\009end)\010\009\009\009mouse.Icon=cursors[1]\010\009\009\009sp.Reloading.Changed:connect(function(val)\010\009\009\009\009if mouse~=nil and equipped then\010\009\009\009\009\009if val then\010\009\009\009\009\009\009mouse.Icon=cursors.reloading\010\009\009\009\009\009else\010\009\009\009\009\009\009mouse.Icon=cursors[1]\010\009\009\009\009\009end\010\009\009\009\009\009local plr=game.Players.localPlayer\010\009\009\009\009\009if plr~=nil then\010\009\009\009\009\009\009local gui=plr.PlayerGui:FindFirstChild(\034AmmoHud\034)\010\009\009\009\009\009\009if gui~=nil then\010\009\009\009\009\009\009\009updategui()\010\009\009\009\009\009\009\009if sp.Reloading.Value then\010\009\009\009\009\009\009\009\009gui.Bar.AmmoLabel.Text=\034Reloading\034\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009updategui()\010\009\009end\010\009end\010end\010\010function onUnequipped()\010\009gui.Parent=sp\010\009equipped=false\010\009local plr=game.Players.localPlayer\010\009if plr~=nil then\010\009\009local gui=plr.PlayerGui:FindFirstChild(\034AmmoHud\034)\010\009\009if gui~=nil then\010\009\009\009gui.Bar.GunLabel.Text=\034\034\010\009\009\009gui.Bar.AmmoLabel.Text=\034\034\010\009\009\009gui.Bar.Fill.Visible=false\010\009\009end\010\009end\010end\010\010sp.Equipped:connect(onEquipped)\010sp.Unequipped:connect(onUnequipped)\010\010if ammo~=nil then\010\009ammo.Changed:connect(function()\010\009\009updategui()\010\009end)\010\009if clips~=nil then\010\009\009clips.Changed:connect(function()\010\009\009\009updategui()\010\009\009end)\010\009end\010end\010\010while sp:FindFirstChild(\034Reloading\034)==nil do\010\009wait(1)\010end\010sp.Reloading.Changed:connect(function()\010\009updategui()\010end)\010\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28209,class="LocalScript",parent=28195,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Client",["ScriptGuid"]="{4D1EDD48-11F3-4B45-9226-64B57390E8E2}",["Source"]="local Player = game:GetService(\034Players\034).LocalPlayer\010while not Player.Character do wait() end\010local Character = Player.Character\010local Human = Character:WaitForChild(\034Humanoid\034)\010\010local CAS = game:GetService(\034ContextActionService\034)\010local ActionName = \034GiantAngelicSword\034\010\010local Tool = script.Parent\010local Remote = Tool:WaitForChild(\034Remote\034)\010\010local Animations = {\010\009Hold = Tool:WaitForChild(\034Hold\034),\010\009Slam = Tool:WaitForChild(\034Slam\034),\010\009SwingRightToLeft = Tool:WaitForChild(\034SwingRightToLeft\034),\010\009SwingLeftToRight = Tool:WaitForChild(\034SwingLeftToRight\034),\010}\010local HoldTrack\010\010function playAnimation(name, fade, weight, speed)\010\009if Animations[name] then\010\009\009local track = Human:LoadAnimation(Animations[name])\010\009\009track:Play(fade, weight, speed)\010\009end\010end\010\010function onAction(actionName, inputState, inputObject)\010\009if inputState == Enum.UserInputState.Begin then\010\009\009Remote:FireServer(\034Attack\034)\010\009end\010end\010\010function onEquipped()\010\009--ensure unequip\010\009onUnequipped()\010\009\010\009--animate\010\009HoldTrack = Human:LoadAnimation(Animations.Hold)\010\009HoldTrack:Play(0.5)\010\009\010\009--bind actions\010\009CAS:BindActionToInputTypes(\010\009\009ActionName,\010\009\009onAction,\010\009\009false,\010\009\009Enum.UserInputType.MouseButton1,\010\009\009Enum.UserInputType.Touch\010\009)\010end\010\010function onUnequipped()\010\009--unbind\010\009CAS:UnbindAction(ActionName)\010\009\010\009--stop animation\010\009if HoldTrack then\010\009\009HoldTrack:Stop()\010\009end\010end\010\010function onRemote(func, ...)\010\009if func == \034PlayAnimation\034 then\010\009\009playAnimation(...)\010\009end\010end\010\010--set up events\010Tool.Equipped:connect(onEquipped)\010Tool.Unequipped:connect(onUnequipped)\010Remote.OnClientEvent:connect(onRemote)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28601,class="LocalScript",parent=28591,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Local",["ScriptGuid"]="{01FD856C-80B3-4337-9CA8-A048D9DD889D}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Camera = Workspace.CurrentCamera\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local GunScript_Server = Tool:WaitForChild(\034GunScript_Server\034)\010local ChangeAmmoAndClip = GunScript_Server:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = GunScript_Server:WaitForChild(\034InflictTarget\034)\010local AmmoValue = GunScript_Server:WaitForChild(\034Ammo\034)\010local ClipsValue = GunScript_Server:WaitForChild(\034Clips\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local IdleAnim\010local FireAnim\010local ReloadAnim\010local ShotgunClipinAnim\010local Grip2\010local Handle2\010local HandleToFire = Handle\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,2)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local Equipped = false\010local Enabled = true\010local Down = false\010local Reloading = false\010local AimDown = false\010local Ammo = AmmoValue.Value\010local Clips = ClipsValue.Value\010local MaxClip = Module.MaxClip\010local PiercedHumanoid = {}\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009IdleAnim = Tool:WaitForChild(\034IdleAnim\034)\010\009IdleAnim = Humanoid:LoadAnimation(IdleAnim)\010end\010if Module.FireAnimationID ~= nil then\010\009FireAnim = Tool:WaitForChild(\034FireAnim\034)\010\009FireAnim = Humanoid:LoadAnimation(FireAnim)\010end\010if Module.ReloadAnimationID ~= nil then\010\009ReloadAnim = Tool:WaitForChild(\034ReloadAnim\034)\010\009ReloadAnim = Humanoid:LoadAnimation(ReloadAnim)\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009ShotgunClipinAnim = Tool:WaitForChild(\034ShotgunClipinAnim\034)\010\009ShotgunClipinAnim = Humanoid:LoadAnimation(ShotgunClipinAnim)\010end\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function RayCast(Start,Direction,Range,Ignore)\010\009local Hit,EndPos = game.Workspace:FindPartOnRay(Ray.new(Start,Direction*Range),Ignore)\010\009if Hit then\010\009\009if (Hit.Transparency > 0.75\010\009\009\009or Hit.Name == \034Handle\034\010\009\009\009or Hit.Name == \034Effect\034\010\009\009\009or Hit.Name == \034Bullet\034\010\009\009\009or Hit.Name == \034Laser\034\010\009\009\009or string.lower(Hit.Name) == \034water\034\010\009\009\009or Hit.Name == \034Rail\034\010\009\009\009or Hit.Name == \034Arrow\034\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent.Humanoid.Health == 0)\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent:FindFirstChild(\034TEAM\034) and TEAM and Hit.Parent.TEAM.Value == TEAM.Value))\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and PiercedHumanoid[Hit.Parent.Humanoid]) then\010\009\009\009Hit,EndPos = RayCast(EndPos+(Direction*.01),Direction,Range-((Start-EndPos).magnitude),Ignore)\010\009\009end\010\009end\010\009return Hit,EndPos\010end\010\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if ShootingHandle.FireSound.IsPlaying == false then ShootingHandle.FireSound:Play() end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then ShootingHandle.FireSound:Play() end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009PiercedHumanoid[TargetHumanoid] = true\010\009\009\009\009\009end\010\009\009\009\009else\010\009\009\009\009\009PierceAvailable = 0\010\009\009\009\009end\010\009\009\009end\010\009\009else\010\009\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009\009Explosion.BlastRadius = Module.Radius\010\009\009\009Explosion.BlastPressure = 0\010\009\009\009Explosion.Position = EndPos\010\009\009\009Explosion.Parent = Workspace.CurrentCamera\010\009\009\009Explosion.Hit:connect(function(Hit)\010\009\009\009\009if Hit and Hit.Parent and Hit.Name == \034Torso\034 then\010\009\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end)\010\009\009\009PierceAvailable = 0\010\009\009end\010\009\009PierceAvailable = Hit and (PierceAvailable - 1) or -1\010\009\009Player.PlayerScripts.BulletVisualizerScript.Visualize:Fire(nil,ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.HitEffect,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.HitSoundIDs[math.random(1,#Module.HitSoundIDs)],\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.ExplosiveEnabled,Module.BlastRadius,Module.BlastPressure},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009{Module.BulletSpeed,Module.BulletSize,Module.BulletColor,Module.BulletTransparency,Module.BulletMaterial,Module.FadeTime},\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009false,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009\009PierceAvailable == -1 and Module.VisualizerEnabled or false)\010\009\009game.ReplicatedStorage.VisualizeBullet:FireServer(ShootingHandle,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009Module.MuzzleOffset,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009EndPos,\010\009\009\009\009\009\009\009\009\009\009\009\009\009\009script.MuzzleEffect,\010\009\009\009\00