\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010Tool.Unequipped:connect(function()\010\009Handle.FireSound:Stop()\010\009Handle2.FireSound:Stop()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010Humanoid.Died:connect(function()\010\009Handle.FireSound:Stop()\010\009Handle2.FireSound:Stop()\010\009Equipped = false\010\009GUI.Parent = script\010\009if IdleAnim then IdleAnim:Stop() end\010\009\009if AimDown then\010\009\009\009Workspace.CurrentCamera.FieldOfView = 70\010\009\009\009--[[local GUI = game.Players.LocalPlayer.PlayerGui:FindFirstChild(\034ZoomGui\034)\010\009\009\009if GUI then GUI:Destroy() end]]\010\009\009\009GUI.Scope.Visible = false\010\009\009\009game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic\010\009\009\009script[\034Mouse Sensitivity\034].Disabled = true\010\009\009\009AimDown = false\010\009\009\009Mouse.Icon = \034rbxassetid://\034..Module.MouseIconID\010\009\009end\010\009if Module.DualEnabled and not Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)\010\010while true do\010\009local IsChargedShot = false\010\009if Equipped and Enabled and Down and not Reloading and Ammo > 0 and Humanoid.Health > 0 then\010\009\009Enabled = false\010\009\009if Module.ChargedShotEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034ChargeSound\034) then HandleToFire.ChargeSound:Play() end\010\009\009\009wait(Module.ChargingTime)\010\009\009\009IsChargedShot = true\010\009\009end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindUp\034) then HandleToFire.WindUp:Play() end\010\009\009\009wait(Module.DelayBeforeFiring)\010\009\009end\010\009\009while Equipped and not Reloading and (Down or IsChargedShot) and Ammo > 0 and Humanoid.Health > 0 do\010\009\009\009IsChargedShot = false\010\009\009\009for i = 1,(Module.BurstFireEnabled and Module.BulletPerBurst or 1) do\010\009\009\009\009Spawn(ShakeCamera)\010\009\009\009\009for x = 1,(Module.ShotgunEnabled and Module.BulletPerShot or 1) do\010\009\009\009\009\009Fire(HandleToFire)\010\009\009\009\009end\010\009\009\009\009Ammo = Ammo - 1\010\009\009\009\009ChangeAmmoAndClip:FireServer(Ammo,Clips)\010\009\009\009\009UpdateGUI()\010\009\009\009\009if Module.BurstFireEnabled then wait(Module.BurstRate) end\010\009\009\009\009if Ammo <= 0 then break end\010\009\009\009end\010\009\009\009HandleToFire = (HandleToFire == Handle and Module.DualEnabled) and Handle2 or Handle\010\009\009\009wait(Module.FireRate)\010\009\009\009if not Module.Auto then break end\010\009\009end\010\009\009if HandleToFire.FireSound.IsPlaying and HandleToFire.FireSound.Looped then HandleToFire.FireSound:Stop() end\010\009\009if Module.MinigunEnabled then\010\009\009\009if HandleToFire:FindFirstChild(\034WindDown\034) then HandleToFire.WindDown:Play() end\010\009\009\009wait(Module.DelayAfterFiring)\010\009\009end\010\009\009Enabled = true\010\009\009if Ammo <= 0 then Reload() end\010\009end\010\009game:GetService(\034RunService\034).RenderStepped:wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28694,class="LocalScript",parent=28691,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Mouse Sensitivity",["ScriptGuid"]="{E1FD0F1E-070B-42E0-9F37-7D442E148254}",["Source"]="local Module = require(script.Parent.Parent:WaitForChild(\034Setting\034))\010local t=Module.MouseSensitive--MouseSpeed. 1 is regular mouse speed.\010\010local atan2=math.atan2\010local asin=math.asin\010local abs=math.abs\010local floor=math.floor\010local cf=CFrame.new\010local components=cf().components\010local Angles=CFrame.Angles\010local tau=2*math.pi\010local RenderStepped=game:GetService(\034RunService\034).RenderStepped\010\010local Player=game.Players.LocalPlayer\010local Camera=workspace.CurrentCamera\010local Character=Player.Character\010local Head=Character:WaitForChild(\034Head\034)\010\010local function EulerAnglesYX(c)--No z, I don't care about z.\010\009local _,_,_,m00,m01,m02,m10,m11,m12,m20,m21,m22=components(c)\010\009return abs(m12)>0.99999 and -atan2(-m20,m00) or -atan2(-m02,m22),-asin(m12)\010end\010\010local ly,lx=EulerAnglesYX(Camera.CoordinateFrame)\010function Update()\010\009local cy,cx=EulerAnglesYX(Camera.CoordinateFrame)\010\009ly,lx=ly*(1-t)+(cy+tau*floor((ly-cy)/tau+0.5))*t,lx*(1-t)+(cx+tau*floor((lx-cx)/tau+0.5))*t\010\009--print(ly,lx)\010\009Camera.CoordinateFrame=Angles(0,ly,0)*Angles(lx,0,0)*cf(0,0,0.5)+Camera.Focus.p--Head.Position\009\010end\010RenderStepped:connect(Update)\010\010m=Player:GetMouse()\010m.Button1Down:connect(function()\010\009zoom=true\010\009out=false\010end)\010m.Button1Up:connect(function()\010\009zoom=false\010end)\010m.Button2Down:connect(function()\010\009out=true\010\009zoom=false\010end)\010m.Button2Up:connect(function()\010\009out=false\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28745,class="LocalScript",parent=28734,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Local",["ScriptGuid"]="{BD019657-2EA9-445C-8DE4-59974FC96FB5}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player = game.Players.LocalPlayer\010local Mouse = Player:GetMouse()\010local Camera = Workspace.CurrentCamera\010local Character = Workspace:WaitForChild(Player.Name)\010local Humanoid = Character:WaitForChild(\034Humanoid\034)\010local TEAM = Character:WaitForChild(\034TEAM\034)\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local GunScript_Server = Tool:WaitForChild(\034GunScript_Server\034)\010local ChangeAmmoAndClip = GunScript_Server:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = GunScript_Server:WaitForChild(\034InflictTarget\034)\010local AmmoValue = GunScript_Server:WaitForChild(\034Ammo\034)\010local ClipsValue = GunScript_Server:WaitForChild(\034Clips\034)\010local GUI = script:WaitForChild(\034GunGUI\034)\010local IdleAnim\010local FireAnim\010local ReloadAnim\010local ShotgunClipinAnim\010local Grip2\010local Handle2\010local HandleToFire = Handle\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,2)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local Equipped = false\010local Enabled = true\010local Down = false\010local Reloading = false\010local AimDown = false\010local Ammo = AmmoValue.Value\010local Clips = ClipsValue.Value\010local MaxClip = Module.MaxClip\010local PiercedHumanoid = {}\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009IdleAnim = Tool:WaitForChild(\034IdleAnim\034)\010\009IdleAnim = Humanoid:LoadAnimation(IdleAnim)\010end\010if Module.FireAnimationID ~= nil then\010\009FireAnim = Tool:WaitForChild(\034FireAnim\034)\010\009FireAnim = Humanoid:LoadAnimation(FireAnim)\010end\010if Module.ReloadAnimationID ~= nil then\010\009ReloadAnim = Tool:WaitForChild(\034ReloadAnim\034)\010\009ReloadAnim = Humanoid:LoadAnimation(ReloadAnim)\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009ShotgunClipinAnim = Tool:WaitForChild(\034ShotgunClipinAnim\034)\010\009ShotgunClipinAnim = Humanoid:LoadAnimation(ShotgunClipinAnim)\010end\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function RayCast(Start,Direction,Range,Ignore)\010\009local Hit,EndPos = game.Workspace:FindPartOnRay(Ray.new(Start,Direction*Range),Ignore)\010\009if Hit then\010\009\009if (Hit.Transparency > 0.75\010\009\009\009or Hit.Name == \034Handle\034\010\009\009\009or Hit.Name == \034Effect\034\010\009\009\009or Hit.Name == \034Bullet\034\010\009\009\009or Hit.Name == \034Laser\034\010\009\009\009or string.lower(Hit.Name) == \034water\034\010\009\009\009or Hit.Name == \034Rail\034\010\009\009\009or Hit.Name == \034Arrow\034\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent.Humanoid.Health == 0)\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and Hit.Parent:FindFirstChild(\034TEAM\034) and TEAM and Hit.Parent.TEAM.Value == TEAM.Value))\010\009\009\009or (Hit.Parent:FindFirstChild(\034Humanoid\034) and PiercedHumanoid[Hit.Parent.Humanoid]) then\010\009\009\009Hit,EndPos = RayCast(EndPos+(Direction*.01),Direction,Range-((Start-EndPos).magnitude),Ignore)\010\009\009end\010\009end\010\009return Hit,EndPos\010end\010\010function ShakeCamera()\010\009if Module.CameraShakingEnabled then\010\009\009local Intensity = Module.Intensity/(AimDown and Module.MouseSensitive or 1)\010\009\009for i = 1, 10 do\010\009\009\009local cam_rot = Camera.CoordinateFrame - Camera.CoordinateFrame.p\010\009\009\009local cam_scroll = (Camera.CoordinateFrame.p - Camera.Focus.p).magnitude\010\009\009\009local ncf = CFrame.new(Camera.Focus.p)*cam_rot*CFrame.fromEulerAnglesXYZ((-Intensity+(math.random()*(Intensity*2)))/100, (-Intensity+(math.random()*(Intensity*2)))/100, 0)\010\009\009\009Camera.CoordinateFrame = ncf*CFrame.new(0, 0, cam_scroll)\010\009\009\009wait()\010\009\009end\010\009end\010end\010\010function Fire(ShootingHandle)\010\009local PierceAvailable = Module.Piercing\010\009PiercedHumanoid = {}\010\009if FireAnim then FireAnim:Play(nil,nil,Module.FireAnimationSpeed) end\010\009if not ShootingHandle.FireSound.IsPlaying or not ShootingHandle.FireSound.Looped then\010\009local Zombie = script.Parent.Handle.FireSound:Clone()\010\009Zombie:Play()\010\009Zombie.Script.Disabled = false\010\009Zombie.Parent = script.Parent.Handle\010\009Zombie.Name = \034wut\034\010\009end\010\009local Start = (Humanoid.Torso.CFrame * CFrame.new(0,1.5,0)).p--(Handle.CFrame * CFrame.new(Module.MuzzleOffset.X,Module.MuzzleOffset.Y,Module.MuzzleOffset.Z)).p\010\009local Spread = Module.Spread*(AimDown and 1-Module.SpreadRedution or 1)\010\009local Direction = (CFrame.new(Start,Mouse.Hit.p) * CFrame.Angles(math.rad(-Spread+(math.random()*(Spread*2))),math.rad(-Spread+(math.random()*(Spread*2))),0)).lookVector\010\009while PierceAvailable >= 0 do\010\009\009local Hit,EndPos = RayCast(Start,Direction,5000,Character)\010\009\009if not Module.ExplosiveEnabled then\010\009\009\009if Hit and Hit.Parent then\010\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\009(Hit.Name == \034Head\034 and Module.HeadshotEnabled) and Module.BaseDamage * Module.HeadshotDamageMultiplier or Module.BaseDamage,\010\009\009\009\009\009\009\009\009\009\009\009\009Direction,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Knockback,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.Lifesteal,\010\009\009\009\009\009\009\009\009\009\009\009\009Module.FlamingBullet)\010\009\009\009\009\009\009PiercedHumanoid[TargetHumanoid] = true\010\009\009\009\009\009end\010\009\009\009\009else\010\009\009\009\009\009PierceAvailable = 0\010\009\009\009\009end\010\009\009\009end\010\009\009else\010\009\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009\009Explosion.BlastRadius = Module.Radius\010\009\009\009Explosion.BlastPressure = 0\010\009\009\009Explosion.Position = EndPos\010\009\009\009Explosion.Parent = Workspace.CurrentCamera\010\009\009\009Explosion.Hit:connect(function(Hit)\010\009\009\009\009if Hit and Hit.Parent and Hit.Name == \034Torso\034 then\010\009\009\009\009\009local TargetHumanoid = Hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009local TargetTorso = Hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009local TargetTEAM = Hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009if TargetHumanoid and TargetHumanoid.Health > 0 and TargetTorso then\010\009\009\009\009\009\009if TargetTEAM and TargetTEAM.Value ~= TEAM.Value then\010\009\009\009\009\009\009\009InflictTarget:FireServer(TargetHumanoid,\010\009\009\009\009\009\009\009\009\009\009\009\009\009TargetTorso,\010\009\009\009\009\009\009\009\009\009\009\009\