T[#T+1]={id=29022,class="LocalScript",parent=18229,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="errorReport",["ScriptGuid"]="{69270E96-283D-4985-BDC7-4DC51D219839}",["Source"]="-- ReplicatedFirst.errorReport: shows script errors (yours and the server's) in a box at the bottom of the\010-- screen, so they can be screenshotted. Click the box to hide it.\010local pcall = ypcall or pcall\010local players = game:GetService(\034Players\034)\010local player = players.LocalPlayer\010while not player do wait() player = players.LocalPlayer end\010local playerGui = player:WaitForChild(\034PlayerGui\034)\010\010local lines = {}\010local gui, label\010\010local function build()\010\009gui = Instance.new(\034ScreenGui\034)\010\009gui.Name = \034errorReport\034\010\009pcall(function() gui.ResetOnSpawn = false end)\010\009label = Instance.new(\034TextButton\034)\010\009label.Name = \034box\034\010\009label.AutoButtonColor = false\010\009label.Size = UDim2.new(0.5, 0, 0.3, 0)\010\009label.Position = UDim2.new(0.5, -4, 0.7, -4)\010\009label.BackgroundColor3 = Color3.new(0, 0, 0)\010\009label.BackgroundTransparency = 0.25\010\009label.BorderSizePixel = 0\010\009label.TextColor3 = Color3.new(1, 0.45, 0.45)\010\009label.TextXAlignment = Enum.TextXAlignment.Left\010\009label.TextYAlignment = Enum.TextYAlignment.Top\010\009label.TextWrapped = true\010\009pcall(function() label.Font = Enum.Font.SourceSans end)\010\009if not pcall(function() label.TextSize = 14 end) then pcall(function() label.FontSize = Enum.FontSize.Size14 end) end\010\009pcall(function() label.ZIndex = 10 end)\010\009label.Visible = false\010\009label.Text = \034\034\010\009label.MouseButton1Click:connect(function() label.Visible = false end)\010\009label.Parent = gui\010\009gui.Parent = playerGui\010end\010build()\010\010local function add(text)\010\009text = tostring(text):sub(1, 220)\010\009for _, l in ipairs(lines) do if l == text then return end end\010\009table.insert(lines, text)\010\009while #lines > 8 do table.remove(lines, 1) end\010\009if not gui.Parent then build() end\010\009label.Text = \034ERRORS (screenshot this, click to hide):\092n\034 .. table.concat(lines, \034\092n\034)\010\009label.Visible = true\010\009-- stay on top of the other GUIs (old engines draw the last one added on top)\010\009gui.Parent = nil\010\009gui.Parent = playerGui\010end\010\010pcall(function()\010\009game:GetService(\034ScriptContext\034).Error:connect(function(message, trace, scriptObj)\010\009\009local where = \034\034\010\009\009pcall(function() where = \034 [\034 .. scriptObj:GetFullName() .. \034]\034 end)\010\009\009add(\034client: \034 .. tostring(message) .. where)\010\009end)\010end)\010pcall(function()\010\009game:GetService(\034LogService\034).MessageOut:connect(function(message, messageType)\010\009\009if messageType == Enum.MessageType.MessageError then\010\009\009\009add(\034client: \034 .. message)\010\009\009elseif tostring(message):find(\034Infinite yield\034) or tostring(message):find(\034failed to load\034) then\010\009\009\009add(\034client: \034 .. message)\010\009\009end\010\009end)\010end)\010spawn(function()\010\009local remote = game:GetService(\034ReplicatedStorage\034):WaitForChild(\034errorReport\034, 30)\010\009if remote then\010\009\009remote.OnClientEvent:connect(function(message) add(\034server: \034 .. tostring(message)) end)\010\009end\010end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
