T[#T+1]={id=1253,class="ModuleScript",parent=1252,props={["AttributesSerialize"]="",["LinkedSource"]="",["Name"]="Settings",["ScriptGuid"]="{85B5153D-A5B6-4401-803B-4E88FA6378EF}",["Source"]="--[[\010Use usernames or userIds to add a user to a list\010For example;\009Admins={'MyBestFriend','Telamon',261}\009\009]]\010\010local Banned={\034osobeses\034, \034GoSinister\034, \034DeathOfAstra\034, \034KyleChu\034, \034knightofshadows12\034, \034Gangstedude\034, \034Nigerian_Watermelon\034, \034Ryanreis\034, \034MKJ2013\034, \034XXXNoscoper42XXX\034} -- For those who have wronged you, & this guy\010\010--------------------------------------------------------------\010-- You DO NOT need to add yourself to any of these lists!!! --\010--------------------------------------------------------------\010\010local Owners={\034Pokemonfan571\034, \034elijah54403\034, \034Ashpatrick\034, \034iwishforpie1\034, \034ItsPineappleTime\034, \034mariosonicmaster\034, \034Crimson_Knights\034, \034iSavaric\034}\009\009\009\009\009-- Can set SuperAdmins, & use all the commands\010local SuperAdmins={\034NoobyGames123\034}\009\009\009-- Can set permanent admins, & shutdown the game\010local Admins={\034IJustWantAHug\034, \034Cadentopia\034, \034meeper46\034}\009\009\009\009\009-- Can ban, crash, & set Moderators/VIP\010local Mods={\034ImJustOneNoob\034}\009\009\009\009\009-- Can kick, mute, & use most commands\010local VIP={}\009\009\009\009\009-- Can use nonabusive commands only on self\010--\010-- THESE ARE THE CORE SETTINGS\010-- YOU WILL NOT BE ABLE TO CHANGE THEM IN-GAME\010local Settings={\010\009\009\009\009\009\009\009\009--[[\010Style Options\010\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\009\009\009\009\009]]\010Flat=false;\009\009\009\009\009\009-- Enables Flat theme / Disables Aero theme\010ForcedColor=false;\009\009\009\009-- Forces everyone to have set color & transparency\010Color=Color3.new(0,0,0);\009\009-- Changes the Color of the user interface\010ColorTransparency=.75;\009\009\009-- Changes the Transparency of the user interface\010Chat=false;\009\009\009\009\009\009-- Enables the custom chat\010BubbleChat=false;\009\009\009\009-- Enables the custom bubble chat\010\009\009\009\009\009\009\009\009--[[\010Basic Settings\010\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\009\009\009\009\009]]\010AdminCredit=true;\009\009\009\009-- Enables the credit GUI for that appears in the bottom right\010AutoClean=false;\009\009\009\009-- Enables automatic cleaning of hats & tools in the Workspace\010AutoCleanDelay=60;\009\009\009\009-- The delay between each AutoClean routine\010CommandBar=true;\009\009\009\009-- Enables the Command Bar | GLOBAL KEYBIND: \092\010FunCommands=true;\009\009\009\009-- Enables fun yet unnecessary commands\010FreeAdmin=false;\009\009\009\009-- Set to 1-5 to grant admin powers to all, otherwise set to false\010PublicLogs=false;\009\009\009\009-- Allows all users to see the command & chat logs\010Prefix=':';\009\009\009\009\009\009-- Character to begin a command\010\009\009\009\009\009\009\009\009--[[\010Admin Powers\010\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\0100\009\009\009Player\0101\009\009\009VIP\009\009\009\009\009Can use nonabusive commands only on self\0102\009\009\009Moderator\009\009\009Can kick, mute, & use most commands\0103\009\009\009Administrator\009\009Can ban, crash, & set Moderators/VIP\0104\009\009\009SuperAdmin\009\009\009Can grant permanent powers, & shutdown the game\0105\009\009\009Owner\009\009\009\009Can set SuperAdmins, & use all the commands\0106\009\009\009Game Creator\009\009Can set owners & use all the commands\010\010Group & VIP Admin\010\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\010\009\009\009You can set multiple Groups & Ranks to grant users admin powers\010GroupAdmin={\010[12345]={[254]=4,[253]=3};\010[GROUPID]={[RANK]=ADMINPOWER}\010};\010\009\009\009You can set multiple Assets to grant users admin powers\010VIPAdmin={\010[12345]=3;\010[54321]=4;\010[ITEMID]=ADMINPOWER;\010};\009\009\009\009\009\009\009\009]]\010\010GroupAdmin={\010\010};\010\010VIPAdmin={\010\010};\010\010\009\009\009\009\009\009\009\009--[[\010Permissions\010\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\239\191\189\010-- You can set the admin power required to use a command\010-- COMMANDNAME=ADMINPOWER;\009\009]]\010\010Permissions={\010\010};\010\010}\010\010return {Settings,{Owners,SuperAdmins,Admins,Mods,VIP,Banned}}",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1254,class="ModuleScript",parent=1252,props={["AttributesSerialize"]="",["LinkedSource"]="",["Name"]="Custom Commands",["ScriptGuid"]="{F3F627CA-21A6-4A4D-837D-70C13EC16729}",["Source"]="--[[\010\010ADMIN POWERS\010\0100\009\009Player\0101\009\009VIP/Donor\0102\009\009Moderator\0103\009\009Administrator\0104\009\009Super Administrator\0105\009\009Owner\0106\009\009Game Creator\010\010First table consists of the different variations of the command.\010\010Second table consists of the description and an example of how to use it.\010\010Third index is the ADMIN POWER required to use the command.\010\010Fourth table consists of the arguments that will be returned in the args table.\010'player'\009-- returns an array of Players\010'userid'\009-- returns an array of userIds\010'boolean'\009-- returns a Boolean value\010'color'\009\009-- returns a Color3 value\010'number'\009-- returns a Number value\010'string'\009-- returns a String value\010'time'\009\009-- returns # of seconds\010'banned'\009-- returns a value from Bans table\010'admin'\009\009-- returns a value from Admins table\010-- Adding / to any argument will make it optional; can return nil!!!\010\010Fifth index consists of the function that will run when the command is executed properly.\009]]\010return {\010\010{{'test','othertest'},{'Test command.','Example'},6,{'number','string/'},function(pl,args)\010print(pl,args[1],args[2])\010end}\010\010};",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18250,class="ModuleScript",parent=18241,props={["AttributesSerialize"]="",["LinkedSource"]="",["Name"]="Setting",["ScriptGuid"]="{D514344B-FCAC-4DFD-A459-AE74B627620D}",["Source"]="--[[ Version v1.0.6\010====================================================================================================\010Weapons and Tools Pack 2016's Gun by SuperEvilAzmil\010\010Features:\010- FilteringEnabled support\010- Easy to edit with a bunch of settings\010- No delays between Mouse Click and Gun Fire\010====================================================================================================\010]]\010\010local Module = {\010--\009====================\010--\009BASIC\010--\009A basic settings for the gun\010--\009====================\010\010\009\009Auto = false;\010\009\009MuzzleOffset = Vector3.new(0,0.75,.5);\010\009\009BaseDamage = 15;\010\009\009FireRate = 0.25; --In second\010\009\009ReloadTime = 2.25; --In second\010\009\009AmmoPerClip = 12; --Put \034math.huge\034 to make this gun has infinite ammo and never reload\010\009\009Spread = 0.75; --In degree\010\009\009HeadshotEnabled = false; --Enable the gun to do extra damage on headshot\010\009\009HeadshotDamageMultiplier = 1;\010\009\009MouseIconID = \034316279304\034;\010\009\009HitSoundIDs = {186809061,186809249,186809250,186809252};\010\009\009IdleAnimationID = \034514256706\034; --Set to \034nil\034 if you don't want to animate\010\009\009IdleAnimationSpeed = 0.5;\010\009\009FireAnimationID = \034514251510\034; --Set to \034nil\034 if you don't want to animate\010\009\009FireAnimationSpeed = 1;\010\009\009ReloadAnimationID = \034514257403\034; --Set to \034nil\034 if you don't want to animate\010\009\009ReloadAnimationSpeed = 0.8;\010\009\009\010--\009====================\010--\009LIMITED CLIP\010--\009Make a gun has a limit clip\010--\009====================\010\010\009\009LimitedClipEnabled = false;\010\009\009Clips = 10;\010\009\009MaxClip = 10; --Put \034math.huge\034 to allow user to carry unlimited clip\010\009\009\010--\009====================\010--\009SHOTGUN\010--\009Enable the gun to fire multiple bullet in one shot\010--\009====================\010\010\009\009ShotgunEnabled = false;\010\009\009BulletPerShot = 12;\010\009\009\010\009\009ShotgunReload = false; --Make user reloading like Shotgun, which user clipin shell one by one\010\009\009ShotgunClipinAnimationID = \034558163388\034; --Set to \034nil\034 if you don't want to animate\010\009\009ShotgunClipinAnimationSpeed = 0.5;\010\009\009ShellClipinSpeed = 0.7; --In second\010\009\009\010--\009\009How \034ShotgunEnabled\034 work [Example]:\010\010--\009\009Play \034ShotgunClipinAnimation\034 + Play \034ShotgunClipin\034 Audio\010--\009\009>>>\010--\009\009Wait \034ShellClipinSpeed\034 second\010--\009\009>>>\010--\009\009Repeat \034AmmoPerClip\034 - \034Current Ammo\034 times\010--\009\009>>>\010--\009\009Play \034ReloadAnimation\034 + Play \034ReloadSound\034\010--\009\009Wait \034ReloadTime\034\010\009\009\010--\009====================\010--\009BURST FIRE\010--\009Enable the gun to do burst firing like Assault Rifle\010--\009====================\010\010\009\009BurstFireEnabled = false;\010\009\009BulletPerBurst = 3;\010\009\009BurstRate = 0.075; --In second\010\009\009\010--\009====================\010--\009SNIPER\010--\009Enable user to use scope\010--\009====================\010\010\009\009SniperEnabled = false;\010\009\009FieldOfView = 12.5;\010\009\009MouseSensitive = 0.05; --In percent\010\009\009SpreadRedution = 1; --In percent.\010\009\009\010--\009====================\010--\009CAMERA SHAKING\010--\009Make user's camera shaking when shooting\010--\009====================\010\010\009\009CameraShakingEnabled = false;\010\009\009Intensity = 0.5; --In degree\010\009\009\010--\009====================\010--\009EXPLOSIVE\010--\009Make a bullet explosive so user can deal a damage to multiple enemy in single shot. NOTE: Explosion won't break joints\010--\009====================\010\010\009\009ExplosiveEnabled = false;\010\009\009Radius = 8;\010\009\009\010--\009====================\010--\009BULLET VISUALIZER\010--\009Enabled the gun to display a fake travelling bullet\010--\009====================\010\010\009\009VisualizerEnabled = true;\010\009\009BulletSpeed = 25;\010\009\009BulletSize = Vector3.new(0.25,0.25,100);\010\009\009BulletColor = BrickColor.new(\034Bright yellow\034);\010\009\009BulletTransparency = 0.25;\010\009\009BulletMaterial = Enum.Material.SmoothPlastic;\010\009\009FadeTime = 0.25; --Only work when bullet travel instantly. For this, you have to set BulletSpeed to \034math.huge\034\010\009\009\010--\009====================\010--\009CHARGED SHOT\010--\009Make a gun charging before firing. Useful for a gun like \034Railgun\034 or \034Laser Cannon\034\010--\009====================\010\009\009\010\009\009ChargedShotEnabled = false;\010\009\009ChargingTime = 1;\010\009\009\010--\009====================\010--\009MINIGUN\010--\009Make a gun delay before/after firing\010--\009====================\010\010\009\009MinigunEnabled = false;\010\009\009DelayBeforeFiring = 1;\010\009\009DelayAfterFiring = 1;\010\009\009\010--\009====================\010--\009MISCELLANEOUS\010--\009Etc. settings for the gun\010--\009====================\010\010\009\009Knockback = 0; --Setting above 0 will enabling the gun to push enemy back. NOTE: If \034ExplosiveEnabled\034 is enabled, this setting is not work\010\009\009Lifesteal = 0; --In percent - Setting above 0 will allow user to steal enemy's health by dealing a damage to them.\010\009\009FlamingBullet = false; --Enable the bullet to set enemy on fire. Its DPS and Duration can be edited inside \034IgniteScript\034\010\009\009DualEnabled = false; --Enable the user to hold two guns instead one. In order to make this setting work, you must clone its Handle and name it to \034Handle2\034. Enabling this setting will override Idle Animation ID.\010\009\009Piercing = 0; --Setting above 0 will enabling the gun to penetrate up to XX victim(s). Cannot penetrate wall. NOTE: It doesn't work with \034ExplosiveEnabled\034\010\009\009\010--\009====================\010--\009END OF SETTING\010--\009====================\010}\010\010return Module\010",["SourceAssetId"]=-1,["Tags"]=""}}
