T[#T+1]={id=18969,class="ModuleScript",parent=18960,props={["AttributesSerialize"]="",["LinkedSource"]="",["Name"]="Setting",["ScriptGuid"]="{FA51553A-59BC-448A-9479-B51D3EF5E21A}",["Source"]="--[[ Version v1.0.6\010====================================================================================================\010Weapons and Tools Pack 2016's Gun by SuperEvilAzmil\010\010Features:\010- FilteringEnabled support\010- Easy to edit with a bunch of settings\010- No delays between Mouse Click and Gun Fire\010====================================================================================================\010]]\010\010local Module = {\010--\009====================\010--\009BASIC\010--\009A basic settings for the gun\010--\009====================\010\010\009\009Auto = false;\010\009\009MuzzleOffset = Vector3.new(0,2.45,0.1875);\010\009\009BaseDamage = 100;\010\009\009FireRate = 1.5; --In second\010\009\009ReloadTime = 5.25; --In second\010\009\009AmmoPerClip = 8; --Put \034math.huge\034 to make this gun has infinite ammo and never reload\010\009\009Spread = 1; --In degree\010\009\009HeadshotEnabled = true; --Enable the gun to do extra damage on headshot\010\009\009HeadshotDamageMultiplier = 5;\010\009\009MouseIconID = \034316279304\034;\010\009\009HitSoundIDs = {186809061,186809249,186809250,186809252};\010\009\009IdleAnimationID = \034558365347\034; --Set to \034nil\034 if you don't want to animate\010\009\009IdleAnimationSpeed = 0.5;\010\009\009FireAnimationID = \034558365752\034; --Set to \034nil\034 if you don't want to animate\010\009\009FireAnimationSpeed = 2;\010\009\009ReloadAnimationID = \034558365999\034; --Set to \034nil\034 if you don't want to animate\010\009\009ReloadAnimationSpeed = 0.3;\010\009\009\010--\009====================\010--\009LIMITED CLIP\010--\009Make a gun has a limit clip\010--\009====================\010\010\009\009LimitedClipEnabled = false;\010\009\009Clips = 10;\010\009\009MaxClip = 10; --Put \034math.huge\034 to allow user to carry