xplosiveEnabled = false;\010\009\009Radius = 8;\010\009\009\010--\009====================\010--\009BULLET VISUALIZER\010--\009Enabled the gun to display a fake travelling bullet\010--\009====================\010\010\009\009VisualizerEnabled = true;\010\009\009BulletSpeed = 25;\010\009\009BulletSize = Vector3.new(0.25,0.25,100);\010\009\009BulletColor = BrickColor.new(\034Bright yellow\034);\010\009\009BulletTransparency = 0.25;\010\009\009BulletMaterial = Enum.Material.SmoothPlastic;\010\009\009FadeTime = 0.25; --Only work when bullet travel instantly. For this, you have to set BulletSpeed to \034math.huge\034\010\009\009\010--\009====================\010--\009CHARGED SHOT\010--\009Make a gun charging before firing. Useful for a gun like \034Railgun\034 or \034Laser Cannon\034\010--\009====================\010\009\009\010\009\009ChargedShotEnabled = false;\010\009\009ChargingTime = 1;\010\009\009\010--\009====================\010--\009MINIGUN\010--\009Make a gun delay before/after firing\010--\009====================\010\010\009\009MinigunEnabled = false;\010\009\009DelayBeforeFiring = 1;\010\009\009DelayAfterFiring = 1;\010\009\009\010--\009====================\010--\009MISCELLANEOUS\010--\009Etc. settings for the gun\010--\009====================\010\010\009\009Knockback = 0; --Setting above 0 will enabling the gun to push enemy back. NOTE: If \034ExplosiveEnabled\034 is enabled, this setting is not work\010\009\009Lifesteal = 0; --In percent - Setting above 0 will allow user to steal enemy's health by dealing a damage to them.\010\009\009FlamingBullet = false; --Enable the bullet to set enemy on fire. Its DPS and Duration can be edited inside \034IgniteScript\034\010\009\009DualEnabled = false; --Enable the user to hold two guns instead one. In order to make this setting work, you must clone its Handle and name it to \034Handle2\034. Enabling this setting will override Idle Animation ID.\010\009\009Piercing = 0; --Setting above 0 will enabling the gun to penetrate up to XX victim(s). Cannot penetrate wall. NOTE: It doesn't work with \034ExplosiveEnabled\034\010\009\009\010--\009====================\010--\009END OF SETTING\010--\009====================\010}\010\010return Module\010",["SourceAssetId"]=-1,["Tags"]=""}}
