T[#T+1]={id=19943,class="ModuleScript",parent=19942,props={["AttributesSerialize"]="",["LinkedSource"]="",["Name"]="Functions",["ScriptGuid"]="{56A7A57A-FC80-4036-9C3B-CBA083F4CA6C}",["Source"]="--Made by Luckymaxer\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010\010RbxUtility = LoadLibrary(\034RbxUtility\034)\010Create = RbxUtility.Create\010\010Functions = {}\010\010function Functions.Clamp(Number, Min, Max)\010\009return math.max(math.min(Max, Number), Min)\010end\010\010function Functions.GetPercentage(Start, End, Number)\010\009return (((Number - Start) / (End - Start)) * 100)\010end\010\010function Functions.Round(Number, RoundDecimal)\010\009local WholeNumber, Decimal = math.modf(Number)\010\009return ((Decimal >= RoundDecimal and math.ceil(Number)) or (Decimal < RoundDecimal and math.floor(Number)))\010end\010\010function Functions.IsTeamMate(Player1, Player2)\010\009return (Player1 and Player2 and not Player1.Neutral and not Player2.Neutral and Player1.TeamColor == Player2.TeamColor)\010end\010\010function Functions.TagHumanoid(humanoid, player)\010\009local Creator_Tag = Create(\034ObjectValue\034){\010\009\009Name = \034creator\034,\010\009\009Value = player,\010\009}\010\009Debris:AddItem(Creator_Tag, 2)\010\009Creator_Tag.Parent = humanoid\010end\010\010function Functions.UntagHumanoid(humanoid)\010\009for i, v in pairs(humanoid:GetChildren()) do\010\009\009if v:IsA(\034ObjectValue\034) and v.Name == \034creator\034 then\010\009\009\009v:Destroy()\010\009\009end\010\009end\010end\010\010function Functions.CheckTableForString(Table, String)\010\009for i, v in pairs(Table) do\010\009\009if string.find(string.lower(String), string.lower(v)) then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function Functions.CheckIntangible(Hit)\010\009local ProjectileNames = {\034Water\034, \034Arrow\034, \034Projectile\034, \034Effect\034, \034Rail\034, \034Laser\034, \034Bullet\034}\010\009if Hit and Hit.Parent then\010\009\009if ((not Hit.CanCollide or Functions.CheckTableForString(ProjectileNames, Hit.Name)) and not Hit.Parent:FindFirstChild(\034Humanoid\034)) then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function Functions.CastRay(StartPos, Vec, Length, Ignore, DelayIfHit)\010\009local Ignore = ((type(Ignore) == \034table\034 and Ignore) or {Ignore})\010\009local RayHit, RayPos, RayNormal = game:GetService(\034Workspace\034):FindPartOnRayWithIgnoreList(Ray.new(StartPos, Vec * Length), Ignore)\010\009if RayHit and Functions.CheckIntangible(RayHit) then\010\009\009if DelayIfHit then\010\009\009\009wait()\010\009\009end\010\009\009RayHit, RayPos, RayNormal = Functions.CastRay((RayPos + (Vec * 0.01)), Vec, (Length - ((StartPos - RayPos).magnitude)), Ignore, DelayIfHit)\010\009end\010\009return RayHit, RayPos, RayNormal\010end\010\010return Functions",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20002,class="ModuleScript",parent=20001,props={["AttributesSerialize"]="",["LinkedSource"]="",["Name"]="Functions",["ScriptGuid"]="{C040F2CD-A741-4F71-B62B-7E8FAE676848}",["Source"]="--Made by Luckymaxer\010\010Debris = game:GetService(\034Debris\034)\010\010ProjectileNames = {\034Water\034, \034Arrow\034, \034Projectile\034, \034Effect\034, \034Rail\034, \034Laser\034, \034Ray\034, \034Bullet\034, \034ParticlePart\034}\010\010Functions = {\010\009\010\009CreateConfiguration = (function(Configurations, Table)\010\009\009for i, v in pairs(Configurations:GetChildren()) do\010\009\009\009if string.find(v.ClassName, \034Value\034) then\010\009\009\009\009Table[v.Name] = v:Clone()\010\009\009\009elseif v:IsA(\034Folder\034) or v:IsA(\034Configuration\034) then\010\009\009\009\009Table[v.Name] = Functions.CreateConfiguration(v, Table)\010\009\009\009end\010\009\009end\010\009\009return Table\010\009end),\010\009\010\009FindCharacterAncestor = (function(Object)\010\009\009if Object and Object ~= game:GetService(\034Workspace\034) then\010\009\009\009local Humanoid = Object:FindFirstChild(\034Humanoid\034)\010\009\009\009if Humanoid then\010\009\009\009\009return Object, Humanoid\010\009\009\009else\010\009\009\009\009return Functions.FindCharacterAncestor(Object.Parent)\010\009\009\009end\010\009\009end\010\009\009return nil\010\009end),\010\010\009CheckTableForString = (function(Table, String)\010\009\009for i, v in pairs(Table) do\010\009\009\009if string.lower(v) == string.lower(String) then\010\009\009\009\009return true\010\009\009\009end\010\009\009end\010\009\009return false\010\009end),\010\009\010\009CheckIntangible = (function(Hit)\010\009\009if Hit and Hit.Parent then\010\009\009\009if Functions.CheckTableForString(ProjectileNames, Hit.Name) then\010\009\009\009\009return true\010\009\009\009end\010\009\009\009local ObjectParent = Hit.Parent\010\009\009\009local Character = ObjectParent.Parent\010\009\009\009local Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009\009\009if Humanoid and Humanoid.Health > 0 and ObjectParent:IsA(\034Hat\034) then\010\009\009\009\009return true\010\009\009\009end\010\009\009end\010\009\009return false\010\009end),\010\009\010\009CastRay = (function(StartPos, Vec, Length, Ignore, DelayIfHit)\010\009\009local RayHit, RayPos, RayNormal = game:GetService(\034Workspace\034):FindPartOnRayWithIgnoreList(Ray.new(StartPos, Vec * Length), Ignore)\010\009\009if RayHit and Functions.CheckIntangible(RayHit) then\010\009\009\009if DelayIfHit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009RayHit, RayPos, RayNormal = Functions.CastRay((RayPos + (Vec * 0.01)), Vec, (Length - ((StartPos - RayPos).magnitude)), Ignore, DelayIfHit)\010\009\009end\010\009\009return RayHit, RayPos, RayNormal\010\009end),\010\009\010\009IsTeamMate = (function(Player1, Player2)\010\009\009return (Player1 and Player2 and not Player1.Neutral and not Player2.Neutral and Player1.TeamColor == Player2.TeamColor)\010\009end),\010\009\010\009TagHumanoid = (function(humanoid, player)\010\009\009local Creator_Tag = Instance.new(\034ObjectValue\034)\010\009\009Creator_Tag.Name = \034creator\034\010\009\009Creator_Tag.Value = player\010\009\009Debris:AddItem(Creator_Tag, 2)\010\009\009Creator_Tag.Parent = humanoid\010\009end),\010\009\010\009UntagHumanoid = (function(humanoid)\010\009\009for i, v in pairs(humanoid:GetChildren()) do\010\009\009\009if v:IsA(\034ObjectValue\034) and v.Name == \034creator\034 then\010\009\009\009\009v:Destroy()\010\009\009\009end\010\009\009end\010\009end),\010\009\010\009CheckTableForString = (function(Table, String)\010\009\009for i, v in pairs(Table) do\010\009\009\009if string.lower(v) == string.lower(String) then\010\009\009\009\009return true\010\009\009\009end\010\009\009end\010\009\009return false\010\009end),\010\009\010\009Clamp = (function(Number, Min, Max)\010\009\009return math.max(math.min(Max, Number), Min)\010\009end),\010\009\010\009GetPercentage = (function(Start, End, Number)\010\009\009return (((Number - Start) / (End - Start)) * 100)\010\009end),\010\009\010\009Round = (function(Number, RoundDecimal)\010\009\009local WholeNumber, Decimal = math.modf(Number)\010\009\009return ((Decimal >= RoundDecimal and math.ceil(Number)) or (Decimal < RoundDecimal and math.floor(Number)))\010\009end),\010\009\010}\010\010return Functions",["SourceAssetId"]=-1,["Tags"]=""}}
