T[#T+1]={id=20682,class="ModuleScript",parent=20681,props={["AttributesSerialize"]="",["LinkedSource"]="",["Name"]="Functions",["ScriptGuid"]="{BACFD002-4925-4D78-B3B8-F51DC2E0888D}",["Source"]="--Made by Luckymaxer\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010\010RbxUtility = LoadLibrary(\034RbxUtility\034)\010Create = RbxUtility.Create\010\010Functions = {}\010\010function Functions.Clamp(Number, Min, Max)\010\009return math.max(math.min(Max, Number), Min)\010end\010\010function Functions.GetPercentage(Start, End, Number)\010\009return (((Number - Start) / (End - Start)) * 100)\010end\010\010function Functions.Round(Number, RoundDecimal)\010\009local WholeNumber, Decimal = math.modf(Number)\010\009return ((Decimal >= RoundDecimal and math.ceil(Number)) or (Decimal < RoundDecimal and math.floor(Number)))\010end\010\010function Functions.IsTeamMate(Player1, Player2)\010\009return (Player1 and Player2 and not Player1.Neutral and not Player2.Neutral and Player1.TeamColor == Player2.TeamColor)\010end\010\010function Functions.TagHumanoid(humanoid, player)\010\009local Creator_Tag = Create(\034ObjectValue\034){\010\009\009Name = \034creator\034,\010\009\009Value = player,\010\009}\010\009Debris:AddItem(Creator_Tag, 2)\010\009Creator_Tag.Parent = humanoid\010end\010\010function Functions.UntagHumanoid(humanoid)\010\009for i, v in pairs(humanoid:GetChildren()) do\010\009\009if v:IsA(\034ObjectValue\034) and v.Name == \034creator\034 then\010\009\009\009v:Destroy()\010\009\009end\010\009end\010end\010\010function Functions.CheckTableForString(Table, String)\010\009for i, v in pairs(Table) do\010\009\009if string.find(string.lower(String), string.lower(v)) then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function Functions.CheckIntangible(Hit)\010\009local ProjectileNames = {\034Water\034, \034Arrow\034, \034Projectile\034, \034Effect\034, \034Rail\034, \034Laser\034, \034Bullet\034}\010\009if Hit and Hit.Parent then\010\009\009if ((not Hit.CanCollide or Functions.CheckTableForString(ProjectileNames, Hit.Name)) and not Hit.Parent:FindFirstChild(\034Humanoid\034)) then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function Functions.CastRay(StartPos, Vec, Length, Ignore, DelayIfHit)\010\009local Ignore = ((type(Ignore) == \034table\034 and Ignore) or {Ignore})\010\009local RayHit, RayPos, RayNormal = game:GetService(\034Workspace\034):FindPartOnRayWithIgnoreList(Ray.new(StartPos, Vec * Length), Ignore)\010\009if RayHit and Functions.CheckIntangible(RayHit) then\010\009\009if DelayIfHit then\010\009\009\009wait()\010\009\009end\010\009\009RayHit, RayPos, RayNormal = Functions.CastRay((RayPos + (Vec * 0.01)), Vec, (Length - ((StartPos - RayPos).magnitude)), Ignore, DelayIfHit)\010\009end\010\009return RayHit, RayPos, RayNormal\010end\010\010return Functions",["SourceAssetId"]=-1,["Tags"]=""}}
