ry unlimited clip\010\009\009\010--\009====================\010--\009SHOTGUN\010--\009Enable the gun to fire multiple bullet in one shot\010--\009====================\010\010\009\009ShotgunEnabled = false;\010\009\009BulletPerShot = 12;\010\009\009\010\009\009ShotgunReload = false; --Make user reloading like Shotgun, which user clipin shell one by one\010\009\009ShotgunClipinAnimationID = \034558163388\034; --Set to \034nil\034 if you don't want to animate\010\009\009ShotgunClipinAnimationSpeed = 0.5;\010\009\009ShellClipinSpeed = 0.7; --In second\010\009\009\010--\009\009How \034ShotgunEnabled\034 work [Example]:\010\010--\009\009Play \034ShotgunClipinAnimation\034 + Play \034ShotgunClipin\034 Audio\010--\009\009>>>\010--\009\009Wait \034ShellClipinSpeed\034 second\010--\009\009>>>\010--\009\009Repeat \034AmmoPerClip\034 - \034Current Ammo\034 times\010--\009\009>>>\010--\009\009Play \034ReloadAnimation\034 + Play \034ReloadSound\034\010--\009\009Wait \034ReloadTime\034\010\009\009\010--\009====================\010--\009BURST FIRE\010--\009Enable the gun to do burst firing like Assault Rifle\010--\009====================\010\010\009\009BurstFireEnabled = false;\010\009\009BulletPerBurst = 3;\010\009\009BurstRate = 0.075; --In second\010\009\009\010--\009====================\010--\009SNIPER\010--\009Enable user to use scope\010--\009====================\010\010\009\009SniperEnabled = false;\010\009\009FieldOfView = 12.5;\010\009\009MouseSensitive = 0.05; --In percent\010\009\009SpreadRedution = 1; --In percent.\010\009\009\010--\009====================\010--\009CAMERA SHAKING\010--\009Make user's camera shaking when shooting\010--\009====================\010\010\009\009CameraShakingEnabled = false;\010\009\009Intensity = 0.5; --In degree\010\009\009\010--\009====================\010--\009EXPLOSIVE\010--\009Make a bullet explosive so user can deal a damage to multiple enemy in single shot. NOTE: Explosion won't break joints\010--\009====================\010\010\009\0