 \010Zombie:MakeJoints() \010wait(2) \010Zombie = game.Lighting[\034Zombie\034]:Clone() \010Zombie.Parent = game.Workspace \010Zombie:MakeJoints() \010\009while script.WaveNum.Value == 1 do\010\009\009wait(0.1)\010\009\009if script.Dead_Zombies.Value == 5 then\010\009\009\010\009\009script.Dead_Zombies.Value = 0\010\009\009script.Zombies_To_Kill.Value = 0\010\009\009game.workspace.Core.Humanoid.Health = game.workspace.Core.Humanoid.MaxHealth\010\009\009for i, child in pairs(game.Players:getChildren()) do\010\009\009if child.leaderstats ~= nil then\010\009\009child.leaderstats.Coin.Value = child.leaderstats.Coin.Value + 100\010\009\009end\010\009\009end\010\009\009Wave2()\010\009\009break\010\009\009end\010\009end\010\009end\010\010function Wave2()\010script.Message.Text = \034WAVE OVER\034\010wait(2)\010script.Message.Text = \034Zombies: X_X\034\010wait(5)\010script.Message.Text = \034Origin Zombie: Welp time to send the flintlockers ands blunderbussers\034\010wait(5)\010script.Message.Text = \034WAVE 2\034\010wait(2)\010script.WaveNum.Value = 2\010script.Message.Text = \034\034\010script.Zombies_To_Kill.Value = 7\010Zombie = game.Lighting[\034Zombie\034]:Clone() \010Zombie.Parent = game.Workspace \010Zombie:MakeJoints() \010wait(2)\010Flintlock = game.Lighting[\034Blunderbusser\034]:Clone()   \010Flintlock.Parent = game.Workspace \010Flintlock:MakeJoints() \010wait(2)\010Zombie = game.Lighting[\034Zombie\034]:Clone()  \010Zombie.Parent = game.Workspace \010Zombie:MakeJoints() \010wait(2)\010Flintlock = game.Lighting[\034Zombie\034]:Clone() \010Flintlock.Parent = game.Workspace \010Flintlock:MakeJoints() \010wait(2)\010Zombie = game.Lighting[\034Flintlock Zombie\034]:Clone()  \010Zombie.Parent = game.Workspace \010Zombie:MakeJoints() \010wait(2)\010Flintlock = game.Lighting[\034Zombie\034]:Clone()  \010Flintlock.Parent = game.Workspace \010Flintlock:MakeJoints() \010wait(2)\010Flintlock = game.Lighting[\034Zombie\034]:Clone()  \010Flintlock.Parent = game.Workspace \