:Clone()\010Flintlock.Parent = game.Workspace \010Flintlock:MakeJoints() \010script.Message.Text = \034GAME: 1x1x1x1 ARRIVES IN 40 SECONDS\034\010wait(2)\010script.Message.Text = \034\034\010wait(38)\010Flintlock = game.Lighting[\0341x1x1x1\034]:Clone()  \010Flintlock.Parent = game.Workspace \010Flintlock:MakeJoints() \010\009while script.WaveNum.Value == 99 do\010\009\009wait(0.1)\010\009\009if script.Dead_Zombies.Value == 100 then\010\009\009\009\010\009\009script.Dead_Zombies.Value = 0\010 \009\009script.Zombies_To_Kill.Value = 0\010\009\009game.workspace.Core.Humanoid.Health = game.workspace.Core.Humanoid.MaxHealth\010\009\009for i, child in pairs(game.Players:getChildren()) do\010\009\009if child ~= nil then\010\009\009print(\034Awarding BadgeID: \034 ..script.BadgeID.Value .. \034 to UserID: \034 .. child.userId)\010\009\009local b = game:GetService(\034BadgeService\034)\010\009\009b:AwardBadge(child.userId, script.BadgeID.Value)\010\009\009end\010\009\009end\009\010\009\009DemoEnd()\010\009\009break\010\009\009end\010\009end\010end\010\010function DemoEnd()\010script.Parent.Storm:Remove()\010script.BonusWave:Stop()\010game.Lighting.TimeOfDay =  14\010game.Lighting.Brightness = 1\010script.VictoryMusic:play()\010script.Message.Text = \034GAME: You have beaten the bonus wave\034\010wait(5)\010script.Message.Text = \034GAME: Im really impressed\034\010wait(5)\010script.Message.Text = \034GAME: You win (and you beat the bonus wave) congratulations\034\010wait(5)\010script.Message.Text = \034GAME: The game will restart soon\034\010wait(5)\010script.Message.Text = \034\034\010game.workspace.Core.Humanoid.Health = game.workspace.Core.Humanoid.MaxHealth\010wait(5)\010game.Workspace.Core:remove()\010script.VictoryMusic:Stop()\010wait(0.2)\010game.workspace[\034RESTART SCRIPT\034].Thingylol.Value = true\010game.workspace[\034RESTART SCRIPT\034].RemoveTool.Value = true\010for index, child in pairs (game.Workspace:getChildren()) do\010if child:isA(\034Model\034) then\010if child:FindFirstChild(\034Humanoid\034) then\010child:BreakJoints()\010end\010end\010end\010game.workspace[\034RESTART SCRIPT\034].RemoveTool.Value = false\010local CoreClone = game.Lighting.Core:Clone()\010CoreClone.Parent = game.Workspace\010CoreClone:MakeJoints()\010script.Parent.AllyNpcs.Value = 0\010script.Parent.AllyBosses.Value = 0\010wait(0.1)\010game.workspace[\034RESTART SCRIPT\034].Thingylol.Value = false\010Wave1()\010end\010\010\009wait(1)\010\009if script.Running.Value == 0 then\010\009game.workspace.Core.Humanoid.Health = game.workspace.Core.Humanoid.MaxHealth\010\009Wave1()\010\009else\010\009wait(5)\010\009end",["SourceAssetId"]=-1,["Tags"]=""}}
