T[#T+1]={id=1145,class="Script",parent=0,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ZombieMode",["ScriptGuid"]="{51DAA1A7-C3CF-432C-92E5-F482FD87A3B9}",["Source"]="local __passCache = {}; local function __ownsPass(userId, id) local key = tostring(userId) .. \034:\034 .. tostring(id); if __passCache[key] == nil then local ok, r = (ypcall or pcall)(function() return game:GetService(\034MarketplaceService\034):UserOwnsGamePassAsync(userId, id) end); __passCache[key] = ok and r or false end; return __passCache[key] end; --scripted by ConnorVIII, If you have questions, promblems or this breaks, PM me.\010--script.Parent = game.ServerScriptService\010--[[\010WHAT YOU NEED TO DO.\010Line 8,9 and 10 are IMPORTANT! They instruct the script WHERE to find the tools, you need to make sure you write it ACCURACTLY!!\010Line 15,24 and 34 all have numbers. These numbers are the gamepass ID! You need to edit them for your personal gamepasses!\010--]]\010\010--[[game.Players.PlayerAdded:connect(function(Player)\010\009\010\009Player.CharacterAdded:connect(function(Character)\010\009\009if Player.Name == \034Pokemonfan571\034 or Player.Name == \034elijah54403\034 or Player.Name == \034catnoo\034 or Player.Name == \034THEseriousBOSS\034 or Player.Name == \034ciijay\034 or Player.Name == \034Player1\034 or Player.Name == \034MegaGodPowers\034 or Player.Name == \034NoobyGames123\034 or Player.Name == \034KyleChu\034 or Player.Name == \034DIEGO12316\034 or Player.Name == \034IJustWantAHug\034 or Player.Name == \034vincelukeII\034 or Player.Name == \034Ashpatrick\034 or Player.Name == \034elijah54403\034 or Player.Name == \034iwishforpie1\034 or Player.Name == \034ItsPineappleTime\034 or game:GetService(\034GamePassService\034):PlayerHasPass(Player, 643374319) then\010\009\009\009local gui = script[\034Morph/Model Gui\034]:Clone()\010\009\009\009gui.Parent = Player:WaitForChild(\034PlayerGui\034)\010\009\009\009gui.Enabled = true\010\009\009end\010\009end)\010\009\010\009\010\009 --OPTIONAL YOU CAN REMOVE IF WANTED  v\010\009 --OPTIONAL YOU CAN REMOVE IF WANTED ^\010\009\010end)]]\010local RunService = game:GetService('RunService')\010\010local MarketPlaceService = game:GetService(\034MarketplaceService\034)\010\010while true do\010RunService.Heartbeat:wait()\010\009for i,Player in pairs (game.Players:GetChildren()) do\010\009\009local PlayerBoughtThisGamePass = __ownsPass(Player.UserId, 2403885)\010\009\009if Player.Name == \034Pokemonfan571\034 or Player.Name == \034elijah54403\034 or Player.Name == \034catnoo\034 or Player.Name == \034THEseriousBOSS\034 or Player.Name == \034ciijay\034 or Player.Name == \034Player1\034 or Player.Name == \034MegaGodPowers\034 or Player.Name == \034NoobyGames123\034 or Player.Name == \034KyleChu\034 or Player.Name == \034DIEGO12316\034 or Player.Name == \034IJustWantAHug\034 or Player.Name == \034vincelukeII\034 or Player.Name == \034Ashpatrick\034 or Player.Name == \034elijah54403\034 or Player.Name == \034iwishforpie1\034 or Player.Name == \034ItsPineappleTime\034 or PlayerBoughtThisGamePass then\010\009\009\009if Player:FindFirstChild(\034PlayerGui\034) and Player:FindFirstChild(\034PlayerGui\034):FindFirstChild(\034Morph/Model Gui\034) == nil then\010\009\009\009\009local gui = script[\034Morph/Model Gui\034]:Clone()\010\009\009\009\009gui.Parent = Player:FindFirstChild(\034PlayerGui\034)\010\009\009\009\009gui.Enabled = true\010\009\009\009end\010\009\009end\010\009end\010end",["SourceAssetId"]=-1,["Tags"]=""}}
