T[#T+1]={id=1262,class="Script",parent=0,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GamepassForTools",["ScriptGuid"]="{F6BBC08B-1235-40B2-8F43-0B3567D1722D}",["Source"]="local __passCache = {}; local function __ownsPass(userId, id) local key = tostring(userId) .. \034:\034 .. tostring(id); if __passCache[key] == nil then local ok, r = (ypcall or pcall)(function() return game:GetService(\034MarketplaceService\034):UserOwnsGamePassAsync(userId, id) end); __passCache[key] = ok and r or false end; return __passCache[key] end; --scripted by ConnorVIII, If you have questions, promblems or this breaks, PM me.\010script.Parent = game.ServerScriptService\010--[[\010WHAT YOU NEED TO DO.\010Line 8,9 and 10 are IMPORTANT! They instruct the script WHERE to find the tools, you need to make sure you write it ACCURACTLY!!\010Line 15,24 and 34 all have numbers. These numbers are the gamepass ID! You need to edit them for your personal gamepasses!\010--]]\010local ToolPath1 = game.Lighting[\034Green Plasma Gun\034]\010\010local MarketPlaceService = game:GetService(\034MarketplaceService\034)\010\010game.Players.PlayerAdded:connect(function(Player)\010\009\010\009local PlayerBoughtThisGamePass = __ownsPass(Player.UserId, 1683887)\010\009\009\010\009if ToolPath1 and PlayerBoughtThisGamePass then\010\009\009ToolPath1:Clone().Parent = Player:WaitForChild(\034StarterGear\034)\010\009\009if Player:WaitForChild(\034Backpack\034):FindFirstChild(\034Green Plasma Gun\034) == nil then\010\009\009\009ToolPath1:Clone().Parent = Player:WaitForChild(\034Backpack\034)\010\009\009end\010\009end\010\009\010\009\010\009 --OPTIONAL YOU CAN REMOVE IF WANTED  v\010\009 --OPTIONAL YOU CAN REMOVE IF WANTED ^\010\009\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
