T[#T+1]={id=1268,class="Script",parent=0,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="CharacterSpawn",["ScriptGuid"]="{62733E43-C64C-4DEB-BD8A-EC76F5D231E3}",["Source"]="--Part of code from The Zombie's Onslaught. This's a code that's required for yous game with NPC from NPCs Set 2016.\010local function __setup(Player)\010\009Player.TeamColor = BrickColor.new(\034Bright red\034)\010\009\010\009Player.CharacterAdded:connect(function(Character)\010\009\009local TEAM = Instance.new(\034BrickColorValue\034,Character) \010\009\009TEAM.Value = BrickColor.new(\034Bright red\034) \010\009\009TEAM.Name = \034TEAM\034\010\009\009--[[if Player.Name == \034Pokemonfan571\034 or Player.Name == \034elijah54403\034 or Player.Name == \034catnoo\034 or Player.Name == \034THEseriousBOSS\034 or Player.Name == \034ciijay\034 or Player.Name == \034Player1\034 or Player.Name == \034MegaGodPowers\034 or Player.Name == \034NoobyGames123\034 or Player.Name == \034KyleChu\034 or Player.Name == \034DIEGO12316\034 or Player.Name == \034IJustWantAHug\034 or Player.Name == \034vincelukeII\034 or Player.Name == \034Ashpatrick\034 or Player.Name == \034elijah54403\034 or Player.Name == \034iwishforpie1\034 or Player.Name == \034ItsPineappleTime\034 or game:GetService(\034GamePassService\034):PlayerHasPass(Player, 643374319) then\010\009\009if Player:FindFirstChild(\034PlayerGui\034) and Player:FindFirstChild(\034PlayerGui\034):FindFirstChild(\034Morph/Model Gui\034) == nil then\010\009\009local gui = script[\034Morph/Model Gui\034]:Clone()\010\009\009gui.Parent = Player--:FindFirstChild(\034PlayerGui\034)\010\009\009--gui.Enabled = true\010\009\009end\010\009end]]\010\009end)\010end\010game.Players.PlayerAdded:connect(__setup)\010-- [fix] players already in the game (and characters that already spawned) get set up too\010for _, Player in pairs(game.Players:GetPlayers()) do\010\009__setup(Player)\010\009if Player.Character and not Player.Character:FindFirstChild(\034TEAM\034) then\010\009\009local TEAM = Instance.new(\034BrickColorValue\034, Player.Character)\010\009\009TEAM.Value = BrickColor.new(\034Bright red\034)\010\009\009TEAM.Name = \034TEAM\034\010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
