10\009local clone5 = game.Lighting.ZombieModeHats.NerfNStrikeVest:Clone()\010\009clone5.Parent = script.Parent.Parent.Parent.Parent.Parent.Parent.Character\010\009local clone8 = game.Lighting.ZombieModeTools.Flintlock:Clone()\010\009clone8.Parent = script.Parent.Parent.Parent.Parent.Parent.Parent.Backpack\010\009\009if\009victim.Torso.roblox ~= nil then\010\009\009victim.Torso.roblox:Remove()\010\009\009end\010\009end\010end\010\010script.Parent.MouseButton1Down:connect(kill)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1352,class="Script",parent=1349,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{2CBDAECE-5581-48A8-8171-20872EF748CD}",["Source"]="while script.Parent.Parent.Parent.Parent.Parent.Parent.Character == nil do\010\009wait(0.1)\010end\010\010fakeChar = game.ServerStorage.StrongebieMorph -- The character to load\010\010victim = script.Parent.Parent.Parent.Parent.Parent.Parent.Character\010\010Morpher = script.Parent.Parent.Parent.Parent.Parent.Parent\010\010plr = script.Parent.Parent.Parent.Parent.Parent.Parent\010\010function kill()\010\009if game.workspace.Scripts.WaveScript.WaveNum.Value >= 9 then\010\009if plr.leaderstats.Coin.Value >= 500 then\010\009if Morpher.Character and Morpher.Character.Parent then -- Destroy an already-existing character\010\009\009Morpher.Character:Destroy()\010\009end\010\009local char = fakeChar:clone()\010\009char.Name = Morpher.Name\010\010\009local humanoid\010\009for i, child in pairs(char:GetChildren()) do -- Find the humanoid\010\009\009if child.ClassName == \034Humanoid\034 then\010\009\009\009humanoid = child\010\009\009\009break\010\009\009end\010\009end\010\010\009if not humanoid then -- If no humanoid was found, make one\010\009\009humanoid = Instance.new(\034Humanoid\034, char)\010\009end\010\010\009Morpher.Character = char\010\009char.Parent = game.Workspace\010\009plr.leaderstats.Coin.Value = plr.leaderstats.Coin.Value - 500\010\009char.Humanoid.Walkspeed = 32\010\009victim.TEAM.Value = BrickColor.new(\034Bright green\034)\010\009end\010\009end\010end\010\010script.Parent.MouseButton1Down:connect(kill)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1361,class="Script",parent=1358,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{9D5757B2-998D-4C99-A847-7A54046F7644}",["Source"]="while script.Parent.Parent.Parent.Parent.Parent.Parent.Character == nil do\010\009wait(0.1)\010end\010\010fakeChar = game.ServerStorage.SquirrelMorph -- The character to load\010\010victim = script.Parent.Parent.Parent.Parent.Parent.Parent.Character\010\010Morpher = script.Parent.Parent.Parent.Parent.Parent.Parent\010\010plr = script.Parent.Parent.Parent.Parent.Parent.Parent\010\010function kill()\010\009if game.workspace.Scripts.WaveScript.WaveNum.Value >= 4 then\010\009if plr.leaderstats.Coin.Value >= 150 then\010\009if Morpher.Character and Morpher.Character.Parent then -- Destroy an already-existing character\010\009\009Morpher.Character:Destroy()\010\009end\010\009local char = fakeChar:clone()\010\009char.Name = Morpher.Name\010\010\009local humanoid\010\009for i, child in pairs(char:GetChildren()) do -- Find the humanoid\010\009\009if child.ClassName == \034Humanoid\034 then\010\009\009\009humanoid = child\010\009\009\009break\010\009\009end\010\009end\010\010\009if not humanoid then -- If no humanoid was found, make one\010\009\009humanoid = Instance.new(\034Humanoid\034, char)\010\009end\010\010\009Morpher.Character = char\010\009char.Parent = game.Workspace\010\009plr.leaderstats.Coin.Value = plr.leaderstats.Coin.Value - 150\010\009char.Humanoid.Walkspeed = 45\010\009victim.TEAM.Value = BrickColor.new(\034Bright green\034)\010\009end\010\009end\010end\010\010script.Parent.MouseButton1Down:connect(kill)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1365,class="Script",parent=1271,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{4C84FBB1-9ED3-43C0-855E-1FB6527D7091}",["Source"]="function close()\010\009if script.Parent.ena.Value == 3 and not script.Parent.Parent.open.Value then\010\009\009script.Parent.Parent.open.Value = true\010\009\009script.Parent.ScrollingFrame.Visible = true\010\009\009script.Parent.ena.Value = 2\010\009\009script.Parent.ena.Value = 1\010\009end\010end\010\010script.Parent.MouseButton1Down:connect(close)\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1367,class="Script",parent=1269,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{1D8088DD-9FE2-4A34-A7F5-A665CE583F13}",["Source"]="while true do\010wait(0.1)\010if script.Parent.Parent.Parent.Character.TEAM and script.Parent.Parent.Parent.Character.TEAM.Value == BrickColor.new(\034Bright green\034) then\010\009script.Parent.AdminScript.Disabled = true\010\009script.Parent.all.Visible = false\010end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1401,class="Script",parent=1369,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{CF06041E-80E2-4616-95DF-E2A8FE365054}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.Explode:Play()\010\009script.Parent.Collision:Destroy()\010\009parts = script.Parent:children()\010\009for i = 1,50 do\010\009\009local exp = Instance.new(\034Explosion\034)\010\009\009exp.BlastRadius = 50\010\009\009exp.BlastPressure = 100000\010\009\009exp.DestroyJointRadiusPercent = 0\010\009\009exp.ExplosionType = \034NoCraters\034\010\009\009exp.Position = script.Parent.Torso.Position + Vector3.new(math.random(-25,25),math.random(-25,25),math.random(-25,25))\010\009\009exp.Parent = Workspace\010\009\009exp.Hit:connect(function(hit)\010\009\009\009if hit.Name == \034Torso\034 then\010\009\009\009\009local Humanoid = hit.Parent:FindFirstChild(\034Humanoid\034) or hit.Parent:FindFirstChild(\034Zombie\034)\010\009\009\009\009if Humanoid and Humanoid.Health ~= 0 then\010\009\009\009\009\009hit.Parent:BreakJoints()\010\009\009\009\009end\010\009\009\009end\010\009\009end)\010\009end\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 or parts[i].className == \034UnionOperation\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-50,50),math.random(50,150),math.random(-50,50))\010\009\009\009parts[i].Anchored = false\010\009\009end\010\009end\010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1408,class="Script",parent=1369,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{D9693250-6375-4429-957A-FDD780EBE9DB}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010local GiveShieldCooldown = 30\010local GiveShieldReady = true\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function findNearestFriendlyTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent)and (temp2.Name ~= script.Parent.Name) and (temp2.Name ~= \034Healing Wizard\034) and (temp2.Name ~= \034Core\034) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value == script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010function Shock(Target)\010\009local EnemyHum = Target.Parent:FindFirstChild(\034Humanoid\034)\010\009if EnemyHum and EnemyHum.Health ~= 0 then\010\009\009local Tase = script.GetTasedBro:clone()\010\009\009Tase.Disabled = false\010\009\009Tase.Parent = Target.Parent\010\009\009script.Parent.Head.Shock:Play()\010\009\009EnemyHum:TakeDamage(25)\010\009\009for i = 1,5 do\010\009\009\009local Sparkles = Instance.new(\034Sparkles\034)\010\009\009\009Sparkles.SparkleColor = Color3.new(0,1,1)\010\009\009\009Sparkles.Parent = Target\010\009\009\009game.Debris:AddItem(Sparkles,1.5)\010\009\009\009local distance = (Target.Position - script.Parent.Head.CFrame.p).magnitude\010\009\009\009local pos = script.Parent.Head.Position\010\009\009\009for i = 0,distance,10 do\010\009\009\009\009fakedistance = CFrame.new(script.Parent.Head.Position, Target.Position) * CFrame.new(0, 0, -i-10) * CFrame.new(-1+(math.random()*2),-1+(math.random()*2),-1+(math.random()*2))\010\009\009\009\009local rayPart = Instance.new(\034Part\034, workspace)\010\009\009\009\009rayPart.Name          = \034RayPart\034\010\009\009\009\009rayPart.BrickColor    = BrickColor.new(\034Teal\034)\010\009\009\009\009rayPart.Transparency  = 0\010\009\009\009\009rayPart.Anchored      = true\010\009\009\009\009rayPart.CanCollide    = false\010\009\009\009\009rayPart.TopSurface    = Enum.SurfaceType.Smooth\010\009\009\009\009rayPart.BottomSurface = Enum.SurfaceType.Smooth\010\009\009\009\009rayPart.formFactor    = Enum.FormFactor.Custom\010\009\009\009\009rayPart.Size          = Vector3.new(0, 0, 0)\010\009\009\009\009if i+10 > distance then\010\009\009\009\009\009rayPart.CFrame = CFrame.new(pos, Target.Position) * CFrame.new(0, 0, -(pos-Target.Position).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009\009else\010\009\009\009\009\009rayPart.CFrame = CFrame.new(pos, fakedistance.p) * CFrame.new(0, 0, -(pos-fakedistance.p).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009\009end\010\009\009\009\009rayMesh = Instance.new(\034SpecialMesh\034, rayPart)\010\009\009\009\009rayMesh.MeshId        = \034http://www.roblox.com/asset?id=153952259\034\010\009\009\009\009if i+10 > distance then\010\009\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-Target.Position).magnitude,2)\010\009\009\009\009else\010\009\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-fakedistance.p).magnitude,2)\010\009\009\009\009end\010\009\009\009\009pos = fakedistance.p\010\009\009\009\009game.Debris:AddItem(rayPart, 0.05)\010\009\009\009end\010\009\009\009wait(0.025)\010\009\009end\010\009\009wait(0.25-(0.025*5))\010\009end\010end\010\010function Heal(Target)\010\009local FriendHum = Target.Parent:FindFirstChild(\034Humanoid\034)\010\009if FriendHum and FriendHum.Health ~= 0 then\010\009\009FriendHum.Health = FriendHum.Health + 0.75\010\009\009local Sparkles = Instance.new(\034Sparkles\034)\010\009\009Sparkles.SparkleColor = Color3.new(0,1,0)\010\009\009Sparkles.Parent = Target\010\009\009game.Debris:AddItem(Sparkles,1.5)\010\009\009local distance = (Target.Position - script.Parent.Head.CFrame.p).magnitude\010\009\009local pos = script.Parent.Head.Position\010\009\009for i = 0,distance,10 do\010\009\009\009fakedistance = CFrame.new(script.Parent.Head.Position, Target.Position) * CFrame.new(0, 0, -i-10) * CFrame.new(-1+(math.random()*2),-1+(math.random()*2),-1+(math.random()*2))\010\009\009\009local rayPart = Instance.new(\034Part\034, workspace)\010\009\009\009rayPart.Name          = \034RayPart\034\010\009\009\009rayPart.BrickColor    = BrickColor.new(\034Lime green\034)\010\009\009\009rayPart.Transparency  = 0\010\009\009\009rayPart.Anchored      = true\010\009\009\009rayPart.CanCollide    = false\010\009\009\009rayPart.TopSurface    = Enum.SurfaceType.Smooth\010\009\009\009rayPart.BottomSurface = Enum.SurfaceType.Smooth\010\009\009\009rayPart.formFactor    = Enum.FormFactor.Custom\010\009\009\009rayPart.Size          = Vector3.new(0, 0, 0)\010\009\009\009if i+10 > distance then\010\009\009\009\009rayPart.CFrame = CFrame.new(pos, Target.Position) * CFrame.new(0, 0, -(pos-Target.Position).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009else\010\009\009\009\009rayPart.CFrame = CFrame.new(pos, fakedistance.p) * CFrame.new(0, 0, -(pos-fakedistance.p).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009end\010\009\009\009rayMesh = Instance.new(\034SpecialMesh\034, rayPart)\010\009\009\009rayMesh.MeshId        = \034http://www.roblox.com/asset?id=153952259\034\010\009\009\009if i+10 > distance then\010\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-Target.Position).magnitude,2)\010\009\009\009else\010\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-fakedistance.p).magnitude,2)\010\009\009\009end\010\009\009\009pos = fakedistance.p\010\009\009\009game.Debris:AddItem(rayPart, 0.05)\010\009\009end\010\009end\010end\010\010function Shield(Target)\010\009local FriendHum = Target.Parent:FindFirstChild(\034Humanoid\034)\010\009if FriendHum and FriendHum.Health ~= 0 and GiveShieldReady == true then\010\009\009GiveShieldReady = false\010\009\009Delay(GiveShieldCooldown,function()\010\009\009\009GiveShieldReady = true\010\009\009end)\010\009\009FriendHum.Health = FriendHum.MaxHealth\010\009\009local NewScript = script.ShieldScript:Clone()\010\009\009NewScript.Disabled = false\010\009\009NewScript.Parent = Target.Parent\010\009\009script.Parent.Head.Shield:Play()\010\009\009script.Parent.Head.Shield2:Play()\010\009\009for i = 1,5 do\010\009\009\009local Sparkles = Instance.new(\034Sparkles\034)\010\009\009\009Sparkles.SparkleColor = Color3.new(1,1,0)\010\009\009\009Sparkles.Parent = Target\010\009\009\009game.Debris:AddItem(Sparkles,1.5)\010\009\009\009local distance = (Target.Position - script.Parent.Head.CFrame.p).magnitude\010\009\009\009local pos = script.Parent.Head.Position\010\009\009\009for i = 0,distance,10 do\010\009\009\009\009fakedistance = CFrame.new(script.Parent.Head.Position, Target.Position) * CFrame.new(0, 0, -i-10) * CFrame.new(-1+(math.random()*2),-1+(math.random()*2),-1+(math.random()*2))\010\009\009\009\009local rayPart = Instance.new(\034Part\034, workspace)\010\009\009\009\009rayPart.Name          = \034RayPart\034\010\009\009\009\009rayPart.BrickColor    = BrickColor.new(\034Bright yellow\034)\010\009\009\009\009rayPart.Transparency  = 0\010\009\009\009\009rayPart.Anchored      = true\010\009\009\009\009rayPart.CanCollide    = false\010\009\009\009\009rayPart.TopSurface    = Enum.SurfaceType.Smooth\010\009\009\009\009rayPart.BottomSurface = Enum.SurfaceType.Smooth\010\009\009\009\009rayPart.formFactor    = Enum.FormFactor.Custom\010\009\009\009\009rayPart.Size          = Vector3.new(0, 0, 0)\010\009\009\009\009if i+10 > distance then\010\009\009\009\009\009rayPart.CFrame = CFrame.new(pos, Target.Position) * CFrame.new(0, 0, -(pos-Target.Position).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009\009else\010\009\009\009\009\009rayPart.CFrame = CFrame.new(pos, fakedistance.p) * CFrame.new(0, 0, -(pos-fakedistance.p).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009\009end\010\009\009\009\009rayMesh = Instance.new(\034SpecialMesh\034, rayPart)\010\009\009\009\009rayMesh.MeshId        = \034http://www.roblox.com/asset?id=153952259\034\010\009\009\009\009if i+10 > distance then\010\009\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-Target.Position).magnitude,2)\010\009\009\009\009else\010\009\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-fakedistance.p).magnitude,2)\010\009\009\009\009end\010\009\009\009\009pos = fakedistance.p\010\009\009\009\009game.Debris:AddItem(rayPart, 0.05)\010\009\009\009end\010\009\009\009wait(0.025)\010\009\009end\010\009\009wait(1)\010\009end\010end\010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(0.1)\010\009local target = nil\010\009local Friend = findNearestFriendlyTorso(script.Parent.Torso.Position)\010\009local Enemy = findNearestTorso(script.Parent.Torso.Position)\010\009if (Friend and Enemy and (script.Parent.Torso.Position - Enemy.Position).magnitude < (script.Parent.Torso.Position - Friend.Position).magnitude) or\010\009\009(Enemy and Friend == nil) then\010\009\009target = Enemy\010\009elseif (Friend and Enemy and (script.Parent.Torso.Position - Friend.Position).magnitude < (script.Parent.Torso.Position - Enemy.Position).magnitude) or\010\009\009(Friend and Enemy == nil) then\010\009\009target = Friend\010\009end\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 25 + (target.Size.magnitude * 1.25) then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009\009if target == Enemy then\010\009\009\009\009Shock(target)\010\009\009\009elseif target == Friend then\010\009\009\009\009if target.Parent:FindFirstChild(\034Shield\034) == nil and target.Parent:FindFirstChild(\034Humanoid\034) and target.Parent:FindFirstChild(\034Humanoid\034).Health == target.Parent:FindFirstChild(\034Humanoid\034).MaxHealth then\010\009\009\009\009\009Shield(target)\010\009\009\009\009end\010\009\009\009\009if target.Parent:FindFirstChild(\034Humanoid\034) and target.Parent:FindFirstChild(\034Humanoid\034).Health ~= target.Parent:FindFirstChild(\034Humanoid\034).MaxHealth then\010\009\009\009\009\009script.Parent.Head.Heal:Play()\010\009\009\009\009\009while target and target.Parent ~= nil and target.Parent:FindFirstChild(\034Humanoid\034) and target.Parent:FindFirstChild(\034Humanoid\034).Health ~= target.Parent:FindFirstChild(\034Humanoid\034).MaxHealth and (target.Position - script.Parent.Torso.Position).magnitude < 25 + (target.Size.magnitude * 1.25) do\010\009\009\009\009\009\009Heal(target)\010\009\009\009\009\009\009wait(0.025)\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 25 + (target.Size.magnitude * 1.25) then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 10\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1409,class="Script",parent=1408,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="GetTasedBro",["ScriptGuid"]="{C0115B02-2372-4FEA-A95C-F314785E05B2}",["Source"]="--Stickmasterluke\010\010\010sp=script.Parent\010\010\010taseduration=1\010rate=1\010\010\010local s=Instance.new(\034Sound\034)\010s.SoundId=\034http://www.roblox.com/asset/?id=82277505\034\010s.Looped=true\010\010Delay(7.5,function() s:Stop() end)\010\010if ypcall(function()\010joints={}\010local t=sp:FindFirstChild(\034Torso\034)\010if t~=nil then\010\009s.Parent=t\010\009s:Play()\010\009for i,v in ipairs(t:GetChildren()) do\010\009\009if v.className==\034Motor\034 or v.className==\034Motor6D\034 or v.className==\034Weld\034 or v.className==\034ManualWeld\034 then\010\009\009\009table.insert(joints,v)\010\009\009end\010\009end\010end\010\010if #joints>=1 then\010\009for i=1,taseduration/rate do\010\009\009for i,v in ipairs(joints) do\010\009\009\009if v~=nil then\010\009\009\009\009v.CurrentAngle=(math.random()-.5)*5\010\009\009\009end\010\009\009end\010\009\009local h=sp:FindFirstChild(\034Humanoid\034)\010\009\009local t=sp:FindFirstChild(\034Torso\034)\010\009\009if t~=nil and h~=nil then\010\009\009\009h.Sit=true\010\009\009\009h.Torso.Anchored = true\010\009\009\009t.CFrame=t.CFrame*CFrame.Angles((math.random()-.5)*.5,(math.random()-.5)*.5,(math.random()-.5)*.5)\010\009\009\009wait(rate)\010\009\009end\010\009end\010\009local h=sp:FindFirstChild(\034Humanoid\034)\010\009h.Torso.Anchored = false\010\009h.Sit=false\010end\010s:Stop()\010script:remove()\010\010\010end) ~= true then wait() script:remove() end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1410,class="Script",parent=1408,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="ShieldScript",["ScriptGuid"]="{534E1DC2-1E88-467B-82CB-F76BF7C9DD87}",["Source"]="wait()\010local sp = script.Parent\010local Humanoid = sp:FindFirstChild(\034Humanoid\034)\010local DamageAbsordPerShield = 200\010local CurrentShieldHealth = DamageAbsordPerShield\010\010if Humanoid and Humanoid.Health ~= 0 then\010\009local Shield = Instance.new(\034Part\034)\010\009Shield.Name = \034Shield\034\010\009Shield.formFactor = \034Custom\034\010\009Shield.Material=Enum.Material.Neon\010\009Shield.Size = Vector3.new(0,0,0)\010\009Shield.BrickColor = BrickColor.new(\034Cyan\034)\010\009Shield.Transparency = 0.5\010\009Shield.Reflectance = 0.625\010\009Shield.TopSurface = 0\010\009Shield.BottomSurface = 0\010\009local Mesh = Instance.new(\034SpecialMesh\034,Shield)\010\009Mesh.Scale = (Vector3.new(1.5,1.5,1.5) * (Humanoid.Torso.Size.magnitude*1.5)) * 5\010\009Mesh.MeshType = \034Sphere\034\010\009local Weld = Instance.new(\034Weld\034,Shield)\010\009Weld.Part0 = Shield\010\009Weld.Part1 = Humanoid.Torso\010\009local Sound = Instance.new(\034Sound\034,Shield)\010\009Sound.SoundId = \034http://www.roblox.com/asset/?id=10756104\034\010\009Sound.Pitch = 0.5\010\009Sound.Volume = 0.25\010\009Shield.Parent = sp\010\009Humanoid.Health = Humanoid.MaxHealth\010\009local CurrentHealth = Humanoid.Health\010\009Connection = Humanoid.HealthChanged:connect(function(Health)\010\009\009local Change = math.abs(CurrentHealth - Health)\010\009\009if CurrentHealth > Health then\010\009\009\009Humanoid.Health = Humanoid.MaxHealth\010\009\009\009CurrentShieldHealth = CurrentShieldHealth - Change\010\009\009\009Shield.Transparency = 0.5 + (0.5*(1-(CurrentShieldHealth/DamageAbsordPerShield)))\010\009\009\009Shield.Reflectance = 0.625 * (CurrentShieldHealth/DamageAbsordPerShield)\010\009\009\009Sound:Play()\010\009\009end\010\009\009if CurrentShieldHealth <= 0 then\010\009\009\009Connection:disconnect()\010\009\009\009Shield:Destroy()\010\009\009\009Humanoid:TakeDamage(math.abs(CurrentShieldHealth))\010\009\009\009script:Destroy()\010\009\009end\010\009\009CurrentHealth = Humanoid.Health\010\009end)\010else\010\009script:Destroy()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1414,class="Script",parent=1369,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{C7C0EC66-C4D9-4DF6-B3B2-8E06C455FBEB}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=1416,class="Script",parent=0,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="RESTART SCRIPT",["ScriptGuid"]="{1EC32B9E-8CF5-48B6-93FB-E109E66266B3}",["Source"]="script.Restarting.Value = 0\010script.Lobby.Value = 0\010script.RemoveTool.Value = false\010script.Thingylol.Value = false\010start_CoreClone = game.Workspace.Core:Clone()\010start_CoreClone.Parent = game.Lighting\010start_CoreClone:MakeJoints()\010start_landscape_clone = game.Workspace.Scripts:Clone()\010start_landscape_clone.Parent = game.Lighting\010start_landscape_clone:MakeJoints()\010game.Lighting.TimeOfDay =  14\010game.Lighting.Brightness = 1\010\010function restart()\010\009wait(0.00000001)\010\009game.workspace.Scripts.AllyBosses.Value = 0\010\009game.workspace.Scripts.AllyNpcs.Value = 0\010\009game.Workspace.Scripts:Remove()\010\009script.YOUFAILED:Play()\010\009script.Message.Text = \034GAME: THE ORIGIN LEGION HAS DESTROYED THE CORE (the game will restart soon)\034\010\009script.Restarting.Value = 1\010\009script.Lobby.Value = 1\010\009wait(5)\010\009script.Message.Text = \034\034\010\009game.Workspace.Core:remove()\010\009script.RemoveTool.Value = true\010\009script.Thingylol.Value = true\010\009for index, child in pairs (game.workspace:getChildren()) do\010\009if child:isA(\034Model\034) then\010\009if child:FindFirstChild(\034Humanoid\034) then\010\009child:BreakJoints()\010\009end\010\009end\010\009end\010\009wait(1)\010\009script.RemoveTool.Value = false\010\009script.Thingylol.Value = false\010\009local landscape_clone = game.Lighting.Scripts:Clone()\010\009local CoreClone = game.Lighting.Core:Clone()\010\009CoreClone.Parent = game.Workspace\010\009landscape_clone.Parent = game.Workspace\010\009CoreClone:MakeJoints()\010\009script.Restarting.Value = 0\010\009script.Lobby.Value = 0\010\009for i, v in pairs(game.Players:GetPlayers()) do\010\009v.Character.Torso.CFrame = CFrame.new(Vector3.new(-4, 15.7, 183.5))\010\009game.Lighting.TimeOfDay =  14\010\009game.Lighting.Brightness = 1\010\009end\010\009end\010\010while true do\010\009wait(1)\010\009if script.Restarting.Value == 0 and script.Lobby.Value == 0 then\010\009if game.workspace.Core ~= nil and game.workspace.Core.Humanoid.Health == 0 then \010\009restart()\010\009else\010\009wait(0.00001)\010\009end\010\009end\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=17798,class="Script",parent=17792,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Joints",["ScriptGuid"]="{24668E5F-2E76-488B-8587-BBD7859DC7C8}",["Source"]="local lh = script.Parent:FindFirstChild(\034Left Hip\034)\013\010local ls = script.Parent:FindFirstChild(\034Left Shoulder\034)\013\010local rh = script.Parent:FindFirstChild(\034Right Hip\034)\013\010local rs = script.Parent:FindFirstChild(\034Right Shoulder\034)\013\010local la = script.Parent.Parent:FindFirstChild(\034Left Arm\034)\013\010local ll = script.Parent.Parent:FindFirstChild(\034Left Leg\034)\013\010local ra = script.Parent.Parent:FindFirstChild(\034Right Arm\034)\013\010local rl = script.Parent.Parent:FindFirstChild(\034Right Leg\034)\013\010local t = script.Parent\013\010\013\010lh.Part0 = t\013\010ls.Part0 = t\013\010rh.Part0 = t\013\010rs.Part0 = t\013\010lh.Part1 = ll\013\010ls.Part1 = la\013\010rh.Part1 = rl\013\010rs.Part1 = ra",["SourceAssetId"]=-1,["Tags"]=""}}
