T[#T+1]={id=18102,class="Script",parent=18054,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="TooltipScript",["ScriptGuid"]="{BC8991FF-A291-46C0-89A7-5894ADB35A52}",["Source"]="local items = script.Parent.Frame:GetChildren()\013\010for i = 1, #items do\013\010\013\010function over()\013\010script.Parent.Parent.Tooltip.Visible = true\013\010script.Parent.Parent.Tooltip.ItemName.Text = items[i].ItemName.Value\013\010script.Parent.Parent.Tooltip.Price.Text = \034Cost: \034 ..items[i].Cost.Value.. \034 \034 ..items[i].Currency.Value\013\010script.Parent.Parent.Tooltip.Description.Text = items[i].Description.Value\013\010end\013\010\013\010function move(X,Y)\013\010script.Parent.Parent.Tooltip.Visible = true\013\010script.Parent.Parent.Tooltip.Position = UDim2.new(0,X+40,0,Y)\013\010end\013\010\013\010function off()\013\010script.Parent.Parent.Tooltip.Visible = false\013\010end\013\010\013\010items[i].BuyButton.MouseEnter:connect(over)\013\010items[i].BuyButton.MouseMoved:connect(move)\013\010items[i].BuyButton.MouseLeave:connect(off)\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18118,class="Script",parent=18117,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="TeleportToPart",["ScriptGuid"]="{18C39C5A-47D5-409F-822B-9AF19B3660D7}",["Source"]="--------------------\010--| WaitForChild |--\010--------------------\010\010-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local GamePassService = Game:GetService('GamePassService')\010local PlayersService = Game:GetService('Players')\010local DebrisService = Game:GetService('Debris')\010\010local Teleporter = script.Parent\010\010local GamePassIdObject = WaitForChild(script, 'GamePassId')\010local ExitPartObject = WaitForChild(script, 'ExitPart')\010\010local JustTouched = {}\010\010-----------------\010--| Functions |--\010-----------------\010\010-- When a player with the game pass touches the door, teleport them to the other side\010local function OnTouched(otherPart)\010\009if otherPart and otherPart.Parent and otherPart.Parent:FindFirstChild('Humanoid') then\010\009\009local player = PlayersService:GetPlayerFromCharacter(otherPart.Parent)\010\009\009if player and not JustTouched[player] then\010\009\009\009JustTouched[player] = time()\010\009\009\009if GamePassService:PlayerHasPass(player, GamePassIdObject.Value) then\010\009\009\009\009local character = player.Character\010\009\009\009\009if not character:FindFirstChild('JustTeleported') then\010\009\009\009\009\009local justTeleported = Instance.new('StringValue')\010\009\009\009\009\009justTeleported.Name = 'JustTeleported'\010\009\009\009\009\009DebrisService:AddItem(justTeleported, 0.3)\010\009\009\009\009\009justTeleported.Parent = character\010\009\009\009\009\009character:MoveTo(ExitPartObject.Value.Position)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010end\010\010-- Removes old entries in JustTouched\010local function RemoveOldTouches()\010\009for player, touchTime in pairs(JustTouched) do\010\009\009if time() > touchTime + 0.3 then\010\009\009\009JustTouched[player] = nil\010\009\009end\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Teleporter.Touched:connect(OnTouched)\010\010while true do\010\009RemoveOldTouches()\010\009wait(1/30)\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18122,class="Script",parent=18121,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="TeleportToPart",["ScriptGuid"]="{AA84FEC8-CF69-4779-AFC8-CF5E94319ED5}",["Source"]="--------------------\010--| WaitForChild |--\010--------------------\010\010-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local GamePassService = Game:GetService('GamePassService')\010local PlayersService = Game:GetService('Players')\010local DebrisService = Game:GetService('Debris')\010\010local Teleporter = script.Parent\010\010local GamePassIdObject = WaitForChild(script, 'GamePassId')\010local ExitPartObject = WaitForChild(script, 'ExitPart')\010\010local JustTouched = {}\010\010-----------------\010--| Functions |--\010-----------------\010\010-- When a player with the game pass touches the door, teleport them to the other side\010local function OnTouched(otherPart)\010\009if otherPart and otherPart.Parent and otherPart.Parent:FindFirstChild('Humanoid') then\010\009\009local player = PlayersService:GetPlayerFromCharacter(otherPart.Parent)\010\009\009if player and not JustTouched[player] then\010\009\009\009JustTouched[player] = time()\010\009\009\009if GamePassService:PlayerHasPass(player, GamePassIdObject.Value) then\010\009\009\009\009local character = player.Character\010\009\009\009\009if not character:FindFirstChild('JustTeleported') then\010\009\009\009\009\009local justTeleported = Instance.new('StringValue')\010\009\009\009\009\009justTeleported.Name = 'JustTeleported'\010\009\009\009\009\009DebrisService:AddItem(justTeleported, 0.3)\010\009\009\009\009\009justTeleported.Parent = character\010\009\009\009\009\009character:MoveTo(ExitPartObject.Value.Position)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010end\010\010-- Removes old entries in JustTouched\010local function RemoveOldTouches()\010\009for player, touchTime in pairs(JustTouched) do\010\009\009if time() > touchTime + 0.3 then\010\009\009\009JustTouched[player] = nil\010\009\009end\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010Teleporter.Touched:connect(OnTouched)\010\010while true do\010\009RemoveOldTouches()\010\009wait(1/30)\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18132,class="Script",parent=18126,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Joints",["ScriptGuid"]="{5F4625D9-0D56-43B3-AF76-F97AF21E28F1}",["Source"]="local lh = script.Parent:FindFirstChild(\034Left Hip\034)\013\010local ls = script.Parent:FindFirstChild(\034Left Shoulder\034)\013\010local rh = script.Parent:FindFirstChild(\034Right Hip\034)\013\010local rs = script.Parent:FindFirstChild(\034Right Shoulder\034)\013\010local la = script.Parent.Parent:FindFirstChild(\034Left Arm\034)\013\010local ll = script.Parent.Parent:FindFirstChild(\034Left Leg\034)\013\010local ra = script.Parent.Parent:FindFirstChild(\034Right Arm\034)\013\010local rl = script.Parent.Parent:FindFirstChild(\034Right Leg\034)\013\010local t = script.Parent\013\010\013\010lh.Part0 = t\013\010ls.Part0 = t\013\010rh.Part0 = t\013\010rs.Part0 = t\013\010lh.Part1 = ll\013\010ls.Part1 = la\013\010rh.Part1 = rl\013\010rs.Part1 = ra",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18145,class="Script",parent=18142,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="OldShop (new one is in server storage)",["ScriptGuid"]="{DD124B23-E5BB-4750-9EE6-EA998ECCDE39}",["Source"]="local Dialog = script.Parent\010\010Dialog.DialogChoiceSelected:connect(function(Player, Choice)\010if not Player then return end\010if Choice.Name == \034ShopChoice\034 and Player.PlayerGui:findFirstChild(\034ShopGui\034) == nil then\010local Gui = script.Parent.ShopGui:clone()\010Gui.Parent = Player.PlayerGui\010end\010end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
