T[#T+1]={id=18216,class="Script",parent=18147,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="BuyScript",["ScriptGuid"]="{7CF78080-E4F1-446A-B858-962EAEAEDCC7}",["Source"]="local items = script.Parent.Frame:GetChildren()\013\010for i = 1, #items do\013\010function buy()\013\010Cash = script.Parent.Parent.Parent.Parent.leaderstats:FindFirstChild(items[i].Currency.Value)\013\010h = Instance.new(\034Hint\034)\013\010h.Parent = script.Parent.Parent.Parent\013\010if Cash.Value >= items[i].Cost.Value then\013\010Cash.Value = Cash.Value - items[i].Cost.Value\013\010toolca = game.Lighting:FindFirstChild(items[i].ItemName.Value):Clone()\013\010toolcb = game.Lighting:FindFirstChild(items[i].ItemName.Value):Clone()\013\010toolca.Parent = script.Parent.Parent.Parent.Parent.Backpack\013\010toolcb.Parent = script.Parent.Parent.Parent.Parent.StarterGear\013\010print(\034Successfully bought!\034)\013\010h.Text = \034You have bought \034 ..items[i].ItemName.Value.. \034!\034\013\010wait(2)\013\010h:Remove()\013\010else print(\034Insufficient money!\034)\013\010h.Text = \034You don't have enough \034 ..items[i].Currency.Value.. \034!\034\013\010wait(2)\013\010h:Remove()\013\010end\013\010end\013\010items[i].BuyButton.MouseButton1Click:connect(buy)\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18217,class="Script",parent=18147,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="TooltipScript",["ScriptGuid"]="{E99E2ED2-388D-4ADD-A952-B89109BEF239}",["Source"]="local items = script.Parent.Frame:GetChildren()\013\010for i = 1, #items do\013\010\013\010function over()\013\010script.Parent.Parent.Tooltip.Visible = true\013\010script.Parent.Parent.Tooltip.ItemName.Text = items[i].ItemName.Value\013\010script.Parent.Parent.Tooltip.Price.Text = \034Cost: \034 ..items[i].Cost.Value.. \034 \034 ..items[i].Currency.Value\013\010script.Parent.Parent.Tooltip.Description.Text = items[i].Description.Value\013\010end\013\010\013\010function move(X,Y)\013\010script.Parent.Parent.Tooltip.Visible = true\013\010script.Parent.Parent.Tooltip.Position = UDim2.new(0,X+40,0,Y)\013\010end\013\010\013\010function off()\013\010script.Parent.Parent.Tooltip.Visible = false\013\010end\013\010\013\010items[i].BuyButton.MouseEnter:connect(over)\013\010items[i].BuyButton.MouseMoved:connect(move)\013\010items[i].BuyButton.MouseLeave:connect(off)\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18279,class="Script",parent=18241,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Server",["ScriptGuid"]="{53E2CD00-539B-4982-836F-526E59E6512D}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player\010local Character\010local Humanoid\010local TEAM\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local ChangeAmmoAndClip = script:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = script:WaitForChild(\034InflictTarget\034)\010local Grip2\010local Handle2\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,1)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local AmmoValue = script:FindFirstChild(\034Ammo\034) or Instance.new(\034NumberValue\034,script)\010AmmoValue.Name = \034Ammo\034\010AmmoValue.Value = Module.AmmoPerClip\010local ClipsValue = script:FindFirstChild(\034Clips\034) or Instance.new(\034NumberValue\034,script)\010ClipsValue.Name = \034Clips\034\010ClipsValue.Value = Module.LimitedClipEnabled and Module.Clips or 0\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009local IdleAnim = Instance.new(\034Animation\034,Tool)\010\009IdleAnim.Name = \034IdleAnim\034\010\009IdleAnim.AnimationId = \034rbxassetid://\034..(Module.DualEnabled and 53610688 or Module.IdleAnimationID)\010end\010if Module.FireAnimationID ~= nil then\010\009local FireAnim = Instance.new(\034Animation\034,Tool)\010\009FireAnim.Name = \034FireAnim\034\010\009FireAnim.AnimationId = \034rbxassetid://\034..Module.FireAnimationID\010end\010if Module.ReloadAnimationID ~= nil then\010\009local ReloadAnim = Instance.new(\034Animation\034,Tool)\010\009ReloadAnim.Name = \034ReloadAnim\034\010\009ReloadAnim.AnimationId = \034rbxassetid://\034..Module.ReloadAnimationID\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009local ShotgunClipinAnim = Instance.new(\034Animation\034,Tool)\010\009ShotgunClipinAnim.Name = \034ShotgunClipinAnim\034\010\009ShotgunClipinAnim.AnimationId = \034rbxassetid://\034..Module.ShotgunClipinAnimationID\010end\010\010ChangeAmmoAndClip.OnServerEvent:connect(function(Player,Ammo,Clips)\010\009AmmoValue.Value = Ammo\010\009ClipsValue.Value = Clips\010end)\010InflictTarget.OnServerEvent:connect(function(Player,TargetHumanoid,TargetTorso,Damage,Direction,Knockback,Lifesteal,FlamingBullet)\010\009if Player and TargetHumanoid and TargetHumanoid.Health ~= 0 and TargetTorso then\010\009\009while TargetHumanoid:FindFirstChild(\034creator\034) do\010\009\009\009TargetHumanoid.creator:Destroy()\010\009\009end\010\009\009local creator = Instance.new(\034ObjectValue\034,TargetHumanoid)\010\009\009creator.Name = \034creator\034\010\009\009creator.Value = Player\010\009\009game.Debris:AddItem(creator,5)\010\009\009TargetHumanoid:TakeDamage(Damage)\010\009\009if Knockback > 0 then\010\009\009\009TargetTorso.Velocity = Direction * Knockback\010\009\009end\010\009\009if Lifesteal > 0 and Humanoid and Humanoid.Health ~= 0 then\010\009\009\009Humanoid.Health = Humanoid.Health + (Damage*Lifesteal)\010\009\009end\010\009\009if FlamingBullet then\010\009\009\009local Debuff = TargetHumanoid.Parent:FindFirstChild(\034IgniteScript\034) or script.IgniteScript:Clone()\010\009\009\009Debuff.creator.Value = Player\010\009\009\009Debuff.Disabled = false\010\009\009\009Debuff.Parent = TargetHumanoid.Parent\010\009\009end\010\009end\010end)\010\010Tool.Equipped:connect(function()\010\009Player = game.Players:GetPlayerFromCharacter(Tool.Parent)\010\009Character = Tool.Parent\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009TEAM = Character:FindFirstChild(\034TEAM\034)\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010\010Tool.Unequipped:connect(function()\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18282,class="Script",parent=18279,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="IgniteScript",["ScriptGuid"]="{4ECFE10B-0E85-458E-AA32-8C883CA2B280}",["Source"]="local Humanoid = script.Parent:FindFirstChild(\034Humanoid\034)\010local Torso = script.Parent:FindFirstChild(\034Torso\034)\010local Fires = {}\010local FireDamagePerSecond = 5\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010if Humanoid and Torso then\010\009BurnSound = Instance.new(\034Sound\034)\010\009BurnSound.Name = \034BurnSound\034\010\009BurnSound.SoundId = \034http://www.roblox.com/asset/?id=32791565\034\010\009BurnSound.Parent = Torso\010\009BurnSound.Volume = 1\010\009game.Debris:AddItem(BurnSound,10)\010\009Delay(0,function()\010\009\009BurnSound:Play()\010\009end)\010\009for _,parts in pairs(script.Parent:GetChildren()) do\010\009\009if parts.className == \034Part\034 or parts.className == \034WedgePart\034 or parts.className == \034CornerWedgePart\034 then\010\009\009\009local firer = Instance.new(\034Fire\034)\010\009\009\009table.insert(Fires,firer)\010\009\009\009firer.Size = 5 + (parts.Size.magnitude*1.5)\010\009\009\009firer.Parent = parts\010\009\009end\010\009end\010\009while script.Duration.Value > 0 do\010\009\009wait(0.1)\010\009\009script.Duration.Value = script.Duration.Value - 0.1\010\009\009while Humanoid:FindFirstChild(\034creator\034) do\010\009\009\009Humanoid.creator:Destroy()\010\009\009end\010\009\009local Tag = script.creator:clone()\010\009\009Tag.Parent = Humanoid\010\009\009game.Debris:AddItem(Tag,5)\010\009\009Humanoid:TakeDamage(FireDamagePerSecond*0.1)\010\009end\010\009for _, Fire in pairs(Fires) do\010\009\009Fire.Enabled = false\010\009end\010\009wait(5)\010\009for _, Fire in pairs(Fires) do\010\009\009Fire:Destroy()\010\009end\010end\010wait()\010script:remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18285,class="Script",parent=18241,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="CHANGE LOG",["ScriptGuid"]="{2B4947EE-EB9C-4355-A47A-E92FB6C7167D}",["Source"]="--[[\010\009\010v1.0.6\010==================================================\010-Fixed a glitch which player can shooting even after died\010-Added \034ChargedShot\034 setting\010-Added \034Minigun\034 setting\010-Added \034Piercing\034 setting\010-Added \034FadeTime\034 setting\010-Updated \034BulletVisualizerScript\034. Replace an older one now!\010==================================================\010\009\010v1.0.5\010==================================================\010-Fixed a gun that shoot slower even you set \034FireRate\034 to lower\010-Added \034ShotgunReload\034 setting\010==================================================\010\009\010v1.0.4\010==================================================\010-Fixed VisualizeBulletScript and BulletVisualizerScript. Previously, it's a bug that doesn't show bullet for other player.\010-Fixed a bug which scope still in use even unequipped\010==================================================\010\009\010v1.0.3\010==================================================\010-Fixed a bug that you can reload a gun even unequip\010-Ray start position is now at Player's Head instead Gun Muzzle\010-Added \034DualEnabled\034 setting\010-Added Ammo Box for the gun\010-User can no longer use Scope while reloading\010==================================================\010\009\010v1.0.2\010==================================================\010-Fixed Bullet Visualizer that doesn't display fake bullet to other player\010-Fixed fake bullet still displayed even \034VisualizerEnabled\034 is disabled\010==================================================\010\009\010v1.0.1\010==================================================\010-Fixed reload\010-Ammo GUI will not show if AmmoPerClip is \034math.huge\034\010-Added Animation setting\010==================================================\010\009\010v1.0\010==================================================\010-First release\010==================================================\010\009\010--]]",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18290,class="Script",parent=18286,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="SwordScript",["ScriptGuid"]="{0719B20F-F2FB-46A7-8D12-12956E4B6780}",["Source"]="local DebrisService = Game:GetService(\034Debris\034)\010local PlayersService = Game:GetService('Players')\010local damage = 10\010\010local WALK_SPEED_BUFF = 0\010local TEAM = script.Parent.Handle:WaitForChild('TEAM')\010\010local SLASH_DAMAGE = 40.5\010local LUNGE_DAMAGE = 54\010local OVERHEAD_SLASH_DAMAGE = 90\010local CAN_CUT_TREES = true\010\010local Tool = script.Parent\010local Handle = Tool:WaitForChild('Handle')\010\010local KILL_FEED_ICON_URL = 'http://www.roblox.com/asset/?id=94746323'\010\010local MyCharacter\010local MyHumanoid\010\010local PlaySlash\010local PlayThrust\010local PlayOverhead\010\010--[[local ModifierManager = Workspace:WaitForChild('ModifierManager')\010local AddModifier = ModifierManager:WaitForChild('AddModifier')\010local RemoveModifier = ModifierManager:WaitForChild('RemoveModifier')]]\010\010local WalkSpeedMod;\010\010local AttackSequence = {}\010local SlashSound = Handle:WaitForChild('SlashSound')\010\010local OverheadSound = Handle:WaitForChild('OverheadSound')\010\010local LungeSound = Handle:WaitForChild('LungeSound')\010\010local UnsheathSound = Handle:WaitForChild('UnsheathSound')\010\010local HitSound = Handle:WaitForChild('HitSound')\010\010local IsCrystal = Tool:WaitForChild('IsCrystal')\010\010local HitCharacters\010\010local CreatorTag = nil\010\010local TreeNames = {\010\009Trees = true,\010\009PineTree = true,\010\009Tree = true,\010\009['Tree Full'] = true,\010\009['Tree Small'] = true,\010\009Pine = true\010}\010\010local function CheckInTreesModel(object)\010\009while object do\010\009\009if object:FindFirstChild('Humanoid') then return false end\010\009\009if TreeNames[object.Name] then return true end\010\009\009object = object.Parent\010\009end\009\010\009return false\010\009--return object and object.Parent and object.Parent.Name == 'Tree'\010\009--if object == nil or not Workspace:FindFirstChild('Trees') or not object.Parent or object.Parent.Name == 'Billboard' then return false end\010\009--return object:IsDescendantOf(Workspace.Trees)\010end\010\010function Blow(hit)\010\009if (hit.Parent == nil) then return end -- happens when bullet hits sword\010\009local humanoid = hit.Parent:findFirstChild(\034Humanoid\034)\010\009local vCharacter = Tool.Parent\010\009local vPlayer = game.Players:playerFromCharacter(vCharacter)\010\009local hum = vCharacter:findFirstChild(\034Humanoid\034) -- non-nil if tool held by a character\010\009if humanoid~=nil and humanoid ~= hum and hum ~= nil and HitCharacters and not HitCharacters[humanoid.Parent] and hum.Health>0 then\010\009\009if humanoid ~= nil and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009-- final check, make sure sword is in-hand\010\009\009local right_arm = vCharacter:FindFirstChild(\034Right Arm\034)\010\009\009if (right_arm ~= nil) then\010\009\009\009local joint = right_arm:FindFirstChild(\034RightGrip\034)\010\009\009\009if (joint ~= nil and (joint.Part0 == Handle or joint.Part1 == Handle)) then\010\009\009\009\009HitCharacters[humanoid.Parent] = true\010\009\009\009\009TagHumanoid(humanoid, vPlayer)\010\009\009\009\009HitSound:Play()\010\009\009\009\009humanoid:TakeDamage(damage)\010\009\009\009\009--[[local hitBindable = humanoid:FindFirstChild('Hit')\010\009\009\009\009if hitBindable then\010\009\009\009\009\009if IsCrystal.Value then\010\009\009\009\009\009\009HitSound:Play()\010\009\009\009\009\009end\010\009\009\009\009\009hitBindable:Invoke(damage, CreatorTag)\010\009\009\009\009else\010\009\009\009\009\009print(\034Could not find BindableFunction 'Hit'\034)\010\009\009\009\009end]]\010\009\009\009end\010\009\009end\010\009\009end\010\009elseif CheckInTreesModel(hit) and Tool.Enabled == false and CAN_CUT_TREES then\010\009\009hit:BreakJoints()\010\009\009if hit and not hit.Parent:FindFirstChild('Cut') then\010\009\009\009if hit.Parent and hit.Parent:FindFirstChild('Ball') then\010\009\009\009\009hit.Parent.Ball.Velocity =\010\009\009\009\009\009hit.Parent.Ball.Velocity +\010\009\009\009\009\009 CFrame.Angles(0, -math.rad(math.random(0, 180)), 0) * ((hit.CFrame.p - MyCharacter.Torso.CFrame.p).unit:Cross(Vector3.new(0,1,0)) * 15)\010\009\009\009\009local cut = Instance.new('BoolValue')\010\009\009\009\009cut.Value = true\010\009\009\009\009cut.Name = 'Cut'\010\009\009\009\009cut.Parent = hit.Parent\010\009\009\009else\010\009\009\009\009--print('No Ball')\010\009\009\009end\010\009\009end\010\009end\010end\010\010function TagHumanoid(humanoid, player)\010\009-- Add more tags here to customize what tags are available.\010\009while humanoid:FindFirstChild('creator') do\010\009\009humanoid:FindFirstChild('creator'):Destroy()\010\009end \010\009local creatorTag = Instance.new(\034ObjectValue\034)\010\009creatorTag.Value = player\010\009creatorTag.Name = \034creator\034\010\009DebrisService:AddItem(creatorTag, 1.5)\010\009creatorTag.Parent = humanoid\010\010\009--[[local weaponIconTag = Instance.new(\034StringValue\034)\010\009weaponIconTag.Value = KILL_FEED_ICON_URL\010\009weaponIconTag.Name = \034icon\034\010\009weaponIconTag.Parent = creatorTag]]\010end\010\010function Attack()\010\009damage = SLASH_DAMAGE\010\009SlashSound:play()\010\010\009if PlaySlash then\010\009\009PlaySlash.Value = not PlaySlash.Value\010\009end\010\009wait(0.25)\010end\010\010function OverheadSlash()\010\009damage = OVERHEAD_SLASH_DAMAGE\010\009if PlayOverhead then\010\009\009PlayOverhead.Value = not PlayOverhead.Value\010\009end\010\009--OverheadSound:Play()\010\009LungeSound:play()\010\009--[[local force = Instance.new(\034BodyVelocity\034)\010\009force.velocity = Vector3.new(0,10,0)\010\009DebrisService:AddItem(force, 0.5)\010\009force.Parent = Tool.Parent.Torso]]\010\009wait(0.75)\010end\010\010function Lunge()\010\009damage = LUNGE_DAMAGE\010\009--LungeSound:play()\010\009OverheadSound:Play()\010\009if PlayThrust then\010\009\009PlayThrust.Value = not PlayThrust.Value\010\009end\010\009wait(.2)\010\009swordOut()\010\009wait(.05)\010\009if force then\010\009\009force.Parent = nil\010\009end\010\009wait(.15)\010\009swordUp()\010\010\009damage = SLASH_DAMAGE\010end\010\010function swordUp()\010\009Tool.GripForward = Vector3.new(1,0,0)\010\009Tool.GripRight = Vector3.new(0,0,1)\010\009Tool.GripUp = Vector3.new(0,1,0)\010end\010\010function swordOut()\010\009Tool.GripForward = Vector3.new(0,-1,0)\010\009Tool.GripRight = Vector3.new(0,0,1)\010\009Tool.GripUp = Vector3.new(-1,0,0)\010end\010\010table.insert(AttackSequence, Attack)\010table.insert(AttackSequence, Lunge)\010table.insert(AttackSequence, OverheadSlash)\010\010local CurrentIndex = 1\010\010local LastAttackTime = tick()\010\010Tool.Enabled = true\010function OnActivated()\010\009if Tool.Parent:IsA('Model') and Tool.Enabled and MyCharacter and MyHumanoid and MyHumanoid.Health > 0 then\010\009\009Tool.Enabled = false\010\009\009HitCharacters = {[MyCharacter] = true}\010\009\009----------- ATTACK SEQUENCE CODE --------------\010\009\009local now = tick()\010\009\009if now - LastAttackTime > 1.5 then\010\009\009\009CurrentIndex = 1\010\009\009else\010\009\009\009CurrentIndex = CurrentIndex + 1\010\009\009end\010\009\009LastAttackTime = now\010\009\009if CurrentIndex > #AttackSequence then\010\009\009\009CurrentIndex = 1\010\009\009end\010\010\009  -----------------------------------------------\010\009\009AttackSequence[CurrentIndex]()\010\009\009if MyHumanoid == nil then\010\009\009\009print(\034Humanoid not found\034)\010\009\009\009return \010\009\009end\010\009\009HitCharacters = nil\010\009\009Tool.Enabled = true\010\009end\010end\010\010\010function OnEquipped()\010\009Delay(0.55, function() UnsheathSound:play() end)\010\009MyCharacter = Tool.Parent\010\009MyPlayer = game.Players:GetPlayerFromCharacter(MyCharacter)\010\009MyHumanoid = MyCharacter:FindFirstChild('Humanoid')\010\009--WalkSpeedMod = AddModifier:Invoke(MyPlayer, 'WalkSpeed', WALK_SPEED_BUFF)\010\009PlaySlash = Tool:WaitForChild('PlaySlash')\010\009PlayOverhead = Tool:WaitForChild('PlayOverhead')\010\009PlayThrust = Tool:WaitForChild('PlayThrust')\010\009CreatorTag.Value = PlayersService:GetPlayerFromCharacter(MyCharacter)\010end\010\010function OnUnequipped()\010\009if WalkSpeedMod then\010\009\009RemoveModifier:Invoke(MyPlayer, WalkSpeedMod)\010\009\009WalkSpeedMod = nil\010\009end\010end\010\010-- Also activate when the Action Button is pressed\010local function OnChildAdded(child)\010\009if child.Name == 'ActionButtonData' then\010\009\009child.Changed:connect(function(newValue)\010\009\009\009if string.sub(newValue, 1, 1) == 'v' then\010\009\009\009\009OnActivated()\010\009\009\009end\010\009\009end)\010\009end\010end\010\010-- Create the CreatorTag once at the start\010CreatorTag = Instance.new('ObjectValue')\010CreatorTag.Name = 'creator'\010local weaponNameTag = Instance.new('StringValue', CreatorTag)\010weaponNameTag.Name = 'weaponName'\010weaponNameTag.Value = Tool.Name\010local weaponIconTag = Instance.new('StringValue', CreatorTag)\010weaponIconTag.Name = 'weaponIcon'\010weaponIconTag.Value = KILL_FEED_ICON_URL\010\010Tool.Activated:connect(OnActivated)\010Tool.Equipped:connect(OnEquipped)\010Tool.Unequipped:connect(OnUnequipped)\010\010connection = Handle.Touched:connect(Blow)\010\010-- Listen for Action Button Data Object\010for _, child in pairs(Tool:GetChildren()) do\010\009OnChildAdded(child)\010end\010Tool.ChildAdded:connect(OnChildAdded)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18309,class="Script",parent=18240,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{8A12DF78-268E-40A0-91B6-2D50DC220CCC}",["Source"]="while true do\010\010v =  script.Parent:GetChildren()\010if script.Parent.Parent.Character.Morphed and script.Parent.Name == (\034Backpack\034) then\010\009for f = 1,#v do\010\009\009if v[f].className == \034Tool\034then\010\009\009\009\009v[f]:Remove()\010\009\009end\010\009end\010\009end\010\009wait(0.1)\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18310,class="Script",parent=18240,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ToolRemoverOnRestart",["ScriptGuid"]="{A255CA60-E24D-4131-9F35-8254792EF6ED}",["Source"]="while true do\010\010v = script.Parent.Parent.StarterGear:GetChildren()\010if game.workspace[\034RESTART SCRIPT\034].RemoveTool.Value == true then\010\009for f = 1,#v do\010\009\009if v[f].className == \034Tool\034 and v[f].Name ~= \034Pistol\034 and v[f].Name ~= \034Sword\034 and v[f].Name ~= \034Abomasnow\034 and v[f].Name ~= \034Green Plasma Gun\034 and v[f].Name ~= \034Doge Hammer\034 and v[f].Name ~= \034Xurkitree-47\034 and v[f].Name ~= \034Red Sword\034 and v[f].Name ~= \034GoldenGodlyMaul\034 and v[f].Name ~= \034SuperKatana\034 then\010\009\009\009\009v[f]:Remove()\010\009\009end\010\009end\010\009end\010\009wait(0.1)\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18317,class="Script",parent=18315,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MainScript",["ScriptGuid"]="{A2F1547D-71C2-4149-ABB0-FC9C76522B10}",["Source"]="-- Admin Powers GUI Version 1.0\013\010 \013\010 -- Last updated on the 18th February 2011.\013\010\013\010target = script.Parent.TargetName\013\010text = script.Parent.MessageText\013\010\013\010function kill_target()\013\010\009local fatality = game.Players:FindFirstChild(target.Text)\013\010\009if (fatality ~= nil) then\013\010\009\009fatality.Character:BreakJoints()\013\010\009end\013\010end\013\010\013\010function kick_target()\013\010\009local kicked = game.Players:FindFirstChild(target.Text)\013\010\009if (kicked ~= nil) then\013\010\009\009kicked:Remove()\013\010\009end\013\010end\013\010\013\010function ban_target()\013\010\009local banned = game.Players:FindFirstChild(target.Text)\013\010\009if (banned ~= nil) then\013\010\009\009local ban_script = script.BanScript:Clone()\013\010\009\009ban_script.Parent = game.Workspace\013\010\009\009ban_script.Name = \034\034 ..banned.Name.. \034BanScript\034\013\010\009\009ban_script.Banned.Value = banned.Name\013\010\009\009ban_script.Disabled = false\013\010\009end\013\010end\013\010\013\010function punish_target()\013\010\009local punished = game.Players:FindFirstChild(target.Text)\013\010\009if (punished ~= nil) then\013\010\009\009punished.Character.Parent = game.Lighting\013\010\009end\013\010end\013\010\013\010function output_text()\013\010\009game.Workspace.OutputText.Value = text.Text\013\010end\013\010\013\010function create_message()\013\010\009message = Instance.new(\034Message\034)\013\010\009message.Parent = game.Workspace\013\010\009message.Name = \034AdminMessage\034\013\010\009message.Text = text.Text\013\010\009wait(5)\013\010\009message:Remove()\013\010end\013\010\013\010\013\010script.Parent.KillButton.MouseButton1Click:connect(kill_target)\013\010script.Parent.KickButton.MouseButton1Click:connect(kick_target)\013\010script.Parent.BanButton.MouseButton1Click:connect(ban_target)\013\010script.Parent.PunishButton.MouseButton1Click:connect(punish_target)\013\010script.Parent.OutputButton.MouseButton1Click:connect(output_text)\013\010script.Parent.MessageButton.MouseButton1Click:connect(create_message)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18318,class="Script",parent=18317,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="BanScript",["ScriptGuid"]="{8B681F49-1437-4975-8053-86A89C784B30}",["Source"]="while true do\013\010\009wait(0.1)\013\010\009local player = game.Players:FindFirstChild(script.Banned.Value)\013\010\009if (player ~= nil) then\013\010\009\009player:Remove()\013\010\009end\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
