T[#T+1]={id=18424,class="Script",parent=18423,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="VisualizeBulletScript",["ScriptGuid"]="{CFCA9C16-9033-4E32-A86A-DD2E536E7166}",["Source"]="local RE = game.ReplicatedStorage.VisualizeBullet\010RE.OnServerEvent:connect(function(Player,Handle,MuzzleOffset,EndPos,MuzzleEffect,HitEffect,HitSound,ExplosiveData,BulletData,VisualizeExplosion,VisualizeEnabled)\010\009for _, TruePlayer in pairs(game.Players:GetPlayers()) do\010\009\009RE:FireClient(TruePlayer,Player,Handle,MuzzleOffset,EndPos,MuzzleEffect,HitEffect,HitSound,ExplosiveData,BulletData,VisualizeExplosion,VisualizeEnabled)\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18425,class="Script",parent=18423,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MercMaster",["ScriptGuid"]="{F33A5A68-4BCC-4E04-98E3-2B4AF8CCFD8A}",["Source"]="local Model1 = game.lighting.Allies[\034Noob\034]:Clone()\010local Model2 = game.lighting.Allies[\034Gunner\034]:Clone()\010local Model3 = game.lighting.Allies[\034Giant Noob\034]:Clone()\010local Model4 = game.lighting.Allies[\034Capper\034]:Clone()\010\010local Model5 = game.lighting.Allies[\034Deshuller\034]:Clone()\010local Model6 = game.lighting.Allies[\034Tank\034]:Clone()\010local Model7 = game.lighting.Allies[\034Aerial Bot\034]:Clone()\010local Model8 = game.lighting.Allies[\034Guardian Bot 2000\034]:Clone()\010\010local Model9 = game.lighting.Allies[\034Floating Fortress\034]:Clone()\010local Model10 = game.lighting.Allies[\034Mecha Tanker DX-5\034]:Clone()\010local Model11 = game.lighting.Allies[\034Destroyer\034]:Clone()\010local Model12 = game.lighting.Allies[\034Metal Monstrosity\034]:Clone()\010\010local ch1 = \034Noob\034\010local ch2 = \034Gunner\034\010local ch3 = \034Giant\034\010local ch4 = \034Capper\034\010\010local ch5 = \034Deshuller\034\010local ch6 = \034Tank\034\010local ch7 = \034ABot\034\010local ch8 = \034GUARD\034\010\010local ch9 = \034FF\034\010local ch10 = \034Mech\034\010local ch11 = \034Destroyer\034\010local ch12 = \034MM\034\010\010game.ReplicatedStorage.Merc.OnServerEvent:connect(function(plr,choice)\010\009--normal merc\010\009if choice.Name == ch1 then\010\009\009if plr.leaderstats.Coin.Value >= 20 then\010\009\009\009if game.workspace.Scripts.AllyNpcs.Value < 10 then\009\009\009\009\010\009\009\009game.workspace.Scripts.AllyNpcs.Value = game.workspace.Scripts.AllyNpcs.Value + 1\010\009\009\009local CloneModel = Model1:Clone()\010\009\009\009CloneModel:MakeJoints()\010\009\009\009CloneModel.Parent = game.Workspace\010\009\009\009CloneModel:MakeJoints()\010\009\009\009plr.leaderstats.Coin.Value = plr.leaderstats.Coin.Valu