T[#T+1]={id=18654,class="Script",parent=18428,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="thing",["ScriptGuid"]="{EF0B4DAD-05B0-4BAA-B690-2D4126E6634A}",["Source"]="while true do\010\010v =  script.Parent:GetChildren()\010\009for f = 1,#v do\010\009\009if v[f].className == \034Tool\034then\010\009\009\009\009v[f]:Remove()\010\009\009end\010\009end\010\009wait(0.1)\010end",["SourceAssetId"]=-1,["Tags"]=""}}
