T[#T+1]={id=18658,class="Script",parent=18655,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{461C146B-6374-49C9-8FCC-E595825784C0}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010\010\010damage=100\010range=2500\010damagedealthdebounch = false\010DeathDB = false\010\010meshes={114647745,114647773,114647802,114647836,114647881,114647920,114647944}\010standingmesh=114636624\010--Accidental mesh with no legs. Maybe someone wants it anyways -> 115975800\010\010local head=sp:WaitForChild(\034Head\034)\010local hum=sp:WaitForChild(\034Humanoid\034)\010--local ct=sp:WaitForChild(\034creator\034)\010local torso=sp:WaitForChild(\034Torso\034)\010local mesh=torso:WaitForChild(\034Mesh\034)\010local debris=game:GetService(\034Debris\034)\010\010alive=true\010currentmesh=0\010nextmove=0\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010torso.Touched:connect(function(hit)\010\009local TEAM = hit.Parent:FindFirstChild(\034TEAM\034)\010\009if hit and hit.Parent and hit.Parent.Name~=sp.Name and alive and TEAM and TEAM.Value~=sp.TEAM.Value then\010\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009if h~=nil then\010\009\009\009local plr=game.Players:GetPlayerFromCharacter(hit.Parent)\010\009\009\009if plr then\010\009\009\009\009--[[if plr==ct.Value then\010\009\009\009\009\009return\010\009\009\009\009end]]\010\009\009\009end\010\009\009\009if damagedealthdebounch == false then\010\009\009\009\009damagedealthdebounch = true\010\009\009\009\009torso.Bite:Play()\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009\009Delay(0.25,function() damagedealthdebounch = false end)\010\009\009\009end\010\009\009end\010\009end\010end)\010\010hum.Changed:connect(function(prop)\010\009if hum then\010\009\009if hum.Health<=0 then\010\009\009\009if DeathDB == true then return end\010\009\009\009DeathDB = true\010\009\009\009alive=false\010\009\009\009if torso then\010\009\009\009\009torso.Footstep:Stop()\010\009\009\009\009torso.Death:Play()\010\009\009\009\009torso.Anchored=true\010\009\009\009\009if head then\010\009\009\009\009\009head:remove()\010\009\009\009\009end\010\009\009\009\009for i = 1,4 do\010\009\009\009\009\009torso.CFrame = torso.CFrame * CFrame.Angles(0,0,math.rad(22.5))\010\009\009\009\009\009wait(0.0125)\010\009\009\009\009end\010\009\009\009\009wait(0.7)\010\009\009\009\009torso.Mesh.VertexColor = Vector3.new(1,0.75,0.75)\010\009\009\009\009wait(0.1)\010\009\009\009\009torso.Mesh.VertexColor = Vector3.new(1,0.5,0.5)\010\009\009\009\009wait(0.1)\010\009\009\009\009torso.Mesh.VertexColor = Vector3.new(1,0.25,0.25)\010\009\009\009\009wait(0.1)\010\009\009\009\009torso.Mesh.VertexColor = Vector3.new(1,0,0)\010\009\009\009\009hum:remove()\010\009\009\009\009--[[local f=Instance.new(\034Fire\034)\010\009\009\009\009f.Parent=torso]]\010\009\009\009\009wait(15)\010\009\009\009\009for i = 0,1,0.1 do\010\009\009\009\009\009torso.Transparency = i\010\009\009\009\009\009wait(0.1)\010\009\009\009\009end\010\009\009\009end\010\009\009\009sp:remove()\010\009\009end\010\009else\010\009\009alive=false\010\009\009sp:remove()\010\009end\010end)\010\010Spawn(function()\010\009while hum and hum.Health~=0 do\010\009\009if torso and mesh then\010\009\009\009if torso.Velocity.magnitude>3 then\010\009\009\009\009currentmesh=currentmesh+1\010\009\009\009\009mesh.MeshId=\034http://www.roblox.com/asset/?id=\034..tostring(meshes[(currentmesh%(#meshes))+1])\010\009\009\009\009if mesh.MeshId==\034http://www.roblox.com/asset/?id=114647944\034 or mesh.MeshId==\034http://www.roblox.com/asset/?id=114647836\034 then\010\009\009\009\009\009torso.Footstep:Play()\010\009\009\009\009end\010\009\009\009else\010\009\009\009\009mesh.MeshId=\034http://www.roblox.com/asset/?id=\034..tostring(standingmesh)\010\009\009\009end\010\009\009end\010\009\009wait(0.05)\010\009end\010end)\010\009\009\009--hum.WalkToPoint=point\010\009\009\009--[[if math.random()<.15 then\010\009\009\009\009hum.Jump=true\010\009\009\009end]]\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18665,class="Script",parent=18660,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="JumpScript",["ScriptGuid"]="{B7512DAC-8A45-4C9C-915D-A50140CFB704}",["Source"]="local sp = script.Parent\010local Humanoid = sp.Parent:WaitForChild(\034Humanoid\034)\010\010Humanoid.Jumping:connect(function()\010\009sp.Jump:Play()\010\009sp.Mesh.Scale = Vector3.new(1.5,5,1.5)\010\009for i = 1,5 do\010\009\009if i == 5 then\010\009\009\009sp.Mesh.Scale = Vector3.new(3,3,3)\010\009\009else\010\009\009\009sp.Mesh.Scale = sp.Mesh.Scale + ((Vector3.new(3,3,3)-sp.Mesh.Scale)/5)\010\009\009end\010\009\009wait(0.02)\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18669,class="Script",parent=18655,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="team changer",["ScriptGuid"]="{863EDFCB-7A47-4C5D-B7E6-ED2FBC58D127}",["Source"]="while true do\010if script.Parent.TEAM then\010script.Parent.TEAM.Value = BrickColor.new(\034Bright green\034)\010end\010wait(0.1)\010end\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18671,class="Script",parent=18655,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="thing",["ScriptGuid"]="{BC616CCD-B25C-4411-8658-F1B3D98FF181}",["Source"]="while true do\010\010v =  script.Parent:GetChildren()\010\009for f = 1,#v do\010\009\009if v[f].className == \034Tool\034then\010\009\009\009\009v[f]:Remove()\010\009\009end\010\009end\010\009wait(0.1)\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18727,class="Script",parent=18689,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Server",["ScriptGuid"]="{CE9FEFB7-7DFD-4276-9FDE-DF1FC9B368D0}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player\010local Character\010local Humanoid\010local TEAM\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local ChangeAmmoAndClip = script:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = script:WaitForChild(\034InflictTarget\034)\010local Grip2\010local Handle2\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,1)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local AmmoValue = script:FindFirstChild(\034Ammo\034) or Instance.new(\034NumberValue\034,script)\010AmmoValue.Name = \034Ammo\034\010AmmoValue.Value = Module.AmmoPerClip\010local ClipsValue = script:FindFirstChild(\034Clips\034) or Instance.new(\034NumberValue\034,script)\010ClipsValue.Name = \034Clips\034\010ClipsValue.Value = Module.LimitedClipEnabled and Module.Clips or 0\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009local IdleAnim = Instance.new(\034Animation\034,Tool)\010\009IdleAnim.Name = \034IdleAnim\034\010\009IdleAnim.AnimationId = \034rbxassetid://\034..(Module.DualEnabled and 53610688 or Module.IdleAnimationID)\010end\010if Module.FireAnimationID ~= nil then\010\009local FireAnim = Instance.new(\034Animation\034,Tool)\010\009FireAnim.Name = \034FireAnim\034\010\009FireAnim.AnimationId = \034rbxassetid://\034..Module.FireAnimationID\010end\010if Module.ReloadAnimationID ~= nil then\010\009local ReloadAnim = Instance.new(\034Animation\034,Tool)\010\009ReloadAnim.Name = \034ReloadAnim\034\010\009ReloadAnim.AnimationId = \034rbxassetid://\034..Module.ReloadAnimationID\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009local ShotgunClipinAnim = Instance.new(\034Animation\034,Tool)\010\009ShotgunClipinAnim.Name = \034ShotgunClipinAnim\034\010\009ShotgunClipinAnim.AnimationId = \034rbxassetid://\034..Module.ShotgunClipinAnimationID\010end\010\010ChangeAmmoAndClip.OnServerEvent:connect(function(Player,Ammo,Clips)\010\009AmmoValue.Value = Ammo\010\009ClipsValue.Value = Clips\010end)\010InflictTarget.OnServerEvent:connect(function(Player,TargetHumanoid,TargetTorso,Damage,Direction,Knockback,Lifesteal,FlamingBullet)\010\009if Player and TargetHumanoid and TargetHumanoid.Health ~= 0 and TargetTorso then\010\009\009while TargetHumanoid:FindFirstChild(\034creator\034) do\010\009\009\009TargetHumanoid.creator:Destroy()\010\009\009end\010\009\009local creator = Instance.new(\034ObjectValue\034,TargetHumanoid)\010\009\009creator.Name = \034creator\034\010\009\009creator.Value = Player\010\009\009game.Debris:AddItem(creator,5)\010\009\009TargetHumanoid:TakeDamage(Damage)\010\009\009if Knockback > 0 then\010\009\009\009TargetTorso.Velocity = Direction * Knockback\010\009\009end\010\009\009if Lifesteal > 0 and Humanoid and Humanoid.Health ~= 0 then\010\009\009\009Humanoid.Health = Humanoid.Health + (Damage*Lifesteal)\010\009\009end\010\009\009if FlamingBullet then\010\009\009\009local Debuff = TargetHumanoid.Parent:FindFirstChild(\034IgniteScript\034) or script.IgniteScript:Clone()\010\009\009\009Debuff.creator.Value = Player\010\009\009\009Debuff.Disabled = false\010\009\009\009Debuff.Parent = TargetHumanoid.Parent\010\009\009end\010\009end\010end)\010\010Tool.Equipped:connect(function()\010\009Player = game.Players:GetPlayerFromCharacter(Tool.Parent)\010\009Character = Tool.Parent\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009TEAM = Character:FindFirstChild(\034TEAM\034)\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010\010Tool.Unequipped:connect(function()\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18730,class="Script",parent=18727,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="IgniteScript",["ScriptGuid"]="{7BB06555-D05E-458F-B020-E2F3873BFED6}",["Source"]="local Humanoid = script.Parent:FindFirstChild(\034Humanoid\034)\010local Torso = script.Parent:FindFirstChild(\034Torso\034)\010local Fires = {}\010local FireDamagePerSecond = 5\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010if Humanoid and Torso then\010\009BurnSound = Instance.new(\034Sound\034)\010\009BurnSound.Name = \034BurnSound\034\010\009BurnSound.SoundId = \034http://www.roblox.com/asset/?id=32791565\034\010\009BurnSound.Parent = Torso\010\009BurnSound.Volume = 1\010\009game.Debris:AddItem(BurnSound,10)\010\009Delay(0,function()\010\009\009BurnSound:Play()\010\009end)\010\009for _,parts in pairs(script.Parent:GetChildren()) do\010\009\009if parts.className == \034Part\034 or parts.className == \034WedgePart\034 or parts.className == \034CornerWedgePart\034 then\010\009\009\009local firer = Instance.new(\034Fire\034)\010\009\009\009table.insert(Fires,firer)\010\009\009\009firer.Size = 5 + (parts.Size.magnitude*1.5)\010\009\009\009firer.Parent = parts\010\009\009end\010\009end\010\009while script.Duration.Value > 0 do\010\009\009wait(0.1)\010\009\009script.Duration.Value = script.Duration.Value - 0.1\010\009\009while Humanoid:FindFirstChild(\034creator\034) do\010\009\009\009Humanoid.creator:Destroy()\010\009\009end\010\009\009local Tag = script.creator:clone()\010\009\009Tag.Parent = Humanoid\010\009\009game.Debris:AddItem(Tag,5)\010\009\009Humanoid:TakeDamage(FireDamagePerSecond*0.1)\010\009end\010\009for _, Fire in pairs(Fires) do\010\009\009Fire.Enabled = false\010\009end\010\009wait(5)\010\009for _, Fire in pairs(Fires) do\010\009\009Fire:Destroy()\010\009end\010end\010wait()\010script:remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18733,class="Script",parent=18689,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="CHANGE LOG",["ScriptGuid"]="{33A7A932-195B-481E-938A-DBFB16CCEA8D}",["Source"]="--[[\010\009\010v1.0.6\010==================================================\010-Fixed a glitch which player can shooting even after died\010-Added \034ChargedShot\034 setting\010-Added \034Minigun\034 setting\010-Added \034Piercing\034 setting\010-Added \034FadeTime\034 setting\010-Updated \034BulletVisualizerScript\034. Replace an older one now!\010==================================================\010\009\010v1.0.5\010==================================================\010-Fixed a gun that shoot slower even you set \034FireRate\034 to lower\010-Added \034ShotgunReload\034 setting\010==================================================\010\009\010v1.0.4\010==================================================\010-Fixed VisualizeBulletScript and BulletVisualizerScript. Previously, it's a bug that doesn't show bullet for other player.\010-Fixed a bug which scope still in use even unequipped\010==================================================\010\009\010v1.0.3\010==================================================\010-Fixed a bug that you can reload a gun even unequip\010-Ray start position is now at Player's Head instead Gun Muzzle\010-Added \034DualEnabled\034 setting\010-Added Ammo Box for the gun\010-User can no longer use Scope while reloading\010==================================================\010\009\010v1.0.2\010==================================================\010-Fixed Bullet Visualizer that doesn't display fake bullet to other player\010-Fixed fake bullet still displayed even \034VisualizerEnabled\034 is disabled\010==================================================\010\009\010v1.0.1\010==================================================\010-Fixed reload\010-Ammo GUI will not show if AmmoPerClip is \034math.huge\034\010-Added Animation setting\010==================================================\010\009\010v1.0\010==================================================\010-First release\010==================================================\010\009\010--]]",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=18742,class="Script",parent=18741,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{04F46E1F-52C6-4301-8BC9-C9D31845851C}",["Source"]="wait(1)\010script.Parent:Remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
