a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009if animName == \034walk\034 then\010\009\009\009currentAnimTrack:Play(nil,nil,2)\010\009\009else\010\009\009\009currentAnimTrack:Play(transitionTime)\010\009\009end\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19310,class="Script",parent=19266,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HurtSound",["ScriptGuid"]="{C29A31D0-BBEF-4C69-9F85-808CC24E6342}",["Source"]="Humanoid = script.Parent:WaitForChild(\034Humanoid\034)\010Sound = Humanoid.Parent.Head:WaitForChild(\034Hurt\034)\010CurrentHealth = Humanoid.Health\010\010function HealthChanged(Health)\010\009local Change = math.abs(CurrentHealth - Health)\010\009if CurrentHealth > Health then\010\009\009Sound.Pitch = 0.95 + (math.random()*0.1)\010\009\009Sound:Play()\010\009end\010\009CurrentHealth = Humanoid.Health\010end\010\010Humanoid.HealthChanged:connect(HealthChanged)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19311,class="Script",parent=19266,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{61A4B3EF-0803-4DE2-B264-1614ED127873}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009game.workspace.Scripts.WaveScript.Dead_Zombies.Value = game.workspace.Scripts.WaveScript.Dead_Zombies.Value + 1\010\009wait(2.5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19312,class="Script",parent=19266,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="money kill",["ScriptGuid"]="{C7347C1B-6467-4125-BEFA-9116E50BE8C7}",["Source"]="local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then \010Leaderstats.Coin.Value = Leaderstats.Coin.Value + 30 --Change Money to the stat that is increased. \010wait(0.1) \010script:remove() \010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) ",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19313,class="Script",parent=19266,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="PP",["ScriptGuid"]="{F341CDFC-FEFA-4C32-B049-613B76F825A5}",["Source"]="print(\034Hello world!\034)\010\010Character = script.Parent\010Humanoid = Character.Humanoid\010Torso = Character.Torso\010\010local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then\010game:GetService(\034PointsService\034):AwardPoints(tag.Value.userId,30)\010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) \010\010",["SourceAssetId"]=-1,["Tags"]=""}}
