T[#T+1]={id=19378,class="Script",parent=19364,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="money kill",["ScriptGuid"]="{429551A8-B470-476A-BE50-5814FB687698}",["Source"]="local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then \010Leaderstats.Coin.Value = Leaderstats.Coin.Value + 30 --Change Money to the stat that is increased. \010wait(0.1) \010script:remove() \010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) ",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19380,class="Script",parent=19364,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{1434836A-A350-499D-81E7-457FEF9FFF15}",["Source"]="-- util\013\010\013\010function waitForChild(parent, childName)\013\010\009local child = parent:findFirstChild(childName)\013\010\009if child then return child end\013\010\009while true do\013\010\009\009child = parent.ChildAdded:wait()\013\010\009\009if child.Name==childName then return child end\013\010\009end\013\010end\013\010\013\010function newSound(id)\013\010\009local sound = Instance.new(\034Sound\034)\013\010\009sound.SoundId = id\013\010\009sound.archivable = false\013\010\009sound.Parent = script.Parent.Head\013\010\009return sound\013\010end\013\010\013\010-- declarations\013\010\013\010local sDied = newSound(\034http://www.roblox.com/asset/?id=49059793\034)\013\010--sDied.Pitch = 0.5\013\010sDied.Volume = 1\013\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\013\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\013\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\013\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\013\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\013\010sRunning.Looped = true\013\010\013\010local Figure = script.Parent\013\010local Head = waitForChild(Figure, \034Head\034)\013\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\013\010\013\010-- functions\013\010\013\010function onDied()\013\010\009sDied:Play()\013\010end\013\010\013\010function onState(state, sound)\013\010\009if state then\013\010\009\009sound:Play()\013\010\009else\013\010\009\009sound:Pause()\013\010\009end\013\010end\013\010\013\010function onRunning(speed)\013\010\009if speed>0 then\013\010\009\009sRunning:Play()\013\010\009else\013\010\009\009sRunning:Pause()\013\010\009end\013\010end\013\010\013\010-- connect up\013\010\013\010Humanoid.Died:connect(onDied)\013\010Humanoid.Running:connect(onRunning)\013\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\013\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\013\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\013\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19390,class="Script",parent=19384,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="RocketScript",["ScriptGuid"]="{2F99C95A-AEF2-44F6-A957-C26AE9374EB7}",["Source"]="local Rocket = script.Parent\010local TEAM = Rocket:WaitForChild('TEAM')\010\010r = game:service(\034RunService\034)\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010shaft = script.Parent\010position = shaft.Position\010damage = shaft.Damage.Value\010spawnpos = shaft.Position\010\010--script.Parent.Explosion.PlayOnRemove = true -- play explosion sound when projectile removed from game\010\010function fly()\010\009direction = shaft.CFrame.lookVector \010\009position = position + direction*4\010\009error = position - shaft.Position\010\009shaft.Velocity = 50*error\010end\010\010function blow(hit)\010\009connection:disconnect()\010\009local explosion = Instance.new(\034Explosion\034)\010\009explosion.Position = shaft.Position\010\009explosion.BlastRadius = 20\010\009explosion.BlastPressure = 0 \010\009shaft.Explosion:play()\010\009explosion.Hit:connect(function(part, distance) onPlayerBlownUp(part, distance) end)\010\009explosion.Parent = game.Workspace\010\009shaft.Transparency = 1\010\009wait(0.25)\010\009shaft:remove()\010end\010\010function onPlayerBlownUp(part, distance)\010\009if part.Name == \034Torso\034 then\010\009\009local humanoid = part.Parent:findFirstChild(\034Humanoid\034)\010\009\009if humanoid ~= nil and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then \010\009\009\009humanoid:TakeDamage(damage)\010\009\009end \010\009\009--tagHumanoid(humanoid, creator)\010\009end\010end\010\010function tagHumanoid(humanoid, creator)\010\009-- tag does not need to expire iff all explosions lethal\010\009\010\009if creator ~= nil then\010\009\009local new_tag = creator:clone()\010\009\009new_tag.Parent = humanoid\010\009\009\010\009end\010end\010\010function untagHumanoid(humanoid)\010\009if humanoid ~= nil then\010\009\009local tag = humanoid:findFirstChild(\034creator\034)\010\009\009if tag ~= nil then\010\009\009\010\009\009\009tag.Parent = nil\010\009\009end\010\009end\010end\010\010t, s = r.Stepped:wait()\010\010swoosh = script.Parent.Swoosh\010\010d = t + 10.0 - s\010connection = shaft.Touched:connect(blow)\010\010while (spawnpos - shaft.Position).magnitude < 950 do\010\009fly()\010\009t = r.Stepped:wait()\010end\010\010-- at max range\010script.Parent.Explosion.PlayOnRemove = true\010swoosh:stop()\010shaft:remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19391,class="Script",parent=19384,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Server Launcher",["ScriptGuid"]="{7D0073C6-0463-414E-887E-46CC60E4DED5}",["Source"]="local Rocket = Instance.new(\034Part\034)\010local Tool = script.Parent\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010Rocket.Locked = true\010Rocket.formFactor = \034Custom\034\010Rocket.BackSurface = 0\010Rocket.BottomSurface = 0\010Rocket.FrontSurface = 0\010Rocket.LeftSurface = 0\010Rocket.RightSurface = 0\010Rocket.TopSurface = 0\010Rocket.Size = Vector3.new(0.5,0.5,10)\010Rocket.BrickColor = BrickColor.new(\034Bright green\034)\010Rocket.CanCollide = false\010\010Tool.RocketScript:clone().Parent = Rocket\010Tool.Explosion:clone().Parent = Rocket\010Tool.Swoosh:clone().Parent = Rocket\010Tool.Parent.TEAM:Clone().Parent = Rocket\010\010\010function fire(vTarget)\010\010\009local vCharacter = Tool.Parent;\010\009\010\009local vHandle = Tool:findFirstChild(\034Handle\034)\010\009if vHandle == nil then\010\009\009print(\034Handle not found\034)\010\009\009return \010\009end\010\010\009local dir = vTarget - vHandle.Position\010\010\009dir = computeDirection(dir)\010\010\009local missile = Rocket:clone()\010\010\009local pos = vHandle.Position + (dir*10) --15\010\009\010\009--missile.Position = pos\010\009missile.CFrame = CFrame.new(pos,  pos + dir)\010\010\009local creator_tag = Instance.new(\034ObjectValue\034)\010\010\009local vPlayer = game.Players:playerFromCharacter(vCharacter)\010\010\009if vPlayer == nil then\010\009\009print(\034Player not found\034)\010\009else\010\009\009if (vPlayer.Neutral == false) then -- nice touch\010\009\009\009missile.BrickColor = vPlayer.TeamColor\010\009\009end\010\009end\010\010\009creator_tag.Value =vPlayer\010\009creator_tag.Name = \034creator\034\010\009creator_tag.Parent = missile\010\010\009damage = Instance.new(\034NumberValue\034,missile)\010\009damage.Name = \034Damage\034\010\009damage.Value = 20\010\009\010\009missile.RocketScript.Disabled = false\010\010\009missile.Parent = game.Workspace\010end\010\010function computeDirection(vec)\010\009local lenSquared = vec.magnitude * vec.magnitude\010\009local invSqrt = 1 / math.sqrt(lenSquared)\010\009return Vector3.new(vec.x * invSqrt, vec.y * invSqrt, vec.z * invSqrt)\010end\010\010Tool.Enabled = true\010function onActivated()\010\009if not Tool.Enabled then\010\009\009return\010\009end\010\010\009Tool.Enabled = false\010\010\009local character = Tool.Parent;\010\009local humanoid = character.Humanoid\010\009if humanoid == nil then\010\009\009print(\034Humanoid not found\034)\010\009\009return \010\009end\010\010\009local targetPos = script.Parent.Parent.Target.Value.Position\010\010\009fire(targetPos)\010\010\009Tool.Handle.Swoosh:play()\010\009wait(0.5)\010\010\009Tool.Enabled = true\010end\010\010while true do \010wait(0.0)\010\009if script.Parent.Parent.Attack.Value == true then \010\009\009onActivated()\010\009end \010end \010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19404,class="Script",parent=19403,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{AA9025DF-DBFD-4522-BF22-2383B99C0F03}",["Source"]="while true do\010\009if script.Parent.Parent.Velocity.magnitude > 7.5 then\010\009\009script.Parent.Enabled = true\010\009else\010\009\009script.Parent.Enabled = false\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
