udge\010\009\009LeftShoulder.DesiredAngle=desiredAngle - climbFudge\010\009\009RightHip.DesiredAngle=-desiredAngle\010\009\009LeftHip.DesiredAngle=-desiredAngle\010\009end\010end\010\010\010function attack(time,attackpos)\010\009if time-lastattack>=1 then\010\009\009local hit,pos=raycast(Torso.Position,(attackpos-Torso.Position).unit,attackrange)\010\009\009if hit and hit.Parent~=nil then\010\009\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local TEAM=hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h and TEAM and TEAM.Value~=sp.TEAM.Value then\010\009\009\009\009local creator=sp:FindFirstChild(\034creator\034)\010\009\009\009\009if creator then\010\009\009\009\009\009if creator.Value~=nil then\010\009\009\009\009\009\009if creator.Value~=game.Players:GetPlayerFromCharacter(h.Parent) then\010\009\009\009\009\009\009\009for i,oldtag in ipairs(h:GetChildren()) do\010\009\009\009\009\009\009\009\009if oldtag.Name==\034creator\034 then\010\009\009\009\009\009\009\009\009\009oldtag:remove()\010\009\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009creator:clone().Parent=h\010\009\009\009\009\009\009else\010\009\009\009\009\009\009\009return\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009\009if Anim then Anim:Play(nil,nil,1.5) end\010\009\009\009\009wait(0.5)\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009\009hitsound.Volume=1\010\009\009\009\009hitsound.Pitch=.75+(math.random()*.5)\010\009\009\009\009hitsound:Play()\010\009\009\009\009--[[if RightShoulder and LeftShoulder then\010\009\009\009\009\009RightShoulder.CurrentAngle=0\010\009\009\009\009\009LeftShoulder.CurrentAngle=0\010\009\009\009\009end]]\010\009\009\009end\010\009\009end\010\009\009lastattack=time\010\009end\010end\010\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010\010\010function populatehumanoids(mdl)\010\009if mdl.ClassName==\034Humanoid\034 then\010\009\009if mdl.Parent:FindFirstChild(\034TEAM\034) and mdl.Parent:FindFirstChild(\034TEAM\034).Value~=sp.TEAM.Value then\010\009\009\009table.insert(humanoids,mdl)\010\009\009end\010\009end\010\009for i2,mdl2 in ipairs(mdl:GetChildren()) do\010\009\009populatehumanoids(mdl2)\010\009end\010end\010\010--[[function playsound(time)\010\009nextsound=time+5+(math.random()*5)\010\009local randomsound=sounds[math.random(1,#sounds)]\010\009randomsound.Volume=.5+(.5*math.random())\010\009randomsound.Pitch=.5+(.5*math.random())\010\009randomsound:Play()\010end]]\010\010while sp.Parent~=nil and Humanoid and Humanoid.Parent~=nil and Humanoid.Health>0 and Torso and Head and Torso~=nil and Torso.Parent~=nil do\010\009local _,time=wait(0.25)--wait(1/3)\010\009humanoids={}\010\009populatehumanoids(game.Workspace)\010\009closesttarget=nil\010\009closestdist=sightrange\010\009local creator=sp:FindFirstChild(\034creator\034)\010\009for i,h in ipairs(humanoids) do\010\009\009if h and h.Parent~=nil then\010\009\009\009if h.Health>0 and h.Parent~=sp then\010\009\009\009\009local plr=game.Players:GetPlayerFromCharacter(h.Parent)\010\009\009\009\009if creator==nil or plr==nil or creator.Value~=plr then\010\009\009\009\009\009local t=h.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009if t~=nil then\010\009\009\009\009\009\009local dist=(t.Position-Torso.Position).magnitude\010\009\009\009\009\009\009if dist<closestdist then\010\009\009\009\009\009\009\009closestdist=dist\010\009\009\009\009\009\009\009closesttarget=t\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009if closesttarget~=nil then\010\009\009if not chasing then\010\009\009\009--playsound(time)\010\009\009\009chasing=true\010\009\009\009Humanoid.WalkSpeed=runspeed\010\009\009end\010\009\009Humanoid:MoveTo(closesttarget.Position+(Vector3.new(1,1,1)*(variance*((math.random()*2)-1))),closesttarget)\010\009\009if math.random()<.5 then\010\009\009\009attack(time,closesttarget.Position)\010\009\009end\010\009else\010\009\009if chasing then\010\009\009\009chasing=false\010\009\009\009Humanoid.WalkSpeed=wonderspeed\010\009\009end\010\009\009if time>nextrandom then\010\009\009\009nextrandom=time+3+(math.random()*5)\010\009\009\009local randompos=Torso.Position+((Vector3.new(1,1,1)*math.random()-Vector3.new(.5,.5,.5))*40)\010\009\009\009Humanoid:MoveTo(randompos,game.Workspace.Terrain)\010\009\009end\010\009end\010\009if time>nextsound then\010\009\009--playsound(time)\010\009end\010\009if time>nextjump then\010\009\009nextjump=time+7+(math.random()*5)\010\009\009Humanoid.Jump=true\010\009end\010\009animate(time)\010end\010\010wait(4)\010sp:remove() --Rest In Pizza\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19700,class="Script",parent=19681,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{63FA3C6C-0B36-4B11-97CD-5D6DC1BDD957}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxassetid://365003093\034)\010sDied.Pitch = 0.565\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19702,class="Script",parent=19681,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="HealthRegenerationScript",["ScriptGuid"]="{04AF6C3B-7131-4BD4-BE75-4B07D6A852FC}",["Source"]="-- Renegeration Script for the bot\013\010-- Renegerates about 1% of max hp per second until it reaches max health\013\010bot = script.Parent\013\010Humanoid = bot:FindFirstChild(\034Humanoid\034)\013\010\013\010local regen = false\013\010\013\010function regenerate() \013\010\009if regen then return end\013\010\009-- Lock this function until the regeneration to max health is complete by using a boolean toggle\013\010\009regen = true\013\010\009while Humanoid.Health < Humanoid.MaxHealth do\013\010\009\009local delta = wait(1)\013\010\009\009local health = Humanoid.Health\013\010\009\009if health > 0 and health < Humanoid.MaxHealth then \013\010\009\009\009-- This delta is for regenerating 1% of max hp per second instead of 1 hp per second\013\010\009\009\009delta = 0.01 * delta * Humanoid.MaxHealth\013\010\009\009\009health = health + delta\013\010\009\009\009Humanoid.Health = math.min(health, Humanoid.MaxHealth)\009\009\009\013\010\009\009end\013\010\009end\009\013\010\009-- release the lock, since the health is at max now, and if the character loses health again\013\010\009-- it needs to start regenerating \013\010\009regen = false\013\010end\009\013\010\013\010if Humanoid then \013\010\009-- Better than a while true do loop since it only fires when the health actually changes\013\010\009Humanoid.HealthChanged:connect(regenerate)\009\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19703,class="Script",parent=19681,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{C7B067E6-A982-4E62-9804-68F97A9DD2B4}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect