T[#T+1]={id=19836,class="Script",parent=19778,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="PP",["ScriptGuid"]="{8144F483-BE1C-447A-881B-153CE968FCAE}",["Source"]="print(\034Hello world!\034)\010\010Character = script.Parent\010Humanoid = Character.Humanoid\010Torso = Character.Torso\010\010local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then\010game:GetService(\034PointsService\034):AwardPoints(tag.Value.userId,1000)\010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) \010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19845,class="Script",parent=19778,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{7701B704-2604-45C4-8E51-F65D8943ED0E}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009game.workspace.Scripts.WaveScript.Dead_Zombies.Value = game.workspace.Scripts.WaveScript.Dead_Zombies.Value + 1\010\009wait(2.5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19846,class="Script",parent=19778,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="money kill",["ScriptGuid"]="{6C7E8939-36EE-42CB-9AF1-2C0B39663426}",["Source"]="local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then \010Leaderstats.Coin.Value = Leaderstats.Coin.Value + 1000 --Change Money to the stat that is increased. \010wait(0.1) \010script:remove() \010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) ",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19849,class="Script",parent=19848,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Firescript",["ScriptGuid"]="{DC2D95FD-19F2-4874-8343-5314B53CC415}",["Source"]="-- Made by Stickmasterluke\010 -- edited by fusroblox\010local GoreOn=false\010local TEAM = script.Parent.Handle.TEAM\010\010function WaitForChild(parent,child)\010\009while not parent:FindFirstChild(child) do print(\0342waiting for \034 .. child) wait() end\010\009return parent[child]\010end\010 \010local GunObject = {\010\009Tool = script.Parent,\010\009Handle = WaitForChild(script.Parent,'Handle'),\010\009check = true,\010\009\010\009GunDamage = 15, -- Base output damage per shot.\010\009FireRate = .12, -- How often the weapon can fire.\010\009Automatic = true, -- hold down to continue firing\010\009Range = 250, -- Max distance that the weapon can fire.\010\009Spread = 7, -- The bigger the spread, the more inaccurate the shots will be.\010\009ClipSize = 50, -- Shots in a clip\010\009ReloadTime = 3, -- Time it takes to reload the tool.\010\009StartingClips = 10, -- If you want infinit clips, remove the IntValue named \034Clips\034 from the tool.\010\009SegmentLength = 40, -- How long the shot segments are, or the speed of the shot.\010\009FadeDelayTime = 1/30,\010\009\010\009\010\009BarrelPos = CFrame.new(0, 0, - 1.2), -- L, F, U\010\009Rate = 1/30,\010\009--local Colors = {BrickColor.new(\034Bright red\034), BrickColor.new(\034Really red\034), BrickColor.new(\034Dusty Rose\034), BrickColor.new(\034Medium red\034)}\010\009Colors = {BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Mid gray\034), BrickColor.new(\034Medium stone grey\034), BrickColor.new(\034Dark stone grey\034)},\010\009FlashColors = {\034Medium red\034, \034Dusty Rose\034, \034Bright red\034, \034Really red\034},\010\009\010\009Reloading = false,\010\009Debris = game:GetService(\034Debris\034),\010\009Ammo,\010\009Clips,\010\009LaserObj,\010\009SparkEffect,\010\009ShellPart,\010\009--tool children\010\009DownVal=WaitForChild(script.Parent, 'Down'),\010\009AimVal=WaitForChild(script.Parent, 'Aim'),\010\009ReloadingVal=WaitForChild(script.Parent, 'Reloading'),\010\009DoFireAni = WaitForChild(script.Parent,'DoFireAni'),\010\009\010\009--handlechildren\010\009Fire,\010\009\010}\010\010--[[Member functions]]\010\010function GunObject:Initialize()\010\010\009self.Fire=WaitForChild(self.Handle, 'Fire')\010\009\010\009self.Ammo = self.Tool:FindFirstChild(\034Ammo\034)\010\009if self.Ammo ~= nil then\010\009\009self.Ammo.Value = self.ClipSize\010\009end\010\009self.Clips = self.Tool:FindFirstChild(\034Clips\034)\010\009if self.Clips ~= nil then\010\009\009self.Clips.Value = self.StartingClips\010\009end\010\009self.Tool.Equipped:connect(function()\010\009\009self.Tool.Handle.Fire:Stop()\010\009\009self.Tool.Handle.Reload:Stop()\010\009end)\010\009self.Tool.Unequipped:connect(function()\010\009\009self.Tool.Handle.Fire:Stop()\010\009\009self.Tool.Handle.Reload:Stop()\010\009end)\010\009self.LaserObj = Instance.new(\034Part\034)\010\009self.LaserObj.Name = \034Bullet\034\010\009self.LaserObj.Anchored = true\010\009self.LaserObj.CanCollide = false\010\009self.LaserObj.Shape = \034Block\034\010\009self.LaserObj.formFactor = \034Custom\034\010\009self.LaserObj.Material = Enum.Material.Plastic\010\009self.LaserObj.Locked = true\010\009self.LaserObj.TopSurface = 0\010\009self.LaserObj.BottomSurface = 0\010\010\009local tSparkEffect = Instance.new(\034Part\034)\010\009tSparkEffect.Name = \034Effect\034\010\009tSparkEffect.Anchored = false\010\009tSparkEffect.CanCollide = false\010\009tSparkEffect.Shape = \034Block\034\010\009tSparkEffect.formFactor = \034Custom\034\010\009tSparkEffect.Material = Enum.Material.Plastic\010\009tSparkEffect.Locked = true\010\009tSparkEffect.TopSurface = 0\010\009tSparkEffect.BottomSurface = 0\010\009self.SparkEffect=tSparkEffect\010\010\009local tshell = Instance.new('Part')\010\009tshell.Name='effect'\010\009tshell.FormFactor='Custom'\010\009tshell.Size=Vector3.new(1, 0.4, 0.33)\010\009tshell.BrickColor=BrickColor.new('Bright yellow')\010\009local tshellmesh=WaitForChild(script.Parent,'BulletMesh'):Clone()\010\009tshellmesh.Parent=tshell\010\009self.ShellPart = tshell\010\010\009self.DownVal.Changed:connect(function()\010\009\009while self.DownVal.Value and self.check and not self.Reloading do\010\009\009\009self.check = false\010\009\009\009local humanoid = self.Tool.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local plr1 = game.Players:GetPlayerFromCharacter(self.Tool.Parent)\010\009\009\009if humanoid ~= nil and plr1 ~= nil then\010\009\009\009\009if humanoid.Health > 0 then\010\009\009\009\009\009local spos1 = (self.Tool.Handle.CFrame * self.BarrelPos).p\010\009\009\009\009\009delay(0, function() self:SendBullet(spos1, self.AimVal.Value, self.Spread, self.SegmentLength, self.Tool.Parent, self.Colors[1], self.GunDamage, self.FadeDelayTime) end)\010\009\009\009\009else\010\009\009\009\009\009self.check = true\010\009\009\009\009\009break\010\009\009\009\009end\010\009\009\009else\010\009\009\009\009self.check = true\010\009\009\009\009break\010\009\009\009end\010\009\009\009wait(self.FireRate)\010\009\009\009self.check = true\010\009\009\009if not self.Automatic then\010\009\009\009\009break\010\009\009\009end\010\009\009end\010\009end)\010\010\009self.ReloadingVal.Changed:connect(function() if self.ReloadingVal.Value then self:Reload() end end)\010\010end\010\010\010\010function GunObject:Reload()\010\009self.Reloading = true\010\009self.ReloadingVal.Value = true\010\009if self.Clips ~= nil then\010\009\009if self.Clips.Value > 0 then\010\009\009\009self.Clips.Value = Clips.Value - 1\010\009\009else\010\009\009\009self.Reloading = false\010\009\009\009self.ReloadingVal.Value = false\010\009\009\009return\010\009\009end\010\009end\010\009self.Tool.Handle.Reload:Play()\010\009for i = 1, self.ClipSize do\010\009\009wait(self.ReloadTime/self.ClipSize)\010\009\009self.Ammo.Value = i\010\009end\010\009self.Reloading = false\010\009self.Tool.Reloading.Value = false\010end\010\010\010\010function GunObject:SpawnShell()\010\009local tshell=self.ShellPart:Clone()\010\009tshell.CFrame=self.Handle.CFrame\010\009tshell.Parent=Workspace\010\009game.Debris:AddItem(tshell,2)\010end\010\010function KnockOffHats(tchar)\010\009for _,i in pairs(tchar:GetChildren()) do\010\009\009if i:IsA('Hat') then\010\009\009\009i.Parent=game.Workspace\010\009\009end\010\009end\010end\010\010function KnockOffTool(tchar)\010\009for _,i in pairs(tchar:GetChildren()) do\010\009\009if i:IsA('Tool') then\010\009\009\009i.Parent=game.Workspace\010\009\009end\010\009end\010end\010\010function GunObject:SendBullet(boltstart, targetpos, fuzzyness, SegmentLength, ignore, clr, damage, fadedelay)\010\009if self.Ammo.Value <=0 then return end\010\009self.Ammo.Value = self.Ammo.Value - 1\010\009self:SpawnShell()\010\009self.Fire.Pitch = (math.random() * .5) + .75\010\009self.Fire:Play()\010\009self.DoFireAni.Value = not self.DoFireAni.Value\010\009print(self.Fire.Pitch)\010\009local boltdist = self.Range\010\009local clickdist = (boltstart - targetpos).magnitude\010\009local targetpos = targetpos + (Vector3.new(math.random() - .5, math.random() - .5, math.random() - .5) * (clickdist/100) * fuzzyness)\010\009local boltvec = (targetpos - boltstart).unit\010\009local totalsegments = math.ceil(boltdist/SegmentLength)\010\009local lastpos = boltstart\010\009for i = 1, totalsegments do\010\009\009local newpos = (boltstart + (boltvec * (boltdist * (i/totalsegments))))\010\009\009local segvec = (newpos - lastpos).unit\010\009\009local boltlength = (newpos - lastpos).magnitude\010\009\009local bolthit, endpos = CastRay(lastpos, segvec, boltlength, ignore, false)\010\009\009DrawBeam(lastpos, endpos, clr, fadedelay, self.LaserObj)\010\009\009if bolthit ~= nil then\010\009\009\009local h = bolthit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if h ~= nil then\010\009\009\009\009local plr = game.Players:GetPlayerFromCharacter(self.Tool.Parent)\010\009\009\009\009if plr ~= nil then\010\009\009\009\009\009local creator = Instance.new(\034ObjectValue\034)\010\009\009\009\009\009creator.Name = \034creator\034\010\009\009\009\009\009creator.Value = plr\010\009\009\009\009\009creator.Parent = h\010\009\009\009\009end\010\009\009\009\009if hit.Parent:FindFirstChild(\034BlockShot\034) then\010\009\009\009\009\009\009hit.Parent:FindFirstChild(\034BlockShot\034):Fire(newpos)\010\009\009\009\009\009\009delay(0, function() self:HitEffect(endpos, BrickColor.new('Medium stone grey'),5) end)\010\009\009\009\009else\010\009\009\009\009\009if(hit.Name=='Head') then\010\009\009\009\009\009\009KnockOffHats(hit.Parent)\010\009\009\009\009\009end\010\009\009\009\009\009if GoreOn then delay(0,function() self:HitEffect(endpos, BrickColor.new('Bright red'),20) end) end\010\009\009\009\009\009if h ~= nil and h.Parent:FindFirstChild(\034TEAM\034) and h.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009\009h:TakeDamage(damage)\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009else\010\009\009\009\009delay(0, function() self:HitEffect(endpos, BrickColor.new('Medium stone grey'),5) end)\010\009\009\009end\010\009\009\009break\010\009\009end\010\009\009lastpos = endpos\010\009\009wait(Rate)\010\009end\010\010\009if self.Ammo.Value < 1 then\010\009\009self:Reload()\010\009end\010\010end\010\010\010\010function GunObject:MakeSpark(pos,tcolor)\010\009local effect=self.SparkEffect:Clone()\010\009effect.BrickColor = tcolor\010\009effect.CFrame = CFrame.new(pos)\010\009effect.Parent = game.Workspace\010\009local effectVel = Instance.new(\034BodyVelocity\034)\010\009effectVel.maxForce = Vector3.new(99999, 99999, 99999)\010\009effectVel.velocity = Vector3.new(math.random() * 15 * SigNum(math.random( - 10, 10)), \009\009math.random() * 15 * SigNum(math.random( - 10, 10)), math.random() * 15 * SigNum(math.random( - 10, 10)))\010\009effectVel.Parent = effect\010\009effect.Size = Vector3.new(math.abs(effectVel.velocity.x)/30, math.abs(effectVel.velocity.y)/30, math.abs(effectVel.velocity.z)/30)\010\009wait()\010\009effectVel:Destroy()\010\009local effecttime = .5\010\009game.Debris:AddItem(effect, effecttime * 2)\010\009local startTime = time()\010\009while time() - startTime < effecttime do\010\009\009if effect ~= nil then\010\009\009\009effect.Transparency = (time() - startTime)/effecttime\010\009\009end\010\009\009wait()\010\009end\010\009if effect ~= nil then\010\009\009effect.Parent = nil\010\009end\010end\010\010function GunObject:HitEffect(pos,tcolor,numSparks)\010\009for i = 0, numSparks, 1 do\010\009\009Spawn(function() self:MakeSpark(pos,tcolor) end)\010\009end\010\009\010end\010\010--[[/Member functions]]\010\010\010--[[Static functions]]\010\010function Round(number, decimal)\010\009decimal = decimal or 0\010\009local mult = 10^decimal\010\009return math.floor(number * mult + .5)/mult\010end\010\010function SigNum(num)\010\009if num == 0 then return 1 end\010\009return math.abs(num)/num\010end\010\010--this is a little bad, but shouldn't really be part of the 'class' of the gun\010local Intangibles = {shock=1, bolt=1, bullet=1, plasma=1, effect=1, laser=1, handle=1, effects=1, flash=1,}\010function CheckIntangible(hitObj)\010\009print(hitObj.Name)\010\009return Intangibles[(string.lower(hitObj.Name))] or hitObj.Transparency == 1\010end\010\010function CastRay(startpos, vec, length, ignore, delayifhit)\010\009if length > 999 then\010\009\009length = 999\010\009end\010\009hit, endpos2 = game.Workspace:FindPartOnRay(Ray.new(startpos, vec * length), ignore)\010\009if hit ~= nil then\010\009\009if CheckIntangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit, endpos2 = CastRay(endpos2 + (vec * .01), vec, length - ((startpos - endpos2).magnitude), ignore, delayifhit)\010\009\009end\010\009end\010\009return hit, endpos2\010end\010\010function DrawBeam(beamstart, beamend, clr, fadedelay, templatePart)\010\009local dis = 2 --(beamstart - beamend).magnitude\010\009local tlaser=templatePart:Clone()\010\009tlaser.BrickColor = clr\010\009tlaser.Size = Vector3.new(.1, .1, dis + .2)\010\009tlaser.CFrame = CFrame.new((beamend+beamstart)/2, beamstart) * CFrame.new(0, 0, - dis/2)\010\009tlaser.Parent = game.Workspace\010\009game.Debris:AddItem(tlaser, fadedelay)\010end\010\010--[[/Static functions]]\010\010\010GunObject:Initialize()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19885,class="Script",parent=19884,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="SwordScript",["ScriptGuid"]="{81ECECA4-659D-4969-B6B9-F36015C9ED79}",["Source"]="-------- OMG HAX\010\010r = game:service(\034RunService\034)\010\010local TEAM = script.Parent.Handle:WaitForChild('TEAM')\010\010local damage = 15\010\010\010local slash_damage = 15\010\010\010sword = script.Parent.Handle\010Tool = script.Parent\010\010\010local SlashSound = Instance.new(\034Sound\034)\010SlashSound.SoundId = \034http://www.roblox.com/asset/?id=10548112\034\010SlashSound.Parent = sword\010SlashSound.Volume = 1\010\010\010local UnsheathSound = Instance.new(\034Sound\034)\010UnsheathSound.SoundId = \034http://www.roblox.com/asset/?id=10548108\034\010UnsheathSound.Parent = sword\010UnsheathSound.Volume = 1\010\010\010function blow(hit)\010\009local humanoid = hit.Parent:findFirstChild(\034Humanoid\034)\010\009local vCharacter = Tool.Parent\010\009local vPlayer = game.Players:playerFromCharacter(vCharacter)\010\009local hum = vCharacter:findFirstChild(\034Humanoid\034) -- non-nil if tool held by a character\010\009if humanoid~=nil and humanoid ~= hum and hum ~= nil then\010\009\009-- final check, make sure sword is in-hand\010\010\009\009local right_arm = vCharacter:FindFirstChild(\034Right Arm\034)\010\009\009if (right_arm ~= nil) then\010\009\009\009local joint = right_arm:FindFirstChild(\034RightGrip\034)\010\009\009\009if (joint ~= nil and (joint.Part0 == sword or joint.Part1 == sword)) then\010\009\009\009\009if humanoid ~= nil and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009tagHumanoid(humanoid, vPlayer)\010\009\009\009\009humanoid:TakeDamage(damage)\010\009\009\009\009wait(1)\010\009\009\009\009untagHumanoid(humanoid)\010\009\009\009end\010\009\009\009end\010\009\009end\010\009\009\010\010\010\009end\010end\010\010\010function tagHumanoid(humanoid, player)\010\009local creator_tag = Instance.new(\034ObjectValue\034)\010\009creator_tag.Value = player\010\009creator_tag.Name = \034creator\034\010\009creator_tag.Parent = humanoid\010end\010\010function untagHumanoid(humanoid)\010\009if humanoid ~= nil then\010\009\009local tag = humanoid:findFirstChild(\034creator\034)\010\009\009if tag ~= nil then\010\009\009\009tag.Parent = nil\010\009\009end\010\009end\010end\010\010\010function attack()\010\009damage = slash_damage\010\009SlashSound:play()\010\009local anim = Instance.new(\034StringValue\034)\010\009anim.Name = \034toolanim\034\010\009anim.Value = \034Slash\034\010\009anim.Parent = Tool\010end\010\010\010function swordUp()\010\009Tool.GripForward = Vector3.new(-1,0,0)\010\009Tool.GripRight = Vector3.new(0,1,0)\010\009Tool.GripUp = Vector3.new(0,0,1)\010end\010\010function swordOut()\010\009Tool.GripForward = Vector3.new(0,0,1)\010\009Tool.GripRight = Vector3.new(0,-1,0)\010\009Tool.GripUp = Vector3.new(-1,0,0)\010end\010\010\010\010Tool.Enabled = true\010\010function onActivated()\010\010\009if not Tool.Enabled then\010\009\009return\010\009end\010\010\009Tool.Enabled = false\010\010\009local character = Tool.Parent;\010\009local humanoid = character.Humanoid\010\009if humanoid == nil then\010\009\009print(\034Humanoid not found\034)\010\009\009return \010\009end\010\010\009\010\010\009attack()\010\010\009wait(1)\010\010\009Tool.Enabled = true\010end\010\010\010function onEquipped()\010\009UnsheathSound:play()\010end\010\010\010script.Parent.Activated:connect(onActivated)\010script.Parent.Equipped:connect(onEquipped)\010\010\010connection = sword.Touched:connect(blow)\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19900,class="Script",parent=19890,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{97EF01EF-9385-4584-91C7-56644D682C33}",["Source"]="--Made by Luckymaxer\010\010Tool = script.Parent\010Handle = Tool:WaitForChild(\034Handle\034)\010Mesh = Handle:WaitForChild(\034Mesh\034)\010\010local TEAM = Handle:WaitForChild('TEAM')\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010RunService = game:GetService(\034RunService\034)\010\010RbxUtility = LoadLibrary(\034RbxUtility\034)\010Create = RbxUtility.Create\010\010BaseUrl = \034http://www.roblox.com/asset/?id=\034\010\010BasePart = Create(\034Part\034){\010\009Material = Enum.Material.Plastic,\010\009FormFactor = Enum.FormFactor.Custom,\010\009TopSurface = Enum.SurfaceType.Smooth,\010\009BottomSurface = Enum.SurfaceType.Smooth,\010\009Size = Vector3.new(0.2, 0.2, 0.2),\010\009CanCollide = true,\010\009Locked = true,\010}\010\010BaseArrow = BasePart:Clone()\010BaseArrow.Name = \034Arrow\034\010BaseArrow.Size = Vector3.new(0.2, 0.2, 2.5)\010ArrowMesh = Create(\034SpecialMesh\034){\010\009MeshType = Enum.MeshType.FileMesh,\010\009MeshId = (BaseUrl .. \034283706782\034),\010\009TextureId = (BaseUrl .. \034283706893\034),\010\009Scale = Mesh.Scale,\010\009VertexColor = Vector3.new(1, 1, 1),\010\009Parent = BaseArrow\010}\010\010Grips = {\010\009Unequipped = CFrame.new(0.125, 0, -0.55, 0.9, -0, 0.45, 0, 1, 0, -0.45, 0, 0.9),\010\009Equipped = CFrame.new(0.125, 0, -0.55, 0.65, -0, 0.775, 0, 1, 0, -0.775, 0, 0.65),\010}\010\010Sounds = {\010\009Fire = Handle:WaitForChild(\034Fire\034),\010\009Hit = Handle:WaitForChild(\034Hit\034),\010\009Magic = Handle:WaitForChild(\034Magic\034),\010}\010\010Animations = {\010\009Hold = {Animation = Tool:WaitForChild(\034Hold\034), FadeTime = 0.75, Weight = nil, Speed = nil, Duration = nil},\010\009Idle = {Animation = Tool:WaitForChild(\034Idle\034), FadeTime = nil, Weight = nil, Speed = nil, Duration = nil},\010\009Fire = {Animation = Tool:WaitForChild(\034Fire\034), FadeTime = 0, Weight = nil, Speed = nil, Duration = nil},\010}\010\010ServerControl = (Tool:FindFirstChild(\034ServerControl\034) or Create(\034RemoteFunction\034){\010\009Name = \034ServerControl\034,\010\009Parent = Tool,\010})\010\010ClientControl = (Tool:FindFirstChild(\034ClientControl\034) or Create(\034RemoteFunction\034){\010\009Name = \034ClientControl\034,\010\009Parent = Tool,\010})\010\010Range = 350\010FireRate = 0.75\010\010Rate = (1 / 30)\010\010BarrelOffset = Vector3.new(-0.05, 0.5, -1.5)\010WindVec = Vector3.new(2, -1, 1).unit\010\010Damage = {\010\009Min = 15,\010\009Max = 30,\010}\010\010MaxCharge = 3\010\010Gravity = 196.20\010\010ChargeTable = {\010\009Charge = 0,\010\009FullyCharged = false,\010\009CalculatedCharge = nil,\010}\010\010Special = {\010\009Enabled = true,\010\009Active = false,\010\009ReloadTime = 20,\010}\010\010MouseDown = false\010ToolEquipped = false\010\010Handle.Transparency = 0\010Tool.Grip = Grips.Unequipped\010Tool.Enabled = true\010\010function IsTeamMate(Player1, Player2)\010\009return (Player1 and Player2 and not Player1.Neutral and not Player2.Neutral and Player1.TeamColor == Player2.TeamColor)\010end\010\010function TagHumanoid(humanoid, player)\010\009local Creator_Tag = Create(\034ObjectValue\034){\010\009\009Name = \034creator\034,\010\009\009Value = player,\010\009}\010\009Debris:AddItem(Creator_Tag, 2)\010\009Creator_Tag.Parent = humanoid\010end\010\010function UntagHumanoid(humanoid)\010\009for i, v in pairs(humanoid:GetChildren()) do\010\009\009if v:IsA(\034ObjectValue\034) and v.Name == \034creator\034 then\010\009\009\009v:Destroy()\010\009\009end\010\009end\010end\010\010function Clamp(Number, Min, Max)\010\009return math.max(math.min(Max, Number), Min)\010end\010\010function GetPercentage(Start, End, Number)\010\009return (((Number - Start) / (End - Start)) * 100)\010end\010\010function Round(Number, RoundDecimal)\010\009local WholeNumber, Decimal = math.modf(Number)\010\009return ((Decimal >= RoundDecimal and math.ceil(Number)) or (Decimal < RoundDecimal and math.floor(Number)))\010end\010\010function CheckTableForString(Table, String)\010\009for i, v in pairs(Table) do\010\009\009if string.find(string.lower(String), string.lower(v)) then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function CheckIntangible(Hit)\010\009local ProjectileNames = {\034Water\034, \034Arrow\034, \034Projectile\034, \034Effect\034, \034Rail\034, \034Laser\034, \034Bullet\034}\010\009if Hit and Hit.Parent then\010\009\009if ((not Hit.CanCollide or CheckTableForString(ProjectileNames, Hit.Name)) and not Hit.Parent:FindFirstChild(\034Humanoid\034)) then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function CastRay(StartPos, Vec, Length, Ignore, DelayIfHit)\010\009local Ignore = ((type(Ignore) == \034table\034 and Ignore) or {Ignore})\010\009local RayHit, RayPos, RayNormal = game:GetService(\034Workspace\034):FindPartOnRayWithIgnoreList(Ray.new(StartPos, Vec * Length), Ignore)\010\009if RayHit and CheckIntangible(RayHit) then\010\009\009if DelayIfHit then\010\009\009\009wait()\010\009\009end\010\009\009RayHit, RayPos, RayNormal = CastRay((RayPos + (Vec * 0.01)), Vec, (Length - ((StartPos - RayPos).magnitude)), Ignore, DelayIfHit)\010\009end\010\009return RayHit, RayPos, RayNormal\010end\010\010function DrawBeam(StartPos, EndPos, Color, FadeDelay)\010\009local Distance = (StartPos - EndPos).magnitude\010\009local Laser = BasePart:Clone()\010\009Laser.Name = \034Effect\034\010\009Laser.Size = Vector3.new(0.2, 0.2, 0.2)\010\009Laser.Transparency = 5\010\009Laser.BrickColor = Color\010\009Laser.Anchored = true\010\009Laser.CanCollide = false\010\009local Mesh = Create(\034SpecialMesh\034){\010\009\009MeshType = Enum.MeshType.Head,\010\009\009Scale = Vector3.new(1, (Distance * 5), 1),\010\009\009Parent = Laser,\010\009}\010\009Laser.CFrame = CFrame.new(StartPos, EndPos) * CFrame.new(0, 0, (-Distance / 2)) * CFrame.Angles((math.pi / 2), 0, 0)\010\009Debris:AddItem(Laser, (FadeDelay * 3))\010\009Laser.Parent = game:GetService(\034Workspace\034)\010\009local Frames = math.floor(FadeDelay / Rate)\010\009for Frame = 1, Frames do\010\009\009wait(Rate)\010\009\009local Percent = (Frame / Frames)\010\009\009Laser.CFrame = Laser.CFrame + WindVec * Rate\010\009\009Laser.Transparency = (0.5 + (Percent * 0.5))\010\009end\010\009wait(1)\010\009if Laser and Laser.Parent then\010\009\009Laser:Destroy()\010\009end\010end\010\010function CreateArrow()\010\009for i, v in pairs(Tool:GetChildren()) do\010\009\009if v:IsA(\034BasePart\034) and v ~= Handle then\010\009\009\009v:Destroy()\010\009\009end\010\009end\010\009DisplayArrow = BaseArrow:Clone()\010\009DisplayArrow.Name = \034DisplayArrow\034\010\009ArrowWeld = Create(\034Weld\034){\010\009\009Name = \034ArrowWeld\034,\010\009\009Part0 = LeftArm,\010\009\009Part1 = DisplayArrow,\010\009\009Parent = DisplayArrow,\010\009}\010\009DisplayArrow.Parent = Tool\010\009Spawn(function()\010\009\009InvokeClient(\034SetLocalTransparencyModifier\034, {Object = DisplayArrow, Transparency = 0, AutoUpdate = true})\010\009end)\010\009FocusArrow = RunService.Stepped:connect(function()\010\009\009if CheckIfAlive() and ToolEquipped and CheckIfArrowReady() then\010\009\009\009local ArrowCFrame = CFrame.new((LeftArm.CFrame * CFrame.new(0, -1, 0)).p, (Handle.CFrame * CFrame.new(0, 0, -2.25)).p) * CFrame.new(0, 0, -1.2)\010\009\009\009ArrowWeld.C0 = LeftArm.CFrame:toObjectSpace(ArrowCFrame)\010\009\009\009ArrowWeld.C1 = CFrame.new() * CFrame.Angles(math.pi, math.pi, (math.pi / 1))\010\009\009\009if (tick() - ChargeTable.Charge) >= MaxCharge and not ChargeTable.FullyCharged then\010\009\009\009\009ChargeTable.FullyCharged = true\010\009\009\009\009local Fire = Create(\034Fire\034){\010\009\009\009\009\009Color = Color3.new((85 / 255), (0 / 255), (127 / 255)),\010\009\009\009\009\009SecondaryColor = Color3.new((85 / 255), (0 / 255), (127 / 255)),\010\009\009\009\009\009Heat = 5,\010\009\009\009\009\009Size = 3.5,\010\009\009\009\009\009Enabled = true,\010\009\009\009\009\009Parent = DisplayArrow,\010\009\009\009\009}\010\009\009\009\009local Arrows = {CFrame.new(0, 0.5, 0), CFrame.new(0, -0.5, 0)}\010\009\009\009\009for i, v in pairs(Arrows) do\010\009\009\009\009\009local Arrow = DisplayArrow:Clone()\010\009\009\009\009\009local Weld = Arrow.ArrowWeld\010\009\009\009\009\009Weld.Part0 = DisplayArrow\010\009\009\009\009\009Weld.Part1 = Arrow\010\009\009\009\009\009Weld.C0 = v\010\009\009\009\009\009Arrow.Parent = Tool\010\009\009\009\009end\010\009\009\009end\010\009\009elseif FocusArrow then\010\009\009\009FocusArrow:disconnect()\010\009\009end\010\009end)\010end\010\010function Fire(StartPos, TargetPos, Damage)\010\009local FakeStartPos = (CFrame.new(StartPos) * CFrame.new(BarrelOffset)).p\010\009local Vec = (TargetPos - StartPos).unit\010\009local Drop = false\010\009local RayHit, RayPos = CastRay(StartPos, Vec, Range, {Character}, false)\010\009local FakeVec = (RayPos - FakeStartPos).unit\010\009local Arrow = BaseArrow:Clone()\010\009Arrow.Name = \034Effect\034\010\009Arrow.CanCollide = false\010\009if RayHit then\010\009\009local character = RayHit.Parent\010\009\009if character:IsA(\034Hat\034) or character:IsA(\034Tool\034) then\010\009\009\009character = character.Parent\010\009\009end\010\009\009if character == Character then\010\009\009\009return\010\009\009end\010\009\009local player = Players:GetPlayerFromCharacter(character)\010\009\009if player and IsTeamMate(Player, player) then\010\009\009\009return\010\009\009end\010\009\009local humanoid = character:FindFirstChild(\034Humanoid\034)\010\009\009if humanoid then\010\009\009\009if humanoid ~= nil and humanoid.Health > 0 and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009UntagHumanoid(humanoid)\010\009\009\009\009TagHumanoid(humanoid, Player)\010\009\009\009\009humanoid:TakeDamage(Damage)\010\009\009\009else\010\009\009\009\009--Drop = true\010\009\009\009end\010\009\009end\010\009\009local HitSound = Arrow:FindFirstChild(\034Hit\034)\010\009\009if HitSound then\010\009\009\009HitSound.Pitch = (math.random(80, 120) / 100)\010\009\009\009HitSound:Play()\010\009\009end\010\009\009local NewCF = CFrame.new(RayPos, (RayPos + FakeVec)) * CFrame.new(0, 0, (0.9 + (math.random(0, 1) * 0.4)))\010\009\009Arrow.CFrame = NewCF\010\009\009if not Drop then\010\009\009\009local StickWeld = Create(\034Weld\034){\010\009\009\009\009Part0 = RayHit,\010\009\009\009\009Part1 = Arrow,\010\009\009\009\009C0 = (RayHit.CFrame:inverse() * NewCF),\010\009\009\009\009C1 = (NewCF:inverse() * NewCF),\010\009\009\009\009Parent = Arrow,\010\009\009\009}\010\009\009\009if ChargeTable.FullyCharged then\010\009\009\009\009local CharacterStruck = character\010\009\009\009\009local Charge = {\010\009\009\009\009\009Min = 7,\010\009\009\009\009\009Max = 25,\010\009\009\009\009}\010\009\009\009\009local ChargeDamage = Round((GetPercentage(0, MaxCharge, ChargeTable.CalculatedCharge)), 0.5)\010\009\009\009\009ChargeDamage = Clamp(((ChargeDamage < Charge.Min and Charge.Min) or ChargeDamage), Charge.Min, Charge.Max)\009\009\009\009\010\009\009\009end\010\009\009\009if not Special.Enabled and Special.Active then\010\009\009\009\009Special.Active = false\010\009\009\009\009Spawn(function()\010\009\009\009\009\009local ArrowSpamRate = (1 / 30)\010\009\009\009\009\009for i = 1, math.random(30, 50) do\010\009\009\009\009\009\009if not ToolEquipped or not CheckIfAlive() then\010\009\009\009\009\009\009\009break\010\009\009\009\009\009\009end\010\009\009\009\009\009\009for ii = 1, math.random(1, 3) do\010\009\009\009\009\009\009\009local Accuracy = {Min = -6, Max = 6}\010\009\009\009\009\009\009\009for i, v in pairs(Accuracy) do\010\009\009\009\009\009\009\009\009Accuracy[i] = (v * 1000)\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009local AccuracyChance = Vector3.new((math.random(Accuracy.Min, Accuracy.Max) * 0.001), (math.random(Accuracy.Min, Accuracy.Max) * 0.001), (math.random(Accuracy.Min, Accuracy.Max) * 0.001))\010\009\009\009\009\009\009\009print(AccuracyChance)\010\009\009\009\009\009\009\009local SpawnPos = ((CFrame.new(TargetPos, StartPos).lookVector * 100) + Vector3.new(0, 75, 0))\010\009\009\009\009\009\009\009local EndPos = (TargetPos + AccuracyChance)\010\009\009\009\009\009\009\009Spawn(function()\010\009\009\009\009\009\009\009\009Fire(SpawnPos, EndPos, 12.5)\010\009\009\009\009\009\009\009end)\010\009\009\009\009\009\009end\010\009\009\009\009\009\009wait(ArrowSpamRate)\010\009\009\009\009\009end\010\009\009\009\009end)\010\009\009\009\009Delay(Special.ReloadTime, (function()\010\009\009\009\009\009Special.Enabled = true\010\009\009\009\009end))\010\009\009\009end\010\009\009else\010\009\009\009Arrow.Velocity = Vector3.new(0, 0, 0)\010\009\009\009Arrow.RotVelocity = Vector3.new(0, 0, 0)\010\009\009end\010\009else\010\009\009Arrow.CFrame = CFrame.new(RayPos, (RayPos + FakeVec))\010\009\009Arrow.Velocity = (FakeVec * 300)\010\009end\010\009\010\009Debris:AddItem(Arrow, (10 + (math.random() * 10)))\010\009Arrow.Parent = game:GetService(\034Workspace\034)\010\010\009Spawn(function()\010\009\009DrawBeam(FakeStartPos, RayPos, BrickColor.new(\034Institutional white\034), 0.5)\010\009end)\010\009\010\009for i, v in pairs(Tool:GetChildren()) do\010\009\009if v:IsA(\034BasePart\034) and v ~= Handle then\010\009\009\009v:Destroy()\010\009\009end\010\009end\010end\010\010function CreateDisplayArrow(CreateNew)\010\009for i, v in pairs(Tool:GetChildren()) do\010\009\009if v:IsA(\034BasePart\034) and v ~= Handle then\010\009\009\009v:Destroy()\010\009\009end\010\009end\010\009if not CreateNew then\010\009\009return\010\009end\010\009local DisplayArrow = BaseArrow:Clone()\010\009DisplayArrow.Name = \034DisplayArrow\034\010\009ArrowWeld = Create(\034Weld\034){\010\009\009Name = \034ArrowWeld\034,\010\009\009Part0 = Handle,\010\009\009Part1 = DisplayArrow,\010\009\009Parent = DisplayArrow,\010\009}\010\009DisplayArrow.Parent = Tool\010end\010\010function CheckIfAlive()\010\009return (((Character and Character.Parent and Humanoid and Humanoid.Parent and Humanoid.Health > 0 and Head and Head.Parent and Torso and Torso.Parent and RightArm and RightArm.Parent and LeftArm and LeftArm.Parent) and true) or false)\010end\010\010function CheckIfArrowReady()\010\009return (((DisplayArrow and DisplayArrow.Parent and ArrowWeld and ArrowWeld.Parent) and true) or false)\010end\010\010function Equipped()\010\009Character = Tool.Parent\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009Head = Character:FindFirstChild(\034Head\034)\010\009Torso = Character:FindFirstChild(\034Torso\034)\010\009RightArm = Character:FindFirstChild(\034Right Arm\034)\010\009LeftArm = Character:FindFirstChild(\034Left Arm\034)\010\009Player = Players:GetPlayerFromCharacter(Character)\010\009if not CheckIfAlive() then\010\009\009return\010\009end\010\009Tool.Grip = Grips.Unequipped\010\009Spawn(function()\010\009\009CreateDisplayArrow(false)\010\009\009InvokeClient(\034PlayAnimation\034, Animations.Idle)\010\009end)\010\009ToolEquipped = true\010end\010\010function Unequipped()\010\009for i, v in pairs(Tool:GetChildren()) do\010\009\009if v:IsA(\034BasePart\034) and v ~= Handle then\010\009\009\009v:Destroy()\010\009\009end\010\009end\010\009Tool.Grip = Grips.Unequipped\010\009Spawn(function()\010\009\009CreateDisplayArrow(true)\010\009\009for i, v in pairs(Animations) do\010\009\009\009InvokeClient(\034StopAnimation\034, v)\010\009\009end\010\009end)\010\009MouseDown = false\010\009ToolEquipped = false\010end\010\010function OnServerInvoke(player, mode, value)\010\009if player ~= Player or not ToolEquipped or not mode or not value or not CheckIfAlive() then\010\009\009return\010\009end\010\009if mode == \034KeyPress\034 then\010\009\009local Key = value.Key\010\009\009local Down = value.Down\010\009\009if Key == \034q\034 and Down and Special.Enabled and not Special.Active then\010\009\009\009Sounds.Magic:Play()\010\009\009\009Special.Enabled = false\010\009\009\009Special.Active = true\010\009\009end\010\009elseif mode == \034Button1Click\034 then\010\009\009local Down = value.Down\010\009\009if Down and not MouseDown and Tool.Enabled then\010\009\009\009MouseDown = true\010\009\009\009Tool.Grip = Grips.Equipped\010\009\009\009Spawn(function()\010\009\009\009\009InvokeClient(\034PlayAnimation\034, Animations.Hold)\010\009\009\009end)\010\009\009\009local FocusArrow\010\009\009\009ChargeTable.Charge = tick()\010\009\009\009ChargeTable.FullyCharged = false\010\009\009\009ChargeTable.CalculatedCharge = nil\010\009\009\009CreateArrow()\010\009\009\009while MouseDown do\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009local TargetPosition = InvokeClient(\034MousePosition\034)\010\009\009\009if TargetPosition and ToolEquipped and CheckIfAlive()then\010\009\009\009\009Tool.Enabled = false\010\009\009\009\009ChargeTable.CalculatedCharge = Clamp((tick() - ChargeTable.Charge), 0, MaxCharge)\010\009\009\009\009Sounds.Fire.Pitch = (0.6 + (0.8 * (ChargeTable.CalculatedCharge / MaxCharge)))\010\009\009\009\009Sounds.Fire:Play()\010\009\009\009\009local FireDamage = Round((GetPercentage(0, MaxCharge, ChargeTable.CalculatedCharge)), 0.5)\010\009\009\009\009FireDamage = Clamp(((FireDamage < Damage.Min and Damage.Min) or FireDamage), Damage.Min, Damage.Max)\010\009\009\009\009for i, v in pairs(Tool:GetChildren()) do\010\009\009\009\009\009if v:IsA(\034BasePart\034) and v.Name == \034DisplayArrow\034 then\010\009\009\009\009\009\009local Weld = v:FindFirstChild(\034ArrowWeld\034)\010\009\009\009\009\009\009if Weld and Weld.Part0 and Weld.Part1 and Weld.Part1 == v then\010\009\009\009\009\009\009\009Spawn(function()\010\009\009\009\009\009\009\009\009Fire(v.Position, (TargetPosition.Position + Vector3.new(0, (v.Position.Y - Handle.Position.Y), 0)), FireDamage)\010\009\009\009\009\009\009\009end)\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009\009for i, v in pairs(Tool:GetChildren()) do\010\009\009\009\009\009if v:IsA(\034BasePart\034) and v ~= Handle then\010\009\009\009\009\009\009v:Destroy()\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009\009Spawn(function()\010\009\009\009\009\009InvokeClient(\034StopAnimation\034, Animations.Hold)\010\009\009\009\009\009InvokeClient(\034PlayAnimation\034, Animations.Fire)\010\009\009\009\009end)\010\009\009\009end\010\009\009\009wait(FireRate)\010\009\009\009Tool.Enabled = true\010\009\009elseif not Down and MouseDown then\010\009\009\009Tool.Grip = Grips.Unequipped\010\009\009\009MouseDown = false\010\009\009end\010\009end\010end\010\010function InvokeClient(Mode, Value)\010\009local ClientReturn = nil\010\009pcall(function()\010\009\009ClientReturn = ClientControl:InvokeClient(Player, Mode, Value)\010\009end)\010\009return ClientReturn\010end\010\010CreateDisplayArrow(true)\010\010Tool.Equipped:connect(Equipped)\010Tool.Unequipped:connect(Unequipped)\010ServerControl.OnServerInvoke = OnServerInvoke",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19908,class="Script",parent=19907,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Global",["ScriptGuid"]="{0B60F43C-01C1-447F-90F4-B2CEC524C314}",["Source"]="local Tool = script.Parent\010local Player;\010local HealthVal = Tool.ShieldValue\010local TEAM = script.Parent.Handle:WaitForChild('TEAM')\010\010local DamagedCn, AttackCn;\010\010Tool.Equipped:connect(function()\010\009Player = game.Players:GetPlayerFromCharacter(Tool.Parent)\010\009local hum = Tool.Parent.Humanoid\010\009DamagedCn = hum.HealthChanged:connect(function()\010\009\009if Tool.ShieldState.Value then\010\009\009\009local toHeal = math.min(HealthVal.Value, hum.MaxHealth-hum.Health)\010\009\009\009hum.Health = hum.Health + toHeal\010\009\009\009HealthVal.Value = HealthVal.Value - toHeal\010\009\009end\010\009end)\010\009AttackCn = Tool.DamageBin.ChildAdded:connect(function(ch)\010\009\009local hum = ch.Value\010\009\009local p = game.Players:GetPlayerFromCharacter(hum.Parent)\010\009\009local dmg = tonumber(ch.Name)\010\009\009---------\010\009\009local tag = Instance.new('ObjectValue')\010\009\009tag.Name = 'creator'\010\009\009tag.Value = Player\010\009\009tag.Parent = hum\010\009\009---------\010\009\009if hum.Parent:FindFirstChild(\034TEAM\034) and hum.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009hum:TakeDamage(dmg)\010\009\009---------\010\009\009game.Debris:AddItem(tag, 2)\010\009\009game.Debris:AddItem(ch, 2)\010\009\009end\010\009end)\010end)\010\010Tool.Unequipped:connect(function() \010\009DamagedCn:disconnect()\010\009AttackCn:disconnect()\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=19910,class="Script",parent=19909,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="MotorizeRightGrip",["ScriptGuid"]="{6FD20EE1-2981-421C-A75B-2A3085B5740F}",["Source"]="function Create(ty)\013\010\009return function(data)\013\010\009\009local obj = Instance.new(ty)\013\010\009\009for k, v in pairs(data) do\013\010\009\009\009if type(k) == 'number' then\013\010\009\009\009\009v.Parent = obj\013\010\009\009\009else\013\010\009\009\009\009obj[k] = v\013\010\009\009\009end\013\010\009\009end\013\010\009\009return obj\013\010\009end\013\010end\013\010\013\010local Tool = script.Parent.Parent\013\010\013\010local armChildRemovedConn = nil\013\010local Motor6DGrip = nil\013\010local EquippedNum = 0\013\010\013\010Tool.Equipped:connect(function()\013\010\009EquippedNum = EquippedNum + 1\013\010\009local myEquip = EquippedNum\013\010\009--some vars\013\010\009local Player = game.Players:GetPlayerFromCharacter(Tool.Parent)\013\010\009local Character = Player.Character\013\010\013\010\009local rightarm = Character:FindFirstChild('Right Arm')\013\010\009if rightarm and rightarm:FindFirstChild('RightGrip') then\013\010\009\009local rightGrip = rightarm['RightGrip']\013\010\009\009local handle = rightGrip.Part1\013\010\013\010\009\009--kill my joint when the normal joint is removed\013\010\009\009--this must be done here so that the joint is removed \013\010\009\009--_right away_ after unequipping and the character doesn't \013\010\009\009--glitch up.\013\010\009\009local armChildRemovedConn = rightarm.ChildRemoved:connect(function(ch)\013\010\009\009\009if ch == rightGrip then\013\010\009\009\009\009Motor6DGrip:Remove()\013\010\009\009\009\009Motor6DGrip = nil\013\010\009\009\009\009--\013\010\009\009\009\009if handle and Character:FindFirstChild('Torso') then\013\010\009\009\009\009\009if Tool.Parent.Parent:IsA('Player') then\013\010\009\009\009\009\009\009--the sword has been deselected\013\010\009\009\009\009\009\009--put the sword far away so the user doesn't notice that the handle doesn't\013\010\009\009\009\009\009\009--update for about 0.1 seconds after selecting the tool.\013\010\009\009\009\009\009\009handle.CFrame = CFrame.new(100000, 100000, 100000)\013\010\009\009\009\009\009else\013\010\009\009\009\009\009\009--if in the workspace, position the handle where it should be dropped\013\010\009\009\009\009\009\009--use the size of the handle to make sure it's dropped far enough away\013\010\009\009\009\009\009\009handle.CFrame = Character.Torso.CFrame * CFrame.new(0, 0, -(handle.Size.magnitude+2))\013\010\009\009\009\009\009end\013\010\009\009\009\009end\013\010\009\009\009end\013\010\009\009end)\013\010\013\010\009\009--make my new joint\013\010\009\009Motor6DGrip = Create'Motor6D'{\013\010\009\009\009Name = 'RightGrip_Motor',\013\010\009\009\009Part0 = rightarm,\013\010\009\009\009Part1 = handle,\013\010\009\009}\013\010\009\009--kill the old weld\013\010\009\009rightGrip.Part1 = nil\013\010\009\009rightGrip.Part0 = nil\013\010\009\009Motor6DGrip.Parent = rightGrip.Parent\013\010\009end\013\010end)\013\010\013\010Tool.Unequipped:connect(function()\013\010\009EquippedNum = EquippedNum + 1\013\010\009if armChildRemovedConn then\013\010\009\009armChildRemovedConn:disconnect()\013\010\009\009armChildRemovedConn = nil\013\010\009end\013\010end)\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
