ck()\010\009\009local ChargePercent = (Functions.Clamp(Functions.GetPercentage(Charge.Start, (Charge.Start + Charge.Max), Now), 0, 100) * 0.01)\010\009\009if BarrelMotor then\010\009\009\009BarrelMotor.MaxVelocity = Functions.Clamp((BarrelSpeed.Max * ChargePercent), BarrelSpeed.Min, BarrelSpeed.Max)\010\009\009end\010\009\009FireSound.Volume = Functions.Clamp((1 * ChargePercent), 0, 1)\010\009\009FireSound.Pitch = Functions.Clamp((0.75 * ChargePercent), 0.4, 0.75)\010\009\009Shooting.Delay = (1 - Functions.Clamp((0.75 * ChargePercent), 0.1, 0.75))\010\009\009if (Now - Shooting.Tick) >= Shooting.Delay and ChargePercent >= 0.25 then\010\009\009\009Shooting.Tick = Now\010\009\009\009local MouseData = InvokeClient(\034MouseData\034)\010\009\009\009if MouseData then\010\009\009\009\009local TargetPosition = MouseData.Position\010\009\009\009\009Spawn(function()\010\009\009\009\009\009for i, v in pairs(BulletOffsets) do\010\009\009\009\009\009\009if not ToolEquipped or not CurrentlyEquipped or not CheckIfAlive() or not MouseDown then\010\009\009\009\009\009\009\009return\010\009\009\009\009\009\009end\010\009\009\009\009\009\009local Projectile = BaseProjectile:Clone()\010\009\009\009\009\009\009local Color = ((not Player.Neutral and Player.TeamColor) or Projectile.BrickColor)\010\009\009\009\009\009\009Projectile.BrickColor = Color\010\009\009\009\009\009\009for i, v in pairs(Projectile:GetChildren()) do\010\009\009\009\009\009\009\009if v:IsA(\034Light\034) then\010\009\009\009\009\009\009\009\009v.Color = Color.Color\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009end\010\009\009\009\009\009\009local SparksCopy = Particles.Sparks:Clone()\010\009\009\009\009\009\009SparksCopy.Color = ColorSequence.new(Color.Color, Color.Color)\010\009\009\009\009\009\009SparksCopy.Enabled = true\010\009\009\009\009\009\009SparksCopy.Parent = Projectile\010\009\009\009\009\009\009local StartPosition = (Handle.CFrame * CFrame.new(v.X, v.Y, (v.Z - (Projectile.Size.Y / 1.5))))