T[#T+1]={id=19944,class="Script",parent=19942,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="ProjectileManager",["ScriptGuid"]="{C8C23E12-EE64-4BC9-AA68-BB99D439A1DF}",["Source"]="--Made by Luckymaxer\010\010Model = script.Parent\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010local TEAM = script.TEAM\010\010FunctionsLibrary = script:FindFirstChild(\034Functions\034)\010ParticleScript = script:FindFirstChild(\034ParticleScript\034)\010Fire = script:FindFirstChild(\034EffectFire\034)\010\010RbxUtility = LoadLibrary(\034RbxUtility\034)\010Create = RbxUtility.Create\010\010Sounds = {\010\009Hit = script:FindFirstChild(\034Hit\034),\010}\010\010FadeRate = 0.025\010Rate = (1 / 15)\010\010Removing = false\010\010Values = {}\010for i, v in pairs(script:GetChildren()) do\010\009if string.find(string.lower(v.ClassName), string.lower(\034Value\034)) then\010\009\009Values[v.Name] = v\010\009end\010end\010\010function GetCreator()\010\009local Creator = Values.Creator.Value\010\009return (((Creator and Creator.Parent and Creator:IsA(\034Player\034)) and Creator) or nil)\010end\010\010function ManageProjectile(Part)\010\009local AlreadyHit = false\010\009local Creator = GetCreator()\010\009local Type = Part:FindFirstChild(\034Type\034)\010\009local Damage = Part:FindFirstChild(\034Damage\034)\010\009if not Type or not Type:IsA(\034StringValue\034) or not Damage or not Damage:IsA(\034NumberValue\034) then\010\009\009return\010\009end\010\009Part.Touched:connect(function(Hit)\010\009\009local Creator = GetCreator()\010\009\009if not Hit or not Hit.Parent or not Creator or AlreadyHit or Functions.CheckIntangible(Hit) then\010\009\009\009return\010\009\009end\010\009\009local character = Hit.Parent\010\009\009if character:IsA(\034Hat\034) then\010\009\009\009character = character.Parent\010\009\009end\010\009\009local player = Players:GetPlayerFromCharacter(character)\010\009\009if not player or (player and player ~= Creator and not Functions.IsTeamMate(Creator, player)) then\010\009\009\009local humanoid = character:FindFirstChild(\034Humanoid\034)\010\009\009\009if humanoid and humanoid.Health > 0 and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009Functions.UntagHumanoid(humanoid)\010\009\009\009\009Functions.TagHumanoid(humanoid, Creator)\010\009\009\009\009humanoid:TakeDamage(Damage.Value)\010\009\009\009\009if Type.Value == \034Fire\034 then\010\009\009\009\009\009local IgniteChance = math.random(1, 2)\010\009\009\009\009\009if ParticleScript and Fire and IgniteChance == 1 and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009\009\009local EffectFire = Hit:FindFirstChild(Fire.Name)\010\009\009\009\009\009\009if not EffectFire then\010\009\009\009\009\009\009\009EffectFire = Fire:Clone()\010\009\009\009\009\009\009\009EffectFire.Enabled = true\010\009\009\009\009\009\009\009local ParticleScriptCopy = ParticleScript:Clone()\010\009\009\009\009\009\009\009ParticleScriptCopy.Disabled = false\010\009\009\009\009\009\009\009ParticleScriptCopy.Parent = EffectFire\010\009\009\009\009\009\009\009local Duration = Create(\034NumberValue\034){\010\009\009\009\009\009\009\009\009Name = \034Duration\034,\010\009\009\009\009\009\009\009\009Parent = EffectFire,\010\009\009\009\009\009\009\009}\010\009\009\009\009\009\009end\010\009\009\009\009\009\009local Duration = EffectFire:FindFirstChild(\034Duration\034)\010\009\009\009\009\009\009if Duration and Duration:IsA(\034NumberValue\034) then\010\009\009\009\009\009\009\009Duration.Value = 4\010\009\009\009\009\009\009end\010\009\009\009\009\009\009EffectFire.Parent = Hit\010\009\009\009\009\009end\010\009\009\009\009elseif Type.Value == \034Projectile\034 then\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009\009if Type.Value == \0