T[#T+1]={id=20006,class="Script",parent=19959,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{F638B826-7F7C-408D-A24C-C2C86A06613B}",["Source"]="--Made by Luckymaxer\010\010Tool = script.Parent\010Handle = Tool:WaitForChild(\034Handle\034)\010Light = Handle:WaitForChild(\034Light\034)\010local TEAM = Handle.TEAM\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010\010CastLaser = Tool:WaitForChild(\034CastLaser\034):Clone()\010\010Modules = Tool:WaitForChild(\034Modules\034)\010Functions = require(Modules:WaitForChild(\034Functions\034))\010BaseUrl = \034http://www.roblox.com/asset/?id=\034\010\010ConfigurationBin = Tool:WaitForChild(\034Configuration\034)\010Configuration = {}\010Configuration = Functions.CreateConfiguration(ConfigurationBin, Configuration)\010\010ToolEquipped = false\010\010Remotes = Tool:WaitForChild(\034Remotes\034)\010\010Sounds = {\010\009Fire = Handle:WaitForChild(\034Fire\034),\010}\010\010BasePart = Instance.new(\034Part\034)\010BasePart.Shape = Enum.PartType.Block\010BasePart.Material = Enum.Material.Plastic\010BasePart.TopSurface = Enum.SurfaceType.Smooth\010BasePart.BottomSurface = Enum.SurfaceType.Smooth\010BasePart.FormFactor = Enum.FormFactor.Custom\010BasePart.Size = Vector3.new(0.2, 0.2, 0.2)\010BasePart.CanCollide = true\010BasePart.Locked = true\010BasePart.Anchored = false\010\010BaseRay = BasePart:Clone()\010BaseRay.Name = \034Ray\034\010BaseRay.BrickColor = BrickColor.new(\034New Yeller\034)\010BaseRay.Material = Enum.Material.SmoothPlastic\010BaseRay.Size = Vector3.new(0.2, 0.2, 0.2)\010BaseRay.Anchored = true\010BaseRay.CanCollide = false\010BaseRayMesh = Instance.new(\034SpecialMesh\034)\010BaseRayMesh.Name = \034Mesh\034\010BaseRayMesh.MeshType = Enum.MeshType.Brick\010BaseRayMesh.Scale = Vector3.new(0.2, 0.2, 1)\010BaseRayMesh.Offset = Vector3.new(0, 0, 0)\010BaseRayMesh.VertexColor = Vector3.new(1, 1, 1)\010BaseRayMesh.Parent = BaseRay\010\010ServerControl = (Remotes:FindFirstChild(\034ServerControl\034) or Instance.new(\034RemoteFunction\034))\010ServerControl.Name = \034ServerControl\034\010ServerControl.Parent = Remotes\010\010ClientControl = (Remotes:FindFirstChild(\034ClientControl\034) or Instance.new(\034RemoteFunction\034))\010ClientControl.Name = \034ClientControl\034\010ClientControl.Parent = Remotes\010\010Light.Enabled = false\010Tool.Enabled = true\010\010function RayTouched(Hit, Position)\010\009if not Hit or not Hit.Parent then\010\009\009return\010\009end\010\009local character = Hit.Parent\010\009if character:IsA(\034Hat\034) then\010\009\009character = character.Parent\010\009end\010\009if character == Character then\010\009\009return\010\009end\010\009local humanoid = character:FindFirstChild(\034Humanoid\034)\010\009if not humanoid or humanoid.Health == 0 then\010\009\009return\010\009end\010\009local player = Players:GetPlayerFromCharacter(character)\010\009if player and Functions.IsTeamMate(Player, player) then\010\009\009return\010\009end\010\009local DeterminedDamage = math.random(Configuration.Damage.MinValue, Configuration.Damage.MaxValue)\010\009if humanoid ~= nil and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009Functions.UntagHumanoid(humanoid)\010\009Functions.TagHumanoid(humanoid, Player)\010\009humanoid:TakeDamage(DeterminedDamage)\010\009end\010end\010\010function CheckIfAlive()\010\009return (((Player and Player.Parent and Character and Character.Parent and Humanoid and Humanoid.Parent and Humanoid.Health > 0) and true) or false)\010end\010\010function Equipped()\010\009Character = Tool.Parent\010\009Player = Players:GetPlayerFromCharacter(Character)\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009if not CheckIfAlive() then\010\009\009return\010\009end\010\009ToolEquipped = true\010end\010\010function Unequipped()\010\009ToolEquipped = false\010end\010\010function InvokeClient(Mode, Value)\010\009local ClientReturn = nil\010\009pcall(function()\010\009\009ClientReturn = ClientControl:InvokeClient(Player, Mode, Value)\010\009end)\010\009return ClientReturn\010end\010\010ServerControl.OnServerInvoke = (function(player, Mode, Value)\010\009if player ~= Player or not ToolEquipped or not CheckIfAlive() or not Mode or not Value then\010\009\009return\010\009end\010\009if Mode == \034Fire\034 then\010\009\009Sounds.Fire:Play()\010\009elseif Mode == \034RayHit\034 then\010\009\009local RayHit = Value.Hit\010\009\009local RayPosition = Value.Position\010\009\009if RayHit and RayPosition then\010\009\009\009RayTouched(RayHit, RayPosition)\010\009\009end\010\009\009Light.Color = BaseRay.BrickColor.Color\010\009\009if not Light.Enabled then\010\009\009\009Light.Enabled = true\010\009\009\009Delay(0.1, function()\010\009\009\009\009Light.Enabled = false\010\009\009\009end)\010\009\009end\010\009elseif Mode == \034CastLaser\034 then\010\009\009local StartPosition = Value.StartPosition\010\009\009local TargetPosition = Value.TargetPosition\010\009\009local RayHit = Value.RayHit\010\009\009if not StartPosition or not TargetPosition or not RayHit then\010\009\009\009return\010\009\009end\010\009\009for i, v in pairs(Players:GetPlayers()) do\010\009\009\009if v:IsA(\034Player\034) and v ~= Player then\010\009\009\009\009local Backpack = v:FindFirstChild(\034Backpack\034)\010\009\009\009\009if Backpack then\010\009\009\009\009\009local LaserScript = CastLaser:Clone()\010\009\009\009\009\009local StartPos = Instance.new(\034Vector3Value\034)\010\009\009\009\009\009StartPos.Name = \034StartPosition\034\010\009\009\009\009\009StartPos.Value = StartPosition\010\009\009\009\009\009StartPos.Parent = LaserScript\010\009\009\009\009\009local TargetPos = Instance.new(\034Vector3Value\034)\010\009\009\009\009\009TargetPos.Name = \034TargetPosition\034\010\009\009\009\009\009TargetPos.Value = TargetPosition\010\009\009\009\009\009TargetPos.Parent = LaserScript\010\009\009\009\009\009local RayHit = Instance.new(\034BoolValue\034)\010\009\009\009\009\009RayHit.Name = \034RayHit\034\010\009\009\009\009\009RayHit.Value = RayHit\010\009\009\009\009\009RayHit.Parent = LaserScript\010\009\009\009\009\009LaserScript.Disabled = false\010\009\009\009\009\009Debris:AddItem(LaserScript, 1.5)\010\009\009\009\009\009LaserScript.Parent = Backpack\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010end)\010\010Tool.Equipped:connect(Equipped)\010Tool.Unequipped:connect(Unequipped)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20014,class="Script",parent=20013,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Server",["ScriptGuid"]="{17C4DC3A-8C6B-4EF3-9AF7-CD71AB31CB7D}",["Source"]="local Tool = script.Parent\010local Remote = Tool:WaitForChild(\034Remote\034)\010local Handle = Tool:WaitForChild(\034Handle\034)\010\010local Heartbeat = game:GetService(\034RunService\034).Heartbeat\010\010local FriendlyFire = false\010local TEAM = Tool.Handle.TEAM\010\010local LeftDown = false\010\010local AttackHoldTime = 1\010local AttackAble = true\010local AttackRestTime = 1\010local AttackWindupTime = 0.2\010local AttackDamaging = false\010local AttackWindow = 0.6\010local AttackVictims = {}\010local AttackDamage = 30\010local AttackProjectileSpeed = 128\010local AttackProjectileDamage = 30\010local AttackProjectileVictims = {}\010\010--returns the wielding player of this tool\010function getPlayer()\010\009local char = Tool.Parent\010\009return game:GetService(\034Players\034):GetPlayerFromCharacter(char)\010end\010\010--helpfully checks a table for a specific value\010function contains(t, v)\010\009for _, val in pairs(t) do\010\009\009if val == v then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010--tags a human for the ROBLOX KO system\010function tagHuman(human)\010\009local tag = Instance.new(\034ObjectValue\034)\010\009tag.Value = getPlayer()\010\009tag.Name = \034creator\034\010\009tag.Parent = human\010\009game:GetService(\034Debris\034):AddItem(tag)\010end\010\010--used by checkTeams\010function sameTeam(otherHuman)\010\009local player = getPlayer()\010\009local otherPlayer = game:GetService(\034Players\034):GetPlayerFromCharacter(otherHuman.Parent)\010\009if player and otherPlayer then\010\009\009if player == otherPlayer then\010\009\009\009return true\010\009\009end\010\009\009if otherPlayer.Neutral then\010\009\009\009return false\010\009\009end\010\009\009return player.TeamColor == otherPlayer.TeamColor\010\009end\010\009return false\010end\010\010--use this to determine if you want this human to be harmed or not, returns boolean\010function checkTeams(otherHuman)\010\009return not (sameTeam(otherHuman) and not FriendlyFire)\010end\010\010function onHandleTouched(part)\010\009if not AttackDamaging then return end\010\009if part:IsDescendantOf(Tool.Parent) then return end\010\009\010\009\009if part.Parent and part.Parent:FindFirstChild(\034Humanoid\034) then\010\009\009\009local human = part.Parent.Humanoid\010\009\009\009if checkTeams(human) and not contains(AttackVictims, human) then\010\009\009\009\009tagHuman(human)\010\009\009\009\009table.insert(AttackVictims, human)\010\009\009\009\009if human ~= nil and human.Parent:FindFirstChild(\034TEAM\034) and human.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009human:TakeDamage(AttackDamage)\010\009\009\009end\010\009\009end\010\009end\010end\010\010function onProjectileTouched(part)\010\009if part:IsDescendantOf(Tool.Parent) then return end\010\009\009\010\009\009if part.Parent and part.Parent:FindFirstChild(\034Humanoid\034) then\010\009\009\009local human = part.Parent.Humanoid\010\009\009\009if checkTeams(human) and not contains(AttackProjectileVictims, human) then\010\009\009\009\009tagHuman(human)\010\009\009\009\009table.insert(AttackProjectileVictims, human)\010\009\009\009\009if human ~= nil and human.Parent:FindFirstChild(\034TEAM\034) and human.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009human:TakeDamage(AttackDamage)\010\009\009\009end\010\009\009end\010\009end\010end\010\010function onLeftHold()\010\009Remote:FireClient(getPlayer(), \034PlayAnimation\034, \034Swing2\034)\010\009\010\009delay(0.1, function()\010\009\009Handle.Swing.Pitch = 0.8\010\009\009Handle.Swing:Play()\010\009\009delay(0.4, function()\010\009\009\009Handle.Swing.Pitch = 1\010\009\009\009Handle.Swing:Play()\010\009\009\009delay(0.3, function()\010\009\009\009\009Handle.Swing.Pitch = 1.2\010\009\009\009\009Handle.Swing:Play()\010\009\009\009\009Handle.Shot.Pitch = math.random(90, 110)/100\010\009\009\009\009Handle.Shot:Play()\010\009\009\009end)\010\009\009end)\010\009end)\010\009\010\009wait(0.8)\010\009\010\009local root = Tool.Parent:FindFirstChild(\034HumanoidRootPart\034)\010\009if root then\010\009\009local slash = Instance.new(\034Part\034)\010\009\009slash.CanCollide = false\010\009\009slash.FormFactor = \034Custom\034\010\009\009slash.TopSurface = \034Smooth\034\010\009\009slash.BottomSurface = \034Smooth\034\010\009\009slash.BrickColor = BrickColor.new(\034Lime green\034)\010\009\009slash.Size = Vector3.new(3, 0.2, 3)\010\009\009slash.CFrame = root.CFrame * CFrame.new(0, 0, -3) * CFrame.Angles(0, 0, math.pi/2)\010\009\009\010\009\009Instance.new(\034CylinderMesh\034, slash)\010\009\009\010\009\009local bv = Instance.new(\034BodyVelocity\034)\010\009\009bv.maxForce = Vector3.new(1e9, 1e9, 1e9)\010\009\009bv.velocity = root.CFrame.lookVector * AttackProjectileSpeed\010\009\009bv.Parent = slash\010\009\009\010\009\009local spark = Instance.new(\034Fire\034)\010\009\009spark.Color = slash.BrickColor.Color\010\009\009spark.SecondaryColor = spark.Color\010\009\009spark.Parent = slash\010\009\009\010\009\009local light = Instance.new(\034PointLight\034)\010\009\009light.Range = 16\010\009\009light.Color = slash.BrickColor.Color\010\009\009light.Parent = slash\010\009\009\010\009\009slash.Parent = workspace\010\009\009game:GetService(\034Debris\034):AddItem(slash, 5)\010\009\009\010\009\009AttackProjectileVictims = {}\010\009\009local c = slash.Touched:connect(onProjectileTouched)\010\009\009\010\009\009wait(0.5)\010\009\009slash.Anchored = true\010\009\009slash.Transparency = 1\010\009\009c:disconnect()\010\009\009spark.Enabled = false\010\009\009light:Destroy()\010\009end \010end\010\010function onLeftDown()\010\009if not AttackAble then return end\010\009AttackAble = false\010\009\010\009Remote:FireClient(getPlayer(), \034PlayAnimation\034, \034Swing1\034)\010\009\010\009delay(0.2, function()\010\009\009Handle.Swing.Pitch = math.random(90, 110)/100\010\009\009Handle.Swing:Play()\010\009end)\010\009\010\009delay(AttackWindupTime, function()\010\009\009AttackVictims = {}\010\009\009AttackDamaging = true\010\009\009delay(AttackWindow, function()\010\009\009\009AttackDamaging = false\010\009\009end)\010\009end)\010\009\010\009LeftDown = true\010\009local t = 0\010\009while LeftDown do\010\009\009t = t + Heartbeat:wait()\010\009\009if t > AttackHoldTime then\010\009\009\009onLeftHold()\010\009\009\009break\010\009\009end\010\009end\010\009\010\009delay(AttackRestTime, function()\010\009\009AttackAble = true\010\009end)\010end\010\010function onLeftUp()\010\009LeftDown = false\010end\010\010function onRemote(player, func, ...)\010\009if player ~= getPlayer() then return end\010\009\010\009if func == \034LeftDown\034 then\010\009\009onLeftDown(...)\010\009elseif func == \034LeftUp\034 then\010\009\009onLeftUp(...)\010\009end\010end\010\010Remote.OnServerEvent:connect(onRemote)\010Handle.Touched:connect(onHandleTouched)\010",["SourceAssetId"]=-1,["Tags"]=""}}
