T[#T+1]={id=20087,class="Script",parent=20071,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Server",["ScriptGuid"]="{4A53E6EA-9607-45A0-9450-0B899F7D2625}",["Source"]="local Tool = script.Parent\010local Remote = Tool:WaitForChild(\034Remote\034)\010local Handle = Tool:WaitForChild(\034Handle\034)\010local TEAM = script.Parent.Handle:WaitForChild('TEAM')\010\010local Motor\010\010local AttackNumber = 1\010local AttackDamage = 1000\010local AttackWindow = 0.6\010local AttackRest = 1\010local AttackAble = true\010local AttackDamaging = false\010local AttackHit = {}\010\010function getPlayerChar()\010\009local char = Tool.Parent\010\009local player = game:GetService(\034Players\034):GetPlayerFromCharacter(char)\010\009return player, char\010end\010\010function convertWeldToMotor(weld)\010\009local m = Instance.new(\034Motor6D\034)\010\009m.Name = weld.Name\010\009m.Part0 = weld.Part0\010\009m.Part1 = weld.Part1\010\009m.C0 = weld.C0\010\009m.C1 = weld.C1\010\009\010\009local parent = weld.Parent\010\009weld:Destroy()\010\009m.Parent = parent\010\009\010\009Motor = m\010end\010\010function changeGrip()\010\009local player, char = getPlayerChar()\010\009while not char:FindFirstChild(\034Right Arm\034) do wait() end\010\009while not char[\034Right Arm\034]:FindFirstChild(\034RightGrip\034) do wait() end\010\009convertWeldToMotor(char[\034Right Arm\034].RightGrip)\010end\010\010function contains(t, v)\010\009for _, val in pairs(t) do\010\009\009if val == v then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function tagHuman(human)\010\009local player, char = getPlayerChar()\010\009local val = Instance.new(\034ObjectValue\034)\010\009val.Name = \034creator\034\010\009val.Value = player\010\009val.Parent = human\010\009game:GetService(\034Debris\034):AddItem(val, 1)\010end\010\010function openAttackWindow()\010\009AttackHit = {}\010\009\010\009AttackDamaging = true\010\009delay(AttackWindow, function()\010\009\009AttackDamaging = false\010\009end)\010end\010\010function onTouched(part)\010\009if not AttackDamaging then return end\010\009\010\009local player, char = getPlayerChar()\010\009\010\009if part.Parent and part.Parent ~= char and part.Parent:FindFirstChild(\034Humanoid\034) then\010\009\009local human = part.Parent.Humanoid\010\009\009if not contains(AttackHit, human) then\010\009\009\009if human ~= nil and human.Parent:FindFirstChild(\034TEAM\034) and human.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009table.insert(AttackHit, human)\010\009\009\009tagHuman(human)\010\009\009\009human:TakeDamage(AttackDamage)\010\009\009\009\010\009\009\009local pitch = math.random(60, 80)/100\010\009\009\009playSound(\034HitSound\034, pitch, 1)\010\009\009\009playSound(\034HitSound2\034, pitch + .3, 1)\010\009\009\009end\010\009\009end\010\009end\010end\010\010function onTouchedSpecial(part)\010\009local player, char = getPlayerChar()\010\009\010\009if part.Parent and part.Parent ~= char and part.Parent:FindFirstChild(\034Humanoid\034) then\010\009\009local human = part.Parent.Humanoid\010\009\009if not contains(AttackHit, human) then\010\009\009\009if human ~= nil and human.Parent:FindFirstChild(\034TEAM\034) and human.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009table.insert(AttackHit, human)\010\009\009\009tagHuman(human)\010\009\009\009human:TakeDamage(AttackDamage)\010\009\009\009end\010\009\009end\010\009end\010end\010\010function special()\010\009local player, char = getPlayerChar()\010\009local root = char:FindFirstChild(\034HumanoidRootPart\034)\010\009if root then\010\009\009openAttackWindow()\010\009\009\010\009\009local c = root.CFrame\010\009\009local dz = -8\010\009\009for t = 0, 1, 1/100 do\010\009\009\009delay(t, function()\010\009\009\009\009local pos = c:pointToWorldSpace(Vector3.new(0, -2.5, dz))\010\009\009\009\009\010\009\009\009\009local e = Instance.new(\034Explosion\034)\010\009\009\009\009e.BlastPressure = 0\010\009\009\009\009e.Position = pos\010\009\009\009\009e.Hit:connect(onTouchedSpecial)\010\009\009\009\009e.Parent = workspace\010\009\009\009\009\010\009\009\009\009dz = dz - 6\010\009\009\009end)\010\009\009end\010\009\009\010\009\009playSound(\034Explosion\034, 0.9, 1)\010\009end\010end\010\010function playSound(name, pitch, volume)\010\009local sound = Handle:FindFirstChild(name)\010\009if sound then\010\009\009sound.Pitch = pitch or math.random(90, 110)/100\010\009\009sound.Volume = volume or 0.5\010\009\009sound:Play()\010\009end\010end\010\010function attack()\010\009if not AttackAble then return end\010\009\010\009AttackAble = false\010\009delay(AttackRest, function()\010\009\009AttackAble = true\010\009end)\010\009\010\009local player, char = getPlayerChar()\010\009\010\009if AttackNumber < 5 then\010\009\009if AttackNumber == 1 or AttackNumber == 3 then\010\009\009\009Remote:FireClient(player, \034PlayAnimation\034, \034SwingRightToLeft\034)\010\009\009elseif AttackNumber == 2 or AttackNumber == 4 then\010\009\009\009Remote:FireClient(player, \034PlayAnimation\034, \034SwingLeftToRight\034)\010\009\009end\010\009\009\010\009\009openAttackWindow()\010\009\009playSound(\034SwingSound\034)\010\009else\010\009\009Remote:FireClient(player, \034PlayAnimation\034, \034Slam\034)\010\009\009\010\009\009delay(1.1, function()\010\009\009\009for _, obj in pairs(Handle:GetChildren()) do\010\009\009\009\009if obj:IsA(\034Fire\034) then\010\009\009\009\009\009obj.Enabled = false\010\009\009\009\009\009game:GetService(\034Debris\034):AddItem(obj)\010\009\009\009\009end\010\009\009\009end\010\009\009end)\010\009\009\010\009\009delay(1.1, special)\010\009\009\010\009\009playSound(\034FireSound\034, 1)\010\009\009\010\009\009AttackNumber = 0\010\009end\010\009\010\009AttackNumber = AttackNumber + 1\010\009\010\009if AttackNumber == 5 then\010\009\009local fire = Instance.new(\034Fire\034)\010\009\009fire.Parent = Handle\010\009end\010end\010\010function onRemote(callingPlayer, func, ...)\010\009local player, char = getPlayerChar()\010\009if callingPlayer == player then\010\009\009if func == \034Attack\034 then\010\009\009\009attack()\010\009\009end\010\009end\010end\010\010function onEquipped()\010\009--ensure unequip\010\009onUnequipped()\010\009\010\009--convert grip to a motor\010\009changeGrip()\010end\010\010function onUnequipped()\010\009if Motor then\010\009\009Motor:Destroy()\010\009end\010end\010\010--connect events\010Tool.Equipped:connect(onEquipped)\010Tool.Unequipped:connect(onUnequipped)\010Remote.OnServerEvent:connect(onRemote)\010Handle.Touched:connect(onTouched)",["SourceAssetId"]=-1,["Tags"]=""}}
