T[#T+1]={id=20519,class="Script",parent=20430,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{E70B795E-10BB-4AA7-833F-87BCCAA8DEF4}",["Source"]="function waitForChild(parent, childName)\013\010\013\010 \009while true do\013\010\013\010 \009\009local child = parent:findFirstChild(childName)\013\010\013\010 \009\009if child then\013\010\013\010 \009\009\009return child\013\010\013\010 \009\009end\013\010\013\010 \009\009parent.ChildAdded:wait()\013\010\013\010 \009end\013\010\013\010 end\013\010\013\010 local Figure = script.Parent\013\013\010 local Torso = waitForChild(Figure, \034Torso\034)\013\013\010 local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\013\013\010 local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\013\013\010 local RightHip = waitForChild(Torso, \034Right Hip\034)\013\013\010 local LeftHip = waitForChild(Torso, \034Left Hip\034)\013\013\010 local Neck = waitForChild(Torso, \034Neck\034)\013\013\010 local Humanoid = waitForChild(Figure, \034Zombie\034)\013\013\010 local pose = \034Standing\034\013\013\010 \013\013\010 local toolAnim = \034None\034\013\013\010 local toolAnimTime = 0\013\013\010 \013\013\010 local isSeated = false\013\013\010 \013\013\010 -- functions\013\013\010 \013\013\010 function onRunning(speed)\013\013\010 \009if isSeated then return end\013\013\010 \013\013\010 \009if speed>0 then\013\013\010 \009\009pose = \034Running\034\013\013\010 \009else\013\013\010 \009\009pose = \034Standing\034\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 function onDied()\013\013\010 \009pose = \034Dead\034\013\013\010 end\013\013\010 \013\013\010 function onJumping()\013\013\010 \009isSeated = false\013\013\010 \009pose = \034Jumping\034\013\013\010 end\013\013\010 \013\013\010 function onClimbing()\013\013\010 \009pose = \034Climbing\034\013\013\010 end\013\013\010 \013\013\010 function onGettingUp()\013\013\010 \009pose = \034GettingUp\034\013\013\010 end\013\013\010 \013\013\010 function onFreeFall()\013\013\010 \009pose = \034FreeFall\034\013\013\010 end\013\013\010 \013\013\010 function onFallingDown()\013\013\010 \009pose = \034FallingDown\034\013\013\010 end\013\013\010 \013\013\010 function onSeated()\013\013\010 \009isSeated = true\013\013\010 \009pose = \034Seated\034\013\013\010 \009print(\034Seated\034)\013\013\010 end\013\013\010 \013\013\010 function moveJump()\013\013\010 \009RightShoulder.MaxVelocity = 0.5\013\013\010 \009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009RightShoulder.DesiredAngle = 3.14\013\013\010 \009LeftShoulder.DesiredAngle = -3.14\013\013\010 \009RightHip.DesiredAngle = 0\013\013\010 \009LeftHip.DesiredAngle = 0\013\013\010 end\013\013\010 \013\013\010-- same as jump for now\013\013\010function moveFreeFall()\013\013\010 \009RightShoulder.MaxVelocity = 0.5\013\013\010 \009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009RightShoulder.DesiredAngle = 3.14\013\013\010 \009LeftShoulder.DesiredAngle = -3.14\013\013\010 \009RightHip.DesiredAngle = 0\013\013\010 \009LeftHip.DesiredAngle = 0\013\013\010 end\013\013\010 \013\013\010 function moveSit()\013\013\010 \009print(\034Move Sit\034)\013\013\010 \009RightShoulder.MaxVelocity = 0.15\013\013\010 \009LeftShoulder.MaxVelocity = 0.15\013\013\010 \009RightShoulder.DesiredAngle = 3.14 /2\013\013\010 \009LeftShoulder.DesiredAngle = -3.14 /2\013\013\010 \009RightHip.DesiredAngle = 3.14 /2\013\013\010 \009LeftHip.DesiredAngle = -3.14 /2\013\013\010 end\013\013\010 \013\013\010 function getTool()\013\013\010 \009\013\013\010 \009kidTable = Figure:children()\013\013\010 \009if (kidTable ~= nil) then\013\013\010 \009\009numKids = #kidTable\013\013\010 \009\009for i=1,numKids do\013\013\010 \009\009\009if (kidTable[i].className == \034Tool\034) then return kidTable[i] end\013\013\010 \009\009end\013\013\010 \009end\013\013\010 \009\013\013\010 \009return nil\013\013\010 end\013\013\010 \013\013\010 function getToolAnim(tool)\013\013\010 \013\013\010 \009c = tool:children()\013\013\010 \009for i=1,#c do\013\013\010 \009\009if (c[i].Name == \034toolanim\034 and c[i].className == \034StringValue\034) then\013\013\010 \009\009\009return c[i]\013\013\010 \009\009end\013\013\010 \009end\013\013\010 \009return nil\013\013\010 end\013\013\010 \013\013\010 function animateTool()\013\013\010 \009\013\013\010 \009if (toolAnim == \034None\034) then\013\013\010 \009\009RightShoulder.DesiredAngle = 1.57\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (toolAnim == \034Slash\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5\013\013\010 \009\009RightShoulder.DesiredAngle = 0\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (toolAnim == \034Lunge\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5\013\013\010 \009\009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009\009RightHip.MaxVelocity = 0.5\013\013\010 \009\009LeftHip.MaxVelocity = 0.5\013\013\010 \009\009RightShoulder.DesiredAngle = 1.57\013\013\010 \009\009LeftShoulder.DesiredAngle = 1.0\013\013\010 \009\009RightHip.DesiredAngle = 1.57\013\013\010 \009\009LeftHip.DesiredAngle = 1.0\013\013\010 \009\009return\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 function move(time)\013\013\010 \009local amplitude\013\013\010 \009local frequency\013\013\010 \013\013\010 \009if (pose == \034Jumping\034) then\013\013\010 \009\009moveJump()\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (pose == \034FreeFall\034) then\013\013\010 \009\009moveFreeFall()\013\013\010 \009\009return\013\013\010 \009end\013\013\010  \013\013\010 \009if (pose == \034Seated\034) then\013\013\010 \009\009moveSit()\013\013\010 \009\009return\013\013\010 \009end\013\013\010  \013\013\010 \009local climbFudge = 0\013\013\010 \009\013\013\010 \009if (pose == \034Running\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.15\013\013\010 \009\009LeftShoulder.MaxVelocity = 0.15\013\013\010 \009\009amplitude = 1\013\013\010 \009\009frequency = 9\013\013\010 \009elseif (pose == \034Climbing\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5 \013\013\010 \009\009LeftShoulder.MaxVelocity = 0.5\013\013\010  \009\009amplitude = 1\013\013\010 \009\009frequency = 9\013\013\010 \009\009climbFudge = 3.14\013\013\010 \009else\013\013\010 \009\009amplitude = 0.1\013\013\010 \009\009frequency = 1\013\013\010 \009end\013\013\010 \013\013\010 \009desiredAngle = amplitude * math.sin(time*frequency)\013\013\010 \013\013\010 \009RightShoulder.DesiredAngle = desiredAngle + climbFudge\013\013\010 \009LeftShoulder.DesiredAngle = desiredAngle - climbFudge\013\013\010 \009RightHip.DesiredAngle = -desiredAngle\013\013\010 \009LeftHip.DesiredAngle = -desiredAngle\013\013\010 \013\013\010 \013\013\010 \009local tool = getTool()\013\013\010 \013\013\010 \009if tool ~= nil then\013\013\010 \009\013\013\010 \009\009animStringValueObject = getToolAnim(tool)\013\013\010 \013\013\010 \009\009if animStringValueObject ~= nil then\013\013\010 \009\009\009toolAnim = animStringValueObject.Value\013\013\010 \009\009\009-- message recieved, delete StringValue\013\013\010 \009\009\009animStringValueObject.Parent = nil\013\013\010 \009\009\009toolAnimTime = time + .3\013\013\010 \009\009end\013\013\010 \013\013\010 \009\009if time > toolAnimTime then\013\013\010 \009\009\009toolAnimTime = 0\013\013\010 \009\009\009toolAnim = \034None\034\013\013\010 \009\009end\013\013\010 \013\013\010 \009\009animateTool()\013\013\010 \013\013\010 \009\009\013\013\010 \009else\013\013\010 \009\009toolAnim = \034None\034\013\013\010 \009\009toolAnimTime = 0\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 \013\013\010 -- connect events\013\013\010 \013\013\010 Humanoid.Died:connect(onDied)\013\013\010 Humanoid.Running:connect(onRunning)\013\013\010 Humanoid.Jumping:connect(onJumping)\013\013\010 Humanoid.Climbing:connect(onClimbing)\013\013\010 Humanoid.GettingUp:connect(onGettingUp)\013\013\010 Humanoid.FreeFalling:connect(onFreeFall)\013\013\010 Humanoid.FallingDown:connect(onFallingDown)\013\013\010 Humanoid.Seated:connect(onSeated)\013\013\010 \013\013\010 -- main program\013\013\010 \013\013\010 local nextTime = 0\013\013\010 local runService = game:service(\034RunService\034);\013\013\010 \013\013\010 while Figure.Parent~=nil do\013\013\010 \009time = runService.Stepped:wait()\013\013\010 \009if time > nextTime then\013\013\010 \009\009move(time)\013\013\010 \009\009nextTime = time + 0.1\013\013\010 \009end\013\013\010 end\013\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20521,class="Script",parent=20430,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{70DFA8E0-439F-4032-936B-2A0566D8B4DF}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009\009if dist < 50 then \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 0\010\009\009\009\009script.Parent.Attack.Value = true \010\009\009\009else \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 5\010\009\009\009\009script.Parent.Attack.Value = false \010\009\009\009end \010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = math.random(0,0)\010\009\009ry = math.random(0,0)\010\009\009rz = math.random(0,0)\010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20522,class="Script",parent=20430,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{00F78812-42AF-4375-BA11-A2A9E0B66FC7}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009game.Debris:AddItem(script.Parent,30)\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009game.workspace.Scripts.WaveScript.Dead_Zombies.Value = game.workspace.Scripts.WaveScript.Dead_Zombies.Value + 1\010\009wait(5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
