T[#T+1]={id=20532,class="Script",parent=20430,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{83DF353E-165B-4149-BDF9-F77985608ED1}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20551,class="Script",parent=20548,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="LaserBlast",["ScriptGuid"]="{61A0D0BA-8478-4283-8C40-8CA1E0E4B9DE}",["Source"]="-- 42672473 is sorry sound\010-- 42672581 is wind-knocked-out sound\010\010ball = script.Parent\010damage = 20\010HitSound = Instance.new(\034Sound\034)\010HitSound.Name = \034HitSound\034\010HitSound.SoundId = \034http://www.roblox.com/asset/?id=11945266\034\010HitSound.Parent = ball\010HitSound.Volume = 1\010\010PersonHitSound = Instance.new(\034Sound\034)\010PersonHitSound.Name = \034PersonHitSound\034\010--PersonHitSound.SoundId = \034http://www.roblox.com/asset/?id=42672473\034\010PersonHitSound.SoundId = \034http://www.roblox.com/asset/?id=42672581\034 -- grunt sound\010PersonHitSound.Volume = .5\010PersonHitSound.Pitch = 1\010PersonHitSound.Parent = ball\010\010db = false\010\010target = ball:findFirstChild(\034Target\034)\010if target ~= nil then\010\009if db == false then\010\009\009local humanoid = target.Value:findFirstChild(\034Humanoid\034)\010\010\009\009if humanoid ~= nil then\010\009\009\009humanoid:TakeDamage(damage)\010\010\009\009\009PersonHitSound:Play()\010\009\009end\010\010\009ball.Anchored = true\010\009end\010end\010\010function tagHumanoid(humanoid)\010\009-- todo: make tag expire\010\009local tag = ball:findFirstChild(\034creator\034)\010\009if tag ~= nil then\010\009\009local new_tag = tag:clone()\010\009\009new_tag.Parent = humanoid\010\009end\010end\010\010\010function untagHumanoid(humanoid)\010\009if humanoid ~= nil then\010\009\009local tag = humanoid:findFirstChild(\034creator\034)\010\009\009if tag ~= nil then\010\009\009\009tag.Parent = nil\010\009\009end\010\009end\010end\010\010--connection = ball.Touched:connect(onTouched)\010\010for i = 1,5 do\010\009ball.Transparency = ball.Transparency + 0.2\010\009ball.Mesh.Scale = ball.Mesh.Scale + Vector3.new(0.5,0.5,0.5)\010\009wait(0.1)\010end\010\010--ball.SparkSound.Looped = false\010--ball.SparkSound:Stop()\010ball.Parent = nil",["SourceAssetId"]=-1,["Tags"]=""}}
