T[#T+1]={id=20554,class="Script",parent=20548,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Welding",["ScriptGuid"]="{CDD81999-643B-4582-A105-7CFF19462C77}",["Source"]="function Weld(x,y)\013\010\009local W = Instance.new(\034Weld\034)\013\010\009W.Part0 = x\013\010\009W.Part1 = y\013\010\009local CJ = CFrame.new(x.Position)\013\010\009local C0 = x.CFrame:inverse()*CJ\013\010\009local C1 = y.CFrame:inverse()*CJ\013\010\009W.C0 = C0\013\010\009W.C1 = C1\013\010\009W.Parent = x\013\010end\013\010\013\010function Get(A)\013\010\009if A.className == \034Part\034 then\013\010\009\009Weld(script.Parent.Handle, A)\013\010\009\009A.Anchored = false\013\010\009else\013\010\009\009local C = A:GetChildren()\013\010\009\009for i=1, #C do\013\010\009\009Get(C[i])\013\010\009\009end\013\010\009end\013\010end\013\010\013\010function Finale()\013\010\009Get(script.Parent)\013\010end\013\010\013\010script.Parent.Equipped:connect(Finale)\013\010script.Parent.Unequipped:connect(Finale)\013\010Finale()",["SourceAssetId"]=-1,["Tags"]=""}}
