script.Disabled = false\010\009new_script.Parent = missile\010\009\010\009local target = Instance.new(\034ObjectValue\034)\010\009target.Name = \034Target\034\010\009target.Value = Tool.Parent.Target.Value.Parent\010\009target.Parent = missile\010\009\010\010\009Hit = missile.CFrame\010\009local Projectile = Instance.new(\034Part\034) \010\009Projectile.Name = \034Trail\034 \010\009local Place0 = Tool[\034Handle\034].CFrame \010\009Projectile.formFactor = 0 \010\009Projectile.Size = Vector3.new(1,1,(Place0.p - Hit.p).magnitude) \010\009Projectile.CFrame = CFrame.new((Place0.p + Hit.p)/2,Place0.p) \010\009Projectile.Parent = Workspace\010\009Projectile.BrickColor = missile.BrickColor\010\009Projectile.Anchored = true \010\009Projectile.CanCollide = false\010\009\010\009local new_script2 = script.Parent.ProjectileTimeLife:clone()\010\009new_script2.Disabled = false\010\009new_script2.Parent = Projectile\010\010\009me2 = Instance.new(\034BlockMesh\034)\010\009me2.Scale = Vector3.new(0.25,0.25,1)\010\009me2.Parent = Projectile\010\010\009--Tool.Handle.GruntSound:Clone().Parent = missile\010\010\009missile.Parent = Workspace\010--\009wait(.15)\010\009--PewPew:Stop()\010end\010\010\010\010function gunUp()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.5)\010end\010\010function gunOut()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.75)\010end\010\010function isTurbo(character)\010\009return character:FindFirstChild(\034BoltHelm\034) ~= nil\010end\010\010\010function onActivated()\010\009if not enabled  then\010\009\009return\010\009end\010\010\009enabled = false\010\010\010\009local character = Tool.Parent;\010\009local humanoid = character.Invulnerable\010\009if humanoid == nil then\010\009\009print(\034Humanoid not found\034)\010\009\009return \010\009end\010\010\009local targetPos = Tool.Parent.Target.Value.Position\010\009local lookAt = (targetPos - character.Head.Position).unit\010\010\009local reload = .05\010\009--if (isTurbo(character)) then\010\009--\009reload = .25\010\009--\009print(\034turbo\034)\010\009--end\010\010\009\010\009local PewPew = Tool.Handle:FindFirstChild(\034PewPew\034)\010\010\009if (PewPew == nil) then\010\009\009PewPew = Instance.new(\034Sound\034)\010\009\009PewPew.Name = \034PewPew\034\010\009\009PewPew.SoundId = \034http://www.roblox.com/asset/?id=92651381\034\010\009\009PewPew.Parent = Tool.Handle\010\009\009PewPew.Volume = 1\010\009\009PewPew.Pitch = 0.75\010\009end\010\009\010\009--PewPew:Play()\010\009for i =1,3 do\010\010\009\009local spark = Instance.new(\034Fire\034)\010\009\009spark.Color = Color3.new(1,0,0)\010\009\009spark.SecondaryColor = Color3.new(1,0,0)\010\009\009spark.Size = 7.5\010\009\009spark.Heat = 0\010\009\009spark.Parent = Tool.Handle\010\010\009--gunUp()\010\009\009fire(lookAt,humanoid)\010\009\009PewPew:Play()\010\009\009wait(0.25)\010\010\009\009spark:remove()\010\009end\010\009--wait(reload)\010\009--gunOut()\010\009--wait(reload)\010\010\009wait(1.25)\010\010\009enabled = true\010\010end\010\010function onEquipped()\010\009--Tool.Handle.EquipSound:play()\010end\010\010Tool.Activated:connect(onActivated)\010Tool.Equipped:connect(onEquipped)\010\010while true do\010if Tool.Parent.Attack.Value == true then\010onActivated()\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20587,class="Script",parent=20563,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{B3E53B82-0CFC-4CEC-B4B3-64EC511EAF66}",["Source"]="wait()\010zombieParent = false\010\010while zombieParent == false do\010\010\009wait()\010\009if script.Parent.Name == \034Turret\034 or script.Parent.Name == \034Giant Noob\034 then\010\009\009zombieParent = true\010\009end\010\010end\010\010local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009\009if dist < 75 then \010\009\009\009\009script.Parent.Attack.Value = true \010\009\009\009elseif dist > 75 then\010\009\009\009\009script.Parent.Attack.Value = false \010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010db = false \010function Hit(hit)\010\009if db == false then \010\009\009kk = script.Parent:FindFirstChild(\034ClassicPartiron\034)\010\009\009if script.Parent.Name == \034Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(50)\010\009\009\009\009db = true \010\009\009\009\009wait(0.5)\010\009\009\009\009db = false \010\009\009\009end\010\009\009elseif script.Parent.Name == \034Giant Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(100)\010\009\009\009\009db = true \010\009\009\009\009wait(0.25)\010\009\009\009\009db = false \010\009\009\009end\010\009\009elseif kk ~= nil and script.Parent.Name == \034Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Zombie\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(300)\010\009\009\009\009db = true \010\009\009\009\009wait(1)\010\009\009\009\009db = false \010\009\009\009end\010\009\009end  \010\009end \010end\010\010function Sit()\010\009if script.Parent.Invulnerable.Sit == true then\010\009\009wait(1) \010\009\009script.Parent.Invulnerable.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Invulnerable.Changed:connect(Sit)\010\010for i,p in pairs(script.Parent:GetChildren()) do \010\009if p:IsA(\034Part\034) then \010\009\009p.Touched:connect(Hit)\010\009end\010end \010\010while true do\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = math.random(0,0)\010\009\009ry = math.random(0,0)\010\009\009rz = math.random(0,0)\010\009\009script.Parent.Invulnerable:MoveTo(target.Position + Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009chancetorotate = math.random(0,3)\010\009\009if chancetorotate == 3 then script.Parent.Invulnerable:MoveTo(script.Parent.Torso.Position + Vector3.new(math.random(-10,10),0,math.random(-10,10)), script.Parent.Parent.Torso) end\010\009\009wait(1)\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20593,class="Script",parent=20430,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{5932A694-3FD4-4414-A830-0AF9ABA9DFD1}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Torso.Death:Play()\010\009e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-50,50),math.random(0,100),math.random(-50,50))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\010\009wait(3)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20597,class="Script",parent=20595,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{0EFF1160-7A1A-4FD8-B03E-286A9BA15091}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxassetid://138108873\034)\010--sDied.Pitch = 0.75\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20600,class="Script",parent=20595,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{50DDE61B-C763-4776-90BE-DFED032F6B85}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20619,class="Script",parent=20595,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{D01998B3-B175-4931-9F14-35EBFD8D864B}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(0.1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 125 and\010\009\009\009 (target.Position - script.Parent.Torso.Position).magnitude > 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude < 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = -16\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 125 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 16\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20626,class="Script",parent=20620,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{9CD5CB66-CABC-41BD-8E8C-9CD802AE5D80}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010\010\010firerate=1.5\010range=950\010power=300\010rate=1/30\010spinuptime=0\010barreloffset=Vector3.new(0,2.75,.375)\010windvec=Vector3.new(2,-1,1).unit\010firetime=0\010maxammo=5\010reloadtime = 5\010ammo=maxammo\010\010debris=game:GetService(\034Debris\034)\010equipped=false\010check=true\010firing=false\010reloading=false\010fireanimdelay=0\010handle=sp:WaitForChild(\034Handle\034)\010--handle2=sp:WaitForChild(\034Handle2\034)\010handles = {handle}\010handlestofire = 1\010anim = sp.Parent.Humanoid:LoadAnimation(sp.idle)\010anim2 = sp.Parent.Humanoid:LoadAnimation(sp.FireAni)\010anim3 = sp.Parent.Humanoid:LoadAnimation(sp.Reload)\010--fireanimloop = false\010\010--[[Spawn(function()\010\009while true do\010\009\009fireanimdelay = fireanimdelay - game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009if fireanimdelay <= 0 then\010\009\009\009fireanimdelay = 0\010\009\009\009if anim2 and fireanimloop then anim2:Stop() fireanimloop = false end\010\009\009end\010\009\009wait()\010\009end\010end)]]\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function waitfor(parent,name)\010\009while parent:FindFirstChild(name)==nil do\010\009\009wait()\010\009end\010\009return parent:FindFirstChild(name)\010end\010\010function checkintangible(hit)\010\009if hit and hit~=nil then\010\009\009if hit:IsDescendantOf(sp.Parent) or hit.Transparency>.8 or hit.Name==\034Handle\034 or hit.Name==\034Effect\034 or hit.Name==\034Bullet\034 or hit.Name==\034Laser\034 or string.lower(hit.Name)==\034water\034 or hit.Name==\034Rail\034 or hit.Name==\034Arrow\034 then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function castray(startpos,vec,length,ignore,delayifhit)\010\009local hit,endpos2=game.Workspace:FindPartOnRay(Ray.new(startpos,vec*length),ignore)\010\009if hit~=nil then\010\009\009if checkintangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit,endpos2=castray(endpos2+(vec*.01),vec,length-((startpos-endpos2).magnitude),ignore,delayifhit)\010\009\009end\010\009end\010\009return hit,endpos2\010end\010\010function drawbeam(beamstart,beamend,clr,fadedelay)\010\009local dist=(beamstart-beamend).magnitude\010\009local laser=Instance.new(\034Part\034)\010\009laser.Name=\034Effect\034\010\009laser.Anchored=true\010\009laser.CanCollide=false\010\009laser.Shape=\034Block\034\010\009laser.formFactor=\034Custom\034\010\009laser.Size=Vector3.new(.2,.2,.2)\010\009laser.Transparency=0\010\009laser.Material=Enum.Material.Plastic\010\009laser.Locked=true\010\009laser.TopSurface=0\010\009laser.BottomSurface=0\010\009laser.BrickColor=clr\010\009laser.CFrame=CFrame.new(beamend,beamstart)*CFrame.new(0,0,-dist/2)*CFrame.Angles(math.pi/2,0,0)\010\009local m=Instance.new(\034SpecialMesh\034)\010\009m.Scale=Vector3.new(1,dist*5,1)\010\009m.MeshType=\034Brick\034\010\009m.Parent=laser\010\009debris:AddItem(laser,fadedelay*0.5)\010\009laser.Parent=game.Workspace\010\010\009--[[local frames=math.floor(fadedelay/rate)\010\009for frame=1,frames do\010\009\009wait(rate)\010\009\009local percent=frame/frames\010\009\009laser.CFrame=laser.CFrame+windvec*rate\010\009\009laser.Transparency=.5+(percent*.5)\010\009end]]\010\009wait(.5)\010\009laser:remove()\010end\010\010function fire()\010\009local hu=sp.Parent:FindFirstChild(\034Humanoid\034)\010\009local he=sp.Parent:FindFirstChild(\034Head\034)\010\009local t=sp.Parent:FindFirstChild(\034Torso\034)\010\009local team=sp.Parent:FindFirstChild(\034TEAM\034)\010\009--if handlestofire == 1 then handlestofire = 2 elseif handlestofire == 2 then handlestofire = 1 end\010\009if hu and team and hu.Health>0 and t and he and equipped then\010\010\009\009if anim2 and not fireanimloop then anim2:Play() anim2:AdjustSpeed(5) fireanimloop = true end\010\009\009fireanimdelay = 0.5\010\009\009local startpos=he.Position\010\009\009local fakestartpos=(handles[handlestofire].CFrame*CFrame.new(barreloffset)).p\010\009\009local vec=(sp.Parent.Target.Value.Position-startpos).unit + (Vector3.new(math.random(-1000,1000),math.random(-1000,1000),math.random(-1000,1000)) / (1500*30))\010\010\009\009local p=Instance.new(\034Part\034)\010\009\009p.Name=\034Effect\034\010\009\009p.BrickColor=BrickColor.new(\034Black\034)\010\009\009p.CanCollide=false\010\009\009p.TopSurface=\034Smooth\034\010\009\009p.BottomSurface=\034Smooth\034\010\009\009p.formFactor=\034Custom\034\010\009\009p.Size=Vector3.new(0,0,0)\010\009\009p.Transparency=1\010\009\009local m=Instance.new(\034SpecialMesh\034)\010\009\009m.Parent=p\010\010\009\009local hit,endpos=castray(startpos,vec,range,sp.Parent,false)\010\009\009local fakevec=(endpos-fakestartpos).unit\010\009\009if hit~=nil then\010\009\009\009local newcf=CFrame.new(endpos,endpos+fakevec)*CFrame.Angles(math.pi/2,0,0)*CFrame.new(0,0,0)\010\009\009\009p.CFrame=newcf\010\009\009\009local w=Instance.new(\034Weld\034)\010\009\009\009w.Part0=hit\010\009\009\009w.Part1=p\010\009\009\009w.C0=hit.CFrame:inverse()*newcf\010\009\009\009w.C1=newcf:inverse()*newcf\010\009\009\009w.Parent=p\010\010\009\009\009--[[local c=Instance.new(\034ObjectValue\034)\010\009\009\009c.Name=\034creator\034\010\009\009\009c.Value=game.Players.LocalPlayer\010\009\009\009c.Parent=p]]\010\009\009\009\010\009\009\009team:clone().Parent=p\010\010\009\009\009local s=script.Script:clone()\010\009\009\009s.Parent=p\010\009\009\009s.Disabled=false\010\009\009else\010\009\009\009p.CFrame=CFrame.new(endpos,endpos+fakevec)\010\009\009\009p.Velocity=fakevec*power\010\009\009\009p.Parent=game.Workspace\010\009\009end\010\010\009\009debris:AddItem(p,1)\010\009\009p.Parent=game.Workspace\010\010\009\009delay(0,function()\010\009\009\009drawbeam(fakestartpos,endpos,BrickColor.new(\034Bright yellow\034),.1)\010\009\009end)\010\010\009\009local sound=handles[handlestofire]:FindFirstChild(\034Fire\034)\010\009\009if sound~=nil then\010\009\009\009--sound:Stop()\010\009\009\009sound:Play()\010\009\009end\010\010\009\009local shoulder=t:FindFirstChild(\034Right Shoulder\034)\010\009\009if shoulder~=nil then\010\009\009\009shoulder.CurrentAngle=(math.pi/2)+.1\010\009\009end\010\009end\010end\010\010function onEquipped(mouse)\010\009equipped=true\010\009anim = sp.Parent.Humanoid:LoadAnimation(sp.idle)\010\009if anim then anim:Play() end\010\009--[[if mouse~=nil then\010\009\009themouse=mouse\010\009\009mouse.Icon=\034rbxasset://textures\092\092GunCursor.png\034\010\009\009mouse.Button1Down:connect(function()\010\009\009\009mouse.Icon=\034rbxasset://textures\092\092GunWaitCursor.png\034\010\009\009\009firetime=tick()+spinuptime\010\009\009\009down=true\010\009\009end)\010\009\009mouse.Button1Up:connect(function()\010\009\009\009down=false\010\009\009\009mouse.Icon=\034rbxasset://textures\092\092GunCursor.png\034\010\009\009end)\010\009end]]\010end\010\010function Reload()\010\009anim3 = sp.Parent.Humanoid:LoadAnimation(sp.Reload)\010\009if anim3 then anim3:Play() anim3:AdjustSpeed(2.5) end\010\009local sound=handles[handlestofire]:FindFirstChild(\034Reload\034)\010\009if sound~=nil then\010\009\009sound:Play()\010\009end\010\009wait(reloadtime)\010\009ammo = maxammo\010end\010\010function onUnequipped()\010\009if anim then anim:Stop() end\010\009equipped=false\010\009themouse=nil\010end\010\010sp.Equipped:connect(onEquipped)\010sp.Unequipped:connect(onUnequipped)\010\010while true do\010\009if sp.Parent.Attack.Value == true then\010\009\009if ammo > 0 then\010\009\009\009ammo = ammo - 1\010\009\009\009fire()\010\009\009\009wait(firerate)\010\009\009else\010\009\009\009Reload()\010\009\009end\010\009else\010\009\009wait()\010\009end\010end\010\010\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20627,class="Script",parent=20626,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{465464CD-AD6B-4848-8FEB-96E1689DD3CD}",["Source"]="--Stickmasterluke\010\010\010sp=script.Parent\010\010damage=90--15\010\010wait()\010\010local weld=sp:FindFirstChild(\034Weld\034)\010if weld~=nil then\010\009if weld.Part0~=nil then\010\009\009hit=weld.Part0\010\009\009local sound=sp:FindFirstChild(\034Sound\034)\010\009\009if sound~=nil then\010\009\009\009sound:Play()\010\009\009end\010\009\009if hit.Name~=\034Handle\034 and hit.Name~=\034Effect\034 then\010\009\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local t=hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009local team=hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h~=nil and t~=nil and h.Health>0 and team~=nil and team.Value~=sp.TEAM.Value then\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009end\010\009\009end\010\009end\010end\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20631,class="Script",parent=20595,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="HealthRegenerationScript",["ScriptGuid"]="{BD6F6A26-30BF-4817-BB42-E3A58D0AD895}",["Source"]="-- Renegeration Script for the bot\013\010-- Renegerates about 1% of max hp per second until it reaches max health\013\010bot = script.Parent\013\010Humanoid = bot:FindFirstChild(\034Humanoid\034)\013\010\013\010local regen = false\013\010\013\010function regenerate() \013\010\009if regen then return end\013\010\009-- Lock this function until the regeneration to max health is complete by using a boolean toggle\013\010\009regen = true\013\010\009while Humanoid.Health < Humanoid.MaxHealth do\013\010\009\009local delta = wait(1)\013\010\009\009local health = Humanoid.Health\013\010\009\009if health > 0 and health < Humanoid.MaxHealth then \013\010\009\009\009-- This delta is for regenerating 1% of max hp per second instead of 1 hp per second\013\010\009\009\009delta = 0.01 * delta * Humanoid.MaxHealth\013\010\009\009\009health = health + delta\013\010\009\009\009Humanoid.Health = math.min(health, Humanoid.MaxHealth)\009\009\009\013\010\009\009end\013\010\009end\009\013\010\009-- release the lock, since the health is at max now, and if the character loses health again\013\010\009-- it needs to start regenerating \013\010\009regen = false\013\010end\009\013\010\013\010if Humanoid then \013\010\009-- Better than a while true do loop since it only fires when the health actually changes\013\010\009Humanoid.HealthChanged:connect(regenerate)\009\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20633,class="Script",parent=20595,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="PP",["ScriptGuid"]="{EC53BF8F-BAB0-40F1-8CB2-2A5DF8EB16BE}",["Source"]="print(\034Hello world!\034)\010\010Character = script.Parent\010Humanoid = Character.Humanoid\010Torso = Character.Torso\010\010local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then\010game:GetService(\034PointsService\034):AwardPoints(tag.Value.userId,150)\010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) \010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20668,class="Script",parent=20595,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="money kill",["ScriptGuid"]="{131F5868-A11E-4F8E-AE01-D4207FDFEA52}",["Source"]="local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then \010Leaderstats.Coin.Value = Leaderstats.Coin.Value + 150 --Change Money to the stat that is increased. \010wait(0.1) \010script:remove() \010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) ",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20669,class="Script",parent=20595,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{0BB78EC5-DD53-46CD-B095-6D02C72F34DA}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009game.workspace.Scripts.WaveScript.Dead_Zombies.Value = game.workspace.Scripts.WaveScript.Dead_Zombies.Value + 1\010\009wait(2.5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20681,class="Script",parent=20670,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{47E0CBBF-27E7-4923-A464-35A1B6ECEDBF}",["Source"]="--Made by Luckymaxer\010\010wait()\010\010Tool = script.Parent\010Handle = Tool:WaitForChild(\034Handle\034)\010Mesh = Handle:WaitForChild(\034Mesh\034)\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010\010RbxUtility = LoadLibrary(\034RbxUtility\034)\010Create = RbxUtility.Create\010\010FunctionsLibrary = script:WaitForChild(\034Functions\034)\010ProjectileManager = script:WaitForChild(\034ProjectileManager\034)\010Functions = require(FunctionsLibrary)\010\010ParticlesBin = script:WaitForChild(\034Particles\034)\010Particles = {}\010for i, v in pairs(ParticlesBin:GetChildren()) do\010\009if v:IsA(\034ParticleEmitter\034) then\010\009\009Particles[v.Name] = v\010\009end\010end\010\010ModeGui = script:WaitForChild(\034ModeGui\034)\010\010BaseUrl = \034http://www.roblox.com/asset/?id=\034\010\010Animations = {\010\009Hold = {Animation = Tool:WaitForChild(\034Hold\034), FadeTime = nil, Weight = nil, Speed = 1, Duration = nil},\010}\010\010Sounds = {\010\009Fire = Handle:WaitForChild(\034Fire\034),\010\009Flame = Handle:WaitForChild(\034Flame\034),\010\009IgniteFlameOn = Handle:WaitForChild(\034IgniteFlameOn\034),\010\009IgniteFlameOff = Handle:WaitForChild(\034IgniteFlameOff\034),\010}\010\010BasePart = Create(\034Part\034){\010\009Material = Enum.Material.Plastic,\010\009FormFactor = Enum.FormFactor.Custom,\010\009TopSurface = Enum.SurfaceType.Smooth,\010\009BottomSurface = Enum.SurfaceType.Smooth,\010\009Size = Vector3.new(0.2, 0.2, 0.2),\010\009CanCollide = true,\010\009Locked = true,\010}\010\010BaseProjectile = BasePart:Clone()\010BaseProjectile.Name = \034Projectile\034\010BaseProjectile.BrickColor = BrickColor.new(\034Pastel Blue\034)\010BaseProjectile.Material = Enum.Material.Neon\010BaseProjectile.Size = Vector3.new(0.2, 1.5, 0.2)\010BaseProjectile.CanCollide = false\010BaseProjectile.Locked = true\010BaseProjectile.Anchored = false\010Create(\034BlockMesh\034){\010\009Scale = Vector3.new(0.5, 1, 0.5),\010\009VertexColor = Vector3.new(1, 1, 1),\010\009Offset = Vector3.new(0, 0, 0),\010\009Parent = BaseProjectile,\009\010}\010Create(\034PointLight\034){\010\009Color = BaseProjectile.BrickColor.Color,\010\009Brightness = 50,\010\009Range = 2,\010\009Shadows = false,\010\009Enabled = true,\010\009Parent = BaseProjectile,\010}\010\010Modes = {\010\009{Name = \034RapidFire\034, Text = \034MODE: Rapid-Fire Gatling Gun\034, Color = Color3.new(0, 0, 1)},\010\009{Name = \034Flamethrower\034, Text = \034MODE: Underbarrel-Flamethrower\034, Color = Color3.new(1, 0, 0)},\010}\010\010FireMode = Modes[1]\010\010Rate = (1 / 30)\010Gravity = 196.20\010\010MouseDown = false\010ToolEquipped = false\010\010ServerControl = (Tool:FindFirstChild(\034ServerControl\034) or Create(\034RemoteFunction\034){\010\009Name = \034ServerControl\034,\010\009Parent = Tool,\010})\010\010ClientControl = (Tool:FindFirstChild(\034ClientControl\034) or Create(\034RemoteFunction\034){\010\009Name = \034ClientControl\034,\010\009Parent = Tool,\010})\010\010Handle.Transparency = 0\010Tool.Enabled = true\010\010function CheckIfAlive()\010\009return (((Character and Character.Parent and Humanoid and Humanoid.Parent and Humanoid.Health > 0 and Player and Player.Parent and Player:IsA(\034Player\034)) and true) or false)\010end\010\010function CraftGun(Craft)\010\009for i, v in pairs(Tool:GetChildren()) do\010\009\009if v:IsA(\034BasePart\034) and v ~= Handle then\010\009\009\009v:Destroy()\010\009\009end\010\009end\010\009Handle.Transparency = ((Craft and 1) or 0)\010\009if not Craft then\010\009\009return\010\009end\010\009local Gun = BasePart:Clone()\010\009Gun.Name = \034Gun\034\010\009Gun.Size = Vector3.new(0.2, 0.2, 0.2)\010\009Gun.CanCollide = false\010\009Create(\034SpecialMesh\034){\010\009\009MeshType = Enum.MeshType.FileMesh,\010\009\009MeshId = (BaseUrl .. \034287444318\034),\010\009\009TextureId = (BaseUrl .. \034287439796\034),\010\009\009Scale = Mesh.Scale,\010\009\009VertexColor = Vector3.new(1, 1, 1),\010\009\009Offset = Vector3.new(0, 0, 0),\010\009\009Parent = Gun,\010\009}\010\009local Barrel = BasePart:Clone()\010\009Barrel.Name = \034Barrel\034\010\009Barrel.Size = Vector3.new(0.2, 0.2, 0.2)\010\009Barrel.CanCollide = false\010\009Create(\034SpecialMesh\034){\010\009\009MeshType = Enum.MeshType.FileMesh,\010\009\009MeshId = (BaseUrl .. \034287444248\034),\010\009\009TextureId = (BaseUrl .. \034287439796\034),\010\009\009Scale = Mesh.Scale,\010\009\009VertexColor = Vector3.new(1, 1, 1),\010\009\009Offset = Vector3.new(0, 0, 0),\010\009\009Parent = Barrel,\010\009}\010\009Flamethrower = BasePart:Clone()\010\009Flamethrower.Name = \034Flamethrower\034\010\009Flamethrower.Transparency = 1\010\009Flamethrower.Size = Vector3.new(0.2, 0.2, 0.2)\010\009Flamethrower.CanCollide = false\010\009GunWeld = Create(\034Weld\034){\010\009\009Part0 = Handle,\010\009\009Part1 = Gun,\010\009\009C0 = CFrame.new(0, 0, 0.25),\010\009\009C1 = CFrame.new(0, 0, 0),\010\009\009Parent = Gun,\010\009}\010\009BarrelMotor = Create(\034Motor6D\034){\010\009\009Part0 = Gun,\010\009\009Part1 = Barrel,\010\009\009C0 = CFrame.new(0, 0.53, -1.825),\010\009\009C1 = CFrame.new(0, 0, 0),\010\009\009CurrentAngle = 0,\010\009\009DesiredAngle = 9999999999999,\010\009\009MaxVelocity = 0,\010\009\009Parent = Barrel\010\009}\010\009FlamethrowerWeld = Create(\034Weld\034){\010\009\009Part0 = Handle,\010\009\009Part1 = Flamethrower,\010\009\009C0 = (CFrame.new(0, 0, -1.375) * CFrame.Angles(-(math.pi / 2), 0, 0)),\010\009\009C1 = CFrame.new(0, 0, 0),\010\009\009Parent = Flamethrower,\010\009}\010\009for i, v in pairs({Gun, Barrel, Flamethrower}) do\010\009\009v.Parent = Tool\010\009end\010end\010\010function GetProjectileManager()\010\009local ProjectileModelName = (Player.Name .. \034'sProjectiles\034)\010\009local ProjectileModel = game:GetService(\034Workspace\034):FindFirstChild(ProjectileModelName)\010\009if not ProjectileModel then\010\009\009local Values = {\010\009\009\009{Name = \034Creator\034, Class = \034ObjectValue\034, Value = Player},\010\009\009\009{Name = \034Tool\034, Class = \034ObjectValue\034, Value = Tool},\010\009\009}\010\009\009ProjectileModel = Create(\034Model\034){\010\009\009\009Name = ProjectileModelName,\010\009\009}\010\009\009local ProjectileManagerCopy = ProjectileManager:Clone()\010\009\009for i, v in pairs(Values) do\010\009\009\009local Value = Create(v.Class){\010\009\009\009\009Name = v.Name,\010\009\009\009\009Value = v.Value,\010\009\009\009\009Parent = ProjectileManagerCopy,\010\009\009\009}\010\009\009end\010\009\009local FunctionsCopy = FunctionsLibrary:Clone()\010\009\009FunctionsCopy.Parent = ProjectileManagerCopy\010\009\009ProjectileManagerCopy.Disabled = false\010\009\009ProjectileManagerCopy.Parent = ProjectileModel\010\009\009ProjectileModel.Parent = game:GetService(\034Workspace\034)\010\009end\010\009return ProjectileModel\010end\010\010function FireProjectiles()\010\009local CurrentlyEquipped = true\010\009if ToolUnequipped then\010\009\009ToolUnequipped:disconnect()\010\009end\010\009ToolUnequipped = Tool.Unequipped:connect(function()\010\009\009CurrentlyEquipped = false\010\009\009if ToolUnequipped then\010\009\009\009ToolUnequipped:disconnect()\010\009\009end\010\009end)\010\009local BarrelSpeed = {Min = 0, Max = 0.375}\010\009local Charge = {Start = tick(), Max = 8}\010\009local BulletOffsets = {\010\009\009Vector3.new(0, 0.525, -2),\010\009\009Vector3.new(0.2, 0.365, -2),\010\009\009Vector3.new(0.2, 0.7, -2),\010\009\009Vector3.new(-0.2, 0.365, -2),\010\009\009Vector3.new(-0.2, 0.7, -2),\010\009}\010\009local FireSound = Sounds.Fire\010\009FireSound:Play()\010\009local Shooting = {Tick = 0, Delay = 0.25}\010\009while ToolEquipped and CurrentlyEquipped and CheckIfAlive() and MouseDown do\010\009\009local Now = tick()\010\009\009local ChargePercent = (Functions.Clamp(Functions.GetPercentage(Charge.Start, (Charge.Start + Charge.Max), Now), 0, 100) * 0.01)\010\009\009if BarrelMotor then\010\009\009\009BarrelMotor.MaxVelocity = Functions.Clamp((BarrelSpeed.Max * ChargePercent), BarrelSpeed.Min, BarrelSpeed.Max)\010\009\009end\010\009\009FireSound.Volume = Functions.Clamp((1 * ChargePercent), 0, 1)\010\009\009FireSound.Pitch = Functions.Clamp((0.75 * ChargePercent), 0.4, 0.75)\010\009\009Shooting.Delay = (1 - Functions.Clamp((0.75 * ChargePercent), 0.1, 0.75))\010\009\009if (Now - Shooting.Tick) >= Shooting.Delay and ChargePercent >= 0.25 then\010\009\009\009Shooting.Tick = Now\010\009\009\009local MouseData = InvokeClient(\034MouseData\034)\010\009\009\009if MouseData then\010\009\009\009\009local TargetPosition = MouseData.Position\010\009\009\009\009Spawn(function()\010\009\009\009\009\009for i, v in pairs(BulletOffsets) do\010\009\009\009\009\009\009if not ToolEquipped or not CurrentlyEquipped or not CheckIfAlive() or not MouseDown then\010\009\009\009\009\009\009\009return\010\009\009\009\009\009\009end\010\009\009\009\009\009\009local Projectile = BaseProjectile:Clone()\010\009\009\009\009\009\009local Color = ((not Player.Neutral and Player.TeamColor) or Projectile.BrickColor)\010\009\009\009\009\009\009Projectile.BrickColor = Color\010\009\009\009\009\009\009for i, v in pairs(Projectile:GetChildren()) do\010\009\009\009\009\009\009\009if v:IsA(\034Light\034) then\010\009\009\009\009\009\009\009\009v.Color = Color.Color\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009end\010\009\009\009\009\009\009local SparksCopy = Particles.Sparks:Clone()\010\009\009\009\009\009\009SparksCopy.Color = ColorSequence.new(Color.Color, Color.Color)\010\009\009\009\009\009\009SparksCopy.Enabled = true\010\009\009\009\009\009\009SparksCopy.Parent = Projectile\010\009\009\009\009\009\009local StartPosition = (Handle.CFrame * CFrame.new(v.X, v.Y, (v.Z - (Projectile.Size.Y / 1.5))))