0, Mass, 0),\010\009\009\009\009Parent = FirePart,\010\009\009\009}\010\009\009\009local Values = {\010\009\009\009\009{Name = \034Damage\034, Class = \034NumberValue\034, Value = 50},\010\009\009\009\009{Name = \034Type\034, Class = \034StringValue\034, Value = \034Fire\034},\010\009\009\009}\010\009\009\009for i, v in pairs(Values) do\010\009\009\009\009local Value = Create(v.Class){\010\009\009\009\009\009Name = v.Name,\010\009\009\009\009\009Value = v.Value,\010\009\009\009\009\009Parent = FirePart,\010\009\009\009\009}\010\009\009\009end\010\009\009\009Debris:AddItem(FirePart, Fire.Lifetime.Max)\010\009\009\009FirePart.Parent = GetProjectileManager()\010\009\009end\010\009\009wait()\010\009end\010\009if ToolUnequipped then\010\009\009ToolUnequipped:disconnect()\010\009end\010\009Fire.Enabled = false\010\009Debris:AddItem(Fire, 2)\010\009Sounds.Flame:Stop()\010\009Sounds.IgniteFlameOff:Play()\010end\010\010function Activated()\010\009if not Tool.Enabled or not ToolEquipped or not CheckIfAlive() or MouseDown then\010\009\009return\010\009end\010\009Tool.Enabled = false\010\009MouseDown = true\010\009if FireMode == Modes[1] then\010\009\009FireProjectiles()\010\009elseif FireMode == Modes[2] then\010\009\009SprayFire()\010\009end\010end\010\010function Deactivated()\010\009if not MouseDown then\010\009\009return\010\009end\010\009MouseDown = false\010\009if FireMode == Modes[1] then\010\009\009local DecreaseRate = 100\010\009\009local WaitRate = 0.03\010\009\009local CurrentMotor = BarrelMotor\010\009\009local FireSound = Sounds.Fire\010\009\009local MotorDecreaseAmount = (CurrentMotor.MaxVelocity / DecreaseRate)\010\009\009local FireVolume = (FireSound.Volume / DecreaseRate)\010\009\009local FirePitch = (FireSound.Pitch / DecreaseRate)\010\009\009for i = 1, DecreaseRate do\010\009\009\009local DecreaseAmount = (DecreaseRate - i)\010\009\009\009CurrentMotor.MaxVelocity = (MotorDecreaseAmount * DecreaseAmount)\010\009\009\009FireSound.Volume = (FireVolume * DecreaseAmount)\010\009\009\009FireSound.Pitch = (FirePitch * DecreaseAmount)\010\009\009\009wait(WaitRate)\010\009\009end\010\009\009Sounds.Fire:Stop()\010\009elseif FireMode == Modes[2] then\010\009\009local Smoke = Particles.Smoke:Clone()\010\009\009Smoke.Enabled = true\010\009\009Debris:AddItem(Smoke, 3)\010\009\009Delay(1.5, (function()\010\009\009\009Smoke.Enabled = false\010\009\009end))\010\009\009Smoke.Parent = Flamethrower\010\009\009wait(2.5)\010\009end\010\009Tool.Enabled = true\010end\010\010function UpdateGui()\010\009if not ModeGuiCopy then\010\009\009return\010\009end\010\009local MainFrame = ModeGuiCopy:FindFirstChild(\034MainFrame\034)\010\009if not MainFrame then\010\009\009return\010\009end\010\009local Button = MainFrame:FindFirstChild(\034Button\034)\010\009if not Button then\010\009\009return\010\009end\010\009local ModeText = Button:FindFirstChild(\034ModeText\034)\010\009if not ModeText then\010\009\009return\010\009end\010\009ModeText.Text = FireMode.Text\010\009ModeText.TextColor3 = FireMode.Color\010end\010\010function Equipped()\010\009Character = Tool.Parent\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009Player = Players:GetPlayerFromCharacter(Character)\010\009if not CheckIfAlive() then\010\009\009return\010\009end\010\009Spawn(function()\010\009\009local PlayerGui = Player:FindFirstChild(\034PlayerGui\034)\010\009\009if PlayerGui then\010\009\009\009ModeGuiCopy = ModeGui:Clone()\010\009\009\009local Values = {\010\009\009\009\009{Name = \034ServerConnection\034, Class = \034ObjectValue\034, Value = ServerControl},\010\009\009\009\009{Name = \034Tool\034, Class = \034ObjectValue\034, Value = Tool},\010\009\009\009}\010\009\009\009for i, v in pairs(Values) do\010\009\009\009\009local Value = Create(v.Class){\010\009\009\009\009\009Name = v.Name,\010\009\009\009\009\009Value = v.Value,\010\009\009\009\009\009Parent = ModeGuiCopy,\010\009\009\009\009}\010\009\009\009end\010\009\009\009UpdateGui()\010\009\009\009ModeGuiCopy.P