T[#T+1]={id=20683,class="Script",parent=20681,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="ProjectileManager",["ScriptGuid"]="{799CA8C1-1BD0-4627-BE17-A6FCB4AEAADF}",["Source"]="--Made by Luckymaxer\010\010Model = script.Parent\010\010Players = game:GetService(\034Players\034)\010Debris = game:GetService(\034Debris\034)\010local TEAM = script.TEAM\010\010FunctionsLibrary = script:FindFirstChild(\034Functions\034)\010ParticleScript = script:FindFirstChild(\034ParticleScript\034)\010Fire = script:FindFirstChild(\034EffectFire\034)\010\010RbxUtility = LoadLibrary(\034RbxUtility\034)\010Create = RbxUtility.Create\010\010Sounds = {\010\009Hit = script:FindFirstChild(\034Hit\034),\010}\010\010FadeRate = 0.025\010Rate = (1 / 15)\010\010Removing = false\010\010Values = {}\010for i, v in pairs(script:GetChildren()) do\010\009if string.find(string.lower(v.ClassName), string.lower(\034Value\034)) then\010\009\009Values[v.Name] = v\010\009end\010end\010\010function GetCreator()\010\009local Creator = Values.Creator.Value\010\009return (((Creator and Creator.Parent and Creator:IsA(\034Player\034)) and Creator) or nil)\010end\010\010function ManageProjectile(Part)\010\009local AlreadyHit = false\010\009local Creator = GetCreator()\010\009local Type = Part:FindFirstChild(\034Type\034)\010\009local Damage = Part:FindFirstChild(\034Damage\034)\010\009if not Type or not Type:IsA(\034StringValue\034) or not Damage or not Damage:IsA(\034NumberValue\034) then\010\009\009return\010\009end\010\009Part.Touched:connect(function(Hit)\010\009\009local Creator = GetCreator()\010\009\009if not Hit or not Hit.Parent or not Creator or AlreadyHit or Functions.CheckIntangible(Hit) then\010\009\009\009return\010\009\009end\010\009\009local character = Hit.Parent\010\009\009if character:IsA(\034Hat\034) then\010\009\009\009character = character.Parent\010\009\009end\010\009\009local player = Players:GetPlayerFromCharacter(character)\010\009\009if not player or (player and player ~= Creator and not Functions.IsTeamMate(Creator, player)) then\010\009\009\009local humanoid = character:FindFirstChild(\034Humanoid\034)\010\009\009\009if humanoid and humanoid.Health > 0 and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009Functions.UntagHumanoid(humanoid)\010\009\009\009\009Functions.TagHumanoid(humanoid, Creator)\010\009\009\009\009humanoid:TakeDamage(Damage.Value)\010\009\009\009\009if Type.Value == \034Fire\034 then\010\009\009\009\009\009local IgniteChance = math.random(1, 2)\010\009\009\009\009\009if ParticleScript and Fire and IgniteChance == 1 and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009\009\009local EffectFire = Hit:FindFirstChild(Fire.Name)\010\009\009\009\009\009\009if not EffectFire then\010\009\009\009\009\009\009\009EffectFire = Fire:Clone()\010\009\009\009\009\009\009\009EffectFire.Enabled = true\010\009\009\009\009\009\009\009local ParticleScriptCopy = ParticleScript:Clone()\010\009\009\009\009\009\009\009ParticleScriptCopy.Disabled = false\010\009\009\009\009\009\009\009ParticleScriptCopy.Parent = EffectFire\010\009\009\009\009\009\009\009local Duration = Create(\034NumberValue\034){\010\009\009\009\009\009\009\009\009Name = \034Duration\034,\010\009\009\009\009\009\009\009\009Parent = EffectFire,\010\009\009\009\009\009\009\009}\010\009\009\009\009\009\009end\010\009\009\009\009\009\009local Duration = EffectFire:FindFirstChild(\034Duration\034)\010\009\009\009\009\009\009if Duration and Duration:IsA(\034NumberValue\034) then\010\009\009\009\009\009\009\009Duration.Value = 4\010\009\009\009\009\009\009end\010\009\009\009\009\009\009EffectFire.Parent = Hit\010\009\009\009\009\009end\010\009\009\009\009elseif Type.Value == \034Projectile\034 then\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009\009if Type.Value == \034Projectile\034 then\010\009\009\009AlreadyHit = true\010\009\009\009Part.Name = \034Effect\034\010\009\009\009Part.Transparency = 1\010\009\009\009Part.CanCollide = false\010\009\009\009Part.Anchored = true\010\009\009\009for i, v in pairs(Part:GetChildren()) do\010\009\009\009\009if v:IsA(\034ParticleEmitter\034) then\010\009\009\009\009\009v.Enabled = false\010\009\009\009\009end\010\009\009\009end\010\009\009\009local Sound = Sounds.Hit\010\009\009\009if Sound then\010\009\009\009\009local SoundCopy = Sound:Clone()\010\009\009\009\009Debris:AddItem(SoundCopy, 1.5)\010\009\009\009\009SoundCopy.Parent = Part\010\009\009\009\009SoundCopy:Play()\010\009\009\009end\010\009\009\009Debris:AddItem(Part, 1.5)\010\009\009end\010\009end)\010end\010\010function RemoveModel()\010\009if Removing then\010\009\009return\010\009end\010\009local Parts = {}\010\009for i, v in pairs(Model:GetChildren()) do\010\009\009if v:IsA(\034BasePart\034) then\010\009\009\009table.insert(Parts, v)\010\009\009end\010\009end\010\009if #Parts == 0 then\010\009\009Removing = true\010\009\009Model.Name = \034\034\010\009\009Debris:AddItem(Model, 0.5)\010\009end\010end\010\010if not FunctionsLibrary or not Values.Creator then\010\009RemoveModel()\010\009return\010end\010\010Functions = require(FunctionsLibrary)\010\010Model.ChildAdded:connect(function(Child)\010\009if Child:IsA(\034BasePart\034) and Child.Name == \034Projectile\034 then\010\009\009ManageProjectile(Child)\010\009end\010end)\010\010Model.ChildRemoved:connect(function(Child)\010\009RemoveModel()\010end)\010\010wait(1)\010\010RemoveModel()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20684,class="Script",parent=20683,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="ParticleScript",["ScriptGuid"]="{FE98CCC4-F85D-488A-80A8-0CA5C0EE8A03}",["Source"]="--Made by Luckymaxer\010\010Particle = script.Parent\010\010Debris = game:GetService(\034Debris\034)\010\010Duration = Particle:WaitForChild(\034Duration\034)\010\010while Duration.Value > 0 do\010\009local Time = wait()\010\009Duration.Value = (Duration.Value - Time)\010end\010\010Particle.Enabled = false\010\010Debris:AddItem(Particle, 2)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20704,class="Script",parent=20703,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="DamageTag",["ScriptGuid"]="{8AE0EF8C-B4D0-405D-9D13-DC1FB94B244D}",["Source"]="wait()\010h = script.Parent:findFirstChild(\034Humanoid\034)\010if h ~= nil then\010\009while h:findFirstChild(\034creator\034) do\010\009\009h.creator:Destroy()\010\009end\010\009tag = script.creator:clone()\010\009tag.Parent = h\010\009game.Debris:AddItem(tag,5)\010\009h:TakeDamage(script.Damage.Value)\010end\010script:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20728,class="Script",parent=20717,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="AIUseFPSMode",["ScriptGuid"]="{3159E0EB-B11E-49BC-9C12-76BC9634F88F}",["Source"]="gyro = Instance.new(\034BodyGyro\034)\010gyro.Parent = script.Parent:findFirstChild(\034Torso\034)\010gyro.P = 7500\010gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\010script.Parent.Humanoid.StateChanged:connect(function(Old,New)\010\009if New == Enum.HumanoidStateType.Running then\010\009\009gyro.P = 7500\010\009\009gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\009else\010\009\009gyro.P = 0\010\009\009gyro.maxTorque = Vector3.new(0,0,0)\010\009end\010end)\010\010while true do\010\009vCharacter = script.Parent\010\009if vCharacter ~= nil then \010\009\009gyro.Parent = script.Parent.Torso\010\009\009local tp\010\009\009if (vCharacter.Target.Value) and vCharacter.Humanoid:GetState() then\010\009\009\009tp = vCharacter.Target.Value.Position\010\009\009else\010\009\009\009tp = vCharacter.Humanoid.WalkToPoint\010\009\009end\010\009\009tp = Vector3.new(tp.X,script.Parent.Torso.Position.Y,tp.Z) \010\009\009local dir = (tp - script.Parent.Torso.Position).unit\010\009\009local spawnPos = script.Parent.Torso.Position\010\009\009local pos = spawnPos + (dir * 1)\010\009\009gyro.cframe = CFrame.new(pos,  pos + dir)\010\009elseif not vCharacter.Attack.Value then\010\009\009gyro.Parent = nil\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20850,class="Script",parent=20717,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Death-On-Spawn Debugger",["ScriptGuid"]="{EA7A6FF5-42F8-4447-BB4B-EB86A0A5A6A6}",["Source"]="--You must anchor all part to make this script work. This will reduce a chance to happen Death-On-Spawn glitch.\010wait()\010parts = script.Parent:children()\010script.Parent:MakeJoints()\010for i = 1,#parts do\010\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 or parts[i].className == \034UnionOperation\034 then\010\009\009if parts[i].Anchored == true then\010\009\009\009parts[i].Anchored = false\010\009\009\009script.Parent:MakeJoints()\010\009\009end\010\009end\010end\010script.Parent:MakeJoints()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20855,class="Script",parent=20717,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{3534EF44-775C-48D9-9DCD-085168E4AD60}",["Source"]="wait()\010function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010--[[local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)]]\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimInstance = nil\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=481142564\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=481142564\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=481143027\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=180436148\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=180436334\034, weight = 10 } \010\009\009\009}, \010\009sit = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=178130996\034, weight = 10 } \010\009\009\009},\009\010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182393478\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182435998\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491037\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491065\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436842\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491248\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491277\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436935\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491368\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491423\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009currentAnimInstance = nil\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if frameName == \034Footstep1\034 or frameName == \034Footstep2\034 then Figure.FakeTorso[\034Footstep\034..math.random(1,4)]:Play() end\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\010\009\009local repeatAnim = currentAnim\010\009\009-- return to idle if finishing an emote\010\009\009if (emoteNames[repeatAnim] ~= nil and emoteNames[repeatAnim] == false) then\010\009\009\009repeatAnim = \034idle\034\010\009\009end\010\009\009\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid) \010\009\009\010\009local roll = math.random(1, animTable[animName].totalWeight) \010\009local origRoll = roll\010\009local idx = 1\010\009while (roll > animTable[animName][idx].weight) do\010\009\009roll = roll - animTable[animName][idx].weight\010\009\009idx = idx + 1\010\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009local anim = animTable[animName][idx].anim\010\010\009-- switch animation\009\009\010\009if (anim ~= currentAnimInstance) then\010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\009\009currentAnimInstance = anim\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009\009\010\009end\010\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local toolAnimInstance = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\009\010\009\009playToolAnimation(toolAnimName, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\009 \010\009\009\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009if (toolAnimInstance ~= anim) then\010\009\009\009\010\009\009\009if (toolAnimTrack ~= nil) then\010\009\009\009\009toolAnimTrack:Stop()\010\009\009\009\009toolAnimTrack:Destroy()\010\009\009\009\009transitionTime = 0\010\009\009\009end\010\009\009\009\009\009\010\009\009\009-- load it to the humanoid; get AnimationTrack\010\009\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009\009 \010\009\009\009-- play the animation\010\009\009\009toolAnimTrack:Play(transitionTime)\010\009\009\009toolAnimName = animName\010\009\009\009toolAnimInstance = anim\010\010\009\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009toolAnimInstance = nil\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009--[[if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end]]\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009--playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010--[[function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end]]\010\010--[[function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end]]\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009--playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009--playAnimation(\034sit\034, 0.5, Humanoid)\010\009\009return\010\009--[[elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)]]\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009stopAllAnimations()\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009--[[desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)]]\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009--animStringValueObject = getToolAnim(tool)\010\010\009\009--[[if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end]]\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009--animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimInstance = nil\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010--[[Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)]]\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009--[[print((Torso.Velocity * Vector3.new(1,0,1)).magnitude)\010\009print(pose)]]\010\009if (Torso.Velocity * Vector3.new(1,0,1)).magnitude > 1 and pose ~= \034Running\034 then\010\009\009pose = \034Running\034\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (Torso.Velocity * Vector3.new(1,0,1)).magnitude < 1 and pose ~= \034Standing\034 then\010\009\009pose = \034Standing\034\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009end\010\009local _, time = wait(0.01)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20876,class="Script",parent=20875,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Jump",["ScriptGuid"]="{277F027F-42DE-4861-B32A-C1AB1C4D488C}",["Source"]="local CanJump = true\010\010script.Parent.Changed:connect(function()\010\009if script.Parent.Jump == true then\010\009\009script.Parent.Jump = false\010\009\009if CanJump then\010\009\009\009CanJump = false\010\009\009\009script.Parent.Torso.Velocity = script.Parent.Torso.Velocity + Vector3.new(0,script.Parent.JumpPower,0)\010\009\009\009wait(2)\010\009\009\009CanJump = true\010\009\009end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20878,class="Script",parent=20717,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{EA27E41A-AB93-4306-83C1-A4AA1CAEE2CD}",["Source"]="local Model = script.Parent\010local Humanoid = Model.Humanoid\010\010function ChooseRandomPart()\010\009local PartToChoose = {}\010\009for _, Child in pairs(Model:GetChildren()) do\010\009\009if Child:IsA(\034BasePart\034) then\010\009\009\009table.insert(PartToChoose,Child)\010\009\009end\010\009end\010\009return PartToChoose[math.random(1,#PartToChoose)]\010end\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Death:Play()\010\009local e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009local parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 or parts[i].className == \034UnionOperation\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-75,75),math.random(75,150),math.random(-75,75))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\010\009wait(10)\010\009script.Parent:remove() \010end \010\010Humanoid.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20880,class="Script",parent=20879,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Launcher",["ScriptGuid"]="{8B34738A-FEC8-44EE-BC8F-3C0432E6A0ED}",["Source"]="wait()\010-----------------\010--| Constants |--\010-----------------\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010local GRAVITY_ACCELERATION = 196.2\010\010local RELOAD_TIME = 0.10 -- Seconds until tool can be used again\010local ROCKET_SPEED = 0 -- Speed of the projectile\010\010local MISSILE_MESH_ID = 'rbxassetid://189741947'\010local MISSILE_TEXTURE_ID = 'rbxassetid://189741994'\010local MISSILE_MESH_SCALE = Vector3.new(2.5, 2.5, 2.5)\010local ROCKET_PART_SIZE = Vector3.new(1,1,1)\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Tool = script.Parent\010\010local RocketScript = script:WaitForChild('Rocket')\010--local SwooshSound = script:WaitForChild('Swoosh')\010local BoomSound = script:WaitForChild('Boom')\010--local BoomSound2 = script:WaitForChild('Boom2')\010local ShootSound = Tool.Parent.FakeTorso:WaitForChild('ShootRocket')\010\010local Pod = 1\010\010--NOTE: We create the rocket once and then clone it when the player fires\010local Rocket = Instance.new('Part') do\010\009-- Set up the rocket part\010\009Rocket.Name = 'Rocket'\010\009Rocket.FormFactor = Enum.FormFactor.Custom --NOTE: This must be done before changing Size\010\009Rocket.Size = ROCKET_PART_SIZE\010\009Rocket.CanCollide = false\010\009Rocket.Anchored = true\010\010\009-- Add the mesh\010\009local mesh = Instance.new('SpecialMesh', Rocket)\010\009mesh.MeshId = MISSILE_MESH_ID\010\009mesh.TextureId = MISSILE_TEXTURE_ID\010\009mesh.Scale = MISSILE_MESH_SCALE\010\009mesh.Offset = Vector3.new(0, 0, -1)\010\010\009-- Add fire\010\009--[[local fire = Instance.new('Fire', Rocket)\010\009fire.Heat = 5\010\009fire.Size = 2]]\010\009local fire = script.Effect:Clone()\010\009fire.Enabled = true\010\009fire.Parent = Rocket\010\009\010\009local TargetValue = Instance.new('ObjectValue', Rocket)\010\009TargetValue.Name = 'Target' --NOTE: Must be called 'creator' for website stats\010\009Tool.Parent.TEAM:Clone().Parent = Rocket\010\010\009-- Add a force to counteract gravity\010\009local bodyForce = Instance.new('BodyForce', Rocket)\010\009bodyForce.Name = 'Antigravity'\010\009bodyForce.force = Vector3.new(0, Rocket:GetMass() * GRAVITY_ACCELERATION, 0)\010\010\009-- Clone the sounds and set Boom to PlayOnRemove\010\009--[[local swooshSoundClone = SwooshSound:Clone()\010\009swooshSoundClone.Parent = Rocket]]\010\009local boomSoundClone = BoomSound:Clone()\010\009boomSoundClone.PlayOnRemove = true\010\009boomSoundClone.Parent = Rocket\010\009--[[local boomSoundClone2 = BoomSound2:Clone()\010\009boomSoundClone2.PlayOnRemove = true\010\009boomSoundClone2.Parent = Rocket]]\010\010\009-- Finally, clone the rocket script and enable it\010\009local rocketScriptClone = RocketScript:Clone()\010\009rocketScriptClone.Parent = Rocket\010\009rocketScriptClone.Disabled = false\010end\010\010-----------------\010--| Functions |--\010-----------------\010\010local function Equip()\010\009\010end\010\010local function Unequip()\010\009\010end\010\010local function OnActivated()\010\009local myModel = Tool.Parent\010\009if Tool.Enabled and myModel and myModel:FindFirstChild('Humanoid') and myModel.Humanoid.Health > 0 then\010\009\009Tool.Enabled = false\010\009\009\010\009\009ShootSound:Play()\010\010\009\009-- Create a clone of Rocket and set its color\010\009\009local rocketClone = Rocket:Clone()\010\009\009DebrisService:AddItem(rocketClone, 30)\010\010\009\009rocketClone.Target.Value = myModel.Target.Value\010\010\009\009-- Position the rocket clone and launch!\010\009\009local spawnPosition = (Tool.Parent[\034RocketPod\034..Pod].CFrame * CFrame.new(0, 2, 0)).p\010\009\009rocketClone.CFrame = CFrame.new(spawnPosition, myModel.Target.Value.Position) * CFrame.Angles(math.rad(90), math.rad(-22.5+(math.random()*45)), 0) --NOTE: This must be done before assigning Parent\010\009\009rocketClone.Velocity = rocketClone.CFrame.lookVector --NOTE: This should be done before assigning Parent\010\009\009rocketClone.Parent = Workspace\010\010\009\009Pod = Pod == 1 and 2 or 1\010\010\009\009wait(RELOAD_TIME)\010\010\009\009Tool.Enabled = true\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010--Tool.Activated:connect(OnActivated)\010Tool.Equipped:connect(Equip)\010Tool.Unequipped:connect(Unequip)\010\010while true do\010\009if Tool.Parent.Attack.Value == true then OnActivated() end\010\009game:GetService(\034RunService\034).Stepped:wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20882,class="Script",parent=20880,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Rocket",["ScriptGuid"]="{556899C0-667E-4B7F-8C1D-A71CFDADD82D}",["Source"]="-----------------\010--| Constants |--\010-----------------\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010local BLAST_RADIUS = 12 -- Blast radius of the explosion\010local BLAST_DAMAGE = 80 -- Amount of damage done to players\010local BLAST_FORCE = 125 -- Amount of force applied to parts\010\010local IGNORE_LIST = {rocket = 1, effect = 1, water = 1} -- Rocket will fly through things named these\010--NOTE: Keys must be lowercase, values must evaluate to true\010\010Explode = Instance.new(\034Part\034)\010Explode.formFactor = \034Custom\034\010Explode.Size = Vector3.new(0,0,0)\010Explode.Anchored = true\010Explode.CanCollide = false\010Explode.TopSurface = 0\010Explode.BottomSurface = 0\010Explode.BrickColor = BrickColor.new(\034Deep orange\034)\010Mesh = Instance.new(\034SpecialMesh\034,Explode)\010Mesh.MeshType = \034Brick\034\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009return hit2,pos2\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Rocket = script.Parent\010\010--local CreatorTag = Rocket:WaitForChild('creator')\010--local SwooshSound = Rocket:WaitForChild('Swoosh')\010local Target = Rocket:WaitForChild('Target')\010local TEAM = Rocket:WaitForChild('TEAM')\010\010-----------------\010--| Functions |--\010-----------------\010\010-- Removes any old creator tags and applies a new one to the target\010--[[local function ApplyTags(target)\010\009while target:FindFirstChild('creator') do\010\009\009target.creator:Destroy()\010\009end\010\010\009local creatorTagClone = CreatorTag:Clone()\010\009DebrisService:AddItem(creatorTagClone, 1.5)\010\009creatorTagClone.Parent = target\010end]]\010\010-- Returns the ancestor that contains a Humanoid, if it exists\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009local humanoid = subject:FindFirstChild('Humanoid')\010\009\009if humanoid then\010\009\009\009return subject, humanoid\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010-- Customized explosive effect that doesn't affect teammates and only breaks joints on dead parts\010local function OnExplosionHit(hitPart, hitDistance, blastCenter)\010\009if hitPart and hitDistance then\010\009\009local character, humanoid = FindCharacterAncestor(hitPart.Parent)\010\009\009if humanoid and humanoid.Health > 0 then -- Humanoids are tagged and damaged\010\009\009\009if hitPart.Name == 'Torso' then\010\009\009\009\009--ApplyTags(humanoid)\010\009\009\009\009--DamageTag(character,BLAST_DAMAGE)\010\009\009\009\009if humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009\009humanoid:TakeDamage(BLAST_DAMAGE)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010end\010\010local function OnTouched(otherPart,RayPos)\010\009if Rocket and otherPart then\010\009\009-- Fly through anything in the ignore list\010\009\009if IGNORE_LIST[string.lower(otherPart.Name)] then\010\009\009\009return\010\009\009end\010\010\009\009--[[local myPlayer = CreatorTag.Value\010\009\009if myPlayer then\010\009\009\009-- Fly through the creator\010\009\009\009if myPlayer.Character and myPlayer.Character:IsAncestorOf(otherPart) then\010\009\009\009\009return\010\009\009\009end\010\010\009\009\009 -- Fly through friendlies\010\009\009\009if not myPlayer.Neutral then\010\009\009\009\009local character = FindCharacterAncestor(otherPart.Parent)\010\009\009\009\009local player = PlayersService:GetPlayerFromCharacter(character)\010\009\009\009\009if player and player ~= myPlayer and player.TeamColor == Rocket.BrickColor then\010\009\009\009\009\009return\010\009\009\009\009end\010\009\009\009end\010\009\009end]]\010\010\009\009-- Fly through terrain water\010\009\009if otherPart == Workspace.Terrain then\010\009\009\009--NOTE: If the rocket is large, then the simplifications made here will cause it to fly through terrain in some cases\010\009\009\009local frontOfRocket = Rocket.Position + (Rocket.CFrame.lookVector * (Rocket.Size.Z / 2))\010\009\009\009local cellLocation = Workspace.Terrain:WorldToCellPreferSolid(frontOfRocket)\010\009\009\009local cellMaterial = Workspace.Terrain:GetCell(cellLocation.X, cellLocation.Y, cellLocation.Z)\010\009\009\009if cellMaterial == Enum.CellMaterial.Water or cellMaterial == Enum.CellMaterial.Empty then\010\009\009\009\009return\010\009\009\009end\010\009\009end\010\009\009\010\009\009Rocket.Transparency = 1\010\009\009Rocket.CFrame = CFrame.new(RayPos.X,RayPos.Y,RayPos.Z)\010\010\009\009-- Create the explosion\010\009\009local explosion = Instance.new('Explosion')\010\009\009explosion.BlastPressure = 5000 -- Completely safe explosion\010\009\009explosion.BlastRadius = BLAST_RADIUS\010\009\009explosion.DestroyJointRadiusPercent = 0\010\009\009explosion.ExplosionType = Enum.ExplosionType.NoCraters\010\009\009explosion.Position = Rocket.Position\010\009\009explosion.Parent = Workspace\010\010\009\009-- Connect custom logic for the explosion\010\009\009explosion.Hit:connect(function(hitPart, hitDistance) OnExplosionHit(hitPart, hitDistance, explosion.Position) end)\010\009\009\010\009\009--[[ypcall(function()\010\009\009\009for i = 1, 3 do\010\009\009\009\009ExplodeClone = Explode:clone()\010\009\009\009\009ExplodeClone.Position = Rocket.Position\010\009\009\009\009ExplodeClone.Mesh.Scale = Vector3.new(5,5,5)*5\010\009\009\009\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009\009\009\009ExplodeClone.Parent = Workspace\010\009\009\009\009NewScript = Rocket.Script:clone()\010\009\009\009\009NewScript.Disabled = false\010\009\009\009\009NewScript.Parent = ExplodeClone\010\009\009\009end\010\009\009end)]]\010\010\009\009-- Move this script and the creator tag (so our custom logic can execute), then destroy the rocket\010\009\009script.Parent = explosion\010\009\009--CreatorTag.Parent = script\010\009\009Rocket:Destroy()\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010--SwooshSound:Play()\010\010--Rocket.Touched:connect(OnTouched)\010\010local RotSpeed = 0\010\010for i = 1,math.huge do\010\009if RotSpeed < 0.375 then RotSpeed = RotSpeed + 0.0125 end\010\009--[[ExplodeClone = Explode:clone()\010\009ExplodeClone.Name = \034Effect\034\010\009ExplodeClone.BrickColor = BrickColor.new(\034White\034)\010\009ExplodeClone.Position = Rocket.Position\010\009ExplodeClone.Mesh.Scale = Vector3.new(1,1,1)*5\010\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009ExplodeClone.Parent = Workspace\010\009NewScript = Rocket.Trail:clone()\010\009NewScript.Disabled = false\010\009NewScript.Parent = ExplodeClone]]\010\009if Target.Value ~= nil and Target.Value.Parent ~= nil then\010\009\009if Target.Value then idealVelocity = --[[SPEED *]] (Target.Value.Position - Rocket.Position).unit end\010\009\009Rocket.Velocity = --[[SPEED *]] (Rocket.Velocity + RotSpeed * (idealVelocity - Rocket.Velocity)).unit\010\009\009Rocket.CFrame = CFrame.new(Rocket.Position, Rocket.Position + Rocket.Velocity)\010\009end\010\009local hit,pos = raycast(Rocket.Position,((Rocket.CFrame * CFrame.new(0,0,-10)).p-Rocket.Position).unit,10)\010\009if hit then\010\009\009OnTouched(hit,pos)\010\009end\010\009Rocket.CFrame = Rocket.CFrame * CFrame.new(0,0,-2.5)-- * CFrame.Angles(0, 0, math.rad(18))\010\009game:GetService(\034RunService\034).Stepped:wait()\010\009if script.Parent ~= Rocket then break end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20897,class="Script",parent=20885,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Firescript",["ScriptGuid"]="{D5746B52-7DB6-4CF1-B094-3038B207AB56}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010check=true\010\010gundamage=80\009\009\009\009\009\009\009\009--Base output damage per shot.\010firerate=.1\009\009\009\009\009\009\009\009--How often the weapon can fire.\010automatic=true\009\009\009\009\009\009\009--hold down to continue firing\010range=1000\009\009\009\009\009\009\009\009\009--Max distance that the weapon can fire.\010spread=2\009\009\009\009\009\009\009\009\009\009--The bigger the spread, the more inaccurate the shots will be.\010clipsize=50\009\009\009\009\009\009\009\009\009--Shots in a clip\010reloadtime=1.2\009\009\009\009\009\009\009\009--Time it takes to reload the tool.\010startingclips=10\009\009\009\009\009\009\009--If you want infinit clips, remove the IntValue named \034Clips\034 from the tool.\010segmentlength=25\009\009\009\009\009\009\009--How long the shot segments are, or the speed of the shot.\010fadedelaytime=1/30\010\010\010barrelpos=CFrame.new(0,0,0.5)\009\009--R,U,B\010rate=1/100\010intangibles={\034Shock\034,\034Bolt\034,\034Bullet\034,\034Plasma\034,\034Effect\034,\034Laser\034,\034Handle\034,\034Effects\034,\034Effect\034,\034Flash\034}\010colors={BrickColor.new(\034Really red\034),BrickColor.new(\034Pastel blue-green\034),BrickColor.new(\034Lime green\034),BrickColor.new(\034New Yeller\034)}\010flashcolors={\034Really red\034}\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010reloading=false\010local debris=game:GetService(\034Debris\034)\010\010local ammo=sp:FindFirstChild(\034Ammo\034)\010if ammo~=nil then\010\009ammo.Value=clipsize\010end\010local clips=sp:FindFirstChild(\034Clips\034)\010if clips~=nil then\010\009clips.Value=startingclips\010end\010\010sp.Equipped:connect(function()\010\009sp.Parent.Eye.Fire:Stop()\010\009sp.Parent.Eye.Reload:Stop()\010end)\010sp.Unequipped:connect(function()\010\009sp.Parent.Eye.Fire:Stop()\010\009sp.Parent.Eye.Reload:Stop()\010end)\010\010function round(number,decimal)\010\009decimal=decimal or 0\010\009local mult=10^decimal\010\009return math.floor(number*mult+.5)/mult\010end\010\010function checkintangible(t)\010\009for i3,v3 in ipairs(intangibles) do\010\009\009if string.lower(v3)==string.lower(t.Name) or t.Transparency==1 then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function reload()\010\009reloading=true\010\009sp.Reloading.Value=true\010\009if clips~=nil then\010\009\009if clips.Value>0 then\010\009\009\009clips.Value=clips.Value-1\010\009\009else\010\009\009\009reloading=false\010\009\009\009sp.Reloading.Value=false\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Eye.Reload:Play()\010\009for i=1,clipsize do\010\009\009wait(reloadtime/clipsize)\010\009\009ammo.Value=i\010\009end\010\009reloading=false\010\009sp.Reloading.Value=false\010end\010\010function castray(startpos,vec,length,ignore,delayifhit)\010\009if length>999 then\010\009\009length=999\010\009end\010\009hit,endpos2=game.Workspace:FindPartOnRay(Ray.new(startpos,vec*length),ignore)\010\009if hit~=nil then\010\009\009if checkintangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit,endpos2=castray(endpos2+(vec*.01),vec,length-((startpos-endpos2).magnitude),ignore,delayifhit)\010\009\009end\010\009end\010\009return hit,endpos2\010end\010\010function sendbullet(boltstart,targetpos,fuzzyness,segmentlength,ignore,clr,damage,fadedelay)\010\009if ammo~=nil then\010\009\009if ammo.Value>0 then\010\009\009\009ammo.Value=ammo.Value-1\010\009\009else\010\009\009\009reload()\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Eye.Fire:Play()\010\009muzzleeffect()\010\009local t=sp.Parent:FindFirstChild(\034Torso\034)\010\009if t~=nil then\010\009\009local shoulder=t:FindFirstChild(\034Right Shoulder\034)\010\009\009if shoulder~=nil then\010\009\009\009shoulder.CurrentAngle=2\010\009\009end\010\009end\010\010\009local boltdist=range\010\009local clickdist=(boltstart-targetpos).magnitude\010\009local targetpos=targetpos+(Vector3.new(math.random()-.5,math.random()-.5,math.random()-.5)*(clickdist/100)*fuzzyness)\010\009local boltvec=(targetpos-boltstart).unit\010\009local totalsegments=math.ceil(boltdist/segmentlength)\010\009local lastpos=boltstart\010\009for i=1,totalsegments do\010\009\009local newpos=(boltstart+(boltvec*(boltdist*(i/totalsegments))))\010\009\009local segvec=(newpos-lastpos).unit\010\009\009local boltlength=(newpos-lastpos).magnitude\010\009\009local bolthit,endpos=castray(lastpos,segvec,boltlength,ignore,false)\010\009\009drawbeam(lastpos,endpos,clr,fadedelay)\010\009\009if bolthit~=nil then\010\009\009\009local h=bolthit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local t=bolthit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h~=nil and t and t.Value ~= sp.Parent.TEAM.Value then\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009end\010\009\009\009break\010\009\009end\010\009\009lastpos=endpos\010\009\009wait(rate)\010\009end\010end\010\010function drawbeam(beamstart,beamend,clr,fadedelay)\010\009local dis=(beamstart-beamend).magnitude\010\009local laser=Instance.new(\034Part\034)\010\009laser.Name=\034Bullet\034\010\009laser.Transparency = 0\010\009laser.Anchored=true\010\009laser.CanCollide=false\010\009laser.Shape=\034Block\034\010\009laser.formFactor=\034Custom\034\010\009laser.Size=Vector3.new(.375,.375,dis+.2)\010\009laser.Material=Enum.Material.Neon\010\009laser.Locked=true\010\009laser.TopSurface=0\010\009laser.BottomSurface=0\010\009laser.BrickColor=clr\010\009laser.CFrame=CFrame.new(beamend,beamstart)*CFrame.new(0,0,-dis/2)\010\009--[[local mesh = Instance.new(\034BlockMesh\034,laser)\010\009mesh.Scale = Vector3.new(10,0,1)\010\009local decal = Instance.new(\034Decal\034,laser)\010\009decal.Face = \034Top\034\010\009decal.Texture = \034rbxassetid://201063866\034\010\009decal.Transparency = 0.25\010\009local decal2 = decal:Clone()\010\009decal2.Face = \034Bottom\034\010\009decal2.Parent = decal.Parent]]\010\009local light = script.SurfaceLight:Clone()\010\009light.Enabled = true\010\009light.Face = \034Top\034\010\009light.Parent = laser\010\009local light2 = script.SurfaceLight:Clone()\010\009light2.Enabled = true\010\009light.Face = \034Bottom\034\010\009light2.Parent = laser\010\009laser.Parent=game.Workspace\010\009debris:AddItem(laser,fadedelay)\010end\010\010function muzzleeffect()\010\009local flash=Instance.new(\034Part\034)\010\009flash.Name=\034Effect\034\010\009flash.Anchored=true\010\009flash.CanCollide=false\010\009flash.Shape=\034Block\034\010\009flash.formFactor=\034Custom\034\010\009flash.Size=Vector3.new(.2,.2,.2)\010\009flash.Material=Enum.Material.Plastic\010\009flash.Locked=true\010\009flash.TopSurface=0\010\009flash.BottomSurface=0\010\009flash.BrickColor=BrickColor.new(flashcolors[math.random(1,#flashcolors)])\010\009local mesh=Instance.new(\034SpecialMesh\034)\010\009mesh.MeshId=\034http://www.roblox.com/asset/?id=25212400\034\010\009local scale=Vector3.new(.2+(math.random()*.1),.4+(math.random()*.4),.2+(math.random()*.1))\010\009mesh.Scale=scale\010\009mesh.Parent=flash\010\009flash.CFrame=sp.Parent.Eye.CFrame*barrelpos*CFrame.Angles(0,math.pi*2*math.random(),0)*CFrame.new(0,scale.y*.9,0)\010\009debris:AddItem(flash,rate)\010\009flash.Parent=game.Workspace\010end\010\010sp.Down.Changed:connect(function()\010\009while sp.Down.Value and check and not reloading do\010\009\009check=false\010\009\009local humanoid=sp.Parent:FindFirstChild(\034Humanoid\034)\010\009\009if humanoid~=nil then\010\009\009\009if humanoid.Health>0 then\010\009\009\009\009spos1=(sp.Parent.Eye.CFrame*barrelpos).p\010\009\009\009\009delay(0,function() sendbullet(spos1,sp.Aim.Value,spread,segmentlength,sp.Parent,colors[1],gundamage,fadedelaytime) end)\010\009\009\009else\010\009\009\009\009check=true\010\009\009\009\009break\010\009\009\009end\010\009\009else\010\009\009\009check=true\010\009\009\009break\010\009\009end\010\009\009wait(firerate)\010\009\009check=true\010\009\009if not automatic then\010\009\009\009break\010\009\009end\010\009end\010end)\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=20899,class="Script",parent=20717,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{C204880B-0EB4-44FD-89B1-A8C0A10A9667}",["Source"]="wait(1)\010local NPC = script.Parent\010local Humanoid = NPC:WaitForChild(\034Humanoid\034)\010local AttackEnabled = true\010local TargetAlreadyHit = {}\010local TimerForAbility = 0\010\010local Torso = NPC:WaitForChild(\034Torso\034)\010local AttackAnim = Humanoid:LoadAnimation(NPC.AttackAnim)\010local DeathAnim = Humanoid:LoadAnimation(NPC.DeathAnim)\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),NPC)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==NPC and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == NPC.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function AOEDamage(pos,radius,damage)\010\009local NumberOfTargetInsideRadius = 0\010\009local temp = Workspace:GetChildren()\010\009for i = 1,#temp do\010\009\009if temp[i] ~= NPC then\010\009\009\009local ThisHumanoidIsAlreadyDamaged = false\010\009\009\009local human = temp[i]:findFirstChild(\034Humanoid\034)\010\009\009\009local torso = temp[i]:findFirstChild(\034Torso\034)\010\009\009\009local team = temp[i]:findFirstChild(\034TEAM\034)\010\009\009\009if Humanoid.Health ~= 0 and human ~= nil and torso ~= nil and human.Health ~= 0 and team and team.Value ~= NPC.TEAM.Value then\010\009\009\009\009--print(\034Found both Humanoid and Torso\034)\010\009\009\009\009for _, Humanoids in pairs(TargetAlreadyHit) do\010\009\009\009\009\009if Humanoids == human then ThisHumanoidIsAlreadyDamaged = true end\010\009\009\009\009\009--print(\034That Humanoid is already took a damage\034)\010\009\009\009\009end\010\009\009\009\009--print(\034Current: \034..(pos - torso.Position).magnitude)\010\009\009\009\009--print(\034Should: \034..radius + (torso.Size.magnitude/2.5))\010\009\009\009\009if (pos - torso.Position).magnitude < radius + (torso.Size.magnitude/2.5) and ThisHumanoidIsAlreadyDamaged == false then\010\009\009\009\009\009table.insert(TargetAlreadyHit,human)\010\009\009\009\009\009--print(\034Add Humanoid to table\034)\010\009\009\009\009\009NumberOfTargetInsideRadius = NumberOfTargetInsideRadius + 1\010\009\009\009\009\009NPC.FakeTorso.ClawHit:Play()\010\009\009\009\009\009human:TakeDamage(180)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return NumberOfTargetInsideRadius\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= NPC) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and team and team.Value ~= NPC.TEAM.Value then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009NPC.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009NPC.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009NPC.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function HumanoidChanged(Property)\010\009if Property == \034Sit\034 --[[and Humanoid.Sit == true]] then \010\009\009Humanoid.Sit = false \010\009end \010end \010\010Humanoid.Changed:connect(HumanoidChanged)\010\010NPC.Torso.Changed:connect(function(Value)\010\009if Value == \034Velocity\034 then\010\009\009NPC.Torso.Velocity = Vector3.new(0,0,0)\010\009end\010end)\010\010local CurrentHealth = Humanoid.Health\010local Defeated = false\010Humanoid.HealthChanged:connect(function()\010\009if Defeated then return end\010\009local Health = math.min(Humanoid.Health-CurrentHealth)\010\009if CurrentHealth-1 < -Health then\010\009\009Humanoid.Health = 0.1\010\009\009if not NPC:FindFirstChild(\034DEFEATED\034) then\010\009\009\009local DeathTag = Instance.new(\034ObjectValue\034,NPC)\010\009\009\009DeathTag.Name = \034DEFEATED\034\010\009\009end\010\009end\010\009CurrentHealth = Humanoid.Health\010end)\010\010TimerForAbility = 0.5 + (math.random()*3)\010\010while true do\010\009wait(0.1)\010\009TimerForAbility = TimerForAbility - 0.1\010\009local target = findNearestTorso(NPC.Torso.Position)\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009NPC.Attack.Value = false\010\009\009Humanoid.WalkSpeed = 75\010\009\009Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009\009if (NPC.Torso.Position - target.Position).magnitude < (30 + (target.Size.magnitude * 1.25)) then\010\009\009\009Humanoid.WalkSpeed = 0.1\010\009\009\009if AttackAnim then AttackAnim:Play() end\010\009\009\009wait(0.5)\010\009\009\009for i = 1,2 do\010\009\009\009\009if target then\010\009\009\009\009\009AOEDamage(NPC.Torso.Position + (NPC.Torso.CFrame.lookVector * 20),30,250)\010\009\009\009\009end\010\009\009\009\009wait(0.125)\010\009\009\009\009TargetAlreadyHit = {}\010\009\009\009end\010\009\009elseif TimerForAbility < 1 then\010\009\009\009local AbilityToChoose = math.random(1,2)\010\009\009\009if AbilityToChoose == 1 then --Laser-Eye\010\009\009\009\009Humanoid.WalkSpeed = 0\010\009\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009\009NPC.EyeLaser.Down.Value=true\010\009\009\009\009Spawn(function()\010\009\009\009\009\009while NPC.EyeLaser.Down.Value do\010\009\009\009\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009\009\009\009wait()\010\009\009\009\009\009end\010\009\009\009\009end)\010\009\009\009\009wait(1 + (math.random()*1))\010\009\009\009\009NPC.EyeLaser.Down.Value=false\010\009\009\009elseif AbilityToChoose == 2 then --Rocket launcher\010\009\009\009\009Humanoid.WalkSpeed = 0\010\009\009\009\009NPC.Attack.Value = true\010\009\009\009\009wait(2.5 + (math.random()*2.5))\010\009\009\009\009NPC.Attack.Value = false\010\009\009\009end\010\009\009\009TimerForAbility = 0.5 + (math.random()*3)\010\009\009else\010\009\009\009Humanoid.WalkSpeed = 50\010\009\009end\010\009else \010\009\009NPC.Range.Value = false \010\009\009NPC.Attack.Value = false \010\009end\010\009if NPC:FindFirstChild(\034DEFEATED\034) then --Special death animation\010\009\009NPC.FakeTorso.PreDeath:Play()\010\009\009NPC.PreDeath:Play()\010\009\009Humanoid.WalkSpeed = 0\010\009\009if DeathAnim then DeathAnim:Play() end\010\009\009wait(3)\010\009\009NPC.FakeTorso.PreDeath:Stop()\010\009\009Defeated = true\010\009\009NPC:BreakJoints()\010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21759,class="Script",parent=21741,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{6DA5CB58-FDDB-477A-A3B6-306EF7CEC684}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21777,class="Script",parent=21741,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="HealthRegenerationScript",["ScriptGuid"]="{736E942C-8FE0-44B0-A74F-11C7739C7C42}",["Source"]="-- Renegeration Script for the bot\013\010-- Renegerates about 1% of max hp per second until it reaches max health\013\010bot = script.Parent\013\010Humanoid = bot:FindFirstChild(\034Humanoid\034)\013\010\013\010local regen = false\013\010\013\010function regenerate() \013\010\009if regen then return end\013\010\009-- Lock this function until the regeneration to max health is complete by using a boolean toggle\013\010\009regen = true\013\010\009while Humanoid.Health < Humanoid.MaxHealth do\013\010\009\009local delta = wait(1)\013\010\009\009local health = Humanoid.Health\013\010\009\009if health > 0 and health < Humanoid.MaxHealth then \013\010\009\009\009-- This delta is for regenerating 1% of max hp per second instead of 1 hp per second\013\010\009\009\009delta = 0.01 * delta * Humanoid.MaxHealth\013\010\009\009\009health = health + delta\013\010\009\009\009Humanoid.Health = math.min(health, Humanoid.MaxHealth)\009\009\009\013\010\009\009end\013\010\009end\009\013\010\009-- release the lock, since the health is at max now, and if the character loses health again\013\010\009-- it needs to start regenerating \013\010\009regen = false\013\010end\009\013\010\013\010if Humanoid then \013\010\009-- Better than a while true do loop since it only fires when the health actually changes\013\010\009Humanoid.HealthChanged:connect(regenerate)\009\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21779,class="Script",parent=21741,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{44E0D29B-3211-4911-9308-373BEE1E2464}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxasset://sounds/uuhhh.wav\034)\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21781,class="Script",parent=21741,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ZombieScript",["ScriptGuid"]="{61F88C8D-44D3-44F4-A2BC-147EF3BFA98C}",["Source"]="--Made by Stickmasterluke\010\010--Zombie artificial stupidity script\010\010\010sp=script.Parent\010lastattack=0\010nextrandom=0\010nextsound=0\010nextjump=0\010chasing=false\010\010variance=4\010\010damage=10\010attackrange=4.5\010sightrange=999--60\010runspeed=16\010wonderspeed=8\010healthregen=false\010colors={\034Sand red\034,\034Dusty Rose\034,\034Medium blue\034,\034Sand blue\034,\034Lavender\034,\034Earth green\034,\034Brown\034,\034Medium stone grey\034,\034Brick yellow\034}\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function waitForChild(parent,childName)\010\009local child=parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child=parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010-- ANIMATION\010\010-- declarations\010\010local Torso=waitForChild(sp,\034Torso\034)\010local Head=waitForChild(sp,\034Head\034)\010local RightShoulder=waitForChild(Torso,\034Right Shoulder\034)\010local LeftShoulder=waitForChild(Torso,\034Left Shoulder\034)\010local RightHip=waitForChild(Torso,\034Right Hip\034)\010local LeftHip=waitForChild(Torso,\034Left Hip\034)\010local Neck=waitForChild(Torso,\034Neck\034)\010local Humanoid=waitForChild(sp,\034Humanoid\034)\010local BodyColors=waitForChild(sp,\034Body Colors\034)\010local pose=\034Standing\034\010local hitsound=waitForChild(Torso,\034HitSound\034)\010local Anim = Humanoid:LoadAnimation(sp.AttackAnim)\010\010--[[local sounds={\010\009waitForChild(Torso,\034GroanSound\034),\010\009waitForChild(Torso,\034RawrSound\034)\010}]]\010\010if healthregen then\010\009local regenscript=waitForChild(sp,\034HealthRegenerationScript\034)\010\009regenscript.Disabled=false\010end\010Humanoid.WalkSpeed=wonderspeed\010\010local toolAnim=\034None\034\010local toolAnimTime=0\010\010--[[BodyColors.HeadColor=BrickColor.new(\034Grime\034)\010local randomcolor1=colors[math.random(1,#colors)]\010BodyColors.TorsoColor=BrickColor.new(randomcolor1)\010BodyColors.LeftArmColor=BrickColor.new(randomcolor1)\010BodyColors.RightArmColor=BrickColor.new(randomcolor1)\010local randomcolor2=colors[math.random(1,#colors)]\010BodyColors.LeftLegColor=BrickColor.new(randomcolor2)\010BodyColors.RightLegColor=BrickColor.new(randomcolor2)]]\010\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009pose=\034Running\034\010\009else\010\009\009pose=\034Standing\034\010\009end\010end\010function onDied()\010\009pose=\034Dead\034\010end\010function onJumping()\010\009pose=\034Jumping\034\010end\010function onClimbing()\010\009pose=\034Climbing\034\010end\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010function onFreeFall()\010\009pose = \034FreeFall\034\010end\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010function onSeated()\010\009pose = \034Seated\034\010end\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function moveJump()\010\009RightShoulder.MaxVelocity = 0.5\010\009LeftShoulder.MaxVelocity = 0.5\010  RightShoulder.DesiredAngle=3.14\010\009LeftShoulder.DesiredAngle=-3.14\010\009RightHip.DesiredAngle=0\010\009LeftHip.DesiredAngle=0\010end\010\010function moveFreeFall()\010\009RightShoulder.MaxVelocity = 0.5\010\009LeftShoulder.MaxVelocity =0.5\010\009RightShoulder.DesiredAngle=3.14\010\009LeftShoulder.DesiredAngle=-3.14\010\009RightHip.DesiredAngle=0\010\009LeftHip.DesiredAngle=0\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder.DesiredAngle=3.14 /2\010\009LeftShoulder.DesiredAngle=-3.14 /2\010\009RightHip.DesiredAngle=3.14 /2\010\009LeftHip.DesiredAngle=-3.14 /2\010end\010\010function animate(time)\010\009local amplitude\010\009local frequency\010\009if (pose == \034Jumping\034) then\010\009\009moveJump()\010\009\009return\010\009end\010\009if (pose == \034FreeFall\034) then\010\009\009moveFreeFall()\010\009\009return\010\009end\010\009if (pose == \034Seated\034) then\010\009\009moveSit()\010\009\009return\010\009end\010\009local climbFudge = 0\010\009if (pose == \034Running\034) then\010\009\009RightShoulder.MaxVelocity = 0.15\010\009\009LeftShoulder.MaxVelocity = 0.15\010\009\009amplitude = 1\010\009\009frequency = 9\010\009elseif (pose == \034Climbing\034) then\010\009\009RightShoulder.MaxVelocity = 0.5 \010\009\009LeftShoulder.MaxVelocity = 0.5\010\009\009amplitude = 1\010\009\009frequency = 9\010\009\009climbFudge = 3.14\010\009else\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009end\010\009desiredAngle = amplitude * math.sin(time*frequency)\010\009if not chasing and frequency==9 then\010\009\009frequency=4\010\009end\010\009if chasing then\010\009\009--[[RightShoulder.DesiredAngle=math.pi/2\010\009\009LeftShoulder.DesiredAngle=-math.pi/2\010\009\009RightHip.DesiredAngle=-desiredAngle*2\010\009\009LeftHip.DesiredAngle=-desiredAngle*2]]\010\009else\010\009\009RightShoulder.DesiredAngle=desiredAngle + climbFudge\010\009\009LeftShoulder.DesiredAngle=desiredAngle - climbFudge\010\009\009RightHip.DesiredAngle=-desiredAngle\010\009\009LeftHip.DesiredAngle=-desiredAngle\010\009end\010end\010\010\010function attack(time,attackpos)\010\009if time-lastattack>=0.25 then\010\009\009local hit,pos=raycast(Torso.Position,(attackpos-Torso.Position).unit,attackrange)\010\009\009if hit and hit.Parent~=nil then\010\009\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local TEAM=hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h and TEAM and TEAM.Value~=sp.TEAM.Value then\010\009\009\009\009local creator=sp:FindFirstChild(\034creator\034)\010\009\009\009\009if creator then\010\009\009\009\009\009if creator.Value~=nil then\010\009\009\009\009\009\009if creator.Value~=game.Players:GetPlayerFromCharacter(h.Parent) then\010\009\009\009\009\009\009\009for i,oldtag in ipairs(h:GetChildren()) do\010\009\009\009\009\009\009\009\009if oldtag.Name==\034creator\034 then\010\009\009\009\009\009\009\009\009\009oldtag:remove()\010\009\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009creator:clone().Parent=h\010\009\009\009\009\009\009else\010\009\009\009\009\009\009\009return\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009\009if Anim then Anim:Play(nil,nil,1.5) end\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009\009hitsound.Volume=1\010\009\009\009\009hitsound.Pitch=.75+(math.random()*.5)\010\009\009\009\009hitsound:Play()\010\009\009\009\009--[[if RightShoulder and LeftShoulder then\010\009\009\009\009\009RightShoulder.CurrentAngle=0\010\009\009\009\009\009LeftShoulder.CurrentAngle=0\010\009\009\009\009end]]\010\009\009\009end\010\009\009end\010\009\009lastattack=time\010\009end\010end\010\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010\010\010function populatehumanoids(mdl)\010\009if mdl.ClassName==\034Humanoid\034 then\010\009\009if mdl.Parent:FindFirstChild(\034TEAM\034) and mdl.Parent:FindFirstChild(\034TEAM\034).Value~=sp.TEAM.Value then\010\009\009\009table.insert(humanoids,mdl)\010\009\009end\010\009end\010\009for i2,mdl2 in ipairs(mdl:GetChildren()) do\010\009\009populatehumanoids(mdl2)\010\009end\010end\010\010--[[function playsound(time)\010\009nextsound=time+5+(math.random()*5)\010\009local randomsound=sounds[math.random(1,#sounds)]\010\009randomsound.Volume=.5+(.5*math.random())\010\009randomsound.Pitch=.5+(.5*math.random())\010\009randomsound:Play()\010end]]\010\010while sp.Parent~=nil and Humanoid and Humanoid.Parent~=nil and Humanoid.Health>0 and Torso and Head and Torso~=nil and Torso.Parent~=nil do\010\009local _,time=wait(0.25)--wait(1/3)\010\009humanoids={}\010\009populatehumanoids(game.Workspace)\010\009closesttarget=nil\010\009closestdist=sightrange\010\009local creator=sp:FindFirstChild(\034creator\034)\010\009for i,h in ipairs(humanoids) do\010\009\009if h and h.Parent~=nil then\010\009\009\009if h.Health>0 and h.Parent~=sp then\010\009\009\009\009local plr=game.Players:GetPlayerFromCharacter(h.Parent)\010\009\009\009\009if creator==nil or plr==nil or creator.Value~=plr then\010\009\009\009\009\009local t=h.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009if t~=nil then\010\009\009\009\009\009\009local dist=(t.Position-Torso.Position).magnitude\010\009\009\009\009\009\009if dist<closestdist then\010\009\009\009\009\009\009\009closestdist=dist\010\009\009\009\009\009\009\009closesttarget=t\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009if closesttarget~=nil then\010\009\009if not chasing then\010\009\009\009--playsound(time)\010\009\009\009chasing=true\010\009\009\009Humanoid.WalkSpeed=runspeed\010\009\009end\010\009\009Humanoid:MoveTo(closesttarget.Position+(Vector3.new(1,1,1)*(variance*((math.random()*2)-1))),closesttarget)\010\009\009if math.random()<.5 then\010\009\009\009attack(time,closesttarget.Position)\010\009\009end\010\009else\010\009\009if chasing then\010\009\009\009chasing=false\010\009\009\009Humanoid.WalkSpeed=wonderspeed\010\009\009end\010\009\009if time>nextrandom then\010\009\009\009nextrandom=time+3+(math.random()*5)\010\009\009\009local randompos=Torso.Position+((Vector3.new(1,1,1)*math.random()-Vector3.new(.5,.5,.5))*40)\010\009\009\009Humanoid:MoveTo(randompos,game.Workspace.Terrain)\010\009\009end\010\009end\010\009if time>nextsound then\010\009\009--playsound(time)\010\009end\010\009if time>nextjump then\010\009\009nextjump=time+7+(math.random()*5)\010\009\009Humanoid.Jump=true\010\009end\010\009animate(time)\010end\010\010wait(4)\010sp:remove() --Rest In Pizza\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21783,class="Script",parent=21741,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{C74A23DC-FA68-4981-A4E7-F2B1530E64A5}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009game.workspace.Scripts.AllyNpcs.Value = game.workspace.Scripts.AllyNpcs.Value - 1\010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21788,class="Script",parent=21784,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Damage2",["ScriptGuid"]="{DD3501E7-92E9-4C06-90FD-BB5875B644AD}",["Source"]="robloxia = script.Parent\010wait(1.1)\010while true do\010if robloxia.Humanoid.Health < 625 then\010\009while true do\010\009\009exp = Instance.new(\034Explosion\034, workspace)\010\009\009exp.Position = robloxia.Torso.Position + Vector3.new(math.random(-10,10),math.random(-10,10),math.random(-10,10))\010\009\009exp.BlastRadius = 2.25\010\009\009exp.BlastPressure = 0\010\009\009wait(0.5)\010\009end\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21861,class="Script",parent=21784,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="CarrierScript",["ScriptGuid"]="{50701C76-548B-45B7-A00F-E1E2B207569F}",["Source"]="sp = script.Parent\010minion = game.Lighting.Allies.Guest:clone()\010\010--[[Setting]]--\010SpawnTime = 10\010NumberOfMinion = 1\010SpawnTimePerMinion = 0.25\010---------------\010\010sp.Minion.Value = minion\010--minion.Parent = game.Lighting\010--sp[\034Drone\034]:remove()\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010while true do\010\009wait(SpawnTime)\010\009if sp.Range.Value == true then\010\009\009sp.LDoor1.Transparency = 1\010\009\009sp.RDoor1.Transparency = 1\010\009\009wait(0.05)\010\009\009sp.LDoor2.Transparency = 1\010\009\009sp.RDoor2.Transparency = 1\010\009\009wait(0.05)\010\009\009sp.LDoor3.Transparency = 1\010\009\009sp.RDoor3.Transparency = 1\010\009\009wait(0.05)\010\009\009sp.LDoor4.Transparency = 1\010\009\009sp.RDoor4.Transparency = 1\010\009\009wait(0.05)\010\009\009sp.LDoor5.Transparency = 1\010\009\009sp.RDoor5.Transparency = 1\010\009\009for i = 1,NumberOfMinion do\010\009\009\009minion2 = minion:clone()\010\009\009\009minion2.Parent = Workspace\010\009\009\009minion2:MoveTo(sp.Torso.Position+Vector3.new(0,-15,0))\010\009\009\009minion2[\034Humanoid\034].Jump = true\010\009\009\009wait(SpawnTimePerMinion)\010\009\009end\010\009\009sp.LDoor5.Transparency = 0\010\009\009sp.RDoor5.Transparency = 0\010\009\009wait(0.05)\010\009\009sp.LDoor4.Transparency = 0\010\009\009sp.RDoor4.Transparency = 0\010\009\009wait(0.05)\010\009\009sp.LDoor3.Transparency = 0\010\009\009sp.RDoor3.Transparency = 0\010\009\009wait(0.05)\010\009\009sp.LDoor2.Transparency = 0\010\009\009sp.RDoor2.Transparency = 0\010\009\009wait(0.05)\010\009\009sp.LDoor1.Transparency = 0\010\009\009sp.RDoor1.Transparency = 0\010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21863,class="Script",parent=21784,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Damage",["ScriptGuid"]="{CB47C07A-EDF0-4549-9BEF-3D9E6F998A96}",["Source"]="robloxia = script.Parent\010smoke = robloxia.Torso:findFirstChild(\034Smoke\034)\010wait(1.1)\010while true do\010if robloxia.Humanoid.Health < 1250 then\010\009smoke.Enabled = true\010\009wait()\010\009script.Disabled = true\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21864,class="Script",parent=21784,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{ED9CB61A-B6D0-4BE9-9DE1-6462E165FEC0}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21865,class="Script",parent=21784,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{495675A7-F918-45AB-B018-777DDEA74479}",["Source"]="function waitForChild(parent, childName)\013\010\013\010 \009while true do\013\010\013\010 \009\009local child = parent:findFirstChild(childName)\013\010\013\010 \009\009if child then\013\010\013\010 \009\009\009return child\013\010\013\010 \009\009end\013\010\013\010 \009\009parent.ChildAdded:wait()\013\010\013\010 \009end\013\010\013\010 end\013\010\013\010 local Figure = script.Parent\013\013\010 local Torso = waitForChild(Figure, \034Torso\034)\013\013\010 local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\013\013\010 local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\013\013\010 local RightHip = waitForChild(Torso, \034Right Hip\034)\013\013\010 local LeftHip = waitForChild(Torso, \034Left Hip\034)\013\013\010 local Neck = waitForChild(Torso, \034Neck\034)\013\013\010 local Humanoid = waitForChild(Figure, \034Humanoid\034)\013\013\010 local pose = \034Standing\034\013\013\010 \013\013\010 local toolAnim = \034None\034\013\013\010 local toolAnimTime = 0\013\013\010 \013\013\010 local isSeated = false\013\013\010 \013\013\010 -- functions\013\013\010 \013\013\010 function onRunning(speed)\013\013\010 \009if isSeated then return end\013\013\010 \013\013\010 \009if speed>0 then\013\013\010 \009\009pose = \034Running\034\013\013\010 \009else\013\013\010 \009\009pose = \034Standing\034\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 function onDied()\013\013\010 \009pose = \034Dead\034\013\013\010 end\013\013\010 \013\013\010 function onJumping()\013\013\010 \009isSeated = false\013\013\010 \009pose = \034Jumping\034\013\013\010 end\013\013\010 \013\013\010 function onClimbing()\013\013\010 \009pose = \034Climbing\034\013\013\010 end\013\013\010 \013\013\010 function onGettingUp()\013\013\010 \009pose = \034GettingUp\034\013\013\010 end\013\013\010 \013\013\010 function onFreeFall()\013\013\010 \009pose = \034FreeFall\034\013\013\010 end\013\013\010 \013\013\010 function onFallingDown()\013\013\010 \009pose = \034FallingDown\034\013\013\010 end\013\013\010 \013\013\010 function onSeated()\013\013\010 \009isSeated = true\013\013\010 \009pose = \034Seated\034\013\013\010 \009print(\034Seated\034)\013\013\010 end\013\013\010 \013\013\010 function moveJump()\013\013\010 \009RightShoulder.MaxVelocity = 0.5\013\013\010 \009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009RightShoulder.DesiredAngle = 3.14\013\013\010 \009LeftShoulder.DesiredAngle = -3.14\013\013\010 \009RightHip.DesiredAngle = 0\013\013\010 \009LeftHip.DesiredAngle = 0\013\013\010 end\013\013\010 \013\013\010-- same as jump for now\013\013\010function moveFreeFall()\013\013\010 \009RightShoulder.MaxVelocity = 0.5\013\013\010 \009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009RightShoulder.DesiredAngle = 3.14\013\013\010 \009LeftShoulder.DesiredAngle = -3.14\013\013\010 \009RightHip.DesiredAngle = 0\013\013\010 \009LeftHip.DesiredAngle = 0\013\013\010 end\013\013\010 \013\013\010 function moveSit()\013\013\010 \009print(\034Move Sit\034)\013\013\010 \009RightShoulder.MaxVelocity = 0.15\013\013\010 \009LeftShoulder.MaxVelocity = 0.15\013\013\010 \009RightShoulder.DesiredAngle = 3.14 /2\013\013\010 \009LeftShoulder.DesiredAngle = -3.14 /2\013\013\010 \009RightHip.DesiredAngle = 3.14 /2\013\013\010 \009LeftHip.DesiredAngle = -3.14 /2\013\013\010 end\013\013\010 \013\013\010 function getTool()\013\013\010 \009\013\013\010 \009kidTable = Figure:children()\013\013\010 \009if (kidTable ~= nil) then\013\013\010 \009\009numKids = #kidTable\013\013\010 \009\009for i=1,numKids do\013\013\010 \009\009\009if (kidTable[i].className == \034Tool\034) then return kidTable[i] end\013\013\010 \009\009end\013\013\010 \009end\013\013\010 \009\013\013\010 \009return nil\013\013\010 end\013\013\010 \013\013\010 function getToolAnim(tool)\013\013\010 \013\013\010 \009c = tool:children()\013\013\010 \009for i=1,#c do\013\013\010 \009\009if (c[i].Name == \034toolanim\034 and c[i].className == \034StringValue\034) then\013\013\010 \009\009\009return c[i]\013\013\010 \009\009end\013\013\010 \009end\013\013\010 \009return nil\013\013\010 end\013\013\010 \013\013\010 function animateTool()\013\013\010 \009\013\013\010 \009if (toolAnim == \034None\034) then\013\013\010 \009\009RightShoulder.DesiredAngle = 1.57\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (toolAnim == \034Slash\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5\013\013\010 \009\009RightShoulder.DesiredAngle = 0\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (toolAnim == \034Lunge\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5\013\013\010 \009\009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009\009RightHip.MaxVelocity = 0.5\013\013\010 \009\009LeftHip.MaxVelocity = 0.5\013\013\010 \009\009RightShoulder.DesiredAngle = 1.57\013\013\010 \009\009LeftShoulder.DesiredAngle = 1.0\013\013\010 \009\009RightHip.DesiredAngle = 1.57\013\013\010 \009\009LeftHip.DesiredAngle = 1.0\013\013\010 \009\009return\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 function move(time)\013\013\010 \009local amplitude\013\013\010 \009local frequency\013\013\010 \013\013\010 \009if (pose == \034Jumping\034) then\013\013\010 \009\009moveJump()\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (pose == \034FreeFall\034) then\013\013\010 \009\009moveFreeFall()\013\013\010 \009\009return\013\013\010 \009end\013\013\010  \013\013\010 \009if (pose == \034Seated\034) then\013\013\010 \009\009moveSit()\013\013\010 \009\009return\013\013\010 \009end\013\013\010  \013\013\010 \009local climbFudge = 0\013\013\010 \009\013\013\010 \009if (pose == \034Running\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.15\013\013\010 \009\009LeftShoulder.MaxVelocity = 0.15\013\013\010 \009\009amplitude = 1\013\013\010 \009\009frequency = 9\013\013\010 \009elseif (pose == \034Climbing\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5 \013\013\010 \009\009LeftShoulder.MaxVelocity = 0.5\013\013\010  \009\009amplitude = 1\013\013\010 \009\009frequency = 9\013\013\010 \009\009climbFudge = 3.14\013\013\010 \009else\013\013\010 \009\009amplitude = 0.1\013\013\010 \009\009frequency = 1\013\013\010 \009end\013\013\010 \013\013\010 \009desiredAngle = amplitude * math.sin(time*frequency)\013\013\010 \013\013\010 \009RightShoulder.DesiredAngle = desiredAngle + climbFudge\013\013\010 \009LeftShoulder.DesiredAngle = desiredAngle - climbFudge\013\013\010 \009RightHip.DesiredAngle = -desiredAngle\013\013\010 \009LeftHip.DesiredAngle = -desiredAngle\013\013\010 \013\013\010 \013\013\010 \009local tool = getTool()\013\013\010 \013\013\010 \009if tool ~= nil then\013\013\010 \009\013\013\010 \009\009animStringValueObject = getToolAnim(tool)\013\013\010 \013\013\010 \009\009if animStringValueObject ~= nil then\013\013\010 \009\009\009toolAnim = animStringValueObject.Value\013\013\010 \009\009\009-- message recieved, delete StringValue\013\013\010 \009\009\009animStringValueObject.Parent = nil\013\013\010 \009\009\009toolAnimTime = time + .3\013\013\010 \009\009end\013\013\010 \013\013\010 \009\009if time > toolAnimTime then\013\013\010 \009\009\009toolAnimTime = 0\013\013\010 \009\009\009toolAnim = \034None\034\013\013\010 \009\009end\013\013\010 \013\013\010 \009\009animateTool()\013\013\010 \013\013\010 \009\009\013\013\010 \009else\013\013\010 \009\009toolAnim = \034None\034\013\013\010 \009\009toolAnimTime = 0\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 \013\013\010 -- connect events\013\013\010 \013\013\010 Humanoid.Died:connect(onDied)\013\013\010 Humanoid.Running:connect(onRunning)\013\013\010 Humanoid.Jumping:connect(onJumping)\013\013\010 Humanoid.Climbing:connect(onClimbing)\013\013\010 Humanoid.GettingUp:connect(onGettingUp)\013\013\010 Humanoid.FreeFalling:connect(onFreeFall)\013\013\010 Humanoid.FallingDown:connect(onFallingDown)\013\013\010 Humanoid.Seated:connect(onSeated)\013\013\010 \013\013\010 -- main program\013\013\010 \013\013\010 local nextTime = 0\013\013\010 local runService = game:service(\034RunService\034);\013\013\010 \013\013\010 while Figure.Parent~=nil do\013\013\010 \009time = runService.Stepped:wait()\013\013\010 \009if time > nextTime then\013\013\010 \009\009move(time)\013\013\010 \009\009nextTime = time + 0.1\013\013\010 \009end\013\013\010 end\013\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21867,class="Script",parent=21784,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{A1F6D6FF-538E-46BF-9C4D-79B4C72CE773}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009\009if dist < 50 then \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 0\010\009\009\009\009script.Parent.Attack.Value = true \010\009\009\009else \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 5\010\009\009\009\009script.Parent.Attack.Value = false \010\009\009\009end \010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = math.random(0,0)\010\009\009ry = math.random(0,0)\010\009\009rz = math.random(0,0)\010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21868,class="Script",parent=21784,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{DF6B9D43-DA39-4CFE-B069-606836B44038}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009game.Debris:AddItem(script.Parent,30)\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009game.workspace.Scripts.AllyBosses.Value = game.workspace.Scripts.AllyBosses.Value - 1\010\009wait(5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21869,class="Script",parent=21784,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="FF",["ScriptGuid"]="{1036E5B6-42F0-4D8C-9800-59D99EFA31BB}",["Source"]="ff = Instance.new(\034ForceField\034)\010ff.Parent = script.Parent\010wait(1)\010ff:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21871,class="Script",parent=21870,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="health",["ScriptGuid"]="{CDE7EFD6-B9F6-4A35-A17F-147D3EB25134}",["Source"]="wait(1)\013\010script.Parent.Health = script.Parent.MaxHealth\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21873,class="Script",parent=21784,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{117D5781-04A6-408C-89E6-B0C3B34C5BE4}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Torso.Death:Play()\010\009e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-50,50),math.random(0,100),math.random(-50,50))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\009\009for i = 1,10 do\010\009\009local minion = game.Lighting[\034Noob\034]:clone()\010\009\009minion.Parent = Workspace\010\009\009minion:MoveTo(script.Parent.Torso.Position + Vector3.new(math.random(-15,15),0,math.random(-15,15)))\010\009\009minion[\034Humanoid\034].Jump = true\010\009end\010\010\009wait(3)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21878,class="Script",parent=21877,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{C367CD3C-9073-4E49-88EF-E97B38E585C8}",["Source"]="human = script.Parent.Parent.Parent.Parent[\034Humanoid\034]\013\010\013\010while true do\013\010\009script.Parent.Text = \034Floating Fortress [\034 .. human.Health / human.MaxHealth * 100 .. \034%]\034\013\010\009wait()\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21882,class="Script",parent=21879,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{663F2ED7-236D-4C0C-A1CD-ACC9186217BF}",["Source"]="wait()\010zombieParent = false\010\010while zombieParent == false do\010\010\009wait()\010\009if script.Parent.Name == \034Turret\034 or script.Parent.Name == \034Giant Noob\034 then\010\009\009zombieParent = true\010\009end\010\010end\010\010local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009\009if dist < 75 then \010\009\009\009\009script.Parent.Attack.Value = true \010\009\009\009elseif dist > 75 then\010\009\009\009\009script.Parent.Attack.Value = false \010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010db = false \010function Hit(hit)\010\009if db == false then \010\009\009kk = script.Parent:FindFirstChild(\034ClassicPartiron\034)\010\009\009if script.Parent.Name == \034Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Zombie\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(50)\010\009\009\009\009db = true \010\009\009\009\009wait(0.5)\010\009\009\009\009db = false \010\009\009\009end\010\009\009elseif script.Parent.Name == \034Giant Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(100)\010\009\009\009\009db = true \010\009\009\009\009wait(0.25)\010\009\009\009\009db = false \010\009\009\009end\010\009\009elseif kk ~= nil and script.Parent.Name == \034Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(300)\010\009\009\009\009db = true \010\009\009\009\009wait(1)\010\009\009\009\009db = false \010\009\009\009end\010\009\009end  \010\009end \010end\010\010function Sit()\010\009if script.Parent.Invulnerable.Sit == true then\010\009\009wait(1) \010\009\009script.Parent.Invulnerable.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Invulnerable.Changed:connect(Sit)\010\010for i,p in pairs(script.Parent:GetChildren()) do \010\009if p:IsA(\034Part\034) then \010\009\009p.Touched:connect(Hit)\010\009end\010end \010\010while true do\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = math.random(0,0)\010\009\009ry = math.random(0,0)\010\009\009rz = math.random(0,0)\010\009\009script.Parent.Invulnerable:MoveTo(target.Position + Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009chancetorotate = math.random(0,3)\010\009\009if chancetorotate == 3 then script.Parent.Invulnerable:MoveTo(script.Parent.Torso.Position + Vector3.new(math.random(-10,10),0,math.random(-10,10)), script.Parent.Parent.Torso) end\010\009\009wait(1)\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
