T[#T+1]={id=21901,class="Script",parent=21895,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="RayGun",["ScriptGuid"]="{2D5BA28A-F2CE-49C7-A2DC-70687823FC75}",["Source"]="local Tool = script.Parent;\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010enabled = true\010\010--local spark = Instance.new(\034Sparkles\034)\010--spark.Color = Color3.new(0,1,0)\010\010function fire(v)\010\010\009local vCharacter = Tool.Parent\010\009local vPlayer = game.Players:playerFromCharacter(vCharacter)\010\010\009local missile = Instance.new(\034Part\034)\010\010\009\010\009--spark:Clone().Parent = missile\010\010\009local spawnPos = Tool.Parent.Target.Value.Position\010\009\010\010\009--spawnPos  = spawnPos + (v * 10)\010\010\009\010\009missile.Position = spawnPos\010\009missile.Size = Vector3.new(.2,.2,.2)\010\009--missile.Velocity = v * 100\010\009missile.BrickColor = BrickColor.new(\034Really blue\034)\010\009missile.Shape = 0\010\009missile.BottomSurface = 0\010\009missile.TopSurface = 0\010\009missile.Name = \034Spark\034\010\009missile.Reflectance = 0\010\009missile.Elasticity = 1\010\009missile.Anchored = true\010\009missile.CanCollide = false\010\009Tool.Mesh:clone().Parent = missile\010\010\010\009local force = Instance.new(\034BodyForce\034)\010\009force.force = Vector3.new(0,99,0)\010\009force.Parent = missile\010\010\009local creator_tag = Instance.new(\034ObjectValue\034)\010\009creator_tag.Value = vPlayer\010\009creator_tag.Name = \034creator\034\010\009creator_tag.Parent = missile\010\009\010\009local new_script = script.Parent.LaserBlast:clone()\010\009new_script.Disabled = false\010\009new_script.Parent = missile\010\009\010\009local target = Instance.new(\034ObjectValue\034)\010\009target.Name = \034Target\034\010\009target.Value = Tool.Parent.Target.Value.Parent\010\009target.Parent = missile\010\009\010\010\009Hit = missile.CFrame\010\009local Projectile = Instance.new(\034Part\034) \010\009Projectile.Name = \034Trail\034 \010\009local Place0 = Tool[\034Handle\034].CFrame \010\009Projectile.formFactor = 0 \010\009Projectile.Size = Vector3.new(1,1,(Place0.p - Hit.p).magnitude) \010\009Projectile.CFrame = CFrame.new((Place0.p + Hit.p)/2,Place0.p) \010\009Projectile.Parent = Workspace\010\009Projectile.BrickColor = missile.BrickColor\010\009Projectile.Anchored = true \010\009Projectile.CanCollide = false\010\009\010\009local new_script2 = script.Parent.ProjectileTimeLife:clone()\010\009new_script2.Disabled = false\010\009new_script2.Parent = Projectile\010\010\009me2 = Instance.new(\034BlockMesh\034)\010\009me2.Scale = Vector3.new(0.25,0.25,1)\010\009me2.Parent = Projectile\010\010\009--Tool.Handle.GruntSound:Clone().Parent = missile\010\010\009missile.Parent = Workspace\010--\009wait(.15)\010\009--PewPew:Stop()\010end\010\010\010\010function gunUp()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.5)\010end\010\010function gunOut()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.75)\010end\010\010function isTurbo(character)\010\009return character:FindFirstChild(\034BoltHelm\034) ~= nil\010end\010\010\010function onActivated()\010\009if not enabled  then\010\009\009return\010\009end\010\010\009enabled = false\010\010\010\009local character = Tool.Parent;\010\009local humanoid = character.Invulnerable\010\009if humanoid == nil then\010\009\009print(\034Humanoid not found\034)\010\009\009return \010\009end\010\010\009local targetPos = Tool.Parent.Target.Value.Position\010\009local lookAt = (targetPos - character.Head.Position).unit\010\010\009local reload = .05\010\009--if (isTurbo(character)) then\010\009--\009reload = .25\010\009--\009print(\034turbo\034)\010\009--end\010\010\009\010\009local PewPew = Tool.Handle:FindFirstChild(\034PewPew\034)\010\010\009if (PewPew == nil) then\010\009\009PewPew = Instance.new(\034Sound\034)\010\009\009PewPew.Name = \034PewPew\034\010\009\009PewPew.SoundId = \034http://www.roblox.com/asset/?id=92651381\034\010\009\009PewPew.Parent = Tool.Handle\010\009\009PewPew.Volume = 1\010\009\009--PewPew.Pitch = 1.2\010\009end\010\009\010\009--PewPew:Play()\010\009for i =1,3 do\010\010\009\009local spark = Instance.new(\034Fire\034)\010\009\009spark.Color = Color3.new(0,0,1)\010\009\009spark.SecondaryColor = Color3.new(0,0,1)\010\009\009spark.Size = 7.5\010\009\009spark.Heat = 0\010\009\009spark.Parent = Tool.Handle\010\010\009--gunUp()\010\009\009fire(lookAt,humanoid)\010\009\009PewPew:Play()\010\009\009wait(0.25)\010\010\009\009spark:remove()\010\009end\010\009--wait(reload)\010\009--gunOut()\010\009--wait(reload)\010\010\009wait(1.25)\010\010\009enabled = true\010\010end\010\010function onEquipped()\010\009--Tool.Handle.EquipSound:play()\010end\010\010Tool.Activated:connect(onActivated)\010Tool.Equipped:connect(onEquipped)\010\010while true do\010if Tool.Parent.Attack.Value == true then\010onActivated()\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=21902,class="Script",parent=21895,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Welding",["ScriptGuid"]="{4FDFA2FC-E4CF-43A2-86AB-0BECA8BF8795}",["Source"]="function Weld(x,y)\013\010\009local W = Instance.new(\034Weld\034)\013\010\009W.Part0 = x\013\010\009W.Part1 = y\013\010\009local CJ = CFrame.new(x.Position)\013\010\009local C0 = x.CFrame:inverse()*CJ\013\010\009local C1 = y.CFrame:inverse()*CJ\013\010\009W.C0 = C0\013\010\009W.C1 = C1\013\010\009W.Parent = x\013\010end\013\010\013\010function Get(A)\013\010\009if A.className == \034Part\034 then\013\010\009\009Weld(script.Parent.Handle, A)\013\010\009\009A.Anchored = false\013\010\009else\013\010\009\009local C = A:GetChildren()\013\010\009\009for i=1, #C do\013\010\009\009Get(C[i])\013\010\009\009end\013\010\009end\013\010end\013\010\013\010function Finale()\013\010\009Get(script.Parent)\013\010end\013\010\013\010script.Parent.Equipped:connect(Finale)\013\010script.Parent.Unequipped:connect(Finale)\013\010Finale()",["SourceAssetId"]=-1,["Tags"]=""}}
