tChild(\034creator\034)\010\009\009if tag ~= nil then\010\009\009\009tag.Parent = nil\010\009\009end\010\009end\010end\010\010--connection = ball.Touched:connect(onTouched)\010\010for i = 1,5 do\010\009ball.Transparency = ball.Transparency + 0.2\010\009ball.Mesh.Scale = ball.Mesh.Scale + Vector3.new(0.5,0.5,0.5)\010\009wait(0.1)\010end\010\010--ball.SparkSound.Looped = false\010--ball.SparkSound:Stop()\010ball.Parent = nil",["SourceAssetId"]=-1,["Tags"]=""}}
