T[#T+1]={id=22407,class="Script",parent=22406,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{4952DC29-08AD-4B61-880F-9746A34A0909}",["Source"]="while true do\010\009if script.Parent.Parent.Velocity.magnitude > 7.5 then\010\009\009script.Parent.Enabled = true\010\009else\010\009\009script.Parent.Enabled = false\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22419,class="Script",parent=22399,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="AIUseFPSMode",["ScriptGuid"]="{D11A130C-EC78-48A9-9AD6-834EBCE4DAA3}",["Source"]="gyro = Instance.new(\034BodyGyro\034)\010gyro.Parent = script.Parent:findFirstChild(\034Torso\034)\010gyro.P = 7500\010gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\010while true do\010\009vCharacter = script.Parent\010\009if vCharacter ~= nil then \010\009\009gyro.Parent = script.Parent.Torso\010\009\009local tp\010\009\009if (vCharacter.Target.Value and vCharacter.Range.Value) then\010\009\009\009tp = vCharacter.Target.Value.Position\010\009\009else\010\009\009\009tp = vCharacter.Humanoid.WalkToPoint\010\009\009end\010\009\009tp = Vector3.new(tp.X,script.Parent.Torso.Position.Y,tp.Z) \010\009\009local dir = (tp - script.Parent.Torso.Position).unit\010\009\009local spawnPos = script.Parent.Torso.Position\010\009\009local pos = spawnPos + (dir * 1)\010\009\009gyro.cframe = CFrame.new(pos,  pos + dir)\010\009elseif not vCharacter.Attack.Value then\010\009\009gyro.Parent = nil\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22429,class="Script",parent=22399,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Weld",["ScriptGuid"]="{6E6B7E0A-6CB9-4EC3-9D3A-66C43050D02F}",["Source"]="local Weld = Instance.new(\034Weld\034,script.Parent.Torso)\010Weld.Name = \034BallWeld\034\010Weld.Part0 = script.Parent.Torso\010Weld.Part1 = script.Parent.FakeTorso\010Weld.C0 = CFrame.new(0, 2, 0)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22430,class="Script",parent=22399,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{618DF41D-8EDB-4848-901D-29D55E3501C7}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Sit = false \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(0.1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 125 and\010\009\009\009 (target.Position - script.Parent.Torso.Position).magnitude > 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.1\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude < 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = -12.5\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 125 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 12.5\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22431,class="Script",parent=22399,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{C87A9B23-B2DB-4EE2-9B31-29E6C9725198}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Torso.Death:Play()\010\009e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-25,25),math.random(25,50),math.random(-25,25))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\010\009wait(3)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22434,class="Script",parent=22433,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="health",["ScriptGuid"]="{9CFEDC73-403B-4A31-AE7C-4077E2157A8F}",["Source"]="wait(1)\013\010script.Parent.Health = script.Parent.MaxHealth\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22435,class="Script",parent=22399,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{A3088370-11DD-4E52-8A4C-E574F1D2BD04}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009wait(5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22437,class="Script",parent=22399,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{382003FC-F0AF-41C1-ADFD-37ABD8993746}",["Source"]="-- util\013\010\013\010function waitForChild(parent, childName)\013\010\009local child = parent:findFirstChild(childName)\013\010\009if child then return child end\013\010\009while true do\013\010\009\009child = parent.ChildAdded:wait()\013\010\009\009if child.Name==childName then return child end\013\010\009end\013\010end\013\010\013\010function newSound(id)\013\010\009local sound = Instance.new(\034Sound\034)\013\010\009sound.SoundId = id\013\010\009sound.archivable = false\013\010\009sound.Parent = script.Parent.Head\013\010\009return sound\013\010end\013\010\013\010-- declarations\013\010\013\010local sDied = newSound(\034http://www.roblox.com/asset/?id=49059793\034)\013\010--sDied.Pitch = 0.5\013\010sDied.Volume = 1\013\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\013\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\013\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\013\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\013\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\013\010sRunning.Looped = true\013\010\013\010local Figure = script.Parent\013\010local Head = waitForChild(Figure, \034Head\034)\013\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\013\010\013\010-- functions\013\010\013\010function onDied()\013\010\009sDied:Play()\013\010end\013\010\013\010function onState(state, sound)\013\010\009if state then\013\010\009\009sound:Play()\013\010\009else\013\010\009\009sound:Pause()\013\010\009end\013\010end\013\010\013\010function onRunning(speed)\013\010\009if speed>0 then\013\010\009\009sRunning:Play()\013\010\009else\013\010\009\009sRunning:Pause()\013\010\009end\013\010end\013\010\013\010-- connect up\013\010\013\010Humanoid.Died:connect(onDied)\013\010Humanoid.Running:connect(onRunning)\013\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\013\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\013\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\013\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22474,class="Script",parent=22473,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{90CB6F4A-98AE-4BE6-8D77-BD8DA0D6F4C2}",["Source"]="while true do\010\009if script.Parent.Parent.Velocity.magnitude > 7.5 then\010\009\009script.Parent.Enabled = true\010\009else\010\009\009script.Parent.Enabled = false\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22523,class="Script",parent=22517,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="RocketScript",["ScriptGuid"]="{312A0208-3795-4A30-BEBD-98D1411690D1}",["Source"]="local Rocket = script.Parent\010local TEAM = Rocket:WaitForChild('TEAM')\010\010r = game:service(\034RunService\034)\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010shaft = script.Parent\010position = shaft.Position\010damage = shaft.Damage.Value\010spawnpos = shaft.Position\010\010--script.Parent.Explosion.PlayOnRemove = true -- play explosion sound when projectile removed from game\010\010function fly()\010\009direction = shaft.CFrame.lookVector \010\009position = position + direction*4\010\009error = position - shaft.Position\010\009shaft.Velocity = 50*error\010end\010\010function blow(hit)\010\009connection:disconnect()\010\009local explosion = Instance.new(\034Explosion\034)\010\009explosion.Position = shaft.Position\010\009explosion.BlastRadius = 20\010\009explosion.BlastPressure = 0 \010\009shaft.Explosion:play()\010\009explosion.Hit:connect(function(part, distance) onPlayerBlownUp(part, distance) end)\010\009explosion.Parent = game.Workspace\010\009shaft.Transparency = 1\010\009wait(0.25)\010\009shaft:remove()\010end\010\010function onPlayerBlownUp(part, distance)\010\009if part.Name == \034Torso\034 then\010\009\009local humanoid = part.Parent:findFirstChild(\034Humanoid\034)\010\009\009if humanoid ~= nil and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then \010\009\009\009humanoid:TakeDamage(damage)\010\009\009end \010\009\009--tagHumanoid(humanoid, creator)\010\009end\010end\010\010function tagHumanoid(humanoid, creator)\010\009-- tag does not need to expire iff all explosions lethal\010\009\010\009if creator ~= nil then\010\009\009local new_tag = creator:clone()\010\009\009new_tag.Parent = humanoid\010\009\009\010\009end\010end\010\010function untagHumanoid(humanoid)\010\009if humanoid ~= nil then\010\009\009local tag = humanoid:findFirstChild(\034creator\034)\010\009\009if tag ~= nil then\010\009\009\010\009\009\009tag.Parent = nil\010\009\009end\010\009end\010end\010\010t, s = r.Stepped:wait()\010\010swoosh = script.Parent.Swoosh\010\010d = t + 10.0 - s\010connection = shaft.Touched:connect(blow)\010\010while (spawnpos - shaft.Position).magnitude < 950 do\010\009fly()\010\009t = r.Stepped:wait()\010end\010\010-- at max range\010script.Parent.Explosion.PlayOnRemove = true\010swoosh:stop()\010shaft:remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22524,class="Script",parent=22517,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Server Launcher",["ScriptGuid"]="{7551C4E1-3751-46CF-B3AA-41CBDD561A80}",["Source"]="local Rocket = Instance.new(\034Part\034)\010local Tool = script.Parent\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010Rocket.Locked = true\010Rocket.formFactor = \034Custom\034\010Rocket.BackSurface = 0\010Rocket.BottomSurface = 0\010Rocket.FrontSurface = 0\010Rocket.LeftSurface = 0\010Rocket.RightSurface = 0\010Rocket.TopSurface = 0\010Rocket.Size = Vector3.new(0.5,0.5,10)\010Rocket.BrickColor = BrickColor.new(\034Bright yellow\034)\010Rocket.CanCollide = false\010\010Tool.RocketScript:clone().Parent = Rocket\010Tool.Explosion:clone().Parent = Rocket\010Tool.Swoosh:clone().Parent = Rocket\010Tool.Parent.TEAM:Clone().Parent = Rocket\010\010\010function fire(vTarget)\010\010\009local vCharacter = Tool.Parent;\010\009\010\009local vHandle = Tool:findFirstChild(\034Handle\034)\010\009if vHandle == nil then\010\009\009print(\034Handle not found\034)\010\009\009return \010\009end\010\010\009local dir = vTarget - vHandle.Position\010\010\009dir = computeDirection(dir)\010\010\009local missile = Rocket:clone()\010\010\009local pos = vHandle.Position + (dir*10) --15\010\009\010\009--missile.Position = pos\010\009missile.CFrame = CFrame.new(pos,  pos + dir)\010\010\009local creator_tag = Instance.new(\034ObjectValue\034)\010\010\009local vPlayer = game.Players:playerFromCharacter(vCharacter)\010\010\009if vPlayer == nil then\010\009\009print(\034Player not found\034)\010\009else\010\009\009if (vPlayer.Neutral == false) then -- nice touch\010\009\009\009missile.BrickColor = vPlayer.TeamColor\010\009\009end\010\009end\010\010\009creator_tag.Value =vPlayer\010\009creator_tag.Name = \034creator\034\010\009creator_tag.Parent = missile\010\010\009damage = Instance.new(\034NumberValue\034,missile)\010\009damage.Name = \034Damage\034\010\009damage.Value = 250\010\009\010\009missile.RocketScript.Disabled = false\010\010\009missile.Parent = game.Workspace\010end\010\010function computeDirection(vec)\010\009local lenSquared = vec.magnitude * vec.magnitude\010\009local invSqrt = 1 / math.sqrt(lenSquared)\010\009return Vector3.new(vec.x * invSqrt, vec.y * invSqrt, vec.z * invSqrt)\010end\010\010Tool.Enabled = true\010function onActivated()\010\009if not Tool.Enabled then\010\009\009return\010\009end\010\010\009Tool.Enabled = false\010\010\009local character = Tool.Parent;\010\009local humanoid = character.Humanoid\010\009if humanoid == nil then\010\009\009print(\034Humanoid not found\034)\010\009\009return \010\009end\010\010\009local targetPos = script.Parent.Parent.Target.Value.Position\010\010\009fire(targetPos)\010\010\009Tool.Handle.Swoosh:play()\010\009wait(5)\010\010\009Tool.Enabled = true\010end\010\010while true do \010wait(0.0)\010\009if script.Parent.Parent.Attack.Value == true then \010\009\009onActivated()\010\009end \010end \010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22525,class="Script",parent=22399,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{94E04D87-09DD-4800-AB24-71764B577104}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009game.workspace.Scripts.AllyNpcs.Value = game.workspace.Scripts.AllyNpcs.Value - 1\010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22548,class="Script",parent=22547,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{BAF12D75-7D71-467B-BBF6-2F94C18E6B30}",["Source"]="human = script.Parent.Parent.Parent.Parent[\034Humanoid\034]\013\010\013\010while true do\013\010\009script.Parent.Text = \034Floating Fortress [\034 .. human.Health / human.MaxHealth * 100 .. \034%]\034\013\010\009wait()\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22557,class="Script",parent=22526,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{15D79EF6-661B-448B-9ACD-A7CB6045208B}",["Source"]="function waitForChild(parent, childName)\013\010\013\010 \009while true do\013\010\013\010 \009\009local child = parent:findFirstChild(childName)\013\010\013\010 \009\009if child then\013\010\013\010 \009\009\009return child\013\010\013\010 \009\009end\013\010\013\010 \009\009parent.ChildAdded:wait()\013\010\013\010 \009end\013\010\013\010 end\013\010\013\010 local Figure = script.Parent\013\013\010 local Torso = waitForChild(Figure, \034Torso\034)\013\013\010 local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\013\013\010 local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\013\013\010 local RightHip = waitForChild(Torso, \034Right Hip\034)\013\013\010 local LeftHip = waitForChild(Torso, \034Left Hip\034)\013\013\010 local Neck = waitForChild(Torso, \034Neck\034)\013\013\010 local Humanoid = waitForChild(Figure, \034Humanoid\034)\013\013\010 local pose = \034Standing\034\013\013\010 \013\013\010 local toolAnim = \034None\034\013\013\010 local toolAnimTime = 0\013\013\010 \013\013\010 local isSeated = false\013\013\010 \013\013\010 -- functions\013\013\010 \013\013\010 function onRunning(speed)\013\013\010 \009if isSeated then return end\013\013\010 \013\013\010 \009if speed>0 then\013\013\010 \009\009pose = \034Running\034\013\013\010 \009else\013\013\010 \009\009pose = \034Standing\034\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 function onDied()\013\013\010 \009pose = \034Dead\034\013\013\010 end\013\013\010 \013\013\010 function onJumping()\013\013\010 \009isSeated = false\013\013\010 \009pose = \034Jumping\034\013\013\010 end\013\013\010 \013\013\010 function onClimbing()\013\013\010 \009pose = \034Climbing\034\013\013\010 end\013\013\010 \013\013\010 function onGettingUp()\013\013\010 \009pose = \034GettingUp\034\013\013\010 end\013\013\010 \013\013\010 function onFreeFall()\013\013\010 \009pose = \034FreeFall\034\013\013\010 end\013\013\010 \013\013\010 function onFallingDown()\013\013\010 \009pose = \034FallingDown\034\013\013\010 end\013\013\010 \013\013\010 function onSeated()\013\013\010 \009isSeated = true\013\013\010 \009pose = \034Seated\034\013\013\010 \009print(\034Seated\034)\013\013\010 end\013\013\010 \013\013\010 function moveJump()\013\013\010 \009RightShoulder.MaxVelocity = 0.5\013\013\010 \009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009RightShoulder.DesiredAngle = 3.14\013\013\010 \009LeftShoulder.DesiredAngle = -3.14\013\013\010 \009RightHip.DesiredAngle = 0\013\013\010 \009LeftHip.DesiredAngle = 0\013\013\010 end\013\013\010 \013\013\010-- same as jump for now\013\013\010function moveFreeFall()\013\013\010 \009RightShoulder.MaxVelocity = 0.5\013\013\010 \009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009RightShoulder.DesiredAngle = 3.14\013\013\010 \009LeftShoulder.DesiredAngle = -3.14\013\013\010 \009RightHip.DesiredAngle = 0\013\013\010 \009LeftHip.DesiredAngle = 0\013\013\010 end\013\013\010 \013\013\010 function moveSit()\013\013\010 \009print(\034Move Sit\034)\013\013\010 \009RightShoulder.MaxVelocity = 0.15\013\013\010 \009LeftShoulder.MaxVelocity = 0.15\013\013\010 \009RightShoulder.DesiredAngle = 3.14 /2\013\013\010 \009LeftShoulder.DesiredAngle = -3.14 /2\013\013\010 \009RightHip.DesiredAngle = 3.14 /2\013\013\010 \009LeftHip.DesiredAngle = -3.14 /2\013\013\010 end\013\013\010 \013\013\010 function getTool()\013\013\010 \009\013\013\010 \009kidTable = Figure:children()\013\013\010 \009if (kidTable ~= nil) then\013\013\010 \009\009numKids = #kidTable\013\013\010 \009\009for i=1,numKids do\013\013\010 \009\009\009if (kidTable[i].className == \034Tool\034) then return kidTable[i] end\013\013\010 \009\009end\013\013\010 \009end\013\013\010 \009\013\013\010 \009return nil\013\013\010 end\013\013\010 \013\013\010 function getToolAnim(tool)\013\013\010 \013\013\010 \009c = tool:children()\013\013\010 \009for i=1,#c do\013\013\010 \009\009if (c[i].Name == \034toolanim\034 and c[i].className == \034StringValue\034) then\013\013\010 \009\009\009return c[i]\013\013\010 \009\009end\013\013\010 \009end\013\013\010 \009return nil\013\013\010 end\013\013\010 \013\013\010 function animateTool()\013\013\010 \009\013\013\010 \009if (toolAnim == \034None\034) then\013\013\010 \009\009RightShoulder.DesiredAngle = 1.57\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (toolAnim == \034Slash\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5\013\013\010 \009\009RightShoulder.DesiredAngle = 0\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (toolAnim == \034Lunge\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5\013\013\010 \009\009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009\009RightHip.MaxVelocity = 0.5\013\013\010 \009\009LeftHip.MaxVelocity = 0.5\013\013\010 \009\009RightShoulder.DesiredAngle = 1.57\013\013\010 \009\009LeftShoulder.DesiredAngle = 1.0\013\013\010 \009\009RightHip.DesiredAngle = 1.57\013\013\010 \009\009LeftHip.DesiredAngle = 1.0\013\013\010 \009\009return\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 function move(time)\013\013\010 \009local amplitude\013\013\010 \009local frequency\013\013\010 \013\013\010 \009if (pose == \034Jumping\034) then\013\013\010 \009\009moveJump()\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (pose == \034FreeFall\034) then\013\013\010 \009\009moveFreeFall()\013\013\010 \009\009return\013\013\010 \009end\013\013\010  \013\013\010 \009if (pose == \034Seated\034) then\013\013\010 \009\009moveSit()\013\013\010 \009\009return\013\013\010 \009end\013\013\010  \013\013\010 \009local climbFudge = 0\013\013\010 \009\013\013\010 \009if (pose == \034Running\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.15\013\013\010 \009\009LeftShoulder.MaxVelocity = 0.15\013\013\010 \009\009amplitude = 1\013\013\010 \009\009frequency = 9\013\013\010 \009elseif (pose == \034Climbing\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5 \013\013\010 \009\009LeftShoulder.MaxVelocity = 0.5\013\013\010  \009\009amplitude = 1\013\013\010 \009\009frequency = 9\013\013\010 \009\009climbFudge = 3.14\013\013\010 \009else\013\013\010 \009\009amplitude = 0.1\013\013\010 \009\009frequency = 1\013\013\010 \009end\013\013\010 \013\013\010 \009desiredAngle = amplitude * math.sin(time*frequency)\013\013\010 \013\013\010 \009RightShoulder.DesiredAngle = desiredAngle + climbFudge\013\013\010 \009LeftShoulder.DesiredAngle = desiredAngle - climbFudge\013\013\010 \009RightHip.DesiredAngle = -desiredAngle\013\013\010 \009LeftHip.DesiredAngle = -desiredAngle\013\013\010 \013\013\010 \013\013\010 \009local tool = getTool()\013\013\010 \013\013\010 \009if tool ~= nil then\013\013\010 \009\013\013\010 \009\009animStringValueObject = getToolAnim(tool)\013\013\010 \013\013\010 \009\009if animStringValueObject ~= nil then\013\013\010 \009\009\009toolAnim = animStringValueObject.Value\013\013\010 \009\009\009-- message recieved, delete StringValue\013\013\010 \009\009\009animStringValueObject.Parent = nil\013\013\010 \009\009\009toolAnimTime = time + .3\013\013\010 \009\009end\013\013\010 \013\013\010 \009\009if time > toolAnimTime then\013\013\010 \009\009\009toolAnimTime = 0\013\013\010 \009\009\009toolAnim = \034None\034\013\013\010 \009\009end\013\013\010 \013\013\010 \009\009animateTool()\013\013\010 \013\013\010 \009\009\013\013\010 \009else\013\013\010 \009\009toolAnim = \034None\034\013\013\010 \009\009toolAnimTime = 0\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 \013\013\010 -- connect events\013\013\010 \013\013\010 Humanoid.Died:connect(onDied)\013\013\010 Humanoid.Running:connect(onRunning)\013\013\010 Humanoid.Jumping:connect(onJumping)\013\013\010 Humanoid.Climbing:connect(onClimbing)\013\013\010 Humanoid.GettingUp:connect(onGettingUp)\013\013\010 Humanoid.FreeFalling:connect(onFreeFall)\013\013\010 Humanoid.FallingDown:connect(onFallingDown)\013\013\010 Humanoid.Seated:connect(onSeated)\013\013\010 \013\013\010 -- main program\013\013\010 \013\013\010 local nextTime = 0\013\013\010 local runService = game:service(\034RunService\034);\013\013\010 \013\013\010 while Figure.Parent~=nil do\013\013\010 \009time = runService.Stepped:wait()\013\013\010 \009if time > nextTime then\013\013\010 \009\009move(time)\013\013\010 \009\009nextTime = time + 0.1\013\013\010 \009end\013\013\010 end\013\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22559,class="Script",parent=22526,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{99FC06B2-EA4D-4586-8D3C-1592B18DBE92}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22560,class="Script",parent=22526,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{4E2B7AF5-5AC9-443B-AF8E-5893CF177CE7}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 999999999999999999999999999\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009\009if dist < 150 then \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 0\010\009\009\009\009script.Parent.Attack.Value = true \010\009\009\009else \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 30\010\009\009\009\009script.Parent.Attack.Value = false \010\009\009\009end \010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = math.random(0,0)\010\009\009ry = math.random(0,0)\010\009\009rz = math.random(0,0)\010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22561,class="Script",parent=22526,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Damage",["ScriptGuid"]="{8BBA1FEF-B5FF-49D3-A2AE-B3D67F693729}",["Source"]="robloxia = script.Parent\013\010smoke = robloxia.Torso:findFirstChild(\034Smoke\034)\013\010wait(1.1)\013\010while true do\013\010if robloxia.Humanoid.Health < 375 then\013\010\009smoke.Enabled = true\013\010\009wait()\013\010\009script.Disabled = true\013\010end\013\010wait()\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22562,class="Script",parent=22526,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Damage2",["ScriptGuid"]="{72CA5DD3-8BE2-4B8B-A5A0-425F16C1B8DF}",["Source"]="robloxia = script.Parent\013\010wait(1.1)\013\010while true do\013\010if robloxia.Humanoid.Health < 187.5 then\013\010\009while true do\013\010\009\009exp = Instance.new(\034Explosion\034, workspace)\013\010\009\009exp.Position = robloxia.Torso.Position + Vector3.new(math.random(-10,10),math.random(-10,10),math.random(-10,10))\013\010\009\009exp.BlastRadius = 2.25\013\010\009\009exp.BlastPressure = 0\013\010\009\009wait(0.5)\013\010\009end\013\010end\013\010wait()\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22563,class="Script",parent=22526,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{8F7121F5-53F8-4A31-BB17-7889C372E2BE}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009game.Debris:AddItem(script.Parent,30)\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009wait(5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22564,class="Script",parent=22526,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{8EFB6208-30A7-4310-8064-CC93C7AE4C8D}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Torso.Death:Play()\010\009e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-50,50),math.random(0,100),math.random(-50,50))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\009\009for i = 1,10 do\010\009\009local minion = game.Lighting[\034Noob\034]:clone()\010\009\009minion.Parent = Workspace\010\009\009minion:MoveTo(script.Parent.Torso.Position + Vector3.new(math.random(-15,15),0,math.random(-15,15)))\010\009\009minion[\034Humanoid\034].Jump = true\010\009end\010\010\009wait(3)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22565,class="Script",parent=22526,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="FF",["ScriptGuid"]="{F24E39FC-BDD9-4463-B503-57FF3391C573}",["Source"]="ff = Instance.new(\034ForceField\034)\010ff.Parent = script.Parent\010wait(1)\010ff:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22566,class="Script",parent=22526,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{6E5DBBF5-9C6A-490B-A9F4-FA6FAFCFAA76}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
