\009Projectile.formFactor = 0 \010\009Projectile.Size = Vector3.new(1,1,(Place0.p - Hit.p).magnitude) \010\009Projectile.CFrame = CFrame.new((Place0.p + Hit.p)/2,Place0.p) \010\009Projectile.Parent = Workspace\010\009Projectile.BrickColor = missile.BrickColor\010\009Projectile.Anchored = true \010\009Projectile.CanCollide = false\010\009\010\009local new_script2 = script.Parent.ProjectileTimeLife:clone()\010\009new_script2.Disabled = false\010\009new_script2.Parent = Projectile\010\010\009me2 = Instance.new(\034BlockMesh\034)\010\009me2.Scale = Vector3.new(.5,.5,1.4)\010\009me2.Parent = Projectile\010\010\009--Tool.Handle.GruntSound:Clone().Parent = missile\010\010\009missile.Parent = Workspace\010--\009wait(.15)\010\009--PewPew:Stop()\010end\010\010\010\010function gunUp()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.5)\010end\010\010function gunOut()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.75)\010end\010\010function isTurbo(character)\010\009return character:FindFirstChild(\034BoltHelm\034) ~= nil\010end\010\010\010function onActivated()\010\009if not enabled  then\010\009\009return\010\009end\010\010\009enabled = false\010\010\010\009local character = Tool.Parent;\010\009local humanoid = character.Humanoid\010\009if humanoid == nil then\010\009\009print(\034Humanoid not found\034)\010\009\009return \010\009end\010\010\009local targetPos = Tool.Parent.Target.Value.Position\010\009local lookAt = (targetPos - character.Head.Position).unit\010\010\009local reload = .05\010\009--if (isTurbo(character)) then\010\009--\009reload = .25\010\009--\009print(\034turbo\034)\010\009--end\010\010\009\010\009local PewPew = Tool.Handle:FindFirstChild(\034PewPew\034)\010\010\009if (PewPew == nil) then\010\009\009PewPew = Instance.new(\034Sound\034)\010\009\009PewPew.Name = \034PewPew\034\010\009\009PewPew.SoundId = \034http://www.roblox.com/asset/?id=1369158\034\010\009\009PewPew.Parent = Tool.Handle\010\009\009PewPew.Volume = 1\010\009\009--PewPew.Pitch = 1.2\010\009end\010\009\010\009PewPew:Play()\010\010\009\009local spark = Instance.new(\034Fire\034)\010\009\009spark.Color = Color3.new(1,1,0)\010\009\009spark.SecondaryColor = Color3.new(1,1,0)\010\009\009spark.Size = 2.5\010\009\009spark.Heat = 0\010\009\009spark.Parent = Tool.Handle\010\010\009--gunUp()\010\009fire(lookAt,humanoid)\010\009wait(reload)\010\009--gunOut()\010\009wait(reload)\010\010\009\009spark:remove()\010\010wait(50.0)\010\010\009enabled = true\010\010end\010\010function onEquipped()\010\009--Tool.Handle.EquipSound:play()\010end\010\010Tool.Activated:connect(onActivated)\010Tool.Equipped:connect(onEquipped)\010\010while true do\010if Tool.Parent.Attack.Value == true then\010onActivated()\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
