T[#T+1]={id=22789,class="Script",parent=22604,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{70B85560-092C-4EC2-BE56-E810FDA3BC6D}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Torso.Death:Play()\010\009e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-25,25),math.random(25,50),math.random(-25,25))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\010\009wait(3)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
