T[#T+1]={id=22791,class="Script",parent=22604,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{360335D3-E233-448D-8849-13C5DA9FF5AE}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22795,class="Script",parent=22604,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{DCA63C82-4A90-4691-99CD-F2B48FF0F9FF}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034http://www.roblox.com/asset/?id=165772825\034)\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034http://www.roblox.com/asset/?id=82229584\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
