_script.Disabled = false\010\009new_script.Parent = missile\010\009\010\009local target = Instance.new(\034ObjectValue\034)\010\009target.Name = \034Target\034\010\009target.Value = Tool.Parent.Target.Value.Parent\010\009target.Parent = missile\010\009\010\010\009Hit = missile.CFrame\010\009local Projectile = Instance.new(\034Part\034) \010\009Projectile.Name = \034Trail\034 \010\009local Place0 = Tool[\034Handle\034].CFrame \010\009Projectile.formFactor = 0 \010\009Projectile.Size = Vector3.new(1,1,(Place0.p - Hit.p).magnitude) \010\009Projectile.CFrame = CFrame.new((Place0.p + Hit.p)/2,Place0.p) \010\009Projectile.Parent = Workspace\010\009Projectile.BrickColor = missile.BrickColor\010\009Projectile.Anchored = true \010\009Projectile.CanCollide = false\010\009\010\009local new_script2 = script.Parent.ProjectileTimeLife:clone()\010\009new_script2.Disabled = false\010\009new_script2.Parent = Projectile\010\010\009me2 = Instance.new(\034BlockMesh\034)\010\009me2.Scale = Vector3.new(0.25,0.25,1)\010\009me2.Parent = Projectile\010\010\009--Tool.Handle.GruntSound:Clone().Parent = missile\010\010\009missile.Parent = Workspace\010--\009wait(.15)\010\009--PewPew:Stop()\010end\010\010\010\010function gunUp()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.5)\010end\010\010function gunOut()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.75)\010end\010\010function isTurbo(character)\010\009return character:FindFirstChild(\034BoltHelm\034) ~= nil\010end\010\010\010function onActivated()\010\009if not enabled  then\010\009\009return\010\009end\010\010\009enabled = false\010\010\010\009local character = Tool.Parent;\010\009local humanoid = character.Invulnerable\010\009if humanoid == nil then\010\009\009print(\034Humanoid not found\034)\010\009\009return \010\009end\010\010\009local targetPos = Tool.Parent.Target.Value.Position\010\009local lookAt = (targetPos - character.Head.Position).unit\010\010\009local reload = .05\010\009--if (isTurbo(character)) then\010\009--\009reload = .25\010\009--\009print(\034turbo\034)\010\009--end\010\010\009\010\009local PewPew = Tool.Handle:FindFirstChild(\034PewPew\034)\010\010\009if (PewPew == nil) then\010\009\009PewPew = Instance.new(\034Sound\034)\010\009\009PewPew.Name = \034PewPew\034\010\009\009PewPew.SoundId = \034http://www.roblox.com/asset/?id=92651381\034\010\009\009PewPew.Parent = Tool.Handle\010\009\009PewPew.Volume = 1\010\009\009--PewPew.Pitch = 1.2\010\009end\010\009\010\009--PewPew:Play()\010\009for i =1,3 do\010\010\009\009local spark = Instance.new(\034Fire\034)\010\009\009spark.Color = Color3.new(0,0,1)\010\009\009spark.SecondaryColor = Color3.new(0,0,1)\010\009\009spark.Size = 7.5\010\009\009spark.Heat = 0\010\009\009spark.Parent = Tool.Handle\010\010\009--gunUp()\010\009\009fire(lookAt,humanoid)\010\009\009PewPew:Play()\010\009\009wait(0.25)\010\010\009\009spark:remove()\010\009end\010\009--wait(reload)\010\009--gunOut()\010\009--wait(reload)\010\010\009wait(1.25)\010\010\009enabled = true\010\010end\010\010function onEquipped()\010\009--Tool.Handle.EquipSound:play()\010end\010\010Tool.Activated:connect(onActivated)\010Tool.Equipped:connect(onEquipped)\010\010while true do\010if Tool.Parent.Attack.Value == true then\010onActivated()\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=22984,class="Script",parent=22977,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Welding",["ScriptGuid"]="{6ADEDC94-C7DC-4FAC-92B1-25800FF77C6F}",["Source"]="function Weld(x,y)\013\010\009local W = Instance.new(\034Weld\034)\013\010\009W.Part0 = x\013\010\009W.Part1 = y\013\010\009local CJ = CFrame.new(x.Position)\013\010\009local C0 = x.CFrame:inverse()*CJ\013\010\009local C1 = y.CFrame:inverse()*CJ\013\010\009W.C0 = C0\013\010\009W.C1 = C1\013\010\009W.Parent = x\013\010end\013\010\013\010function Get(A)\013\010\009if A.className == \034Part\034 then\013\010\009\009Weld(script.Parent.Handle, A)\013\010\009\009A.Anchored = false\013\010\009else\013\010\009\009local C = A:GetChildren()\013\010\009\009for i=1, #C do\013\010\009\009Get(C[i])\013\010\009\009end\013\010\009end\013\010end\013\010\013\010function Finale()\013\010\009Get(script.Parent)\013\010end\013\010\013\010script.Parent.Equipped:connect(Finale)\013\010script.Parent.Unequipped:connect(Finale)\013\010Finale()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23022,class="Script",parent=22801,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{C9912700-4EC6-40BF-A698-5AFBD5AB8697}",["Source"]="function waitForChild(parent, childName)\013\010\013\010 \009while true do\013\010\013\010 \009\009local child = parent:findFirstChild(childName)\013\010\013\010 \009\009if child then\013\010\013\010 \009\009\009return child\013\010\013\010 \009\009end\013\010\013\010 \009\009parent.ChildAdded:wait()\013\010\013\010 \009end\013\010\013\010 end\013\010\013\010 local Figure = script.Parent\013\013\010 local Torso = waitForChild(Figure, \034Torso\034)\013\013\010 local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\013\013\010 local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\013\013\010 local RightHip = waitForChild(Torso, \034Right Hip\034)\013\013\010 local LeftHip = waitForChild(Torso, \034Left Hip\034)\013\013\010 local Neck = waitForChild(Torso, \034Neck\034)\013\013\010 local Humanoid = waitForChild(Figure, \034Humanoid\034)\013\013\010 local pose = \034Standing\034\013\013\010 \013\013\010 local toolAnim = \034None\034\013\013\010 local toolAnimTime = 0\013\013\010 \013\013\010 local isSeated = false\013\013\010 \013\013\010 -- functions\013\013\010 \013\013\010 function onRunning(speed)\013\013\010 \009if isSeated then return end\013\013\010 \013\013\010 \009if speed>0 then\013\013\010 \009\009pose = \034Running\034\013\013\010 \009else\013\013\010 \009\009pose = \034Standing\034\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 function onDied()\013\013\010 \009pose = \034Dead\034\013\013\010 end\013\013\010 \013\013\010 function onJumping()\013\013\010 \009isSeated = false\013\013\010 \009pose = \034Jumping\034\013\013\010 end\013\013\010 \013\013\010 function onClimbing()\013\013\010 \009pose = \034Climbing\034\013\013\010 end\013\013\010 \013\013\010 function onGettingUp()\013\013\010 \009pose = \034GettingUp\034\013\013\010 end\013\013\010 \013\013\010 function onFreeFall()\013\013\010 \009pose = \034FreeFall\034\013\013\010 end\013\013\010 \013\013\010 function onFallingDown()\013\013\010 \009pose = \034FallingDown\034\013\013\010 end\013\013\010 \013\013\010 function onSeated()\013\013\010 \009isSeated = true\013\013\010 \009pose = \034Seated\034\013\013\010 \009print(\034Seated\034)\013\013\010 end\013\013\010 \013\013\010 function moveJump()\013\013\010 \009RightShoulder.MaxVelocity = 0.5\013\013\010 \009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009RightShoulder.DesiredAngle = 3.14\013\013\010 \009LeftShoulder.DesiredAngle = -3.14\013\013\010 \009RightHip.DesiredAngle = 0\013\013\010 \009LeftHip.DesiredAngle = 0\013\013\010 end\013\013\010 \013\013\010-- same as jump for now\013\013\010function moveFreeFall()\013\013\010 \009RightShoulder.MaxVelocity = 0.5\013\013\010 \009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009RightShoulder.DesiredAngle = 3.14\013\013\010 \009LeftShoulder.DesiredAngle = -3.14\013\013\010 \009RightHip.DesiredAngle = 0\013\013\010 \009LeftHip.DesiredAngle = 0\013\013\010 end\013\013\010 \013\013\010 function moveSit()\013\013\010 \009print(\034Move Sit\034)\013\013\010 \009RightShoulder.MaxVelocity = 0.15\013\013\010 \009LeftShoulder.MaxVelocity = 0.15\013\013\010 \009RightShoulder.DesiredAngle = 3.14 /2\013\013\010 \009LeftShoulder.DesiredAngle = -3.14 /2\013\013\010 \009RightHip.DesiredAngle = 3.14 /2\013\013\010 \009LeftHip.DesiredAngle = -3.14 /2\013\013\010 end\013\013\010 \013\013\010 function getTool()\013\013\010 \009\013\013\010 \009kidTable = Figure:children()\013\013\010 \009if (kidTable ~= nil) then\013\013\010 \009\009numKids = #kidTable\013\013\010 \009\009for i=1,numKids do\013\013\010 \009\009\009if (kidTable[i].className == \034Tool\034) then return kidTable[i] end\013\013\010 \009\009end\013\013\010 \009end\013\013\010 \009\013\013\010 \009return nil\013\013\010 end\013\013\010 \013\013\010 function getToolAnim(tool)\013\013\010 \013\013\010 \009c = tool:children()\013\013\010 \009for i=1,#c do\013\013\010 \009\009if (c[i].Name == \034toolanim\034 and c[i].className == \034StringValue\034) then\013\013\010 \009\009\009return c[i]\013\013\010 \009\009end\013\013\010 \009end\013\013\010 \009return nil\013\013\010 end\013\013\010 \013\013\010 function animateTool()\013\013\010 \009\013\013\010 \009if (toolAnim == \034None\034) then\013\013\010 \009\009RightShoulder.DesiredAngle = 1.57\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (toolAnim == \034Slash\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5\013\013\010 \009\009RightShoulder.DesiredAngle = 0\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (toolAnim == \034Lunge\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5\013\013\010 \009\009LeftShoulder.MaxVelocity = 0.5\013\013\010 \009\009RightHip.MaxVelocity = 0.5\013\013\010 \009\009LeftHip.MaxVelocity = 0.5\013\013\010 \009\009RightShoulder.DesiredAngle = 1.57\013\013\010 \009\009LeftShoulder.DesiredAngle = 1.0\013\013\010 \009\009RightHip.DesiredAngle = 1.57\013\013\010 \009\009LeftHip.DesiredAngle = 1.0\013\013\010 \009\009return\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 function move(time)\013\013\010 \009local amplitude\013\013\010 \009local frequency\013\013\010 \013\013\010 \009if (pose == \034Jumping\034) then\013\013\010 \009\009moveJump()\013\013\010 \009\009return\013\013\010 \009end\013\013\010 \013\013\010 \009if (pose == \034FreeFall\034) then\013\013\010 \009\009moveFreeFall()\013\013\010 \009\009return\013\013\010 \009end\013\013\010  \013\013\010 \009if (pose == \034Seated\034) then\013\013\010 \009\009moveSit()\013\013\010 \009\009return\013\013\010 \009end\013\013\010  \013\013\010 \009local climbFudge = 0\013\013\010 \009\013\013\010 \009if (pose == \034Running\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.15\013\013\010 \009\009LeftShoulder.MaxVelocity = 0.15\013\013\010 \009\009amplitude = 1\013\013\010 \009\009frequency = 9\013\013\010 \009elseif (pose == \034Climbing\034) then\013\013\010 \009\009RightShoulder.MaxVelocity = 0.5 \013\013\010 \009\009LeftShoulder.MaxVelocity = 0.5\013\013\010  \009\009amplitude = 1\013\013\010 \009\009frequency = 9\013\013\010 \009\009climbFudge = 3.14\013\013\010 \009else\013\013\010 \009\009amplitude = 0.1\013\013\010 \009\009frequency = 1\013\013\010 \009end\013\013\010 \013\013\010 \009desiredAngle = amplitude * math.sin(time*frequency)\013\013\010 \013\013\010 \009RightShoulder.DesiredAngle = desiredAngle + climbFudge\013\013\010 \009LeftShoulder.DesiredAngle = desiredAngle - climbFudge\013\013\010 \009RightHip.DesiredAngle = -desiredAngle\013\013\010 \009LeftHip.DesiredAngle = -desiredAngle\013\013\010 \013\013\010 \013\013\010 \009local tool = getTool()\013\013\010 \013\013\010 \009if tool ~= nil then\013\013\010 \009\013\013\010 \009\009animStringValueObject = getToolAnim(tool)\013\013\010 \013\013\010 \009\009if animStringValueObject ~= nil then\013\013\010 \009\009\009toolAnim = animStringValueObject.Value\013\013\010 \009\009\009-- message recieved, delete StringValue\013\013\010 \009\009\009animStringValueObject.Parent = nil\013\013\010 \009\009\009toolAnimTime = time + .3\013\013\010 \009\009end\013\013\010 \013\013\010 \009\009if time > toolAnimTime then\013\013\010 \009\009\009toolAnimTime = 0\013\013\010 \009\009\009toolAnim = \034None\034\013\013\010 \009\009end\013\013\010 \013\013\010 \009\009animateTool()\013\013\010 \013\013\010 \009\009\013\013\010 \009else\013\013\010 \009\009toolAnim = \034None\034\013\013\010 \009\009toolAnimTime = 0\013\013\010 \009end\013\013\010 end\013\013\010 \013\013\010 \013\013\010 -- connect events\013\013\010 \013\013\010 Humanoid.Died:connect(onDied)\013\013\010 Humanoid.Running:connect(onRunning)\013\013\010 Humanoid.Jumping:connect(onJumping)\013\013\010 Humanoid.Climbing:connect(onClimbing)\013\013\010 Humanoid.GettingUp:connect(onGettingUp)\013\013\010 Humanoid.FreeFalling:connect(onFreeFall)\013\013\010 Humanoid.FallingDown:connect(onFallingDown)\013\013\010 Humanoid.Seated:connect(onSeated)\013\013\010 \013\013\010 -- main program\013\013\010 \013\013\010 local nextTime = 0\013\013\010 local runService = game:service(\034RunService\034);\013\013\010 \013\013\010 while Figure.Parent~=nil do\013\013\010 \009time = runService.Stepped:wait()\013\013\010 \009if time > nextTime then\013\013\010 \009\009move(time)\013\013\010 \009\009nextTime = time + 0.1\013\013\010 \009end\013\013\010 end\013\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23024,class="Script",parent=22801,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="CarrierScript",["ScriptGuid"]="{36ACBD8F-A403-4CB1-BB47-254FD12308D9}",["Source"]="sp = script.Parent\010minion = game.Lighting[\034Giant Noob\034]:clone()\010\010--[[Setting]]--\010SpawnTime = 10\010NumberOfMinion = 1\010SpawnTimePerMinion = 0.25\010---------------\010\010sp.Minion.Value = minion\010--minion.Parent = game.Lighting\010--sp[\034Drone\034]:remove()\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010while true do\010\009wait(SpawnTime)\010\009if sp.Range.Value == true then\010\009\009sp.LDoor1.Transparency = 1\010\009\009sp.RDoor1.Transparency = 1\010\009\009wait(0.05)\010\009\009sp.LDoor2.Transparency = 1\010\009\009sp.RDoor2.Transparency = 1\010\009\009wait(0.05)\010\009\009sp.LDoor3.Transparency = 1\010\009\009sp.RDoor3.Transparency = 1\010\009\009wait(0.05)\010\009\009sp.LDoor4.Transparency = 1\010\009\009sp.RDoor4.Transparency = 1\010\009\009wait(0.05)\010\009\009sp.LDoor5.Transparency = 1\010\009\009sp.RDoor5.Transparency = 1\010\009\009for i = 1,NumberOfMinion do\010\009\009\009minion2 = minion:clone()\010\009\009\009minion2.Parent = Workspace\010\009\009\009minion2:MoveTo(sp.Torso.Position+Vector3.new(0,-22,0))\010\009\009\009minion2[\034Humanoid\034].Jump = true\010\009\009\009wait(SpawnTimePerMinion)\010\009\009end\010\009\009sp.LDoor5.Transparency = 0\010\009\009sp.RDoor5.Transparency = 0\010\009\009wait(0.05)\010\009\009sp.LDoor4.Transparency = 0\010\009\009sp.RDoor4.Transparency = 0\010\009\009wait(0.05)\010\009\009sp.LDoor3.Transparency = 0\010\009\009sp.RDoor3.Transparency = 0\010\009\009wait(0.05)\010\009\009sp.LDoor2.Transparency = 0\010\009\009sp.RDoor2.Transparency = 0\010\009\009wait(0.05)\010\009\009sp.LDoor1.Transparency = 0\010\009\009sp.RDoor1.Transparency = 0\010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23025,class="Script",parent=22801,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="FF",["ScriptGuid"]="{EAF0E360-6DFD-49CB-A5E9-2A279968442C}",["Source"]="ff = Instance.new(\034ForceField\034)\010ff.Parent = script.Parent\010wait(1)\010ff:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23026,class="Script",parent=22801,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{149AA09B-4ED2-42E7-88CA-A087727AF7CE}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009\009if dist < 50 then \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 0\010\009\009\009\009script.Parent.Attack.Value = true \010\009\009\009else \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 5\010\009\009\009\009script.Parent.Attack.Value = false \010\009\009\009end \010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = math.random(0,0)\010\009\009ry = math.random(0,0)\010\009\009rz = math.random(0,0)\010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23027,class="Script",parent=22801,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Damage",["ScriptGuid"]="{7FF2E1B3-AFD2-45F1-8325-E973BE2280EF}",["Source"]="robloxia = script.Parent\010smoke = robloxia.Torso:findFirstChild(\034Smoke\034)\010wait(1.1)\010while true do\010if robloxia.Humanoid.Health < 8000 then\010\009smoke.Enabled = true\010\009wait()\010\009script.Disabled = true\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
