T[#T+1]={id=23030,class="Script",parent=22801,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{F3DDC357-297D-4BBB-9327-907F65CB08C2}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Torso.Death:Play()\010\009e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-50,50),math.random(0,100),math.random(-50,50))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\009\009for i = 1,10 do\010\009\009local minion = game.Lighting[\034Noob\034]:clone()\010\009\009minion.Parent = Workspace\010\009\009minion:MoveTo(script.Parent.Torso.Position + Vector3.new(math.random(-15,15),0,math.random(-15,15)))\010\009\009minion[\034Humanoid\034].Jump = true\010\009end\010\010\009wait(3)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23031,class="Script",parent=22801,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{D609DDFB-57BE-4D6D-9770-30E564378C03}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23060,class="Script",parent=23036,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{8D66BCD8-F99F-4DB0-9409-71D322A6D9F1}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local NormalFace = \034http://www.roblox.com/asset/?id=13335510\034\010local FallFace = \034http://www.roblox.com/asset/?id=66329844\034\010local DiedFace = \034http://www.roblox.com/asset/?id=15395252\034\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local Face = Figure:WaitForChild(\034Head\034):WaitForChild(\034face\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimInstance = nil\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=215190091\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=215190091\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=215188115\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=215192697\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=180436334\034, weight = 10 } \010\009\009\009}, \010\009sit = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=178130996\034, weight = 10 } \010\009\009\009},\009\010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182393478\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182435998\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491037\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491065\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436842\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491248\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491277\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436935\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491368\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491423\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009currentAnimInstance = nil\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\010\009\009local repeatAnim = currentAnim\010\009\009-- return to idle if finishing an emote\010\009\009if (emoteNames[repeatAnim] ~= nil and emoteNames[repeatAnim] == false) then\010\009\009\009repeatAnim = \034idle\034\010\009\009end\010\009\009\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid) \010\009\009\010\009local roll = math.random(1, animTable[animName].totalWeight) \010\009local origRoll = roll\010\009local idx = 1\010\009while (roll > animTable[animName][idx].weight) do\010\009\009roll = roll - animTable[animName][idx].weight\010\009\009idx = idx + 1\010\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009local anim = animTable[animName][idx].anim\010\010\009-- switch animation\009\009\010\009if (anim ~= currentAnimInstance) then\010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\009\009currentAnimInstance = anim\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009\009\010\009end\010\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local toolAnimInstance = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\009\010\009\009playToolAnimation(toolAnimName, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\009 \010\009\009\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009if (toolAnimInstance ~= anim) then\010\009\009\009\010\009\009\009if (toolAnimTrack ~= nil) then\010\009\009\009\009toolAnimTrack:Stop()\010\009\009\009\009toolAnimTrack:Destroy()\010\009\009\009\009transitionTime = 0\010\009\009\009end\010\009\009\009\009\009\010\009\009\009-- load it to the humanoid; get AnimationTrack\010\009\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009\009 \010\009\009\009-- play the animation\010\009\009\009toolAnimTrack:Play(transitionTime)\010\009\009\009toolAnimName = animName\010\009\009\009toolAnimInstance = anim\010\010\009\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009toolAnimInstance = nil\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009\009Face.Texture = NormalFace\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010\009Face.Texture = DiedFace\010\009Face.Changed:connect(function()\010\009\009Face.Texture = DiedFace\010\009end)\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010\009Face.Texture = FallFace\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009playAnimation(\034sit\034, 0.5, Humanoid)\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009stopAllAnimations()\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimInstance = nil\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010Game.Players.LocalPlayer.Chatted:connect(function(msg)\010\009local emote = \034\034\010\009if (string.sub(msg, 1, 3) == \034/e \034) then\010\009\009emote = string.sub(msg, 4)\010\009elseif (string.sub(msg, 1, 7) == \034/emote \034) then\010\009\009emote = string.sub(msg, 8)\010\009end\010\009\010\009if (pose == \034Standing\034 and emoteNames[emote] ~= nil) then\010\009\009playAnimation(emote, 0.1, Humanoid)\010\009end\010--\009print(\034===> \034 .. string.sub(msg, 1, 3) .. \034(\034 .. emote .. \034)\034)\010end)\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23081,class="Script",parent=23036,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{15452405-CF36-4E0D-8215-1AC755F0E88F}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxasset://sounds/uuhhh.wav\034)\010sDied.Pitch = 0.875\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23087,class="Script",parent=23036,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{2E8D4D15-EDBE-4B9D-9CD7-03C98333DA3F}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Leg\034)\010local rarm = script.Parent:FindFirstChild(\034Right Leg\034)\010local Face = script.Parent:WaitForChild(\034Head\034):WaitForChild(\034face\034)\010local AttackEnabled = true\010local TargetAlreadyHit = {}\010\010local NormalFace = \034http://www.roblox.com/asset/?id=13335510\034\010local AttackFace = \034http://www.roblox.com/asset/?id=127959433\034\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function AOEDamage(pos,radius,damage)\010\009local NumberOfTargetInsideRadius = 0\010\009local temp = workspace:children()\010\009for i = 1,#temp do\010\009\009if temp[i] ~= script.Parent then\010\009\009\009local ThisHumanoidIsAlreadyDamaged = false\010\009\009\009local human = temp[i]:findFirstChild(\034Humanoid\034)\010\009\009\009local torso = temp[i]:findFirstChild(\034Torso\034)\010\009\009\009local team = temp[i]:findFirstChild(\034TEAM\034)\010\009\009\009if script.Parent.Humanoid.Health ~= 0 and human ~= nil and torso ~= nil and human.Health ~= 0 and team and team.Value ~= script.Parent.TEAM.Value then\010\009\009\009\009--print(\034Found both Humanoid and Torso\034)\010\009\009\009\009for _, Humanoids in pairs(TargetAlreadyHit) do\010\009\009\009\009\009if Humanoids == human then ThisHumanoidIsAlreadyDamaged = true end\010\009\009\009\009\009--print(\034That Humanoid is already took a damage\034)\010\009\009\009\009end\010\009\009\009\009--print(\034Current: \034..(pos - torso.Position).magnitude)\010\009\009\009\009--print(\034Should: \034..radius + (torso.Size.magnitude/2.5))\010\009\009\009\009if (pos - torso.Position).magnitude < radius + (torso.Size.magnitude/2.5) and ThisHumanoidIsAlreadyDamaged == false then\010\009\009\009\009\009table.insert(TargetAlreadyHit,human)\010\009\009\009\009\009--print(\034Add Humanoid to table\034)\010\009\009\009\009\009NumberOfTargetInsideRadius = NumberOfTargetInsideRadius + 1\010\009\009\009\009\009script.Parent.Torso.Punch:Play()\010\009\009\009\009\009torso.Velocity = (CFrame.new(script.Parent.Torso.Position,torso.Position)).lookVector * 25\010\009\009\009\009\009human.Sit = true\010\009\009\009\009\009human:TakeDamage(damage)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return NumberOfTargetInsideRadius\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010local Anim = script.Parent.Humanoid:LoadAnimation(script.Parent.AttackAnim)\010--[[function Hit(hit)\010\009local human = hit.Parent:FindFirstChild(\034Humanoid\034)\010\009if human ~= nil and AttackEnabled == true then\010\009\009if hit.Parent:findFirstChild(\034TEAM\034) ~= nil and hit.Parent:findFirstChild(\034TEAM\034).Value ~= script.Parent:findFirstChild(\034TEAM\034).Value then\010\009\009\009AttackEnabled = false\010\009\009\009Delay(0.5,function() AttackEnabled = true end)\010\009\009\009if Anim then Anim:Play(nil,nil,1.5) end\010\009\009\009human:TakeDamage(50)\010\009\009\009script.Parent.Head.Bite:play()\010\009\009end\010\009end\010end]]\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Sit = false \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010--[[for _, Child in pairs(script.Parent:GetChildren()) do\010\009if Child:IsA(\034Part\034) or Child:IsA(\034WedgePart\034) or Child:IsA(\034CornerWedgePart\034) then\010\009\009Child.Touched:connect(Hit)\010\009end\010end ]]\010\010while true do\010\009wait(0.1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = -3+(math.random()*6)\010\009\009ry = -3+(math.random()*6)\010\009\009rz = -3+(math.random()*6)\010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009\009if (script.Parent.Torso.Position - target.Position).magnitude < (7.5 + (target.Size.magnitude * 1.25)) then\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.1\010\009\009\009Face.Texture = AttackFace\010\009\009\009local FaceConnection = \009Face.Changed:connect(function()\010\009\009\009\009\009\009\009\009\009Face.Texture = AttackFace\010\009\009\009\009\009\009\009\009end)\010\009\009\009if Anim then Anim:Play(nil,nil,2) end\010\009\009\009wait(0.125)\010\009\009\009for i = 1,2 do\010\009\009\009\009if target then\010\009\009\009\009\009AOEDamage(script.Parent.Torso.Position + (script.Parent.HumanoidRootPart.CFrame.lookVector * 5),15,62.5)\010\009\009\009\009end\010\009\009\009\009wait(0.25)\010\009\009\009\009TargetAlreadyHit = {}\010\009\009\009end\010\009\009\009if FaceConnection then FaceConnection:disconnect() end\010\009\009\009Face.Texture = NormalFace\010\009\009\009wait(0.125)\010\009\009else\010\009\009\009script.Parent.Humanoid.WalkSpeed = 32\010\009\009end\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23304,class="Script",parent=23282,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{5A058C88-0F02-4967-86F6-96658D8D97B3}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009wait(2.5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23306,class="Script",parent=23282,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{659B34DB-2770-4E00-892A-4A71C28DC5D9}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23326,class="Script",parent=23282,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{FF8E0FF4-245D-450F-8490-53A1FC20BEB4}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxassetid://295661351\034)\010sDied.Parent = script.Parent\010sDied.Pitch = 1.3\010sDied.Volume = 1\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23410,class="Script",parent=23329,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="PelletScript",["ScriptGuid"]="{1DC3A97C-B9E8-461F-BEEC-E3656D40412D}",["Source"]="local debris = game:service(\034Debris\034)\010local pellet = script.Parent\010local startingDamage = 10\010local damage = startingDamage\010local LastHitCharacter\010\010\010function WaitForChild(parent, child)\010\009while not parent:FindFirstChild(child) do\010\009\009parent.ChildAdded:wait()\010\009end\010\009return parent:FindFirstChild(child)\010end\010\010--local CreatorTag = WaitForChild(pellet, 'creator')\010\010local GemHitSound = Instance.new('Sound')\010GemHitSound.SoundId = 'http://www.roblox.com/asset/?id=124255305'\010GemHitSound.Pitch=1\010GemHitSound.Parent=pellet\010\010\010--[[function tagHumanoid(humanoid)\010\009-- todo: make tag expire\010\009local tag = pellet:findFirstChild(\034creator\034)\010\009if tag ~= nil then\010\009\009-- kill all other tags\010\009\009while(humanoid:findFirstChild(\034creator\034) ~= nil) do\010\009\009\009humanoid:findFirstChild(\034creator\034).Parent = nil\010\009\009end\010\010\009\009local new_tag = tag:clone()\010\009\009new_tag.Parent = humanoid\010\009\009debris:AddItem(new_tag, 1)\010\009end\010end]]\010\010function Explode(hit)\010\009if hit.Name == \034Torso\034 then\009\010\009\009local humanoid = hit.Parent:findFirstChild(\034Humanoid\034)\010\009\009local team = hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009if humanoid~=nil and team and team.Value ~= pellet.TEAM.Value then\010\009\009\009humanoid:TakeDamage(damage*0.5)\010\009\009end\010\009end\010end\010\010function onTouched(hit)\010\009if hit.Name == \034DeadlyROBUX\034 or hit.CanCollide == false then return end\010\009--local creator = WaitForChild(pellet,'creator')\010\009--if (not hit) or (hit.Name == 'Handle') or (not hit.Parent) then return end\009\010\009if not (hit and hit.Name ~= 'Handle' and hit.Parent) then return end\010\009if pellet:FindFirstChild('IS RAGING') then\010\009\009GemHitSound:Play()\010\009end\010\009local humanoid = hit.Parent:findFirstChild(\034Humanoid\034)\010\009local team = hit.Parent:FindFirstChild(\034TEAM\034)\010\009if humanoid~=nil and humanoid.Parent ~= LastHitCharacter and team and team.Value ~= pellet.TEAM.Value then\010\009\009--[[if startingDamage == damage and game.Players:playerFromCharacter(hit.Parent) == CreatorTag.Value then \010\009\009\009return \010\009\009end\010\009\009tagHumanoid(humanoid)]]\010\009\009humanoid:TakeDamage(damage)\010\009\009LastHitCharacter = humanoid.Parent\010\009\009--[[local hitBindable = humanoid:FindFirstChild('Hit')\010\009\009if hitBindable then\010\009\009\009hitBindable:Invoke(damage, CreatorTag)\010\009\009else\010\009\009\009print(\034Could not find BindableFunction 'Hit'\034)\010\009\009end]]\010\009else\010\009\009--[[if hit.CanCollide == false then return end\010\009\009damage = damage / 1.42\010\009\009if damage < 1 then\010\009\009\009connection:disconnect()\010\009\009\009pellet.Parent = nil\010\009\009end]]\010\009end\010\009if pellet:FindFirstChild(\034IS RAGING\034) then\010\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009Explosion.DestroyJointRadiusPercent = 0\010\009\009Explosion.BlastRadius = 15\010\009\009Explosion.BlastPressure = 1000\010\009\009Explosion.ExplosionType = Enum.ExplosionType.NoCraters\010\009\009Explosion.Position = pellet.Position\010\009\009Explosion.Hit:connect(Explode)\010\009\009Explosion.Parent = Workspace\010\009end\010end\010\010connection = pellet.Touched:connect(onTouched)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23413,class="Script",parent=23329,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalGuiAndAnimations",["ScriptGuid"]="{FD0719F3-A36C-438A-90FA-65C0D8070592}",["Source"]="local Tool = script.Parent;\010\010local EquipAnim\010local ShootAnim \010\010function OnChanged(property)\010\009if property == 'Enabled' then\010\009\009if EquipAnim then EquipAnim:Stop() end\010\009\009if Tool.Enabled == false then\010\009\009\009ShootAnim:Play(nil,nil,2)\010\009\009end\010\009end\010end\010\010\010\010function onEquippedLocal()\010\009local humanoid = Tool.Parent:FindFirstChild('Humanoid')\010\009--EquipAnim = humanoid:LoadAnimation(Tool.Equip)\010\009ShootAnim = humanoid:LoadAnimation(Tool.Shoot)\010\010\009-- Make sure that the tool is still equiped when we play equip anim\010\009Spawn(function() wait() if Tool:IsDescendantOf(Workspace) then\009--[[EquipAnim:Play()]] end end)\010\010\009Tool.Changed:connect(function(property) OnChanged(property) end)\010end\010\010function onUnequippedLocal()\010\009if ShootAnim then ShootAnim:Stop() end\010end\010\010Tool.Equipped:connect(onEquippedLocal)\010Tool.Unequipped:connect(onUnequippedLocal)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23414,class="Script",parent=23329,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Slingshot",["ScriptGuid"]="{DA7955A0-6E7D-4750-A85E-EDA05F7B7D17}",["Source"]="-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010local Tool = script.Parent\010local Handle = WaitForChild(Tool, 'Handle')\010local VELOCITY = 100 -- constant\010local VELOCITY_SQAURED = VELOCITY * VELOCITY\010local VELOCITY_TO_FOURTH = VELOCITY_SQAURED * VELOCITY_SQAURED\010local ASSET_PREFIX = \034http://www.roblox.com/asset/?id=\034\010\010local MyMouse\010\010local SlingShotMeshIds = {Ammo = 94689434, AttachMe = 94689472, Full = 94689497, Handle = 94689515}\010\010local DebrisService = game:GetService('Debris')\010local ContentProvider = Game:GetService(\034ContentProvider\034)\010local Pellet = Instance.new(\034Part\034)\010Pellet.Locked = true\010Pellet.BackSurface = 0\010Pellet.BottomSurface = 0\010Pellet.FrontSurface = 0\010Pellet.LeftSurface = 0\010Pellet.RightSurface = 0\010Pellet.TopSurface = 0\010--Pellet.Shape = 0\010Pellet.formFactor = \034Custom\034\010Pellet.Size = Vector3.new(2,.2,1)\010Pellet.BrickColor = BrickColor.new(\034Bright yellow\034)\010Pellet.Elasticity = 0.01 \010Pellet.Name = \034DeadlyROBUX\034\010--[[local PelletMesh = Instance.new('SpecialMesh')\010PelletMesh.MeshId = ASSET_PREFIX .. SlingShotMeshIds['Ammo']\010PelletMesh.TextureId = ASSET_PREFIX .. 94689543\010PelletMesh.Scale = Vector3.new(1.5, 1.5, 1.5)\010PelletMesh.Name = 'PelletMesh'\010PelletMesh.Parent = Pellet]]\010local Decal = Instance.new(\034Decal\034)\010Decal.Face = 4\010Decal.Texture = \034http://www.roblox.com/asset/?id=8057767\034\010Decal.Parent = Pellet\010local Decal2 = Decal:Clone()\010Decal2.Face = 1\010Decal2.Parent = Pellet\010\010local SlingShotMesh\010\010local EquipSound\010local SlingshotSounds\010\010local PelletCopy\010\010local IsBlingshot= WaitForChild(Tool,'IsBlingshot')\010\010WaitForChild(Tool, 'PelletScript'):clone().Parent = Pellet\010\010function Fire(mouse_pos)\010\010\009if SlingshotSounds then\010\009\009local soundNum = math.random(1, #SlingshotSounds)\010\009\009SlingshotSounds[soundNum]:Play()\010\009end\010\010-- find player's head pos\010\010\009local vCharacter = Tool.Parent\010\009local vPlayer = game.Players:GetPlayerFromCharacter(vCharacter)\010\010\009local head = vCharacter:findFirstChild(\034Head\034)\010\009if head == nil then return end\010\010\009local startPosition = Tool.Handle.Position + Vector3.new(0,0,0)\010\010\009local dir = mouse_pos - startPosition\010\009dir = dir.unit\010\010\009local launch = startPosition + 0 * dir\010\010\009local delta = mouse_pos - launch\010\009\010\009local dy = delta.y\010\009\010\009local new_delta = Vector3.new(delta.x, 0, delta.z)\010\009delta = new_delta\010\010\009local dx = delta.magnitude\010\009local unit_delta = delta.unit\010\009\010\009-- acceleration due to gravity in RBX units\010\009local g = (-9.81 * 20)\010\010\009local theta = computeLaunchAngle( dx, dy, g)\010\010\009local vy = math.sin(theta)\010\009local xz = math.cos(theta)\010\009local vx = unit_delta.x * xz\010\009local vz = unit_delta.z * xz\010\009\010\010\009local missile = Pellet:clone()\010\010\009missile.CFrame = CFrame.new(launch, launch+Vector3.new(vx,vy,vz))\010        \010\009--missile.Position = launch\010\009missile.Velocity = Vector3.new(vx,vy,vz) * VELOCITY +\010\009(CFrame.Angles(math.rad(-180+(math.random()*360)),math.rad(-180+(math.random()*360)),0).lookVector * (math.random()*50))\010\010\009missile.PelletScript.Disabled = false\010\009\010\010\009--[[if IsBlingshot.Value then\010\009\009missile.PelletMesh.MeshId='http://www.roblox.com/asset/?id=98262500'\010\009\009missile.PelletMesh.TextureId='http://www.roblox.com/asset/?id=98259807'\010\009\009missile.PelletMesh.Scale = Vector3.new(3,3,3)\010\009\009local tbling= IsBlingshot:Clone()\010\009\009tbling.Parent=missile\010\009else\010\009\009missile.PelletMesh.Scale = Vector3.new(2,2,2)\010\009end]]\010\010\009--[[local creator_tag = Instance.new(\034ObjectValue\034)\010\009creator_tag.Value = vPlayer\010\009creator_tag.Name = \034creator\034]]\010\009local team = Tool.Parent.TEAM:Clone()\010\009team.Parent = missile\010\009\010\009if Tool.Parent.Rage.Value == true then\010\009\009local rage = Instance.new(\034ObjectValue\034,missile)\010\009\009rage.Name = \034IS RAGING\034\010\009end\010\009\010\009DebrisService:AddItem(missile,2.0)\010\009missile.Parent = game.Workspace\010\010end\010\010\010function computeLaunchAngle(dx,dy,grav)\010\009-- arcane\010\009-- http://en.wikipedia.org/wiki/Trajectory_of_a_projectile\010\009\010\009local g = math.abs(grav)\010\009local inRoot = (VELOCITY_TO_FOURTH) - (g * ((g*dx*dx) + (2*dy*VELOCITY_SQAURED)))\010\009if inRoot <= 0 then\010\009\009return .25 * math.pi\010\009end\010\009local root = math.sqrt(inRoot)\010\009local inATan1 = ((VELOCITY_SQAURED) + root) / (g*dx)\010\010\009local inATan2 = ((VELOCITY_SQAURED) - root) / (g*dx)\010\009local answer1 = math.atan(inATan1)\010\009local answer2 = math.atan(inATan2)\010\009return math.min(answer1,answer2)\010end\010\010\010Tool.Enabled = true\010function OnActivated(targetOverride)\010\009wait(0) --TODO: Remove when Mouse.Hit and Humanoid.TargetPoint update properly on iPad\010\009if not Tool.Enabled then\010\009\009return\010\009end\010\009local character = Tool.Parent;\010\009local humanoid = character:FindFirstChild('Humanoid')\010\009if humanoid == nil or humanoid.Health <= 0 then\010\009\009print(\034Humanoid not found, or not alive\034)\010\009\009return\010\009end\010\010\009Tool.Enabled = false\010\009local targetPos = targetOverride or MyMouse.Hit.p\010\010\009local Projectiles = 10\010\009if Tool.Parent.Rage.Value == true then Projectiles = 3 end\010\010\009for i = 1,Projectiles do\010\009\009Fire(targetPos)\010\009end\010\009if PelletCopy then PelletCopy.Transparency = 1 end\010\009-- swap meshes here\010\009--[[\010\009for i = 0, 0.2, 0.05 do\010\009\009SlingShotMesh.Scale = Vector3.new(0.5, 0.5, 0.5 + i * 8)\010\009\009wait(0.05)\010\009end\010\009SlingShotMesh.Scale = Vector3.new(0.5, 0.5, 0.5)\010\009--]]\010\009wait()\010\009if PelletCopy then PelletCopy.Transparency = 0 end\010\010\009Tool.Enabled = true\010end\010\010Tool.Use.Changed:connect(function()\010\009if Tool.Use.Value == true then\010\009\009OnActivated(Tool.Parent.Target.Value.Position)\010\009\009Tool.Use.Value = false\010\009end\010end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23417,class="Script",parent=23282,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{93C9B01E-D500-438A-B591-0D90DEBD2B7B}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010local ChanceToUseAbility = 25\010local ChanceToUseAbilityInRageMode = 50\010\010local MinionSpawns = 1\010local MinionSpawnsInRageMode = 2\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Sit = false\010\009end \010end \010\010script.Parent.Humanoid.HealthChanged:connect(function()\010\009if script.Parent.Humanoid.Health < script.Parent.Humanoid.MaxHealth/2 then\010\009\009script.Parent.Rage.Value = true\010\009\009script.Parent.Head.Fire.Enabled = true\010\009\009script.Parent.Head.BrickColor = BrickColor.new(\034Really red\034)\010\009\009script.Parent.Head.Face.Texture = \034http://www.roblox.com/asset/?id=109676489\034\010\009\009script.Parent.Head.Rage:Play()\010\009end\010end)\010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010Animation = script.Parent.Humanoid:LoadAnimation(script.BlastAnim)\010\010local WaitTime = 1\010\010while true do\010\009local CurrentMinionSpawn = MinionSpawns\010\009local CurrentAbilityChance = ChanceToUseAbility\010\009if script.Parent.Rage.Value == true then\010\009\009WaitTime = 0.5\010\009\009CurrentMinionSpawn = MinionSpawnsInRageMode\010\009\009CurrentAbilityChance = ChanceToUseAbilityInRageMode\010\009else\010\009\009WaitTime = 1\010\009end\010\009wait(WaitTime)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = -7.5 + (math.random()*15)\010\009\009ry = 0\010\009\009rz = -7.5 + (math.random()*15)\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 15 then\010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 15 and (target.Position - script.Parent.Torso.Position).magnitude < 75 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 50\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 75 then \010\009\009\009script.Parent.Attack.Value = false\010\009\009\009script.Parent.Humanoid.WalkSpeed = 50\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009\009if script.Parent.Attack.Value == false and math.random()*100 > 37.5 then\010\009\009\009script.Parent.Humanoid.Jump = true\010\009\009end\010\009\009if script.Parent.Attack.Value == true then\010\009\009\009if math.random()*100 < (CurrentAbilityChance) then\010\009\009\009\009local AbilityToUse = math.random(2,3)\010\009\009\009\009--[[if AbilityToUse == 1 then\010\009\009\009\009\009local NumberOfBot = 0\010\009\009\009\009\009for _, WorkspaceBots in pairs(Workspace:GetChildren()) do\010\009\009\009\009\009\009if WorkspaceBots:IsA(\034Model\034) then\010\009\009\009\009\009\009\009local Humanoid = WorkspaceBots:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009\009\009local TEAM = WorkspaceBots:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009\009\009if Humanoid and Humanoid.Health ~= 0 and TEAM and TEAM.Value == BrickColor.new(\034Bright red\034) then\010\009\009\009\009\009\009\009\009NumberOfBot = NumberOfBot + 1\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009\009if NumberOfBot < (Workspace.RobloxiaMaxNPC.Value + 5) then\010\009\009\009\009\009\009local MinionToPick =\010\009\009\009\009\009\009{game.Lighting.RobloxiaBots.Guest,\010\009\009\009\009\009\009game.Lighting.RobloxiaBots[\034Chef Guest\034],\010\009\009\009\009\009\009game.Lighting.RobloxiaBots[\034Baseball Guest\034],\010\009\009\009\009\009\009game.Lighting.RobloxiaBots.Girluest,\010\009\009\009\009\009\009game.Lighting.RARERobloxiaBots[\034GIANT Vikinguest\034],\010\009\009\009\009\009\009game.Lighting.RARERobloxiaBots[\034Witch Guest\034]}\010\009\009\009\009\009\009for i = 1,CurrentMinionSpawn do\010\009\009\009\009\009\009\009local Minion = MinionToPick[math.random(1,#MinionToPick)]:Clone()\010\009\009\009\009\009\009\009Minion.Parent = Workspace\010\009\009\009\009\009\009\009Minion:MakeJoints()\010\009\009\009\009\009\009\009Minion:MoveTo(script.Parent.Torso.Position + Vector3.new(-5+(math.random()*10),0,-5+(math.random()*10)))\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009else]]if AbilityToUse == 2 then\010\009\009\009\009\009if Animation then Animation:Play(nil,nil,2) end\010\009\009\009\009\009wait(0.1)\010\009\009\009\009\009script.Parent.Blast:Play()\010\009\009\009\009\009local Wave = Instance.new(\034Part\034)\010\009\009\009\009\009Wave.Name = \034Wave\034\010\009\009\009\009\009Wave.FormFactor = \034Custom\034\010\009\009\009\009\009Wave.BrickColor = BrickColor.new(\034Really blue\034)\010\009\009\009\009\009Wave.Material = Enum.Material.Neon\010\009\009\009\009\009Wave.Shape = Enum.PartType.Ball\010\009\009\009\009\009Wave.Size = Vector3.new(10,10,10)\010\009\009\009\009\009Wave.Transparency = 0.5\010\009\009\009\009\009Wave.TopSurface = 0\010\009\009\009\009\009Wave.BottomSurface = 0\010\009\009\009\009\009Wave.Position = script.Parent.Torso.Position\010\009\009\009\009\009Wave.Anchored = true\010\009\009\009\009\009Wave.CanCollide = false\010\009\009\009\009\009Wave.Parent = Workspace\010\009\009\009\009\009game.Debris:AddItem(Wave,5)\010\009\009\009\009\009Spawn(function()\010\009\009\009\009\009\009for i = 1,10 do\010\009\009\009\009\009\009\009local CurrentCFrame = Wave.CFrame\010\009\009\009\009\009\009\009Wave.Size = Wave.Size + Vector3.new(10,10,10)\010\009\009\009\009\009\009\009Wave.CFrame = CurrentCFrame\010\009\009\009\009\009\009\009Wave.Transparency = Wave.Transparency + 0.05\010\009\009\009\009\009\009\009game:GetService(\034RunService\034).Stepped:wait()\010\009\009\009\009\009\009end\010\009\009\009\009\009\009if Wave then Wave:Destroy() end\010\009\009\009\009\009end)\010\009\009\009\009\009for _, Child in pairs(Workspace:GetChildren()) do\010\009\009\009\009\009\009if Child:IsA(\034Model\034) then\010\009\009\009\009\009\009\009local Humanoid = Child:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009\009\009local Torso = Child:FindFirstChild(\034Torso\034)\010\009\009\009\009\009\009\009local TEAM = Child:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009\009\009if Humanoid and Humanoid.Health ~= 0 and Torso and (Torso.Position - Wave.Position).magnitude < 75 and TEAM and TEAM.Value ~= script.Parent.TEAM.Value then\010\009\009\009\009\009\009\009\009Torso.Velocity = Torso.Velocity + ((CFrame.new(Torso.Position+Vector3.new(0,-10,0),Torso.Position)).lookVector * math.random(10,25))\010\009\009\009\009\009\009\009\009Humanoid.Sit = true\010\009\009\009\009\009\009\009\009Humanoid:TakeDamage(script.Parent.Rage.Value == true and 75 or 50)\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009elseif AbilityToUse == 3 then\010\009\009\009\009\009script.Parent.Humanoid.WalkSpeed = 0\010\009\009\009\009\009script.Parent.Torso.FartSound:Play()\010\009\009\009\009\009local FartPart = Instance.new(\034Part\034)\010\009\009\009\009\009FartPart.Locked = true\010\009\009\009\009\009FartPart.BackSurface = 0\010\009\009\009\009\009FartPart.BottomSurface = 0\010\009\009\009\009\009FartPart.FrontSurface = 0\010\009\009\009\009\009FartPart.LeftSurface = 0\010\009\009\009\009\009FartPart.RightSurface = 0\010\009\009\009\009\009FartPart.TopSurface = 0\010\009\009\009\009\009FartPart.formFactor = \034Custom\034\010\009\009\009\009\009FartPart.Size = Vector3.new(0,0,0)\010\009\009\009\009\009FartPart.Transparency = 1\010\009\009\009\009\009--FartPart.Shape = \034Ball\034\010\009\009\009\009\009FartPart.CanCollide = false\010\009\009\009\009\009FartPart.Anchored = true\010\009\009\009\009\009FartPart.Position = script.Parent.Torso.Position\010\009\009\009\009\009local Smoke = script.ParticleEmitter:Clone()\010\009\009\009\009\009Smoke.Enabled = true\010\009\009\009\009\009Smoke.Parent = FartPart\010\009\009\009\009\009Delay(30,function()\010\009\009\009\009\009\009Smoke.Enabled = false\010\009\009\009\009\009end)\010\009\009\009\009\009game.Debris:AddItem(FartPart,35)\010\009\009\009\009\009FartPart.Parent = Workspace\010\009\009\009\009\009local NewScript = script.Parent.FartAOEDamage:clone()\010\009\009\009\009\009NewScript.AOEPos.Value = script.Parent.Torso.Position\010\009\009\009\009\009script.Parent.TEAM:Clone().Parent = NewScript\010\009\009\009\009\009NewScript.Disabled = false\010\009\009\009\009\009NewScript.Parent = Workspace\010\009\009\009\009end\010\009\009\009else\010\009\009\009\009script.Parent.Moneybag.Use.Value = true\010\009\009\009end\010\009\009end\010\009else \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23422,class="Script",parent=23282,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="FartAOEDamage",["ScriptGuid"]="{65F665BB-475E-46F5-9E74-90A8F63F0AB6}",["Source"]="wait()\010game.Debris:AddItem(script,30)\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010while true do\010\009for _, Child in pairs(Workspace:GetChildren()) do\010\009\009if Child:IsA(\034Model\034) and Child.Name ~= \034Guest 1337\034 then\010\009\009\009Humanoid = Child:FindFirstChild(\034Humanoid\034)\010\009\009\009Torso = Child:FindFirstChild(\034Torso\034)\010\009\009\009TEAM = Child:FindFirstChild(\034TEAM\034)\010\009\009\009if Humanoid and Torso and Humanoid.Health ~= 0 and TEAM and TEAM.Value ~= script.TEAM.Value and (script.AOEPos.Value - Torso.Position).magnitude < 37.5 then\010\009\009\009\009Humanoid:TakeDamage(5)\010\009\009\009elseif Humanoid and Torso and Humanoid.Health ~= 0 and TEAM and TEAM.Value == script.TEAM.Value and (script.AOEPos.Value - Torso.Position).magnitude < 37.5 then --WARNING: Friendly Fire\010\009\009\009\009Humanoid:TakeDamage(0)\010\009\009\009end\010\009\009end\010\009end\010\009wait(0.1)\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23453,class="Script",parent=23430,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{E9DAF8C8-DACB-4EF9-9C67-8A7D077FBA7C}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23471,class="Script",parent=23430,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="HealthRegenerationScript",["ScriptGuid"]="{92420B5E-60CD-4AA1-80AF-273610616D8D}",["Source"]="-- Renegeration Script for the bot\013\010-- Renegerates about 1% of max hp per second until it reaches max health\013\010bot = script.Parent\013\010Humanoid = bot:FindFirstChild(\034Humanoid\034)\013\010\013\010local regen = false\013\010\013\010function regenerate() \013\010\009if regen then return end\013\010\009-- Lock this function until the regeneration to max health is complete by using a boolean toggle\013\010\009regen = true\013\010\009while Humanoid.Health < Humanoid.MaxHealth do\013\010\009\009local delta = wait(1)\013\010\009\009local health = Humanoid.Health\013\010\009\009if health > 0 and health < Humanoid.MaxHealth then \013\010\009\009\009-- This delta is for regenerating 1% of max hp per second instead of 1 hp per second\013\010\009\009\009delta = 0.01 * delta * Humanoid.MaxHealth\013\010\009\009\009health = health + delta\013\010\009\009\009Humanoid.Health = math.min(health, Humanoid.MaxHealth)\009\009\009\013\010\009\009end\013\010\009end\009\013\010\009-- release the lock, since the health is at max now, and if the character loses health again\013\010\009-- it needs to start regenerating \013\010\009regen = false\013\010end\009\013\010\013\010if Humanoid then \013\010\009-- Better than a while true do loop since it only fires when the health actually changes\013\010\009Humanoid.HealthChanged:connect(regenerate)\009\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23473,class="Script",parent=23430,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{1A797127-405B-4B7C-838E-F2EBA735DDBE}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034http://www.roblox.com/asset/?id=130783046\034)\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23475,class="Script",parent=23430,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ZombieScript",["ScriptGuid"]="{8FB87022-81E5-4145-9E57-AF82E5B49825}",["Source"]="--Made by Stickmasterluke\010\010--Zombie artificial stupidity script\010\010\010sp=script.Parent\010lastattack=0\010nextrandom=0\010nextsound=0\010nextjump=0\010chasing=false\010\010variance=4\010\010damage=500\010attackrange=30\010sightrange=999999999999999999999999999999999999999999999999999999999--60\010runspeed=12\010wonderspeed=5\010healthregen=false\010colors={\034Sand red\034,\034Dusty Rose\034,\034Medium blue\034,\034Sand blue\034,\034Lavender\034,\034Earth green\034,\034Brown\034,\034Medium stone grey\034,\034Brick yellow\034}\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function waitForChild(parent,childName)\010\009local child=parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child=parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010-- ANIMATION\010\010-- declarations\010\010local Torso=waitForChild(sp,\034Torso\034)\010local Head=waitForChild(sp,\034Head\034)\010local RightShoulder=waitForChild(Torso,\034Right Shoulder\034)\010local LeftShoulder=waitForChild(Torso,\034Left Shoulder\034)\010local RightHip=waitForChild(Torso,\034Right Hip\034)\010local LeftHip=waitForChild(Torso,\034Left Hip\034)\010local Neck=waitForChild(Torso,\034Neck\034)\010local Humanoid=waitForChild(sp,\034Humanoid\034)\010local BodyColors=waitForChild(sp,\034Body Colors\034)\010local pose=\034Standing\034\010local hitsound=waitForChild(Torso,\034HitSound\034)\010local Anim = Humanoid:LoadAnimation(sp.AttackAnim)\010\010--[[local sounds={\010\009waitForChild(Torso,\034GroanSound\034),\010\009waitForChild(Torso,\034RawrSound\034)\010}]]\010\010if healthregen then\010\009local regenscript=waitForChild(sp,\034HealthRegenerationScript\034)\010\009regenscript.Disabled=false\010end\010Humanoid.WalkSpeed=wonderspeed\010\010local toolAnim=\034None\034\010local toolAnimTime=0\010\010--[[BodyColors.HeadColor=BrickColor.new(\034Grime\034)\010local randomcolor1=colors[math.random(1,#colors)]\010BodyColors.TorsoColor=BrickColor.new(randomcolor1)\010BodyColors.LeftArmColor=BrickColor.new(randomcolor1)\010BodyColors.RightArmColor=BrickColor.new(randomcolor1)\010local randomcolor2=colors[math.random(1,#colors)]\010BodyColors.LeftLegColor=BrickColor.new(randomcolor2)\010BodyColors.RightLegColor=BrickColor.new(randomcolor2)]]\010\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009pose=\034Running\034\010\009else\010\009\009pose=\034Standing\034\010\009end\010end\010function onDied()\010\009pose=\034Dead\034\010end\010function onJumping()\010\009pose=\034Jumping\034\010end\010function onClimbing()\010\009pose=\034Climbing\034\010end\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010function onFreeFall()\010\009pose = \034FreeFall\034\010end\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010function onSeated()\010\009pose = \034Seated\034\010end\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function moveJump()\010\009RightShoulder.MaxVelocity = 0.5\010\009LeftShoulder.MaxVelocity = 0.5\010  RightShoulder.DesiredAngle=3.14\010\009LeftShoulder.DesiredAngle=-3.14\010\009RightHip.DesiredAngle=0\010\009LeftHip.DesiredAngle=0\010end\010\010function moveFreeFall()\010\009RightShoulder.MaxVelocity = 0.5\010\009LeftShoulder.MaxVelocity =0.5\010\009RightShoulder.DesiredAngle=3.14\010\009LeftShoulder.DesiredAngle=-3.14\010\009RightHip.DesiredAngle=0\010\009LeftHip.DesiredAngle=0\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder.DesiredAngle=3.14 /2\010\009LeftShoulder.DesiredAngle=-3.14 /2\010\009RightHip.DesiredAngle=3.14 /2\010\009LeftHip.DesiredAngle=-3.14 /2\010end\010\010function animate(time)\010\009local amplitude\010\009local frequency\010\009if (pose == \034Jumping\034) then\010\009\009moveJump()\010\009\009return\010\009end\010\009if (pose == \034FreeFall\034) then\010\009\009moveFreeFall()\010\009\009return\010\009end\010\009if (pose == \034Seated\034) then\010\009\009moveSit()\010\009\009return\010\009end\010\009local climbFudge = 0\010\009if (pose == \034Running\034) then\010\009\009RightShoulder.MaxVelocity = 0.15\010\009\009LeftShoulder.MaxVelocity = 0.15\010\009\009amplitude = 1\010\009\009frequency = 9\010\009elseif (pose == \034Climbing\034) then\010\009\009RightShoulder.MaxVelocity = 0.5 \010\009\009LeftShoulder.MaxVelocity = 0.5\010\009\009amplitude = 1\010\009\009frequency = 9\010\009\009climbFudge = 3.14\010\009else\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009end\010\009desiredAngle = amplitude * math.sin(time*frequency)\010\009if not chasing and frequency==9 then\010\009\009frequency=4\010\009end\010\009if chasing then\010\009\009--[[RightShoulder.DesiredAngle=math.pi/2\010\009\009LeftShoulder.DesiredAngle=-math.pi/2\010\009\009RightHip.DesiredAngle=-desiredAngle*2\010\009\009LeftHip.DesiredAngle=-desiredAngle*2]]\010\009else\010\009\009RightShoulder.DesiredAngle=desiredAngle + climbFudge\010\009\009LeftShoulder.DesiredAngle=desiredAngle - climbFudge\010\009\009RightHip.DesiredAngle=-desiredAngle\010\009\009LeftHip.DesiredAngle=-desiredAngle\010\009end\010end\010\010\010function attack(time,attackpos)\010\009if time-lastattack>=0.25 then\010\009\009local hit,pos=raycast(Torso.Position,(attackpos-Torso.Position).unit,attackrange)\010\009\009if hit and hit.Parent~=nil then\010\009\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local TEAM=hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h and TEAM and TEAM.Value~=sp.TEAM.Value then\010\009\009\009\009local creator=sp:FindFirstChild(\034creator\034)\010\009\009\009\009if creator then\010\009\009\009\009\009if creator.Value~=nil then\010\009\009\009\009\009\009if creator.Value~=game.Players:GetPlayerFromCharacter(h.Parent) then\010\009\009\009\009\009\009\009for i,oldtag in ipairs(h:GetChildren()) do\010\009\009\009\009\009\009\009\009if oldtag.Name==\034creator\034 then\010\009\009\009\009\009\009\009\009\009oldtag:remove()\010\009\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009creator:clone().Parent=h\010\009\009\009\009\009\009else\010\009\009\009\009\009\009\009return\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009\009if Anim then Anim:Play(nil,nil,1.5) end\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009\009hitsound.Volume=1\010\009\009\009\009hitsound.Pitch=.75+(math.random()*.5)\010\009\009\009\009hitsound:Play()\010\009\009\009\009--[[if RightShoulder and LeftShoulder then\010\009\009\009\009\009RightShoulder.CurrentAngle=0\010\009\009\009\009\009LeftShoulder.CurrentAngle=0\010\009\009\009\009end]]\010\009\009\009end\010\009\009end\010\009\009lastattack=time\010\009end\010end\010\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010\010\010function populatehumanoids(mdl)\010\009if mdl.ClassName==\034Humanoid\034 then\010\009\009if mdl.Parent:FindFirstChild(\034TEAM\034) and mdl.Parent:FindFirstChild(\034TEAM\034).Value~=sp.TEAM.Value then\010\009\009\009table.insert(humanoids,mdl)\010\009\009end\010\009end\010\009for i2,mdl2 in ipairs(mdl:GetChildren()) do\010\009\009populatehumanoids(mdl2)\010\009end\010end\010\010--[[function playsound(time)\010\009nextsound=time+5+(math.random()*5)\010\009local randomsound=sounds[math.random(1,#sounds)]\010\009randomsound.Volume=.5+(.5*math.random())\010\009randomsound.Pitch=.5+(.5*math.random())\010\009randomsound:Play()\010end]]\010\010while sp.Parent~=nil and Humanoid and Humanoid.Parent~=nil and Humanoid.Health>0 and Torso and Head and Torso~=nil and Torso.Parent~=nil do\010\009local _,time=wait(0.25)--wait(1/3)\010\009humanoids={}\010\009populatehumanoids(game.Workspace)\010\009closesttarget=nil\010\009closestdist=sightrange\010\009local creator=sp:FindFirstChild(\034creator\034)\010\009for i,h in ipairs(humanoids) do\010\009\009if h and h.Parent~=nil then\010\009\009\009if h.Health>0 and h.Parent~=sp then\010\009\009\009\009local plr=game.Players:GetPlayerFromCharacter(h.Parent)\010\009\009\009\009if creator==nil or plr==nil or creator.Value~=plr then\010\009\009\009\009\009local t=h.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009if t~=nil then\010\009\009\009\009\009\009local dist=(t.Position-Torso.Position).magnitude\010\009\009\009\009\009\009if dist<closestdist then\010\009\009\009\009\009\009\009closestdist=dist\010\009\009\009\009\009\009\009closesttarget=t\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009if closesttarget~=nil then\010\009\009if not chasing then\010\009\009\009--playsound(time)\010\009\009\009chasing=true\010\009\009\009Humanoid.WalkSpeed=runspeed\010\009\009end\010\009\009Humanoid:MoveTo(closesttarget.Position+(Vector3.new(1,1,1)*(variance*((math.random()*2)-1))),closesttarget)\010\009\009if math.random()<.5 then\010\009\009\009attack(time,closesttarget.Position)\010\009\009end\010\009else\010\009\009if chasing then\010\009\009\009chasing=false\010\009\009\009Humanoid.WalkSpeed=wonderspeed\010\009\009end\010\009\009if time>nextrandom then\010\009\009\009nextrandom=time+3+(math.random()*5)\010\009\009\009local randompos=Torso.Position+((Vector3.new(1,1,1)*math.random()-Vector3.new(.5,.5,.5))*40)\010\009\009\009Humanoid:MoveTo(randompos,game.Workspace.Terrain)\010\009\009end\010\009end\010\009if time>nextsound then\010\009\009--playsound(time)\010\009end\010\009if time>nextjump then\010\009\009nextjump=time+7+(math.random()*5)\010\009\009Humanoid.Jump=true\010\009end\010\009animate(time)\010end\010\010wait(4)\010sp:remove() --Rest In Pizza\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23481,class="Script",parent=23430,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{5A57C5EE-00AE-4739-9067-D6AEF541D926}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23484,class="Script",parent=23482,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{12F62C90-7B67-4BE4-9CEF-33BD34C0B0BB}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxassetid://138108873\034)\010--sDied.Pitch = 0.75\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23487,class="Script",parent=23482,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{A7357577-F9CB-4D95-B48B-3F01AFC1D57B}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23506,class="Script",parent=23482,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{C153C1A0-598A-452B-B82D-8203B1EFE5C2}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(0.1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 125 and\010\009\009\009 (target.Position - script.Parent.Torso.Position).magnitude > 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude < 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = -16\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 125 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 16\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23507,class="Script",parent=23482,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{41DDF54D-9986-4DAD-B400-10CB9F8C7FC4}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009wait(2.5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23508,class="Script",parent=23482,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="HealthRegenerationScript",["ScriptGuid"]="{3E2C6113-D467-4687-955C-EAF645211A3C}",["Source"]="-- Renegeration Script for the bot\013\010-- Renegerates about 1% of max hp per second until it reaches max health\013\010bot = script.Parent\013\010Humanoid = bot:FindFirstChild(\034Humanoid\034)\013\010\013\010local regen = false\013\010\013\010function regenerate() \013\010\009if regen then return end\013\010\009-- Lock this function until the regeneration to max health is complete by using a boolean toggle\013\010\009regen = true\013\010\009while Humanoid.Health < Humanoid.MaxHealth do\013\010\009\009local delta = wait(1)\013\010\009\009local health = Humanoid.Health\013\010\009\009if health > 0 and health < Humanoid.MaxHealth then \013\010\009\009\009-- This delta is for regenerating 1% of max hp per second instead of 1 hp per second\013\010\009\009\009delta = 0.01 * delta * Humanoid.MaxHealth\013\010\009\009\009health = health + delta\013\010\009\009\009Humanoid.Health = math.min(health, Humanoid.MaxHealth)\009\009\009\013\010\009\009end\013\010\009end\009\013\010\009-- release the lock, since the health is at max now, and if the character loses health again\013\010\009-- it needs to start regenerating \013\010\009regen = false\013\010end\009\013\010\013\010if Humanoid then \013\010\009-- Better than a while true do loop since it only fires when the health actually changes\013\010\009Humanoid.HealthChanged:connect(regenerate)\009\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23521,class="Script",parent=23515,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{C5E8C23C-76D9-4C57-9EC2-37F076BB54DD}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010\010\010firerate=0.5\010range=950\010power=300\010rate=1/30\010spinuptime=0\010barreloffset=Vector3.new(0,2.75,.375)\010windvec=Vector3.new(2,-1,1).unit\010firetime=0\010maxammo=20\010reloadtime = 5\010ammo=maxammo\010\010debris=game:GetService(\034Debris\034)\010equipped=false\010check=true\010firing=false\010reloading=false\010fireanimdelay=0\010handle=sp:WaitForChild(\034Handle\034)\010--handle2=sp:WaitForChild(\034Handle2\034)\010handles = {handle}\010handlestofire = 1\010anim = sp.Parent.Humanoid:LoadAnimation(sp.idle)\010anim2 = sp.Parent.Humanoid:LoadAnimation(sp.FireAni)\010anim3 = sp.Parent.Humanoid:LoadAnimation(sp.Reload)\010--fireanimloop = false\010\010--[[Spawn(function()\010\009while true do\010\009\009fireanimdelay = fireanimdelay - game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009if fireanimdelay <= 0 then\010\009\009\009fireanimdelay = 0\010\009\009\009if anim2 and fireanimloop then anim2:Stop() fireanimloop = false end\010\009\009end\010\009\009wait()\010\009end\010end)]]\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function waitfor(parent,name)\010\009while parent:FindFirstChild(name)==nil do\010\009\009wait()\010\009end\010\009return parent:FindFirstChild(name)\010end\010\010function checkintangible(hit)\010\009if hit and hit~=nil then\010\009\009if hit:IsDescendantOf(sp.Parent) or hit.Transparency>.8 or hit.Name==\034Handle\034 or hit.Name==\034Effect\034 or hit.Name==\034Bullet\034 or hit.Name==\034Laser\034 or string.lower(hit.Name)==\034water\034 or hit.Name==\034Rail\034 or hit.Name==\034Arrow\034 then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function castray(startpos,vec,length,ignore,delayifhit)\010\009local hit,endpos2=game.Workspace:FindPartOnRay(Ray.new(startpos,vec*length),ignore)\010\009if hit~=nil then\010\009\009if checkintangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit,endpos2=castray(endpos2+(vec*.01),vec,length-((startpos-endpos2).magnitude),ignore,delayifhit)\010\009\009end\010\009end\010\009return hit,endpos2\010end\010\010function drawbeam(beamstart,beamend,clr,fadedelay)\010\009local dist=(beamstart-beamend).magnitude\010\009local laser=Instance.new(\034Part\034)\010\009laser.Name=\034Effect\034\010\009laser.Anchored=true\010\009laser.CanCollide=false\010\009laser.Shape=\034Block\034\010\009laser.formFactor=\034Custom\034\010\009laser.Size=Vector3.new(.2,.2,.2)\010\009laser.Transparency=0\010\009laser.Material=Enum.Material.Plastic\010\009laser.Locked=true\010\009laser.TopSurface=0\010\009laser.BottomSurface=0\010\009laser.BrickColor=clr\010\009laser.CFrame=CFrame.new(beamend,beamstart)*CFrame.new(0,0,-dist/2)*CFrame.Angles(math.pi/2,0,0)\010\009local m=Instance.new(\034SpecialMesh\034)\010\009m.Scale=Vector3.new(1,dist*5,1)\010\009m.MeshType=\034Brick\034\010\009m.Parent=laser\010\009debris:AddItem(laser,fadedelay*0.5)\010\009laser.Parent=game.Workspace\010\010\009--[[local frames=math.floor(fadedelay/rate)\010\009for frame=1,frames do\010\009\009wait(rate)\010\009\009local percent=frame/frames\010\009\009laser.CFrame=laser.CFrame+windvec*rate\010\009\009laser.Transparency=.5+(percent*.5)\010\009end]]\010\009wait(.5)\010\009laser:remove()\010end\010\010function fire()\010\009local hu=sp.Parent:FindFirstChild(\034Humanoid\034)\010\009local he=sp.Parent:FindFirstChild(\034Head\034)\010\009local t=sp.Parent:FindFirstChild(\034Torso\034)\010\009local team=sp.Parent:FindFirstChild(\034TEAM\034)\010\009--if handlestofire == 1 then handlestofire = 2 elseif handlestofire == 2 then handlestofire = 1 end\010\009if hu and team and hu.Health>0 and t and he and equipped then\010\010\009\009if anim2 and not fireanimloop then anim2:Play() anim2:AdjustSpeed(5) fireanimloop = true end\010\009\009fireanimdelay = 0.5\010\009\009local startpos=he.Position\010\009\009local fakestartpos=(handles[handlestofire].CFrame*CFrame.new(barreloffset)).p\010\009\009local vec=(sp.Parent.Target.Value.Position-startpos).unit + (Vector3.new(math.random(-1000,1000),math.random(-1000,1000),math.random(-1000,1000)) / (1500*30))\010\010\009\009local p=Instance.new(\034Part\034)\010\009\009p.Name=\034Effect\034\010\009\009p.BrickColor=BrickColor.new(\034Black\034)\010\009\009p.CanCollide=false\010\009\009p.TopSurface=\034Smooth\034\010\009\009p.BottomSurface=\034Smooth\034\010\009\009p.formFactor=\034Custom\034\010\009\009p.Size=Vector3.new(0,0,0)\010\009\009p.Transparency=1\010\009\009local m=Instance.new(\034SpecialMesh\034)\010\009\009m.Parent=p\010\010\009\009local hit,endpos=castray(startpos,vec,range,sp.Parent,false)\010\009\009local fakevec=(endpos-fakestartpos).unit\010\009\009if hit~=nil then\010\009\009\009local newcf=CFrame.new(endpos,endpos+fakevec)*CFrame.Angles(math.pi/2,0,0)*CFrame.new(0,0,0)\010\009\009\009p.CFrame=newcf\010\009\009\009local w=Instance.new(\034Weld\034)\010\009\009\009w.Part0=hit\010\009\009\009w.Part1=p\010\009\009\009w.C0=hit.CFrame:inverse()*newcf\010\009\009\009w.C1=newcf:inverse()*newcf\010\009\009\009w.Parent=p\010\010\009\009\009--[[local c=Instance.new(\034ObjectValue\034)\010\009\009\009c.Name=\034creator\034\010\009\009\009c.Value=game.Players.LocalPlayer\010\009\009\009c.Parent=p]]\010\009\009\009\010\009\009\009team:clone().Parent=p\010\010\009\009\009local s=script.Script:clone()\010\009\009\009s.Parent=p\010\009\009\009s.Disabled=false\010\009\009else\010\009\009\009p.CFrame=CFrame.new(endpos,endpos+fakevec)\010\009\009\009p.Velocity=fakevec*power\010\009\009\009p.Parent=game.Workspace\010\009\009end\010\010\009\009debris:AddItem(p,1)\010\009\009p.Parent=game.Workspace\010\010\009\009delay(0,function()\010\009\009\009drawbeam(fakestartpos,endpos,BrickColor.new(\034Bright yellow\034),.1)\010\009\009end)\010\010\009\009local sound=script.Fire\010\009\009if sound~=nil then\010\009\009\009--sound:Stop()\010\009\009\009sound:Play()\010\009\009end\010\010\009\009local shoulder=t:FindFirstChild(\034Right Shoulder\034)\010\009\009if shoulder~=nil then\010\009\009\009shoulder.CurrentAngle=(math.pi/2)+.1\010\009\009end\010\009end\010end\010\010function onEquipped(mouse)\010\009equipped=true\010\009anim = sp.Parent.Humanoid:LoadAnimation(sp.idle)\010\009if anim then anim:Play() end\010\009--[[if mouse~=nil then\010\009\009themouse=mouse\010\009\009mouse.Icon=\034rbxasset://textures\092\092GunCursor.png\034\010\009\009mouse.Button1Down:connect(function()\010\009\009\009mouse.Icon=\034rbxasset://textures\092\092GunWaitCursor.png\034\010\009\009\009firetime=tick()+spinuptime\010\009\009\009down=true\010\009\009end)\010\009\009mouse.Button1Up:connect(function()\010\009\009\009down=false\010\009\009\009mouse.Icon=\034rbxasset://textures\092\092GunCursor.png\034\010\009\009end)\010\009end]]\010end\010\010function Reload()\010\009anim3 = sp.Parent.Humanoid:LoadAnimation(sp.Reload)\010\009if anim3 then anim3:Play() anim3:AdjustSpeed(2.5) end\010\009local sound=script.Reload\010\009if sound~=nil then\010\009\009sound:Play()\010\009end\010\009wait(reloadtime)\010\009ammo = maxammo\010end\010\010function onUnequipped()\010\009if anim then anim:Stop() end\010\009equipped=false\010\009themouse=nil\010end\010\010sp.Equipped:connect(onEquipped)\010sp.Unequipped:connect(onUnequipped)\010\010while true do\010\009if sp.Parent.Attack.Value == true then\010\009\009if ammo > 0 then\010\009\009\009ammo = ammo - 1\010\009\009\009fire()\010\009\009\009wait(firerate)\010\009\009else\010\009\009\009Reload()\010\009\009end\010\009else\010\009\009wait()\010\009end\010end\010\010\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23522,class="Script",parent=23521,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{2BDD302C-72ED-4E12-9765-449F77BFB674}",["Source"]="--Stickmasterluke\010\010\010sp=script.Parent\010\010damage=1000--15\010\010wait()\010\010local weld=sp:FindFirstChild(\034Weld\034)\010if weld~=nil then\010\009if weld.Part0~=nil then\010\009\009hit=weld.Part0\010\009\009local sound=sp:FindFirstChild(\034Sound\034)\010\009\009if sound~=nil then\010\009\009\009sound:Play()\010\009\009end\010\009\009if hit.Name~=\034Handle\034 and hit.Name~=\034Effect\034 then\010\009\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local t=hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009local team=hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h~=nil and t~=nil and h.Health>0 and team~=nil and team.Value~=sp.TEAM.Value then\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009end\010\009\009end\010\009end\010end\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23573,class="Script",parent=23572,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{7669F3FC-CB1B-44EB-B86F-637757241365}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23596,class="Script",parent=23572,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{A5D14387-F8B5-4A2F-B0BC-1925C40A4106}",["Source"]="--print(\034Loaded.\034)\010--You don't need to edit this!\010\010Character = script.Parent\010Humanoid = Character.Humanoid\010Torso = Character.Torso\010mode = Instance.new(\034Model\034)\010mode.Name = \034\034\010mode.Parent = game.Workspace\010\010function OnDeath()\010\009\010\009--[[print(\034Death\034)]]\010        wait(0.00000001)\010\009Character:Remove()\009\009\010end\010\010Humanoid.Died:connect(OnDeath)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23607,class="Script",parent=23572,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{DE6D077F-A40B-4611-B0E5-10E028BEFE14}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 999999999999999999999999999999\010\009local distHeal = 99999999999999999999999999999\010\009local InjuredTarget = false\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value == script.Parent.TEAM.Value) and (temp2.Name ~= \034Core\034) then\010\009\009\009\009if human.Health ~= human.MaxHealth then InjuredTarget = true end\010\009\009\009\009if (InjuredTarget and (temp.Position - pos).magnitude < distHeal) or\010\009\009\009\009\009(not InjuredTarget and (temp.Position - pos).magnitude < dist) then\010\009\009\009\009\009if (human.Health ~= human.MaxHealth and InjuredTarget == true) or\010\009\009\009\009\009\009(human.Health == human.MaxHealth and InjuredTarget == false) then\010\009\009\009\009\009\009torso = temp\010\009\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009\009if not InjuredTarget then\010\009\009\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\009\009\009\009\009\009else\010\009\009\009\009\009\009\009distHeal = (temp.Position - pos).magnitude\010\009\009\009\009\009\009end\010\009\009\010\009\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009\009else \010\009\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009\009end \010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010local Anim = script.Parent.Humanoid:LoadAnimation(script.Heal)\010\010while true do\010\009wait(0.1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 25 + (target.Size.magnitude * 1.25) then\010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009\009local TargetHum = target.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if TargetHum and TargetHum.Health ~= TargetHum.MaxHealth then\010\009\009\009\009if Anim then Anim:Play(0.1, 1, 4) end\010\009\009\009\009script.Parent.Torso.Heal:Play()\010\009\009\009\009TargetHum.Health = TargetHum.Health + 50\010\009\009\009\009local Fire = Instance.new(\034Fire\034)\010\009\009\009\009Fire.Size = 10\010\009\009\009\009Fire.Heat = 0\010\009\009\009\009Fire.Color = Color3.new(0,1,0)\010\009\009\009\009Fire.SecondaryColor = Color3.new(0,1,0)\010\009\009\009\009Fire.Parent = target\010\009\009\009\009local Sparkles = Instance.new(\034Sparkles\034)\010\009\009\009\009Sparkles.SparkleColor = Color3.new(0,1,0)\010\009\009\009\009Sparkles.Parent = target\010\009\009\009\009Delay(0.5,function()\010\009\009\009\009\009Fire.Enabled = false\010\009\009\009\009\009Sparkles.Enabled = false\010\009\009\009\009end)\010\009\009\009\009game.Debris:AddItem(Fire,5)\010\009\009\009\009game.Debris:AddItem(Sparkles,5)\010\009\009\009\009wait(1)\010\009\009\009\009if Anim then Anim:Stop() end\010\009\009\009end\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 25 + (target.Size.magnitude * 1.25) then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 50\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23621,class="Script",parent=23572,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{FE7B4A3F-26F4-4CC5-AD80-5C48CA3AC827}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = script.Parent.Head[\034Death\034..math.random(1,3)]--newSound(\034rbxasset://sounds/uuhhh.wav\034)\010--sDied.Pitch = 0.75\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23622,class="Script",parent=23572,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="AIUseFPSMode",["ScriptGuid"]="{FC2AF93F-A700-42F2-A9AA-5ED56CEDA480}",["Source"]="gyro = Instance.new(\034BodyGyro\034)\010gyro.Parent = script.Parent:findFirstChild(\034Torso\034)\010gyro.P = 7500\010gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\010while true do\010\009vCharacter = script.Parent\010\009if vCharacter ~= nil and vCharacter.Target.Value and vCharacter.Attack.Value then \010\009\009gyro.Parent = script.Parent.Torso\010\009\009local tp = vCharacter.Target.Value.Position\010\009\009tp = Vector3.new(tp.X,script.Parent.Torso.Position.Y,tp.Z) \010\009\009local dir = (tp - script.Parent.Torso.Position).unit\010\009\009local spawnPos = script.Parent.Torso.Position\010\009\009local pos = spawnPos + (dir * 1)\010\009\009gyro.cframe = CFrame.new(pos,  pos + dir)\010\009elseif not vCharacter.Attack.Value then\010\009\009gyro.Parent = nil\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23653,class="Script",parent=23628,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{7D7906FB-D93E-4A6B-B5BA-AF8519A6C858}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23673,class="Script",parent=23672,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="health",["ScriptGuid"]="{F207D7AF-D85E-440D-8C66-1FCE81A60EA1}",["Source"]="script.Parent.MaxHealth = 20000\010wait(1)\010script.Parent.Health = script.Parent.MaxHealth\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23674,class="Script",parent=23628,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{C6597BD0-22B9-4A18-8EC7-9DD746C163CD}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxassetid://213632774\034)\010sDied.Parent = script.Parent\010sDied.Pitch = 1.3\010sDied.Volume = 1\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23758,class="Script",parent=23677,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="PelletScript",["ScriptGuid"]="{7960B2F0-1F84-4813-A66D-680271568D55}",["Source"]="local debris = game:service(\034Debris\034)\010local pellet = script.Parent\010local startingDamage = 150\010local damage = startingDamage\010local LastHitCharacter\010\010\010function WaitForChild(parent, child)\010\009while not parent:FindFirstChild(child) do\010\009\009parent.ChildAdded:wait()\010\009end\010\009return parent:FindFirstChild(child)\010end\010\010--local CreatorTag = WaitForChild(pellet, 'creator')\010\010local GemHitSound = Instance.new('Sound')\010GemHitSound.SoundId = 'http://www.roblox.com/asset/?id=124255305'\010GemHitSound.Pitch=1\010GemHitSound.Parent=pellet\010\010\010--[[function tagHumanoid(humanoid)\010\009-- todo: make tag expire\010\009local tag = pellet:findFirstChild(\034creator\034)\010\009if tag ~= nil then\010\009\009-- kill all other tags\010\009\009while(humanoid:findFirstChild(\034creator\034) ~= nil) do\010\009\009\009humanoid:findFirstChild(\034creator\034).Parent = nil\010\009\009end\010\010\009\009local new_tag = tag:clone()\010\009\009new_tag.Parent = humanoid\010\009\009debris:AddItem(new_tag, 1)\010\009end\010end]]\010\010function Explode(hit)\010\009if hit.Name == \034Torso\034 then\009\010\009\009local humanoid = hit.Parent:findFirstChild(\034Humanoid\034)\010\009\009local team = hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009if humanoid~=nil and team and team.Value ~= pellet.TEAM.Value then\010\009\009\009humanoid:TakeDamage(damage*0.5)\010\009\009end\010\009end\010end\010\010function onTouched(hit)\010\009if hit.Name == \034DeadlyROBUX\034 or hit.CanCollide == false then return end\010\009--local creator = WaitForChild(pellet,'creator')\010\009--if (not hit) or (hit.Name == 'Handle') or (not hit.Parent) then return end\009\010\009if not (hit and hit.Name ~= 'Handle' and hit.Parent) then return end\010\009if pellet:FindFirstChild('IS RAGING') then\010\009\009GemHitSound:Play()\010\009end\010\009local humanoid = hit.Parent:findFirstChild(\034Humanoid\034)\010\009local team = hit.Parent:FindFirstChild(\034TEAM\034)\010\009if humanoid~=nil and humanoid.Parent ~= LastHitCharacter and team and team.Value ~= pellet.TEAM.Value then\010\009\009--[[if startingDamage == damage and game.Players:playerFromCharacter(hit.Parent) == CreatorTag.Value then \010\009\009\009return \010\009\009end\010\009\009tagHumanoid(humanoid)]]\010\009\009humanoid:TakeDamage(damage)\010\009\009LastHitCharacter = humanoid.Parent\010\009\009--[[local hitBindable = humanoid:FindFirstChild('Hit')\010\009\009if hitBindable then\010\009\009\009hitBindable:Invoke(damage, CreatorTag)\010\009\009else\010\009\009\009print(\034Could not find BindableFunction 'Hit'\034)\010\009\009end]]\010\009else\010\009\009--[[if hit.CanCollide == false then return end\010\009\009damage = damage / 1.42\010\009\009if damage < 1 then\010\009\009\009connection:disconnect()\010\009\009\009pellet.Parent = nil\010\009\009end]]\010\009end\010\009if pellet:FindFirstChild(\034IS RAGING\034) then\010\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009Explosion.DestroyJointRadiusPercent = 0\010\009\009Explosion.BlastRadius = 15\010\009\009Explosion.BlastPressure = 1000\010\009\009Explosion.ExplosionType = Enum.ExplosionType.NoCraters\010\009\009Explosion.Position = pellet.Position\010\009\009Explosion.Hit:connect(Explode)\010\009\009Explosion.Parent = Workspace\010\009end\010end\010\010connection = pellet.Touched:connect(onTouched)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23761,class="Script",parent=23677,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalGuiAndAnimations",["ScriptGuid"]="{08C8DC0A-ED2F-4BDB-ADC9-8EBD6DD6A8BA}",["Source"]="local Tool = script.Parent;\010\010local EquipAnim\010local ShootAnim \010\010function OnChanged(property)\010\009if property == 'Enabled' then\010\009\009if EquipAnim then EquipAnim:Stop() end\010\009\009if Tool.Enabled == false then\010\009\009\009ShootAnim:Play(nil,nil,2)\010\009\009end\010\009end\010end\010\010\010\010function onEquippedLocal()\010\009local humanoid = Tool.Parent:FindFirstChild('Humanoid')\010\009--EquipAnim = humanoid:LoadAnimation(Tool.Equip)\010\009ShootAnim = humanoid:LoadAnimation(Tool.Shoot)\010\010\009-- Make sure that the tool is still equiped when we play equip anim\010\009Spawn(function() wait() if Tool:IsDescendantOf(Workspace) then\009--[[EquipAnim:Play()]] end end)\010\010\009Tool.Changed:connect(function(property) OnChanged(property) end)\010end\010\010function onUnequippedLocal()\010\009if ShootAnim then ShootAnim:Stop() end\010end\010\010Tool.Equipped:connect(onEquippedLocal)\010Tool.Unequipped:connect(onUnequippedLocal)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23762,class="Script",parent=23677,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Slingshot",["ScriptGuid"]="{C8D527ED-270F-4025-BED0-DB35C9534E00}",["Source"]="-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010local Tool = script.Parent\010local Handle = WaitForChild(Tool, 'Handle')\010local VELOCITY = 100 -- constant\010local VELOCITY_SQAURED = VELOCITY * VELOCITY\010local VELOCITY_TO_FOURTH = VELOCITY_SQAURED * VELOCITY_SQAURED\010local ASSET_PREFIX = \034http://www.roblox.com/asset/?id=\034\010\010local MyMouse\010\010local SlingShotMeshIds = {Ammo = 94689434, AttachMe = 94689472, Full = 94689497, Handle = 94689515}\010\010local DebrisService = game:GetService('Debris')\010local ContentProvider = Game:GetService(\034ContentProvider\034)\010local Pellet = Instance.new(\034Part\034)\010Pellet.Locked = true\010Pellet.BackSurface = 0\010Pellet.BottomSurface = 0\010Pellet.Transparency = 0.2\010Pellet.FrontSurface = 0\010Pellet.LeftSurface = 0\010Pellet.RightSurface = 0\010Pellet.TopSurface = 0\010Pellet.Shape = (\034Ball\034)\010Pellet.formFactor = \034Custom\034\010Pellet.Size = Vector3.new(1, 1, 1)\010Pellet.BrickColor = BrickColor.new(\034Lime green\034)\010Pellet.Elasticity = 0.01 \010Pellet.Name = \034DeadlyROBUX\034\010--[[local PelletMesh = Instance.new('SpecialMesh')\010PelletMesh.MeshId = ASSET_PREFIX .. SlingShotMeshIds['Ammo']\010PelletMesh.TextureId = ASSET_PREFIX .. 94689543\010PelletMesh.Scale = Vector3.new(1.5, 1.5, 1.5)\010PelletMesh.Name = 'PelletMesh'\010PelletMesh.Parent = Pellet]]\010\010local SlingShotMesh\010\010local EquipSound\010local SlingshotSounds\010\010local PelletCopy\010\010local IsBlingshot= WaitForChild(Tool,'IsBlingshot')\010\010WaitForChild(Tool, 'PelletScript'):clone().Parent = Pellet\010\010function Fire(mouse_pos)\010\010\009if SlingshotSounds then\010\009\009local soundNum = math.random(1, #SlingshotSounds)\010\009\009SlingshotSounds[soundNum]:Play()\010\009end\010\010-- find player's head pos\010\010\009local vCharacter = Tool.Parent\010\009local vPlayer = game.Players:GetPlayerFromCharacter(vCharacter)\010\010\009local head = vCharacter:findFirstChild(\034Head\034)\010\009if head == nil then return end\010\010\009local startPosition = Tool.Handle.Position + Vector3.new(0,0,0)\010\010\009local dir = mouse_pos - startPosition\010\009dir = dir.unit\010\010\009local launch = startPosition + 0 * dir\010\010\009local delta = mouse_pos - launch\010\009\010\009local dy = delta.y\010\009\010\009local new_delta = Vector3.new(delta.x, 0, delta.z)\010\009delta = new_delta\010\010\009local dx = delta.magnitude\010\009local unit_delta = delta.unit\010\009\010\009-- acceleration due to gravity in RBX units\010\009local g = (-9.81 * 20)\010\010\009local theta = computeLaunchAngle( dx, dy, g)\010\010\009local vy = math.sin(theta)\010\009local xz = math.cos(theta)\010\009local vx = unit_delta.x * xz\010\009local vz = unit_delta.z * xz\010\009\010\010\009local missile = Pellet:clone()\010\010\009missile.CFrame = CFrame.new(launch, launch+Vector3.new(vx,vy,vz))\010        \010\009--missile.Position = launch\010\009missile.Velocity = Vector3.new(vx,vy,vz) * VELOCITY +\010\009(CFrame.Angles(math.rad(-180+(math.random()*360)),math.rad(-180+(math.random()*360)),0).lookVector * (math.random()*50))\010\010\009missile.PelletScript.Disabled = false\010\009\010\010\009--[[if IsBlingshot.Value then\010\009\009missile.PelletMesh.MeshId='http://www.roblox.com/asset/?id=98262500'\010\009\009missile.PelletMesh.TextureId='http://www.roblox.com/asset/?id=98259807'\010\009\009missile.PelletMesh.Scale = Vector3.new(3,3,3)\010\009\009local tbling= IsBlingshot:Clone()\010\009\009tbling.Parent=missile\010\009else\010\009\009missile.PelletMesh.Scale = Vector3.new(2,2,2)\010\009end]]\010\010\009--[[local creator_tag = Instance.new(\034ObjectValue\034)\010\009creator_tag.Value = vPlayer\010\009creator_tag.Name = \034creator\034]]\010\009local team = Tool.Parent.TEAM:Clone()\010\009team.Parent = missile\010\009\010\009if Tool.Parent.Rage.Value == true then\010\009\009local rage = Instance.new(\034ObjectValue\034,missile)\010\009\009rage.Name = \034IS RAGING\034\010\009end\010\009\010\009DebrisService:AddItem(missile,2.0)\010\009missile.Parent = game.Workspace\010\010end\010\010\010function computeLaunchAngle(dx,dy,grav)\010\009-- arcane\010\009-- http://en.wikipedia.org/wiki/Trajectory_of_a_projectile\010\009\010\009local g = math.abs(grav)\010\009local inRoot = (VELOCITY_TO_FOURTH) - (g * ((g*dx*dx) + (2*dy*VELOCITY_SQAURED)))\010\009if inRoot <= 0 then\010\009\009return .25 * math.pi\010\009end\010\009local root = math.sqrt(inRoot)\010\009local inATan1 = ((VELOCITY_SQAURED) + root) / (g*dx)\010\010\009local inATan2 = ((VELOCITY_SQAURED) - root) / (g*dx)\010\009local answer1 = math.atan(inATan1)\010\009local answer2 = math.atan(inATan2)\010\009return math.min(answer1,answer2)\010end\010\010\010Tool.Enabled = true\010function OnActivated(targetOverride)\010\009wait(0) --TODO: Remove when Mouse.Hit and Humanoid.TargetPoint update properly on iPad\010\009if not Tool.Enabled then\010\009\009return\010\009end\010\009local character = Tool.Parent;\010\009local humanoid = character:FindFirstChild('Humanoid')\010\009if humanoid == nil or humanoid.Health <= 0 then\010\009\009print(\034Humanoid not found, or not alive\034)\010\009\009return\010\009end\010\010\009Tool.Enabled = false\010\009local targetPos = targetOverride or MyMouse.Hit.p\010\010\009local Projectiles = 10\010\009if Tool.Parent.Rage.Value == true then Projectiles = 3 end\010\010\009for i = 1,Projectiles do\010\009\009Fire(targetPos)\010\009end\010\009if PelletCopy then PelletCopy.Transparency = 1 end\010\009-- swap meshes here\010\009--[[\010\009for i = 0, 0.2, 0.05 do\010\009\009SlingShotMesh.Scale = Vector3.new(0.5, 0.5, 0.5 + i * 8)\010\009\009wait(0.05)\010\009end\010\009SlingShotMesh.Scale = Vector3.new(0.5, 0.5, 0.5)\010\009--]]\010\009wait()\010\009if PelletCopy then PelletCopy.Transparency = 0 end\010\010\009Tool.Enabled = true\010end\010\010Tool.Use.Changed:connect(function()\010\009if Tool.Use.Value == true then\010\009\009OnActivated(Tool.Parent.Target.Value.Position)\010\009\009Tool.Use.Value = false\010\009end\010end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23765,class="Script",parent=23628,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{58807934-F224-46CE-9A0F-1C5097658349}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010local ChanceToUseAbility = 25\010local ChanceToUseAbilityInRageMode = 50\010\010local MinionSpawns = 1\010local MinionSpawnsInRageMode = 2\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Sit = false\010\009end \010end \010\010script.Parent.Humanoid.HealthChanged:connect(function()\010\009if script.Parent.Humanoid.Health < script.Parent.Humanoid.MaxHealth/2 then\010\009\009script.Parent.Rage.Value = true\010\009\009script.Parent.Head.Fire.Enabled = true\010\009\009script.Parent.Head.BrickColor = BrickColor.new(\034Really red\034)\010\009\009script.Parent.Head.Face.Texture = \034http://www.roblox.com/asset/?id=109676489\034\010\009\009script.Parent.Head.Rage:Play()\010\009end\010end)\010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010Animation = script.Parent.Humanoid:LoadAnimation(script.BlastAnim)\010\010local WaitTime = 1\010\010while true do\010\009local CurrentMinionSpawn = MinionSpawns\010\009local CurrentAbilityChance = ChanceToUseAbility\010\009if script.Parent.Rage.Value == true then\010\009\009WaitTime = 0.5\010\009\009CurrentMinionSpawn = MinionSpawnsInRageMode\010\009\009CurrentAbilityChance = ChanceToUseAbilityInRageMode\010\009else\010\009\009WaitTime = 1\010\009end\010\009wait(WaitTime)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = -7.5 + (math.random()*15)\010\009\009ry = 0\010\009\009rz = -7.5 + (math.random()*15)\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 15 then\010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 15 and (target.Position - script.Parent.Torso.Position).magnitude < 75 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 50\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 75 then \010\009\009\009script.Parent.Attack.Value = false\010\009\009\009script.Parent.Humanoid.WalkSpeed = 50\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009\009if script.Parent.Attack.Value == false and math.random()*100 > 37.5 then\010\009\009\009script.Parent.Humanoid.Jump = true\010\009\009end\010\009\009if script.Parent.Attack.Value == true then\010\009\009\009if math.random()*100 < (CurrentAbilityChance) then\010\009\009\009\009local AbilityToUse = math.random(2,3)\010\009\009\009\009--[[if AbilityToUse == 1 then\010\009\009\009\009\009local NumberOfBot = 0\010\009\009\009\009\009for _, WorkspaceBots in pairs(Workspace:GetChildren()) do\010\009\009\009\009\009\009if WorkspaceBots:IsA(\034Model\034) then\010\009\009\009\009\009\009\009local Humanoid = WorkspaceBots:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009\009\009local TEAM = WorkspaceBots:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009\009\009if Humanoid and Humanoid.Health ~= 0 and TEAM and TEAM.Value == BrickColor.new(\034Bright red\034) then\010\009\009\009\009\009\009\009\009NumberOfBot = NumberOfBot + 1\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009\009if NumberOfBot < (Workspace.RobloxiaMaxNPC.Value + 5) then\010\009\009\009\009\009\009local MinionToPick =\010\009\009\009\009\009\009{game.Lighting.RobloxiaBots.Guest,\010\009\009\009\009\009\009game.Lighting.RobloxiaBots[\034Chef Guest\034],\010\009\009\009\009\009\009game.Lighting.RobloxiaBots[\034Baseball Guest\034],\010\009\009\009\009\009\009game.Lighting.RobloxiaBots.Girluest,\010\009\009\009\009\009\009game.Lighting.RARERobloxiaBots[\034GIANT Vikinguest\034],\010\009\009\009\009\009\009game.Lighting.RARERobloxiaBots[\034Witch Guest\034]}\010\009\009\009\009\009\009for i = 1,CurrentMinionSpawn do\010\009\009\009\009\009\009\009local Minion = MinionToPick[math.random(1,#MinionToPick)]:Clone()\010\009\009\009\009\009\009\009Minion.Parent = Workspace\010\009\009\009\009\009\009\009Minion:MakeJoints()\010\009\009\009\009\009\009\009Minion:MoveTo(script.Parent.Torso.Position + Vector3.new(-5+(math.random()*10),0,-5+(math.random()*10)))\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009else]]if AbilityToUse == 2 then\010\009\009\009\009\009if Animation then Animation:Play(nil,nil,2) end\010\009\009\009\009\009wait(0.1)\010\009\009\009\009\009script.Parent.Blast:Play()\010\009\009\009\009\009local Wave = Instance.new(\034Part\034)\010\009\009\009\009\009Wave.Name = \034Wave\034\010\009\009\009\009\009Wave.FormFactor = \034Custom\034\010\009\009\009\009\009Wave.BrickColor = BrickColor.new(\034Lime green\034)\010\009\009\009\009\009Wave.Material = Enum.Material.Neon\010\009\009\009\009\009Wave.Shape = Enum.PartType.Ball\010\009\009\009\009\009Wave.Size = Vector3.new(10,10,10)\010\009\009\009\009\009Wave.Transparency = 0.5\010\009\009\009\009\009Wave.TopSurface = 0\010\009\009\009\009\009Wave.BottomSurface = 0\010\009\009\009\009\009Wave.Position = script.Parent.Torso.Position\010\009\009\009\009\009Wave.Anchored = true\010\009\009\009\009\009Wave.CanCollide = false\010\009\009\009\009\009Wave.Parent = Workspace\010\009\009\009\009\009game.Debris:AddItem(Wave,5)\010\009\009\009\009\009Spawn(function()\010\009\009\009\009\009\009for i = 1,10 do\010\009\009\009\009\009\009\009local CurrentCFrame = Wave.CFrame\010\009\009\009\009\009\009\009Wave.Size = Wave.Size + Vector3.new(10,10,10)\010\009\009\009\009\009\009\009Wave.CFrame = CurrentCFrame\010\009\009\009\009\009\009\009Wave.Transparency = Wave.Transparency + 0.05\010\009\009\009\009\009\009\009game:GetService(\034RunService\034).Stepped:wait()\010\009\009\009\009\009\009end\010\009\009\009\009\009\009if Wave then Wave:Destroy() end\010\009\009\009\009\009end)\010\009\009\009\009\009for _, Child in pairs(Workspace:GetChildren()) do\010\009\009\009\009\009\009if Child:IsA(\034Model\034) then\010\009\009\009\009\009\009\009local Humanoid = Child:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009\009\009local Torso = Child:FindFirstChild(\034Torso\034)\010\009\009\009\009\009\009\009local TEAM = Child:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009\009\009if Humanoid and Humanoid.Health ~= 0 and Torso and (Torso.Position - Wave.Position).magnitude < 75 and TEAM and TEAM.Value ~= script.Parent.TEAM.Value then\010\009\009\009\009\009\009\009\009Torso.Velocity = Torso.Velocity + ((CFrame.new(Torso.Position+Vector3.new(0,-10,0),Torso.Position)).lookVector * math.random(10,25))\010\009\009\009\009\009\009\009\009Humanoid.Sit = true\010\009\009\009\009\009\009\009\009Humanoid:TakeDamage(script.Parent.Rage.Value == true and 750 or 500)\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009elseif AbilityToUse == 3 then\010\009\009\009\009\009script.Parent.Humanoid.WalkSpeed = 0\010\009\009\009\009\009script.Parent.Torso.FartSound:Play()\010\009\009\009\009\009local FartPart = Instance.new(\034Part\034)\010\009\009\009\009\009FartPart.Locked = true\010\009\009\009\009\009FartPart.BackSurface = 0\010\009\009\009\009\009FartPart.BottomSurface = 0\010\009\009\009\009\009FartPart.FrontSurface = 0\010\009\009\009\009\009FartPart.LeftSurface = 0\010\009\009\009\009\009FartPart.RightSurface = 0\010\009\009\009\009\009FartPart.TopSurface = 0\010\009\009\009\009\009FartPart.formFactor = \034Custom\034\010\009\009\009\009\009FartPart.Size = Vector3.new(0,0,0)\010\009\009\009\009\009FartPart.Transparency = 1\010\009\009\009\009\009--FartPart.Shape = \034Ball\034\010\009\009\009\009\009FartPart.CanCollide = false\010\009\009\009\009\009FartPart.Anchored = true\010\009\009\009\009\009FartPart.Position = script.Parent.Torso.Position\010\009\009\009\009\009local Smoke = script.ParticleEmitter:Clone()\010\009\009\009\009\009Smoke.Enabled = true\010\009\009\009\009\009Smoke.Parent = FartPart\010\009\009\009\009\009Delay(30,function()\010\009\009\009\009\009\009Smoke.Enabled = false\010\009\009\009\009\009end)\010\009\009\009\009\009game.Debris:AddItem(FartPart,35)\010\009\009\009\009\009FartPart.Parent = Workspace\010\009\009\009\009\009local NewScript = script.Parent.FartAOEDamage:clone()\010\009\009\009\009\009NewScript.AOEPos.Value = script.Parent.Torso.Position\010\009\009\009\009\009script.Parent.TEAM:Clone().Parent = NewScript\010\009\009\009\009\009NewScript.Disabled = false\010\009\009\009\009\009NewScript.Parent = Workspace\010\009\009\009\009end\010\009\009\009else\010\009\009\009\009script.Parent.Moneybag.Use.Value = true\010\009\009\009end\010\009\009end\010\009else \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=23770,class="Script",parent=23628,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="FartAOEDamage",["ScriptGuid"]="{D5F121E5-C929-4DF0-892F-273758052943}",["Source"]="wait()\010game.Debris:AddItem(script,30)\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010while true do\010\009for _, Child in pairs(Workspace:GetChildren()) do\010\009\009if Child:IsA(\034Model\034) and Child.Name ~= \034Guest 1337\034 then\010\009\009\009Humanoid = Child:FindFirstChild(\034Humanoid\034)\010\009\009\009Torso = Child:FindFirstChild(\034Torso\034)\010\009\009\009TEAM = Child:FindFirstChild(\034TEAM\034)\010\009\009\009if Humanoid and Torso and Humanoid.Health ~= 0 and TEAM and TEAM.Value ~= script.TEAM.Value and (script.AOEPos.Value - Torso.Position).magnitude < 37.5 then\010\009\009\009\009Humanoid:TakeDamage(20)\010\009\009\009elseif Humanoid and Torso and Humanoid.Health ~= 0 and TEAM and TEAM.Value == script.TEAM.Value and (script.AOEPos.Value - Torso.Position).magnitude < 37.5 then --WARNING: Friendly Fire\010\009\009\009\009Humanoid:TakeDamage(0)\010\009\009\009end\010\009\009end\010\009end\010\009wait(0.1)\010end",["SourceAssetId"]=-1,["Tags"]=""}}
