()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25460,class="Script",parent=25415,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="HealthRegenerationScript",["ScriptGuid"]="{3069EC41-18DD-46CA-8BC5-4C17DDAF135C}",["Source"]="-- Renegeration Script for the bot\013\010-- Renegerates about 1% of max hp per second until it reaches max health\013\010bot = script.Parent\013\010Humanoid = bot:FindFirstChild(\034Humanoid\034)\013\010\013\010local regen = false\013\010\013\010function regenerate() \013\010\009if regen then return end\013\010\009-- Lock this function until the regeneration to max health is complete by using a boolean toggle\013\010\009regen = true\013\010\009while Humanoid.Health < Humanoid.MaxHealth do\013\010\009\009local delta = wait(1)\013\010\009\009local health = Humanoid.Health\013\010\009\009if health > 0 and health < Humanoid.MaxHealth then \013\010\009\009\009-- This delta is for regenerating 1% of max hp per second instead of 1 hp per second\013\010\009\009\009delta = 0.01 * delta * Humanoid.MaxHealth\013\010\009\009\009health = health + delta\013\010\009\009\009Humanoid.Health = math.min(health, Humanoid.MaxHealth)\009\009\009\013\010\009\009end\013\010\009end\009\013\010\009-- release the lock, since the health is at max now, and if the character loses health again\013\010\009-- it needs to start regenerating \013\010\009regen = false\013\010end\009\013\010\013\010if Humanoid then \013\010\009-- Better than a while true do loop since it only fires when the health actually changes\013\010\009Humanoid.HealthChanged:connect(regenerate)\009\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25462,class="Script",parent=25461,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="health",["ScriptGuid"]="{F1B72CFA-C231-4639-8E51-B98EABE725ED}",["Source"]="script.Parent.MaxHealth = 20000\010wait(1)\010script.Parent.Health = script.Parent.MaxHealth\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25463,class="Script",parent=25415,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{F12AE8C2-2DDD-438B-9FF0-8A7ED478CEBD}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxasset://sounds/uuhhh.wav\034)\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25465,class="Script",parent=25415,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ZombieScript",["ScriptGuid"]="{B3D675D2-C02F-4878-BFB1-1CBDB0DC95AD}",["Source"]="--Made by Stickmasterluke\010\010--Zombie artificial stupidity script\010\010\010sp=script.Parent\010lastattack=0\010nextrandom=0\010nextsound=0\010nextjump=0\010chasing=false\010\010variance=4\010\010damage=1000\010attackrange=6\010sightrange=999--60\010runspeed=35\010wonderspeed=17\010healthregen=false\010colors={\034Sand red\034,\034Dusty Rose\034,\034Medium blue\034,\034Sand blue\034,\034Lavender\034,\034Earth green\034,\034Brown\034,\034Medium stone grey\034,\034Brick yellow\034}\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function waitForChild(parent,childName)\010\009local child=parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child=parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010-- ANIMATION\010\010-- declarations\010\010local Torso=waitForChild(sp,\034Torso\034)\010local Head=waitForChild(sp,\034Head\034)\010local RightShoulder=waitForChild(Torso,\034Right Shoulder\034)\010local LeftShoulder=waitForChild(Torso,\034Left Shoulder\034)\010local RightHip=waitForChild(Torso,\034Right Hip\034)\010local LeftHip=waitForChild(Torso,\034Left Hip\034)\010local Neck=waitForChild(Torso,\034Neck\034)\010local Humanoid=waitForChild(sp,\034Humanoid\034)\010local BodyColors=waitForChild(sp,\034Body Colors\034)\010local pose=\034Standing\034\010local hitsound=waitForChild(Torso,\034HitSound\034)\010local Anim = Humanoid:LoadAnimation(sp.AttackAnim)\010\010--[[local sounds={\010\009waitForChild(Torso,\034GroanSound\034),\010\009waitForChild(Torso,\034RawrSound\034)\010}]]\010\010if healthregen then\010\009local regenscript=waitForChild(sp,\034HealthRegenerationScript\034)\010\009regenscript.Disabled=false\010end\010Humanoid.WalkSpeed=wonderspeed\010\010local toolAnim=\034None\034\010local toolAnimTime=0\010\010--[[BodyColors.HeadColor=BrickColor.new(\034Grime\034)\010local randomcolor1=colors[math.random(1,#colors)]\010BodyColors.TorsoColor=BrickColor.new(randomcolor1)\010BodyColors.LeftArmColor=BrickColor.new(randomcolor1)\010BodyColors.RightArmColor=BrickColor.new(randomcolor1)\010local randomcolor2=colors[math.random(1,#colors)]\010BodyColors.LeftLegColor=BrickColor.new(randomcolor2)\010BodyColors.RightLegColor=BrickColor.new(randomcolor2)]]\010\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009pose=\034Running\034\010\009else\010\009\009pose=\034Standing\034\010\009end\010end\010function onDied()\010\009pose=\034Dead\034\010end\010function onJumping()\010\009pose=\034Jumping\034\010end\010function onClimbing()\010\009pose=\034Climbing\034\010end\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010function onFreeFall()\010\009pose = \034FreeFall\034\010end\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010function onSeated()\010\009pose = \034Seated\034\010end\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function moveJump()\010\009RightShoulder.MaxVelocity = 0.5\010\009LeftShoulder.MaxVelocity = 0.5\010  RightShoulder.DesiredAngle=3.14\010\009LeftShoulder.DesiredAngle=-3.14\010\009RightHip.DesiredAngle=0\010\009LeftHip.DesiredAngle=0\010end\010\010function moveFreeFall()\010\009RightShoulder.MaxVelocity = 0.5\010\009LeftShoulder.MaxVelocity =0.5\010\009RightShoulder.DesiredAngle=3.14\010\009LeftShoulder.DesiredAngle=-3.14\010\009RightHip.DesiredAngle=0\010\009LeftHip.DesiredAngle=0\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder.DesiredAngle=3.14 /2\010\009LeftShoulder.DesiredAngle=-3.14 /2\010\009RightHip.DesiredAngle=3.14 /2\010\009LeftHip.DesiredAngle=-3.14 /2\010end\010\010function animate(time)\010\009local amplitude\010\009local frequency\010\009if (pose == \034Jumping\034) then\010\009\009moveJump()\010\009\009return\010\009end\010\009if (pose == \034FreeFall\034) then\010\009\009moveFreeFall()\010\009\009return\010\009end\010\009if (pose == \034Seated\034) then\010\009\009moveSit()\010\009\009return\010\009end\010\009local climbFudge = 0\010\009if (pose == \034Running\034) then\010\009\009RightShoulder.MaxVelocity = 0.15\010\009\009LeftShoulder.MaxVelocity = 0.15\010\009\009amplitude = 1\010\009\009frequency = 9\010\009elseif (pose == \034Climbing\034) then\010\009\009RightShoulder.MaxVelocity = 0.5 \010\009\009LeftShoulder.MaxVelocity = 0.5\010\009\009amplitude = 1\010\009\009frequency = 9\010\009\009climbFudge = 3.14\010\009else\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009end\010\009desiredAngle = amplitude * math.sin(time*frequency)\010\009if not chasing and frequency==9 then\010\009\009frequency=4\010\009end\010\009if chasing then\010\009\009--[[RightShoulder.DesiredAngle=math.pi/2\010\009\009LeftShoulder.DesiredAngle=-math.pi/2\010\009\009RightHip.DesiredAngle=-desiredAngle*2\010\009\009LeftHip.DesiredAngle=-desiredAngle*2]]\010\009else\010\009\009RightShoulder.DesiredAngle=desiredAngle + climbFudge\010\009\009LeftShoulder.DesiredAngle=desiredAngle - climbFudge\010\009\009RightHip.DesiredAngle=-desiredAngle\010\009\009LeftHip.DesiredAngle=-desiredAngle\010\009end\010end\010\010\010function attack(time,attackpos)\010\009if time-lastattack>=0.25 then\010\009\009local hit,pos=raycast(Torso.Position,(attackpos-Torso.Position).unit,attackrange)\010\009\009if hit and hit.Parent~=nil then\010\009\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local TEAM=hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h and TEAM and TEAM.Value~=sp.TEAM.Value then\010\009\009\009\009local creator=sp:FindFirstChild(\034creator\034)\010\009\009\009\009if creator then\010\009\009\009\009\009if creator.Value~=nil then\010\009\009\009\009\009\009if creator.Value~=game.Players:GetPlayerFromCharacter(h.Parent) then\010\009\009\009\009\009\009\009for i,oldtag in ipairs(h:GetChildren()) do\010\009\009\009\009\009\009\009\009if oldtag.Name==\034creator\034 then\010\009\009\009\009\009\009\009\009\009oldtag:remove()\010\009\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009creator:clone().Parent=h\010\009\009\009\009\009\009else\010\009\009\009\009\009\009\009return\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009\009if Anim then Anim:Play(nil,nil,1.5) end\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009\009hitsound.Volume=1\010\009\009\009\009hitsound.Pitch=.75+(math.random()*.5)\010\009\009\009\009hitsound:Play()\010\009\009\009\009--[[if RightShoulder and LeftShoulder then\010\009\009\009\009\009RightShoulder.CurrentAngle=0\010\009\009\009\009\009LeftShoulder.CurrentAngle=0\010\009\009\009\009end]]\010\009\009\009end\010\009\009end\010\009\009lastattack=time\010\009end\010end\010\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010\010\010function populatehumanoids(mdl)\010\009if mdl.ClassName==\034Humanoid\034 then\010\009\009if mdl.Parent:FindFirstChild(\034TEAM\034) and mdl.Parent:FindFirstChild(\034TEAM\034).Value~=sp.TEAM.Value then\010\009\009\009table.insert(humanoids,mdl)\010\009\009end\010\009end\010\009for i2,mdl2 in ipairs(mdl:GetChildren()) do\010\009\009populatehumanoids(mdl2)\010\009end\010end\010\010--[[function playsound(time)\010\009nextsound=time+5+(math.random()*5)\010\009local randomsound=sounds[math.random(1,#sounds)]\010\009randomsound.Volume=.5+(.5*math.random())\010\009randomsound.Pitch=.5+(.5*math.random())\010\009randomsound:Play()\010end]]\010\010while sp.Parent~=nil and Humanoid and Humanoid.Parent~=nil and Humanoid.Health>0 and Torso and Head and Torso~=nil and Torso.Parent~=nil do\010\009local _,time=wait(0.25)--wait(1/3)\010\009humanoids={}\010\009populatehumanoids(game.Workspace)\010\009closesttarget=nil\010\009closestdist=sightrange\010\009local creator=sp:FindFirstChild(\034creator\034)\010\009for i,h in ipairs(humanoids) do\010\009\009if h and h.Parent~=nil then\010\009\009\009if h.Health>0 and h.Parent~=sp then\010\009\009\009\009local plr=game.Players:GetPlayerFromCharacter(h.Parent)\010\009\009\009\009if creator==nil or plr==nil or creator.Value~=plr then\010\009\009\009\009\009local t=h.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009if t~=nil then\010\009\009\009\009\009\009local dist=(t.Position-Torso.Position).magnitude\010\009\009\009\009\009\009if dist<closestdist then\010\009\009\009\009\009\009\009closestdist=dist\010\009\009\009\009\009\009\009closesttarget=t\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009if closesttarget~=nil then\010\009\009if not chasing then\010\009\009\009--playsound(time)\010\009\009\009chasing=true\010\009\009\009Humanoid.WalkSpeed=runspeed\010\009\009end\010\009\009Humanoid:MoveTo(closesttarget.Position+(Vector3.new(1,1,1)*(variance*((math.random()*2)-1))),closesttarget)\010\009\009if math.random()<.5 then\010\009\009\009attack(time,closesttarget.Position)\010\009\009end\010\009else\010\009\009if chasing then\010\009\009\009chasing=false\010\009\009\009Humanoid.WalkSpeed=wonderspeed\010\009\009end\010\009\009if time>nextrandom then\010\009\009\009nextrandom=time+3+(math.random()*5)\010\009\009\009local randompos=Torso.Position+((Vector3.new(1,1,1)*math.random()-Vector3.new(.5,.5,.5))*40)\010\009\009\009Humanoid:MoveTo(randompos,game.Workspace.Terrain)\010\009\009end\010\009end\010\009if time>nextsound then\010\009\009--playsound(time)\010\009end\010\009if time>nextjump then\010\009\009nextjump=time+7+(math.random()*5)\010\009\009Humanoid.Jump=true\010\009end\010\009animate(time)\010end\010\010wait(4)\010sp:remove() --Rest In Pizza\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25467,class="Script",parent=25415,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ENERGYBALL",["ScriptGuid"]="{451BDD6E-3351-49C9-954B-8E3118CCD2B5}",["Source"]="function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 100\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\009\009\009\009\009fire = Instance.new(\034Part\034)\010\009\009\009\009\009fire.Parent = game.Workspace\010\009\009\009\009\009fire.CanCollide = false\010\009\009\009\009\009fire.Size = Vector3.new(10,10,10)\010\009\009\009\009\009fire.Transparency = 0.5\010\009\009\009\009\009fire.Anchored = true\010\009\009\009\009\009fire.Shape = \034Ball\034\010\009\009\009\009\009fire.BrickColor = BrickColor.new(\034Light orange\034)\010\009\009\009\009\009fire.CFrame = script.Parent.Torso.CFrame\010\009\009\009\009\009local dir = (temp.Position - script.Parent.Torso.Position).unit\010\009\009\009\009\009local spawnPos = script.Parent.Torso.Position\010\009\009\009\009\009local pos = spawnPos + (dir * 1)\010\009\009\009\009\009fire.CFrame = CFrame.new(pos,  pos + dir)\010\009\009\009\009\009script.Damage:clone().Parent = fire\010\009\009\009\009\009script.Parent.TEAM:Clone().Parent = fire\010\009\009\009\009\009script.Move:clone().Parent = fire\010\009\009\009\009\009local thing = script.Fire:clone()\010\009\009\009\009\009thing.Parent = fire\010\009\009\009\009\009thing.Enabled = true\010\009\009\009\009\009wait(3)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010while true do\010\009wait() \010\009if script.Parent.Humanoid.Health < 1 then\010\009\009script.Parent:remove()\010\009end\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009fire = nil\010\009end\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25468,class="Script",parent=25467,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Move",["ScriptGuid"]="{B2DBA7F3-E292-474C-824C-4B90AAD42E64}",["Source"]="tim = 0\010\010while true do\010\009wait()\010\009tim = tim + 1\010\009script.Parent.CFrame = script.Parent.CFrame * CFrame.new(0,0,-10)\010\009if tim > 100 then\010\009\009script.Parent.Anchored = false\010\009end\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25469,class="Script",parent=25467,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Damage",["ScriptGuid"]="{600AADBE-2B75-4C1A-A897-AC66B6BEFC25}",["Source"]="local TEAM = script.Parent:WaitForChild('TEAM')\010\010function onTouched(hit)\010        local human = hit.Parent:findFirstChild(\034Humanoid\034)\010        if human ~= nil and human.Parent:FindFirstChild(\034TEAM\034) and human.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010                human.Health = human.Health - 100 -- Change the amount to change the damage.\010        end\010end\010script.Parent.Touched:connect(onTouched)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25477,class="Script",parent=25471,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="DualHandle",["ScriptGuid"]="{2E86A866-B571-477A-9B6D-EFF30310A346}",["Source"]="wait()\010local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Grip2\010\010local Handle2 = Handle:Clone()\010Handle2.Name = \034Handle2\034\010Handle2.Parent = Tool\010\010function Equipped()\010\009Handle2.CanCollide = false\010\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009if RightArm then\010\009\009local Grip = RightArm:FindFirstChild(\034RightGrip\034)\010\009\009if Grip then\010\009\009\009Grip2 = Grip:Clone()\010\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009Grip2.Part0 = LeftArm\010\009\009\009Grip2.Part1 = Handle2\010\009\009\009Grip2.Parent = LeftArm\010\009\009end\010\009end\010end\010\010function Unequipped()\010\009Handle2.CanCollide = true\010\009if Grip2 then Grip2:Destroy() end\010end\010\010Tool.Equipped:connect(Equipped)\010Tool.Unequipped:connect(Unequipped)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25482,class="Script",parent=25471,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{7071CE28-A9DC-4EFD-9DB5-7BFDA6E44D5F}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010\010\010firerate=0.1\010range=950\010power=300\010rate=1/30\010spinuptime=0\010barreloffset=Vector3.new(0,0.75,.5)\010windvec=Vector3.new(2,-1,1).unit\010firetime=0\010maxammo=30\010reloadtime = 2.75\010ammo=maxammo\010\010debris=game:GetService(\034Debris\034)\010equipped=false\010check=true\010firing=false\010reloading=false\010fireanimdelay=0\010handle=sp:WaitForChild(\034Handle\034)\010handle2=sp:WaitForChild(\034Handle2\034)\010handles = {handle,handle2}\010handlestofire = 1\010anim = sp.Parent.Humanoid:LoadAnimation(sp.idle)\010anim2 = sp.Parent.Humanoid:LoadAnimation(sp.FireAni)\010anim3 = sp.Parent.Humanoid:LoadAnimation(sp.Reload)\010fireanimloop = false\010\010Spawn(function()\010\009while true do\010\009\009fireanimdelay = fireanimdelay - game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009if fireanimdelay <= 0 then\010\009\009\009fireanimdelay = 0\010\009\009\009if anim2 and fireanimloop then anim2:Stop() fireanimloop = false end\010\009\009end\010\009\009wait()\010\009end\010end)\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function waitfor(parent,name)\010\009while parent:FindFirstChild(name)==nil do\010\009\009wait()\010\009end\010\009return parent:FindFirstChild(name)\010end\010\010function checkintangible(hit)\010\009if hit and hit~=nil then\010\009\009if hit:IsDescendantOf(sp.Parent) or hit.Transparency>.8 or hit.Name==\034Handle\034 or hit.Name==\034Effect\034 or hit.Name==\034Bullet\034 or hit.Name==\034Laser\034 or string.lower(hit.Name)==\034water\034 or hit.Name==\034Rail\034 or hit.Name==\034Arrow\034 then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function castray(startpos,vec,length,ignore,delayifhit)\010\009local hit,endpos2=game.Workspace:FindPartOnRay(Ray.new(startpos,vec*length),ignore)\010\009if hit~=nil then\010\009\009if checkintangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit,endpos2=castray(endpos2+(vec*.01),vec,length-((startpos-endpos2).magnitude),ignore,delayifhit)\010\009\009end\010\009end\010\009return hit,endpos2\010end\010\010function drawbeam(beamstart,beamend,clr,fadedelay)\010\009local dist=(beamstart-beamend).magnitude\010\009local laser=Instance.new(\034Part\034)\010\009laser.Name=\034Effect\034\010\009laser.Anchored=true\010\009laser.CanCollide=false\010\009laser.Shape=\034Block\034\010\009laser.formFactor=\034Custom\034\010\009laser.Size=Vector3.new(.2,.2,.2)\010\009laser.Transparency=0\010\009laser.Material=Enum.Material.Plastic\010\009laser.Locked=true\010\009laser.TopSurface=0\010\009laser.BottomSurface=0\010\009laser.BrickColor=clr\010\009laser.CFrame=CFrame.new(beamend,beamstart)*CFrame.new(0,0,-dist/2)*CFrame.Angles(math.pi/2,0,0)\010\009local m=Instance.new(\034SpecialMesh\034)\010\009m.Scale=Vector3.new(1,dist*5,1)\010\009m.MeshType=\034Brick\034\010\009m.Parent=laser\010\009debris:AddItem(laser,fadedelay*0.5)\010\009laser.Parent=game.Workspace\010\010\009--[[local frames=math.floor(fadedelay/rate)\010\009for frame=1,frames do\010\009\009wait(rate)\010\009\009local percent=frame/frames\010\009\009laser.CFrame=laser.CFrame+windvec*rate\010\009\009laser.Transparency=.5+(percent*.5)\010\009end]]\010\009wait(.5)\010\009laser:remove()\010end\010\010function fire()\010\009local hu=sp.Parent:FindFirstChild(\034Humanoid\034)\010\009local he=sp.Parent:FindFirstChild(\034Head\034)\010\009local t=sp.Parent:FindFirstChild(\034Torso\034)\010\009local team=sp.Parent:FindFirstChild(\034TEAM\034)\010\009if handlestofire == 1 then handlestofire = 2 elseif handlestofire == 2 then handlestofire = 1 end\010\009if hu and team and hu.Health>0 and t and he and equipped then\010\010\009\009if anim2 and not fireanimloop then anim2:Play() anim2:AdjustSpeed(5) fireanimloop = true end\010\009\009fireanimdelay = 0.5\010\009\009local startpos=he.Position\010\009\009local fakestartpos=(handles[handlestofire].CFrame*CFrame.new(barreloffset)).p\010\009\009local vec=(sp.Parent.Target.Value.Position-startpos).unit + (Vector3.new(math.random(-1000,1000),math.random(-1000,1000),math.random(-1000,1000)) / (1500*30))\010\010\009\009local p=Instance.new(\034Part\034)\010\009\009p.Name=\034Effect\034\010\009\009p.BrickColor=BrickColor.new(\034Black\034)\010\009\009p.CanCollide=false\010\009\009p.TopSurface=\034Smooth\034\010\009\009p.BottomSurface=\034Smooth\034\010\009\009p.formFactor=\034Custom\034\010\009\009p.Size=Vector3.new(0,0,0)\010\009\009p.Transparency=1\010\009\009local m=Instance.new(\034SpecialMesh\034)\010\009\009m.Parent=p\010\010\009\009local hit,endpos=castray(startpos,vec,range,sp.Parent,false)\010\009\009local fakevec=(endpos-fakestartpos).unit\010\009\009if hit~=nil then\010\009\009\009local newcf=CFrame.new(endpos,endpos+fakevec)*CFrame.Angles(math.pi/2,0,0)*CFrame.new(0,0,0)\010\009\009\009p.CFrame=newcf\010\009\009\009local w=Instance.new(\034Weld\034)\010\009\009\009w.Part0=hit\010\009\009\009w.Part1=p\010\009\009\009w.C0=hit.CFrame:inverse()*newcf\010\009\009\009w.C1=newcf:inverse()*newcf\010\009\009\009w.Parent=p\010\010\009\009\009--[[local c=Instance.new(\034ObjectValue\034)\010\009\009\009c.Name=\034creator\034\010\009\009\009c.Value=game.Players.LocalPlayer\010\009\009\009c.Parent=p]]\010\009\009\009\010\009\009\009team:clone().Parent=p\010\010\009\009\009local s=script.Script:clone()\010\009\009\009s.Parent=p\010\009\009\009s.Disabled=false\010\009\009else\010\009\009\009p.CFrame=CFrame.new(endpos,endpos+fakevec)\010\009\009\009p.Velocity=fakevec*power\010\009\009\009p.Parent=game.Workspace\010\009\009end\010\010\009\009debris:AddItem(p,1)\010\009\009p.Parent=game.Workspace\010\010\009\009delay(0,function()\010\009\009\009drawbeam(fakestartpos,endpos,BrickColor.new(\034Bright yellow\034),.1)\010\009\009end)\010\010\009\009local sound=handles[handlestofire]:FindFirstChild(\034Fire\034)\010\009\009if sound~=nil then\010\009\009\009--sound:Stop()\010\009\009\009sound:Play()\010\009\009end\010\010\009\009local shoulder=t:FindFirstChild(\034Right Shoulder\034)\010\009\009if shoulder~=nil then\010\009\009\009shoulder.CurrentAngle=(math.pi/2)+.1\010\009\009end\010\009end\010end\010\010function onEquipped(mouse)\010\009equipped=true\010\009anim = sp.Parent.Humanoid:LoadAnimation(sp.idle)\010\009if anim then anim:Play() end\010\009--[[if mouse~=nil then\010\009\009themouse=mouse\010\009\009mouse.Icon=\034rbxasset://textures\092\092GunCursor.png\034\010\009\009mouse.Button1Down:connect(function()\010\009\009\009mouse.Icon=\034rbxasset://textures\092\092GunWaitCursor.png\034\010\009\009\009firetime=tick()+spinuptime\010\009\009\009down=true\010\009\009end)\010\009\009mouse.Button1Up:connect(function()\010\009\009\009down=false\010\009\009\009mouse.Icon=\034rbxasset://textures\092\092GunCursor.png\034\010\009\009end)\010\009end]]\010end\010\010function Reload()\010\009anim3 = sp.Parent.Humanoid:LoadAnimation(sp.Reload)\010\009if anim3 then anim3:Play() anim3:AdjustSpeed(2.5) end\010\009local sound=handles[handlestofire]:FindFirstChild(\034Reload\034)\010\009if sound~=nil then\010\009\009sound:Play()\010\009end\010\009wait(reloadtime)\010\009ammo = maxammo\010end\010\010function onUnequipped()\010\009if anim then anim:Stop() end\010\009equipped=false\010\009themouse=nil\010end\010\010sp.Equipped:connect(onEquipped)\010sp.Unequipped:connect(onUnequipped)\010\010while true do\010\009if sp.Parent.Attack.Value == true then\010\009\009if ammo > 0 then\010\009\009\009ammo = ammo - 1\010\009\009\009fire()\010\009\009\009wait(firerate)\010\009\009else\010\009\009\009Reload()\010\009\009end\010\009else\010\009\009wait()\010\009end\010end\010\010\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25483,class="Script",parent=25482,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{06151E7A-3E37-45DF-B32E-4E07B8447A73}",["Source"]="--Stickmasterluke\010\010\010sp=script.Parent\010\010damage=8--15\010\010wait()\010\010local weld=sp:FindFirstChild(\034Weld\034)\010if weld~=nil then\010\009if weld.Part0~=nil then\010\009\009hit=weld.Part0\010\009\009local sound=sp:FindFirstChild(\034Sound\034)\010\009\009if sound~=nil then\010\009\009\009sound:Play()\010\009\009end\010\009\009if hit.Name~=\034Handle\034 and hit.Name~=\034Effect\034 then\010\009\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local t=hit.Parent:FindFirstChild(\034Torso\034)\010\009\009\009local team=hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h~=nil and t~=nil and h.Health>0 and team~=nil and team.Value~=sp.TEAM.Value then\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009end\010\009\009end\010\009end\010end\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25500,class="Script",parent=25415,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="CarrierScript",["ScriptGuid"]="{5222A8E4-B344-4C4A-BA23-2803DF1FE66E}",["Source"]="sp = script.Parent\010minion = game.Lighting.Allies[\034Doge Sworder\034]:clone()\010\010--[[Setting]]--\010SpawnTime = 60\010NumberOfMinion = 1\010SpawnTimePerMinion = 0\010---------------\010\010sp.Minion.Value = minion\010--minion.Parent = game.Lighting\010--sp[\034Drone\034]:remove()\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010while true do\010\009wait(SpawnTime)\010\009\009for i = 1,NumberOfMinion do\010\009\009\009minion2 = minion:clone()\010\009\009\009minion2.Parent = Workspace\010\009\009\009minion2:MoveTo(sp.Torso.Position+Vector3.new(0,5,0))\010\009\009\009minion2[\034Humanoid\034].Jump = true\010\009\009\009wait(SpawnTimePerMinion)\010\009\009end\010\009end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25502,class="Script",parent=25415,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="FF",["ScriptGuid"]="{EA6B90C3-12EE-444C-895C-98FB3BC78DFE}",["Source"]="ff = Instance.new(\034ForceField\034)\010ff.Parent = script.Parent\010wait(1)\010ff:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25521,class="Script",parent=25504,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{55C14660-6A53-44FD-BF0E-018F5E8A102E}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25539,class="Script",parent=25504,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="HealthRegenerationScript",["ScriptGuid"]="{7F281702-22BD-4735-AF64-4D51E8196E54}",["Source"]="-- Renegeration Script for the bot\013\010-- Renegerates about 1% of max hp per second until it reaches max health\013\010bot = script.Parent\013\010Humanoid = bot:FindFirstChild(\034Humanoid\034)\013\010\013\010local regen = false\013\010\013\010function regenerate() \013\010\009if regen then return end\013\010\009-- Lock this function until the regeneration to max health is complete by using a boolean toggle\013\010\009regen = true\013\010\009while Humanoid.Health < Humanoid.MaxHealth do\013\010\009\009local delta = wait(1)\013\010\009\009local health = Humanoid.Health\013\010\009\009if health > 0 and health < Humanoid.MaxHealth then \013\010\009\009\009-- This delta is for regenerating 1% of max hp per second instead of 1 hp per second\013\010\009\009\009delta = 0.01 * delta * Humanoid.MaxHealth\013\010\009\009\009health = health + delta\013\010\009\009\009Humanoid.Health = math.min(health, Humanoid.MaxHealth)\009\009\009\013\010\009\009end\013\010\009end\009\013\010\009-- release the lock, since the health is at max now, and if the character loses health again\013\010\009-- it needs to start regenerating \013\010\009regen = false\013\010end\009\013\010\013\010if Humanoid then \013\010\009-- Better than a while true do loop since it only fires when the health actually changes\013\010\009Humanoid.HealthChanged:connect(regenerate)\009\013\010end\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25543,class="Script",parent=25504,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ZombieScript",["ScriptGuid"]="{6C329FCD-C217-4F43-AD22-4215D38F875D}",["Source"]="--Made by Stickmasterluke\010\010--Zombie artificial stupidity script\010\010\010sp=script.Parent\010lastattack=0\010nextrandom=0\010nextsound=0\010nextjump=0\010chasing=false\010\010variance=4\010\010damage=40\010attackrange=7.6\010sightrange=999999999999999999--60\010runspeed=50\010wonderspeed=8\010healthregen=false\010colors={\034Sand red\034,\034Dusty Rose\034,\034Medium blue\034,\034Sand blue\034,\034Lavender\034,\034Earth green\034,\034Brown\034,\034Medium stone grey\034,\034Brick yellow\034}\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function waitForChild(parent,childName)\010\009local child=parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child=parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010-- ANIMATION\010\010-- declarations\010\010local Torso=waitForChild(sp,\034Torso\034)\010local Head=waitForChild(sp,\034Head\034)\010local RightShoulder=waitForChild(Torso,\034Right Shoulder\034)\010local LeftShoulder=waitForChild(Torso,\034Left Shoulder\034)\010local RightHip=waitForChild(Torso,\034Right Hip\034)\010local LeftHip=waitForChild(Torso,\034Left Hip\034)\010local Neck=waitForChild(Torso,\034Neck\034)\010local Humanoid=waitForChild(sp,\034Humanoid\034)\010local BodyColors=waitForChild(sp,\034Body Colors\034)\010local pose=\034Standing\034\010local hitsound=waitForChild(Torso,\034HitSound\034)\010local Anim = Humanoid:LoadAnimation(sp.AttackAnim)\010\010--[[local sounds={\010\009waitForChild(Torso,\034GroanSound\034),\010\009waitForChild(Torso,\034RawrSound\034)\010}]]\010\010if healthregen then\010\009local regenscript=waitForChild(sp,\034HealthRegenerationScript\034)\010\009regenscript.Disabled=false\010end\010Humanoid.WalkSpeed=wonderspeed\010\010local toolAnim=\034None\034\010local toolAnimTime=0\010\010--[[BodyColors.HeadColor=BrickColor.new(\034Grime\034)\010local randomcolor1=colors[math.random(1,#colors)]\010BodyColors.TorsoColor=BrickColor.new(randomcolor1)\010BodyColors.LeftArmColor=BrickColor.new(randomcolor1)\010BodyColors.RightArmColor=BrickColor.new(randomcolor1)\010local randomcolor2=colors[math.random(1,#colors)]\010BodyColors.LeftLegColor=BrickColor.new(randomcolor2)\010BodyColors.RightLegColor=BrickColor.new(randomcolor2)]]\010\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009pose=\034Running\034\010\009else\010\009\009pose=\034Standing\034\010\009end\010end\010function onDied()\010\009pose=\034Dead\034\010end\010function onJumping()\010\009pose=\034Jumping\034\010end\010function onClimbing()\010\009pose=\034Climbing\034\010end\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010function onFreeFall()\010\009pose = \034FreeFall\034\010end\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010function onSeated()\010\009pose = \034Seated\034\010end\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function moveJump()\010\009RightShoulder.MaxVelocity = 0.5\010\009LeftShoulder.MaxVelocity = 0.5\010  RightShoulder.DesiredAngle=3.14\010\009LeftShoulder.DesiredAngle=-3.14\010\009RightHip.DesiredAngle=0\010\009LeftHip.DesiredAngle=0\010end\010\010function moveFreeFall()\010\009RightShoulder.MaxVelocity = 0.5\010\009LeftShoulder.MaxVelocity =0.5\010\009RightShoulder.DesiredAngle=3.14\010\009LeftShoulder.DesiredAngle=-3.14\010\009RightHip.DesiredAngle=0\010\009LeftHip.DesiredAngle=0\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder.DesiredAngle=3.14 /2\010\009LeftShoulder.DesiredAngle=-3.14 /2\010\009RightHip.DesiredAngle=3.14 /2\010\009LeftHip.DesiredAngle=-3.14 /2\010end\010\010function animate(time)\010\009local amplitude\010\009local frequency\010\009if (pose == \034Jumping\034) then\010\009\009moveJump()\010\009\009return\010\009end\010\009if (pose == \034FreeFall\034) then\010\009\009moveFreeFall()\010\009\009return\010\009end\010\009if (pose == \034Seated\034) then\010\009\009moveSit()\010\009\009return\010\009end\010\009local climbFudge = 0\010\009if (pose == \034Running\034) then\010\009\009RightShoulder.MaxVelocity = 0.15\010\009\009LeftShoulder.MaxVelocity = 0.15\010\009\009amplitude = 1\010\009\009frequency = 9\010\009elseif (pose == \034Climbing\034) then\010\009\009RightShoulder.MaxVelocity = 0.5 \010\009\009LeftShoulder.MaxVelocity = 0.5\010\009\009amplitude = 1\010\009\009frequency = 9\010\009\009climbFudge = 3.14\010\009else\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009end\010\009desiredAngle = amplitude * math.sin(time*frequency)\010\009if not chasing and frequency==9 then\010\009\009frequency=4\010\009end\010\009if chasing then\010\009\009--[[RightShoulder.DesiredAngle=math.pi/2\010\009\009LeftShoulder.DesiredAngle=-math.pi/2\010\009\009RightHip.DesiredAngle=-desiredAngle*2\010\009\009LeftHip.DesiredAngle=-desiredAngle*2]]\010\009else\010\009\009RightShoulder.DesiredAngle=desiredAngle + climbFudge\010\009\009LeftShoulder.DesiredAngle=desiredAngle - climbFudge\010\009\009RightHip.DesiredAngle=-desiredAngle\010\009\009LeftHip.DesiredAngle=-desiredAngle\010\009end\010end\010\010\010function attack(time,attackpos)\010\009if time-lastattack>=0.25 then\010\009\009local hit,pos=raycast(Torso.Position,(attackpos-Torso.Position).unit,attackrange)\010\009\009if hit and hit.Parent~=nil then\010\009\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local TEAM=hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h and TEAM and TEAM.Value~=sp.TEAM.Value then\010\009\009\009\009local creator=sp:FindFirstChild(\034creator\034)\010\009\009\009\009if creator then\010\009\009\009\009\009if creator.Value~=nil then\010\009\009\009\009\009\009if creator.Value~=game.Players:GetPlayerFromCharacter(h.Parent) then\010\009\009\009\009\009\009\009for i,oldtag in ipairs(h:GetChildren()) do\010\009\009\009\009\009\009\009\009if oldtag.Name==\034creator\034 then\010\009\009\009\009\009\009\009\009\009oldtag:remove()\010\009\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009\009creator:clone().Parent=h\010\009\009\009\009\009\009else\010\009\009\009\009\009\009\009return\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009\009if Anim then Anim:Play(nil,nil,1.5) end\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009\009hitsound.Volume=1\010\009\009\009\009hitsound.Pitch=.75+(math.random()*.5)\010\009\009\009\009hitsound:Play()\010\009\009\009\009--[[if RightShoulder and LeftShoulder then\010\009\009\009\009\009RightShoulder.CurrentAngle=0\010\009\009\009\009\009LeftShoulder.CurrentAngle=0\010\009\009\009\009end]]\010\009\009\009end\010\009\009end\010\009\009lastattack=time\010\009end\010end\010\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010\010\010function populatehumanoids(mdl)\010\009if mdl.ClassName==\034Humanoid\034 then\010\009\009if mdl.Parent:FindFirstChild(\034TEAM\034) and mdl.Parent:FindFirstChild(\034TEAM\034).Value~=sp.TEAM.Value then\010\009\009\009table.insert(humanoids,mdl)\010\009\009end\010\009end\010\009for i2,mdl2 in ipairs(mdl:GetChildren()) do\010\009\009populatehumanoids(mdl2)\010\009end\010end\010\010--[[function playsound(time)\010\009nextsound=time+5+(math.random()*5)\010\009local randomsound=sounds[math.random(1,#sounds)]\010\009randomsound.Volume=.5+(.5*math.random())\010\009randomsound.Pitch=.5+(.5*math.random())\010\009randomsound:Play()\010end]]\010\010while sp.Parent~=nil and Humanoid and Humanoid.Parent~=nil and Humanoid.Health>0 and Torso and Head and Torso~=nil and Torso.Parent~=nil do\010\009local _,time=wait(0.25)--wait(1/3)\010\009humanoids={}\010\009populatehumanoids(game.Workspace)\010\009closesttarget=nil\010\009closestdist=sightrange\010\009local creator=sp:FindFirstChild(\034creator\034)\010\009for i,h in ipairs(humanoids) do\010\009\009if h and h.Parent~=nil then\010\009\009\009if h.Health>0 and h.Parent~=sp then\010\009\009\009\009local plr=game.Players:GetPlayerFromCharacter(h.Parent)\010\009\009\009\009if creator==nil or plr==nil or creator.Value~=plr then\010\009\009\009\009\009local t=h.Parent:FindFirstChild(\034Torso\034)\010\009\009\009\009\009if t~=nil then\010\009\009\009\009\009\009local dist=(t.Position-Torso.Position).magnitude\010\009\009\009\009\009\009if dist<closestdist then\010\009\009\009\009\009\009\009closestdist=dist\010\009\009\009\009\009\009\009closesttarget=t\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009if closesttarget~=nil then\010\009\009if not chasing then\010\009\009\009--playsound(time)\010\009\009\009chasing=true\010\009\009\009Humanoid.WalkSpeed=runspeed\010\009\009end\010\009\009Humanoid:MoveTo(closesttarget.Position+(Vector3.new(1,1,1)*(variance*((math.random()*2)-1))),closesttarget)\010\009\009if math.random()<.5 then\010\009\009\009attack(time,closesttarget.Position)\010\009\009end\010\009else\010\009\009if chasing then\010\009\009\009chasing=false\010\009\009\009Humanoid.WalkSpeed=wonderspeed\010\009\009end\010\009\009if time>nextrandom then\010\009\009\009nextrandom=time+3+(math.random()*5)\010\009\009\009local randompos=Torso.Position+((Vector3.new(1,1,1)*math.random()-Vector3.new(.5,.5,.5))*40)\010\009\009\009Humanoid:MoveTo(randompos,game.Workspace.Terrain)\010\009\009end\010\009end\010\009if time>nextsound then\010\009\009--playsound(time)\010\009end\010\009if time>nextjump then\010\009\009nextjump=time+7+(math.random()*5)\010\009\009Humanoid.Jump=true\010\009end\010\009animate(time)\010end\010\010wait(4)\010sp:remove() --Rest In Pizza\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25544,class="Script",parent=25504,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Anti-Sit Script",["ScriptGuid"]="{249552AF-5D5D-48B6-9DC7-D52346F19626}",["Source"]="script.Parent.Humanoid.Changed:connect(function()\013\010script.Parent.Humanoid.Sit = false\013\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25547,class="Script",parent=25504,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{7F06BC08-F45B-4349-82EF-B14721B1E092}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxassetid://213632774\034)\010sDied.Parent = script.Parent\010sDied.Pitch = 1.3\010sDied.Volume = 1\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25885,class="Script",parent=25872,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Firescript",["ScriptGuid"]="{C218F3CF-37C6-4E0F-82A9-413D66A03EF0}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010check=true\010\010gundamage=10\009\009\009\009\009\009\009\009--Base output damage per shot.\010firerate=.1\009\009\009\009\009\009\009\009--How often the weapon can fire.\010automatic=true\009\009\009\009\009\009\009--hold down to continue firing\010range=1000\009\009\009\009\009\009\009\009\009--Max distance that the weapon can fire.\010spread=2\009\009\009\009\009\009\009\009\009\009--The bigger the spread, the more inaccurate the shots will be.\010clipsize=math.huge\009\009\009\009\009\009\009\009--Shots in a clip\010reloadtime=3\009\009\009\009\009\009\009\009--Time it takes to reload the tool.\010startingclips=10\009\009\009\009\009\009\009--If you want infinit clips, remove the IntValue named \034Clips\034 from the tool.\010segmentlength=25\009\009\009\009\009\009\009--How long the shot segments are, or the speed of the shot.\010fadedelaytime=1/30\010\010\010barrelpos=CFrame.new(0,0,-2.7)\009\009--R,U,B\010rate=1/100\010intangibles={\034Shock\034,\034Bolt\034,\034Bullet\034,\034Plasma\034,\034Effect\034,\034Laser\034,\034Handle\034,\034Effects\034,\034Effect\034,\034Flash\034}\010colors={BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034)}\010flashcolors={\034Bright yellow\034}\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010reloading=false\010local debris=game:GetService(\034Debris\034)\010\010local ammo=sp:FindFirstChild(\034Ammo\034)\010if ammo~=nil then\010\009ammo.Value=clipsize\010end\010local clips=sp:FindFirstChild(\034Clips\034)\010if clips~=nil then\010\009clips.Value=startingclips\010end\010\010sp.Equipped:connect(function()\010\009sp.Parent.Arm2.Fire:Stop()\010\009sp.Parent.Arm2.Reload:Stop()\010end)\010sp.Unequipped:connect(function()\010\009sp.Parent.Arm2.Fire:Stop()\010\009sp.Parent.Arm2.Reload:Stop()\010end)\010\010function round(number,decimal)\010\009decimal=decimal or 0\010\009local mult=10^decimal\010\009return math.floor(number*mult+.5)/mult\010end\010\010function checkintangible(t)\010\009for i3,v3 in ipairs(intangibles) do\010\009\009if string.lower(v3)==string.lower(t.Name) or t.Transparency==1 then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function reload()\010\009reloading=true\010\009sp.Reloading.Value=true\010\009if clips~=nil then\010\009\009if clips.Value>0 then\010\009\009\009clips.Value=clips.Value-1\010\009\009else\010\009\009\009reloading=false\010\009\009\009sp.Reloading.Value=false\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Arm2.Reload:Play()\010\009for i=1,clipsize do\010\009\009wait(reloadtime/clipsize)\010\009\009ammo.Value=i\010\009end\010\009reloading=false\010\009sp.Reloading.Value=false\010end\010\010function castray(startpos,vec,length,ignore,delayifhit)\010\009if length>999 then\010\009\009length=999\010\009end\010\009hit,endpos2=game.Workspace:FindPartOnRay(Ray.new(startpos,vec*length),ignore)\010\009if hit~=nil then\010\009\009if checkintangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit,endpos2=castray(endpos2+(vec*.01),vec,length-((startpos-endpos2).magnitude),ignore,delayifhit)\010\009\009end\010\009end\010\009return hit,endpos2\010end\010\010function sendbullet(boltstart,targetpos,fuzzyness,segmentlength,ignore,clr,damage,fadedelay)\010\009if ammo~=nil then\010\009\009if ammo.Value>0 then\010\009\009\009ammo.Value=ammo.Value-1\010\009\009else\010\009\009\009reload()\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Arm2.Fire:Play()\010\009muzzleeffect()\010\009local t=sp.Parent:FindFirstChild(\034Torso\034)\010\009if t~=nil then\010\009\009local shoulder=t:FindFirstChild(\034Right Shoulder\034)\010\009\009if shoulder~=nil then\010\009\009\009shoulder.CurrentAngle=2\010\009\009end\010\009end\010\010\009local boltdist=range\010\009local clickdist=(boltstart-targetpos).magnitude\010\009local targetpos=targetpos+(Vector3.new(math.random()-.5,math.random()-.5,math.random()-.5)*(clickdist/100)*fuzzyness)\010\009local boltvec=(targetpos-boltstart).unit\010\009local totalsegments=math.ceil(boltdist/segmentlength)\010\009local lastpos=boltstart\010\009for i=1,totalsegments do\010\009\009local newpos=(boltstart+(boltvec*(boltdist*(i/totalsegments))))\010\009\009local segvec=(newpos-lastpos).unit\010\009\009local boltlength=(newpos-lastpos).magnitude\010\009\009local bolthit,endpos=castray(lastpos,segvec,boltlength,ignore,false)\010\009\009drawbeam(lastpos,endpos,clr,fadedelay)\010\009\009if bolthit~=nil then\010\009\009\009local h=bolthit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local t=bolthit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h~=nil and t and t.Value ~= sp.Parent.TEAM.Value then\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009end\010\009\009\009break\010\009\009end\010\009\009lastpos=endpos\010\009\009wait(rate)\010\009end\010end\010\010function drawbeam(beamstart,beamend,clr,fadedelay)\010\009local dis=(beamstart-beamend).magnitude\010\009local laser=Instance.new(\034Part\034)\010\009laser.Name=\034Bullet\034\010\009laser.Transparency = 0\010\009laser.Anchored=true\010\009laser.CanCollide=false\010\009laser.Shape=\034Block\034\010\009laser.formFactor=\034Custom\034\010\009laser.Size=Vector3.new(.375,.375,dis+.2)\010\009laser.Material=Enum.Material.Plastic\010\009laser.Locked=true\010\009laser.TopSurface=0\010\009laser.BottomSurface=0\010\009laser.BrickColor=clr\010\009laser.CFrame=CFrame.new(beamend,beamstart)*CFrame.new(0,0,-dis/2)\010\009--[[local mesh = Instance.new(\034BlockMesh\034,laser)\010\009mesh.Scale = Vector3.new(10,0,1)\010\009local decal = Instance.new(\034Decal\034,laser)\010\009decal.Face = \034Top\034\010\009decal.Texture = \034rbxassetid://201063866\034\010\009decal.Transparency = 0.25\010\009local decal2 = decal:Clone()\010\009decal2.Face = \034Bottom\034\010\009decal2.Parent = decal.Parent]]\010\009local light = script.SurfaceLight:Clone()\010\009light.Enabled = true\010\009light.Face = \034Top\034\010\009light.Parent = laser\010\009local light2 = script.SurfaceLight:Clone()\010\009light2.Enabled = true\010\009light.Face = \034Bottom\034\010\009light2.Parent = laser\010\009laser.Parent=game.Workspace\010\009debris:AddItem(laser,fadedelay)\010end\010\010function muzzleeffect()\010\009local flash=Instance.new(\034Part\034)\010\009flash.Name=\034Effect\034\010\009flash.Anchored=true\010\009flash.CanCollide=false\010\009flash.Shape=\034Block\034\010\009flash.formFactor=\034Custom\034\010\009flash.Size=Vector3.new(.2,.2,.2)\010\009flash.Material=Enum.Material.Plastic\010\009flash.Locked=true\010\009flash.TopSurface=0\010\009flash.BottomSurface=0\010\009flash.BrickColor=BrickColor.new(flashcolors[math.random(1,#flashcolors)])\010\009local mesh=Instance.new(\034SpecialMesh\034)\010\009mesh.MeshId=\034http://www.roblox.com/asset/?id=25212400\034\010\009local scale=Vector3.new(.2+(math.random()*.1),.4+(math.random()*.4),.2+(math.random()*.1))\010\009mesh.Scale=scale\010\009mesh.Parent=flash\010\009flash.CFrame=sp.Parent.Arm2.CFrame*barrelpos*CFrame.Angles(0,math.pi*2*math.random(),0)*CFrame.new(0,scale.y*.9,0)\010\009debris:AddItem(flash,rate)\010\009flash.Parent=game.Workspace\010end\010\010sp.Down.Changed:connect(function()\010\009while sp.Down.Value and check and not reloading do\010\009\009check=false\010\009\009local humanoid=sp.Parent:FindFirstChild(\034Humanoid\034)\010\009\009if humanoid~=nil then\010\009\009\009if humanoid.Health>0 then\010\009\009\009\009spos1=(sp.Parent.Arm2.CFrame*barrelpos).p\010\009\009\009\009delay(0,function() sendbullet(spos1,sp.Aim.Value,spread,segmentlength,sp.Parent,colors[1],gundamage,fadedelaytime) end)\010\009\009\009else\010\009\009\009\009check=true\010\009\009\009\009break\010\009\009\009end\010\009\009else\010\009\009\009check=true\010\009\009\009break\010\009\009end\010\009\009wait(firerate)\010\009\009check=true\010\009\009if not automatic then\010\009\009\009break\010\009\009end\010\009end\010end)\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25887,class="Script",parent=25548,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{8718FD1C-E110-40A4-A745-A1BC22B79220}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010NPC = script.Parent\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(0.1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 125 and\010\009\009\009 (target.Position - script.Parent.Torso.Position).magnitude > 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser.Down.Value=true\010\009\009\009NPC.EyeLaser2.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser2.Down.Value=true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude < 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser.Down.Value=true\010\009\009\009NPC.EyeLaser2.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser2.Down.Value=true\010\009\009\009script.Parent.Humanoid.WalkSpeed = -16\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 125 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser.Down.Value=true\010\009\009\009NPC.EyeLaser2.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser2.Down.Value=true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 16\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false\010\009\009NPC.EyeLaser.Down.Value=false\010\009\009NPC.EyeLaser2.Down.Value=false\010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25889,class="Script",parent=25548,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{FE6F6E4B-3CD4-4AE2-8F53-56F43511D710}",["Source"]="local Model = script.Parent\010local Humanoid = Model.Humanoid\010\010function ChooseRandomPart()\010\009local PartToChoose = {}\010\009for _, Child in pairs(Model:GetChildren()) do\010\009\009if Child:IsA(\034BasePart\034) then\010\009\009\009table.insert(PartToChoose,Child)\010\009\009end\010\009end\010\009return PartToChoose[math.random(1,#PartToChoose)]\010end\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Death:Play()\010\009local e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009local parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 or parts[i].className == \034UnionOperation\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-75,75),math.random(75,150),math.random(-75,75))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\010\009wait(10)\010\009script.Parent:remove() \010end \010\010Humanoid.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25890,class="Script",parent=25548,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="AIUseFPSMode",["ScriptGuid"]="{406EC0C8-50AA-4127-8E61-672B80D886D7}",["Source"]="gyro = Instance.new(\034BodyGyro\034)\010gyro.Parent = script.Parent:findFirstChild(\034Torso\034)\010gyro.P = 7500\010gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\010script.Parent.Humanoid.StateChanged:connect(function(Old,New)\010\009if New == Enum.HumanoidStateType.Running then\010\009\009gyro.P = 7500\010\009\009gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\009else\010\009\009gyro.P = 0\010\009\009gyro.maxTorque = Vector3.new(0,0,0)\010\009end\010end)\010\010while true do\010\009vCharacter = script.Parent\010\009if vCharacter ~= nil then \010\009\009gyro.Parent = script.Parent.Torso\010\009\009local tp\010\009\009if (vCharacter.Target.Value) and vCharacter.Humanoid:GetState() then\010\009\009\009tp = vCharacter.Target.Value.Position\010\009\009else\010\009\009\009tp = vCharacter.Humanoid.WalkToPoint\010\009\009end\010\009\009tp = Vector3.new(tp.X,script.Parent.Torso.Position.Y,tp.Z) \010\009\009local dir = (tp - script.Parent.Torso.Position).unit\010\009\009local spawnPos = script.Parent.Torso.Position\010\009\009local pos = spawnPos + (dir * 1)\010\009\009gyro.cframe = CFrame.new(pos,  pos + dir)\010\009elseif not vCharacter.Attack.Value then\010\009\009gyro.Parent = nil\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25891,class="Script",parent=25548,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{2C408082-B972-4984-B40F-E2F5FD6A1309}",["Source"]="wait()\010function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010--[[local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)]]\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimInstance = nil\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=583217857\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=583217857\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=583216937\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=180436148\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=180436334\034, weight = 10 } \010\009\009\009}, \010\009sit = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=178130996\034, weight = 10 } \010\009\009\009},\009\010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182393478\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182435998\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491037\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491065\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436842\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491248\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491277\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436935\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491368\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491423\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009currentAnimInstance = nil\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if frameName == \034Footstep1\034 or frameName == \034Footstep2\034 then Figure.FakeTorso[\034Footstep\034..math.random(1,4)]:Play() end\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\010\009\009local repeatAnim = currentAnim\010\009\009-- return to idle if finishing an emote\010\009\009if (emoteNames[repeatAnim] ~= nil and emoteNames[repeatAnim] == false) then\010\009\009\009repeatAnim = \034idle\034\010\009\009end\010\009\009\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid) \010\009\009\010\009local roll = math.random(1, animTable[animName].totalWeight) \010\009local origRoll = roll\010\009local idx = 1\010\009while (roll > animTable[animName][idx].weight) do\010\009\009roll = roll - animTable[animName][idx].weight\010\009\009idx = idx + 1\010\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009local anim = animTable[animName][idx].anim\010\010\009-- switch animation\009\009\010\009if (anim ~= currentAnimInstance) then\010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\009\009currentAnimInstance = anim\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009\009\010\009end\010\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local toolAnimInstance = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\009\010\009\009playToolAnimation(toolAnimName, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\009 \010\009\009\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009if (toolAnimInstance ~= anim) then\010\009\009\009\010\009\009\009if (toolAnimTrack ~= nil) then\010\009\009\009\009toolAnimTrack:Stop()\010\009\009\009\009toolAnimTrack:Destroy()\010\009\009\009\009transitionTime = 0\010\009\009\009end\010\009\009\009\009\009\010\009\009\009-- load it to the humanoid; get AnimationTrack\010\009\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009\009 \010\009\009\009-- play the animation\010\009\009\009toolAnimTrack:Play(transitionTime)\010\009\009\009toolAnimName = animName\010\009\009\009toolAnimInstance = anim\010\010\009\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009toolAnimInstance = nil\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009--[[if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end]]\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009--playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010--[[function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end]]\010\010--[[function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end]]\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009--playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009--playAnimation(\034sit\034, 0.5, Humanoid)\010\009\009return\010\009--[[elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)]]\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009stopAllAnimations()\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009--[[desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)]]\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009--animStringValueObject = getToolAnim(tool)\010\010\009\009--[[if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end]]\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009--animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimInstance = nil\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010--[[Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)]]\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009--[[print((Torso.Velocity * Vector3.new(1,0,1)).magnitude)\010\009print(pose)]]\010\009if (Torso.Velocity * Vector3.new(1,0,1)).magnitude > 1 and pose ~= \034Running\034 then\010\009\009pose = \034Running\034\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (Torso.Velocity * Vector3.new(1,0,1)).magnitude < 1 and pose ~= \034Standing\034 then\010\009\009pose = \034Standing\034\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009end\010\009local _, time = wait(0.01)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25931,class="Script",parent=25918,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Firescript",["ScriptGuid"]="{58B3A629-038B-4CF9-875C-7175B8AA6A09}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010check=true\010\010gundamage=10\009\009\009\009\009\009\009\009--Base output damage per shot.\010firerate=.1\009\009\009\009\009\009\009\009--How often the weapon can fire.\010automatic=true\009\009\009\009\009\009\009--hold down to continue firing\010range=1000\009\009\009\009\009\009\009\009\009--Max distance that the weapon can fire.\010spread=2\009\009\009\009\009\009\009\009\009\009--The bigger the spread, the more inaccurate the shots will be.\010clipsize=math.huge\009\009\009\009\009\009\009\009--Shots in a clip\010reloadtime=3\009\009\009\009\009\009\009\009--Time it takes to reload the tool.\010startingclips=10\009\009\009\009\009\009\009--If you want infinit clips, remove the IntValue named \034Clips\034 from the tool.\010segmentlength=25\009\009\009\009\009\009\009--How long the shot segments are, or the speed of the shot.\010fadedelaytime=1/30\010\010\010barrelpos=CFrame.new(0,0,-2.7)\009\009--R,U,B\010rate=1/100\010intangibles={\034Shock\034,\034Bolt\034,\034Bullet\034,\034Plasma\034,\034Effect\034,\034Laser\034,\034Handle\034,\034Effects\034,\034Effect\034,\034Flash\034}\010colors={BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034)}\010flashcolors={\034Bright yellow\034}\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010reloading=false\010local debris=game:GetService(\034Debris\034)\010\010local ammo=sp:FindFirstChild(\034Ammo\034)\010if ammo~=nil then\010\009ammo.Value=clipsize\010end\010local clips=sp:FindFirstChild(\034Clips\034)\010if clips~=nil then\010\009clips.Value=startingclips\010end\010\010sp.Equipped:connect(function()\010\009sp.Parent.Arm1.Fire:Stop()\010\009sp.Parent.Arm1.Reload:Stop()\010end)\010sp.Unequipped:connect(function()\010\009sp.Parent.Arm1.Fire:Stop()\010\009sp.Parent.Arm1.Reload:Stop()\010end)\010\010function round(number,decimal)\010\009decimal=decimal or 0\010\009local mult=10^decimal\010\009return math.floor(number*mult+.5)/mult\010end\010\010function checkintangible(t)\010\009for i3,v3 in ipairs(intangibles) do\010\009\009if string.lower(v3)==string.lower(t.Name) or t.Transparency==1 then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function reload()\010\009reloading=true\010\009sp.Reloading.Value=true\010\009if clips~=nil then\010\009\009if clips.Value>0 then\010\009\009\009clips.Value=clips.Value-1\010\009\009else\010\009\009\009reloading=false\010\009\009\009sp.Reloading.Value=false\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Arm1.Reload:Play()\010\009for i=1,clipsize do\010\009\009wait(reloadtime/clipsize)\010\009\009ammo.Value=i\010\009end\010\009reloading=false\010\009sp.Reloading.Value=false\010end\010\010function castray(startpos,vec,length,ignore,delayifhit)\010\009if length>999 then\010\009\009length=999\010\009end\010\009hit,endpos2=game.Workspace:FindPartOnRay(Ray.new(startpos,vec*length),ignore)\010\009if hit~=nil then\010\009\009if checkintangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit,endpos2=castray(endpos2+(vec*.01),vec,length-((startpos-endpos2).magnitude),ignore,delayifhit)\010\009\009end\010\009end\010\009return hit,endpos2\010end\010\010function sendbullet(boltstart,targetpos,fuzzyness,segmentlength,ignore,clr,damage,fadedelay)\010\009if ammo~=nil then\010\009\009if ammo.Value>0 then\010\009\009\009ammo.Value=ammo.Value-1\010\009\009else\010\009\009\009reload()\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Arm1.Fire:Play()\010\009muzzleeffect()\010\009local t=sp.Parent:FindFirstChild(\034Torso\034)\010\009if t~=nil then\010\009\009local shoulder=t:FindFirstChild(\034Right Shoulder\034)\010\009\009if shoulder~=nil then\010\009\009\009shoulder.CurrentAngle=2\010\009\009end\010\009end\010\010\009local boltdist=range\010\009local clickdist=(boltstart-targetpos).magnitude\010\009local targetpos=targetpos+(Vector3.new(math.random()-.5,math.random()-.5,math.random()-.5)*(clickdist/100)*fuzzyness)\010\009local boltvec=(targetpos-boltstart).unit\010\009local totalsegments=math.ceil(boltdist/segmentlength)\010\009local lastpos=boltstart\010\009for i=1,totalsegments do\010\009\009local newpos=(boltstart+(boltvec*(boltdist*(i/totalsegments))))\010\009\009local segvec=(newpos-lastpos).unit\010\009\009local boltlength=(newpos-lastpos).magnitude\010\009\009local bolthit,endpos=castray(lastpos,segvec,boltlength,ignore,false)\010\009\009drawbeam(lastpos,endpos,clr,fadedelay)\010\009\009if bolthit~=nil then\010\009\009\009local h=bolthit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local t=bolthit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h~=nil and t and t.Value ~= sp.Parent.TEAM.Value then\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009end\010\009\009\009break\010\009\009end\010\009\009lastpos=endpos\010\009\009wait(rate)\010\009end\010end\010\010function drawbeam(beamstart,beamend,clr,fadedelay)\010\009local dis=(beamstart-beamend).magnitude\010\009local laser=Instance.new(\034Part\034)\010\009laser.Name=\034Bullet\034\010\009laser.Transparency = 0\010\009laser.Anchored=true\010\009laser.CanCollide=false\010\009laser.Shape=\034Block\034\010\009laser.formFactor=\034Custom\034\010\009laser.Size=Vector3.new(.375,.375,dis+.2)\010\009laser.Material=Enum.Material.Plastic\010\009laser.Locked=true\010\009laser.TopSurface=0\010\009laser.BottomSurface=0\010\009laser.BrickColor=clr\010\009laser.CFrame=CFrame.new(beamend,beamstart)*CFrame.new(0,0,-dis/2)\010\009--[[local mesh = Instance.new(\034BlockMesh\034,laser)\010\009mesh.Scale = Vector3.new(10,0,1)\010\009local decal = Instance.new(\034Decal\034,laser)\010\009decal.Face = \034Top\034\010\009decal.Texture = \034rbxassetid://201063866\034\010\009decal.Transparency = 0.25\010\009local decal2 = decal:Clone()\010\009decal2.Face = \034Bottom\034\010\009decal2.Parent = decal.Parent]]\010\009local light = script.SurfaceLight:Clone()\010\009light.Enabled = true\010\009light.Face = \034Top\034\010\009light.Parent = laser\010\009local light2 = script.SurfaceLight:Clone()\010\009light2.Enabled = true\010\009light.Face = \034Bottom\034\010\009light2.Parent = laser\010\009laser.Parent=game.Workspace\010\009debris:AddItem(laser,fadedelay)\010end\010\010function muzzleeffect()\010\009local flash=Instance.new(\034Part\034)\010\009flash.Name=\034Effect\034\010\009flash.Anchored=true\010\009flash.CanCollide=false\010\009flash.Shape=\034Block\034\010\009flash.formFactor=\034Custom\034\010\009flash.Size=Vector3.new(.2,.2,.2)\010\009flash.Material=Enum.Material.Plastic\010\009flash.Locked=true\010\009flash.TopSurface=0\010\009flash.BottomSurface=0\010\009flash.BrickColor=BrickColor.new(flashcolors[math.random(1,#flashcolors)])\010\009local mesh=Instance.new(\034SpecialMesh\034)\010\009mesh.MeshId=\034http://www.roblox.com/asset/?id=25212400\034\010\009local scale=Vector3.new(.2+(math.random()*.1),.4+(math.random()*.4),.2+(math.random()*.1))\010\009mesh.Scale=scale\010\009mesh.Parent=flash\010\009flash.CFrame=sp.Parent.Arm1.CFrame*barrelpos*CFrame.Angles(0,math.pi*2*math.random(),0)*CFrame.new(0,scale.y*.9,0)\010\009debris:AddItem(flash,rate)\010\009flash.Parent=game.Workspace\010end\010\010sp.Down.Changed:connect(function()\010\009while sp.Down.Value and check and not reloading do\010\009\009check=false\010\009\009local humanoid=sp.Parent:FindFirstChild(\034Humanoid\034)\010\009\009if humanoid~=nil then\010\009\009\009if humanoid.Health>0 then\010\009\009\009\009spos1=(sp.Parent.Arm1.CFrame*barrelpos).p\010\009\009\009\009delay(0,function() sendbullet(spos1,sp.Aim.Value,spread,segmentlength,sp.Parent,colors[1],gundamage,fadedelaytime) end)\010\009\009\009else\010\009\009\009\009check=true\010\009\009\009\009break\010\009\009\009end\010\009\009else\010\009\009\009check=true\010\009\009\009break\010\009\009end\010\009\009wait(firerate)\010\009\009check=true\010\009\009if not automatic then\010\009\009\009break\010\009\009end\010\009end\010end)\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=25933,class="Script",parent=25548,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{66C3E310-821A-4F5D-A9E9-1E31301AC322}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
