T[#T+1]={id=26206,class="Script",parent=26198,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="WeldScript",["ScriptGuid"]="{E74CA40F-6AF8-4441-8D94-C1BE1A444CAA}",["Source"]="--Made by Stickmasterluke\013\010\013\010\013\010sp=script.Parent\013\010\013\010function waitfor(a,b)\013\010\009while a:FindFirstChild(b)==nil do\013\010\009\009a.ChildAdded:wait()\013\010\009end\013\010\009return a:FindFirstChild(b)\013\010end\013\010\013\010h2=waitfor(sp,\034Handle2\034)\013\010\013\010function weld()\013\010\009if w~=nil then\013\010\009\009w:remove()\013\010\009end\013\010\009for _,v in pairs(sp:GetChildren()) do\013\010\009\009if v and v.Name==\034Handle2Weld\034 then\013\010\009\009\009v:remove()\013\010\009\009end\013\010\009end\013\010\009local w=Instance.new(\034Weld\034)\013\010\009w.Name=\034Handle2Weld\034\013\010\009w.Part0=sp\013\010\009w.Part1=h2\013\010\009w.C0=CFrame.new(0,0,-.06)\013\010\009w.Parent=sp\013\010end\013\010weld()\013\010\013\010sp.ChildRemoved:connect(weld)\013\010\013\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26209,class="Script",parent=26198,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="WeldScript2",["ScriptGuid"]="{062F2BFF-8C4F-42B5-ACCF-CE5A6348589A}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010\010function waitfor(a,b)\010\009while a:FindFirstChild(b)==nil do\010\009\009a.ChildAdded:wait()\010\009end\010\009return a:FindFirstChild(b)\010end\010\010h2=waitfor(sp,\034Handle3\034)\010\010function weld()\010\009if w~=nil then\010\009\009w:remove()\010\009end\010\009for _,v in pairs(sp:GetChildren()) do\010\009\009if v and v.Name==\034Handle3Weld\034 then\010\009\009\009v:remove()\010\009\009end\010\009end\010\009local w=Instance.new(\034Weld\034)\010\009w.Name=\034Handle3Weld\034\010\009w.Part0=sp\010\009w.Part1=h2\010\009w.C0=CFrame.new(0,0,-.06)\010\009w.Parent=sp\010end\010weld()\010\010sp.ChildRemoved:connect(weld)\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26243,class="Script",parent=26197,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Server",["ScriptGuid"]="{5CF69853-896C-4590-87A5-8BE17930B732}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player\010local Character\010local Humanoid\010local TEAM\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local ChangeAmmoAndClip = script:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = script:WaitForChild(\034InflictTarget\034)\010local Grip2\010local Handle2\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,1)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local AmmoValue = script:FindFirstChild(\034Ammo\034) or Instance.new(\034NumberValue\034,script)\010AmmoValue.Name = \034Ammo\034\010AmmoValue.Value = Module.AmmoPerClip\010local ClipsValue = script:FindFirstChild(\034Clips\034) or Instance.new(\034NumberValue\034,script)\010ClipsValue.Name = \034Clips\034\010ClipsValue.Value = Module.LimitedClipEnabled and Module.Clips or 0\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009local IdleAnim = Instance.new(\034Animation\034,Tool)\010\009IdleAnim.Name = \034IdleAnim\034\010\009IdleAnim.AnimationId = \034rbxassetid://\034..(Module.DualEnabled and 53610688 or Module.IdleAnimationID)\010end\010if Module.FireAnimationID ~= nil then\010\009local FireAnim = Instance.new(\034Animation\034,Tool)\010\009FireAnim.Name = \034FireAnim\034\010\009FireAnim.AnimationId = \034rbxassetid://\034..Module.FireAnimationID\010end\010if Module.ReloadAnimationID ~= nil then\010\009local ReloadAnim = Instance.new(\034Animation\034,Tool)\010\009ReloadAnim.Name = \034ReloadAnim\034\010\009ReloadAnim.AnimationId = \034rbxassetid://\034..Module.ReloadAnimationID\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009local ShotgunClipinAnim = Instance.new(\034Animation\034,Tool)\010\009ShotgunClipinAnim.Name = \034ShotgunClipinAnim\034\010\009ShotgunClipinAnim.AnimationId = \034rbxassetid://\034..Module.ShotgunClipinAnimationID\010end\010\010ChangeAmmoAndClip.OnServerEvent:connect(function(Player,Ammo,Clips)\010\009AmmoValue.Value = Ammo\010\009ClipsValue.Value = Clips\010end)\010InflictTarget.OnServerEvent:connect(function(Player,TargetHumanoid,TargetTorso,Damage,Direction,Knockback,Lifesteal,FlamingBullet)\010\009if Player and TargetHumanoid and TargetHumanoid.Health ~= 0 and TargetTorso then\010\009\009while TargetHumanoid:FindFirstChild(\034creator\034) do\010\009\009\009TargetHumanoid.creator:Destroy()\010\009\009end\010\009\009local creator = Instance.new(\034ObjectValue\034,TargetHumanoid)\010\009\009creator.Name = \034creator\034\010\009\009creator.Value = Player\010\009\009game.Debris:AddItem(creator,5)\010\009\009TargetHumanoid:TakeDamage(Damage)\010\009\009if Knockback > 0 then\010\009\009\009TargetTorso.Velocity = Direction * Knockback\010\009\009end\010\009\009if Lifesteal > 0 and Humanoid and Humanoid.Health ~= 0 then\010\009\009\009Humanoid.Health = Humanoid.Health + (Damage*Lifesteal)\010\009\009end\010\009\009if FlamingBullet then\010\009\009\009local Debuff = TargetHumanoid.Parent:FindFirstChild(\034IgniteScript\034) or script.IgniteScript:Clone()\010\009\009\009Debuff.creator.Value = Player\010\009\009\009Debuff.Disabled = false\010\009\009\009Debuff.Parent = TargetHumanoid.Parent\010\009\009end\010\009end\010end)\010\010Tool.Equipped:connect(function()\010\009Player = game.Players:GetPlayerFromCharacter(Tool.Parent)\010\009Character = Tool.Parent\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009TEAM = Character:FindFirstChild(\034TEAM\034)\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010\010Tool.Unequipped:connect(function()\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26246,class="Script",parent=26243,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="IgniteScript",["ScriptGuid"]="{A0DE3086-3878-424D-BCAE-6DB1EDF5083B}",["Source"]="local Humanoid = script.Parent:FindFirstChild(\034Humanoid\034)\010local Torso = script.Parent:FindFirstChild(\034Torso\034)\010local Fires = {}\010local FireDamagePerSecond = 5\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010if Humanoid and Torso then\010\009BurnSound = Instance.new(\034Sound\034)\010\009BurnSound.Name = \034BurnSound\034\010\009BurnSound.SoundId = \034http://www.roblox.com/asset/?id=32791565\034\010\009BurnSound.Parent = Torso\010\009BurnSound.Volume = 1\010\009game.Debris:AddItem(BurnSound,10)\010\009Delay(0,function()\010\009\009BurnSound:Play()\010\009end)\010\009for _,parts in pairs(script.Parent:GetChildren()) do\010\009\009if parts.className == \034Part\034 or parts.className == \034WedgePart\034 or parts.className == \034CornerWedgePart\034 then\010\009\009\009local firer = Instance.new(\034Fire\034)\010\009\009\009table.insert(Fires,firer)\010\009\009\009firer.Size = 5 + (parts.Size.magnitude*1.5)\010\009\009\009firer.Parent = parts\010\009\009end\010\009end\010\009while script.Duration.Value > 0 do\010\009\009wait(0.1)\010\009\009script.Duration.Value = script.Duration.Value - 0.1\010\009\009while Humanoid:FindFirstChild(\034creator\034) do\010\009\009\009Humanoid.creator:Destroy()\010\009\009end\010\009\009local Tag = script.creator:clone()\010\009\009Tag.Parent = Humanoid\010\009\009game.Debris:AddItem(Tag,5)\010\009\009Humanoid:TakeDamage(FireDamagePerSecond*0.1)\010\009end\010\009for _, Fire in pairs(Fires) do\010\009\009Fire.Enabled = false\010\009end\010\009wait(5)\010\009for _, Fire in pairs(Fires) do\010\009\009Fire:Destroy()\010\009end\010end\010wait()\010script:remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26251,class="Script",parent=26197,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="CHANGE LOG",["ScriptGuid"]="{432108E9-CA6D-49FB-920F-F92D31FB8FDB}",["Source"]="--[[\010\009\010v1.0.6\010==================================================\010-Fixed a glitch which player can shooting even after died\010-Added \034ChargedShot\034 setting\010-Added \034Minigun\034 setting\010-Added \034Piercing\034 setting\010-Added \034FadeTime\034 setting\010-Updated \034BulletVisualizerScript\034. Replace an older one now!\010==================================================\010\009\010v1.0.5\010==================================================\010-Fixed a gun that shoot slower even you set \034FireRate\034 to lower\010-Added \034ShotgunReload\034 setting\010==================================================\010\009\010v1.0.4\010==================================================\010-Fixed VisualizeBulletScript and BulletVisualizerScript. Previously, it's a bug that doesn't show bullet for other player.\010-Fixed a bug which scope still in use even unequipped\010==================================================\010\009\010v1.0.3\010==================================================\010-Fixed a bug that you can reload a gun even unequip\010-Ray start position is now at Player's Head instead Gun Muzzle\010-Added \034DualEnabled\034 setting\010-Added Ammo Box for the gun\010-User can no longer use Scope while reloading\010==================================================\010\009\010v1.0.2\010==================================================\010-Fixed Bullet Visualizer that doesn't display fake bullet to other player\010-Fixed fake bullet still displayed even \034VisualizerEnabled\034 is disabled\010==================================================\010\009\010v1.0.1\010==================================================\010-Fixed reload\010-Ammo GUI will not show if AmmoPerClip is \034math.huge\034\010-Added Animation setting\010==================================================\010\009\010v1.0\010==================================================\010-First release\010==================================================\010\009\010--]]",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26282,class="Script",parent=26256,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{85740BC1-7664-41EB-861C-DAA1BDBFF6E8}",["Source"]="function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750544\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750618\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125749145\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750759\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750800\034, weight = 10 } \010\009\009\009}, \010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750867\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=130018893\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546839\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=132546884\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934142\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934298\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934376\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934458\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934530\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=160934593\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopAllAnimations()\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid)\010\009local idleFromEmote = (animName == \034idle\034 and emoteNames[currentAnim] ~= nil)\010\009if (animName ~= currentAnim and not idleFromEmote) then\009\009 \010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009end\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\009\009local repeatAnim = stopToolAnimations()\010\009\009playToolAnimation(repeatAnim, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\010\009if (animName ~= toolAnimName) then\009\009 \010\009\009\010\009\009if (toolAnimTrack ~= nil) then\010\009\009\009toolAnimTrack:Stop()\010\009\009\009toolAnimTrack:Destroy()\010\009\009\009transitionTime = 0\010\009\009end\010\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009toolAnimTrack:Play(transitionTime)\010\009\009toolAnimName = animName\010\010\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end\010\010function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009stopAllAnimations()\010\009\009moveSit()\010\009\009return\010\009elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009animStringValueObject = getToolAnim(tool)\010\010\009\009if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)\010\010-- setup emote chat hook\010\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009local _, time = wait(0.1)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26302,class="Script",parent=26301,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Put this in Boss's Humanoid",["ScriptGuid"]="{D4B593F6-EBFB-4972-AFE6-EC420CAC5B4B}",["Source"]="while true do\010\009if game.ReplicatedStorage.Boss6.Value == nil then\010\009game.ReplicatedStorage.Boss6.Value = script.Parent.Parent\010\009end\010\009--[[for _, Players in pairs(game.Players:GetChildren()) do\010\009\009local BossBattleHealthGui = Players.PlayerGui:FindFirstChild(\034BossBattleHealthGui\034)\010\009\009if BossBattleHealthGui then\010\009\009\009BossBattleHealthGui.Frame.Boss.Value = script.Parent.Parent\010\009\009end\010\009end]]\010\009wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26303,class="Script",parent=26256,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Sound",["ScriptGuid"]="{4737A8C1-4299-485B-A0D3-444B4CBFB2E2}",["Source"]="-- util\010\010function waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010function newSound(id)\010\009local sound = Instance.new(\034Sound\034)\010\009sound.SoundId = id\010\009sound.archivable = false\010\009sound.Parent = script.Parent.Head\010\009return sound\010end\010\010-- declarations\010\010local sDied = newSound(\034rbxassetid://213632774\034)\010sDied.Parent = script.Parent\010sDied.Pitch = 1.3\010sDied.Volume = 1\010local sFallingDown = newSound(\034rbxasset://sounds/splat.wav\034)\010local sFreeFalling = newSound(\034rbxasset://sounds/swoosh.wav\034)\010local sGettingUp = newSound(\034rbxasset://sounds/hit.wav\034)\010local sJumping = newSound(\034rbxasset://sounds/button.wav\034)\010local sRunning = newSound(\034rbxasset://sounds/bfsl-minifigfoots1.mp3\034)\010sRunning.Looped = true\010\010local Figure = script.Parent\010local Head = waitForChild(Figure, \034Head\034)\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010-- functions\010\010function onDied()\010\009sDied:Play()\010\009wait(2.5)\010\009script.Parent:Destroy()\010end\010\010function onState(state, sound)\010\009if state then\010\009\009sound:Play()\010\009else\010\009\009sound:Pause()\010\009end\010end\010\010function onRunning(speed)\010\009if speed>0 then\010\009\009sRunning:Play()\010\009else\010\009\009sRunning:Pause()\010\009end\010end\010\010-- connect up\010\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010Humanoid.Jumping:connect(function(state) onState(state, sJumping) end)\010Humanoid.GettingUp:connect(function(state) onState(state, sGettingUp) end)\010Humanoid.FreeFalling:connect(function(state) onState(state, sFreeFalling) end)\010Humanoid.FallingDown:connect(function(state) onState(state, sFallingDown) end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26305,class="Script",parent=26256,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{CDC77B8E-7F2F-4D14-967D-07B2E2FFA5A0}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009game.workspace.Scripts.WaveScript.Dead_Zombies.Value = game.workspace.Scripts.WaveScript.Dead_Zombies.Value + 1\010\009wait(2.5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26387,class="Script",parent=26306,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="PelletScript",["ScriptGuid"]="{9F1A1DF1-71FA-4513-890C-32EA0A3CBD0B}",["Source"]="local debris = game:service(\034Debris\034)\010local pellet = script.Parent\010local startingDamage = 20\010local damage = startingDamage\010local LastHitCharacter\010\010\010function WaitForChild(parent, child)\010\009while not parent:FindFirstChild(child) do\010\009\009parent.ChildAdded:wait()\010\009end\010\009return parent:FindFirstChild(child)\010end\010\010--local CreatorTag = WaitForChild(pellet, 'creator')\010\010local GemHitSound = Instance.new('Sound')\010GemHitSound.SoundId = 'http://www.roblox.com/asset/?id=124255305'\010GemHitSound.Pitch=1\010GemHitSound.Parent=pellet\010\010\010--[[function tagHumanoid(humanoid)\010\009-- todo: make tag expire\010\009local tag = pellet:findFirstChild(\034creator\034)\010\009if tag ~= nil then\010\009\009-- kill all other tags\010\009\009while(humanoid:findFirstChild(\034creator\034) ~= nil) do\010\009\009\009humanoid:findFirstChild(\034creator\034).Parent = nil\010\009\009end\010\010\009\009local new_tag = tag:clone()\010\009\009new_tag.Parent = humanoid\010\009\009debris:AddItem(new_tag, 1)\010\009end\010end]]\010\010function Explode(hit)\010\009if hit.Name == \034Torso\034 then\009\010\009\009local humanoid = hit.Parent:findFirstChild(\034Humanoid\034)\010\009\009local team = hit.Parent:FindFirstChild(\034TEAM\034)\010\009\009if humanoid~=nil and team and team.Value ~= pellet.TEAM.Value then\010\009\009\009humanoid:TakeDamage(damage*0.5)\010\009\009end\010\009end\010end\010\010function onTouched(hit)\010\009if hit.Name == \034DeadlyROBUX\034 or hit.CanCollide == false then return end\010\009--local creator = WaitForChild(pellet,'creator')\010\009--if (not hit) or (hit.Name == 'Handle') or (not hit.Parent) then return end\009\010\009if not (hit and hit.Name ~= 'Handle' and hit.Parent) then return end\010\009if pellet:FindFirstChild('IS RAGING') then\010\009\009GemHitSound:Play()\010\009end\010\009local humanoid = hit.Parent:findFirstChild(\034Humanoid\034)\010\009local team = hit.Parent:FindFirstChild(\034TEAM\034)\010\009if humanoid~=nil and humanoid.Parent ~= LastHitCharacter and team and team.Value ~= pellet.TEAM.Value then\010\009\009--[[if startingDamage == damage and game.Players:playerFromCharacter(hit.Parent) == CreatorTag.Value then \010\009\009\009return \010\009\009end\010\009\009tagHumanoid(humanoid)]]\010\009\009humanoid:TakeDamage(damage)\010\009\009LastHitCharacter = humanoid.Parent\010\009\009--[[local hitBindable = humanoid:FindFirstChild('Hit')\010\009\009if hitBindable then\010\009\009\009hitBindable:Invoke(damage, CreatorTag)\010\009\009else\010\009\009\009print(\034Could not find BindableFunction 'Hit'\034)\010\009\009end]]\010\009else\010\009\009--[[if hit.CanCollide == false then return end\010\009\009damage = damage / 1.42\010\009\009if damage < 1 then\010\009\009\009connection:disconnect()\010\009\009\009pellet.Parent = nil\010\009\009end]]\010\009end\010\009if pellet:FindFirstChild(\034IS RAGING\034) then\010\009\009local Explosion = Instance.new(\034Explosion\034)\010\009\009Explosion.DestroyJointRadiusPercent = 0\010\009\009Explosion.BlastRadius = 15\010\009\009Explosion.BlastPressure = 1000\010\009\009Explosion.ExplosionType = Enum.ExplosionType.NoCraters\010\009\009Explosion.Position = pellet.Position\010\009\009Explosion.Hit:connect(Explode)\010\009\009Explosion.Parent = Workspace\010\009end\010end\010\010connection = pellet.Touched:connect(onTouched)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26390,class="Script",parent=26306,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="LocalGuiAndAnimations",["ScriptGuid"]="{D4C36C35-DC07-455A-AC36-1EEF36FDDC62}",["Source"]="local Tool = script.Parent;\010\010local EquipAnim\010local ShootAnim \010\010function OnChanged(property)\010\009if property == 'Enabled' then\010\009\009if EquipAnim then EquipAnim:Stop() end\010\009\009if Tool.Enabled == false then\010\009\009\009ShootAnim:Play(nil,nil,2)\010\009\009end\010\009end\010end\010\010\010\010function onEquippedLocal()\010\009local humanoid = Tool.Parent:FindFirstChild('Humanoid')\010\009--EquipAnim = humanoid:LoadAnimation(Tool.Equip)\010\009ShootAnim = humanoid:LoadAnimation(Tool.Shoot)\010\010\009-- Make sure that the tool is still equiped when we play equip anim\010\009Spawn(function() wait() if Tool:IsDescendantOf(Workspace) then\009--[[EquipAnim:Play()]] end end)\010\010\009Tool.Changed:connect(function(property) OnChanged(property) end)\010end\010\010function onUnequippedLocal()\010\009if ShootAnim then ShootAnim:Stop() end\010end\010\010Tool.Equipped:connect(onEquippedLocal)\010Tool.Unequipped:connect(onUnequippedLocal)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26391,class="Script",parent=26306,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Slingshot",["ScriptGuid"]="{AD4DF50C-C6E5-45CC-B7AD-80828D21D2F5}",["Source"]="-- Waits for parent.child to exist, then returns it\010local function WaitForChild(parent, childName)\010\009assert(parent, \034ERROR: WaitForChild: parent is nil\034)\010\009while not parent:FindFirstChild(childName) do parent.ChildAdded:wait() end\010\009return parent[childName]\010end\010\010local Tool = script.Parent\010local Handle = WaitForChild(Tool, 'Handle')\010local VELOCITY = 100 -- constant\010local VELOCITY_SQAURED = VELOCITY * VELOCITY\010local VELOCITY_TO_FOURTH = VELOCITY_SQAURED * VELOCITY_SQAURED\010local ASSET_PREFIX = \034http://www.roblox.com/asset/?id=\034\010\010local MyMouse\010\010local SlingShotMeshIds = {Ammo = 94689434, AttachMe = 94689472, Full = 94689497, Handle = 94689515}\010\010local DebrisService = game:GetService('Debris')\010local ContentProvider = Game:GetService(\034ContentProvider\034)\010local Pellet = Instance.new(\034Part\034)\010Pellet.Locked = true\010Pellet.BackSurface = 0\010Pellet.BottomSurface = 0\010Pellet.Transparency = 0.2\010Pellet.FrontSurface = 0\010Pellet.LeftSurface = 0\010Pellet.RightSurface = 0\010Pellet.TopSurface = 0\010Pellet.Shape = (\034Ball\034)\010Pellet.formFactor = \034Custom\034\010Pellet.Size = Vector3.new(1, 1, 1)\010Pellet.BrickColor = BrickColor.new(\034Lime green\034)\010Pellet.Elasticity = 0.01 \010Pellet.Name = \034DeadlyROBUX\034\010--[[local PelletMesh = Instance.new('SpecialMesh')\010PelletMesh.MeshId = ASSET_PREFIX .. SlingShotMeshIds['Ammo']\010PelletMesh.TextureId = ASSET_PREFIX .. 94689543\010PelletMesh.Scale = Vector3.new(1.5, 1.5, 1.5)\010PelletMesh.Name = 'PelletMesh'\010PelletMesh.Parent = Pellet]]\010\010local SlingShotMesh\010\010local EquipSound\010local SlingshotSounds\010\010local PelletCopy\010\010local IsBlingshot= WaitForChild(Tool,'IsBlingshot')\010\010WaitForChild(Tool, 'PelletScript'):clone().Parent = Pellet\010\010function Fire(mouse_pos)\010\010\009if SlingshotSounds then\010\009\009local soundNum = math.random(1, #SlingshotSounds)\010\009\009SlingshotSounds[soundNum]:Play()\010\009end\010\010-- find player's head pos\010\010\009local vCharacter = Tool.Parent\010\009local vPlayer = game.Players:GetPlayerFromCharacter(vCharacter)\010\010\009local head = vCharacter:findFirstChild(\034Head\034)\010\009if head == nil then return end\010\010\009local startPosition = Tool.Handle.Position + Vector3.new(0,0,0)\010\010\009local dir = mouse_pos - startPosition\010\009dir = dir.unit\010\010\009local launch = startPosition + 0 * dir\010\010\009local delta = mouse_pos - launch\010\009\010\009local dy = delta.y\010\009\010\009local new_delta = Vector3.new(delta.x, 0, delta.z)\010\009delta = new_delta\010\010\009local dx = delta.magnitude\010\009local unit_delta = delta.unit\010\009\010\009-- acceleration due to gravity in RBX units\010\009local g = (-9.81 * 20)\010\010\009local theta = computeLaunchAngle( dx, dy, g)\010\010\009local vy = math.sin(theta)\010\009local xz = math.cos(theta)\010\009local vx = unit_delta.x * xz\010\009local vz = unit_delta.z * xz\010\009\010\010\009local missile = Pellet:clone()\010\010\009missile.CFrame = CFrame.new(launch, launch+Vector3.new(vx,vy,vz))\010        \010\009--missile.Position = launch\010\009missile.Velocity = Vector3.new(vx,vy,vz) * VELOCITY +\010\009(CFrame.Angles(math.rad(-180+(math.random()*360)),math.rad(-180+(math.random()*360)),0).lookVector * (math.random()*50))\010\010\009missile.PelletScript.Disabled = false\010\009\010\010\009--[[if IsBlingshot.Value then\010\009\009missile.PelletMesh.MeshId='http://www.roblox.com/asset/?id=98262500'\010\009\009missile.PelletMesh.TextureId='http://www.roblox.com/asset/?id=98259807'\010\009\009missile.PelletMesh.Scale = Vector3.new(3,3,3)\010\009\009local tbling= IsBlingshot:Clone()\010\009\009tbling.Parent=missile\010\009else\010\009\009missile.PelletMesh.Scale = Vector3.new(2,2,2)\010\009end]]\010\010\009--[[local creator_tag = Instance.new(\034ObjectValue\034)\010\009creator_tag.Value = vPlayer\010\009creator_tag.Name = \034creator\034]]\010\009local team = Tool.Parent.TEAM:Clone()\010\009team.Parent = missile\010\009\010\009if Tool.Parent.Rage.Value == true then\010\009\009local rage = Instance.new(\034ObjectValue\034,missile)\010\009\009rage.Name = \034IS RAGING\034\010\009end\010\009\010\009DebrisService:AddItem(missile,2.0)\010\009missile.Parent = game.Workspace\010\010end\010\010\010function computeLaunchAngle(dx,dy,grav)\010\009-- arcane\010\009-- http://en.wikipedia.org/wiki/Trajectory_of_a_projectile\010\009\010\009local g = math.abs(grav)\010\009local inRoot = (VELOCITY_TO_FOURTH) - (g * ((g*dx*dx) + (2*dy*VELOCITY_SQAURED)))\010\009if inRoot <= 0 then\010\009\009return .25 * math.pi\010\009end\010\009local root = math.sqrt(inRoot)\010\009local inATan1 = ((VELOCITY_SQAURED) + root) / (g*dx)\010\010\009local inATan2 = ((VELOCITY_SQAURED) - root) / (g*dx)\010\009local answer1 = math.atan(inATan1)\010\009local answer2 = math.atan(inATan2)\010\009return math.min(answer1,answer2)\010end\010\010\010Tool.Enabled = true\010function OnActivated(targetOverride)\010\009wait(0) --TODO: Remove when Mouse.Hit and Humanoid.TargetPoint update properly on iPad\010\009if not Tool.Enabled then\010\009\009return\010\009end\010\009local character = Tool.Parent;\010\009local humanoid = character:FindFirstChild('Humanoid')\010\009if humanoid == nil or humanoid.Health <= 0 then\010\009\009print(\034Humanoid not found, or not alive\034)\010\009\009return\010\009end\010\010\009Tool.Enabled = false\010\009local targetPos = targetOverride or MyMouse.Hit.p\010\010\009local Projectiles = 10\010\009if Tool.Parent.Rage.Value == true then Projectiles = 3 end\010\010\009for i = 1,Projectiles do\010\009\009Fire(targetPos)\010\009end\010\009if PelletCopy then PelletCopy.Transparency = 1 end\010\009-- swap meshes here\010\009--[[\010\009for i = 0, 0.2, 0.05 do\010\009\009SlingShotMesh.Scale = Vector3.new(0.5, 0.5, 0.5 + i * 8)\010\009\009wait(0.05)\010\009end\010\009SlingShotMesh.Scale = Vector3.new(0.5, 0.5, 0.5)\010\009--]]\010\009wait()\010\009if PelletCopy then PelletCopy.Transparency = 0 end\010\010\009Tool.Enabled = true\010end\010\010Tool.Use.Changed:connect(function()\010\009if Tool.Use.Value == true then\010\009\009OnActivated(Tool.Parent.Target.Value.Position)\010\009\009Tool.Use.Value = false\010\009end\010end)\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26394,class="Script",parent=26256,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{05BAB4F2-B685-49D4-978F-E45A014D23B8}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010local ChanceToUseAbility = 25\010local ChanceToUseAbilityInRageMode = 50\010\010local MinionSpawns = 1\010local MinionSpawnsInRageMode = 2\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Sit = false\010\009end \010end \010\010script.Parent.Humanoid.HealthChanged:connect(function()\010\009if script.Parent.Humanoid.Health < script.Parent.Humanoid.MaxHealth/2 then\010\009\009script.Parent.Rage.Value = true\010\009\009script.Parent.Head.Fire.Enabled = true\010\009\009script.Parent.Head.BrickColor = BrickColor.new(\034Really red\034)\010\009\009script.Parent.Head.Face.Texture = \034http://www.roblox.com/asset/?id=109676489\034\010\009\009script.Parent.Head.Rage:Play()\010\009end\010end)\010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010Animation = script.Parent.Humanoid:LoadAnimation(script.BlastAnim)\010\010local WaitTime = 1\010\010while true do\010\009local CurrentMinionSpawn = MinionSpawns\010\009local CurrentAbilityChance = ChanceToUseAbility\010\009if script.Parent.Rage.Value == true then\010\009\009WaitTime = 0.5\010\009\009CurrentMinionSpawn = MinionSpawnsInRageMode\010\009\009CurrentAbilityChance = ChanceToUseAbilityInRageMode\010\009else\010\009\009WaitTime = 1\010\009end\010\009wait(WaitTime)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = -7.5 + (math.random()*15)\010\009\009ry = 0\010\009\009rz = -7.5 + (math.random()*15)\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 15 then\010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 15 and (target.Position - script.Parent.Torso.Position).magnitude < 75 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 50\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 75 then \010\009\009\009script.Parent.Attack.Value = false\010\009\009\009script.Parent.Humanoid.WalkSpeed = 50\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009\009if script.Parent.Attack.Value == false and math.random()*100 > 37.5 then\010\009\009\009script.Parent.Humanoid.Jump = true\010\009\009end\010\009\009if script.Parent.Attack.Value == true then\010\009\009\009if math.random()*100 < (CurrentAbilityChance) then\010\009\009\009\009local AbilityToUse = math.random(2,3)\010\009\009\009\009--[[if AbilityToUse == 1 then\010\009\009\009\009\009local NumberOfBot = 0\010\009\009\009\009\009for _, WorkspaceBots in pairs(Workspace:GetChildren()) do\010\009\009\009\009\009\009if WorkspaceBots:IsA(\034Model\034) then\010\009\009\009\009\009\009\009local Humanoid = WorkspaceBots:FindFirstChild(\034Humanoid\034)\010\009\009\009\009\009\009\009local TEAM = WorkspaceBots:FindFirstChild(\034TEAM\034)\010\009\009\009\009\009\009\009if Humanoid and Humanoid.Health ~= 0 and TEAM and TEAM.Value == BrickColor.new(\034Bright red\034) then\010\009\009\009\009\009\009\009\009NumberOfBot = NumberOfBot + 1\010\009\009\009\009\009\009\009end\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009\009if NumberOfBot < (Workspace.RobloxiaMaxNPC.Value + 5) then\010\009\009\009\009\009\009local MinionToPick =\010\009\009\009\009\009\009{game.Lighting.RobloxiaBots.Guest,\010\009\009\009\009\009\009game.Lighting.RobloxiaBots[\034Chef Guest\034],\010\009\009\009\009\009\009game.Lighting.RobloxiaBots[\034Baseball Guest\034],\010\009\009\009\009\009\009game.Lighting.RobloxiaBots.Girluest,\010\009\009\009\009\009\009game.Lighting.RARERobloxiaBots[\034GIANT Vikinguest\034],\010\009\009\009\009\009\009game.Lighting.RARERobloxiaBots[\034Witch Guest\034]}\010\009\009\009\009\009\009for i = 1,CurrentMinionSpawn do\010\009\009\009\009\009\009\009local Minion = MinionToPick[math.random(1,#MinionToPick)]:Clone()\010\009\009\009\009\009\009\009Minion.Parent = Workspace\010\009\009\009\009\009\009\009Minion:MakeJoints()\010\009\009\009\009\009\009\009Minion:MoveTo(script.Parent.Torso.Position + Vector3.new(-5+(math.random()*10),0,-5+(math.random()*10)))\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009else]]if AbilityToUse == 2 then\010\009\009\009\009\009if Animation then Animation:Play(nil,nil,2) end\010\009\009\009\009\009wait(0.1)\010\009\009\009\009\009script.Parent.Blast:Play()\010\009\009\009\009\009local Wave = Instance.new(\034Part\034)\010\009\009\009\009\009Wave.Name = \034Wave\034\010\009\009\009\009\009Wave.FormFactor = \034Custom\034\010\009\009\009\009\009Wave.BrickColor = BrickColor.new(\034Lime green\034)\010\009\009\009\009\009Wave.Material = Enum.Material.Neon\010\009\009\009\009\009Wave.Shape = Enum.PartType.Ball\010\009\009\009\009\009Wave.Size = Vector3.new(10,10,10)\010\009\009\009\009\009Wave.Transparency = 0.5\010\009\009\009\009\009Wave.TopSurface = 0\010\009\009\009\009\009Wave.BottomSurface = 0\010\009\009\009\009\009Wave.Position = script.Parent.Torso.Position\010\009\009\009\009\009Wave.Anchored = true\010\009\009\009\009\009Wave.CanCollide = false\010\009\009\009\009\009Wave.Parent = Workspace\010\009\009\009\009\009game.Debris:AddItem(Wave,5)\010\009\009\009\009\009Spawn(function()\010\009\009\009\009\009\009for i = 1,10 do\01