T[#T+1]={id=26731,class="Script",parent=26728,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{5D1C8D80-ECB7-4CE5-852C-1433E19E1FD5}",["Source"]="wait()\010zombieParent = false\010\010while zombieParent == false do\010\010\009wait()\010\009if script.Parent.Name == \034Turret\034 or script.Parent.Name == \034Giant Noob\034 then\010\009\009zombieParent = true\010\009end\010\010end\010\010local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009\009if dist < 75 then \010\009\009\009\009script.Parent.Attack.Value = true \010\009\009\009elseif dist > 75 then\010\009\009\009\009script.Parent.Attack.Value = false \010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010db = false \010function Hit(hit)\010\009if db == false then \010\009\009kk = script.Parent:FindFirstChild(\034ClassicPartiron\034)\010\009\009if script.Parent.Name == \034Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Zombie\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(50)\010\009\009\009\009db = true \010\009\009\009\009wait(0.5)\010\009\009\009\009db = false \010\009\009\009end\010\009\009elseif script.Parent.Name == \034Giant Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(100)\010\009\009\009\009db = true \010\009\009\009\009wait(0.25)\010\009\009\009\009db = false \010\009\009\009end\010\009\009elseif kk ~= nil and script.Parent.Name == \034Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(300)\010\009\009\009\009db = true \010\009\009\009\009wait(1)\010\009\009\009\009db = false \010\009\009\009end\010\009\009end  \010\009end \010end\010\010function Sit()\010\009if script.Parent.Invulnerable.Sit == true then\010\009\009wait(1) \010\009\009script.Parent.Invulnerable.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Invulnerable.Changed:connect(Sit)\010\010for i,p in pairs(script.Parent:GetChildren()) do \010\009if p:IsA(\034Part\034) then \010\009\009p.Touched:connect(Hit)\010\009end\010end \010\010while true do\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = math.random(0,0)\010\009\009ry = math.random(0,0)\010\009\009rz = math.random(0,0)\010\009\009script.Parent.Invulnerable:MoveTo(target.Position + Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009chancetorotate = math.random(0,3)\010\009\009if chancetorotate == 3 then script.Parent.Invulnerable:MoveTo(script.Parent.Torso.Position + Vector3.new(math.random(-10,10),0,math.random(-10,10)), script.Parent.Parent.Torso) end\010\009\009wait(1)\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
