T[#T+1]={id=26780,class="Script",parent=26773,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="LaserBlast2",["ScriptGuid"]="{720E6EC0-C22F-4CB0-8384-75A15BEA2F50}",["Source"]="-- 42672473 is sorry sound\010-- 42672581 is wind-knocked-out sound\010\010ball = script.Parent\010damage = 20\010\010HitSound = Instance.new(\034Sound\034)\010HitSound.Name = \034HitSound\034\010HitSound.SoundId = \034http://www.roblox.com/asset/?id=11945266\034\010HitSound.Parent = ball\010HitSound.Volume = 1\010\010PersonHitSound = Instance.new(\034Sound\034)\010PersonHitSound.Name = \034PersonHitSound\034\010--PersonHitSound.SoundId = \034http://www.roblox.com/asset/?id=42672473\034\010PersonHitSound.SoundId = \034http://www.roblox.com/asset/?id=42672581\034 -- grunt sound\010PersonHitSound.Volume = .5\010PersonHitSound.Pitch = 1\010PersonHitSound.Parent = ball\010\010db = false\010\010function onTouched(hit)\010\009if db == false then\010\009local humanoid = hit.Parent:findFirstChild(\034Humanoid\034)\010\010\009if humanoid ~= nil then\010\009\009--tagHumanoid(humanoid)\010\009\009humanoid:TakeDamage(damage)\010\009\009db = true\010\009\009--untagHumanoid(humanoid)\010\010\009\009--soundSelector = math.random()*100\010\009\009PersonHitSound:Play()\010\009end\010\010\009ball.Anchored = true\010\010\009--[[\010\009local spark = Instance.new(\034Fire\034)\010\009spark.Color = Color3.new(1,1,0)\010\009spark.SecondaryColor = Color3.new(1,1,0)\010\009spark.Size = 7.5\010\009spark.Heat = 0\010\009spark.Parent = ball\010\009HitSound:Play()\010\009wait(0.05)\010\009ball.Parent = nil\010\009]]\010\009end\010end\010\010function tagHumanoid(humanoid)\010\009-- todo: make tag expire\010\009local tag = ball:findFirstChild(\034creator\034)\010\009if tag ~= nil then\010\009\009local new_tag = tag:clone()\010\009\009new_tag.Parent = humanoid\010\009end\010end\010\010\010function untagHumanoid(humanoid)\010\009if humanoid ~= nil then\010\009\009local tag = humanoid:findFirstChild(\034creator\034)\010\009\009if tag ~= nil then\010\009\009\009tag.Parent = nil\010\009\009end\010\009end\010end\010\010--connection = ball.Touched:connect(onTouched)\010\010for i = 1,5 do\010\009ball.Transparency = ball.Transparency + 0.2\010\009ball.Mesh.Scale = ball.Mesh.Scale + Vector3.new(0.5,0.5,0.5)\010\009wait(0.1)\010end\010\010--ball.SparkSound.Looped = false\010--ball.SparkSound:Stop()\010ball.Parent = nil",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26781,class="Script",parent=26773,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="LaserBlast",["ScriptGuid"]="{1BB64857-E7C6-4371-84D2-2C274DEAFC36}",["Source"]="-- 42672473 is sorry sound\010-- 42672581 is wind-knocked-out sound\010\010ball = script.Parent\010damage = 20\010\010HitSound = Instance.new(\034Sound\034)\010HitSound.Name = \034HitSound\034\010HitSound.SoundId = \034http://www.roblox.com/asset/?id=11945266\034\010HitSound.Parent = ball\010HitSound.Volume = 1\010\010PersonHitSound = Instance.new(\034Sound\034)\010PersonHitSound.Name = \034PersonHitSound\034\010--PersonHitSound.SoundId = \034http://www.roblox.com/asset/?id=42672473\034\010PersonHitSound.SoundId = \034http://www.roblox.com/asset/?id=42672581\034 -- grunt sound\010PersonHitSound.Volume = .5\010PersonHitSound.Pitch = 1\010PersonHitSound.Parent = ball\010\010db = false\010\010target = ball:findFirstChild(\034Target\034)\010if target ~= nil then\010\009if db == false then\010\009\009local humanoid = target.Value:findFirstChild(\034Humanoid\034)\010\010\009\009if humanoid ~= nil then\010\009\009\009humanoid:TakeDamage(damage)\010\010\009\009\009PersonHitSound:Play()\010\009\009end\010\010\009ball.Anchored = true\010\009end\010end\010\010function tagHumanoid(humanoid)\010\009-- todo: make tag expire\010\009local tag = ball:findFirstChild(\034creator\034)\010\009if tag ~= nil then\010\009\009local new_tag = tag:clone()\010\009\009new_tag.Parent = humanoid\010\009end\010end\010\010\010function untagHumanoid(humanoid)\010\009if humanoid ~= nil then\010\009\009local tag = humanoid:findFirstChild(\034creator\034)\010\009\009if tag ~= nil then\010\009\009\009tag.Parent = nil\010\009\009end\010\009end\010end\010\010--connection = ball.Touched:connect(onTouched)\010\010for i = 1,5 do\010\009ball.Transparency = ball.Transparency + 0.2\010\009ball.Mesh.Scale = ball.Mesh.Scale + Vector3.new(0.5,0.5,0.5)\010\009wait(0.1)\010end\010\010--ball.SparkSound.Looped = false\010--ball.SparkSound:Stop()\010ball.Parent = nil",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26782,class="Script",parent=26758,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{BDEF9511-5455-4754-8DA3-89094FDE5FED}",["Source"]="wait()\010zombieParent = false\010\010while zombieParent == false do\010\010\009wait()\010\009if script.Parent.Name == \034Turret\034 or script.Parent.Name == \034Giant Noob\034 then\010\009\009zombieParent = true\010\009end\010\010end\010\010local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009\009if dist < 75 then \010\009\009\009\009script.Parent.Attack.Value = true \010\009\009\009elseif dist > 75 then\010\009\009\009\009script.Parent.Attack.Value = false \010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010db = false \010function Hit(hit)\010\009if db == false then \010\009\009kk = script.Parent:FindFirstChild(\034ClassicPartiron\034)\010\009\009if script.Parent.Name == \034Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(50)\010\009\009\009\009db = true \010\009\009\009\009wait(0.5)\010\009\009\009\009db = false \010\009\009\009end\010\009\009elseif script.Parent.Name == \034Giant Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(100)\010\009\009\009\009db = true \010\009\009\009\009wait(0.25)\010\009\009\009\009db = false \010\009\009\009end\010\009\009elseif kk ~= nil and script.Parent.Name == \034Noob\034 then \010\009\009\009if hit.Parent == nil then return end\010\009\009\009local human = hit.Parent:FindFirstChild(\034Zombie\034)\010\009\009\009if human ~= nil and human.Parent.Name ~=  script.Parent.Owner.Value and waitTimer == 0 and human.Parent.Name ~= \034Noob\034 and human.Parent.Name ~= \034Giant Noob\034 then\010\009\009\009\009human:TakeDamage(300)\010\009\009\009\009db = true \010\009\009\009\009wait(1)\010\009\009\009\009db = false \010\009\009\009end\010\009\009end  \010\009end \010end\010\010function Sit()\010\009if script.Parent.Invulnerable.Sit == true then\010\009\009wait(1) \010\009\009script.Parent.Invulnerable.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Invulnerable.Changed:connect(Sit)\010\010for i,p in pairs(script.Parent:GetChildren()) do \010\009if p:IsA(\034Part\034) then \010\009\009p.Touched:connect(Hit)\010\009end\010end \010\010while true do\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = math.random(0,0)\010\009\009ry = math.random(0,0)\010\009\009rz = math.random(0,0)\010\009\009script.Parent.Invulnerable:MoveTo(target.Position + Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009chancetorotate = math.random(0,3)\010\009\009if chancetorotate == 3 then script.Parent.Invulnerable:MoveTo(script.Parent.Torso.Position + Vector3.new(math.random(-10,10),0,math.random(-10,10)), script.Parent.Parent.Torso) end\010\009\009wait(1)\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
