T[#T+1]={id=26810,class="Script",parent=26804,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="RayGun",["ScriptGuid"]="{10A2163E-A19B-41A0-83F1-963526E66050}",["Source"]="local Tool = script.Parent;\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010enabled = true\010\010--local spark = Instance.new(\034Sparkles\034)\010--spark.Color = Color3.new(0,1,0)\010\010function fire(v)\010\010\009local vCharacter = Tool.Parent\010\009local vPlayer = game.Players:playerFromCharacter(vCharacter)\010\010\009local missile = Instance.new(\034Part\034)\010\010\009\010\009--spark:Clone().Parent = missile\010\010\009local spawnPos = Tool.Parent.Target.Value.Position\010\009\010\010\009--spawnPos  = spawnPos + (v * 10)\010\010\009\010\009missile.Position = spawnPos\010\009missile.Size = Vector3.new(.2,.2,.2)\010\009--missile.Velocity = v * 100\010\009missile.BrickColor = BrickColor.new(\034Really red\034)\010\009missile.Shape = 0\010\009missile.BottomSurface = 0\010\009missile.TopSurface = 0\010\009missile.Name = \034Spark\034\010\009missile.Reflectance = 0\010\009missile.Elasticity = 1\010\009missile.Anchored = true\010\009missile.CanCollide = false\010\009Tool.Mesh:clone().Parent = missile\010\010\010\009local force = Instance.new(\034BodyForce\034)\010\009force.force = Vector3.new(0,99,0)\010\009force.Parent = missile\010\010\009local creator_tag = Instance.new(\034ObjectValue\034)\010\009creator_tag.Value = vPlayer\010\009creator_tag.Name = \034creator\034\010\009creator_tag.Parent = missile\010\009\010\009local new_script = script.Parent.LaserBlast:clone()\010\009new_