T[#T+1]={id=26840,class="Script",parent=26834,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="RayGun",["ScriptGuid"]="{7A7B4885-2E1A-42BB-8023-EC492662E248}",["Source"]="local Tool = script.Parent;\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010enabled = true\010\010--local spark = Instance.new(\034Sparkles\034)\010--spark.Color = Color3.new(0,1,0)\010\010function fire(v)\010\010\009local vCharacter = Tool.Parent\010\009local vPlayer = game.Players:playerFromCharacter(vCharacter)\010\010\009local missile = Instance.new(\034Part\034)\010\010\009\010\009--spark:Clone().Parent = missile\010\010\009local spawnPos = Tool.Parent.Target.Value.Position\010\009\010\010\009--spawnPos  = spawnPos + (v * 10)\010\010\009\010\009missile.Position = spawnPos\010\009missile.Size = Vector3.new(.2,.2,.2)\010\009--missile.Velocity = v * 100\010\009missile.BrickColor = BrickColor.new(\034Really red\034)\010\009missile.Shape = 0\010\009missile.BottomSurface = 0\010\009missile.TopSurface = 0\010\009missile.Name = \034Spark\034\010\009missile.Reflectance = 0\010\009missile.Elasticity = 1\010\009missile.Anchored = true\010\009missile.CanCollide = false\010\009Tool.Mesh:clone().Parent = missile\010\010\010\009local force = Instance.new(\034BodyForce\034)\010\009force.force = Vector3.new(0,99,0)\010\009force.Parent = missile\010\010\009local creator_tag = Instance.new(\034ObjectValue\034)\010\009creator_tag.Value = vPlayer\010\009creator_tag.Name = \034creator\034\010\009creator_tag.Parent = missile\010\009\010\009local new_script = script.Parent.LaserBlast:clone()\010\009new_script.Disabled = false\010\009new_script.Parent = missile\010\009\010\009local target = Instance.new(\034ObjectValue\034)\010\009target.Name = \034Target\034\010\009target.Value = Tool.Parent.Target.Value.Parent\010\009target.Parent = missile\010\009\010\010\009Hit = missile.CFrame\010\009local Projectile = Instance.new(\034Part\034) \010\009Projectile.Name = \034Trail\034 \010\009local Place0 = Tool[\034Handle\034].CFrame \010\009Projectile.formFactor = 0 \010\009Projectile.Size = Vector3.new(1,1,(Place0.p - Hit.p).magnitude) \010\009Projectile.CFrame = CFrame.new((Place0.p + Hit.p)/2,Place0.p) \010\009Projectile.Parent = Workspace\010\009Projectile.BrickColor = missile.BrickColor\010\009Projectile.Anchored = true \010\009Projectile.CanCollide = false\010\009\010\009local new_script2 = script.Parent.ProjectileTimeLife:clone()\010\009new_script2.Disabled = false\010\009new_script2.Parent = Projectile\010\010\009me2 = Instance.new(\034BlockMesh\034)\010\009me2.Scale = Vector3.new(0.25,0.25,1)\010\009me2.Parent = Projectile\010\010\009--Tool.Handle.GruntSound:Clone().Parent = missile\010\010\009missile.Parent = Workspace\010--\009wait(.15)\010\009--PewPew:Stop()\010end\010\010\010\010function gunUp()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.5)\010end\010\010function gunOut()\010\009Tool.GripPos = Vector3.new(0,-0.5,0.75)\010end\010\010function isTurbo(character)\010\009return character:FindFirstChild(\034BoltHelm\034) ~= nil\010end\010\010\010function onActivated()\010\009if not enabled  then\010\009\009return\010\009end\010\010\009enabled = false\010\010\010\009local character = Tool.Parent;\010\009local humanoid = character.Invulnerable\010\009if humanoid == nil then\010\009\009print(\034Humanoid not found\034)\010\009\009return \010\009end\010\010\009local targetPos = Tool.Parent.Target.Value.Position\010\009local lookAt = (targetPos - character.Head.Position).unit\010\010\009local reload = .05\010\009--if (isTurbo(character)) then\010\009--\009reload = .25\010\009--\009print(\034turbo\034)\010\009--end\010\010\009\010\009local PewPew = Tool.Handle:FindFirstChild(\034PewPew\034)\010\010\009if (PewPew == nil) then\010\009\009PewPew = Instance.new(\034Sound\034)\010\009\009PewPew.Name = \034PewPew\034\010\009\009PewPew.SoundId = \034http://www.roblox.com/asset/?id=92651381\034\010\009\009PewPew.Parent = Tool.Handle\010\009\009PewPew.Volume = 1\010\009\009--PewPew.Pitch = 1.2\010\009end\010\009\010\009--PewPew:Play()\010\009for i =1,3 do\010\010\009\009local spark = Instance.new(\034Fire\034)\010\009\009spark.Color = Color3.new(1,0,0)\010\009\009spark.SecondaryColor = Color3.new(1,0,0)\010\009\009spark.Size = 7.5\010\009\009spark.Heat = 0\010\009\009spark.Parent = Tool.Handle\010\010\009--gunUp()\010\009\009fire(lookAt,humanoid)\010\009\009PewPew:Play()\010\009\009wait(0.25)\010\010\009\009spark:remove()\010\009end\010\009--wait(reload)\010\009--gunOut()\010\009--wait(reload)\010\010\009wait(1.25)\010\010\009enabled = true\010\010end\010\010function onEquipped()\010\009--Tool.Handle.EquipSound:play()\010end\010\010Tool.Activated:connect(onActivated)\010Tool.Equipped:connect(onEquipped)\010\010while true do\010if Tool.Parent.Attack.Value == true then\010onActivated()\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26841,class="Script",parent=26834,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Welding",["ScriptGuid"]="{09F445FD-76E2-47AB-8366-AE85B6C2AB03}",["Source"]="function Weld(x,y)\013\010\009local W = Instance.new(\034Weld\034)\013\010\009W.Part0 = x\013\010\009W.Part1 = y\013\010\009local CJ = CFrame.new(x.Position)\013\010\009local C0 = x.CFrame:inverse()*CJ\013\010\009local C1 = y.CFrame:inverse()*CJ\013\010\009W.C0 = C0\013\010\009W.C1 = C1\013\010\009W.Parent = x\013\010end\013\010\013\010function Get(A)\013\010\009if A.className == \034Part\034 then\013\010\009\009Weld(script.Parent.Handle, A)\013\010\009\009A.Anchored = false\013\010\009else\013\010\009\009local C = A:GetChildren()\013\010\009\009for i=1, #C do\013\010\009\009Get(C[i])\013\010\009\009end\013\010\009end\013\010end\013\010\013\010function Finale()\013\010\009Get(script.Parent)\013\010end\013\010\013\010script.Parent.Equipped:connect(Finale)\013\010script.Parent.Unequipped:connect(Finale)\013\010Finale()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26879,class="Script",parent=26661,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{88115424-9F8B-40C9-B132-5C9E06A00C0D}",["Source"]="function waitForChild(parent, childName)\010\010 \009while true do\010\010 \009\009local child = parent:findFirstChild(childName)\010\010 \009\009if child then\010\010 \009\009\009return child\010\010 \009\009end\010\010 \009\009parent.ChildAdded:wait()\010\010 \009end\010\010 end\010\010 local Figure = script.Parent\010\010 local Torso = waitForChild(Figure, \034Torso\034)\010\010 local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010\010 local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010\010 local RightHip = waitForChild(Torso, \034Right Hip\034)\010\010 local LeftHip = waitForChild(Torso, \034Left Hip\034)\010\010 local Neck = waitForChild(Torso, \034Neck\034)\010\010 local Humanoid = waitForChild(Figure, \034Humanoid\034)\010\010 local pose = \034Standing\034\010\010 \010\010 local toolAnim = \034None\034\010\010 local toolAnimTime = 0\010\010 \010\010 local isSeated = false\010\010 \010\010 -- functions\010\010 \010\010 function onRunning(speed)\010\010 \009if isSeated then return end\010\010 \010\010 \009if speed>0 then\010\010 \009\009pose = \034Running\034\010\010 \009else\010\010 \009\009pose = \034Standing\034\010\010 \009end\010\010 end\010\010 \010\010 function onDied()\010\010 \009pose = \034Dead\034\010\010 end\010\010 \010\010 function onJumping()\010\010 \009isSeated = false\010\010 \009pose = \034Jumping\034\010\010 end\010\010 \010\010 function onClimbing()\010\010 \009pose = \034Climbing\034\010\010 end\010\010 \010\010 function onGettingUp()\010\010 \009pose = \034GettingUp\034\010\010 end\010\010 \010\010 function onFreeFall()\010\010 \009pose = \034FreeFall\034\010\010 end\010\010 \010\010 function onFallingDown()\010\010 \009pose = \034FallingDown\034\010\010 end\010\010 \010\010 function onSeated()\010\010 \009isSeated = true\010\010 \009pose = \034Seated\034\010\010 \009print(\034Seated\034)\010\010 end\010\010 \010\010 function moveJump()\010\010 \009RightShoulder.MaxVelocity = 0.5\010\010 \009LeftShoulder.MaxVelocity = 0.5\010\010 \009RightShoulder.DesiredAngle = 3.14\010\010 \009LeftShoulder.DesiredAngle = -3.14\010\010 \009RightHip.DesiredAngle = 0\010\010 \009LeftHip.DesiredAngle = 0\010\010 end\010\010 \010\010-- same as jump for now\010\010function moveFreeFall()\010\010 \009RightShoulder.MaxVelocity = 0.5\010\010 \009LeftShoulder.MaxVelocity = 0.5\010\010 \009RightShoulder.DesiredAngle = 3.14\010\010 \009LeftShoulder.DesiredAngle = -3.14\010\010 \009RightHip.DesiredAngle = 0\010\010 \009LeftHip.DesiredAngle = 0\010\010 end\010\010 \010\010 function moveSit()\010\010 \009print(\034Move Sit\034)\010\010 \009RightShoulder.MaxVelocity = 0.15\010\010 \009LeftShoulder.MaxVelocity = 0.15\010\010 \009RightShoulder.DesiredAngle = 3.14 /2\010\010 \009LeftShoulder.DesiredAngle = -3.14 /2\010\010 \009RightHip.DesiredAngle = 3.14 /2\010\010 \009LeftHip.DesiredAngle = -3.14 /2\010\010 end\010\010 \010\010 function getTool()\010\010 \009\010\010 \009kidTable = Figure:children()\010\010 \009if (kidTable ~= nil) then\010\010 \009\009numKids = #kidTable\010\010 \009\009for i=1,numKids do\010\010 \009\009\009if (kidTable[i].className == \034Tool\034) then return kidTable[i] end\010\010 \009\009end\010\010 \009end\010\010 \009\010\010 \009return nil\010\010 end\010\010 \010\010 function getToolAnim(tool)\010\010 \010\010 \009c = tool:children()\010\010 \009for i=1,#c do\010\010 \009\009if (c[i].Name == \034toolanim\034 and c[i].className == \034StringValue\034) then\010\010 \009\009\009return c[i]\010\010 \009\009end\010\010 \009end\010\010 \009return nil\010\010 end\010\010 \010\010 function animateTool()\010\010 \009\010\010 \009if (toolAnim == \034None\034) then\010\010 \009\009RightShoulder.DesiredAngle = 1.57\010\010 \009\009return\010\010 \009end\010\010 \010\010 \009if (toolAnim == \034Slash\034) then\010\010 \009\009RightShoulder.MaxVelocity = 0.5\010\010 \009\009RightShoulder.DesiredAngle = 0\010\010 \009\009return\010\010 \009end\010\010 \010\010 \009if (toolAnim == \034Lunge\034) then\010\010 \009\009RightShoulder.MaxVelocity = 0.5\010\010 \009\009LeftShoulder.MaxVelocity = 0.5\010\010 \009\009RightHip.MaxVelocity = 0.5\010\010 \009\009LeftHip.MaxVelocity = 0.5\010\010 \009\009RightShoulder.DesiredAngle = 1.57\010\010 \009\009LeftShoulder.DesiredAngle = 1.0\010\010 \009\009RightHip.DesiredAngle = 1.57\010\010 \009\009LeftHip.DesiredAngle = 1.0\010\010 \009\009return\010\010 \009end\010\010 end\010\010 \010\010 function move(time)\010\010 \009local amplitude\010\010 \009local frequency\010\010 \010\010 \009if (pose == \034Jumping\034) then\010\010 \009\009moveJump()\010\010 \009\009return\010\010 \009end\010\010 \010\010 \009if (pose == \034FreeFall\034) then\010\010 \009\009moveFreeFall()\010\010 \009\009return\010\010 \009end\010\010  \010\010 \009if (pose == \034Seated\034) then\010\010 \009\009moveSit()\010\010 \009\009return\010\010 \009end\010\010  \010\010 \009local climbFudge = 0\010\010 \009\010\010 \009if (pose == \034Running\034) then\010\010 \009\009RightShoulder.MaxVelocity = 0.15\010\010 \009\009LeftShoulder.MaxVelocity = 0.15\010\010 \009\009amplitude = 1\010\010 \009\009frequency = 9\010\010 \009elseif (pose == \034Climbing\034) then\010\010 \009\009RightShoulder.MaxVelocity = 0.5 \010\010 \009\009LeftShoulder.MaxVelocity = 0.5\010\010  \009\009amplitude = 1\010\010 \009\009frequency = 9\010\010 \009\009climbFudge = 3.14\010\010 \009else\010\010 \009\009amplitude = 0.1\010\010 \009\009frequency = 1\010\010 \009end\010\010 \010\010 \009desiredAngle = amplitude * math.sin(time*frequency)\010\010 \010\010 \009RightShoulder.DesiredAngle = desiredAngle + climbFudge\010\010 \009LeftShoulder.DesiredAngle = desiredAngle - climbFudge\010\010 \009RightHip.DesiredAngle = -desiredAngle\010\010 \009LeftHip.DesiredAngle = -desiredAngle\010\010 \010\010 \010\010 \009local tool = getTool()\010\010 \010\010 \009if tool ~= nil then\010\010 \009\010\010 \009\009animStringValueObject = getToolAnim(tool)\010\010 \010\010 \009\009if animStringValueObject ~= nil then\010\010 \009\009\009toolAnim = animStringValueObject.Value\010\010 \009\009\009-- message recieved, delete StringValue\010\010 \009\009\009animStringValueObject.Parent = nil\010\010 \009\009\009toolAnimTime = time + .3\010\010 \009\009end\010\010 \010\010 \009\009if time > toolAnimTime then\010\010 \009\009\009toolAnimTime = 0\010\010 \009\009\009toolAnim = \034None\034\010\010 \009\009end\010\010 \010\010 \009\009animateTool()\010\010 \010\010 \009\009\010\010 \009else\010\010 \009\009toolAnim = \034None\034\010\010 \009\009toolAnimTime = 0\010\010 \009end\010\010 end\010\010 \010\010 \010\010 -- connect events\010\010 \010\010 Humanoid.Died:connect(onDied)\010\010 Humanoid.Running:connect(onRunning)\010\010 Humanoid.Jumping:connect(onJumping)\010\010 Humanoid.Climbing:connect(onClimbing)\010\010 Humanoid.GettingUp:connect(onGettingUp)\010\010 Humanoid.FreeFalling:connect(onFreeFall)\010\010 Humanoid.FallingDown:connect(onFallingDown)\010\010 Humanoid.Seated:connect(onSeated)\010\010 \010\010 -- main program\010\010 \010\010 local nextTime = 0\010\010 local runService = game:service(\034RunService\034);\010\010 \010\010 while Figure.Parent~=nil do\010\010 \009time = runService.Stepped:wait()\010\010 \009if time > nextTime then\010\010 \009\009move(time)\010\010 \009\009nextTime = time + 0.1\010\010 \009end\010\010 end\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26882,class="Script",parent=26661,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="FF",["ScriptGuid"]="{F1F06E07-B176-4073-9AA6-AFD40B4BFC4E}",["Source"]="ff = Instance.new(\034ForceField\034)\010ff.Parent = script.Parent\010wait(1)\010ff:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26883,class="Script",parent=26661,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{D1684D2D-A560-4247-B963-71E214F274BA}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009\009if dist < 50 then \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 0\010\009\009\009\009script.Parent.Attack.Value = true \010\009\009\009else \010\009\009\009\009script.Parent.Humanoid.WalkSpeed = 5\010\009\009\009\009script.Parent.Attack.Value = false \010\009\009\009end \010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = math.random(0,0)\010\009\009ry = math.random(0,0)\010\009\009rz = math.random(0,0)\010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26884,class="Script",parent=26661,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Damage",["ScriptGuid"]="{4DFC4517-1236-4702-AF58-5100ECE7158F}",["Source"]="robloxia = script.Parent\010smoke = robloxia.Torso:findFirstChild(\034Smoke\034)\010wait(1.1)\010while true do\010if robloxia.Humanoid.Health < 4000 then\010\009smoke.Enabled = true\010\009wait()\010\009script.Disabled = true\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26885,class="Script",parent=26661,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Damage2",["ScriptGuid"]="{76FB7BE5-B493-414E-A4A1-C4343F840630}",["Source"]="robloxia = script.Parent\010wait(1.1)\010while true do\010if robloxia.Humanoid.Health < 2000 then\010\009while true do\010\009\009exp = Instance.new(\034Explosion\034, workspace)\010\009\009exp.Position = robloxia.Torso.Position + Vector3.new(math.random(-10,10),math.random(-10,10),math.random(-10,10))\010\009\009exp.BlastRadius = 2.25\010\009\009exp.BlastPressure = 0\010\009\009wait(0.5)\010\009end\010end\010wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26886,class="Script",parent=26661,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{6FA9834E-5364-48EF-9C27-97528C5547F8}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009game.Debris:AddItem(script.Parent,30)\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009game.workspace.Scripts.WaveScript.Dead_Zombies.Value = game.workspace.Scripts.WaveScript.Dead_Zombies.Value + 1\010\009wait(5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26887,class="Script",parent=26661,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{B84AA3B0-7152-4C56-8FF9-8993569198F5}",["Source"]="human = script.Parent.Humanoid\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Torso.Death:Play()\010\009e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-50,50),math.random(0,100),math.random(-50,50))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\009\009for i = 1,10 do\010\009\009local minion = game.Lighting[\034Noob\034]:clone()\010\009\009minion.Parent = Workspace\010\009\009minion:MoveTo(script.Parent.Torso.Position + Vector3.new(math.random(-15,15),0,math.random(-15,15)))\010\009\009minion[\034Humanoid\034].Jump = true\010\009end\010\010\009wait(3)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26891,class="Script",parent=26661,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="money kill",["ScriptGuid"]="{11677958-0F0B-4EA4-B660-9BDB35649A06}",["Source"]="local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then \010Leaderstats.Coin.Value = Leaderstats.Coin.Value + 1000 --Change Money to the stat that is increased. \010wait(0.1) \010script:remove() \010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) ",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26892,class="Script",parent=26661,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="PP",["ScriptGuid"]="{1AB864CF-4567-4166-BB53-E04BC32D9D63}",["Source"]="print(\034Hello world!\034)\010\010Character = script.Parent\010Humanoid = Character.Humanoid\010Torso = Character.Torso\010\010local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then\010game:GetService(\034PointsService\034):AwardPoints(tag.Value.userId,1000)\010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) \010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26931,class="Script",parent=26893,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Server",["ScriptGuid"]="{6560A866-947B-4078-B350-45B852ADEE0A}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player\010local Character\010local Humanoid\010local TEAM\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local ChangeAmmoAndClip = script:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = script:WaitForChild(\034InflictTarget\034)\010local Grip2\010local Handle2\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,1)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local AmmoValue = script:FindFirstChild(\034Ammo\034) or Instance.new(\034NumberValue\034,script)\010AmmoValue.Name = \034Ammo\034\010AmmoValue.Value = Module.AmmoPerClip\010local ClipsValue = script:FindFirstChild(\034Clips\034) or Instance.new(\034NumberValue\034,script)\010ClipsValue.Name = \034Clips\034\010ClipsValue.Value = Module.LimitedClipEnabled and Module.Clips or 0\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009local IdleAnim = Instance.new(\034Animation\034,Tool)\010\009IdleAnim.Name = \034IdleAnim\034\010\009IdleAnim.AnimationId = \034rbxassetid://\034..(Module.DualEnabled and 53610688 or Module.IdleAnimationID)\010end\010if Module.FireAnimationID ~= nil then\010\009local FireAnim = Instance.new(\034Animation\034,Tool)\010\009FireAnim.Name = \034FireAnim\034\010\009FireAnim.AnimationId = \034rbxassetid://\034..Module.FireAnimationID\010end\010if Module.ReloadAnimationID ~= nil then\010\009local ReloadAnim = Instance.new(\034Animation\034,Tool)\010\009ReloadAnim.Name = \034ReloadAnim\034\010\009ReloadAnim.AnimationId = \034rbxassetid://\034..Module.ReloadAnimationID\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009local ShotgunClipinAnim = Instance.new(\034Animation\034,Tool)\010\009ShotgunClipinAnim.Name = \034ShotgunClipinAnim\034\010\009ShotgunClipinAnim.AnimationId = \034rbxassetid://\034..Module.ShotgunClipinAnimationID\010end\010\010ChangeAmmoAndClip.OnServerEvent:connect(function(Player,Ammo,Clips)\010\009AmmoValue.Value = Ammo\010\009ClipsValue.Value = Clips\010end)\010InflictTarget.OnServerEvent:connect(function(Player,TargetHumanoid,TargetTorso,Damage,Direction,Knockback,Lifesteal,FlamingBullet)\010\009if Player and TargetHumanoid and TargetHumanoid.Health ~= 0 and TargetTorso then\010\009\009while TargetHumanoid:FindFirstChild(\034creator\034) do\010\009\009\009TargetHumanoid.creator:Destroy()\010\009\009end\010\009\009local creator = Instance.new(\034ObjectValue\034,TargetHumanoid)\010\009\009creator.Name = \034creator\034\010\009\009creator.Value = Player\010\009\009game.Debris:AddItem(creator,5)\010\009\009TargetHumanoid:TakeDamage(Damage)\010\009\009if Knockback > 0 then\010\009\009\009TargetTorso.Velocity = Direction * Knockback\010\009\009end\010\009\009if Lifesteal > 0 and Humanoid and Humanoid.Health ~= 0 then\010\009\009\009Humanoid.Health = Humanoid.Health + (Damage*Lifesteal)\010\009\009end\010\009\009if FlamingBullet then\010\009\009\009local Debuff = TargetHumanoid.Parent:FindFirstChild(\034IgniteScript\034) or script.IgniteScript:Clone()\010\009\009\009Debuff.creator.Value = Player\010\009\009\009Debuff.Disabled = false\010\009\009\009Debuff.Parent = TargetHumanoid.Parent\010\009\009end\010\009end\010end)\010\010Tool.Equipped:connect(function()\010\009Player = game.Players:GetPlayerFromCharacter(Tool.Parent)\010\009Character = Tool.Parent\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009TEAM = Character:FindFirstChild(\034TEAM\034)\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010\010Tool.Unequipped:connect(function()\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26934,class="Script",parent=26931,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="IgniteScript",["ScriptGuid"]="{0044918E-D5AF-4901-9268-5DBBD9ADBF99}",["Source"]="local Humanoid = script.Parent:FindFirstChild(\034Humanoid\034)\010local Torso = script.Parent:FindFirstChild(\034Torso\034)\010local Fires = {}\010local FireDamagePerSecond = 5\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010if Humanoid and Torso then\010\009BurnSound = Instance.new(\034Sound\034)\010\009BurnSound.Name = \034BurnSound\034\010\009BurnSound.SoundId = \034http://www.roblox.com/asset/?id=32791565\034\010\009BurnSound.Parent = Torso\010\009BurnSound.Volume = 1\010\009game.Debris:AddItem(BurnSound,10)\010\009Delay(0,function()\010\009\009BurnSound:Play()\010\009end)\010\009for _,parts in pairs(script.Parent:GetChildren()) do\010\009\009if parts.className == \034Part\034 or parts.className == \034WedgePart\034 or parts.className == \034CornerWedgePart\034 then\010\009\009\009local firer = Instance.new(\034Fire\034)\010\009\009\009table.insert(Fires,firer)\010\009\009\009firer.Size = 5 + (parts.Size.magnitude*1.5)\010\009\009\009firer.Parent = parts\010\009\009end\010\009end\010\009while script.Duration.Value > 0 do\010\009\009wait(0.1)\010\009\009script.Duration.Value = script.Duration.Value - 0.1\010\009\009while Humanoid:FindFirstChild(\034creator\034) do\010\009\009\009Humanoid.creator:Destroy()\010\009\009end\010\009\009local Tag = script.creator:clone()\010\009\009Tag.Parent = Humanoid\010\009\009game.Debris:AddItem(Tag,5)\010\009\009Humanoid:TakeDamage(FireDamagePerSecond*0.1)\010\009end\010\009for _, Fire in pairs(Fires) do\010\009\009Fire.Enabled = false\010\009end\010\009wait(5)\010\009for _, Fire in pairs(Fires) do\010\009\009Fire:Destroy()\010\009end\010end\010wait()\010script:remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=26937,class="Script",parent=26893,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="CHANGE LOG",["ScriptGuid"]="{68CE6C7C-0962-4304-869B-387630CD3D90}",["Source"]="--[[\010\009\010v1.0.6\010==================================================\010-Fixed a glitch which player can shooting even after died\010-Added \034ChargedShot\034 setting\010-Added \034Minigun\034 setting\010-Added \034Piercing\034 setting\010-Added \034FadeTime\034 setting\010-Updated \034BulletVisualizerScript\034. Replace an older one now!\010==================================================\010\009\010v1.0.5\010==================================================\010-Fixed a gun that shoot slower even you set \034FireRate\034 to lower\010-Added \034ShotgunReload\034 setting\010==================================================\010\009\010v1.0.4\010==================================================\010-Fixed VisualizeBulletScript and BulletVisualizerScript. Previously, it's a bug that doesn't show bullet for other player.\010-Fixed a bug which scope still in use even unequipped\010==================================================\010\009\010v1.0.3\010==================================================\010-Fixed a bug that you can reload a gun even unequip\010-Ray start position is now at Player's Head instead Gun Muzzle\010-Added \034DualEnabled\034 setting\010-Added Ammo Box for the gun\010-User can no longer use Scope while reloading\010==================================================\010\009\010v1.0.2\010==================================================\010-Fixed Bullet Visualizer that doesn't display fake bullet to other player\010-Fixed fake bullet still displayed even \034VisualizerEnabled\034 is disabled\010==================================================\010\009\010v1.0.1\010==================================================\010-Fixed reload\010-Ammo GUI will not show if AmmoPerClip is \034math.huge\034\010-Added Animation setting\010==================================================\010\009\010v1.0\010==================================================\010-First release\010==================================================\010\009\010--]]",["SourceAssetId"]=-1,["Tags"]=""}}
