T[#T+1]={id=27208,class="Script",parent=27170,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Server",["ScriptGuid"]="{CE53D6FA-E529-4DBB-A84A-E6249E5D5663}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player\010local Character\010local Humanoid\010local TEAM\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local ChangeAmmoAndClip = script:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = script:WaitForChild(\034InflictTarget\034)\010local Grip2\010local Handle2\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,1)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local AmmoValue = script:FindFirstChild(\034Ammo\034) or Instance.new(\034NumberValue\034,script)\010AmmoValue.Name = \034Ammo\034\010AmmoValue.Value = Module.AmmoPerClip\010local ClipsValue = script:FindFirstChild(\034Clips\034) or Instance.new(\034NumberValue\034,script)\010ClipsValue.Name = \034Clips\034\010ClipsValue.Value = Module.LimitedClipEnabled and Module.Clips or 0\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009local IdleAnim = Instance.new(\034Animation\034,Tool)\010\009IdleAnim.Name = \034IdleAnim\034\010\009IdleAnim.AnimationId = \034rbxassetid://\034..(Module.DualEnabled and 53610688 or Module.IdleAnimationID)\010end\010if Module.FireAnimationID ~= nil then\010\009local FireAnim = Instance.new(\034Animation\034,Tool)\010\009FireAnim.Name = \034FireAnim\034\010\009FireAnim.AnimationId = \034rbxassetid://\034..Module.FireAnimationID\010end\010if Module.ReloadAnimationID ~= nil then\010\009local ReloadAnim = Instance.new(\034Animation\034,Tool)\010\009ReloadAnim.Name = \034ReloadAnim\034\010\009ReloadAnim.AnimationId = \034rbxassetid://\034..Module.ReloadAnimationID\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009local ShotgunClipinAnim = Instance.new(\034Animation\034,Tool)\010\009ShotgunClipinAnim.Name = \034ShotgunClipinAnim\034\010\009ShotgunClipinAnim.AnimationId = \034rbxassetid://\034..Module.ShotgunClipinAnimationID\010end\010\010ChangeAmmoAndClip.OnServerEvent:connect(function(Player,Ammo,Clips)\010\009AmmoValue.Value = Ammo\010\009ClipsValue.Value = Clips\010end)\010InflictTarget.OnServerEvent:connect(function(Player,TargetHumanoid,TargetTorso,Damage,Direction,Knockback,Lifesteal,FlamingBullet)\010\009if Player and TargetHumanoid and TargetHumanoid.Health ~= 0 and TargetTorso then\010\009\009while TargetHumanoid:FindFirstChild(\034creator\034) do\010\009\009\009TargetHumanoid.creator:Destroy()\010\009\009end\010\009\009local creator = Instance.new(\034ObjectValue\034,TargetHumanoid)\010\009\009creator.Name = \034creator\034\010\009\009creator.Value = Player\010\009\009game.Debris:AddItem(creator,5)\010\009\009TargetHumanoid:TakeDamage(Damage)\010\009\009if Knockback > 0 then\010\009\009\009TargetTorso.Velocity = Direction * Knockback\010\009\009end\010\009\009if Lifesteal > 0 and Humanoid and Humanoid.Health ~= 0 then\010\009\009\009Humanoid.Health = Humanoid.Health + (Damage*Lifesteal)\010\009\009end\010\009\009if FlamingBullet then\010\009\009\009local Debuff = TargetHumanoid.Parent:FindFirstChild(\034IgniteScript\034) or script.IgniteScript:Clone()\010\009\009\009Debuff.creator.Value = Player\010\009\009\009Debuff.Disabled = false\010\009\009\009Debuff.Parent = TargetHumanoid.Parent\010\009\009end\010\009end\010end)\010\010Tool.Equipped:connect(function()\010\009Player = game.Players:GetPlayerFromCharacter(Tool.Parent)\010\009Character = Tool.Parent\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009TEAM = Character:FindFirstChild(\034TEAM\034)\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010\010Tool.Unequipped:connect(function()\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27211,class="Script",parent=27208,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="IgniteScript",["ScriptGuid"]="{18E12B5C-A6FA-4E35-A336-EA416E0E58C2}",["Source"]="local Humanoid = script.Parent:FindFirstChild(\034Humanoid\034)\010local Torso = script.Parent:FindFirstChild(\034Torso\034)\010local Fires = {}\010local FireDamagePerSecond = 5\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010if Humanoid and Torso then\010\009BurnSound = Instance.new(\034Sound\034)\010\009BurnSound.Name = \034BurnSound\034\010\009BurnSound.SoundId = \034http://www.roblox.com/asset/?id=32791565\034\010\009BurnSound.Parent = Torso\010\009BurnSound.Volume = 1\010\009game.Debris:AddItem(BurnSound,10)\010\009Delay(0,function()\010\009\009BurnSound:Play()\010\009end)\010\009for _,parts in pairs(script.Parent:GetChildren()) do\010\009\009if parts.className == \034Part\034 or parts.className == \034WedgePart\034 or parts.className == \034CornerWedgePart\034 then\010\009\009\009local firer = Instance.new(\034Fire\034)\010\009\009\009table.insert(Fires,firer)\010\009\009\009firer.Size = 5 + (parts.Size.magnitude*1.5)\010\009\009\009firer.Parent = parts\010\009\009end\010\009end\010\009while script.Duration.Value > 0 do\010\009\009wait(0.1)\010\009\009script.Duration.Value = script.Duration.Value - 0.1\010\009\009while Humanoid:FindFirstChild(\034creator\034) do\010\009\009\009Humanoid.creator:Destroy()\010\009\009end\010\009\009local Tag = script.creator:clone()\010\009\009Tag.Parent = Humanoid\010\009\009game.Debris:AddItem(Tag,5)\010\009\009Humanoid:TakeDamage(FireDamagePerSecond*0.1)\010\009end\010\009for _, Fire in pairs(Fires) do\010\009\009Fire.Enabled = false\010\009end\010\009wait(5)\010\009for _, Fire in pairs(Fires) do\010\009\009Fire:Destroy()\010\009end\010end\010wait()\010script:remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27214,class="Script",parent=27170,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="CHANGE LOG",["ScriptGuid"]="{5FBA1CE9-7FD7-44EE-80D0-93236B6655DC}",["Source"]="--[[\010\009\010v1.0.6\010==================================================\010-Fixed a glitch which player can shooting even after died\010-Added \034ChargedShot\034 setting\010-Added \034Minigun\034 setting\010-Added \034Piercing\034 setting\010-Added \034FadeTime\034 setting\010-Updated \034BulletVisualizerScript\034. Replace an older one now!\010==================================================\010\009\010v1.0.5\010==================================================\010-Fixed a gun that shoot slower even you set \034FireRate\034 to lower\010-Added \034ShotgunReload\034 setting\010==================================================\010\009\010v1.0.4\010==================================================\010-Fixed VisualizeBulletScript and BulletVisualizerScript. Previously, it's a bug that doesn't show bullet for other player.\010-Fixed a bug which scope still in use even unequipped\010==================================================\010\009\010v1.0.3\010==================================================\010-Fixed a bug that you can reload a gun even unequip\010-Ray start position is now at Player's Head instead Gun Muzzle\010-Added \034DualEnabled\034 setting\010-Added Ammo Box for the gun\010-User can no longer use Scope while reloading\010==================================================\010\009\010v1.0.2\010==================================================\010-Fixed Bullet Visualizer that doesn't display fake bullet to other player\010-Fixed fake bullet still displayed even \034VisualizerEnabled\034 is disabled\010==================================================\010\009\010v1.0.1\010==================================================\010-Fixed reload\010-Ammo GUI will not show if AmmoPerClip is \034math.huge\034\010-Added Animation setting\010==================================================\010\009\010v1.0\010==================================================\010-First release\010==================================================\010\009\010--]]",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27550,class="Script",parent=27537,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Firescript",["ScriptGuid"]="{99839274-F32C-494C-BD9E-FB6448F46CD6}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010check=true\010\010gundamage=20\009\009\009\009\009\009\009\009--Base output damage per shot.\010firerate=.1\009\009\009\009\009\009\009\009--How often the weapon can fire.\010automatic=true\009\009\009\009\009\009\009--hold down to continue firing\010range=1000\009\009\009\009\009\009\009\009\009--Max distance that the weapon can fire.\010spread=2\009\009\009\009\009\009\009\009\009\009--The bigger the spread, the more inaccurate the shots will be.\010clipsize=math.huge\009\009\009\009\009\009\009\009--Shots in a clip\010reloadtime=3\009\009\009\009\009\009\009\009--Time it takes to reload the tool.\010startingclips=10\009\009\009\009\009\009\009--If you want infinit clips, remove the IntValue named \034Clips\034 from the tool.\010segmentlength=25\009\009\009\009\009\009\009--How long the shot segments are, or the speed of the shot.\010fadedelaytime=1/30\010\010\010barrelpos=CFrame.new(0,0,-2.7)\009\009--R,U,B\010rate=1/100\010intangibles={\034Shock\034,\034Bolt\034,\034Bullet\034,\034Plasma\034,\034Effect\034,\034Laser\034,\034Handle\034,\034Effects\034,\034Effect\034,\034Flash\034}\010colors={BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034)}\010flashcolors={\034Bright yellow\034}\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010reloading=false\010local debris=game:GetService(\034Debris\034)\010\010local ammo=sp:FindFirstChild(\034Ammo\034)\010if ammo~=nil then\010\009ammo.Value=clipsize\010end\010local clips=sp:FindFirstChild(\034Clips\034)\010if clips~=nil then\010\009clips.Value=startingclips\010end\010\010sp.Equipped:connect(function()\010\009sp.Parent.Arm2.Fire:Stop()\010\009sp.Parent.Arm2.Reload:Stop()\010end)\010sp.Unequipped:connect(function()\010\009sp.Parent.Arm2.Fire:Stop()\010\009sp.Parent.Arm2.Reload:Stop()\010end)\010\010function round(number,decimal)\010\009decimal=decimal or 0\010\009local mult=10^decimal\010\009return math.floor(number*mult+.5)/mult\010end\010\010function checkintangible(t)\010\009for i3,v3 in ipairs(intangibles) do\010\009\009if string.lower(v3)==string.lower(t.Name) or t.Transparency==1 then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function reload()\010\009reloading=true\010\009sp.Reloading.Value=true\010\009if clips~=nil then\010\009\009if clips.Value>0 then\010\009\009\009clips.Value=clips.Value-1\010\009\009else\010\009\009\009reloading=false\010\009\009\009sp.Reloading.Value=false\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Arm2.Reload:Play()\010\009for i=1,clipsize do\010\009\009wait(reloadtime/clipsize)\010\009\009ammo.Value=i\010\009end\010\009reloading=false\010\009sp.Reloading.Value=false\010end\010\010function castray(startpos,vec,length,ignore,delayifhit)\010\009if length>999 then\010\009\009length=999\010\009end\010\009hit,endpos2=game.Workspace:FindPartOnRay(Ray.new(startpos,vec*length),ignore)\010\009if hit~=nil then\010\009\009if checkintangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit,endpos2=castray(endpos2+(vec*.01),vec,length-((startpos-endpos2).magnitude),ignore,delayifhit)\010\009\009end\010\009end\010\009return hit,endpos2\010end\010\010function sendbullet(boltstart,targetpos,fuzzyness,segmentlength,ignore,clr,damage,fadedelay)\010\009if ammo~=nil then\010\009\009if ammo.Value>0 then\010\009\009\009ammo.Value=ammo.Value-1\010\009\009else\010\009\009\009reload()\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Arm2.Fire:Play()\010\009muzzleeffect()\010\009local t=sp.Parent:FindFirstChild(\034Torso\034)\010\009if t~=nil then\010\009\009local shoulder=t:FindFirstChild(\034Right Shoulder\034)\010\009\009if shoulder~=nil then\010\009\009\009shoulder.CurrentAngle=2\010\009\009end\010\009end\010\010\009local boltdist=range\010\009local clickdist=(boltstart-targetpos).magnitude\010\009local targetpos=targetpos+(Vector3.new(math.random()-.5,math.random()-.5,math.random()-.5)*(clickdist/100)*fuzzyness)\010\009local boltvec=(targetpos-boltstart).unit\010\009local totalsegments=math.ceil(boltdist/segmentlength)\010\009local lastpos=boltstart\010\009for i=1,totalsegments do\010\009\009local newpos=(boltstart+(boltvec*(boltdist*(i/totalsegments))))\010\009\009local segvec=(newpos-lastpos).unit\010\009\009local boltlength=(newpos-lastpos).magnitude\010\009\009local bolthit,endpos=castray(lastpos,segvec,boltlength,ignore,false)\010\009\009drawbeam(lastpos,endpos,clr,fadedelay)\010\009\009if bolthit~=nil then\010\009\009\009local h=bolthit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local t=bolthit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h~=nil and t and t.Value ~= sp.Parent.TEAM.Value then\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009end\010\009\009\009break\010\009\009end\010\009\009lastpos=endpos\010\009\009wait(rate)\010\009end\010end\010\010function drawbeam(beamstart,beamend,clr,fadedelay)\010\009local dis=(beamstart-beamend).magnitude\010\009local laser=Instance.new(\034Part\034)\010\009laser.Name=\034Bullet\034\010\009laser.Transparency = 0\010\009laser.Anchored=true\010\009laser.CanCollide=false\010\009laser.Shape=\034Block\034\010\009laser.formFactor=\034Custom\034\010\009laser.Size=Vector3.new(.375,.375,dis+.2)\010\009laser.Material=Enum.Material.Plastic\010\009laser.Locked=true\010\009laser.TopSurface=0\010\009laser.BottomSurface=0\010\009laser.BrickColor=clr\010\009laser.CFrame=CFrame.new(beamend,beamstart)*CFrame.new(0,0,-dis/2)\010\009--[[local mesh = Instance.new(\034BlockMesh\034,laser)\010\009mesh.Scale = Vector3.new(10,0,1)\010\009local decal = Instance.new(\034Decal\034,laser)\010\009decal.Face = \034Top\034\010\009decal.Texture = \034rbxassetid://201063866\034\010\009decal.Transparency = 0.25\010\009local decal2 = decal:Clone()\010\009decal2.Face = \034Bottom\034\010\009decal2.Parent = decal.Parent]]\010\009local light = script.SurfaceLight:Clone()\010\009light.Enabled = true\010\009light.Face = \034Top\034\010\009light.Parent = laser\010\009local light2 = script.SurfaceLight:Clone()\010\009light2.Enabled = true\010\009light.Face = \034Bottom\034\010\009light2.Parent = laser\010\009laser.Parent=game.Workspace\010\009debris:AddItem(laser,fadedelay)\010end\010\010function muzzleeffect()\010\009local flash=Instance.new(\034Part\034)\010\009flash.Name=\034Effect\034\010\009flash.Anchored=true\010\009flash.CanCollide=false\010\009flash.Shape=\034Block\034\010\009flash.formFactor=\034Custom\034\010\009flash.Size=Vector3.new(.2,.2,.2)\010\009flash.Material=Enum.Material.Plastic\010\009flash.Locked=true\010\009flash.TopSurface=0\010\009flash.BottomSurface=0\010\009flash.BrickColor=BrickColor.new(flashcolors[math.random(1,#flashcolors)])\010\009local mesh=Instance.new(\034SpecialMesh\034)\010\009mesh.MeshId=\034http://www.roblox.com/asset/?id=25212400\034\010\009local scale=Vector3.new(.2+(math.random()*.1),.4+(math.random()*.4),.2+(math.random()*.1))\010\009mesh.Scale=scale\010\009mesh.Parent=flash\010\009flash.CFrame=sp.Parent.Arm2.CFrame*barrelpos*CFrame.Angles(0,math.pi*2*math.random(),0)*CFrame.new(0,scale.y*.9,0)\010\009debris:AddItem(flash,rate)\010\009flash.Parent=game.Workspace\010end\010\010sp.Down.Changed:connect(function()\010\009while sp.Down.Value and check and not reloading do\010\009\009check=false\010\009\009local humanoid=sp.Parent:FindFirstChild(\034Humanoid\034)\010\009\009if humanoid~=nil then\010\009\009\009if humanoid.Health>0 then\010\009\009\009\009spos1=(sp.Parent.Arm2.CFrame*barrelpos).p\010\009\009\009\009delay(0,function() sendbullet(spos1,sp.Aim.Value,spread,segmentlength,sp.Parent,colors[1],gundamage,fadedelaytime) end)\010\009\009\009else\010\009\009\009\009check=true\010\009\009\009\009break\010\009\009\009end\010\009\009else\010\009\009\009check=true\010\009\009\009break\010\009\009end\010\009\009wait(firerate)\010\009\009check=true\010\009\009if not automatic then\010\009\009\009break\010\009\009end\010\009end\010end)\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27552,class="Script",parent=27215,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{593C45B8-8B51-47BD-A897-BB956C2A730A}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010\010NPC = script.Parent\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(0.1)\010\009local target = findNearestTorso(script.Parent.Torso.Position)\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 125 and\010\009\009\009 (target.Position - script.Parent.Torso.Position).magnitude > 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser.Down.Value=true\010\009\009\009NPC.EyeLaser2.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser2.Down.Value=true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude < 25 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser.Down.Value=true\010\009\009\009NPC.EyeLaser2.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser2.Down.Value=true\010\009\009\009script.Parent.Humanoid.WalkSpeed = -16\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 125 then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser.Down.Value=true\010\009\009\009NPC.EyeLaser2.Aim.Value = target.Position\010\009\009\009NPC.EyeLaser2.Down.Value=true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 16\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false\010\009\009NPC.EyeLaser.Down.Value=false\010\009\009NPC.EyeLaser2.Down.Value=false\010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27554,class="Script",parent=27215,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{3C2FFD42-14D2-4C6D-85A4-A2184F897638}",["Source"]="local Model = script.Parent\010local Humanoid = Model.Humanoid\010\010function ChooseRandomPart()\010\009local PartToChoose = {}\010\009for _, Child in pairs(Model:GetChildren()) do\010\009\009if Child:IsA(\034BasePart\034) then\010\009\009\009table.insert(PartToChoose,Child)\010\009\009end\010\009end\010\009return PartToChoose[math.random(1,#PartToChoose)]\010end\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Death:Play()\010\009local e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009local parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 or parts[i].className == \034UnionOperation\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-75,75),math.random(75,150),math.random(-75,75))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\009wait(10)\010\009script.Parent:remove() \010end \010\010Humanoid.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27555,class="Script",parent=27215,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="AIUseFPSMode",["ScriptGuid"]="{4B51AD26-D879-43FC-BC38-BAF17C2DC14E}",["Source"]="gyro = Instance.new(\034BodyGyro\034)\010gyro.Parent = script.Parent:findFirstChild(\034Torso\034)\010gyro.P = 7500\010gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\010script.Parent.Humanoid.StateChanged:connect(function(Old,New)\010\009if New == Enum.HumanoidStateType.Running then\010\009\009gyro.P = 7500\010\009\009gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\009else\010\009\009gyro.P = 0\010\009\009gyro.maxTorque = Vector3.new(0,0,0)\010\009end\010end)\010\010while true do\010\009vCharacter = script.Parent\010\009if vCharacter ~= nil then \010\009\009gyro.Parent = script.Parent.Torso\010\009\009local tp\010\009\009if (vCharacter.Target.Value) and vCharacter.Humanoid:GetState() then\010\009\009\009tp = vCharacter.Target.Value.Position\010\009\009else\010\009\009\009tp = vCharacter.Humanoid.WalkToPoint\010\009\009end\010\009\009tp = Vector3.new(tp.X,script.Parent.Torso.Position.Y,tp.Z) \010\009\009local dir = (tp - script.Parent.Torso.Position).unit\010\009\009local spawnPos = script.Parent.Torso.Position\010\009\009local pos = spawnPos + (dir * 1)\010\009\009gyro.cframe = CFrame.new(pos,  pos + dir)\010\009elseif not vCharacter.Attack.Value then\010\009\009gyro.Parent = nil\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27556,class="Script",parent=27215,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{C2480C7A-A7F2-4EA7-AF34-9347FC2381B0}",["Source"]="wait()\010function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010--[[local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)]]\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimInstance = nil\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=583217857\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=583217857\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=583216937\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=180436148\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=180436334\034, weight = 10 } \010\009\009\009}, \010\009sit = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=178130996\034, weight = 10 } \010\009\009\009},\009\010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182393478\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182435998\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491037\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491065\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436842\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491248\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491277\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436935\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491368\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491423\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009currentAnimInstance = nil\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if frameName == \034Footstep1\034 or frameName == \034Footstep2\034 then Figure.FakeTorso[\034Footstep\034..math.random(1,4)]:Play() end\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\010\009\009local repeatAnim = currentAnim\010\009\009-- return to idle if finishing an emote\010\009\009if (emoteNames[repeatAnim] ~= nil and emoteNames[repeatAnim] == false) then\010\009\009\009repeatAnim = \034idle\034\010\009\009end\010\009\009\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid) \010\009\009\010\009local roll = math.random(1, animTable[animName].totalWeight) \010\009local origRoll = roll\010\009local idx = 1\010\009while (roll > animTable[animName][idx].weight) do\010\009\009roll = roll - animTable[animName][idx].weight\010\009\009idx = idx + 1\010\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009local anim = animTable[animName][idx].anim\010\010\009-- switch animation\009\009\010\009if (anim ~= currentAnimInstance) then\010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\009\009currentAnimInstance = anim\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009\009\010\009end\010\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local toolAnimInstance = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\009\010\009\009playToolAnimation(toolAnimName, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\009 \010\009\009\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009if (toolAnimInstance ~= anim) then\010\009\009\009\010\009\009\009if (toolAnimTrack ~= nil) then\010\009\009\009\009toolAnimTrack:Stop()\010\009\009\009\009toolAnimTrack:Destroy()\010\009\009\009\009transitionTime = 0\010\009\009\009end\010\009\009\009\009\009\010\009\009\009-- load it to the humanoid; get AnimationTrack\010\009\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009\009 \010\009\009\009-- play the animation\010\009\009\009toolAnimTrack:Play(transitionTime)\010\009\009\009toolAnimName = animName\010\009\009\009toolAnimInstance = anim\010\010\009\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009toolAnimInstance = nil\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009--[[if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end]]\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009--playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010--[[function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end]]\010\010--[[function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end]]\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009--playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009--playAnimation(\034sit\034, 0.5, Humanoid)\010\009\009return\010\009--[[elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)]]\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009stopAllAnimations()\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009--[[desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)]]\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009--animStringValueObject = getToolAnim(tool)\010\010\009\009--[[if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end]]\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009--animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimInstance = nil\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010--[[Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)]]\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009--[[print((Torso.Velocity * Vector3.new(1,0,1)).magnitude)\010\009print(pose)]]\010\009if (Torso.Velocity * Vector3.new(1,0,1)).magnitude > 1 and pose ~= \034Running\034 then\010\009\009pose = \034Running\034\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (Torso.Velocity * Vector3.new(1,0,1)).magnitude < 1 and pose ~= \034Standing\034 then\010\009\009pose = \034Standing\034\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009end\010\009local _, time = wait(0.01)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27596,class="Script",parent=27583,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Firescript",["ScriptGuid"]="{5364E379-91B4-442F-95B2-7C60202EAF34}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010check=true\010\010gundamage=20\009\009\009\009\009\009\009\009--Base output damage per shot.\010firerate=.1\009\009\009\009\009\009\009\009--How often the weapon can fire.\010automatic=true\009\009\009\009\009\009\009--hold down to continue firing\010range=1000\009\009\009\009\009\009\009\009\009--Max distance that the weapon can fire.\010spread=2\009\009\009\009\009\009\009\009\009\009--The bigger the spread, the more inaccurate the shots will be.\010clipsize=math.huge\009\009\009\009\009\009\009\009--Shots in a clip\010reloadtime=3\009\009\009\009\009\009\009\009--Time it takes to reload the tool.\010startingclips=10\009\009\009\009\009\009\009--If you want infinit clips, remove the IntValue named \034Clips\034 from the tool.\010segmentlength=25\009\009\009\009\009\009\009--How long the shot segments are, or the speed of the shot.\010fadedelaytime=1/30\010\010\010barrelpos=CFrame.new(0,0,-2.7)\009\009--R,U,B\010rate=1/100\010intangibles={\034Shock\034,\034Bolt\034,\034Bullet\034,\034Plasma\034,\034Effect\034,\034Laser\034,\034Handle\034,\034Effects\034,\034Effect\034,\034Flash\034}\010colors={BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034),BrickColor.new(\034Bright yellow\034)}\010flashcolors={\034Bright yellow\034}\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010reloading=false\010local debris=game:GetService(\034Debris\034)\010\010local ammo=sp:FindFirstChild(\034Ammo\034)\010if ammo~=nil then\010\009ammo.Value=clipsize\010end\010local clips=sp:FindFirstChild(\034Clips\034)\010if clips~=nil then\010\009clips.Value=startingclips\010end\010\010sp.Equipped:connect(function()\010\009sp.Parent.Arm1.Fire:Stop()\010\009sp.Parent.Arm1.Reload:Stop()\010end)\010sp.Unequipped:connect(function()\010\009sp.Parent.Arm1.Fire:Stop()\010\009sp.Parent.Arm1.Reload:Stop()\010end)\010\010function round(number,decimal)\010\009decimal=decimal or 0\010\009local mult=10^decimal\010\009return math.floor(number*mult+.5)/mult\010end\010\010function checkintangible(t)\010\009for i3,v3 in ipairs(intangibles) do\010\009\009if string.lower(v3)==string.lower(t.Name) or t.Transparency==1 then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function reload()\010\009reloading=true\010\009sp.Reloading.Value=true\010\009if clips~=nil then\010\009\009if clips.Value>0 then\010\009\009\009clips.Value=clips.Value-1\010\009\009else\010\009\009\009reloading=false\010\009\009\009sp.Reloading.Value=false\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Arm1.Reload:Play()\010\009for i=1,clipsize do\010\009\009wait(reloadtime/clipsize)\010\009\009ammo.Value=i\010\009end\010\009reloading=false\010\009sp.Reloading.Value=false\010end\010\010function castray(startpos,vec,length,ignore,delayifhit)\010\009if length>999 then\010\009\009length=999\010\009end\010\009hit,endpos2=game.Workspace:FindPartOnRay(Ray.new(startpos,vec*length),ignore)\010\009if hit~=nil then\010\009\009if checkintangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit,endpos2=castray(endpos2+(vec*.01),vec,length-((startpos-endpos2).magnitude),ignore,delayifhit)\010\009\009end\010\009end\010\009return hit,endpos2\010end\010\010function sendbullet(boltstart,targetpos,fuzzyness,segmentlength,ignore,clr,damage,fadedelay)\010\009if ammo~=nil then\010\009\009if ammo.Value>0 then\010\009\009\009ammo.Value=ammo.Value-1\010\009\009else\010\009\009\009reload()\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Arm1.Fire:Play()\010\009muzzleeffect()\010\009local t=sp.Parent:FindFirstChild(\034Torso\034)\010\009if t~=nil then\010\009\009local shoulder=t:FindFirstChild(\034Right Shoulder\034)\010\009\009if shoulder~=nil then\010\009\009\009shoulder.CurrentAngle=2\010\009\009end\010\009end\010\010\009local boltdist=range\010\009local clickdist=(boltstart-targetpos).magnitude\010\009local targetpos=targetpos+(Vector3.new(math.random()-.5,math.random()-.5,math.random()-.5)*(clickdist/100)*fuzzyness)\010\009local boltvec=(targetpos-boltstart).unit\010\009local totalsegments=math.ceil(boltdist/segmentlength)\010\009local lastpos=boltstart\010\009for i=1,totalsegments do\010\009\009local newpos=(boltstart+(boltvec*(boltdist*(i/totalsegments))))\010\009\009local segvec=(newpos-lastpos).unit\010\009\009local boltlength=(newpos-lastpos).magnitude\010\009\009local bolthit,endpos=castray(lastpos,segvec,boltlength,ignore,false)\010\009\009drawbeam(lastpos,endpos,clr,fadedelay)\010\009\009if bolthit~=nil then\010\009\009\009local h=bolthit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local t=bolthit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h~=nil and t and t.Value ~= sp.Parent.TEAM.Value then\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009end\010\009\009\009break\010\009\009end\010\009\009lastpos=endpos\010\009\009wait(rate)\010\009end\010end\010\010function drawbeam(beamstart,beamend,clr,fadedelay)\010\009local dis=(beamstart-beamend).magnitude\010\009local laser=Instance.new(\034Part\034)\010\009laser.Name=\034Bullet\034\010\009laser.Transparency = 0\010\009laser.Anchored=true\010\009laser.CanCollide=false\010\009laser.Shape=\034Block\034\010\009laser.formFactor=\034Custom\034\010\009laser.Size=Vector3.new(.375,.375,dis+.2)\010\009laser.Material=Enum.Material.Plastic\010\009laser.Locked=true\010\009laser.TopSurface=0\010\009laser.BottomSurface=0\010\009laser.BrickColor=clr\010\009laser.CFrame=CFrame.new(beamend,beamstart)*CFrame.new(0,0,-dis/2)\010\009--[[local mesh = Instance.new(\034BlockMesh\034,laser)\010\009mesh.Scale = Vector3.new(10,0,1)\010\009local decal = Instance.new(\034Decal\034,laser)\010\009decal.Face = \034Top\034\010\009decal.Texture = \034rbxassetid://201063866\034\010\009decal.Transparency = 0.25\010\009local decal2 = decal:Clone()\010\009decal2.Face = \034Bottom\034\010\009decal2.Parent = decal.Parent]]\010\009local light = script.SurfaceLight:Clone()\010\009light.Enabled = true\010\009light.Face = \034Top\034\010\009light.Parent = laser\010\009local light2 = script.SurfaceLight:Clone()\010\009light2.Enabled = true\010\009light.Face = \034Bottom\034\010\009light2.Parent = laser\010\009laser.Parent=game.Workspace\010\009debris:AddItem(laser,fadedelay)\010end\010\010function muzzleeffect()\010\009local flash=Instance.new(\034Part\034)\010\009flash.Name=\034Effect\034\010\009flash.Anchored=true\010\009flash.CanCollide=false\010\009flash.Shape=\034Block\034\010\009flash.formFactor=\034Custom\034\010\009flash.Size=Vector3.new(.2,.2,.2)\010\009flash.Material=Enum.Material.Plastic\010\009flash.Locked=true\010\009flash.TopSurface=0\010\009flash.BottomSurface=0\010\009flash.BrickColor=BrickColor.new(flashcolors[math.random(1,#flashcolors)])\010\009local mesh=Instance.new(\034SpecialMesh\034)\010\009mesh.MeshId=\034http://www.roblox.com/asset/?id=25212400\034\010\009local scale=Vector3.new(.2+(math.random()*.1),.4+(math.random()*.4),.2+(math.random()*.1))\010\009mesh.Scale=scale\010\009mesh.Parent=flash\010\009flash.CFrame=sp.Parent.Arm1.CFrame*barrelpos*CFrame.Angles(0,math.pi*2*math.random(),0)*CFrame.new(0,scale.y*.9,0)\010\009debris:AddItem(flash,rate)\010\009flash.Parent=game.Workspace\010end\010\010sp.Down.Changed:connect(function()\010\009while sp.Down.Value and check and not reloading do\010\009\009check=false\010\009\009local humanoid=sp.Parent:FindFirstChild(\034Humanoid\034)\010\009\009if humanoid~=nil then\010\009\009\009if humanoid.Health>0 then\010\009\009\009\009spos1=(sp.Parent.Arm1.CFrame*barrelpos).p\010\009\009\009\009delay(0,function() sendbullet(spos1,sp.Aim.Value,spread,segmentlength,sp.Parent,colors[1],gundamage,fadedelaytime) end)\010\009\009\009else\010\009\009\009\009check=true\010\009\009\009\009break\010\009\009\009end\010\009\009else\010\009\009\009check=true\010\009\009\009break\010\009\009end\010\009\009wait(firerate)\010\009\009check=true\010\009\009if not automatic then\010\009\009\009break\010\009\009end\010\009end\010end)\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27598,class="Script",parent=27215,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="HealthBarGUIScript",["ScriptGuid"]="{AAE3447F-0599-4C36-8156-4F0E3E9D7069}",["Source"]="Humanoid = script.Parent.Humanoid\010\010function GainCharge(Humanoid)\010\009Humanoid.Parent.Torso.Healthbar.Frame.Full.Size = UDim2.new(Humanoid.Health/Humanoid.MaxHealth,0,1,0)\010\009if Humanoid.Health >= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(0,200/255,0)\010\009elseif Humanoid.Health >= Humanoid.MaxHealth/4 and Humanoid.Health <= Humanoid.MaxHealth/2 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,200/255,0)\010\009elseif Humanoid.Health <= Humanoid.MaxHealth/4 then\010\009\009Humanoid.Parent.Torso.Healthbar.Frame.Full.BackgroundColor3 = Color3.new(200/255,0,0)\010\009end\010end\010\010Humanoid.HealthChanged:connect(function() GainCharge(Humanoid) end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27599,class="Script",parent=27215,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{C861A41F-230F-4AB5-B708-75EAD3CE4407}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009game.workspace.Scripts.WaveScript.Dead_Zombies.Value = game.workspace.Scripts.WaveScript.Dead_Zombies.Value + 1\010\009wait(2.5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27600,class="Script",parent=27215,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="money kill",["ScriptGuid"]="{06031737-5F11-4856-A2A0-DB393F624A8C}",["Source"]="local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then \010Leaderstats.Coin.Value = Leaderstats.Coin.Value + 300 --Change Money to the stat that is increased. \010wait(0.1) \010script:remove() \010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) ",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27601,class="Script",parent=27215,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="PP",["ScriptGuid"]="{A8B9A2E4-943D-4314-8483-37390B806A47}",["Source"]="print(\034Hello world!\034)\010\010Character = script.Parent\010Humanoid = Character.Humanoid\010Torso = Character.Torso\010\010local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then\010game:GetService(\034PointsService\034):AwardPoints(tag.Value.userId,300)\010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) \010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27609,class="Script",parent=27608,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{584BA853-B7B4-4C6A-9ADB-4DA40213FF89}",["Source"]="wait(1)\010script.Parent:Remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27641,class="Script",parent=27602,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="GunScript_Server",["ScriptGuid"]="{6298C3BD-E432-408E-B6D9-E5597959BE1E}",["Source"]="local Tool = script.Parent\010local Handle = Tool:WaitForChild(\034Handle\034)\010local Player\010local Character\010local Humanoid\010local TEAM\010local VisualizeBullet = game.ReplicatedStorage:WaitForChild(\034VisualizeBullet\034)\010local Module = require(Tool:WaitForChild(\034Setting\034))\010local ChangeAmmoAndClip = script:WaitForChild(\034ChangeAmmoAndClip\034)\010local InflictTarget = script:WaitForChild(\034InflictTarget\034)\010local Grip2\010local Handle2\010\010if Module.DualEnabled then\010\009Handle2 = Tool:WaitForChild(\034Handle2\034,1)\010\009if Handle2 == nil and Module.DualEnabled then error(\034\092\034Dual\092\034 setting is enabled but \092\034Handle2\092\034 is missing!\034) end\010end\010\010local AmmoValue = script:FindFirstChild(\034Ammo\034) or Instance.new(\034NumberValue\034,script)\010AmmoValue.Name = \034Ammo\034\010AmmoValue.Value = Module.AmmoPerClip\010local ClipsValue = script:FindFirstChild(\034Clips\034) or Instance.new(\034NumberValue\034,script)\010ClipsValue.Name = \034Clips\034\010ClipsValue.Value = Module.LimitedClipEnabled and Module.Clips or 0\010\010if Module.IdleAnimationID ~= nil or Module.DualEnabled then\010\009local IdleAnim = Instance.new(\034Animation\034,Tool)\010\009IdleAnim.Name = \034IdleAnim\034\010\009IdleAnim.AnimationId = \034rbxassetid://\034..(Module.DualEnabled and 53610688 or Module.IdleAnimationID)\010end\010if Module.FireAnimationID ~= nil then\010\009local FireAnim = Instance.new(\034Animation\034,Tool)\010\009FireAnim.Name = \034FireAnim\034\010\009FireAnim.AnimationId = \034rbxassetid://\034..Module.FireAnimationID\010end\010if Module.ReloadAnimationID ~= nil then\010\009local ReloadAnim = Instance.new(\034Animation\034,Tool)\010\009ReloadAnim.Name = \034ReloadAnim\034\010\009ReloadAnim.AnimationId = \034rbxassetid://\034..Module.ReloadAnimationID\010end\010if Module.ShotgunClipinAnimationID ~= nil then\010\009local ShotgunClipinAnim = Instance.new(\034Animation\034,Tool)\010\009ShotgunClipinAnim.Name = \034ShotgunClipinAnim\034\010\009ShotgunClipinAnim.AnimationId = \034rbxassetid://\034..Module.ShotgunClipinAnimationID\010end\010\010ChangeAmmoAndClip.OnServerEvent:connect(function(Player,Ammo,Clips)\010\009AmmoValue.Value = Ammo\010\009ClipsValue.Value = Clips\010end)\010InflictTarget.OnServerEvent:connect(function(Player,TargetHumanoid,TargetTorso,Damage,Direction,Knockback,Lifesteal,FlamingBullet)\010\009if Player and TargetHumanoid and TargetHumanoid.Health ~= 0 and TargetTorso then\010\009\009while TargetHumanoid:FindFirstChild(\034creator\034) do\010\009\009\009TargetHumanoid.creator:Destroy()\010\009\009end\010\009\009local creator = Instance.new(\034ObjectValue\034,TargetHumanoid)\010\009\009creator.Name = \034creator\034\010\009\009creator.Value = Player\010\009\009game.Debris:AddItem(creator,5)\010\009\009TargetHumanoid:TakeDamage(Damage)\010\009\009if Knockback > 0 then\010\009\009\009TargetTorso.Velocity = Direction * Knockback\010\009\009end\010\009\009if Lifesteal > 0 and Humanoid and Humanoid.Health ~= 0 then\010\009\009\009Humanoid.Health = Humanoid.Health + (Damage*Lifesteal)\010\009\009end\010\009\009if FlamingBullet then\010\009\009\009local Debuff = TargetHumanoid.Parent:FindFirstChild(\034IgniteScript\034) or script.IgniteScript:Clone()\010\009\009\009Debuff.creator.Value = Player\010\009\009\009Debuff.Disabled = false\010\009\009\009Debuff.Parent = TargetHumanoid.Parent\010\009\009end\010\009end\010end)\010\010Tool.Equipped:connect(function()\010\009Player = game.Players:GetPlayerFromCharacter(Tool.Parent)\010\009Character = Tool.Parent\010\009Humanoid = Character:FindFirstChild(\034Humanoid\034)\010\009TEAM = Character:FindFirstChild(\034TEAM\034)\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = false\010\009\009local LeftArm = Tool.Parent:FindFirstChild(\034Left Arm\034)\010\009\009local RightArm = Tool.Parent:FindFirstChild(\034Right Arm\034)\010\009\009if RightArm then\010\009\009\009local Grip = RightArm:WaitForChild(\034RightGrip\034,0.01)\010\009\009\009if Grip then\010\009\009\009\009Grip2 = Grip:Clone()\010\009\009\009\009Grip2.Name = \034LeftGrip\034\010\009\009\009\009Grip2.Part0 = LeftArm\010\009\009\009\009Grip2.Part1 = Handle2\010\009\009\009\009--Grip2.C1 = Grip2.C1:inverse()\010\009\009\009\009Grip2.Parent = LeftArm\010\009\009\009end\010\009\009end\010\009end\010end)\010\010Tool.Unequipped:connect(function()\010\009if Module.DualEnabled and Workspace.FilteringEnabled then\010\009\009Handle2.CanCollide = true\010\009\009if Grip2 then Grip2:Destroy() end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27644,class="Script",parent=27641,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="IgniteScript",["ScriptGuid"]="{70AD6D55-DE32-4B47-BBD3-81AC0AF173F3}",["Source"]="local Humanoid = script.Parent:FindFirstChild(\034Humanoid\034)\010local Torso = script.Parent:FindFirstChild(\034Torso\034)\010local Fires = {}\010local FireDamagePerSecond = 5\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010if Humanoid and Torso then\010\009BurnSound = Instance.new(\034Sound\034)\010\009BurnSound.Name = \034BurnSound\034\010\009BurnSound.SoundId = \034http://www.roblox.com/asset/?id=32791565\034\010\009BurnSound.Parent = Torso\010\009BurnSound.Volume = 1\010\009game.Debris:AddItem(BurnSound,10)\010\009Delay(0,function()\010\009\009BurnSound:Play()\010\009end)\010\009for _,parts in pairs(script.Parent:GetChildren()) do\010\009\009if parts.className == \034Part\034 or parts.className == \034WedgePart\034 or parts.className == \034CornerWedgePart\034 then\010\009\009\009local firer = Instance.new(\034Fire\034)\010\009\009\009table.insert(Fires,firer)\010\009\009\009firer.Size = 5 + (parts.Size.magnitude*1.5)\010\009\009\009firer.Parent = parts\010\009\009end\010\009end\010\009while script.Duration.Value > 0 do\010\009\009wait(0.1)\010\009\009script.Duration.Value = script.Duration.Value - 0.1\010\009\009while Humanoid:FindFirstChild(\034creator\034) do\010\009\009\009Humanoid.creator:Destroy()\010\009\009end\010\009\009local Tag = script.creator:clone()\010\009\009Tag.Parent = Humanoid\010\009\009game.Debris:AddItem(Tag,5)\010\009\009Humanoid:TakeDamage(FireDamagePerSecond*0.1)\010\009end\010\009for _, Fire in pairs(Fires) do\010\009\009Fire.Enabled = false\010\009end\010\009wait(5)\010\009for _, Fire in pairs(Fires) do\010\009\009Fire:Destroy()\010\009end\010end\010wait()\010script:remove()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27647,class="Script",parent=27602,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="CHANGE LOG",["ScriptGuid"]="{0FF9B4E3-3470-48EF-966D-07DDF531A775}",["Source"]="--[[\010\009\010v1.0.6\010==================================================\010-Fixed a glitch which player can shooting even after died\010-Added \034ChargedShot\034 setting\010-Added \034Minigun\034 setting\010-Added \034Piercing\034 setting\010-Added \034FadeTime\034 setting\010-Updated \034BulletVisualizerScript\034. Replace an older one now!\010==================================================\010\009\010v1.0.5\010==================================================\010-Fixed a gun that shoot slower even you set \034FireRate\034 to lower\010-Added \034ShotgunReload\034 setting\010==================================================\010\009\010v1.0.4\010==================================================\010-Fixed VisualizeBulletScript and BulletVisualizerScript. Previously, it's a bug that doesn't show bullet for other player.\010-Fixed a bug which scope still in use even unequipped\010==================================================\010\009\010v1.0.3\010==================================================\010-Fixed a bug that you can reload a gun even unequip\010-Ray start position is now at Player's Head instead Gun Muzzle\010-Added \034DualEnabled\034 setting\010-Added Ammo Box for the gun\010-User can no longer use Scope while reloading\010==================================================\010\009\010v1.0.2\010==================================================\010-Fixed Bullet Visualizer that doesn't display fake bullet to other player\010-Fixed fake bullet still displayed even \034VisualizerEnabled\034 is disabled\010==================================================\010\009\010v1.0.1\010==================================================\010-Fixed reload\010-Ammo GUI will not show if AmmoPerClip is \034math.huge\034\010-Added Animation setting\010==================================================\010\009\010v1.0\010==================================================\010-First release\010==================================================\010\009\010--]]",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27684,class="Script",parent=27683,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{6B01F682-D2C6-46D7-868F-570CFF7B9F2F}",["Source"]="local GRAVITY_ACCELERATION = 196.2\010\010local RELOAD_TIME = 0.75 -- Seconds until tool can be used again\010local ROCKET_SPEED = 0 -- Speed of the projectile\010local Tool = script.Parent.Parent\010\010local MISSILE_MESH_ID = 'http://www.roblox.com/asset/?id=90780672'\010local MISSILE_TEXTURE_ID = 'http://www.roblox.com/asset/?id=90780623'\010local MISSILE_MESH_SCALE = Vector3.new(10,10,15)\010local ROCKET_PART_SIZE = Vector3.new(1.2, 1.2, 3.27)\010--local Player = game.Players.LocalPlayer\010--local Character = Workspace:WaitForChild(Player.Name)\010--local TEAM = Player.Character:WaitForChild(\034TEAM\034)\010--local GUI = script:WaitForChild(\034GunGUI\034)\010--local Humanoid = Player.Character:WaitForChild(\034Humanoid\034)\010local Reloading = false\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010--local MyPlayer = PlayersService.LocalPlayer\010\010local Tool = script.Parent.Parent\010local ToolHandle = Tool.Handle\010\010local RocketScript = script:WaitForChild('Rocket')\010local SwooshSound = script:WaitForChild('Swoosh')\010local BoomSound = script:WaitForChild('Boom')\010local BoomSound2 = script:WaitForChild('Boom2')\010local Clip = Tool:WaitForChild('Clip')\010local ShootSound = ToolHandle:WaitForChild('Shoot')\010local ReloadSound = ToolHandle:WaitForChild('Reload')\010\010--NOTE: We create the rocket once and then clone it when the player fires\010local Rocket = Instance.new('Part') do\010\009-- Set up the rocket part\010\009Rocket.Name = 'Rocket'\010\009Rocket.FormFactor = Enum.FormFactor.Custom --NOTE: This must be done before changing Size\010\009Rocket.Size = ROCKET_PART_SIZE\010\009Rocket.CanCollide = false\010\009Rocket.Anchored = true\010\009--TEAM:Clone().Parent = Rocket\010\010\009-- Add the mesh\010\009local mesh = Instance.new('SpecialMesh', Rocket)\010\009mesh.MeshId = MISSILE_MESH_ID\010\009mesh.TextureId = MISSILE_TEXTURE_ID\010\009mesh.Scale = MISSILE_MESH_SCALE\010\010\009-- Add fire\010\009local fire = Instance.new('Fire', Rocket)\010\009fire.Heat = 5\010\009fire.Size = 2\010\010\009-- Add a force to counteract gravity\010\009local bodyForce = Instance.new('BodyForce', Rocket)\010\009bodyForce.Name = 'Antigravity'\010\009bodyForce.force = Vector3.new(0, Rocket:GetMass() * GRAVITY_ACCELERATION, 0)\010\010\009-- Clone the sounds and set Boom to PlayOnRemove\010\009local swooshSoundClone = SwooshSound:Clone()\010\009swooshSoundClone.Parent = Rocket\010\009local boomSoundClone = BoomSound:Clone()\010\009boomSoundClone.PlayOnRemove = true\010\009boomSoundClone.Parent = Rocket\010\009local boomSoundClone2 = BoomSound2:Clone()\010\009boomSoundClone2.PlayOnRemove = true\010\009boomSoundClone2.Parent = Rocket\010\010\009-- Attach creator tags to the rocket early on\010\010\009-- Finally, clone the rocket script and enable it\010\009local rocketScriptClone = RocketScript:Clone()\010\009rocketScriptClone.Parent = Rocket\010\009rocketScriptClone.Disabled = false\010\009local rocketScriptClone2 = script.Script:Clone()\010\009rocketScriptClone2.Parent = Rocket\010\009local rocketScriptClone3 = script.Trail:Clone()\010\009rocketScriptClone3.Parent = Rocket\010\009local rocketScriptClone4 = script.DamageTag:Clone()\010\009rocketScriptClone4.Parent = rocketScriptClone\010end\010\010\010\010script.Parent.OnServerEvent:connect(function(Player,vTarget,TEAM)\010local ExplosiveDamage = 125\010local Anim = script.Parent.Parent.Parent:FindFirstChild('Humanoid'):LoadAnimation(Tool.ShootAnim)\010ShootSound:Play()\010Anim:Play(nil,nil,2.5)\010\010-- Create a clone of Rocket and set its color\010local rocketClone = Rocket:Clone()\010local creatorTag = Instance.new('ObjectValue', rocketClone)\010creatorTag.Value = Player\010creatorTag.Name = 'creator' --NOTE: Must be called 'creator' for website stats\010local iconTag = Instance.new('StringValue', creatorTag)\010iconTag.Value = Tool.TextureId\010iconTag.Name = 'icon'\010DebrisService:AddItem(rocketClone, 30)\010rocketClone.BrickColor = Player.TeamColor\010rocketClone.Rocket.Damage.Value = ExplosiveDamage\010TEAM:Clone().Parent = rocketClone\010\010-- Position the rocket clone and launch!\010local spawnPosition = (ToolHandle.CFrame * CFrame.new(0, 0, -3)).p\010rocketClone.CFrame = CFrame.new(spawnPosition, vTarget) --NOTE: This must be done before assigning Parent\010rocketClone.Velocity = rocketClone.CFrame.lookVector * ROCKET_SPEED --NOTE: This should be done before assigning Parent\010rocketClone.Parent = Player.Character.Torso\010\009\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27688,class="Script",parent=27684,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Rocket",["ScriptGuid"]="{9AFC5823-C5EF-4DF7-9B11-26860AB22574}",["Source"]="-----------------\010--| Constants |--\010-----------------\010\010local BLAST_RADIUS = 8 -- Blast radius of the explosion\010local BLAST_DAMAGE = script.Damage.Value -- Amount of damage done to players\010local BLAST_FORCE = 1000 -- Amount of force applied to parts\010\010local IGNORE_LIST = {rocket = 1, handle = 1, effect = 1, water = 1} -- Rocket will fly through things named these\010--NOTE: Keys must be lowercase, values must evaluate to true\010\010Explode = Instance.new(\034Part\034)\010Explode.formFactor = \034Custom\034\010Explode.Size = Vector3.new(0,0,0)\010Explode.Anchored = true\010Explode.CanCollide = false\010Explode.TopSurface = 0\010Explode.BottomSurface = 0\010Explode.BrickColor = BrickColor.new(\034Deep orange\034)\010Mesh = Instance.new(\034SpecialMesh\034,Explode)\010Mesh.MeshType = \034Brick\034\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009return hit2,pos2\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Rocket = script.Parent\010local TEAM = Rocket:WaitForChild('TEAM')\010\010local CreatorTag = Rocket:WaitForChild('creator')\010local SwooshSound = Rocket:WaitForChild('Swoosh')\010\010-----------------\010--| Functions |--\010-----------------\010\010function DamageTag(parent,damage)\010\009DmgTag = script.DamageTag:clone()\010\009DmgTag.Damage.Value = damage\010\009DmgTag.creator.Value = script.creator.Value\010\009DmgTag.Disabled = false\010\009DmgTag.Parent = parent\010end\010\010-- Removes any old creator tags and applies a new one to the target\010local function ApplyTags(target)\010\009while target:FindFirstChild('creator') do\010\009\009target.creator:Destroy()\010\009end\010\010\009local creatorTagClone = CreatorTag:Clone()\010\009DebrisService:AddItem(creatorTagClone, 1.5)\010\009creatorTagClone.Parent = target\010end\010\010-- Returns the ancestor that contains a Humanoid, if it exists\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009local humanoid = subject:FindFirstChild('Humanoid')\010\009\009if humanoid then\010\009\009\009return subject, humanoid\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010-- Customized explosive effect that doesn't affect teammates and only breaks joints on dead parts\010local function OnExplosionHit(hitPart, hitDistance, blastCenter)\010\009if hitPart and hitDistance then\010\009\009local character, humanoid = FindCharacterAncestor(hitPart.Parent)\010\009\009if humanoid and humanoid.Health > 0 then -- Humanoids are tagged and damaged\010\009\009\009if hitPart.Name == 'Torso' then\010\009\009\009\009--ApplyTags(humanoid)\010\009\009\009\009if humanoid ~= nil and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009DamageTag(character,BLAST_DAMAGE)\010\009\009\009\009--humanoid:TakeDamage(BLAST_DAMAGE)\010\009\009\009end\010\009\009end\010\009end\010\009end\010\009end\010\010local function OnTouched(otherPart,RayPos)\010\009if Rocket and otherPart then\010\009\009-- Fly through anything in the ignore list\010\009\009if IGNORE_LIST[string.lower(otherPart.Name)] then\010\009\009\009return\010\009\009end\010\010\009\009local myPlayer = CreatorTag.Value\010\009\009if myPlayer then\010\009\009\009-- Fly through the creator\010\009\009\009if myPlayer.Character and myPlayer.Character:IsAncestorOf(otherPart) then\010\009\009\009\009return\010\009\009\009end\010\010\009\009\009 -- Fly through friendlies\010\009\009\009if not myPlayer.Neutral then\010\009\009\009\009local character = FindCharacterAncestor(otherPart.Parent)\010\009\009\009\009local player = PlayersService:GetPlayerFromCharacter(character)\010\009\009\009\009if player and player ~= myPlayer and player.TeamColor == Rocket.BrickColor then\010\009\009\009\009\009return\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\010\009\009-- Fly through terrain water\010\009\009if otherPart == Workspace.Terrain then\010\009\009\009--NOTE: If the rocket is large, then the simplifications made here will cause it to fly through terrain in some cases\010\009\009\009local frontOfRocket = Rocket.Position + (Rocket.CFrame.lookVector * (Rocket.Size.Z / 2))\010\009\009\009local cellLocation = Workspace.Terrain:WorldToCellPreferSolid(frontOfRocket)\010\009\009\009local cellMaterial = Workspace.Terrain:GetCell(cellLocation.X, cellLocation.Y, cellLocation.Z)\010\009\009\009if cellMaterial == Enum.CellMaterial.Water or cellMaterial == Enum.CellMaterial.Empty then\010\009\009\009\009return\010\009\009\009end\010\009\009end\010\009\009\010\009\009Rocket.Transparency = 1\010\009\009Rocket.CFrame = CFrame.new(RayPos.X,RayPos.Y,RayPos.Z)\010\010\009\009-- Create the explosion\010\009\009local explosion = Instance.new('Explosion')\010\009\009explosion.BlastPressure = 500000 -- Completely safe explosion\010\009\009explosion.BlastRadius = BLAST_RADIUS\010\009\009explosion.DestroyJointRadiusPercent = 0\010\009\009explosion.ExplosionType = Enum.ExplosionType.NoCraters\010\009\009explosion.Position = Rocket.Position\010\009\009explosion.Parent = script.Parent.creator.Value.Character.Torso\010\010\009\009-- Connect custom logic for the explosion\010\009\009explosion.Hit:connect(function(hitPart, hitDistance) OnExplosionHit(hitPart, hitDistance, explosion.Position) end)\010\009\009\010\009\009ypcall(function()\010\009\009\009for i = 1, 3 do\010\009\009\009\009ExplodeClone = Explode:clone()\010\009\009\009\009ExplodeClone.Position = Rocket.Position\010\009\009\009\009ExplodeClone.Mesh.Scale = Vector3.new(5,5,5)*5\010\009\009\009\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009\009\009\009ExplodeClone.Parent = script.Parent.creator.Value.Character.Torso\010\009\009\009\009NewScript = Rocket.Script:clone()\010\009\009\009\009NewScript.Disabled = false\010\009\009\009\009NewScript.Parent = ExplodeClone\010\009\009\009end\010\009\009end)\010\010\009\009-- Move this script and the creator tag (so our custom logic can execute), then destroy the rocket\010\009\009script.Parent = explosion\010\009\009CreatorTag.Parent = script\010\009\009Rocket:Destroy()\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010SwooshSound:Play()\010\010--Rocket.Touched:connect(OnTouched)\010\010while script.Parent == Rocket do\010\009ExplodeClone = Explode:clone()\010\009ExplodeClone.Name = \034Effect\034\010\009ExplodeClone.BrickColor = BrickColor.new(\034White\034)\010\009ExplodeClone.Position = Rocket.Position\010\009ExplodeClone.Mesh.Scale = Vector3.new(1,1,1)*5\010\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009ExplodeClone.Parent = script.Parent.creator.Value.Character.Torso\010\009NewScript = Rocket.Trail:clone()\010\009NewScript.Disabled = false\010\009NewScript.Parent = ExplodeClone\010\009local hit,pos = raycast(Rocket.Position,((Rocket.CFrame * CFrame.new(0,0,-10)).p-Rocket.Position).unit,10)\010\009if hit then\010\009\009OnTouched(hit,pos)\010\009end\010\009Rocket.CFrame = Rocket.CFrame * CFrame.new(0,0,-5) * CFrame.Angles(0, 0, math.rad(18))\010\009game:GetService(\034RunService\034).Stepped:wait()\010end\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27690,class="Script",parent=27684,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{1516B002-48D5-44F3-B028-90965F125ED8}",["Source"]="Fire = script.Parent\010WaitTime = 0.05\010Grow = math.random(15,25)/10\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Bright yellow\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.1\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Bright orange\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.2\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034CGA brown\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.3\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Reddish brown\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.4\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Black\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.5\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Really black\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.6\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.7\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.8\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.9\010wait(WaitTime)\010Fire:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27691,class="Script",parent=27684,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Trail",["ScriptGuid"]="{B048039B-4330-4537-8D2F-30DBC8EB3C48}",["Source"]="Fire = script.Parent\010WaitTime = 0.05\010Grow = math.random(15,25)/10\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Bright yellow\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.1\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Bright orange\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.2\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034CGA brown\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.3\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Reddish brown\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.4\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Black\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.5\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Really black\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.6\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.7\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.8\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.9\010wait(WaitTime)\010Fire:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27692,class="Script",parent=27684,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="DamageTag",["ScriptGuid"]="{29F79DC2-0F59-4718-BF01-E9285302846F}",["Source"]="wait()\010h = script.Parent:findFirstChild(\034Humanoid\034)\010if h ~= nil then\010\009while h:findFirstChild(\034creator\034) do\010\009\009h.creator:Destroy()\010\009end\010\009tag = script.creator:clone()\010\009tag.Parent = h\010\009game.Debris:AddItem(tag,5)\010\009h:TakeDamage(script.Damage.Value)\010end\010script:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27696,class="Script",parent=27695,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{2318FAC9-08DF-4E49-BE89-4D6483DA3710}",["Source"]="script.Parent.OnServerEvent:connect(function(Player,Anim1,Speed)\010local Anim2 = Player.Character:FindFirstChild('Humanoid'):LoadAnimation(Anim1)\010if Anim2 then Anim2:Play(nil,nil,Speed) end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27733,class="Script",parent=27732,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{64EABFD4-B676-461A-8658-491E417588FA}",["Source"]="local GRAVITY_ACCELERATION = 196.2\010\010local RELOAD_TIME = 0.75 -- Seconds until tool can be used again\010local ROCKET_SPEED = 0 -- Speed of the projectile\010local Tool = script.Parent.Parent\010\010local MISSILE_MESH_ID = \034http://www.roblox.com/asset/?id=189741947\034\010local MISSILE_TEXTURE_ID = \034http://www.roblox.com/asset/?id=189741994\034\010local MISSILE_MESH_SCALE = Vector3.new(10,10,15)\010local ROCKET_PART_SIZE = Vector3.new(1.2, 1.2, 3.27)\010--local Player = game.Players.LocalPlayer\010--local Character = Workspace:WaitForChild(Player.Name)\010--local TEAM = Player.Character:WaitForChild(\034TEAM\034)\010--local GUI = script:WaitForChild(\034GunGUI\034)\010--local Humanoid = Player.Character:WaitForChild(\034Humanoid\034)\010local Reloading = false\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010--local MyPlayer = PlayersService.LocalPlayer\010\010local Tool = script.Parent.Parent\010local ToolHandle = Tool.Handle\010\010local RocketScript = script:WaitForChild('Rocket')\010local SwooshSound = script:WaitForChild('Swoosh')\010local BoomSound = script:WaitForChild('Boom')\010local BoomSound2 = script:WaitForChild('Boom2')\010local Clip = Tool:WaitForChild('Clip')\010local ShootSound = ToolHandle:WaitForChild('Shoot')\010local ReloadSound = ToolHandle:WaitForChild('Reload')\010\010--NOTE: We create the rocket once and then clone it when the player fires\010local Rocket = Instance.new('Part') do\010\009-- Set up the rocket part\010\009Rocket.Name = 'Rocket'\010\009Rocket.FormFactor = Enum.FormFactor.Custom --NOTE: This must be done before changing Size\010\009Rocket.Size = ROCKET_PART_SIZE\010\009Rocket.CanCollide = false\010\009Rocket.Anchored = true\010\009--TEAM:Clone().Parent = Rocket\010\010\009-- Add the mesh\010\009local mesh = Instance.new('SpecialMesh', Rocket)\010\009mesh.MeshId = MISSILE_MESH_ID\010\009mesh.TextureId = MISSILE_TEXTURE_ID\010\009mesh.Scale = MISSILE_MESH_SCALE\010\010\009-- Add fire\010\009local fire = Instance.new('Fire', Rocket)\010\009fire.Heat = 5\010\009fire.Size = 2\010\010\009-- Add a force to counteract gravity\010\009local bodyForce = Instance.new('BodyForce', Rocket)\010\009bodyForce.Name = 'Antigravity'\010\009bodyForce.force = Vector3.new(0, Rocket:GetMass() * GRAVITY_ACCELERATION, 0)\010\010\009-- Clone the sounds and set Boom to PlayOnRemove\010\009local swooshSoundClone = SwooshSound:Clone()\010\009swooshSoundClone.Parent = Rocket\010\009local boomSoundClone = BoomSound:Clone()\010\009boomSoundClone.PlayOnRemove = true\010\009boomSoundClone.Parent = Rocket\010\009local boomSoundClone2 = BoomSound2:Clone()\010\009boomSoundClone2.PlayOnRemove = true\010\009boomSoundClone2.Parent = Rocket\010\010\009-- Attach creator tags to the rocket early on\010\010\009-- Finally, clone the rocket script and enable it\010\009local rocketScriptClone = RocketScript:Clone()\010\009rocketScriptClone.Parent = Rocket\010\009rocketScriptClone.Disabled = false\010\009local rocketScriptClone2 = script.Script:Clone()\010\009rocketScriptClone2.Parent = Rocket\010\009local rocketScriptClone3 = script.Trail:Clone()\010\009rocketScriptClone3.Parent = Rocket\010\009local rocketScriptClone4 = script.DamageTag:Clone()\010\009rocketScriptClone4.Parent = rocketScriptClone\010end\010\010\010\010script.Parent.OnServerEvent:connect(function(Player,vTarget,TEAM)\010local ExplosiveDamage = 500\010local Anim = script.Parent.Parent.Parent:FindFirstChild('Humanoid'):LoadAnimation(Tool.ShootAnim)\010ShootSound:Play()\010Anim:Play(nil,nil,2.5)\010\010-- Create a clone of Rocket and set its color\010local rocketClone = Rocket:Clone()\010local creatorTag = Instance.new('ObjectValue', rocketClone)\010creatorTag.Value = Player\010creatorTag.Name = 'creator' --NOTE: Must be called 'creator' for website stats\010local iconTag = Instance.new('StringValue', creatorTag)\010iconTag.Value = Tool.TextureId\010iconTag.Name = 'icon'\010DebrisService:AddItem(rocketClone, 30)\010rocketClone.BrickColor = Player.TeamColor\010rocketClone.Rocket.Damage.Value = ExplosiveDamage\010TEAM:Clone().Parent = rocketClone\010\010-- Position the rocket clone and launch!\010local spawnPosition = (ToolHandle.CFrame * CFrame.new(0, 0, -3)).p\010rocketClone.CFrame = CFrame.new(spawnPosition, vTarget) --NOTE: This must be done before assigning Parent\010rocketClone.Velocity = rocketClone.CFrame.lookVector * ROCKET_SPEED --NOTE: This should be done before assigning Parent\010rocketClone.Parent = Player.Character.Torso\010\009\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27737,class="Script",parent=27733,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Rocket",["ScriptGuid"]="{1A58B7A7-AA5E-45EC-94CF-243CE5DF753D}",["Source"]="-----------------\010--| Constants |--\010-----------------\010\010local BLAST_RADIUS = 8 -- Blast radius of the explosion\010local BLAST_DAMAGE = script.Damage.Value -- Amount of damage done to players\010local BLAST_FORCE = 1000 -- Amount of force applied to parts\010\010local IGNORE_LIST = {rocket = 1, handle = 1, effect = 1, water = 1} -- Rocket will fly through things named these\010--NOTE: Keys must be lowercase, values must evaluate to true\010\010Explode = Instance.new(\034Part\034)\010Explode.formFactor = \034Custom\034\010Explode.Size = Vector3.new(0,0,0)\010Explode.Anchored = true\010Explode.CanCollide = false\010Explode.TopSurface = 0\010Explode.BottomSurface = 0\010Explode.BrickColor = BrickColor.new(\034Deep orange\034)\010Mesh = Instance.new(\034SpecialMesh\034,Explode)\010Mesh.MeshType = \034Brick\034\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009return hit2,pos2\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Rocket = script.Parent\010local TEAM = Rocket:WaitForChild('TEAM')\010\010local CreatorTag = Rocket:WaitForChild('creator')\010local SwooshSound = Rocket:WaitForChild('Swoosh')\010\010-----------------\010--| Functions |--\010-----------------\010\010function DamageTag(parent,damage)\010\009DmgTag = script.DamageTag:clone()\010\009DmgTag.Damage.Value = damage\010\009DmgTag.creator.Value = script.creator.Value\010\009DmgTag.Disabled = false\010\009DmgTag.Parent = parent\010end\010\010-- Removes any old creator tags and applies a new one to the target\010local function ApplyTags(target)\010\009while target:FindFirstChild('creator') do\010\009\009target.creator:Destroy()\010\009end\010\010\009local creatorTagClone = CreatorTag:Clone()\010\009DebrisService:AddItem(creatorTagClone, 1.5)\010\009creatorTagClone.Parent = target\010end\010\010-- Returns the ancestor that contains a Humanoid, if it exists\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009local humanoid = subject:FindFirstChild('Humanoid')\010\009\009if humanoid then\010\009\009\009return subject, humanoid\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010-- Customized explosive effect that doesn't affect teammates and only breaks joints on dead parts\010local function OnExplosionHit(hitPart, hitDistance, blastCenter)\010\009if hitPart and hitDistance then\010\009\009local character, humanoid = FindCharacterAncestor(hitPart.Parent)\010\009\009if humanoid and humanoid.Health > 0 then -- Humanoids are tagged and damaged\010\009\009\009if hitPart.Name == 'Torso' then\010\009\009\009\009--ApplyTags(humanoid)\010\009\009\009\009if humanoid ~= nil and humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009DamageTag(character,BLAST_DAMAGE)\010\009\009\009\009--humanoid:TakeDamage(BLAST_DAMAGE)\010\009\009\009end\010\009\009end\010\009end\010\009end\010\009end\010\010local function OnTouched(otherPart,RayPos)\010\009if Rocket and otherPart then\010\009\009-- Fly through anything in the ignore list\010\009\009if IGNORE_LIST[string.lower(otherPart.Name)] then\010\009\009\009return\010\009\009end\010\010\009\009local myPlayer = CreatorTag.Value\010\009\009if myPlayer then\010\009\009\009-- Fly through the creator\010\009\009\009if myPlayer.Character and myPlayer.Character:IsAncestorOf(otherPart) then\010\009\009\009\009return\010\009\009\009end\010\010\009\009\009 -- Fly through friendlies\010\009\009\009if not myPlayer.Neutral then\010\009\009\009\009local character = FindCharacterAncestor(otherPart.Parent)\010\009\009\009\009local player = PlayersService:GetPlayerFromCharacter(character)\010\009\009\009\009if player and player ~= myPlayer and player.TeamColor == Rocket.BrickColor then\010\009\009\009\009\009return\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\010\009\009-- Fly through terrain water\010\009\009if otherPart == Workspace.Terrain then\010\009\009\009--NOTE: If the rocket is large, then the simplifications made here will cause it to fly through terrain in some cases\010\009\009\009local frontOfRocket = Rocket.Position + (Rocket.CFrame.lookVector * (Rocket.Size.Z / 2))\010\009\009\009local cellLocation = Workspace.Terrain:WorldToCellPreferSolid(frontOfRocket)\010\009\009\009local cellMaterial = Workspace.Terrain:GetCell(cellLocation.X, cellLocation.Y, cellLocation.Z)\010\009\009\009if cellMaterial == Enum.CellMaterial.Water or cellMaterial == Enum.CellMaterial.Empty then\010\009\009\009\009return\010\009\009\009end\010\009\009end\010\009\009\010\009\009Rocket.Transparency = 1\010\009\009Rocket.CFrame = CFrame.new(RayPos.X,RayPos.Y,RayPos.Z)\010\010\009\009-- Create the explosion\010\009\009local explosion = Instance.new('Explosion')\010\009\009explosion.BlastPressure = 500000 -- Completely safe explosion\010\009\009explosion.BlastRadius = BLAST_RADIUS\010\009\009explosion.DestroyJointRadiusPercent = 0\010\009\009explosion.ExplosionType = Enum.ExplosionType.NoCraters\010\009\009explosion.Position = Rocket.Position\010\009\009explosion.Parent = script.Parent.creator.Value.Character.Torso\010\010\009\009-- Connect custom logic for the explosion\010\009\009explosion.Hit:connect(function(hitPart, hitDistance) OnExplosionHit(hitPart, hitDistance, explosion.Position) end)\010\009\009\010\009\009ypcall(function()\010\009\009\009for i = 1, 3 do\010\009\009\009\009ExplodeClone = Explode:clone()\010\009\009\009\009ExplodeClone.Position = Rocket.Position\010\009\009\009\009ExplodeClone.Mesh.Scale = Vector3.new(5,5,5)*5\010\009\009\009\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009\009\009\009ExplodeClone.Parent = script.Parent.creator.Value.Character.Torso\010\009\009\009\009NewScript = Rocket.Script:clone()\010\009\009\009\009NewScript.Disabled = false\010\009\009\009\009NewScript.Parent = ExplodeClone\010\009\009\009end\010\009\009end)\010\010\009\009-- Move this script and the creator tag (so our custom logic can execute), then destroy the rocket\010\009\009script.Parent = explosion\010\009\009CreatorTag.Parent = script\010\009\009Rocket:Destroy()\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010SwooshSound:Play()\010\010--Rocket.Touched:connect(OnTouched)\010\010while script.Parent == Rocket do\010\009ExplodeClone = Explode:clone()\010\009ExplodeClone.Name = \034Effect\034\010\009ExplodeClone.BrickColor = BrickColor.new(\034White\034)\010\009ExplodeClone.Position = Rocket.Position\010\009ExplodeClone.Mesh.Scale = Vector3.new(1,1,1)*5\010\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009ExplodeClone.Parent = script.Parent.creator.Value.Character.Torso\010\009NewScript = Rocket.Trail:clone()\010\009NewScript.Disabled = false\010\009NewScript.Parent = ExplodeClone\010\009local hit,pos = raycast(Rocket.Position,((Rocket.CFrame * CFrame.new(0,0,-10)).p-Rocket.Position).unit,10)\010\009if hit then\010\009\009OnTouched(hit,pos)\010\009end\010\009Rocket.CFrame = Rocket.CFrame * CFrame.new(0,0,-5) * CFrame.Angles(0, 0, math.rad(18))\010\009game:GetService(\034RunService\034).Stepped:wait()\010end\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
