10Fire.BrickColor = BrickColor.new(\034Black\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.5\010wait(WaitTime)\010Fire.BrickColor = BrickColor.new(\034Really black\034)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.6\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.7\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.8\010wait(WaitTime)\010Fire.Mesh.Scale = Fire.Mesh.Scale + Vector3.new(Grow,Grow,Grow)\010Fire.CFrame = Fire.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010Fire.Transparency = 0.9\010wait(WaitTime)\010Fire:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
