T[#T+1]={id=27741,class="Script",parent=27733,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="DamageTag",["ScriptGuid"]="{7003FC11-738A-4720-81D1-8C179FA78FB7}",["Source"]="wait()\010h = script.Parent:findFirstChild(\034Humanoid\034)\010if h ~= nil then\010\009while h:findFirstChild(\034creator\034) do\010\009\009h.creator:Destroy()\010\009end\010\009tag = script.creator:clone()\010\009tag.Parent = h\010\009game.Debris:AddItem(tag,5)\010\009h:TakeDamage(script.Damage.Value)\010end\010script:remove()",["SourceAssetId"]=-1,["Tags"]=""}}
