T[#T+1]={id=27874,class="Script",parent=27837,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="AIUseFPSMode",["ScriptGuid"]="{12F841A6-D961-4ED7-85C5-2E91DFE658AB}",["Source"]="gyro = Instance.new(\034BodyGyro\034)\010gyro.Parent = script.Parent:findFirstChild(\034Torso\034)\010gyro.P = 7500\010gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\010script.Parent.Humanoid.StateChanged:connect(function(Old,New)\010\009if New == Enum.HumanoidStateType.Running then\010\009\009gyro.P = 7500\010\009\009gyro.maxTorque = Vector3.new(math.huge,math.huge,math.huge)\010\009else\010\009\009gyro.P = 0\010\009\009gyro.maxTorque = Vector3.new(0,0,0)\010\009end\010end)\010\010while true do\010\009vCharacter = script.Parent\010\009if vCharacter ~= nil then \010\009\009gyro.Parent = script.Parent.Torso\010\009\009local tp\010\009\009if (vCharacter.Target.Value) and vCharacter.Humanoid:GetState() then\010\009\009\009tp = vCharacter.Target.Value.Position\010\009\009else\010\009\009\009tp = vCharacter.Humanoid.WalkToPoint\010\009\009end\010\009\009tp = Vector3.new(tp.X,script.Parent.Torso.Position.Y,tp.Z) \010\009\009local dir = (tp - script.Parent.Torso.Position).unit\010\009\009local spawnPos = script.Parent.Torso.Position\010\009\009local pos = spawnPos + (dir * 1)\010\009\009gyro.cframe = CFrame.new(pos,  pos + dir)\010\009elseif not vCharacter.Attack.Value then\010\009\009gyro.Parent = nil\010\009end\010\009wait()\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=27991,class="Script",parent=27837,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Death-On-Spawn Debugger",["ScriptGuid"]="{E4FB4112-9688-45B7-B87E-5D4EB9581AC6}",["Source"]="--You must anchor all part to make this script work. This will reduce a chance to happen Death-On-Spawn glitch.\010wait()\010parts = script.Parent:children()\010script.Parent:MakeJoints()\010for i = 1,#parts do\010\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 or parts[i].className == \034UnionOperation\034 then\010\009\009if parts[i].Anchored == true then\010\009\009\009parts[i].Anchored = false\010\009\009\009script.Parent:MakeJoints()\010\009\009end\010\009end\010end\010script.Parent:MakeJoints()\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28000,class="Script",parent=27999,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Jump",["ScriptGuid"]="{7AB20ABE-4DF4-45E6-BF44-81FAFE68AB27}",["Source"]="local CanJump = true\010\010script.Parent.Changed:connect(function()\010\009if script.Parent.Jump == true then\010\009\009script.Parent.Jump = false\010\009\009if CanJump then\010\009\009\009CanJump = false\010\009\009\009script.Parent.Torso.Velocity = script.Parent.Torso.Velocity + Vector3.new(0,script.Parent.JumpPower,0)\010\009\009\009wait(2)\010\009\009\009CanJump = true\010\009\009end\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28002,class="Script",parent=27999,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Put this in Boss's Humanoid",["ScriptGuid"]="{5F5216BC-E39E-495F-9558-D8E656DF15E2}",["Source"]="while true do\010\009if game.ReplicatedStorage.Boss2.Value == nil then\010\009game.ReplicatedStorage.Boss2.Value = script.Parent.Parent\010\009end\010\009--[[for _, Players in pairs(game.Players:GetChildren()) do\010\009\009local BossBattleHealthGui = Players.PlayerGui:FindFirstChild(\034BossBattleHealthGui\034)\010\009\009if BossBattleHealthGui then\010\009\009\009BossBattleHealthGui.Frame.Boss.Value = script.Parent.Parent\010\009\009end\010\009end]]\010\009wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28003,class="Script",parent=27837,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Animate",["ScriptGuid"]="{19EFF437-AFE2-4A66-BA8C-4AA7127B3565}",["Source"]="wait()\010function   waitForChild(parent, childName)\010\009local child = parent:findFirstChild(childName)\010\009if child then return child end\010\009while true do\010\009\009child = parent.ChildAdded:wait()\010\009\009if child.Name==childName then return child end\010\009end\010end\010\010local Figure = script.Parent\010local Torso = waitForChild(Figure, \034Torso\034)\010--[[local RightShoulder = waitForChild(Torso, \034Right Shoulder\034)\010local LeftShoulder = waitForChild(Torso, \034Left Shoulder\034)\010local RightHip = waitForChild(Torso, \034Right Hip\034)\010local LeftHip = waitForChild(Torso, \034Left Hip\034)\010local Neck = waitForChild(Torso, \034Neck\034)]]\010local Humanoid = waitForChild(Figure, \034Humanoid\034)\010local pose = \034Standing\034\010\010local currentAnim = \034\034\010local currentAnimInstance = nil\010local currentAnimTrack = nil\010local currentAnimKeyframeHandler = nil\010local currentAnimSpeed = 1.0\010local animTable = {}\010local animNames = { \010\009idle = \009{\009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=481142564\034, weight = 9 },\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=481142564\034, weight = 1 }\010\009\009\009},\010\009walk = \009{ \009\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=481143027\034, weight = 10 } \010\009\009\009}, \010\009run = \009{\010\009\009\009\009{ id = \034run.xml\034, weight = 10 } \010\009\009\009}, \010\009jump = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=125750702\034, weight = 10 } \010\009\009\009}, \010\009fall = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=180436148\034, weight = 10 } \010\009\009\009}, \010\009climb = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=180436334\034, weight = 10 } \010\009\009\009}, \010\009sit = \009{\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=178130996\034, weight = 10 } \010\009\009\009},\009\010\009toolnone = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182393478\034, weight = 10 } \010\009\009\009},\010\009toolslash = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967390\034, weight = 10 } \010--\009\009\009\009{ id = \034slash.xml\034, weight = 10 } \010\009\009\009},\010\009toollunge = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129967478\034, weight = 10 } \010\009\009\009},\010\009wave = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128777973\034, weight = 10 } \010\009\009\009},\010\009point = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=128853357\034, weight = 10 } \010\009\009\009},\010\009dance = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182435998\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491037\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491065\034, weight = 10 } \010\009\009\009},\010\009dance2 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436842\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491248\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491277\034, weight = 10 } \010\009\009\009},\010\009dance3 = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182436935\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491368\034, weight = 10 }, \010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=182491423\034, weight = 10 } \010\009\009\009},\010\009laugh = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423131\034, weight = 10 } \010\009\009\009},\010\009cheer = {\010\009\009\009\009{ id = \034http://www.roblox.com/asset/?id=129423030\034, weight = 10 } \010\009\009\009},\010}\010\010-- Existance in this list signifies that it is an emote, the value indicates if it is a looping emote\010local emoteNames = { wave = false, point = false, dance = true, dance2 = true, dance3 = true, laugh = false, cheer = false}\010\010math.randomseed(tick())\010\010function configureAnimationSet(name, fileList)\010\009if (animTable[name] ~= nil) then\010\009\009for _, connection in pairs(animTable[name].connections) do\010\009\009\009connection:disconnect()\010\009\009end\010\009end\010\009animTable[name] = {}\010\009animTable[name].count = 0\010\009animTable[name].totalWeight = 0\009\010\009animTable[name].connections = {}\010\010\009-- check for config values\010\009local config = script:FindFirstChild(name)\010\009if (config ~= nil) then\010--\009\009print(\034Loading anims \034 .. name)\010\009\009table.insert(animTable[name].connections, config.ChildAdded:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009table.insert(animTable[name].connections, config.ChildRemoved:connect(function(child) configureAnimationSet(name, fileList) end))\010\009\009local idx = 1\010\009\009for _, childPart in pairs(config:GetChildren()) do\010\009\009\009if (childPart:IsA(\034Animation\034)) then\010\009\009\009\009table.insert(animTable[name].connections, childPart.Changed:connect(function(property) configureAnimationSet(name, fileList) end))\010\009\009\009\009animTable[name][idx] = {}\010\009\009\009\009animTable[name][idx].anim = childPart\010\009\009\009\009local weightObject = childPart:FindFirstChild(\034Weight\034)\010\009\009\009\009if (weightObject == nil) then\010\009\009\009\009\009animTable[name][idx].weight = 1\010\009\009\009\009else\010\009\009\009\009\009animTable[name][idx].weight = weightObject.Value\010\009\009\009\009end\010\009\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + animTable[name][idx].weight\010\009--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. animTable[name][idx].anim.AnimationId .. \034 (\034 .. animTable[name][idx].weight .. \034)\034)\010\009\009\009\009idx = idx + 1\010\009\009\009end\010\009\009end\010\009end\010\010\009-- fallback to defaults\010\009if (animTable[name].count <= 0) then\010\009\009for idx, anim in pairs(fileList) do\010\009\009\009animTable[name][idx] = {}\010\009\009\009animTable[name][idx].anim = Instance.new(\034Animation\034)\010\009\009\009animTable[name][idx].anim.Name = name\010\009\009\009animTable[name][idx].anim.AnimationId = anim.id\010\009\009\009animTable[name][idx].weight = anim.weight\010\009\009\009animTable[name].count = animTable[name].count + 1\010\009\009\009animTable[name].totalWeight = animTable[name].totalWeight + anim.weight\010--\009\009\009print(name .. \034 [\034 .. idx .. \034] \034 .. anim.id .. \034 (\034 .. anim.weight .. \034)\034)\010\009\009end\010\009end\010end\010\010-- Setup animation objects\010function scriptChildModified(child)\010\009local fileList = animNames[child.Name]\010\009if (fileList ~= nil) then\010\009\009configureAnimationSet(child.Name, fileList)\010\009end\009\010end\010\010script.ChildAdded:connect(scriptChildModified)\010script.ChildRemoved:connect(scriptChildModified)\010\010\010for name, fileList in pairs(animNames) do \010\009configureAnimationSet(name, fileList)\010end\009\010\010-- ANIMATION\010\010-- declarations\010local toolAnim = \034None\034\010local toolAnimTime = 0\010\010local jumpAnimTime = 0\010local jumpAnimDuration = 0.3\010\010local toolTransitionTime = 0.1\010local fallTransitionTime = 0.3\010local jumpMaxLimbVelocity = 0.75\010\010-- functions\010\010function stopAllAnimations()\010\009local oldAnim = currentAnim\010\010\009-- return to idle if finishing an emote\010\009if (emoteNames[oldAnim] ~= nil and emoteNames[oldAnim] == false) then\010\009\009oldAnim = \034idle\034\010\009end\010\010\009currentAnim = \034\034\010\009currentAnimInstance = nil\010\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009currentAnimKeyframeHandler:disconnect()\010\009end\010\010\009if (currentAnimTrack ~= nil) then\010\009\009currentAnimTrack:Stop()\010\009\009currentAnimTrack:Destroy()\010\009\009currentAnimTrack = nil\010\009end\010\009return oldAnim\010end\010\010function setAnimationSpeed(speed)\010\009if speed ~= currentAnimSpeed then\010\009\009currentAnimSpeed = speed\010\009\009currentAnimTrack:AdjustSpeed(currentAnimSpeed)\010\009end\010end\010\010function keyFrameReachedFunc(frameName)\010\009if frameName == \034Footstep1\034 or frameName == \034Footstep2\034 then Figure.FakeTorso[\034Footstep\034..math.random(1,4)]:Play() end\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\010\010\009\009local repeatAnim = currentAnim\010\009\009-- return to idle if finishing an emote\010\009\009if (emoteNames[repeatAnim] ~= nil and emoteNames[repeatAnim] == false) then\010\009\009\009repeatAnim = \034idle\034\010\009\009end\010\009\009\010\009\009local animSpeed = currentAnimSpeed\010\009\009playAnimation(repeatAnim, 0.0, Humanoid)\010\009\009setAnimationSpeed(animSpeed)\010\009end\010end\010\010-- Preload animations\010function playAnimation(animName, transitionTime, humanoid) \010\009\009\010\009local roll = math.random(1, animTable[animName].totalWeight) \010\009local origRoll = roll\010\009local idx = 1\010\009while (roll > animTable[animName][idx].weight) do\010\009\009roll = roll - animTable[animName][idx].weight\010\009\009idx = idx + 1\010\009end\010--\009\009print(animName .. \034 \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009local anim = animTable[animName][idx].anim\010\010\009-- switch animation\009\009\010\009if (anim ~= currentAnimInstance) then\010\009\009\010\009\009if (currentAnimTrack ~= nil) then\010\009\009\009currentAnimTrack:Stop(transitionTime)\010\009\009\009currentAnimTrack:Destroy()\010\009\009end\010\010\009\009currentAnimSpeed = 1.0\010\009\010\009\009-- load it to the humanoid; get AnimationTrack\010\009\009currentAnimTrack = humanoid:LoadAnimation(anim)\010\009\009 \010\009\009-- play the animation\010\009\009currentAnimTrack:Play(transitionTime)\010\009\009currentAnim = animName\010\009\009currentAnimInstance = anim\010\010\009\009-- set up keyframe name triggers\010\009\009if (currentAnimKeyframeHandler ~= nil) then\010\009\009\009currentAnimKeyframeHandler:disconnect()\010\009\009end\010\009\009currentAnimKeyframeHandler = currentAnimTrack.KeyframeReached:connect(keyFrameReachedFunc)\010\009\009\010\009end\010\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010local toolAnimName = \034\034\010local toolAnimTrack = nil\010local toolAnimInstance = nil\010local currentToolAnimKeyframeHandler = nil\010\010function toolKeyFrameReachedFunc(frameName)\010\009if (frameName == \034End\034) then\010--\009\009print(\034Keyframe : \034.. frameName)\009\010\009\009playToolAnimation(toolAnimName, 0.0, Humanoid)\010\009end\010end\010\010\010function playToolAnimation(animName, transitionTime, humanoid)\009 \010\009\009\010\009\009local roll = math.random(1, animTable[animName].totalWeight) \010\009\009local origRoll = roll\010\009\009local idx = 1\010\009\009while (roll > animTable[animName][idx].weight) do\010\009\009\009roll = roll - animTable[animName][idx].weight\010\009\009\009idx = idx + 1\010\009\009end\010--\009\009print(animName .. \034 * \034 .. idx .. \034 [\034 .. origRoll .. \034]\034)\010\009\009local anim = animTable[animName][idx].anim\010\010\009\009if (toolAnimInstance ~= anim) then\010\009\009\009\010\009\009\009if (toolAnimTrack ~= nil) then\010\009\009\009\009toolAnimTrack:Stop()\010\009\009\009\009toolAnimTrack:Destroy()\010\009\009\009\009transitionTime = 0\010\009\009\009end\010\009\009\009\009\009\010\009\009\009-- load it to the humanoid; get AnimationTrack\010\009\009\009toolAnimTrack = humanoid:LoadAnimation(anim)\010\009\009\009 \010\009\009\009-- play the animation\010\009\009\009toolAnimTrack:Play(transitionTime)\010\009\009\009toolAnimName = animName\010\009\009\009toolAnimInstance = anim\010\010\009\009\009currentToolAnimKeyframeHandler = toolAnimTrack.KeyframeReached:connect(toolKeyFrameReachedFunc)\010\009\009end\010end\010\010function stopToolAnimations()\010\009local oldAnim = toolAnimName\010\010\009if (currentToolAnimKeyframeHandler ~= nil) then\010\009\009currentToolAnimKeyframeHandler:disconnect()\010\009end\010\010\009toolAnimName = \034\034\010\009toolAnimInstance = nil\010\009if (toolAnimTrack ~= nil) then\010\009\009toolAnimTrack:Stop()\010\009\009toolAnimTrack:Destroy()\010\009\009toolAnimTrack = nil\010\009end\010\010\010\009return oldAnim\010end\010\010-------------------------------------------------------------------------------------------\010-------------------------------------------------------------------------------------------\010\010\010function onRunning(speed)\010\009--[[if speed>0.01 then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009\009pose = \034Running\034\010\009else\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009\009pose = \034Standing\034\010\009end]]\010end\010\010function onDied()\010\009pose = \034Dead\034\010end\010\010function onJumping()\010\009playAnimation(\034jump\034, 0.1, Humanoid)\010\009jumpAnimTime = jumpAnimDuration\010\009pose = \034Jumping\034\010end\010\010function onClimbing(speed)\010\009playAnimation(\034climb\034, 0.1, Humanoid)\010\009setAnimationSpeed(speed / 12.0)\010\009pose = \034Climbing\034\010end\010\010function onGettingUp()\010\009pose = \034GettingUp\034\010end\010\010function onFreeFall()\010\009if (jumpAnimTime <= 0) then\010\009\009--playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009end\010\009pose = \034FreeFall\034\010end\010\010function onFallingDown()\010\009pose = \034FallingDown\034\010end\010\010function onSeated()\010\009pose = \034Seated\034\010end\010\010function onPlatformStanding()\010\009pose = \034PlatformStanding\034\010end\010\010function onSwimming(speed)\010\009if speed>0 then\010\009\009pose = \034Running\034\010\009else\010\009\009pose = \034Standing\034\010\009end\010end\010\010function getTool()\009\010\009for _, kid in ipairs(Figure:GetChildren()) do\010\009\009if kid.className == \034Tool\034 then return kid end\010\009end\010\009return nil\010end\010\010function getToolAnim(tool)\010\009for _, c in ipairs(tool:GetChildren()) do\010\009\009if c.Name == \034toolanim\034 and c.className == \034StringValue\034 then\010\009\009\009return c\010\009\009end\010\009end\010\009return nil\010end\010\010--[[function animateTool()\010\009\010\009if (toolAnim == \034None\034) then\010\009\009playToolAnimation(\034toolnone\034, toolTransitionTime, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Slash\034) then\010\009\009playToolAnimation(\034toolslash\034, 0, Humanoid)\010\009\009return\010\009end\010\010\009if (toolAnim == \034Lunge\034) then\010\009\009playToolAnimation(\034toollunge\034, 0, Humanoid)\010\009\009return\010\009end\010end]]\010\010--[[function moveSit()\010\009RightShoulder.MaxVelocity = 0.15\010\009LeftShoulder.MaxVelocity = 0.15\010\009RightShoulder:SetDesiredAngle(3.14 /2)\010\009LeftShoulder:SetDesiredAngle(-3.14 /2)\010\009RightHip:SetDesiredAngle(3.14 /2)\010\009LeftHip:SetDesiredAngle(-3.14 /2)\010end]]\010\010local lastTick = 0\010\010function move(time)\010\009local amplitude = 1\010\009local frequency = 1\010  \009local deltaTime = time - lastTick\010  \009lastTick = time\010\010\009local climbFudge = 0\010\009local setAngles = false\010\010  \009if (jumpAnimTime > 0) then\010  \009\009jumpAnimTime = jumpAnimTime - deltaTime\010  \009end\010\010\009if (pose == \034FreeFall\034 and jumpAnimTime <= 0) then\010\009\009--playAnimation(\034fall\034, fallTransitionTime, Humanoid)\010\009elseif (pose == \034Seated\034) then\010\009\009--playAnimation(\034sit\034, 0.5, Humanoid)\010\009\009return\010\009--[[elseif (pose == \034Running\034) then\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)]]\010\009elseif (pose == \034Dead\034 or pose == \034GettingUp\034 or pose == \034FallingDown\034 or pose == \034Seated\034 or pose == \034PlatformStanding\034) then\010--\009\009print(\034Wha \034 .. pose)\010\009\009stopAllAnimations()\010\009\009amplitude = 0.1\010\009\009frequency = 1\010\009\009setAngles = true\010\009end\010\010\009if (setAngles) then\010\009\009--[[desiredAngle = amplitude * math.sin(time * frequency)\010\010\009\009RightShoulder:SetDesiredAngle(desiredAngle + climbFudge)\010\009\009LeftShoulder:SetDesiredAngle(desiredAngle - climbFudge)\010\009\009RightHip:SetDesiredAngle(-desiredAngle)\010\009\009LeftHip:SetDesiredAngle(-desiredAngle)]]\010\009end\010\010\009-- Tool Animation handling\010\009local tool = getTool()\010\009if tool then\010\009\010\009\009--animStringValueObject = getToolAnim(tool)\010\010\009\009--[[if animStringValueObject then\010\009\009\009toolAnim = animStringValueObject.Value\010\009\009\009-- message recieved, delete StringValue\010\009\009\009animStringValueObject.Parent = nil\010\009\009\009toolAnimTime = time + .3\010\009\009end]]\010\010\009\009if time > toolAnimTime then\010\009\009\009toolAnimTime = 0\010\009\009\009toolAnim = \034None\034\010\009\009end\010\010\009\009--animateTool()\009\009\010\009else\010\009\009stopToolAnimations()\010\009\009toolAnim = \034None\034\010\009\009toolAnimInstance = nil\010\009\009toolAnimTime = 0\010\009end\010end\010\010-- connect events\010Humanoid.Died:connect(onDied)\010Humanoid.Running:connect(onRunning)\010--[[Humanoid.Jumping:connect(onJumping)\010Humanoid.Climbing:connect(onClimbing)\010Humanoid.GettingUp:connect(onGettingUp)\010Humanoid.FreeFalling:connect(onFreeFall)\010Humanoid.FallingDown:connect(onFallingDown)\010Humanoid.Seated:connect(onSeated)\010Humanoid.PlatformStanding:connect(onPlatformStanding)\010Humanoid.Swimming:connect(onSwimming)]]\010\010-- main program\010\010local runService = game:service(\034RunService\034);\010\010-- initialize to idle\010playAnimation(\034idle\034, 0.1, Humanoid)\010pose = \034Standing\034\010\010while Figure.Parent~=nil do\010\009--[[print((Torso.Velocity * Vector3.new(1,0,1)).magnitude)\010\009print(pose)]]\010\009if (Torso.Velocity * Vector3.new(1,0,1)).magnitude > 1 and pose ~= \034Running\034 then\010\009\009pose = \034Running\034\010\009\009playAnimation(\034walk\034, 0.1, Humanoid)\010\009elseif (Torso.Velocity * Vector3.new(1,0,1)).magnitude < 1 and pose ~= \034Standing\034 then\010\009\009pose = \034Standing\034\010\009\009playAnimation(\034idle\034, 0.1, Humanoid)\010\009end\010\009local _, time = wait(0.01)\010\009move(time)\010end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28024,class="Script",parent=28023,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Launcher",["ScriptGuid"]="{E5E0FE53-F5F2-4E3F-A78D-DE1AD763EA55}",["Source"]="wait()\010-----------------\010--| Constants |--\010-----------------\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010local GRAVITY_ACCELERATION = 196.2\010\010local RELOAD_TIME = 0.25 -- Seconds until tool can be used again\010local ROCKET_SPEED = 0 -- Speed of the projectile\010\010local MISSILE_MESH_ID = 'rbxassetid://189741947'\010local MISSILE_TEXTURE_ID = 'rbxassetid://189741994'\010local MISSILE_MESH_SCALE = Vector3.new(2.5, 2.5, 2.5)\010local ROCKET_PART_SIZE = Vector3.new(1,1,1)\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Tool = script.Parent\010\010local RocketScript = script:WaitForChild('Rocket')\010--local SwooshSound = script:WaitForChild('Swoosh')\010local BoomSound = script:WaitForChild('Boom')\010--local BoomSound2 = script:WaitForChild('Boom2')\010local ShootSound = Tool.Parent.FakeTorso:WaitForChild('ShootRocket')\010\010local Pod = 1\010\010--NOTE: We create the rocket once and then clone it when the player fires\010local Rocket = Instance.new('Part') do\010\009-- Set up the rocket part\010\009Rocket.Name = 'Rocket'\010\009Rocket.FormFactor = Enum.FormFactor.Custom --NOTE: This must be done before changing Size\010\009Rocket.Size = ROCKET_PART_SIZE\010\009Rocket.CanCollide = false\010\009Rocket.Anchored = true\010\010\009-- Add the mesh\010\009local mesh = Instance.new('SpecialMesh', Rocket)\010\009mesh.MeshId = MISSILE_MESH_ID\010\009mesh.TextureId = MISSILE_TEXTURE_ID\010\009mesh.Scale = MISSILE_MESH_SCALE\010\009mesh.Offset = Vector3.new(0, 0, -1)\010\010\009-- Add fire\010\009--[[local fire = Instance.new('Fire', Rocket)\010\009fire.Heat = 5\010\009fire.Size = 2]]\010\009local fire = script.Effect:Clone()\010\009fire.Enabled = true\010\009fire.Parent = Rocket\010\009\010\009local TargetValue = Instance.new('ObjectValue', Rocket)\010\009TargetValue.Name = 'Target' --NOTE: Must be called 'creator' for website stats\010\009Tool.Parent.TEAM:Clone().Parent = Rocket\010\010\009-- Add a force to counteract gravity\010\009local bodyForce = Instance.new('BodyForce', Rocket)\010\009bodyForce.Name = 'Antigravity'\010\009bodyForce.force = Vector3.new(0, Rocket:GetMass() * GRAVITY_ACCELERATION, 0)\010\010\009-- Clone the sounds and set Boom to PlayOnRemove\010\009--[[local swooshSoundClone = SwooshSound:Clone()\010\009swooshSoundClone.Parent = Rocket]]\010\009local boomSoundClone = BoomSound:Clone()\010\009boomSoundClone.PlayOnRemove = true\010\009boomSoundClone.Parent = Rocket\010\009--[[local boomSoundClone2 = BoomSound2:Clone()\010\009boomSoundClone2.PlayOnRemove = true\010\009boomSoundClone2.Parent = Rocket]]\010\010\009-- Finally, clone the rocket script and enable it\010\009local rocketScriptClone = RocketScript:Clone()\010\009rocketScriptClone.Parent = Rocket\010\009rocketScriptClone.Disabled = false\010end\010\010-----------------\010--| Functions |--\010-----------------\010\010local function Equip()\010\009\010end\010\010local function Unequip()\010\009\010end\010\010local function OnActivated()\010\009local myModel = Tool.Parent\010\009if Tool.Enabled and myModel and myModel:FindFirstChild('Humanoid') and myModel.Humanoid.Health > 0 then\010\009\009Tool.Enabled = false\010\009\009\010\009\009ShootSound:Play()\010\010\009\009-- Create a clone of Rocket and set its color\010\009\009local rocketClone = Rocket:Clone()\010\009\009DebrisService:AddItem(rocketClone, 30)\010\010\009\009rocketClone.Target.Value = myModel.Target.Value\010\010\009\009-- Position the rocket clone and launch!\010\009\009local spawnPosition = (Tool.Parent[\034RocketPod\034..Pod].CFrame * CFrame.new(0, 2, 0)).p\010\009\009rocketClone.CFrame = CFrame.new(spawnPosition, myModel.Target.Value.Position) * CFrame.Angles(math.rad(90), math.rad(-22.5+(math.random()*45)), 0) --NOTE: This must be done before assigning Parent\010\009\009rocketClone.Velocity = rocketClone.CFrame.lookVector --NOTE: This should be done before assigning Parent\010\009\009rocketClone.Parent = Workspace\010\010\009\009Pod = Pod == 1 and 2 or 1\010\010\009\009wait(RELOAD_TIME)\010\010\009\009Tool.Enabled = true\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010--Tool.Activated:connect(OnActivated)\010Tool.Equipped:connect(Equip)\010Tool.Unequipped:connect(Unequip)\010\010while true do\010\009if Tool.Parent.Attack.Value == true then OnActivated() end\010\009game:GetService(\034RunService\034).Stepped:wait()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28026,class="Script",parent=28024,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="Rocket",["ScriptGuid"]="{8ECA6204-2379-4D98-84C6-B8A7F01F30CF}",["Source"]="-----------------\010--| Constants |--\010-----------------\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010local BLAST_RADIUS = 8 -- Blast radius of the explosion\010local BLAST_DAMAGE = 20 -- Amount of damage done to players\010local BLAST_FORCE = 100 -- Amount of force applied to parts\010\010local IGNORE_LIST = {rocket = 1, effect = 1, water = 1} -- Rocket will fly through things named these\010--NOTE: Keys must be lowercase, values must evaluate to true\010\010Explode = Instance.new(\034Part\034)\010Explode.formFactor = \034Custom\034\010Explode.Size = Vector3.new(0,0,0)\010Explode.Anchored = true\010Explode.CanCollide = false\010Explode.TopSurface = 0\010Explode.BottomSurface = 0\010Explode.BrickColor = BrickColor.new(\034Deep orange\034)\010Mesh = Instance.new(\034SpecialMesh\034,Explode)\010Mesh.MeshType = \034Brick\034\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009return hit2,pos2\010end\010\010-----------------\010--| Variables |--\010-----------------\010\010local DebrisService = Game:GetService('Debris')\010local PlayersService = Game:GetService('Players')\010\010local Rocket = script.Parent\010\010--local CreatorTag = Rocket:WaitForChild('creator')\010--local SwooshSound = Rocket:WaitForChild('Swoosh')\010local Target = Rocket:WaitForChild('Target')\010local TEAM = Rocket:WaitForChild('TEAM')\010\010-----------------\010--| Functions |--\010-----------------\010\010-- Removes any old creator tags and applies a new one to the target\010--[[local function ApplyTags(target)\010\009while target:FindFirstChild('creator') do\010\009\009target.creator:Destroy()\010\009end\010\010\009local creatorTagClone = CreatorTag:Clone()\010\009DebrisService:AddItem(creatorTagClone, 1.5)\010\009creatorTagClone.Parent = target\010end]]\010\010-- Returns the ancestor that contains a Humanoid, if it exists\010local function FindCharacterAncestor(subject)\010\009if subject and subject ~= Workspace then\010\009\009local humanoid = subject:FindFirstChild('Humanoid')\010\009\009if humanoid then\010\009\009\009return subject, humanoid\010\009\009else\010\009\009\009return FindCharacterAncestor(subject.Parent)\010\009\009end\010\009end\010\009return nil\010end\010\010-- Customized explosive effect that doesn't affect teammates and only breaks joints on dead parts\010local function OnExplosionHit(hitPart, hitDistance, blastCenter)\010\009if hitPart and hitDistance then\010\009\009local character, humanoid = FindCharacterAncestor(hitPart.Parent)\010\009\009if humanoid and humanoid.Health > 0 then -- Humanoids are tagged and damaged\010\009\009\009if hitPart.Name == 'Torso' then\010\009\009\009\009--ApplyTags(humanoid)\010\009\009\009\009--DamageTag(character,BLAST_DAMAGE)\010\009\009\009\009if humanoid.Parent:FindFirstChild(\034TEAM\034) and humanoid.Parent:FindFirstChild(\034TEAM\034).Value ~= TEAM.Value then\010\009\009\009\009\009humanoid:TakeDamage(BLAST_DAMAGE)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010end\010\010local function OnTouched(otherPart,RayPos)\010\009if Rocket and otherPart then\010\009\009-- Fly through anything in the ignore list\010\009\009if IGNORE_LIST[string.lower(otherPart.Name)] then\010\009\009\009return\010\009\009end\010\010\009\009--[[local myPlayer = CreatorTag.Value\010\009\009if myPlayer then\010\009\009\009-- Fly through the creator\010\009\009\009if myPlayer.Character and myPlayer.Character:IsAncestorOf(otherPart) then\010\009\009\009\009return\010\009\009\009end\010\010\009\009\009 -- Fly through friendlies\010\009\009\009if not myPlayer.Neutral then\010\009\009\009\009local character = FindCharacterAncestor(otherPart.Parent)\010\009\009\009\009local player = PlayersService:GetPlayerFromCharacter(character)\010\009\009\009\009if player and player ~= myPlayer and player.TeamColor == Rocket.BrickColor then\010\009\009\009\009\009return\010\009\009\009\009end\010\009\009\009end\010\009\009end]]\010\010\009\009-- Fly through terrain water\010\009\009if otherPart == Workspace.Terrain then\010\009\009\009--NOTE: If the rocket is large, then the simplifications made here will cause it to fly through terrain in some cases\010\009\009\009local frontOfRocket = Rocket.Position + (Rocket.CFrame.lookVector * (Rocket.Size.Z / 2))\010\009\009\009local cellLocation = Workspace.Terrain:WorldToCellPreferSolid(frontOfRocket)\010\009\009\009local cellMaterial = Workspace.Terrain:GetCell(cellLocation.X, cellLocation.Y, cellLocation.Z)\010\009\009\009if cellMaterial == Enum.CellMaterial.Water or cellMaterial == Enum.CellMaterial.Empty then\010\009\009\009\009return\010\009\009\009end\010\009\009end\010\009\009\010\009\009Rocket.Transparency = 1\010\009\009Rocket.CFrame = CFrame.new(RayPos.X,RayPos.Y,RayPos.Z)\010\010\009\009-- Create the explosion\010\009\009local explosion = Instance.new('Explosion')\010\009\009explosion.BlastPressure = 5000 -- Completely safe explosion\010\009\009explosion.BlastRadius = BLAST_RADIUS\010\009\009explosion.DestroyJointRadiusPercent = 0\010\009\009explosion.ExplosionType = Enum.ExplosionType.NoCraters\010\009\009explosion.Position = Rocket.Position\010\009\009explosion.Parent = Workspace\010\010\009\009-- Connect custom logic for the explosion\010\009\009explosion.Hit:connect(function(hitPart, hitDistance) OnExplosionHit(hitPart, hitDistance, explosion.Position) end)\010\009\009\010\009\009--[[ypcall(function()\010\009\009\009for i = 1, 3 do\010\009\009\009\009ExplodeClone = Explode:clone()\010\009\009\009\009ExplodeClone.Position = Rocket.Position\010\009\009\009\009ExplodeClone.Mesh.Scale = Vector3.new(5,5,5)*5\010\009\009\009\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009\009\009\009ExplodeClone.Parent = Workspace\010\009\009\009\009NewScript = Rocket.Script:clone()\010\009\009\009\009NewScript.Disabled = false\010\009\009\009\009NewScript.Parent = ExplodeClone\010\009\009\009end\010\009\009end)]]\010\010\009\009-- Move this script and the creator tag (so our custom logic can execute), then destroy the rocket\010\009\009script.Parent = explosion\010\009\009--CreatorTag.Parent = script\010\009\009Rocket:Destroy()\010\009end\010end\010\010--------------------\010--| Script Logic |--\010--------------------\010\010--SwooshSound:Play()\010\010--Rocket.Touched:connect(OnTouched)\010\010local RotSpeed = 0\010\010for i = 1,math.huge do\010\009if RotSpeed < 0.375 then RotSpeed = RotSpeed + 0.0125 end\010\009--[[ExplodeClone = Explode:clone()\010\009ExplodeClone.Name = \034Effect\034\010\009ExplodeClone.BrickColor = BrickColor.new(\034White\034)\010\009ExplodeClone.Position = Rocket.Position\010\009ExplodeClone.Mesh.Scale = Vector3.new(1,1,1)*5\010\009ExplodeClone.CFrame = ExplodeClone.CFrame * CFrame.fromEulerAnglesXYZ(math.random(-10000,10000)/100,math.random(-10000,10000)/100,math.random(-10000,10000)/100)\010\009ExplodeClone.Parent = Workspace\010\009NewScript = Rocket.Trail:clone()\010\009NewScript.Disabled = false\010\009NewScript.Parent = ExplodeClone]]\010\009if Target.Value ~= nil and Target.Value.Parent ~= nil then\010\009\009if Target.Value then idealVelocity = --[[SPEED *]] (Target.Value.Position - Rocket.Position).unit end\010\009\009Rocket.Velocity = --[[SPEED *]] (Rocket.Velocity + RotSpeed * (idealVelocity - Rocket.Velocity)).unit\010\009\009Rocket.CFrame = CFrame.new(Rocket.Position, Rocket.Position + Rocket.Velocity)\010\009end\010\009local hit,pos = raycast(Rocket.Position,((Rocket.CFrame * CFrame.new(0,0,-10)).p-Rocket.Position).unit,10)\010\009if hit then\010\009\009OnTouched(hit,pos)\010\009end\010\009Rocket.CFrame = Rocket.CFrame * CFrame.new(0,0,-2.5)-- * CFrame.Angles(0, 0, math.rad(18))\010\009game:GetService(\034RunService\034).Stepped:wait()\010\009if script.Parent ~= Rocket then break end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28043,class="Script",parent=28030,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Firescript",["ScriptGuid"]="{C914DD54-8EB3-4297-9C81-A2A450CF1250}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010check=true\010\010gundamage=20\009\009\009\009\009\009\009\009--Base output damage per shot.\010firerate=.1\009\009\009\009\009\009\009\009--How often the weapon can fire.\010automatic=true\009\009\009\009\009\009\009--hold down to continue firing\010range=1000\009\009\009\009\009\009\009\009\009--Max distance that the weapon can fire.\010spread=2\009\009\009\009\009\009\009\009\009\009--The bigger the spread, the more inaccurate the shots will be.\010clipsize=20\009\009\009\009\009\009\009\009\009--Shots in a clip\010reloadtime=3\009\009\009\009\009\009\009\009--Time it takes to reload the tool.\010startingclips=10\009\009\009\009\009\009\009--If you want infinit clips, remove the IntValue named \034Clips\034 from the tool.\010segmentlength=25\009\009\009\009\009\009\009--How long the shot segments are, or the speed of the shot.\010fadedelaytime=1/30\010\010\010barrelpos=CFrame.new(0,0,0.5)\009\009--R,U,B\010rate=1/100\010intangibles={\034Shock\034,\034Bolt\034,\034Bullet\034,\034Plasma\034,\034Effect\034,\034Laser\034,\034Handle\034,\034Effects\034,\034Effect\034,\034Flash\034}\010colors={BrickColor.new(\034Really red\034),BrickColor.new(\034Pastel blue-green\034),BrickColor.new(\034Lime green\034),BrickColor.new(\034New Yeller\034)}\010flashcolors={\034Really red\034}\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010reloading=false\010local debris=game:GetService(\034Debris\034)\010\010local ammo=sp:FindFirstChild(\034Ammo\034)\010if ammo~=nil then\010\009ammo.Value=clipsize\010end\010local clips=sp:FindFirstChild(\034Clips\034)\010if clips~=nil then\010\009clips.Value=startingclips\010end\010\010sp.Equipped:connect(function()\010\009sp.Parent.Eye.Fire:Stop()\010\009sp.Parent.Eye.Reload:Stop()\010end)\010sp.Unequipped:connect(function()\010\009sp.Parent.Eye.Fire:Stop()\010\009sp.Parent.Eye.Reload:Stop()\010end)\010\010function round(number,decimal)\010\009decimal=decimal or 0\010\009local mult=10^decimal\010\009return math.floor(number*mult+.5)/mult\010end\010\010function checkintangible(t)\010\009for i3,v3 in ipairs(intangibles) do\010\009\009if string.lower(v3)==string.lower(t.Name) or t.Transparency==1 then\010\009\009\009return true\010\009\009end\010\009end\010\009return false\010end\010\010function reload()\010\009reloading=true\010\009sp.Reloading.Value=true\010\009if clips~=nil then\010\009\009if clips.Value>0 then\010\009\009\009clips.Value=clips.Value-1\010\009\009else\010\009\009\009reloading=false\010\009\009\009sp.Reloading.Value=false\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Eye.Reload:Play()\010\009for i=1,clipsize do\010\009\009wait(reloadtime/clipsize)\010\009\009ammo.Value=i\010\009end\010\009reloading=false\010\009sp.Reloading.Value=false\010end\010\010function castray(startpos,vec,length,ignore,delayifhit)\010\009if length>999 then\010\009\009length=999\010\009end\010\009hit,endpos2=game.Workspace:FindPartOnRay(Ray.new(startpos,vec*length),ignore)\010\009if hit~=nil then\010\009\009if checkintangible(hit) then\010\009\009\009if delayifhit then\010\009\009\009\009wait()\010\009\009\009end\010\009\009\009hit,endpos2=castray(endpos2+(vec*.01),vec,length-((startpos-endpos2).magnitude),ignore,delayifhit)\010\009\009end\010\009end\010\009return hit,endpos2\010end\010\010function sendbullet(boltstart,targetpos,fuzzyness,segmentlength,ignore,clr,damage,fadedelay)\010\009if ammo~=nil then\010\009\009if ammo.Value>0 then\010\009\009\009ammo.Value=ammo.Value-1\010\009\009else\010\009\009\009reload()\010\009\009\009return\010\009\009end\010\009end\010\009sp.Parent.Eye.Fire:Play()\010\009muzzleeffect()\010\009local t=sp.Parent:FindFirstChild(\034Torso\034)\010\009if t~=nil then\010\009\009local shoulder=t:FindFirstChild(\034Right Shoulder\034)\010\009\009if shoulder~=nil then\010\009\009\009shoulder.CurrentAngle=2\010\009\009end\010\009end\010\010\009local boltdist=range\010\009local clickdist=(boltstart-targetpos).magnitude\010\009local targetpos=targetpos+(Vector3.new(math.random()-.5,math.random()-.5,math.random()-.5)*(clickdist/100)*fuzzyness)\010\009local boltvec=(targetpos-boltstart).unit\010\009local totalsegments=math.ceil(boltdist/segmentlength)\010\009local lastpos=boltstart\010\009for i=1,totalsegments do\010\009\009local newpos=(boltstart+(boltvec*(boltdist*(i/totalsegments))))\010\009\009local segvec=(newpos-lastpos).unit\010\009\009local boltlength=(newpos-lastpos).magnitude\010\009\009local bolthit,endpos=castray(lastpos,segvec,boltlength,ignore,false)\010\009\009drawbeam(lastpos,endpos,clr,fadedelay)\010\009\009if bolthit~=nil then\010\009\009\009local h=bolthit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009\009local t=bolthit.Parent:FindFirstChild(\034TEAM\034)\010\009\009\009if h~=nil and t and t.Value ~= sp.Parent.TEAM.Value then\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009end\010\009\009\009break\010\009\009end\010\009\009lastpos=endpos\010\009\009wait(rate)\010\009end\010end\010\010function drawbeam(beamstart,beamend,clr,fadedelay)\010\009local dis=(beamstart-beamend).magnitude\010\009local laser=Instance.new(\034Part\034)\010\009laser.Name=\034Bullet\034\010\009laser.Transparency = 0\010\009laser.Anchored=true\010\009laser.CanCollide=false\010\009laser.Shape=\034Block\034\010\009laser.formFactor=\034Custom\034\010\009laser.Size=Vector3.new(.375,.375,dis+.2)\010\009laser.Material=Enum.Material.Neon\010\009laser.Locked=true\010\009laser.TopSurface=0\010\009laser.BottomSurface=0\010\009laser.BrickColor=clr\010\009laser.CFrame=CFrame.new(beamend,beamstart)*CFrame.new(0,0,-dis/2)\010\009--[[local mesh = Instance.new(\034BlockMesh\034,laser)\010\009mesh.Scale = Vector3.new(10,0,1)\010\009local decal = Instance.new(\034Decal\034,laser)\010\009decal.Face = \034Top\034\010\009decal.Texture = \034rbxassetid://201063866\034\010\009decal.Transparency = 0.25\010\009local decal2 = decal:Clone()\010\009decal2.Face = \034Bottom\034\010\009decal2.Parent = decal.Parent]]\010\009local light = script.SurfaceLight:Clone()\010\009light.Enabled = true\010\009light.Face = \034Top\034\010\009light.Parent = laser\010\009local light2 = script.SurfaceLight:Clone()\010\009light2.Enabled = true\010\009light.Face = \034Bottom\034\010\009light2.Parent = laser\010\009laser.Parent=game.Workspace\010\009debris:AddItem(laser,fadedelay)\010end\010\010function muzzleeffect()\010\009local flash=Instance.new(\034Part\034)\010\009flash.Name=\034Effect\034\010\009flash.Anchored=true\010\009flash.CanCollide=false\010\009flash.Shape=\034Block\034\010\009flash.formFactor=\034Custom\034\010\009flash.Size=Vector3.new(.2,.2,.2)\010\009flash.Material=Enum.Material.Plastic\010\009flash.Locked=true\010\009flash.TopSurface=0\010\009flash.BottomSurface=0\010\009flash.BrickColor=BrickColor.new(flashcolors[math.random(1,#flashcolors)])\010\009local mesh=Instance.new(\034SpecialMesh\034)\010\009mesh.MeshId=\034http://www.roblox.com/asset/?id=25212400\034\010\009local scale=Vector3.new(.2+(math.random()*.1),.4+(math.random()*.4),.2+(math.random()*.1))\010\009mesh.Scale=scale\010\009mesh.Parent=flash\010\009flash.CFrame=sp.Parent.Eye.CFrame*barrelpos*CFrame.Angles(0,math.pi*2*math.random(),0)*CFrame.new(0,scale.y*.9,0)\010\009debris:AddItem(flash,rate)\010\009flash.Parent=game.Workspace\010end\010\010sp.Down.Changed:connect(function()\010\009while sp.Down.Value and check and not reloading do\010\009\009check=false\010\009\009local humanoid=sp.Parent:FindFirstChild(\034Humanoid\034)\010\009\009if humanoid~=nil then\010\009\009\009if humanoid.Health>0 then\010\009\009\009\009spos1=(sp.Parent.Eye.CFrame*barrelpos).p\010\009\009\009\009delay(0,function() sendbullet(spos1,sp.Aim.Value,spread,segmentlength,sp.Parent,colors[1],gundamage,fadedelaytime) end)\010\009\009\009else\010\009\009\009\009check=true\010\009\009\009\009break\010\009\009\009end\010\009\009else\010\009\009\009check=true\010\009\009\009break\010\009\009end\010\009\009wait(firerate)\010\009\009check=true\010\009\009if not automatic then\010\009\009\009break\010\009\009end\010\009end\010end)\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28045,class="Script",parent=27837,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{2DE51547-97B4-46F0-AD4F-899316BA3D6D}",["Source"]="wait(1)\010local NPC = script.Parent\010local Humanoid = NPC:WaitForChild(\034Humanoid\034)\010local AttackEnabled = true\010local TargetAlreadyHit = {}\010local TimerForAbility = 0\010\010local Torso = NPC:WaitForChild(\034Torso\034)\010local AttackAnim = Humanoid:LoadAnimation(NPC.AttackAnim)\010local DeathAnim = Humanoid:LoadAnimation(NPC.DeathAnim)\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),NPC)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==NPC and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == NPC.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010function AOEDamage(pos,radius,damage)\010\009local NumberOfTargetInsideRadius = 0\010\009local temp = Workspace:GetChildren()\010\009for i = 1,#temp do\010\009\009if temp[i] ~= NPC then\010\009\009\009local ThisHumanoidIsAlreadyDamaged = false\010\009\009\009local human = temp[i]:findFirstChild(\034Humanoid\034)\010\009\009\009local torso = temp[i]:findFirstChild(\034Torso\034)\010\009\009\009local team = temp[i]:findFirstChild(\034TEAM\034)\010\009\009\009if Humanoid.Health ~= 0 and human ~= nil and torso ~= nil and human.Health ~= 0 and team and team.Value ~= NPC.TEAM.Value then\010\009\009\009\009--print(\034Found both Humanoid and Torso\034)\010\009\009\009\009for _, Humanoids in pairs(TargetAlreadyHit) do\010\009\009\009\009\009if Humanoids == human then ThisHumanoidIsAlreadyDamaged = true end\010\009\009\009\009\009--print(\034That Humanoid is already took a damage\034)\010\009\009\009\009end\010\009\009\009\009--print(\034Current: \034..(pos - torso.Position).magnitude)\010\009\009\009\009--print(\034Should: \034..radius + (torso.Size.magnitude/2.5))\010\009\009\009\009if (pos - torso.Position).magnitude < radius + (torso.Size.magnitude/2.5) and ThisHumanoidIsAlreadyDamaged == false then\010\009\009\009\009\009table.insert(TargetAlreadyHit,human)\010\009\009\009\009\009--print(\034Add Humanoid to table\034)\010\009\009\009\009\009NumberOfTargetInsideRadius = NumberOfTargetInsideRadius + 1\010\009\009\009\009\009NPC.FakeTorso.ClawHit:Play()\010\009\009\009\009\009human:TakeDamage(damage)\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return NumberOfTargetInsideRadius\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= NPC) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and team and team.Value ~= NPC.TEAM.Value then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009NPC.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009NPC.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009NPC.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function HumanoidChanged(Property)\010\009if Property == \034Sit\034 --[[and Humanoid.Sit == true]] then \010\009\009Humanoid.Sit = false \010\009end \010end \010\010Humanoid.Changed:connect(HumanoidChanged)\010\010NPC.Torso.Changed:connect(function(Value)\010\009if Value == \034Velocity\034 then\010\009\009NPC.Torso.Velocity = Vector3.new(0,0,0)\010\009end\010end)\010\010local CurrentHealth = Humanoid.Health\010local Defeated = false\010Humanoid.HealthChanged:connect(function()\010\009if Defeated then return end\010\009local Health = math.min(Humanoid.Health-CurrentHealth)\010\009if CurrentHealth-1 < -Health then\010\009\009Humanoid.Health = 0.1\010\009\009if not NPC:FindFirstChild(\034DEFEATED\034) then\010\009\009\009local DeathTag = Instance.new(\034ObjectValue\034,NPC)\010\009\009\009DeathTag.Name = \034DEFEATED\034\010\009\009end\010\009end\010\009CurrentHealth = Humanoid.Health\010end)\010\010TimerForAbility = 0.5 + (math.random()*3)\010\010while true do\010\009wait(0.1)\010\009TimerForAbility = TimerForAbility - 0.1\010\009local target = findNearestTorso(NPC.Torso.Position)\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009NPC.Attack.Value = false\010\009\009Humanoid.WalkSpeed = 50\010\009\009Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009\009if (NPC.Torso.Position - target.Position).magnitude < (30 + (target.Size.magnitude * 1.25)) then\010\009\009\009Humanoid.WalkSpeed = 0.1\010\009\009\009if AttackAnim then AttackAnim:Play() end\010\009\009\009wait(0.5)\010\009\009\009for i = 1,2 do\010\009\009\009\009if target then\010\009\009\009\009\009AOEDamage(NPC.Torso.Position + (NPC.Torso.CFrame.lookVector * 20),30,250)\010\009\009\009\009end\010\009\009\009\009wait(0.125)\010\009\009\009\009TargetAlreadyHit = {}\010\009\009\009end\010\009\009elseif TimerForAbility < 1 then\010\009\009\009local AbilityToChoose = math.random(1,2)\010\009\009\009if AbilityToChoose == 1 then --Laser-Eye\010\009\009\009\009Humanoid.WalkSpeed = 0\010\009\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009\009NPC.EyeLaser.Down.Value=true\010\009\009\009\009Spawn(function()\010\009\009\009\009\009while NPC.EyeLaser.Down.Value do\010\009\009\009\009\009\009NPC.EyeLaser.Aim.Value = target.Position\010\009\009\009\009\009\009wait()\010\009\009\009\009\009end\010\009\009\009\009end)\010\009\009\009\009wait(1 + (math.random()*1))\010\009\009\009\009NPC.EyeLaser.Down.Value=false\010\009\009\009elseif AbilityToChoose == 2 then --Rocket launcher\010\009\009\009\009Humanoid.WalkSpeed = 0\010\009\009\009\009NPC.Attack.Value = true\010\009\009\009\009wait(2.5 + (math.random()*2.5))\010\009\009\009\009NPC.Attack.Value = false\010\009\009\009end\010\009\009\009TimerForAbility = 0.5 + (math.random()*3)\010\009\009else\010\009\009\009Humanoid.WalkSpeed = 50\010\009\009end\010\009else \010\009\009NPC.Range.Value = false \010\009\009NPC.Attack.Value = false \010\009end\010\009if NPC:FindFirstChild(\034DEFEATED\034) then --Special death animation\010\009\009NPC.FakeTorso.PreDeath:Play()\010\009\009NPC.PreDeath:Play()\010\009\009Humanoid.WalkSpeed = 0\010\009\009if DeathAnim then DeathAnim:Play() end\010\009\009wait(3)\010\009\009NPC.FakeTorso.PreDeath:Stop()\010\009\009Defeated = true\010\009\009NPC:BreakJoints()\010\009end\010end\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28060,class="Script",parent=27837,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="README",["ScriptGuid"]="{D687D3F0-6474-494B-9387-E0BA364DFB69}",["Source"]="--[[\010\009\010This NPC has custom animation made by SuperEvilAzmil (Me). There are:\010-Attack\010-Death\010-Idle\010-Walk\010\010These animation won't be played in your game. For this, I've saved 4 of these animation in \034AnimSaves\034 model so you can upload it and make it animated.\010\010Step 1: Open Animation Editor and select this NPC\010Step 2: Go to File >>> Open\010Step 3: Select \034Walk\034 and then click Load\010Step 4: Go to File >>> Export to upload animation\010Step 5: Copy your uploaded animation and paste it to This NPC >>> \034Animate\034 script >>> \034walk\034 >>> \034WalkAnim\034 >>> AnimationId\010Step 6: Repeat from Step 3 with \034Idle\034 animation\010Step 7: After you uploaded \034Idle\034 animation, copy your uploaded animation and paste it to This NPC >>> \034Animate\034 script >>> \034idle\034 >>> both \034Animation1\034 and \034Animation2\034 >>> AnimationId\010Step 8: Further repeat from Step 3 with \034Attack\034 animation\010Step 9: After you uploaded \034Attack\034 animation, copy your uploaded animation and paste it to This NPC >>> \034AttackAnim\034 >>> AnimationId\010Step 10: Further repeat from Step 3 with \034Death\034 animation\010Step 11: After you uploaded \034Death\034 animation, copy your uploaded animation and paste it to This NPC >>> \034DeathAnim\034 >>> AnimationId\010Step 12: Done!\010\010--]]",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28061,class="Script",parent=27837,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Explode",["ScriptGuid"]="{B9F93250-F94B-4F8E-AC16-1A60B3953410}",["Source"]="local Model = script.Parent\010local Humanoid = Model.Humanoid\010\010function ChooseRandomPart()\010\009local PartToChoose = {}\010\009for _, Child in pairs(Model:GetChildren()) do\010\009\009if Child:IsA(\034BasePart\034) then\010\009\009\009table.insert(PartToChoose,Child)\010\009\009end\010\009end\010\009return PartToChoose[math.random(1,#PartToChoose)]\010end\010\010function Die()\010\009if script.Parent.Torso:findFirstChild(\034BodyPosition\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyPosition\034):remove() end\010\009if script.Parent.Torso:findFirstChild(\034BodyGyro\034) ~= nil then script.Parent.Torso:findFirstChild(\034BodyGyro\034):remove() end\010\010\009script.Parent.ChaseScript.Disabled = true\010\009script.Parent.Attack.Value = false\010\009script.Parent.Death:Play()\010\009local e = Instance.new(\034Explosion\034,workspace)\010\009e.BlastPressure = 0\010\009e.BlastRadius = 10\010\009e.Position = script.Parent.Torso.Position\010\009local parts = script.Parent:children()\010\009for i = 1,#parts do\010\009\009if parts[i].className == \034Part\034 or parts[i].className == \034WedgePart\034 or parts[i].className == \034CornerWedgePart\034 or parts[i].className == \034UnionOperation\034 then\010\009\009\009parts[i].Velocity = Vector3.new(math.random(-75,75),math.random(75,150),math.random(-75,75))\010\009\009\009parts[i].CanCollide = true\010\009\009end\010\009end\010\010\009wait(10)\010\009script.Parent:remove() \010end \010\010Humanoid.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28062,class="Script",parent=27837,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{046E558B-718A-4676-8E52-08D3F14E2786}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009game.workspace.Scripts.WaveScript.Dead_Zombies.Value = game.workspace.Scripts.WaveScript.Dead_Zombies.Value + 1\010\009wait(2.5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28063,class="Script",parent=27837,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="PP",["ScriptGuid"]="{6470235B-CA96-4F46-A9E0-62FBD363BF92}",["Source"]="print(\034Hello world!\034)\010\010Character = script.Parent\010Humanoid = Character.Humanoid\010Torso = Character.Torso\010\010local Humanoid = script.Parent.Humanoid\010function PwntX_X() \010local tag = Humanoid:findFirstChild(\034creator\034) \010if tag ~= nil then \010if tag.Value ~= nil then \010local Leaderstats = tag.Value:findFirstChild(\034leaderstats\034) \010if Leaderstats ~= nil then\010game:GetService(\034PointsService\034):AwardPoints(tag.Value.userId,1000)\010end \010end \010end \010end \010Humanoid.Died:connect(PwntX_X) \010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28065,class="Script",parent=28064,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{C306B581-E812-413D-817D-2677416D6E29}",["Source"]="local d = script.Parent\010local ch1 = d.Poke\010local ch2 = d.Elijah\010local ch3 = d.Kyle\010local ch4 = d.Nooby\010\010local Model1 = game.lighting.Allies[\034Pokemonfan571\034]:Clone()\010local Model2 = game.lighting.Allies[\034elijah54403\034]:Clone()\010local Model3 = game.lighting.Allies[\034KyleChu\034]:Clone()\010local Model4 = game.lighting.Allies[\034NoobyGames123\034]:Clone()\010\010d.DialogChoiceSelected:connect(function(plr, choice)\010\009if choice == ch1 then\010\009\009if plr.leaderstats.Coin.Value >= 0 then\009\009\009\010\009\009\009local CloneModel = Model1:Clone()\010\009\009\009CloneModel:MakeJoints()\010\009\009\009CloneModel.Parent = game.Workspace\010\009\009\009CloneModel:MakeJoints()\010\009\009\009plr.leaderstats.Coin.Value = plr.leaderstats.Coin.Value - 0\010\009\009\009end\010\009\009end\010\009\010\009if choice == ch2 then\010\009\009if plr.leaderstats.Coin.Value >= 0 then\009\009\009\010\009\009\009local CloneMode2 = Model2:Clone()\010\009\009\009CloneMode2:MakeJoints()\010\009\009\009CloneMode2.Parent = game.Workspace\010\009\009\009CloneMode2:MakeJoints()\010\009\009\009plr.leaderstats.Coin.Value = plr.leaderstats.Coin.Value - 0\010\009\009\009end\010\009end\010\009\010\009if choice == ch3 then\010\009\009if plr.leaderstats.Coin.Value >= 0 then\009\009\009\010\009\009\009local CloneMode3 = Model3:Clone()\010\009\009\009CloneMode3:MakeJoints()\010\009\009\009CloneMode3.Parent = game.Workspace\010\009\009\009CloneMode3:MakeJoints()\010\009\009\009plr.leaderstats.Coin.Value = plr.leaderstats.Coin.Value - 0\010\009\009\009end\010\009end\010\009\010\009if choice == ch4 then\010\009\009if plr.leaderstats.Coin.Value >= 0 then\009\009\009\010\009\009\009local CloneMode4 = Model4:Clone()\010\009\009\009CloneMode4:MakeJoints()\010\009\009\009CloneMode4.Parent = game.Workspace\010\009\009\009CloneMode4:MakeJoints()\010\009\009\009plr.leaderstats.Coin.Value = plr.leaderstats.Coin.Value - 0\010\009\009\009end\010\009end\010\009end)\010\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28072,class="Script",parent=28070,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Script",["ScriptGuid"]="{F8A7D4E7-287E-4E5D-86DE-31C0AC319A3D}",["Source"]="--Made by Stickmasterluke\010\010\010sp=script.Parent\010\010\010damage=100\010range=2500\010damagedealthdebounch = false\010DeathDB = false\010\010meshes={114647745,114647773,114647802,114647836,114647881,114647920,114647944}\010standingmesh=114636624\010--Accidental mesh with no legs. Maybe someone wants it anyways -> 115975800\010\010local head=sp:WaitForChild(\034Head\034)\010local hum=sp:WaitForChild(\034Humanoid\034)\010local torso=sp:WaitForChild(\034Torso\034)\010local mesh=torso:WaitForChild(\034Mesh\034)\010--local ct=sp:WaitForChild(\034creator\034)\010local debris=game:GetService(\034Debris\034)\010\010alive=true\010currentmesh=0\010nextmove=0\010\010function raycast(spos,vec,currentdist)\010\009local hit2,pos2=game.Workspace:FindPartOnRay(Ray.new(spos+(vec*.01),vec*currentdist),script.Parent)\010\009if hit2~=nil and pos2 then\010\009\009if hit2.Parent==script.Parent and hit2.Transparency>=.8 or hit2.Name==\034Handle\034 or string.sub(hit2.Name,1,6)==\034Effect\034 or hit2.Parent:IsA(\034Hat\034) or hit2.Parent:IsA(\034Tool\034) or (hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.Parent:FindFirstChild(\034TEAM\034) and hit2.Parent:FindFirstChild(\034TEAM\034).Value == script.Parent.TEAM.Value) or (not hit2.Parent:FindFirstChild(\034Humanoid\034) and hit2.CanCollide==false) then\010\009\009\009local currentdist=currentdist-(pos2-spos).magnitude\010\009\009\009return raycast(pos2,vec,currentdist)\010\009\009end\010\009end\010\009return hit2,pos2\010end\010\010torso.Touched:connect(function(hit)\010\009local TEAM = hit.Parent:FindFirstChild(\034TEAM\034)\010\009if hit and hit.Parent and hit.Parent.Name~=sp.Name and alive and TEAM and TEAM.Value~=sp.TEAM.Value then\010\009\009local h=hit.Parent:FindFirstChild(\034Humanoid\034)\010\009\009if h~=nil then\010\009\009\009local plr=game.Players:GetPlayerFromCharacter(hit.Parent)\010\009\009\009if plr then\010\009\009\009\009--[[if plr==ct.Value then\010\009\009\009\009\009return\010\009\009\009\009end]]\010\009\009\009end\010\009\009\009if damagedealthdebounch == false then\010\009\009\009\009damagedealthdebounch = true\010\009\009\009\009torso.Bite:Play()\010\009\009\009\009h:TakeDamage(damage)\010\009\009\009\009Delay(0.25,function() damagedealthdebounch = false end)\010\009\009\009end\010\009\009end\010\009end\010end)\010\010hum.Changed:connect(function(prop)\010\009if hum then\010\009\009if hum.Health<=0 then\010\009\009\009if DeathDB == true then return end\010\009\009\009DeathDB = true\010\009\009\009alive=false\010\009\009\009if torso then\010\009\009\009\009torso.Footstep:Stop()\010\009\009\009\009torso.Death:Play()\010\009\009\009\009torso.Anchored=true\010\009\009\009\009if head then\010\009\009\009\009\009head:remove()\010\009\009\009\009end\010\009\009\009\009for i = 1,4 do\010\009\009\009\009\009torso.CFrame = torso.CFrame * CFrame.Angles(0,0,math.rad(22.5))\010\009\009\009\009\009wait(0.0125)\010\009\009\009\009end\010\009\009\009\009wait(0.7)\010\009\009\009\009torso.Mesh.VertexColor = Vector3.new(1,0.75,0.75)\010\009\009\009\009wait(0.1)\010\009\009\009\009torso.Mesh.VertexColor = Vector3.new(1,0.5,0.5)\010\009\009\009\009wait(0.1)\010\009\009\009\009torso.Mesh.VertexColor = Vector3.new(1,0.25,0.25)\010\009\009\009\009wait(0.1)\010\009\009\009\009torso.Mesh.VertexColor = Vector3.new(1,0,0)\010\009\009\009\009hum:remove()\010\009\009\009\009--[[local f=Instance.new(\034Fire\034)\010\009\009\009\009f.Parent=torso]]\010\009\009\009\009wait(15)\010\009\009\009\009for i = 0,1,0.1 do\010\009\009\009\009\009torso.Transparency = i\010\009\009\009\009\009wait(0.1)\010\009\009\009\009end\010\009\009\009end\010\009\009\009sp:remove()\010\009\009end\010\009else\010\009\009alive=false\010\009\009sp:remove()\010\009end\010end)\010\010Spawn(function()\010\009while hum and hum.Health~=0 do\010\009\009if torso and mesh then\010\009\009\009if torso.Velocity.magnitude>3 then\010\009\009\009\009currentmesh=currentmesh+1\010\009\009\009\009mesh.MeshId=\034http://www.roblox.com/asset/?id=\034..tostring(meshes[(currentmesh%(#meshes))+1])\010\009\009\009\009if mesh.MeshId==\034http://www.roblox.com/asset/?id=114647944\034 or mesh.MeshId==\034http://www.roblox.com/asset/?id=114647836\034 then\010\009\009\009\009\009torso.Footstep:Play()\010\009\009\009\009end\010\009\009\009else\010\009\009\009\009mesh.MeshId=\034http://www.roblox.com/asset/?id=\034..tostring(standingmesh)\010\009\009\009end\010\009\009end\010\009\009wait(0.05)\010\009end\010end)\010\010while alive do\010\009local t1,t2=wait(.05)\010\009if t2>nextmove then\010\009\009nextmove=t2+.5+math.random()\010\009\009closest=range\010\009\009target=nil\010\009\009for i,v in ipairs(game.Workspace:GetChildren()) do\009\009\009\009--targets every thing named humanoid that is in a model in workspace and is not another spide\010\009\009\009if v and v.className==\034Model\034 and v.Name~=sp.Name then\010\009\009\009\009local t=v:FindFirstChild(\034Torso\034)\010\009\009\009\009local h=v:FindFirstChild(\034Humanoid\034)\010\009\009\009\009local TEAM = v:FindFirstChild(\034TEAM\034)\010\009\009\009\009if t~=nil and h~=nil and h.Health>0 and TEAM and TEAM.Value~=sp.TEAM.Value then\010\009\009\009\009\009safe=false\010\009\009\009\009\009local plr=game.Players:GetPlayerFromCharacter(v)\010\009\009\009\009\009if plr then\010\009\009\009\009\009\009--[[if plr==ct.Value then\010\009\009\009\009\009\009\009safe=true\010\009\009\009\009\009\009end]]\010\009\009\009\009\009end\010\009\009\009\009\009if not safe then\010\009\009\009\009\009\009local mag=(t.Position-torso.Position).magnitude\010\009\009\009\009\009\009if mag<closest then\010\009\009\009\009\009\009\009target=t\010\009\009\009\009\009\009\009closest=mag\010\009\009\009\009\009\009end\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009\009\009offset=target.Position+(Vector3.new(math.random()-.5,math.random()-.5,math.random()-.5)*6)\010\009\009\009--hum.WalkToPoint=point\010\009\009\009hum:MoveTo(offset,target)\010\009\009\009--[[if math.random()<.15 then\010\009\009\009\009hum.Jump=true\010\009\009\009end]]\010\009\009\009end\010\009\009end\010\010\010",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28079,class="Script",parent=28074,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="JumpScript",["ScriptGuid"]="{587C83DF-6428-41DD-949C-6965B4E34143}",["Source"]="local sp = script.Parent\010local Humanoid = sp.Parent:WaitForChild(\034Humanoid\034)\010\010Humanoid.Jumping:connect(function()\010\009sp.Jump:Play()\010\009sp.Mesh.Scale = Vector3.new(1.5,5,1.5)\010\009for i = 1,5 do\010\009\009if i == 5 then\010\009\009\009sp.Mesh.Scale = Vector3.new(3,3,3)\010\009\009else\010\009\009\009sp.Mesh.Scale = sp.Mesh.Scale + ((Vector3.new(3,3,3)-sp.Mesh.Scale)/5)\010\009\009end\010\009\009wait(0.02)\010\009end\010end)",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28083,class="Script",parent=28070,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="Die",["ScriptGuid"]="{6C8F7A9D-39F4-4222-9BCD-C9D8A468986A}",["Source"]="human = script.Parent.Humanoid\010--tool = script.Parent.Pistol\010\010function Die()\010\009--if tool ~= nil then tool:remove() end\010\009game.workspace.Scripts.WaveScript.Dead_Zombies.Value = game.workspace.Scripts.WaveScript.Dead_Zombies.Value + 1\010\009wait(2.5)\010\009script.Parent:remove() \010end \010\010human.Died:connect(Die)",["SourceAssetId"]=-1,["Tags"]=""}}
