T[#T+1]={id=28102,class="Script",parent=28084,props={["AttributesSerialize"]="",["Disabled"]=false,["LinkedSource"]="",["Name"]="ChaseScript",["ScriptGuid"]="{717E10A4-21D0-4600-BAD9-D7F779A9CE07}",["Source"]="local larm = script.Parent:FindFirstChild(\034Left Arm\034)\010local rarm = script.Parent:FindFirstChild(\034Right Arm\034)\010local waitTimer = 0\010local GiveShieldCooldown = 30\010local GiveShieldReady = true\010\010function wait(TimeToWait)\010\009if TimeToWait ~= nil then\010\009\009local TotalTime = 0\010\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009while TotalTime < TimeToWait do\010\009\009\009TotalTime = TotalTime + game:GetService(\034RunService\034).Heartbeat:wait()\010\009\009end\010\009else\010\009\009game:GetService(\034RunService\034).Heartbeat:wait()\010\009end\010end\010\010function findNearestTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value ~= script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function findNearestFriendlyTorso(pos)\010\009local list = game.Workspace:children()\010\009local torso = nil\010\009local dist = 2500\010\009local temp = nil\010\009local human = nil\010\009local temp2 = nil\010\009for x = 1, #list do\010\009\009temp2 = list[x]\010\009\009if (temp2.className == \034Model\034) and (temp2 ~= script.Parent)and (temp2.Name ~= script.Parent.Name) and (temp2.Name ~= \034Med-Bie\034) and (temp2.Name ~= \034Core\034) then\010\009\009\009temp = temp2:findFirstChild(\034Torso\034)\010\009\009\009human = temp2:findFirstChild(\034Humanoid\034)\010\009\009\009team = temp2:findFirstChild(\034TEAM\034)\010\009\009\009if (temp ~= nil) and (human ~= nil) and (human.Health > 0) and (team ~= nil) and (team.Value == script.Parent.TEAM.Value) then\010\009\009\009\009if (temp.Position - pos).magnitude < dist then\010\009\009\009\009\009torso = temp\010\009\009\009\009\009script.Parent.Target.Value = temp\010\009\009\009\009\009dist = (temp.Position - pos).magnitude\010\010\009\009\009\009\009if human.Health >= 1 then \010\009\009\009\009\009script.Parent.Range.Value = true \010\009\009\009\009\009else \010\009\009\009\009\009script.Parent.Range.Value = false \010\009\009\009\009\009end \010\009\009\009\009end\010\009\009\009end\010\009\009end\010\009end\010\009return torso\010end\010\010function Sit()\010\009if script.Parent.Humanoid.Sit == true then \010\009\009script.Parent.Humanoid.Jump = true \010\009\009print(\034Anti Seat Putter!!!\034)\010\009end \010end \010\010function Shock(Target)\010\009local EnemyHum = Target.Parent:FindFirstChild(\034Humanoid\034)\010\009if EnemyHum and EnemyHum.Health ~= 0 then\010\009\009local Tase = script.GetTasedBro:clone()\010\009\009Tase.Disabled = false\010\009\009Tase.Parent = Target.Parent\010\009\009script.Parent.Head.Shock:Play()\010\009\009EnemyHum:TakeDamage(25)\010\009\009for i = 1,5 do\010\009\009\009local Sparkles = Instance.new(\034Sparkles\034)\010\009\009\009Sparkles.SparkleColor = Color3.new(0,1,1)\010\009\009\009Sparkles.Parent = Target\010\009\009\009game.Debris:AddItem(Sparkles,1.5)\010\009\009\009local distance = (Target.Position - script.Parent.Head.CFrame.p).magnitude\010\009\009\009local pos = script.Parent.Head.Position\010\009\009\009for i = 0,distance,10 do\010\009\009\009\009fakedistance = CFrame.new(script.Parent.Head.Position, Target.Position) * CFrame.new(0, 0, -i-10) * CFrame.new(-1+(math.random()*2),-1+(math.random()*2),-1+(math.random()*2))\010\009\009\009\009local rayPart = Instance.new(\034Part\034, workspace)\010\009\009\009\009rayPart.Name          = \034RayPart\034\010\009\009\009\009rayPart.BrickColor    = BrickColor.new(\034Teal\034)\010\009\009\009\009rayPart.Transparency  = 0\010\009\009\009\009rayPart.Anchored      = true\010\009\009\009\009rayPart.CanCollide    = false\010\009\009\009\009rayPart.TopSurface    = Enum.SurfaceType.Smooth\010\009\009\009\009rayPart.BottomSurface = Enum.SurfaceType.Smooth\010\009\009\009\009rayPart.formFactor    = Enum.FormFactor.Custom\010\009\009\009\009rayPart.Size          = Vector3.new(0, 0, 0)\010\009\009\009\009if i+10 > distance then\010\009\009\009\009\009rayPart.CFrame = CFrame.new(pos, Target.Position) * CFrame.new(0, 0, -(pos-Target.Position).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009\009else\010\009\009\009\009\009rayPart.CFrame = CFrame.new(pos, fakedistance.p) * CFrame.new(0, 0, -(pos-fakedistance.p).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009\009end\010\009\009\009\009rayMesh = Instance.new(\034SpecialMesh\034, rayPart)\010\009\009\009\009rayMesh.MeshId        = \034http://www.roblox.com/asset?id=153952259\034\010\009\009\009\009if i+10 > distance then\010\009\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-Target.Position).magnitude,2)\010\009\009\009\009else\010\009\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-fakedistance.p).magnitude,2)\010\009\009\009\009end\010\009\009\009\009pos = fakedistance.p\010\009\009\009\009game.Debris:AddItem(rayPart, 0.05)\010\009\009\009end\010\009\009\009wait(0.025)\010\009\009end\010\009\009wait(0.25-(0.025*5))\010\009end\010end\010\010function Heal(Target)\010\009local FriendHum = Target.Parent:FindFirstChild(\034Humanoid\034)\010\009if FriendHum and FriendHum.Health ~= 0 then\010\009\009FriendHum.Health = FriendHum.Health + 0.75\010\009\009local Sparkles = Instance.new(\034Sparkles\034)\010\009\009Sparkles.SparkleColor = Color3.new(0,1,0)\010\009\009Sparkles.Parent = Target\010\009\009game.Debris:AddItem(Sparkles,1.5)\010\009\009local distance = (Target.Position - script.Parent.Head.CFrame.p).magnitude\010\009\009local pos = script.Parent.Head.Position\010\009\009for i = 0,distance,10 do\010\009\009\009fakedistance = CFrame.new(script.Parent.Head.Position, Target.Position) * CFrame.new(0, 0, -i-10) * CFrame.new(-1+(math.random()*2),-1+(math.random()*2),-1+(math.random()*2))\010\009\009\009local rayPart = Instance.new(\034Part\034, workspace)\010\009\009\009rayPart.Name          = \034RayPart\034\010\009\009\009rayPart.BrickColor    = BrickColor.new(\034Lime green\034)\010\009\009\009rayPart.Transparency  = 0\010\009\009\009rayPart.Anchored      = true\010\009\009\009rayPart.CanCollide    = false\010\009\009\009rayPart.TopSurface    = Enum.SurfaceType.Smooth\010\009\009\009rayPart.BottomSurface = Enum.SurfaceType.Smooth\010\009\009\009rayPart.formFactor    = Enum.FormFactor.Custom\010\009\009\009rayPart.Size          = Vector3.new(0, 0, 0)\010\009\009\009if i+10 > distance then\010\009\009\009\009rayPart.CFrame = CFrame.new(pos, Target.Position) * CFrame.new(0, 0, -(pos-Target.Position).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009else\010\009\009\009\009rayPart.CFrame = CFrame.new(pos, fakedistance.p) * CFrame.new(0, 0, -(pos-fakedistance.p).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009end\010\009\009\009rayMesh = Instance.new(\034SpecialMesh\034, rayPart)\010\009\009\009rayMesh.MeshId        = \034http://www.roblox.com/asset?id=153952259\034\010\009\009\009if i+10 > distance then\010\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-Target.Position).magnitude,2)\010\009\009\009else\010\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-fakedistance.p).magnitude,2)\010\009\009\009end\010\009\009\009pos = fakedistance.p\010\009\009\009game.Debris:AddItem(rayPart, 0.05)\010\009\009end\010\009end\010end\010\010function Shield(Target)\010\009local FriendHum = Target.Parent:FindFirstChild(\034Humanoid\034)\010\009if FriendHum and FriendHum.Health ~= 0 and GiveShieldReady == true then\010\009\009GiveShieldReady = false\010\009\009Delay(GiveShieldCooldown,function()\010\009\009\009GiveShieldReady = true\010\009\009end)\010\009\009FriendHum.Health = FriendHum.MaxHealth\010\009\009local NewScript = script.ShieldScript:Clone()\010\009\009NewScript.Disabled = false\010\009\009NewScript.Parent = Target.Parent\010\009\009script.Parent.Head.Shield:Play()\010\009\009script.Parent.Head.Shield2:Play()\010\009\009for i = 1,5 do\010\009\009\009local Sparkles = Instance.new(\034Sparkles\034)\010\009\009\009Sparkles.SparkleColor = Color3.new(1,1,0)\010\009\009\009Sparkles.Parent = Target\010\009\009\009game.Debris:AddItem(Sparkles,1.5)\010\009\009\009local distance = (Target.Position - script.Parent.Head.CFrame.p).magnitude\010\009\009\009local pos = script.Parent.Head.Position\010\009\009\009for i = 0,distance,10 do\010\009\009\009\009fakedistance = CFrame.new(script.Parent.Head.Position, Target.Position) * CFrame.new(0, 0, -i-10) * CFrame.new(-1+(math.random()*2),-1+(math.random()*2),-1+(math.random()*2))\010\009\009\009\009local rayPart = Instance.new(\034Part\034, workspace)\010\009\009\009\009rayPart.Name          = \034RayPart\034\010\009\009\009\009rayPart.BrickColor    = BrickColor.new(\034Bright yellow\034)\010\009\009\009\009rayPart.Transparency  = 0\010\009\009\009\009rayPart.Anchored      = true\010\009\009\009\009rayPart.CanCollide    = false\010\009\009\009\009rayPart.TopSurface    = Enum.SurfaceType.Smooth\010\009\009\009\009rayPart.BottomSurface = Enum.SurfaceType.Smooth\010\009\009\009\009rayPart.formFactor    = Enum.FormFactor.Custom\010\009\009\009\009rayPart.Size          = Vector3.new(0, 0, 0)\010\009\009\009\009if i+10 > distance then\010\009\009\009\009\009rayPart.CFrame = CFrame.new(pos, Target.Position) * CFrame.new(0, 0, -(pos-Target.Position).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009\009else\010\009\009\009\009\009rayPart.CFrame = CFrame.new(pos, fakedistance.p) * CFrame.new(0, 0, -(pos-fakedistance.p).magnitude/2) * CFrame.Angles(math.pi/2,0,0)\010\009\009\009\009end\010\009\009\009\009rayMesh = Instance.new(\034SpecialMesh\034, rayPart)\010\009\009\009\009rayMesh.MeshId        = \034http://www.roblox.com/asset?id=153952259\034\010\009\009\009\009if i+10 > distance then\010\009\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-Target.Position).magnitude,2)\010\009\009\009\009else\010\009\009\009\009\009rayMesh.Scale = Vector3.new(2,(pos-fakedistance.p).magnitude,2)\010\009\009\009\009end\010\009\009\009\009pos = fakedistance.p\010\009\009\009\009game.Debris:AddItem(rayPart, 0.05)\010\009\009\009end\010\009\009\009wait(0.025)\010\009\009end\010\009\009wait(1)\010\009end\010end\010\010script.Parent.Humanoid.Changed:connect(Sit)\010\010while true do\010\009wait(0.1)\010\009local target = nil\010\009local Friend = findNearestFriendlyTorso(script.Parent.Torso.Position)\010\009local Enemy = findNearestTorso(script.Parent.Torso.Position)\010\009if (Friend and Enemy and (script.Parent.Torso.Position - Enemy.Position).magnitude < (script.Parent.Torso.Position - Friend.Position).magnitude) or\010\009\009(Enemy and Friend == nil) then\010\009\009target = Enemy\010\009elseif (Friend and Enemy and (script.Parent.Torso.Position - Friend.Position).magnitude < (script.Parent.Torso.Position - Enemy.Position).magnitude) or\010\009\009(Friend and Enemy == nil) then\010\009\009target = Friend\010\009end\010\009if target ~= nil then\010\009\009rx = 0\010\009\009ry = 0\010\009\009rz = 0\010\009\009if (target.Position - script.Parent.Torso.Position).magnitude < 25 + (target.Size.magnitude * 1.25) then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 0.05\010\009\009\009if target == Enemy then\010\009\009\009\009Shock(target)\010\009\009\009elseif target == Friend then\010\009\009\009\009if target.Parent:FindFirstChild(\034Shield\034) == nil and target.Parent:FindFirstChild(\034Humanoid\034) and target.Parent:FindFirstChild(\034Humanoid\034).Health == target.Parent:FindFirstChild(\034Humanoid\034).MaxHealth then\010\009\009\009\009\009Shield(target)\010\009\009\009\009end\010\009\009\009\009if target.Parent:FindFirstChild(\034Humanoid\034) and target.Parent:FindFirstChild(\034Humanoid\034).Health ~= target.Parent:FindFirstChild(\034Humanoid\034).MaxHealth then\010\009\009\009\009\009script.Parent.Head.Heal:Play()\010\009\009\009\009\009while target and target.Parent ~= nil and target.Parent:FindFirstChild(\034Humanoid\034) and target.Parent:FindFirstChild(\034Humanoid\034).Health ~= target.Parent:FindFirstChild(\034Humanoid\034).MaxHealth and (target.Position - script.Parent.Torso.Position).magnitude < 25 + (target.Size.magnitude * 1.25) do\010\009\009\009\009\009\009Heal(target)\010\009\009\009\009\009\009wait(0.025)\010\009\009\009\009\009end\010\009\009\009\009end\010\009\009\009end\010\009\009elseif (target.Position - script.Parent.Torso.Position).magnitude > 25 + (target.Size.magnitude * 1.25) then \010\009\009\009script.Parent.Attack.Value = true\010\009\009\009script.Parent.Humanoid.WalkSpeed = 10\010\009\009end \010\009\009script.Parent.Humanoid:MoveTo(target.Position+Vector3.new(rx,ry,rz), target)\010\009else \010\009\009script.Parent.Range.Value = false \010\009\009script.Parent.Attack.Value = false \010\009end\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28103,class="Script",parent=28102,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="ShieldScript",["ScriptGuid"]="{229DE049-BCB2-4891-B1EE-47A02B3581F0}",["Source"]="wait()\010local sp = script.Parent\010local Humanoid = sp:FindFirstChild(\034Humanoid\034)\010local DamageAbsordPerShield = 200\010local CurrentShieldHealth = DamageAbsordPerShield\010\010if Humanoid and Humanoid.Health ~= 0 then\010\009local Shield = Instance.new(\034Part\034)\010\009Shield.Name = \034Shield\034\010\009Shield.formFactor = \034Custom\034\010\009Shield.Size = Vector3.new(0,0,0)\010\009Shield.BrickColor = BrickColor.new(\034Bright red\034)\010\009Shield.Transparency = 0.5\010\009Shield.Reflectance = 0.625\010\009Shield.TopSurface = 0\010\009Shield.BottomSurface = 0\010\009local Mesh = Instance.new(\034SpecialMesh\034,Shield)\010\009Mesh.Scale = (Vector3.new(1.5,1.5,1.5) * (Humanoid.Torso.Size.magnitude*1.5)) * 5\010\009Mesh.MeshType = \034Sphere\034\010\009local Weld = Instance.new(\034Weld\034,Shield)\010\009Weld.Part0 = Shield\010\009Weld.Part1 = Humanoid.Torso\010\009local Sound = Instance.new(\034Sound\034,Shield)\010\009Sound.SoundId = \034http://www.roblox.com/asset/?id=10756104\034\010\009Sound.Pitch = 0.5\010\009Sound.Volume = 0.25\010\009Shield.Parent = sp\010\009Humanoid.Health = Humanoid.MaxHealth\010\009local CurrentHealth = Humanoid.Health\010\009Connection = Humanoid.HealthChanged:connect(function(Health)\010\009\009local Change = math.abs(CurrentHealth - Health)\010\009\009if CurrentHealth > Health then\010\009\009\009Humanoid.Health = Humanoid.MaxHealth\010\009\009\009CurrentShieldHealth = CurrentShieldHealth - Change\010\009\009\009Shield.Transparency = 0.5 + (0.5*(1-(CurrentShieldHealth/DamageAbsordPerShield)))\010\009\009\009Shield.Reflectance = 0.625 * (CurrentShieldHealth/DamageAbsordPerShield)\010\009\009\009Sound:Play()\010\009\009end\010\009\009if CurrentShieldHealth <= 0 then\010\009\009\009Connection:disconnect()\010\009\009\009Shield:Destroy()\010\009\009\009Humanoid:TakeDamage(math.abs(CurrentShieldHealth))\010\009\009\009script:Destroy()\010\009\009end\010\009\009CurrentHealth = Humanoid.Health\010\009end)\010else\010\009script:Destroy()\010end",["SourceAssetId"]=-1,["Tags"]=""}}
T[#T+1]={id=28104,class="Script",parent=28102,props={["AttributesSerialize"]="",["Disabled"]=true,["LinkedSource"]="",["Name"]="GetTasedBro",["ScriptGuid"]="{28753C00-2731-4B2A-B385-6456125963EA}",["Source"]="--Stickmasterluke\010\010\010sp=script.Parent\010\010\010taseduration=5\010rate=.4\010\010\010local s=Instance.new(\034Sound\034)\010s.SoundId=\034http://www.roblox.com/asset/?id=82277505\034\010s.Looped=true\010\010Delay(7.5,function() s:Stop() end)\010\010if ypcall(function()\010joints={}\010local t=sp:FindFirstChild(\034Torso\034)\010if t~=nil then\010\009s.Parent=t\010\009s:Play()\010\009for i,v in ipairs(t:GetChildren()) do\010\009\009if v.className==\034Motor\034 or v.className==\034Motor6D\034 or v.className==\034Weld\034 or v.className==\034ManualWeld\034 then\010\009\009\009table.insert(joints,v)\010\009\009end\010\009end\010end\010\010if #joints>=1 then\010\009for i=1,taseduration/rate do\010\009\009for i,v in ipairs(joints) do\010\009\009\009if v~=nil then\010\009\009\009\009v.CurrentAngle=(math.random()-.5)*5\010\009\009\009end\010\009\009end\010\009\009local h=sp:FindFirstChild(\034Humanoid\034)\010\009\009local t=sp:FindFirstChild(\034Torso\034)\010\009\009if t~=nil and h~=nil then\010\009\009\009h.Sit=true\010\009\009\009h.Torso.Anchored = true\010\009\009\009t.CFrame=t.CFrame*CFrame.Angles((math.random()-.5)*.5,(math.random()-.5)*.5,(math.random()-.5)*.5)\010\009\009\009wait(rate)\010\009\009end\010\009end\010\009local h=sp:FindFirstChild(\034Humanoid\034)\010\009h.Torso.Anchored = false\010\009h.Sit=false\010end\010s:Stop()\010script:remove()\010\010\010end) ~= true then wait() script:remove() end",["SourceAssetId"]=-1,["Tags"]=""}}
